// ---------------------------------------------------------------- the sandbox layout (the header's `layout`)

/** The lanes client a `pod` pass's forwarders and a `pod` heat's gateway run in (server/sandbox-host/services.ts LanesClient). */
export interface OnePodLanes {
  /** The lanes pod opened (idempotent): awaited before a `pod` pass or heat sets out; a NodeRoomError when the node has no room for it. */
  open(): Promise<unknown>;
  readonly hosted: HostedServices;
  readonly door: Door;
}

/** What hosts the `pod` layout in this process (the pipeline's: the k8s sandbox with a pod of its own). */
export interface OnePodHost {
  /** The sandbox's one-pod view (K8sSandbox.onePod): `pods`, and its plain spawn (the base's staged pod). */
  view(): Sandbox;
  /** The process's one lanes client, made on its first call (nothing before it: no lanes directory, no lanes pod). */
  lanes(): OnePodLanes;
}

/** The sandbox layout's inputs (the header's `layout`): GradeWorkerDeps.onePod, AgentTrialDeps.onePod, HindsightAuditDeps.onePod. */
export interface OnePodDeps {
  /**
   * Go-live's instant as the one-pod-from site setting held it when this process booted (server/ops/one-pod-from.ts
   * readOnePodFrom, read once), or null while it held none: then every fresh job runs `split`, as before.
   */
  from: Date | null;
  /** This process's host of the `pod` layout, or null when it cannot host one (no k8s sandbox with a pod of its own). */
  host: OnePodHost | null;
}

/** The contests a process that cannot host `pod` has said so of (layoutOfFresh), per OnePodDeps: once a contest. */
const SAID_SPLIT = new WeakMap<OnePodDeps, Set<string>>();

/**
 * The layout a fresh job of competition `comp` runs on (the header's `layout`): `split` while `onePod` is absent or its
 * `from` null (dormant: nothing else read or said), else sandboxLayoutOf(slug, `kind` (its bundle's harness kind), its
 * created_at, from), and `split` for a `pod` contest in a process that cannot host it, said once a contest in `log`
 * (`what` names the job).
 */
export function layoutOfFresh(onePod: OnePodDeps | undefined, comp: { slug: string; createdAt: Date }, kind: string, log: (line: string) => void, what: string): SandboxLayout {
  if (onePod === undefined || onePod.from === null) return 'split';
  if (sandboxLayoutOf(comp.slug, kind, comp.createdAt, onePod.from) === 'split') return 'split';
  if (onePod.host !== null) return 'pod';
  const said = SAID_SPLIT.get(onePod) ?? new Set<string>();
  SAID_SPLIT.set(onePod, said);
  if (!said.has(comp.slug)) {
    said.add(comp.slug);
    log(`[grade] ${what}: ${comp.slug} runs on the pod sandbox layout, and this process cannot host it (no k8s sandbox with a pod of its own): its jobs here run on the split layout, as before; said once for ${comp.slug}`);
  }
  return 'split';
}

/**
 * The host of a run that runs on `pod` by its flag or its job's `one_pod` (the header's `layout`: hosting is not gated on
 * `from`), or the platform's fault of a process that cannot host it: a PlatformFaultError in one plain sentence (`what`
 * names the job), never a re-run on `split`.
 */
export function onePodHostOf(onePod: OnePodDeps | undefined, what: string): OnePodHost {
  const host = onePod?.host ?? null;
  if (host !== null) return host;
  throw new PlatformFaultError(
    `${what} runs on the pod sandbox layout (its run is flagged ${ONE_POD_FLAG}), and this process cannot host that layout (only one on the k8s sandbox with a pod of its own can): it is refused as the platform's fault and never re-run on the split layout, whose CPU and memory room differ`,
  );
}

/** The lanes client of `host`, opened: a NodeRoomError (no room for the lanes pod) or any other failure thrown on as it is. */
export async function openOnePodLanes(host: OnePodHost): Promise<OnePodLanes> {
  const lanes = host.lanes();
  await lanes.open();
  return lanes;
}

/** What a `pod` agent/v1 pass takes besides the one-pod view (grader/agent.ts RunTrialOptions): its entry's lane key too. */
type OnePodPass = Required<Pick<RunTrialOptions, 'hosted' | 'door' | 'entryKey'>> & Pick<RunTrialOptions, 'podRequests'>;

/**
 * A trial's entry lane key on one pod (grader/agent.ts podEntryLaneKey) under the fail-key secret (`secret`, else
 * defaultFailKeySecret): keyed by the trial row's run (TrialRow.runId), so the trial's live pass and its in-job replay,
 * whichever job attempt runs them, hand the entry the same key, and the run's record built from those rows carries it
 * (AgentTrialRecord.entry_key). Only the key leaves here, never the secret.
 */
async function onePodEntryKey(secret: string | undefined, row: Pick<TrialRow, 'runId' | 'trialIndex' | 'instanceSha256'>): Promise<string> {
  const { podEntryLaneKey } = await import('./agent.ts');
  return podEntryLaneKey(secret ?? (await defaultFailKeySecret()), row.runId, { index: row.trialIndex, instance_sha256: row.instanceSha256 });
}

/**
 * A grade-trial payload saying its run's layout (the header's `layout`): `one_pod: true` on `pod`, none on `split`, so
 * every re-send of the job (a void's next pass, a wait, a hand-back) carries the run's flag. `data` itself when it says so.
 */
export function trialPayloadOf(data: JobPayload<'grade-trial'>, layout: SandboxLayout): JobPayload<'grade-trial'> {
  if ((layout === 'pod') === (data.one_pod === true)) return data;
  if (layout === 'pod') return { ...data, one_pod: true };
  const { one_pod: _said, ...rest } = data;
  return rest;
}

/** `flags` with ONE_POD_FLAG added (once, code-unit order) on `pod`; `flags` as they are on `split`. */
function layoutFlags(flags: readonly string[], layout: SandboxLayout): string[] {
  if (layout === 'split' || flags.includes(ONE_POD_FLAG)) return [...flags];
  return [...flags, ONE_POD_FLAG].sort(compareCodeUnits);
}

export interface GradeWorkerDeps {
  db: Db;
  blobs: BlobStore;
  sandbox: Sandbox;
  /**
   * The sandbox layout's inputs (the header's `layout`): go-live's instant as read at boot and this process's host of
   * the `pod` layout. Absent: dormant, every job `split` as before, and a flagged run's job refused (onePodHostOf).
   */
  onePod?: OnePodDeps;
  /** Existing directory for the executions' scratch directories (named for the job when the handler is handed one: the header's `scratch`). */
  workRoot: string;
  /** A phase's frozen dataset (its chunks read and parsed) and its universe sample rule (default createDatasetLoader()). */
  loadDataset?(row: typeof dataset.$inferSelect): Promise<{ dataset: ReplayDataset; sample: UniverseSampleT }>;
  /** A bars-replay/v1 phase's frozen bars window (its bars files read and parsed; default createBarsDatasetLoader()). */
  loadBarsDataset?(row: typeof dataset.$inferSelect): Promise<{ dataset: BarsDataset }>;
  /** A clmm-replay/v1 phase's frozen pool window (its bars and rows files read and parsed; default createClmmDatasetLoader()). */
  loadClmmDataset?(row: typeof dataset.$inferSelect): Promise<{ dataset: ClmmDataset }>;
  /**
   * What scores a clmm-replay/v1 action log (harnesses.ts ClmmPlanInput.scorer; default
   * sim/clmm/metrics.ts scoreClmmActionLog). Its LVR is held to LVR leg by leg whatever it is (the
   * header's `platform fault`); a test plants a fault in one.
   */
  clmmScorer?: ClmmScorer;
  /**
   * The submission's authorship summary (transcripts/authorship.ts ledger.summary) priced under
   * `pricingRev`: of algorithm `algoVersion` (a regrade's: the version its stored run was graded
   * with), else the newest; null when none was computed (default loadStoredAuthorship).
   */
  loadAuthorship?(submissionId: string, pricingRev: string, algoVersion?: number): Promise<AuthorshipSummaryT | null>;
  /**
   * A program/v1 competition's directory, and a sealed-window one's, holding its sealed-window.yaml (the header's
   * `fail key`; default competitions/<slug>; a pack competition's server/competitions/load.ts programCompetitionDir,
   * competitions/code-tests-01 for a sponsored one: competitionDirOf, the header's `pack`).
   */
  competitionDir?(slug: string): string;
  /**
   * A competition's starter as its kit hands it out, each file's path relative to starter/ with its size and sha256
   * (grader/size.ts StarterFile): what a program/v1 size count leaves out of an entry that kept it unchanged (the
   * header's `size`). Read only under a size count. Default: competitionStarter(COMPETITIONS_DIR, slug).
   */
  starter?(slug: string): Promise<readonly StarterFile[]>;
  /**
   * MAKEFUN_SEALED_DIR (config.sealedDir): where an instance-drawn competition's instances and draw
   * records are, <sealedDir>/<slug>/instance/ (the header's `instance`), and a sealed-window
   * competition's draw record, <sealedDir>/<slug>/draw.json, which a phase-secret+beacon/v1 final
   * phase's fail key mixes the signature of (the header's `fail key`). Default: the environment's, as
   * server/config.ts resolves it (load.ts sealedDirFromEnv).
   */
  sealedDir?: string;
  /**
   * The drand chain an instance sidecar's beacon, or a sealed window's, may name besides quicknet
   * (config.drandChain: a dev-auth MAKEFUN_DRAND_CHAIN test chain; quicknet names none). Default:
   * MAKEFUN_DRAND_CHAIN from the environment under dev auth (MAKEFUN_DEV_AUTH with NODE_ENV development
   * or test), else quicknet alone.
   */
  drandChain?: DrandChain;
  /**
   * The server secret a server-secret/v1 final phase's fail key is derived from (config.betterAuthSecret;
   * the pipeline passes it); never read for a phase-secret+beacon/v1 one. Default: BETTER_AUTH_SECRET
   * from the environment, else server/auth.ts's dev-only DEV_AUTH_SECRET (config.ts requires a real
   * secret in production).
   */
  failKeySecret?: string;
  /**
   * Where a grade job that died for good is paged, one line each (the header's `dead grade job`), and a
   * fail key that cannot be derived (the header's `fail key`; default console.error, as a dead hindsight
   * audit job is paged).
   */
  page?: (line: string) => void;
  /**
   * Where a dead grade job recorded without a page (its entry is out) is logged, what a grade or regrade
   * job's attempt removed of one that died (the header's `scratch`), a fail key that cannot be
   * derived once it was paged within the hour, and a race's crosscheck on a landed grade that could not
   * compare a racer or failed (the header's `crosscheck`; default console.log).
   */
  log?: (line: string) => void;
  /**
   * The clock a dead grade job's row is written at, an agent/v1 run starts at, fail-key pages are spaced by, a final
   * grade under a build meter waits for masq by (the header's `metered`), and a code-heat job reads against its
   * attempt's expiry (the header's `hand-on`; default the wall clock).
   */
  now?: () => Date;
  /**
   * Where an agent/v1 grade sends its trials' jobs and its fan-in's, a final grade under a build meter sends itself
   * again for when masq has settled (the header's `metered`), and a code-heat job hands itself on (the header's
   * `code heat`: a wait slot, and the rest of a heat its attempt cannot hold, `hand-on`): the pipeline's queue. Without
   * it an agent/v1 grade job fails (a retryable Error): nothing could run its trials; and so does a metered final grade
   * inside its settle window.
   */
  jobs?: Pick<JobQueue, 'send'>;
  /** The gateway forwarder an agent/v1 L2 regrade replays its trials through (default grader/gateway/bundle.ts gatewayBundle, cached under <workRoot>/gateway). */
  forwarder?: () => Promise<Pick<GatewayBundle, 'dir' | 'script'>>;
  /** The engine check an agent/v1 L2 regrade passes before it replays (the header's `isolation`; default sandboxIsolation(sandbox), null: none). */
  isolation?: IsolationCheck | null;
  /** What runs an agent/v1 L2 regrade (default grader/regrade.ts regradeAgentL2): a test's stand-in reads the request it was handed. */
  regradeAgentL2?: typeof regradeAgentL2;
  /** A scrape/v1 heat's parts (the header's `scrape/v1`): its lease, drand, gateway, launcher, pacing; tests replace the heat's own. */
  scrape?: ScrapeWorkerDeps;
  /**
   * The sandbox a code-fastest timing reads CPU time on (the header's `code heat`): its openCpuClock is opened once for
   * the process (processCpuClock) and every timed run goes to the timed sandbox it hands back. Default: `sandbox` when it
   * is the docker or the k8s driver (timingSandboxOf); null, none (the process driver reads no CPU time): a dev grade is
   * recorded untimed and a heat is refused. A test hands in one whose clock it drives.
   */
  timingSandbox?: TimingSandbox | null;
  /**
   * The masq broker a fresh grade of an entry under a build meter syncs its entrant's build keys through first (the
   * header's `metered`: server/metering/sync.ts syncEntrantKeys reads its request pages): the pipeline hands in the one
   * its metering job runs on (server/pipeline/index.ts startWorkers). Default: the environment's (server/config.ts
   * loadConfig: MAKEFUN_LLM_GATEWAY=masq with MAKEFUN_LLM_GATEWAY_URL and MAKEFUN_LLM_GATEWAY_ADMIN_KEY, masq.ts
   * masqBrokerFromConfig), made when first needed. Null, or MAKEFUN_LLM_GATEWAY off: none, and a fresh grade of an
   * entrant holding a key still to sync fails as a retryable Error. A regrade never calls it.
   */
  meter?: Pick<MasqBuildKeyBroker, 'requests'> | null;
  /** A judged final's heat (the header's `judge heat`): where its calls go. */
  judge?: JudgeWorkerDeps;
  /**
   * How a grade, a regrade and a code heat open an entrant's env-lane entry secrets (the header's `entry secrets`): the
   * grader's seal settings, whose private keys open them (default the environment's, entrySecretSealSettings of
   * loadConfig(), read when an entrant's secrets are first opened).
   */
  entrySecrets?: Pick<AgentEntrySecretDeps, 'seal'>;
}

/** Where a judge heat's calls go (GradeWorkerDeps.judge; the header's `judge heat`). */
export interface JudgeWorkerDeps {
  /**
   * The broker each attempt of a heat mints its judge key at, and retires it at (grader/judge-call.ts openJudgeHeat).
   * Default: the environment's, made when first needed from one loadConfig(): server/superbot-router.ts judgeKeyBroker over
   * masq's (masq.ts masqBrokerFromConfig, as GradeWorkerDeps.meter's) and, with MAKEFUN_SUPERBOT_ROUTER_URL and
   * MAKEFUN_SUPERBOT_ROUTER_KEY set, superbot-router's (routerJudgeBroker), which mints for the models it serves (a judge
   * on superbot, superbot-fast, superbot-flash or a DeepSeek-V4.1-Flash id then dials the router directly; every other
   * judge, Claude's included, stays on masq) and retires a router key id as the router's. Null, or MAKEFUN_LLM_GATEWAY off
   * with the router pair unset: none, and a heat due fails as a PermanentJobError.
   */
  broker?: MasqJudgeKeyBroker | null;
  /** The fetch the judge's calls go out on (default globalThis.fetch). */
  fetch?: typeof fetch;
  /** One call's bound, ms (default grader/judge-call.ts's). */
  timeoutMs?: number;
  /** The most of a heat's planned calls in flight at once (default JUDGE_HEAT_CONCURRENCY; 1 sends them one at a time). */
  concurrency?: number;
  /**
   * The rule a heat's calls still out near a batch's end are backed up by (the header's `judge heat`;
   * grader/judge-backup.ts): undefined, the house's (judgeBackupRuleOf: JUDGE_BACKUP on a masq key, none on a router key);
   * null, none (each call sent once, as before backups).
   */
  backup?: JudgeBackupRule | null;
  /** The clock a heat's sends are aged and stamped by, and its backup wake sleeps on (default Date.now and a timer). */
  clock?: JudgeHeatClock;
  /**
   * The models this process has seen answer a forced form (sendJudgeHeatCalls: a heat's first call then goes out with
   * the rest). Default: with the environment's broker, a memo of the process's (6 h); with an injected broker, none.
   */
  formsSeen?: JudgeFormsSeen;
  /**
   * The platform's one budget of judge sends in flight that a heat takes a seat in while it sends (the header's `judge
   * heat`; openJudgePoolSeat): its seats' directory (default judgePoolDir, under the blob store) and its size (default
   * JUDGE_POOL_BUDGET). Undefined: a seat only on the environment's broker (as `formsSeen`'s default; an injected broker
   * takes none); null: none, each heat bounded by its width alone, as before the pool.
   */
  pool?: { dir?: string; budget?: number } | null;
  /**
   * The judge planner (server/judging/plan.ts judgePlanner, typed here structurally): which judges a heat is played on.
   * Undefined, or `of` answering null: the bundle's one named judge on its own door, today's heat and bytes.
   */
  plan?: JudgeWorkerPlanner;
}

/** A heat's judges as the planner answers them (server/judging/plan.ts JudgeHeatPlan): pins index for index, never recorded. */
export interface JudgeWorkerPlan {
  judges: JudgeOfHeatT[];
  pins: (JudgePin | null)[];
  /** A provisional pick made via the overflow: what a heat that faults is played once more on (null: the bundle's own judge). */
  fallback?: JudgeWorkerPlan | null;
}

/** The judge planner (server/judging/plan.ts JudgePlanner), structurally. */
export interface JudgeWorkerPlanner {
  of(ask: { slug: string; stage: 'provisional' | 'final'; judge: ProgramJudgeT['agent']; seed: string; subject?: string }): Promise<JudgeWorkerPlan | null>;
  resume(judges: readonly JudgeOfHeatT[]): Promise<JudgeWorkerPlan>;
  broker(base: MasqJudgeKeyBroker | null): MasqJudgeKeyBroker;
}

/** The HKDF label of the final phase's fail key. */
export const FAIL_KEY_LABEL = 'agent-fun/fail-key';

/**
 * The final phase's fail key (u64 decimal): the first 8 bytes, big-endian, of
 * HKDF-SHA256(ikm = the server secret, salt = empty, info = "agent-fun/fail-key" 0x00 <phase seed>).
 * Without the secret nothing (hello.seed included) predicts it.
 */
export function secretFailKey(secret: string, seed: string): string {
  if (secret.length === 0) throw new RangeError('the fail-key secret is empty');
  parseU64(seed, 'seed');
  const okm = Buffer.from(hkdfSync('sha256', secret, Buffer.alloc(0), `${FAIL_KEY_LABEL}\0${seed}`, 8));
  return okm.readBigUInt64BE(0).toString();
}

/**
 * The fail key of a server-secret/v1 phase (phaseFailKey picks the scheme): public on `dev` (publicFailKey of its seed,
 * what a kit reproduces), secret on any other (`final`).
 */
export function failKeyFor(phaseKey: string, seed: string, secret: string): string {
  return phaseKey === 'dev' ? publicFailKey(seed) : secretFailKey(secret, seed);
}

/** The fail-key secret when the deps name none (see GradeWorkerDeps.failKeySecret). */
async function defaultFailKeySecret(): Promise<string> {
  const env = (process.env.BETTER_AUTH_SECRET ?? '').trim();
  if (env !== '') return env;
  return (await import('../server/auth.ts')).DEV_AUTH_SECRET;
}

/** The environment's masq broker for a metered grade's sync (GradeWorkerDeps.meter's default), once made; undefined until then. */
let environmentMeter: Pick<MasqBuildKeyBroker, 'requests'> | null | undefined;

/** The broker a fresh metered grade syncs through (GradeWorkerDeps.meter, else the environment's, made once); null: none. */
async function meterOf(deps: Pick<GradeWorkerDeps, 'meter'>): Promise<Pick<MasqBuildKeyBroker, 'requests'> | null> {
  if (deps.meter !== undefined) return deps.meter;
  if (environmentMeter === undefined) {
    const { masqBrokerFromConfig } = await import('./gateway/masq.ts');
    environmentMeter = masqBrokerFromConfig(loadConfig());
  }
  return environmentMeter;
}

/**
 * The entry's cost (entry-cost.ts entryCostOf, under its bundle). `fresh` is a grade's, not a regrade's: under a build
 * meter it first syncs every build key the entrant holds in the competition through the submission's created_at (the
 * header's `metered`), so every request the cost counts is stored, and keeps the list of those it counted; a regrade
 * (`stored`: the stored run's result) prices from exactly the stored rows its list names, and never calls masq. A
 * broker fault on the sync, or no broker while a key is still to sync, is the platform's, never the entry's: a
 * retryable Error (its cause the broker's), thrown before anything is graded or recorded. A regrade whose list or a row
 * it names is gone is a PermanentJobError.
 */
async function entryCostFor(
  deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'meter'>,
  input: { sub: typeof submission.$inferSelect; bundle: CompetitionBundleT; fresh: boolean; stored?: unknown; signal?: AbortSignal },
): Promise<EntryCost> {
  const { sub, bundle } = input;
  if (bundle.build_meter !== undefined && input.fresh) {
    const { syncEntrantKeys } = await import('../server/metering/sync.ts');
    const { MasqBrokerError } = await import('./gateway/masq.ts');
    const what = `submission ${sub.id}'s metered requests (its entrant's build keys in competition ${sub.competitionId}, through ${sub.createdAt.toISOString()})`;
    const broker = await meterOf(deps);
    const meter: Pick<MasqBuildKeyBroker, 'requests'> = broker ?? {
      requests: async () => {
        throw new Error(`${what} cannot be synced: this process has no masq to read them from (MAKEFUN_LLM_GATEWAY=masq with its URL and admin key); the grade waits for one, never the entry's fault`);
      },
    };
    try {
      await syncEntrantKeys(deps.db, meter, { competitionId: sub.competitionId, userId: sub.userId, through: sub.createdAt, ...(input.signal === undefined ? {} : { signal: input.signal }) });
    } catch (err) {
      if (err instanceof MasqBrokerError) throw new Error(`${what} could not be synced from masq (${err.message}): the platform's fault, never the entry's; the job retries`, { cause: err });
      throw err;
    }
  }
  const counted = input.fresh ? undefined : storedMeteredCost(input.stored);
  try {
    return await entryCostOf(deps.db, sub, bundle, { blobs: deps.blobs, ...(counted === undefined ? {} : { counted }) });
  } catch (err) {
    if (err instanceof MeteredCountError) throw new PermanentJobError(err.message, { cause: err });
    throw err;
  }
}

/** How far past masq's settle (the receipt plus CAP_GUARD_LOOKBACK_MS) a metered final grade waiting on it is sent again for: a grader clock behind the queue's still finds it settled. */
export const METERED_SETTLE_SLACK_MS = 60_000;

/** The grade job a metered final grade job `gradeJobId` sends itself again as while masq settles (the header's `metered`): one per job, so a retried attempt sends it once. */
export function meteredSettleJobId(gradeJobId: string): string {
  return sha256Uuid(`grade-metered-settle\0${gradeJobId.toLowerCase()}`);
}

/**
 * Whether a fresh final grade of `sub` under a build meter waits for masq to settle (the header's `metered`): before the
 * receipt plus CAP_GUARD_LOOKBACK_MS by deps.now, the grade job is sent again on its own queue for that instant plus
 * METERED_SETTLE_SLACK_MS at the priority it was sent at, so it keeps its place (meteredSettleJobId of the job; a uuid
 * of its own with no job context), `handedOn` told once
 * it is sent (the pipeline then sends nothing after this job), and the instant answered; settled, null. With no queue
 * to send it on, a retryable Error.
 */
async function meteredSettleWait(
  deps: Pick<GradeWorkerDeps, 'jobs' | 'now' | 'log'>,
  input: { sub: typeof submission.$inferSelect; ph: typeof phase.$inferSelect; job: JobPayload<'grade-dev'>; ctx: GradeJobContext | undefined; handedOn: (() => void) | undefined },
): Promise<Date | null> {
  const { sub, ph, job, ctx } = input;
  const { CAP_GUARD_LOOKBACK_MS } = await import('../server/metering/sync.ts');
  const settled = new Date(sub.createdAt.getTime() + CAP_GUARD_LOOKBACK_MS);
  const now = (deps.now ?? (() => new Date()))();
  if (now.getTime() >= settled.getTime()) return null;
  const what = `submission ${sub.id}'s ${ph.key} grade prices its metered build cost once masq has had ${CAP_GUARD_LOOKBACK_MS / 60_000} minutes past its receipt (${sub.createdAt.toISOString()}) to record every request it counts, at ${settled.toISOString()}`;
  if (deps.jobs === undefined) throw new Error(`${what}, and this process has no queue to send the grade on for then: the job retries`);
  const queue = ctx?.queue === 'grade-dev' || ctx?.queue === 'grade-final' ? ctx.queue : gradeQueue(ph.key);
  const id = meteredSettleJobId(ctx?.id ?? uuidv7());
  const startAfter = new Date(settled.getTime() + METERED_SETTLE_SLACK_MS);
  await deps.jobs.send(queue, job, { id, startAfter, ...(ctx?.priority === undefined ? {} : { priority: ctx.priority }) });
  // Nothing graded: whatever follows a grade follows the job sent again, never this one.
  input.handedOn?.();
  (deps.log ?? ((line: string) => console.log(line)))(`[grade] ${what}: sent again on ${queue} for ${startAfter.toISOString()} (job ${id}); nothing is graded now`);
  return settled;
}

// ---------------------------------------------------------------- the fail key's scheme

/** The largest draw.json a committed fail key reads its signature from (makeDrawRecord's spelling is under 2 KB). */
export const MAX_SEALED_DRAW_BYTES = 65_536;

/** How long a fail key that cannot be derived goes unpaged again, per phase and reason, in one process (failKeyPager). */
export const FAIL_KEY_PAGE_MS = 60 * 60_000;

/**
 * Why a phase's fail key cannot be derived now (phaseFailKey; the header's `fail key`): a phase-secret+beacon/v1 phase
 * with no fail-key secret, no draw record that verifies, or one its deadline commitment does not name (and a scheme this
 * grader does not know). A retryable Error, never a PermanentJobError: an admin can mend each (the window drawn,
 * MAKEFUN_SEALED_DIR pointed where the draw wrote it), the job retries until then, and nothing derives the key from the
 * server secret meanwhile. `fix` names the mend, in the page's words.
 */
export class FailKeyUnavailableError extends Error {
  readonly phaseId: string;
  readonly fix: string;

  constructor(phaseId: string, message: string, fix: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'FailKeyUnavailableError';
    this.phaseId = phaseId;
    this.fix = fix;
  }
}

/** What phaseFailKey reads of a phase row. */
export type FailKeyPhase = Pick<typeof phase.$inferSelect, 'id' | 'key' | 'failKeyScheme' | 'failKeySecret' | 'deadlineCommitment' | 'deadlineCommitmentSha256'>;

export interface PhaseFailKeyInput {
  phase: FailKeyPhase;
  /** The competition's slug: its draw record's and its deadline commitment's. */
  slug: string;
  /** The seed the run is graded under (the phase seed; a regrade's, its stored run's). */
  seed: string;
  /** The phase's dataset row digest, the seed's dataset part: on phase-secret+beacon/v1 the drawn masked window must be it. */
  datasetSha256: string;
  /** The competition's directory, holding its sealed-window.yaml (GradeWorkerDeps.competitionDir's). */
  compDir: string;
  /** MAKEFUN_SEALED_DIR: the draw record is <sealedDir>/<slug>/draw.json. */
  sealedDir: string;
  /** The sealed-window module's explicit test option (instanceChainOptions of the deps' drandChain). */
  chain: SealedWindowChainOptions;
  /** The server secret (GradeWorkerDeps.failKeySecret, else defaultFailKeySecret): asked for on server-secret/v1 alone. */
  serverSecret: () => string | Promise<string>;
}

/**
 * The fail key of a phase's run (u64 decimal), by the phase's scheme (phase.fail_key_scheme; the header's `fail key`):
 *   server-secret/v1        failKeyFor of the server secret, byte for byte as before the schemes
 *   phase-secret+beacon/v1  committedFailKey(phase.fail_key_secret, seed, the drand signature of the sealed window's
 *                           beacon round): the signature the draw record's (<sealedDir>/<slug>/draw.json), verified
 *                           against <compDir>/sealed-window.yaml (verifyDrawRecord), and taken only while the phase's
 *                           deadline commitment holds it: the document hashes to its stored sha256, is this
 *                           competition's sealed pool, fixed the secret's sha256, and names the sidecar the draw was
 *                           made for, its round and its chain; the drawn masked window is `datasetSha256`. The server
 *                           secret is never asked for.
 * Throws FailKeyUnavailableError (retryable) when the committed key cannot be derived, and on a scheme it does not know.
 */
export async function phaseFailKey(input: PhaseFailKeyInput): Promise<string> {
  const scheme: string = input.phase.failKeyScheme;
  if (scheme === SERVER_SECRET_FAIL_KEY_SCHEME) return failKeyFor(input.phase.key, input.seed, await input.serverSecret());
  if (scheme === COMMITTED_FAIL_KEY_SCHEME) return committedPhaseFailKey(input);
  throw new FailKeyUnavailableError(
    input.phase.id,
    `the ${input.phase.key} phase of ${input.slug} names fail-key scheme ${JSON.stringify(scheme)}, which this grader does not know`,
    `grade it with a grader that knows the scheme; no other scheme stands in for it`,
  );
}

/**
 * phaseFailKey on phase-secret+beacon/v1 (see there): every refusal a FailKeyUnavailableError. The draw's drand round is
 * checked off the event loop (load.ts sealedDrawRoundCheckOffLoop); the pool's OffThreadError rejects as it is (the
 * grade retries).
 */
async function committedPhaseFailKey(input: PhaseFailKeyInput): Promise<string> {
  const { phase: ph, slug } = input;
  const decide = `an admin decides how ${slug}'s ${ph.key} phase is graded: no fail key of it is derived from the server secret`;
  const unavailable = (why: string, fix: string, cause?: unknown) =>
    new FailKeyUnavailableError(ph.id, `the ${ph.key} phase of ${slug} keys its failed-tx draws by ${COMMITTED_FAIL_KEY_SCHEME}, and ${why}`, fix, cause === undefined ? undefined : { cause });
  const secret = ph.failKeySecret;
  if (secret === null) throw unavailable('it holds no fail-key secret', `the deadline commitment writes the secret with its document; ${decide}`);
  if (ph.key !== 'final') throw unavailable('it is no final phase: only the final phase is committed at its deadline', decide);

  // The commitment as stored: whole, this competition's sealed pool, and the secret the one whose sha256 it fixed.
  const sha = ph.deadlineCommitmentSha256;
  if (sha === null || !verifyDeadlineCommitment(ph.deadlineCommitment, sha)) throw unavailable(`its deadline commitment is not a commitment document hashing to its sha256 ${sha ?? '(none)'}`, decide);
  const doc = DeadlineCommitment.parse(ph.deadlineCommitment);
  if (doc.slug !== slug) throw unavailable(`its deadline commitment is competition ${doc.slug}'s`, decide);
  let secretSha256: string | null = null;
  try {
    secretSha256 = failKeySecretSha256(secret);
  } catch {
    // Not 32 bytes of hex (the column's check says it is): it matches nothing.
  }
  if (secretSha256 !== doc.fail_key.secret_sha256) throw unavailable(`its fail-key secret does not hash to the secret_sha256 ${doc.fail_key.secret_sha256} its deadline commitment fixed`, decide);
  const committed = doc.window;
  if (committed.kind !== 'sealed_pool') {
    throw unavailable(`its deadline commitment names a ${committed.kind} window, whose round ${doc.fail_key.round} no draw record signs: this grader takes the round's signature from a sealed window's draw alone`, decide);
  }

  // The draw: draw.json under the sealed directory, verified against the sidecar, and the one the commitment names.
  const drawFix = `draw the window once round ${doc.fail_key.round} is emitted (POST /api/admin/competitions/${slug}/sealed-window/draw), and grade with MAKEFUN_SEALED_DIR where the draw wrote ${DRAW_FILE}`;
  const sidecarPath = join(input.compDir, SEALED_WINDOW_FILE);
  const sidecar = sealedFileOf(sidecarPath, MAX_SEALED_WINDOW_BYTES);
  if ('why' in sidecar) throw unavailable(`its ${SEALED_WINDOW_FILE} ${sidecarPath} ${sidecar.why}`, `grade where competitions/${slug}/${SEALED_WINDOW_FILE} is the committed sidecar (sha256 ${committed.sidecar_sha256})`);
  const drawPath = join(input.sealedDir, slug, DRAW_FILE);
  const drawn = sealedFileOf(drawPath, MAX_SEALED_DRAW_BYTES);
  if ('why' in drawn) throw unavailable(`its draw record ${drawPath} ${drawn.why}`, drawFix);
  let raw: unknown;
  try {
    raw = JSON.parse(drawn.bytes.toString('utf8'));
  } catch (err) {
    throw unavailable(`its draw record ${drawPath} is not JSON`, decide, err);
  }
  const verifyRound = await sealedDrawRoundCheckOffLoop({ sidecar: sidecar.bytes, record: raw, testChain: input.chain.testChain });
  let draw;
  try {
    draw = verifyDrawRecord({ sidecar: sidecar.bytes, record: raw, competition: slug, ...input.chain, verifyRound });
  } catch (err) {
    if (isSealedWindowError(err)) throw unavailable(`its draw record ${drawPath} does not verify against ${sidecarPath} (${err.code}): ${err.message}`, decide, err);
    throw err;
  }
  const beacon = DrawRecord.parse(raw).beacon;
  if (draw.sidecarSha256 !== committed.sidecar_sha256) {
    throw unavailable(`its draw record was made for the ${SEALED_WINDOW_FILE} of sha256 ${draw.sidecarSha256}, not the ${committed.sidecar_sha256} its deadline commitment fixed`, decide);
  }
  if (draw.round !== doc.fail_key.round || beacon.chain !== doc.fail_key.chain) {
    throw unavailable(`its draw record signs drand round ${draw.round} on chain ${beacon.chain}, not the round ${doc.fail_key.round} on chain ${doc.fail_key.chain} its deadline commitment's fail key mixes in`, decide);
  }
  if (draw.opening.masked_dataset_sha256 !== input.datasetSha256) {
    throw unavailable(
      `its draw opens the masked window ${draw.opening.masked_dataset_sha256}, but the phase's dataset is ${input.datasetSha256}: the seed and the key are of the window graded`,
      `attach the drawn window to the phase (the draw does: POST /api/admin/competitions/${slug}/sealed-window/draw); ${decide}`,
    );
  }
  return committedFailKey(secret, input.seed, draw.signature);
}

/** A regular file's bytes (never through a link), at most `max`; else why there are none, in words that follow its path. */
function sealedFileOf(path: string, max: number): { bytes: Buffer } | { why: string } {
  let st;
  try {
    st = lstatSync(path);
  } catch {
    return { why: 'is not there' };
  }
  if (!st.isFile()) return { why: 'is not a regular file' };
  if (st.size > max) return { why: `is ${st.size} bytes, over the ${max}-byte limit` };
  try {
    return { bytes: readFileSync(path) };
  } catch (err) {
    return { why: `cannot be read (${(err as Error).message})` };
  }
}

/**
 * A fail key derived through `derive` (phaseFailKey), a FailKeyUnavailableError paged as it goes by (the header's
 * `fail key`): at most once per FAIL_KEY_PAGE_MS per phase and reason in this process (logged in between), then thrown
 * on, so the job retries. `tag` opens each line ("[grade]", "[hindsight]"); `what` names the job's work.
 */
function failKeyPager(
  deps: { page?: (line: string) => void; log?: (line: string) => void; now?: () => Date },
  tag: string,
): (what: string, derive: () => Promise<string>) => Promise<string> {
  const page = deps.page ?? ((line: string) => console.error(line));
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  /** When each phase's reason was last paged. */
  const paged = new Map<string, number>();
  return async (what, derive) => {
    try {
      return await derive();
    } catch (err) {
      if (!(err instanceof FailKeyUnavailableError)) throw err;
      const at = now().getTime();
      const key = `${err.phaseId}\0${err.message}`;
      const last = paged.get(key);
      if (last !== undefined && at - last < FAIL_KEY_PAGE_MS) {
        log(`${tag} ${what} waits on its fail key (paged at ${new Date(last).toISOString()}): ${err.message}`);
      } else {
        paged.set(key, at);
        page(`${tag} ALERT: ${what} waits on its fail key: ${err.message}. The job retries, and no fail key is derived from the server secret instead. Fix: ${err.fix}`);
      }
      throw err;
    }
  };
}

/**
 * The stored authorship summary of a submission (server/pipeline/ingest.ts writes it): the
 * authorship_summary row under `pricingRev` of algorithm `algoVersion` when one is named (a
 * regrade's), else the newest, validated; null when there is none.
 */
export async function loadStoredAuthorship(db: Db, submissionId: string, pricingRev: string, algoVersion?: number): Promise<AuthorshipSummaryT | null> {
  const [row] = await db
    .select({ summary: authorshipSummary.summary, algoVersion: authorshipSummary.algoVersion })
    .from(authorshipSummary)
    .where(
      and(
        eq(authorshipSummary.submissionId, submissionId),
        eq(authorshipSummary.pricingRev, pricingRev),
        ...(algoVersion === undefined ? [] : [eq(authorshipSummary.algoVersion, algoVersion)]),
      ),
    )
    .orderBy(desc(authorshipSummary.algoVersion))
    .limit(1);
  if (row === undefined) return null;
  const parsed = AuthorshipSummary.safeParse(row.summary);
  if (!parsed.success || parsed.data.algo_version !== row.algoVersion) {
    throw new PermanentJobError(`submission ${submissionId}'s stored authorship summary (algorithm ${row.algoVersion}) does not validate`);
  }
  return parsed.data;
}

/**
 * The authorship algorithm version a stored run's score names (score.authorship.algo_version): the
 * summary its regrade must be given again. Null when the run was graded with no summary; undefined
 * when its result carries no score to read one from (a failed run).
 */
export function storedAuthorshipVersion(result: unknown): number | null | undefined {
  if (result === null || typeof result !== 'object' || !('authorship' in result)) return undefined;
  const authorship = (result as { authorship: unknown }).authorship;
  if (authorship === null) return null;
  const version = (authorship as { algo_version?: unknown } | undefined)?.algo_version;
  return typeof version === 'number' && Number.isInteger(version) ? version : undefined;
}

/** The phase seed: the first 8 bytes of sha256("agent-fun/seed/v1\0<competition>\0<phase>\0<dataset sha256>"), as a u64 decimal. */
export function phaseSeed(competitionKey: string, phaseKey: string, datasetSha256: string | null): string {
  const h = createHash('sha256').update(`agent-fun/seed/v1\0${competitionKey}\0${phaseKey}\0${datasetSha256 ?? ''}`).digest('hex');
  return BigInt(`0x${h.slice(0, 16)}`).toString();
}

/** The competition key phaseSeed takes: competition.seed_key (pinned when the row was first seeded), else its bundle_sha256, else its slug. */
export function competitionSeedKey(comp: { seedKey: string | null; bundleSha256: string | null; slug: string }): string {
  return comp.seedKey ?? comp.bundleSha256 ?? comp.slug;
}

/**
 * Whether `phaseKey` is the phase a bundle races live (the header's `seed`): its ranking phase, carrying a race
 * (contracts/competition.ts raceOf), the phase server/race/runner.ts races.
 */
export function racesLive(bundle: Pick<CompetitionBundleT, 'phases'>, phaseKey: string): boolean {
  return raceOf(bundle) !== null && bundle.phases[rankingPhaseIndex(bundle.phases)]?.key === phaseKey;
}

/**
 * Whether a pump phase's official grade takes its race's seed (the header's `seed`): only when the phase races live
 * (racesLive) and keys its failed-tx draws by server-secret/v1, the scheme the race holds too (server/race/runner.ts
 * derives the same key from the same seed). On any other scheme (phase-secret+beacon/v1, a sealed-window final
 * committed at its deadline) the grade keeps its dataset part: the commitment holds every final run to
 * phaseSeed(seed key, final, the drawn masked window) (server/chain/verify.ts checkCommittedFailKey), so the race seed
 * there would be refused seed_mismatch.
 */
export function gradeTakesRaceSeed(bundle: Pick<CompetitionBundleT, 'phases'>, ph: Pick<FailKeyPhase, 'key' | 'failKeyScheme'>): boolean {
  return racesLive(bundle, ph.key) && ph.failKeyScheme === SERVER_SECRET_FAIL_KEY_SCHEME;
}

/** An error's words: the first line of its message, then of each cause's (a Drizzle query error's cause says why it failed). */
function errorWords(err: unknown): string {
  const words: string[] = [];
  for (let e: unknown = err, depth = 0; e !== undefined && e !== null && depth < 4; e = e instanceof Error ? e.cause : undefined, depth++) {
    words.push((e instanceof Error ? e.message : String(e)).split('\n')[0]!);
  }
  return words.join(': ');
}

/**
 * The crosscheck of the race on phase `phaseId` of `slug` as grade run `runId` lands on it (the header's
 * `crosscheck`): server/race/crosscheck.ts crosscheckRace over `deps.blobs`, its report. Never throws: a racer it could
 * not compare is logged (deps.log), and a crosscheck that fails is logged and answers null, every answer it stored
 * before the failure kept (each is final on its own), the rest left uncompared for the live snapshot's retry.
 * crosscheck.ts loads only here, on a racing phase, as raceSeed does.
 */
export async function crosscheckLandedGrade(deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'log'>, landed: { slug: string; phaseId: string; runId: string }): Promise<CrosscheckReport | null> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const what = `[grade] the crosscheck of ${landed.slug}'s race (phase ${landed.phaseId}) as run ${landed.runId} landed`;
  let report: CrosscheckReport;
  try {
    const { crosscheckRace } = await import('../server/race/crosscheck.ts');
    report = await crosscheckRace(deps.db, deps.blobs, landed.phaseId);
  } catch (err) {
    log(`${what} failed, its racers left uncompared for the live snapshot to try again: ${errorWords(err)}`);
    return null;
  }
  if (report.problems.length > 0) {
    log(`${what} left ${report.problems.length} racer(s) uncompared, for the live snapshot to try again: ${report.problems.map((p) => `${p.submission_id} (run ${p.run_id}): ${p.problem}`).join('; ')}`);
  }
  return report;
}

/** The runtime a snapshot's root entrypoint selects, or why it selects none. */
export function entryRuntime(index: SnapshotIndex, accepted: readonly Runtime[]): { runtime: Runtime } | { error: string } {
  const roots = new Set(index.files.filter((f) => f.kind === 'file').map((f) => f.path));
  const found = (Object.entries(ENTRY_SCRIPTS) as [Runtime, string][]).filter(([, script]) => roots.has(script)).map(([r]) => r);
  if (found.length === 0) return { error: `the snapshot has no ${Object.values(ENTRY_SCRIPTS).join(' or ')} at its root` };
  if (found.length > 1) return { error: `the snapshot has both ${found.map((r) => ENTRY_SCRIPTS[r]).join(' and ')} at its root: keep one entrypoint` };
  const runtime = found[0]!;
  if (!accepted.includes(runtime)) return { error: `${ENTRY_SCRIPTS[runtime]} selects ${runtime}, which this competition does not accept (${accepted.join(', ')})` };
  return { runtime };
}

async function one<T>(rows: Promise<T[]>, what: string): Promise<T> {
  const [row] = await rows;
  if (row === undefined) throw new PermanentJobError(`${what} does not exist`);
  return row;
}

/** The latest receipt server_time among a competition's submissions (ISO), or null. */
export async function lastReceiptAt(db: Db, competitionId: string): Promise<string | null> {
  const [row] = await db
    .select({ at: sql<string | null>`max((${submission.receipt}->>'server_time')::timestamptz)` })
    .from(submission)
    .where(and(eq(submission.competitionId, competitionId), isNotNull(submission.receipt)));
  const at = row?.at ?? null;
  return at === null ? null : new Date(at).toISOString();
}

// ---------------------------------------------------------------- drawn instances

/** The largest instance-draw-<k>.json read (formatInstanceDraw's spelling is under 2 KB). */
export const MAX_INSTANCE_DRAW_BYTES = 65_536;

/** The instance a phase of an instance-drawn bundle grades on (phaseInstance). */
export interface PhaseInstance {
  /** practice on the dev phase, scored on the final. */
  purpose: 'practice' | 'scored';
  /** The scored draw in force (the newest record's k); null for practice. */
  k: number | null;
  /** The instance directory, holding input/ and reference/. */
  dir: string;
  /** <dir>/input: ProgramSetup.inputDir (the entry's /input). */
  inputDir: string;
  /** <dir>/reference: ProgramSetup.referenceDir (the scorer's /reference). */
  referenceDir: string;
  /** The draw record's instance_sha256, which programDataSha256 of the two directories must equal; null for practice (the sidecar holds tree digests only). */
  instanceSha256: string | null;
}

/** The test option an instance sidecar is read under: `chain` (default MAKEFUN_DRAND_CHAIN under dev auth, from the environment) when it is not quicknet. */
export function instanceChainOptions(chain?: DrandChain, env: Readonly<Record<string, string | undefined>> = process.env): InstanceChainOptions {
  let c = chain;
  if (c === undefined) {
    try {
      const devAuth = ['1', 'true'].includes((env.MAKEFUN_DEV_AUTH ?? '').toLowerCase()) && isDevAuthNodeEnv(env.NODE_ENV);
      c = drandChainFromEnv(env, { devAuth });
    } catch {
      // server/config.ts refuses it at boot: quicknet alone
      c = DRAND_QUICKNET;
    }
  }
  return c.hash === DRAND_QUICKNET.hash ? {} : { testChain: c };
}

/** A regular file's bytes (never through a link), at most `max`; null when there is none. Anything else is a PermanentJobError naming `what`. */
function readSmallFile(path: string, max: number, what: string): Buffer | null {
  let st;
  try {
    st = lstatSync(path);
  } catch {
    return null;
  }
  if (!st.isFile()) throw new PermanentJobError(`${what} ${path} is not a regular file`);
  if (st.size > max) throw new PermanentJobError(`${what} ${path} is ${st.size} bytes, over the ${max}-byte limit`);
  return readFileSync(path);
}

/**
 * A phase's instance not drawn yet (the header's `not drawn`): what phaseInstance or agentPhaseTrials reads is not there
 * at all (the competition's instance.yaml, the scored draw's first record, or an instance tree checkInstanceTrees
 * reads), or a practice tree there that is not instance.yaml's practice draw (the release re-draws it in place), which
 * the draw mends and the entry never caused. A PlatformFaultError, so a caller that knows nothing of it
 * dead-letters the job and never fails the entry; the pipeline's grade stage puts the entry back and hands its grade
 * job on until the draw lands (server/pipeline/index.ts).
 */
export class InstanceNotDrawnError extends PlatformFaultError {
  /** What is not there: the instance.yaml, the instance-draw-0.json or the tree directory. */
  readonly path: string;
  constructor(message: string, path: string) {
    super(message);
    this.name = 'InstanceNotDrawnError';
    this.path = path;
  }
}

/** Whether nothing is at `path` (not even a link). */
function isAbsent(path: string): boolean {
  try {
    lstatSync(path);
    return false;
  } catch (err) {
    return (err as NodeJS.ErrnoException).code === 'ENOENT';
  }
}

/**
 * The error of a competition's instance.yaml that readSmallFile found none of at `path`: not there at all, an
 * InstanceNotDrawnError (the practice draw writes it); there but not to be read, a PermanentJobError.
 */
function sidecarNotThere(path: string, message: string): PermanentJobError {
  return isAbsent(path) ? new InstanceNotDrawnError(message, path) : new PermanentJobError(message);
}

/** The trees checkInstanceTrees holds an instance directory's input/ and reference/ to, and what it names a failure by. */
interface InstanceTreesCheck {
  dir: string;
  expected: Record<(typeof INSTANCE_TREES)[number], string>;
  what: string;
  fix: string;
  stale?: string;
}

/**
 * An instance directory's input/ and reference/ against their tree digests (load.ts treeSha256), or a PermanentJobError
 * naming `what` and `fix`: an InstanceNotDrawnError when the tree is not there at all. With `stale` (a practice tree's
 * only: the header's `not drawn`), a tree that is there and does not check (it digests otherwise, or holds what a sealed
 * tree may not) is an InstanceNotDrawnError too, naming `stale`: the release's practice draw re-draws it in place from
 * instance.yaml (server/competitions/practice-draw.ts drawCommittedPractice), so the grade waits for it. A scored
 * tree's never takes `stale`: one that is not its record fails for good. The synchronous read (phaseInstance, for the
 * command line and tests); a grade checks them with checkInstanceTreesAsync.
 */
function checkInstanceTrees(c: InstanceTreesCheck): void {
  for (const tree of INSTANCE_TREES) {
    const at = join(c.dir, tree);
    // treeSha256's digest, each file's sum kept for the process while its stat holds: a tree checked again reads no file.
    checkInstanceTree(c, tree, at, () => sealedTreeDigest(at));
  }
}

/** checkInstanceTrees off the event loop's back: each tree walked and hashed on fs/promises (version.ts sealedTreeDigestAsync, its kept sums reused), the same answer. */
async function checkInstanceTreesAsync(c: InstanceTreesCheck): Promise<void> {
  for (const tree of INSTANCE_TREES) {
    const at = join(c.dir, tree);
    const digest = await sealedTreeDigestAsync(at);
    checkInstanceTree(c, tree, at, () => digest);
  }
}

/** One tree of checkInstanceTrees, at `at`, held to its expected digest by `digestOf` (sealedTreeDigest's answer). */
function checkInstanceTree(c: InstanceTreesCheck, tree: (typeof INSTANCE_TREES)[number], at: string, digestOf: () => ReturnType<typeof sealedTreeDigest>): void {
  const { what, fix, stale } = c;
  let actual: string;
  try {
    const digest = digestOf();
    if (!('sha256' in digest)) throw new TreeDigestError(digest.rel, digest.reason);
    actual = digest.sha256;
  } catch (err) {
    if (!(err instanceof TreeDigestError)) throw err;
    const why = err.rel === '' ? err.reason : `holds ${err.rel}, which ${err.reason}`;
    if (err.rel === '' && isAbsent(at)) throw new InstanceNotDrawnError(`${what}'s ${tree} directory ${at} ${why}: ${fix}`, at);
    if (stale !== undefined) throw new InstanceNotDrawnError(`${what}'s ${tree} directory ${at} ${why}: ${stale}`, at);
    throw new PermanentJobError(`${what}'s ${tree} directory ${at} ${why}: ${fix}`);
  }
  if (actual !== c.expected[tree]) {
    const message = `${what}'s ${tree} directory ${at} digests to ${actual}, not ${c.expected[tree]}`;
    if (stale !== undefined) throw new InstanceNotDrawnError(`${message}: ${stale}`, at);
    throw new PermanentJobError(`${message}: ${fix}`);
  }
}

/**
 * What a practice tree that is there but is not instance.yaml's practice draw waits on (checkInstanceTrees' `stale`):
 * the release's practice draw, which re-draws it in place.
 */
function practiceStaleFix(slug: string, what: 'instance' | 'trials'): string {
  const drawn = what === 'instance' ? 'the practice instance' : 'the practice trials';
  return `it is not what ${INSTANCE_FILE}'s practice round draws (a draw of an older ${INSTANCE_FILE}, or damaged): the grade waits while the release re-draws ${drawn} in place from ${INSTANCE_FILE} (${slug}'s practice-draw job)`;
}

/**
 * Every draw record under a competition's instance directory `root`, instance-draw-0.json to the
 * newest, each parsed as JSON, none missing; the empty list when there is none (`root` not there at
 * all included: nothing is drawn yet). Throws PermanentJobError: a `root` that cannot be read, a record
 * missing from the chain, not a regular file, too large or not JSON.
 */
function readDrawRecords(root: string, slug: string): unknown[] {
  let names: string[];
  try {
    names = readdirSync(root);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw new PermanentJobError(`${slug}'s instance directory ${root} cannot be read for its draw records: ${(err as Error).message}`);
    names = [];
  }
  const ks = names
    .map((n) => instanceDrawK(n))
    .filter((k): k is number => k !== null)
    .sort((a, b) => a - b);
  if (ks.length === 0) return [];
  const newest = ks[ks.length - 1]!;
  const records: unknown[] = [];
  for (let k = 0; k <= newest; k++) {
    const path = join(root, instanceDrawFile(k));
    const raw = readSmallFile(path, MAX_INSTANCE_DRAW_BYTES, `${slug}'s draw record`);
    if (raw === null) throw new PermanentJobError(`${slug}'s draw records run k = 0 to ${newest} with none missing, and ${path} is not there`);
    try {
      records.push(JSON.parse(raw.toString('utf8')));
    } catch (err) {
      throw new PermanentJobError(`${slug}'s draw record ${path} is not JSON: ${(err as Error).message}`);
    }
  }
  return records;
}

/** What phaseInstance reads before it reads a tree: the bundle's generator harness, its instance.yaml's bytes and path. */
interface PhaseInstanceSidecar {
  sidecarPath: string;
  bytes: Buffer;
  practiceFix: string;
}

/** phaseInstance's instance.yaml read (its bytes; not there, an InstanceNotDrawnError), before any check of it. */
function phaseInstanceSidecar(input: PhaseInstanceInput): PhaseInstanceSidecar {
  const { slug, bundle } = input;
  const h = bundle.harness;
  if (h.kind !== 'program/v1' || h.generator === undefined) throw new PermanentJobError(`${slug} is not an instance-drawn program/v1 competition`);
  const sidecarPath = join(input.compDir, INSTANCE_FILE);
  const practiceFix = `draw it with node scripts/competitions/instance.ts practice --competition ${slug} (it re-draws a committed ${INSTANCE_FILE}'s practice instance into a removed practice/)`;
  const bytes = readSmallFile(sidecarPath, MAX_INSTANCE_BYTES, `${slug}'s ${INSTANCE_FILE}`);
  if (bytes === null) throw sidecarNotThere(sidecarPath, `${slug} is instance-drawn, and its competition directory has no ${INSTANCE_FILE} (${sidecarPath}) to say which instances it grades on: ${practiceFix}`);
  return { sidecarPath, bytes, practiceFix };
}

/** phaseInstance's instance.yaml parsed under `chain` and checked against the bundle. */
function phaseInstanceParsed(input: PhaseInstanceInput, read: PhaseInstanceSidecar, chain: InstanceChainOptions): InstanceSidecarT {
  const { slug, bundle } = input;
  // An instance-drawn program/v1 harness (phaseInstanceSidecar refused any other).
  const h = bundle.harness as ProgramHarnessT;
  const final = bundle.phases.find((p) => p.key === 'final');
  try {
    const sidecar = parseInstanceSidecar(read.bytes, chain);
    if (final === undefined) throw new PermanentJobError(`${slug} is instance-drawn and has no final phase to draw its scored instance for`);
    checkInstanceBundle(sidecar, { generatorSha256: h.generator_sha256, opensAt: bundle.competition.opens_at, finalStartsAt: final.starts_at, finalEndsAt: final.ends_at }, chain);
    return sidecar;
  } catch (err) {
    if (isInstanceError(err)) throw new PermanentJobError(`${slug}'s ${INSTANCE_FILE} does not check (${err.code}): ${err.message}`, { cause: err });
    throw err;
  }
}

/** The dev phase's instance (the practice instance) and the trees it is held to. */
function phasePracticeInstance(input: PhaseInstanceInput, read: PhaseInstanceSidecar, sidecar: InstanceSidecarT): { instance: PhaseInstance; trees: InstanceTreesCheck } {
  const { slug } = input;
  const dir = practiceInstanceDir(input.sealedDir, slug);
  return {
    instance: { purpose: 'practice', k: null, dir, inputDir: join(dir, 'input'), referenceDir: join(dir, 'reference'), instanceSha256: null },
    trees: { dir, expected: { input: sidecar.practice.input_sha256, reference: sidecar.practice.reference_sha256 }, what: `${slug}'s practice instance`, fix: read.practiceFix, stale: practiceStaleFix(slug, 'instance') },
  };
}

/** Every draw record of the scored instance, from k = 0 (none yet: an InstanceNotDrawnError naming the draw). */
function phaseScoredRecords(input: PhaseInstanceInput, sidecar: Pick<InstanceSidecarT, 'scored'>): unknown[] {
  const { slug } = input;
  const root = instanceRootOf(input.sealedDir, slug);
  const records = readDrawRecords(root, slug);
  if (records.length === 0) {
    throw new InstanceNotDrawnError(
      `the ${input.phaseKey} phase of ${slug} grades on its drawn scored instance, and there is no draw record (${instanceDrawFile(0)}) in ${root}: the final phase is graded once the scored round (${sidecar.scored.beacon.round}, ${sidecar.scored.beacon.at}) is drawn (POST /api/admin/competitions/${slug}/instance/draw)`,
      join(root, instanceDrawFile(0)),
    );
  }
  return records;
}

/** Any other phase's instance (the newest scored draw, the chain verified under `chain`) and the trees it is held to. */
function phaseScoredInstance(input: PhaseInstanceInput, read: PhaseInstanceSidecar, records: readonly unknown[], chain: InstanceChainOptions): { instance: PhaseInstance; trees: InstanceTreesCheck } {
  const { slug } = input;
  let draw;
  try {
    draw = verifyInstanceDraws({ sidecar: read.bytes, records, competition: slug, ...chain }).at(-1)!;
  } catch (err) {
    if (isInstanceError(err)) throw new PermanentJobError(`${slug}'s draw records do not verify (${err.code}): ${err.message}`, { cause: err });
    throw err;
  }
  const dir = scoredInstanceDir(input.sealedDir, slug, draw.k);
  return {
    instance: { purpose: 'scored', k: draw.k, dir, inputDir: join(dir, 'input'), referenceDir: join(dir, 'reference'), instanceSha256: draw.record.instance_sha256 },
    trees: {
      dir,
      expected: { input: draw.record.input_sha256, reference: draw.record.reference_sha256 },
      what: `${slug}'s scored instance ${draw.k}`,
      fix: `it is not the instance ${instanceDrawFile(draw.k)} records; the final phase grades only on the draw as recorded`,
    },
  };
}

/** What phaseInstance reads a phase's instance for. */
export interface PhaseInstanceInput {
  slug: string;
  bundle: CompetitionBundleT;
  compDir: string;
  sealedDir: string;
  phaseKey: string;
  chain: InstanceChainOptions;
}

/**
 * The instance an instance-drawn bundle's phase grades on (the header's `instance`): the competition
 * directory's instance.yaml read under `chain` (parseInstanceSidecar) and checked against `bundle`
 * (checkInstanceBundle); the dev phase's the practice instance (load.ts practiceInstanceDir), its trees
 * the sidecar's practice digests; any other phase's (the final's) the newest scored draw, every
 * instance-draw-<k>.json from k = 0 verified as one chain (verifyInstanceDraws: the sidecar's sha256,
 * the scored round's signature, the seed, the redraw links), and scored-<k>/'s trees the newest
 * record's digests. Throws PermanentJobError: no retry can draw an instance or mend one. What is not there at all (no
 * instance.yaml, no draw record yet, a tree), or a practice tree there that does not digest to the sidecar's, is an
 * InstanceNotDrawnError: the draw mends it. The synchronous read, its drand rounds checked and its trees hashed on the
 * caller's thread (the command line, tests); a grade reads it with phaseInstanceAsync, the same answer.
 */
export function phaseInstance(input: PhaseInstanceInput): PhaseInstance {
  const read = phaseInstanceSidecar(input);
  const sidecar = phaseInstanceParsed(input, read, input.chain);
  const at = input.phaseKey === 'dev' ? phasePracticeInstance(input, read, sidecar) : phaseScoredInstance(input, read, phaseScoredRecords(input, sidecar), input.chain);
  checkInstanceTrees(at.trees);
  return at.instance;
}

/**
 * phaseInstance off the event loop's back, the same answer and the same refusals in the same order: the sidecar's
 * practice round, and on a scored phase the scored round with every record's signature, checked on the off-thread pool
 * (load.ts instanceRoundCheckOffLoop, a true verdict kept in the process's memo) and handed in as the chain's
 * `verifyRound`, so the read does no BLS arithmetic on the loop; the trees walked and hashed on fs/promises
 * (checkInstanceTreesAsync). Rejects with the pool's OffThreadError when it cannot check a round now (the job retries).
 */
export async function phaseInstanceAsync(input: PhaseInstanceInput, opts: { signal?: AbortSignal } = {}): Promise<PhaseInstance> {
  const read = phaseInstanceSidecar(input);
  const testChain = input.chain.testChain;
  const practiceRound = await instanceRoundCheckOffLoop({ sidecar: read.bytes, ...(testChain === undefined ? {} : { testChain }) }, opts);
  const sidecar = phaseInstanceParsed(input, read, { ...input.chain, verifyRound: practiceRound });
  let at: { instance: PhaseInstance; trees: InstanceTreesCheck };
  if (input.phaseKey === 'dev') at = phasePracticeInstance(input, read, sidecar);
  else {
    const records = phaseScoredRecords(input, sidecar);
    const rounds = await instanceRoundCheckOffLoop({ sidecar: read.bytes, records, ...(testChain === undefined ? {} : { testChain }) }, opts);
    at = phaseScoredInstance(input, read, records, { ...input.chain, verifyRound: rounds });
  }
  await checkInstanceTreesAsync(at.trees);
  return at.instance;
}

/**
 * The directory a competition's programs are read from: GradeWorkerDeps.competitionDir's, else
 * competitions/<slug>, or for a pack program/v1 harness server/competitions/load.ts programCompetitionDir's
 * (the header's `pack`: the house tests competition's for a sponsored code bounty; likewise its medium's pilot's for a
 * sponsored judged-artifact competition, whose own trees judgedTreesOf finds).
 */
export function competitionDirOf(deps: Pick<GradeWorkerDeps, 'competitionDir'>, slug: string, harness: HarnessT): string {
  return deps.competitionDir?.(slug) ?? programCompetitionDir(slug, harness, COMPETITIONS_DIR);
}

/**
 * A competition's starter as its kit hands it out (the header's `size`): every file the kit route copies under
 * starter/ (server/routes/competitions/kit.ts starterFiles: <competitionsDir>/<slug>/starter/, dot entries,
 * node_modules and __pycache__ left out), each read and hashed as kit.json lists it, its path relative to starter/
 * (grader/size.ts kitStarterFiles), so the server counts an entry's code against exactly the files an entrant was
 * handed. [] for a competition with no starter (a sponsored code bounty has no directory of its own, and its kit no
 * starter/).
 */
export async function competitionStarter(competitionsDir: string, slug: string): Promise<StarterFile[]> {
  // Loaded when used: the kit route is a large module, needed by a size count's grade alone.
  const { starterFiles } = await import('../server/routes/competitions/kit.ts');
  return kitStarterFiles(
    starterFiles(competitionsDir, slug).map(([path, abs]) => {
      const bytes = readFileSync(abs);
      return { path, size: bytes.length, sha256: sha256Hex(bytes) };
    }),
  );
}

/** The pack trees a phase of a pack bundle grades on (phasePackTrees). */
export interface PhasePackTrees {
  /** The pack's half the phase grades on: dev on the dev phase, final on any other. */
  half: 'dev' | 'final';
  /** The materialized input tree: ProgramSetup.inputDir (the entry's /input, one case at a time under cases 'per-file'). */
  inputDir: string;
  /** The materialized reference tree: ProgramSetup.referenceDir (the scorer's /reference). */
  referenceDir: string;
}

/**
 * The trees a pack bundle's phase grades on (the header's `pack`): its scorer directory under `compDir`
 * re-hashed against scorer_sha256 (load.ts packScorerIssue), then the phase's input and reference trees
 * (pack.dev on the dev phase, pack.final on the final) materialized from `blobs` into
 * <workRoot>/pack-trees/ and re-hashed (load.ts packTreeDir; a tree the store lacks is taken from a pack/
 * copy beside `compDir`'s competition.yaml, once it re-hashes). Throws PermanentJobError: no retry mends
 * a scorer that is not the sealed one or a tree the house does not hold.
 */
export async function phasePackTrees(input: { slug: string; harness: ProgramHarnessT; compDir: string; phaseKey: string; blobs: BlobStore; workRoot: string }): Promise<PhasePackTrees> {
  const { slug, harness: h } = input;
  if (h.pack === undefined) throw new PermanentJobError(`${slug} is not a pack program/v1 competition`);
  const scorer = packScorerIssue(h, input.compDir);
  if (scorer !== null) throw new PermanentJobError(`${slug} grades with the scorer its harness seals (scorer_sha256 ${h.scorer_sha256 ?? 'none'}), and ${scorer}`);
  const half = input.phaseKey === 'dev' ? 'dev' : 'final';
  const dirOf = async (tree: PackTreeName): Promise<string> => {
    const digest = packTreeDigest(h.pack!, tree);
    try {
      return await packTreeDir({ blobs: input.blobs, digest, cacheRoot: join(input.workRoot, PACK_CACHE_DIR), sources: packTreeSources([input.compDir], tree) });
    } catch (err) {
      if (err instanceof Error && err.name === 'PackError') {
        throw new PermanentJobError(`the ${input.phaseKey} phase of ${slug} grades on its pack's ${tree} tree ${digest}, which cannot be materialized: ${err.message}`, { cause: err });
      }
      throw err;
    }
  };
  return { half, inputDir: await dirOf(`${half}/input`), referenceDir: await dirOf(`${half}/reference`) };
}

/**
 * A program/v1 phase's plan as its grades build it: an instance-drawn bundle's on the phase's instance (the header's
 * `instance`), a pack bundle's on the phase's pack trees (`pack`), each seeded on that data's digest (phaseSeed of it;
 * none for a bundle with data of its own), or on `seed` when one is given (a regrade's, the stored run's). What a grade,
 * a regrade and a timing heat (the header's `code heat`) run the entry under.
 */
async function programPhasePlan(
  deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'workRoot' | 'competitionDir' | 'sealedDir' | 'drandChain' | 'sandbox'>,
  input: { slug: string; bundle: CompetitionBundleT; harness: ProgramHarnessT; phaseKey: string; competitionKey: string; seed: string | null },
): Promise<HarnessPlan> {
  return programPlanAsync(await programPhaseSetup(deps, input));
}

/**
 * The tree at `dir`, the bundle's `rel` (its path in the bundle, '.' the competition root), as the k8s sandbox's pods
 * are staged from it (the header's `k8s data`): copied under the data root `dataRoot` as <dataRoot>/bundle-trees/<slug>/
 * <digest>/<rel> (sandbox/bundle-trees.ts stageBundleTree), the digest `sealed` its harness seals it to (undefined: its
 * own), or null when it lies under the data root already, where it is staged from as it is. A tree the image does not hold as
 * sealed is a PlatformFaultError naming `what`: the image's fault, never the entry's.
 */
async function stageOntoClaim(o: { slug: string; dataRoot: string }, dir: string, rel: string, sealed: string | undefined, what: string): Promise<StagedTree | null> {
  if (underDataRoot(o.dataRoot, dir)) return null;
  try {
    return await stageBundleTree({ dataRoot: o.dataRoot, slug: o.slug, source: dir, rel, digest: sealed ?? null });
  } catch (err) {
    if (err instanceof BundleTreeError) {
      throw new PlatformFaultError(`${o.slug}'s ${what} cannot be staged under the k8s sandbox's data root (${o.dataRoot}), the only tree a sandbox pod is staged from: ${err.message}`, { cause: err });
    }
    throw err;
  }
}

/** A bundle directory (its path in the bundle, '.' the root) under the competition directory `compDir`. */
function bundleDirOf(compDir: string, rel: string): string {
  return rel === '.' ? compDir : join(compDir, ...rel.split('/'));
}

/**
 * A program/v1 setup as the k8s sandbox's pods are staged from it (the header's `k8s data`): each tree a grade of it mounts
 * (the scorer directory at /bot, the input data at /input, the reference data at /reference) that lies outside the data
 * root `dataRoot` staged under <dataRoot>/bundle-trees/<slug>/<digest>/ (sandbox/bundle-trees.ts stageBundleTree),
 * a bundle's own tree as the digest its harness seals it to (scorer_sha256, input_sha256, reference_sha256), and the
 * setup pointed at the copies: its compDir the scorer's stage directory, so the scorer is at the bundle's own path in
 * it, and its inputDir and referenceDir named. A tree already under the data root (an instance's under the sealed
 * directory, a pack's under the work root) is staged from where it is. The copies are the trees byte for byte, so the
 * run's dataset digest (programDataSha256) and scorer digest (programScorerDigest) are the image's. A tree the image
 * does not hold as sealed is a PlatformFaultError: the image's fault, never the entry's.
 */
export async function stageProgramSetup(setup: ProgramSetup, o: { slug: string; dataRoot: string }): Promise<ProgramSetup> {
  const h = setup.harness;
  const paths = programPaths(setup);
  const stage = (dir: string, rel: string, sealed: string | undefined, what: string): Promise<StagedTree | null> => stageOntoClaim(o, dir, rel, sealed, what);
  // The bundle's own trees by the paths and digests its harness names them; an instance's or a pack's (named in the
  // setup) by their own digests, under their tree's name.
  const scorer = await stage(paths.scorerDir, scorerDirOf(h.scorer.entrypoint), h.scorer_sha256, 'scorer directory');
  const own = (named: string | undefined, rel: string | null, sealed: string | undefined, tree: 'input' | 'reference') =>
    named === undefined && rel !== null ? { rel, sealed } : { rel: tree, sealed: undefined };
  let inputDir: string | null = null;
  if (paths.inputDir !== null) {
    const t = own(setup.inputDir, h.input_data, h.input_sha256, 'input');
    inputDir = (await stage(paths.inputDir, t.rel, t.sealed, 'input data'))?.dir ?? paths.inputDir;
  }
  const r = own(setup.referenceDir, h.scorer.reference_data, h.reference_sha256, 'reference');
  const referenceDir = (await stage(paths.referenceDir, r.rel, r.sealed, 'reference data'))?.dir ?? paths.referenceDir;
  return { ...setup, compDir: scorer?.root ?? setup.compDir, ...(inputDir === null ? {} : { inputDir }), referenceDir };
}

/**
 * An agent/v1 setup as the k8s sandbox's pods are staged from it (the header's `k8s data`): the env directory (the env's
 * /bot) and the scorer directory (the scorer's /bot), the bundle's own trees read from the image's competitions/<slug>/,
 * staged under <dataRoot>/bundle-trees/<slug>/ as the digests the harness seals them to (env_sha256, scorer_sha256),
 * and the setup pointed at the copies: its compDir the scorer's stage directory, so the scorer is at the bundle's own
 * path in it (agent.ts trialProgramSetup), and its envDir the env's copy (agent.ts envProgram). A tree under the data
 * root already is staged from where it is. A trial's instance (the sealed directory) and its forwarder and scratch (the
 * work root) lie under the data root already. The copies are the trees byte for byte, so the run's scorer_version (the
 * sealed scorer_sha256) is unchanged. A tree the image does not hold as sealed is a PlatformFaultError.
 */
export async function stageAgentSetup(setup: AgentSetup, o: { slug: string; dataRoot: string }): Promise<AgentSetup> {
  const h = setup.harness;
  const envRel = scorerDirOf(h.env.entrypoint);
  const envDir = setup.envDir ?? bundleDirOf(setup.compDir, envRel);
  const scorerRel = scorerDirOf(h.scorer.entrypoint);
  const env = await stageOntoClaim(o, envDir, envRel, h.env_sha256, 'env directory');
  const scorer = await stageOntoClaim(o, bundleDirOf(setup.compDir, scorerRel), scorerRel, h.scorer_sha256, 'scorer directory');
  return { ...setup, compDir: scorer?.root ?? setup.compDir, envDir: env?.dir ?? envDir };
}

/**
 * A scrape/v1 scorer setup as the k8s sandbox's pods are staged from it (the header's `k8s data`): the scorer directory (the
 * scorer's /bot), read from the image's competitions/<slug>/, staged under <dataRoot>/bundle-trees/<slug>/ as its
 * sealed scorer_sha256, and the setup's compDir its stage directory, so the scorer is at the bundle's own path in it
 * (scrape/score.ts scrapeProgramSetup). A scorer under the data root already is staged from where it is. A scorer the image
 * does not hold as sealed is a PlatformFaultError.
 */
export async function stageScrapeScorerSetup(setup: ScrapeScorerSetup, o: { slug: string; dataRoot: string }): Promise<ScrapeScorerSetup> {
  const rel = scorerDirOf(setup.harness.scorer.entrypoint);
  const scorer = await stageOntoClaim(o, bundleDirOf(setup.compDir, rel), rel, setup.harness.scorer_sha256, 'scorer directory');
  return scorer === null ? setup : { ...setup, compDir: scorer.root };
}

/** An agent/v1 setup as `sandbox`'s programs mount it: on the k8s sandbox stageAgentSetup's (under its data root), else `setup` itself. */
export async function agentSetupFor(sandbox: Parameters<typeof k8sDataRoot>[0], slug: string, setup: AgentSetup): Promise<AgentSetup> {
  const dataRoot = k8sDataRoot(sandbox);
  return dataRoot === null ? setup : stageAgentSetup(setup, { slug, dataRoot });
}

/**
 * A scrape/v1 scorer setup as `sandbox`'s programs mount it: on the k8s sandbox stageScrapeScorerSetup's (under its data
 * root), else `setup` itself. What judges a scrape/v1 run with a k8s sandbox takes its setup from here.
 */
export async function scrapeScorerSetupFor(sandbox: Parameters<typeof k8sDataRoot>[0], slug: string, setup: ScrapeScorerSetup): Promise<ScrapeScorerSetup> {
  const dataRoot = k8sDataRoot(sandbox);
  return dataRoot === null ? setup : stageScrapeScorerSetup(setup, { slug, dataRoot });
}

/**
 * What programPhasePlan plans on: the phase's program setup (its instance's or pack's trees, or a sponsored
 * judged-artifact bundle's reference data: judgedTreesOf; on the k8s sandbox, stageProgramSetup's) and its seed.
 */
async function programPhaseSetup(
  deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'workRoot' | 'competitionDir' | 'sealedDir' | 'drandChain' | 'sandbox'>,
  input: { slug: string; bundle: CompetitionBundleT; harness: ProgramHarnessT; phaseKey: string; competitionKey: string; seed: string | null },
): Promise<{ setup: ProgramSetup; seed: string }> {
  const { slug, bundle, harness, phaseKey } = input;
  const compDir = competitionDirOf(deps, slug, harness);
  let setup: ProgramSetup = { compDir, harness, leaderboard: bundle.leaderboard };
  // An instance-drawn bundle grades on the phase's instance, and seeds on its digest; a pack bundle on
  // the phase's pack trees, and seeds on theirs.
  let instanceSha256: string | null = null;
  if (harness.generator !== undefined) {
    const instance = await phaseInstanceAsync({ slug, bundle, compDir, sealedDir: deps.sealedDir ?? sealedDirFromEnv(), phaseKey, chain: instanceChainOptions(deps.drandChain) });
    setup = { ...setup, inputDir: instance.inputDir, referenceDir: instance.referenceDir };
    instanceSha256 = await programDataSha256Async(setup);
    if (instance.instanceSha256 !== null && instanceSha256 !== instance.instanceSha256) {
      throw new PermanentJobError(`${slug}'s scored instance ${instance.dir} has dataset digest ${instanceSha256}, not its draw record's instance_sha256 ${instance.instanceSha256}`);
    }
  } else if (harness.pack !== undefined) {
    const trees = await phasePackTrees({ slug, harness, compDir, phaseKey, blobs: deps.blobs, workRoot: deps.workRoot });
    setup = { ...setup, inputDir: trees.inputDir, referenceDir: trees.referenceDir };
    instanceSha256 = await programDataSha256Async(setup);
  } else if (harness.final_dataset === true && phaseKey === 'final') {
    // A final_dataset bundle's final grades on the program dataset attached to it, and seeds on its trees' digest.
    const trees = await programFinalDataset(deps.db, slug);
    setup = { ...setup, inputDir: trees.inputDir, referenceDir: trees.referenceDir };
    instanceSha256 = await programDataSha256Async(setup);
    if (instanceSha256 !== trees.dataSha256) throw new PermanentJobError(`${slug}'s final dataset ${trees.slug} digests to ${instanceSha256}, not its manifest's data_sha256 ${trees.dataSha256}`);
  } else if (harness.judge !== undefined && judgedHouseSlug(harness) !== null) {
    // A judged-artifact bundle grades on its medium's pilot gate scorer, the sealed one, and on its own caps.
    const scorer = packScorerIssue(harness, compDir);
    if (scorer !== null) throw new PermanentJobError(`${slug} grades with the gate scorer its harness seals (scorer_sha256 ${harness.scorer_sha256 ?? 'none'}), and ${scorer}`);
    const trees = await judgedTreesOf(deps, slug, harness, harness.judge);
    if (trees.referenceDir !== null) setup = { ...setup, referenceDir: trees.referenceDir };
  }
  // A k8s pod is staged only from under the data root: what the grade mounts from outside it is copied there (the header's `k8s data`).
  const dataRoot = k8sDataRoot(deps.sandbox);
  if (dataRoot !== null) setup = await stageProgramSetup(setup, { slug, dataRoot });
  return { setup, seed: input.seed ?? phaseSeed(input.competitionKey, phaseKey, instanceSha256) };
}

/**
 * What a patch/v1 phase's plan grades on (grader/harnesses.ts patchPlan): the bounty's sealed base tree
 * (repo.base_tree_sha256) and the phase's tree (pack.dev on the dev phase, pack.final on the final), each
 * materialized from `blobs` under <workRoot>/patch-base/ and <workRoot>/patch-phase/ and re-verified
 * (patch/execute.ts patchTreeDir), the phase tree's lists.json, and its seed: phaseSeed of the phase tree's digest,
 * or `seed` when one is given (a regrade's, the stored run's). Its test log is never kept: what a grade records is
 * the run log alone, and the final's tests are sealed. Throws PlatformFaultError, the platform's fault and no
 * entry's, on the k8s sandbox (its pods run no repository image: sandbox/k8s.ts refuses one) and for a tree the
 * house cannot materialize or a phase tree whose lists.json is absent or invalid (NO_PATCH_TREES_MESSAGE): no retry
 * mends either. A tree that does not match its index where it was made (PatchRunnerError), or a read that failed
 * otherwise, is thrown as it is, retried.
 */
export async function patchPhaseSetup(
  deps: Pick<GradeWorkerDeps, 'blobs' | 'workRoot' | 'sandbox'>,
  input: { slug: string; harness: PatchHarnessT; phaseKey: string; competitionKey: string; seed: string | null },
): Promise<PatchPlanInput> {
  const { slug, harness: h, phaseKey } = input;
  if (deps.sandbox.kind === 'k8s') {
    throw new PlatformFaultError(`${slug} is a patch/v1 competition, which grades on the docker sandbox alone: the k8s sandbox runs no repository image (MAKEFUN_SANDBOX=k8s)`);
  }
  const phase: PatchPhaseT = phaseKey === 'dev' ? 'dev' : 'final';
  const treeOf = async (what: string, digest: string, cache: string): Promise<PatchTree> => {
    try {
      return await patchTreeDir({ blobs: deps.blobs, digest, cacheRoot: join(deps.workRoot, cache) });
    } catch (err) {
      if (err instanceof RepoIntakeError) {
        throw new PlatformFaultError(`${slug}: ${NO_PATCH_TREES_MESSAGE}, and the ${phaseKey} phase's ${what} ${digest} cannot be materialized: ${err.message}`, { cause: err });
      }
      throw err;
    }
  };
  const base = await treeOf('base tree', h.repo.base_tree_sha256, PATCH_BASE_CACHE);
  const tree = await treeOf(`${phase} tree`, h.pack[phase].tree_sha256, PATCH_PHASE_CACHE);
  let lists: PatchListsT;
  try {
    lists = await readPatchLists(tree.dir);
  } catch (err) {
    // The tree matched its sealed index just now: lists that are not there, not a file or not lists were sealed so.
    const sealed = err instanceof PatchRunnerError || err instanceof z.ZodError || err instanceof SyntaxError || (err instanceof Error && 'code' in err && err.code === 'ENOENT');
    if (!sealed) throw err;
    throw new PlatformFaultError(`${slug}: ${NO_PATCH_TREES_MESSAGE}, and the ${phase} tree ${h.pack[phase].tree_sha256}'s ${PATCH_LISTS_FILE} does not read: ${err instanceof Error ? err.message : String(err)}`, { cause: err });
  }
  return {
    setup: { harness: h, phase, base, phaseTreeDir: tree.dir, lists, keepTestLog: false },
    seed: input.seed ?? phaseSeed(input.competitionKey, phaseKey, h.pack[phase].tree_sha256),
  };
}

/**
 * The trees a final_dataset program/v1 bundle's final phase grades on (contracts/competition.ts
 * ProgramHarness.final_dataset): the program dataset attached to that phase (phase.dataset_id), its directory (the row's
 * path, against the project root as every dataset row's is) verified whole and held to the row's sha256
 * (grader/program-dataset.ts readFrozenProgramDataset). Throws PermanentJobError when none is attached (the lock waits
 * for one: contracts/competition.ts gradesOnPhaseDataset, so a grade asked for without one is a fault no retry mends)
 * or when it does not verify; a directory that is not there at all is an ordinary error, retried (a volume may not be
 * mounted yet), as a replay's dataset is.
 */
async function programFinalDataset(db: Db, slug: string): Promise<{ slug: string; inputDir: string; referenceDir: string; dataSha256: string }> {
  const [row] = await db
    .select({ ds: dataset })
    .from(phase)
    .innerJoin(competition, eq(competition.id, phase.competitionId))
    .leftJoin(dataset, eq(dataset.id, phase.datasetId))
    .where(and(eq(competition.slug, slug), eq(phase.key, 'final')));
  if (row === undefined) throw new PermanentJobError(`${slug} has no final phase`);
  if (row.ds === null) throw new PermanentJobError(`the final phase of ${slug} grades on its attached dataset, and none is attached (npm run admin:dataset -- --sealed --attach ${slug}:final)`);
  const dir = resolve(PROJECT_ROOT, row.ds.path);
  if (!existsSync(dir)) throw new Error(`the final dataset ${row.ds.slug} of ${slug} is not at ${dir}`);
  try {
    const frozen = readFrozenProgramDataset(dir, { expectSha256: row.ds.sha256 });
    return { slug: row.ds.slug, inputDir: frozen.inputDir, referenceDir: frozen.referenceDir, dataSha256: frozen.manifest.data_sha256 };
  } catch (err) {
    if (err instanceof ProgramDatasetError) throw new PermanentJobError(`dataset ${row.ds.slug}: ${err.message}`, { cause: err });
    throw err;
  }
}

/** Where a judged bundle's judge reads its judge directory and its gate its reference data (judgedTreesOf). */
export interface JudgedTrees {
  /** The judge directory (readJudgeTree reads it, held to judge_sha256). */
  judgeDir: string;
  /** The gate's reference data when it is not the competition directory's own (ProgramSetup.referenceDir), else null. */
  referenceDir: string | null;
  /**
   * The judge's ladder directory when the bundle names a ladder and it is not the competition directory's own (a
   * sponsored judged-artifact competition's, materialized from its choice: judgeLadderDirOf reads it); no key otherwise.
   */
  ladderDir?: string;
}

/**
 * Where a judged program/v1 bundle's judge directory and gate reference data are read: judge.dir and
 * scorer.reference_data under its competition's directory in the image (competitionDirOf) when those are the sealed
 * trees (a house judged competition's own, or a sponsored one's composed of its pilot's own inputs), referenceDir null.
 * Else, for a bundle sealed to its medium's pilot gate scorer (load.ts judgedHouseSlug: a sponsored judged-artifact
 * competition, which has no directory of its own) that a proposal set up, the trees load.ts judgedArtifactTrees
 * materializes under <workRoot>/pack-trees/ from the proposal's choice (competition_proposal.document.harness, as the
 * team's setup left it) and the anchors' blobs, each held to the bundle's seal, and, when the bundle names a ladder,
 * its ladder directory too (ladderDir), from the choice's ladder and its blobs, held to ladder_sha256: a sponsored
 * bundle's own directory (its pilot's) holds none. A competition no proposal set up keeps its directory's, which
 * readJudgeTree (and grader/judge-ladder-tree.ts readJudgeLadder) refuses when it is not the sealed one. Throws
 * PermanentJobError when the trees cannot be materialized: no retry mends a choice, an anchor or a ladder file that is
 * not the sealed one.
 */
export async function judgedTreesOf(deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'workRoot' | 'competitionDir'>, slug: string, harness: ProgramHarnessT, judge: ProgramJudgeT): Promise<JudgedTrees> {
  const compDir = competitionDirOf(deps, slug, harness);
  const own: JudgedTrees = { judgeDir: bundleDirOf(compDir, judge.dir), referenceDir: null };
  if (judgedHouseSlug(harness) === null) return own;
  const reference = harness.scorer.reference_data;
  const ownReference = reference === null || harness.reference_sha256 === undefined || (await rehashesAsync(bundleDirOf(compDir, reference), harness.reference_sha256));
  const ownLadder = judge.ladder === undefined || (await rehashesAsync(bundleDirOf(compDir, judge.ladder.dir), judge.ladder.ladder_sha256));
  // Each tree rehashed on fs/promises (load.ts rehashesAsync, a file hashed before answered from its stat).
  if (ownReference && ownLadder && (await rehashesAsync(own.judgeDir, judge.judge_sha256))) return own;
  const [row] = await deps.db
    .select({ document: competitionProposal.document })
    .from(competitionProposal)
    .innerJoin(competition, eq(competition.id, competitionProposal.competitionId))
    .where(eq(competition.slug, slug))
    .limit(1);
  if (row === undefined) return own;
  const document = row.document;
  const choice = typeof document === 'object' && document !== null && 'harness' in document ? document.harness : null;
  try {
    return await judgedArtifactTrees({ blobs: deps.blobs, harness, choice, cacheRoot: join(deps.workRoot, PACK_CACHE_DIR) });
  } catch (err) {
    if (err instanceof Error && (err.name === 'JudgedTreesError' || err.name === 'PackError')) {
      throw new PermanentJobError(
        `${slug}'s reference data ${harness.reference_sha256 ?? 'unsealed'} and judge directory ${judge.judge_sha256}${judge.ladder === undefined ? '' : ` and ladder directory ${judge.ladder.ladder_sha256}`} cannot be materialized from its proposal's choice: ${err.message}`,
        { cause: err },
      );
    }
    throw err;
  }
}

/**
 * Where a judged bundle's ladder directory is read: the one judgedTreesOf materialized (`trees.ladderDir`, a sponsored
 * judged-artifact competition's), else judge.ladder.dir under its competition's directory (competitionDirOf).
 */
function judgeLadderDirOf(deps: Pick<GradeWorkerDeps, 'competitionDir'>, slug: string, harness: ProgramHarnessT, ladder: NonNullable<ProgramJudgeT['ladder']>, trees: Pick<JudgedTrees, 'ladderDir'>): string {
  return trees.ladderDir ?? bundleDirOf(competitionDirOf(deps, slug, harness), ladder.dir);
}

/**
 * The ladder a regrade holds a dev run's v3 provisional record to (regrade.ts RegradeL1Request.judgeLadder): the bundle's
 * sealed ladder as grader/judge-ladder-tree.ts readJudgeLadderAsync reads it, beside the judge directory judgedTreesOf
 * finds, read here before the regrade starts: the tree digests on fs/promises and a calibration record not read before
 * parsed and fitted on the off-thread pool, so the regrade's synchronous hold reads no ladder on the event loop (the pool's
 * OffThreadError rejects, and the job retries). A judge directory that cannot be materialized reads as the ladder's
 * refusal: only a v3 record is held to it, and a v1 or v2 record's regrade never reads it.
 */
async function regradeJudgeLadder(
  deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'workRoot' | 'competitionDir'>,
  slug: string,
  harness: ProgramHarnessT,
  judge: ProgramJudgeT,
): Promise<JudgeLadderInputs | { refused: string }> {
  const ladder = judge.ladder;
  if (ladder === undefined) return { refused: 'the bundle names no ladder (harness.judge.ladder)' };
  let trees: JudgedTrees | { refused: string };
  try {
    trees = await judgedTreesOf(deps, slug, harness, judge);
  } catch (err) {
    if (!(err instanceof PermanentJobError)) throw err;
    trees = { refused: err.message };
  }
  if ('refused' in trees) return trees;
  const { readJudgeLadderAsync } = await import('./judge-ladder-tree.ts');
  return readJudgeLadderAsync(judgeLadderDirOf(deps, slug, harness, ladder, trees), judge, trees.judgeDir);
}

/**
 * The judge heat a program/v1 regrade holds a judged run's record to (regrade.ts RegradeL1Request.judge, judgeVerdictOf):
 * the bundle's harness's judge, and the bundle's prizes beside it (RegradeL1Request.judgePrizes), which a screened
 * final's v4 record's line M and race tiers are held to (regrade.ts holdScreenedRecord: judgeShortlistPlaces over the
 * last paid place, judgeRaceTiers over the placement prizes), as the final's setup drew them (judgeHeatInputs). Nothing
 * under a harness naming no judge heat; no other record reads the prizes.
 */
export function regradeJudgeOf(bundle: Pick<CompetitionBundleT, 'harness' | 'prizes'>): { judge?: ProgramJudgeT; judgePrizes?: CompetitionBundleT['prizes'] } {
  return bundle.harness.kind === 'program/v1' && bundle.harness.judge !== undefined ? { judge: bundle.harness.judge, judgePrizes: bundle.prizes } : {};
}

// ---------------------------------------------------------------- practice windows: the eras dev grade

/** A pumpfun-replay/v2 bundle's harness. */
type PumpHarnessT = Extract<HarnessT, { kind: 'pumpfun-replay/v2' }>;

/** A dev phase's practice windows (Phase.practice_windows) and the pump replay harness they grade on; null for a phase without them. */
export function practiceWindowsOf(bundle: CompetitionBundleT, phaseKey: string): { harness: PumpHarnessT; windows: PracticeWindowsT } | null {
  if (bundle.harness.kind !== 'pumpfun-replay/v2') return null;
  const windows = bundle.phases.find((p) => p.key === phaseKey)?.practice_windows;
  return windows === undefined ? null : { harness: bundle.harness, windows };
}

/** One practice window as a grade takes it: its key, the dataset row it grades on and the seed it runs under (phaseSeed over that dataset). */
export interface EraWindow {
  key: string;
  ds: typeof dataset.$inferSelect;
  seed: string;
}

/**
 * A dev phase's practice windows with a dataset attached, in key order, each under its own seed (phaseSeed of the
 * competition key, the dev phase and the window's dataset). A PermanentJobError when a window the bundle names has no
 * dataset (the pipeline holds the grade until every one has: server/pipeline/ingest.ts gradePhaseOf), or its row names
 * another length than the bundle's.
 */
export async function attachedEraWindows(db: Db, phaseId: string, windows: PracticeWindowsT, competitionKey: string): Promise<EraWindow[]> {
  const rows = await db.select({ key: practiceWindow.key, hours: practiceWindow.hours, ds: dataset }).from(practiceWindow).innerJoin(dataset, eq(dataset.id, practiceWindow.datasetId)).where(eq(practiceWindow.phaseId, phaseId));
  const byKey = new Map(rows.map((r) => [r.key, r]));
  return practiceWindowKeys(windows.count).map((key) => {
    const row = byKey.get(key);
    if (row === undefined) throw new PermanentJobError(`practice window ${key} of the dev phase has no dataset attached`);
    if (row.hours !== windows.hours) throw new PermanentJobError(`practice window ${key} is ${row.hours} h long, and the bundle's windows are ${windows.hours} h`);
    return { key, ds: row.ds, seed: phaseSeed(competitionKey, 'dev', row.ds.sha256) };
  });
}

/**
 * The windows an eras run graded, from its run_era rows (in the order given): each one's dataset resolved by the
 * row's dataset_sha256 (unique, so it is the dataset the window was graded on even when the phase's attached one has
 * been replaced), under the seed the row recorded. A PermanentJobError when a dataset is gone.
 */
export async function storedEraWindows(db: Db, rows: readonly EraRow[]): Promise<EraWindow[]> {
  const windows: EraWindow[] = [];
  for (const row of rows) {
    const ds = await one(db.select().from(dataset).where(eq(dataset.sha256, row.datasetSha256)), `dataset ${row.datasetSha256} (practice window ${row.windowKey})`);
    windows.push({ key: row.windowKey, ds, seed: row.seed });
  }
  return windows;
}

/**
 * One practice window's plan: the window's dataset loaded through `load` and checked against its row, replayed under the
 * window's seed and the public fail key of it (a dev phase's: failKeyFor), no final window. The eras dev grade, its
 * regrade and the dev-stress runs of a window build theirs here.
 */
export async function eraWindowPlan(harness: PumpHarnessT, window: EraWindow, load: NonNullable<GradeWorkerDeps['loadDataset']>): Promise<HarnessPlan> {
  const { ds } = window;
  let loaded;
  try {
    loaded = await load(ds);
  } catch (err) {
    if (err instanceof DatasetIntegrityError) throw new PermanentJobError(`dataset ${ds.slug}: ${err.message}`, { cause: err });
    throw err;
  }
  if (loaded.dataset.sha256 !== ds.sha256) throw new PermanentJobError(`dataset ${ds.slug} loads as ${loaded.dataset.sha256}, not its recorded ${ds.sha256}`);
  return replayPlan({ harness, dataset: loaded.dataset, sample: loaded.sample, seed: window.seed, failKey: publicFailKey(window.seed), finalWindow: null });
}

function eraRef(w: EraWindow): EraWindowRef {
  return { key: w.key, datasetId: w.ds.id, datasetSha256: w.ds.sha256, seed: w.seed };
}

/** The Score a finished window's row holds, or null when the row is not one a retried grade may resume from (another dataset or seed, no whole Score, a Score that no longer hashes to its sha256). */
function keptEraScore(row: EraRow, w: EraWindow): ScoreT | null {
  if (row.status !== 'finished' || row.result === null || row.actionLogSha256 === null || row.datasetSha256 !== w.ds.sha256 || row.seed !== w.seed) return null;
  const parsed = Score.safeParse(row.result);
  return parsed.success && scoreDigest(parsed.data).sha256 === row.resultSha256 ? parsed.data : null;
}

/** What gradeEras takes from the grade handler. */
interface ErasGrade {
  deps: GradeWorkerDeps;
  ctx: GradeJobContext | undefined;
  ids: RunIds;
  harness: PumpHarnessT;
  /** The windows' length (practice_windows.hours): what aggregateEras is given. */
  hours: number;
  windows: readonly EraWindow[];
  /** The first window's plan, built already: it stands for the versions every window's plan has alike. */
  plan: HarnessPlan;
  runtime: Runtime;
  /** The entry, its env-lane entry secrets with it (SnapshotSource.secrets): what every window runs. */
  snapshot: SnapshotSource;
  /** Those secrets' rows and values (the header's `entry secrets`): recorded on the run, masked out of each window's row, and scanned for. */
  secrets: EnvSecrets;
  /** gradeEntry's request but a window's plan, runtime, snapshot and label: the handler's `common` and `stop`. */
  base: Omit<GradeRequest, 'plan' | 'runtime' | 'snapshot' | 'label'>;
  load: NonNullable<GradeWorkerDeps['loadDataset']>;
}

/**
 * A dev grade on practice windows (the header's `practice windows`): the run row first (running, the way an agent/v1
 * run starts, under the id of this grade job so a retry finds it), then each window in key order: one already finished
 * in the run's run_era rows is kept (the retry resumes), any other is graded on its own plan (two executions, byte
 * equal: grade.ts gradeEntry) and its row and blobs recorded. The grade stops at the first window that is not ranked
 * (a failure, a timeout, two executions that disagree, an unmetered cost): that window's own outcome is the run's, as
 * aggregateEras returns the first such window's Score. Otherwise the run's result is aggregateEras over every window,
 * and its dataset_sha256, seed, action log, trace and stderr are the median window's. exec_count and wall_ms are the
 * windows' sums; the flags the median Score's. Every window runs with the entrant's env-lane entry secrets (the header's
 * `entry secrets`): the run records their rows from its start, each window's row is masked of them, and every graded
 * window's action log is scanned for them before the verdict: a hit flags the run secret_in_output with its
 * SECRET_IN_OUTPUT_ACTION row (each file under its window's key), written once, before finishRun.
 */
async function gradeEras(g: ErasGrade): Promise<{ run_id: string }> {
  const { deps, ctx, ids } = g;
  const { db, blobs } = deps;
  const runId = ctx === undefined ? uuidv7() : agentRunId(ctx.id);
  const mask = entrySecretForms(g.secrets.env);
  await startRun(db, {
    id: runId,
    ...ids,
    imageDigest: deps.sandbox.imageDigest(g.runtime),
    datasetSha256: null,
    harnessVersion: harnessVersion(),
    scorerVersion: scorerVersionOf(g.plan, deps.sandbox),
    seed: null,
    startedAt: new Date(),
    entrySecretIds: g.secrets.ids,
  });

  const done = new Map((await loadEras(db, runId)).map((r) => [r.windowKey, r]));
  const graded: string[] = [];
  const scores: EraWindowScore[] = [];
  /** The window the grade stopped at: what the run takes from it, the window's Score if it has one. */
  let stopped: { key: string; status: GradeOutcome['status']; error: string | null; flags: string[]; score: ScoreT | null } | null = null;
  for (const [i, w] of g.windows.entries()) {
    graded.push(w.key);
    const row = done.get(w.key);
    const kept = row === undefined ? null : keptEraScore(row, w);
    if (kept !== null) {
      if (!kept.eligibility.ranked) {
        stopped = { key: w.key, status: 'finished', error: null, flags: kept.flags, score: kept };
        break;
      }
      scores.push({ key: w.key, score: kept });
      continue;
    }
    ctx?.signal?.throwIfAborted();
    const plan = i === 0 ? g.plan : await eraWindowPlan(g.harness, w, g.load);
    const outcome = await gradeEntry({ ...g.base, plan, runtime: g.runtime, snapshot: g.snapshot, label: `grade-dev-${w.key}` });
    // An attempt given up records nothing more, however far it got: its retry grades the windows not recorded again.
    ctx?.signal?.throwIfAborted();
    await recordEra(db, blobs, runId, eraOfGrade(eraRef(w), outcome), mask);
    if (outcome.status !== 'finished' || outcome.result === null || !outcome.result.eligibility.ranked) {
      stopped = { key: w.key, status: outcome.status, error: outcome.error, flags: outcome.flags, score: outcome.result };
      break;
    }
    scores.push({ key: w.key, score: outcome.result });
  }

  ctx?.signal?.throwIfAborted();
  const rows = (await loadEras(db, runId)).filter((r) => graded.includes(r.windowKey));
  const result = stopped === null ? erasResult(scores, g.hours) : stopped.score;
  const rankKey = stopped !== null ? stopped.key : result?.performance.kind === 'pumpfun-replay/v2' ? result.performance.eras?.rank_window : undefined;
  const rank = rows.find((r) => r.windowKey === rankKey);
  if (rank === undefined) throw new Error(`run ${runId}: no window row for ${rankKey ?? 'a rank window'}`);
  // Every graded window's action log scanned for the secrets it ran with, never masked (the header's `entry secrets`).
  const hits: SecretHit[] = [];
  for (const r of rows) hits.push(...(await secretHitsOfRun(blobs, 'pumpfun-replay/v2', { sha256: r.actionLogSha256 }, g.secrets.env, `${r.windowKey}/`)));
  if (hits.length > 0) {
    (deps.log ?? ((line: string) => console.log(line)))(secretHitsLine(`run ${runId} (submission ${ids.submissionId}'s dev grade on practice windows)`, hits));
    // Written once: a retry of a grade that died after it finds it there.
    const [held] = await db.select({ id: auditEvent.id }).from(auditEvent).where(and(eq(auditEvent.action, SECRET_IN_OUTPUT_ACTION), eq(auditEvent.subjectType, 'run'), eq(auditEvent.subjectId, runId))).limit(1);
    if (held === undefined) await recordSecretHits(db, runId, hits);
  }
  const flags = stopped !== null ? stopped.flags : (result?.flags ?? []);
  await finishRun(db, blobs, runId, {
    status: stopped === null ? 'finished' : stopped.status,
    action_log_json: null,
    action_log_sha256: rank.actionLogSha256,
    result,
    result_sha256: result === null ? null : scoreDigest(result).sha256,
    exec_count: rows.reduce((n, r) => n + r.execCount, 0),
    wall_ms: rows.reduce((n, r) => n + (r.wallMs ?? 0), 0),
    error: stopped === null || stopped.error === null ? null : `window ${stopped.key}: ${stopped.error}`,
    finished_at: new Date(),
    median: {
      dataset_sha256: rank.datasetSha256,
      seed: rank.seed,
      fail_key: publicFailKey(rank.seed),
      flags: hits.length === 0 ? flags : [...new Set([...flags, SECRET_IN_OUTPUT_FLAG])].sort(compareCodeUnits),
      trace_sha256: rank.traceSha256,
      stderr_sha256: rank.stderrSha256,
    },
  });
  return { run_id: runId };
}

/** A Score's flags (performance and execution, sorted), as a window's run_era row holds them: the flags its regrade is given as the window's. */
function eraFlagsOf(result: unknown): string[] {
  const flags = (result as { flags?: unknown } | null)?.flags;
  return Array.isArray(flags) ? flags.filter((f): f is string => typeof f === 'string') : [];
}

/**
 * The windows of an eras run as the regrade takes them: each run_era row (in the order `windows` were built from them,
 * storedEraWindows) a stored run of its own, the public fail key of its seed (a dev phase's), the run's versions and
 * image, and the plan of its own dataset built when the regrade comes to it.
 */
function eraRegradeWindows(stored: StoredRun & RunIds, rows: readonly EraRow[], windows: readonly EraWindow[], harness: PumpHarnessT, load: NonNullable<GradeWorkerDeps['loadDataset']>): ErasRegradeWindow[] {
  return windows.map((w, i) => {
    const row = rows[i]!;
    return {
      ...eraRef(w),
      stored: {
        id: `${stored.id} window ${w.key}`,
        submission_id: stored.submission_id,
        status: row.status,
        harness_version: stored.harness_version,
        scorer_version: stored.scorer_version,
        image_digest: stored.image_digest,
        dataset_sha256: row.datasetSha256,
        seed: row.seed,
        fail_key: publicFailKey(row.seed),
        action_log_sha256: row.actionLogSha256,
        result: row.result,
        result_sha256: row.resultSha256,
        flags: eraFlagsOf(row.result),
        stderr_sha256: row.stderrSha256,
        trace_sha256: row.traceSha256,
      },
      plan: () => eraWindowPlan(harness, w, load),
    };
  });
}

// ---------------------------------------------------------------- entry secrets of an entry's own runs

/**
 * The seal settings an entrant's secrets open with (GradeWorkerDeps.entrySecrets.seal, else the environment's:
 * server/secrets/seal.ts entrySecretSealSettings of loadConfig()), read once, when first asked.
 */
export function entrySecretSealOf(deps: Pick<GradeWorkerDeps, 'entrySecrets'>): () => Promise<EntrySecretSealSettings> {
  let settings: EntrySecretSealSettings | null = null;
  return async () => {
    settings ??= deps.entrySecrets?.seal ?? (await import('../server/secrets/seal.ts')).entrySecretSealSettings(loadConfig());
    return settings;
  };
}

/** An entrant's env-lane entry secrets as a run of its code takes them (the header's `entry secrets`): their rows (ids, in name order) and NAME to value. */
export interface EnvSecrets {
  ids: string[];
  env: Record<string, string>;
}

/** Whose secrets: the entrant's account and the competition. */
interface SecretOwner {
  userId: string;
  competitionId: string;
}

/** No secret. */
function noEnvSecrets(): EnvSecrets {
  return { ids: [], env: {} };
}

/** Rows read for a run, by NAME and row as a message names them, never a value. */
function secretRowsNamed(rows: readonly { id: string; name: string }[]): string {
  return rows.map((r) => `${r.name} (entry_secret ${r.id})`).join(', ');
}

/** An env-lane entry secret this grader could not open: its row, its NAME, and why (the seal's words), never a value. */
export interface UnopenedEnvSecret {
  id: string;
  name: string;
  why: string;
}

/**
 * A grade, a regrade or a heat held on its entrant's env-lane entry secrets (the header's `entry secrets`): some it must
 * run the entry with cannot be opened in this process (no seal private key here, entrySecretSealRefusal's words; or one
 * sealed to a key this grader lacks, or a record that does not open, EntrySecretSealError's), so nothing of the entry
 * runs and nothing is recorded. The platform's key configuration, never the entrant's fault: a retryable Error, never a
 * PermanentJobError, so pg-boss tries the job again (a deploy may bring the key). Its message opens
 * ENTRY_SECRETS_UNOPENED_HOLD_REASON (as server/pipeline/snapshot.ts EntrySecretsHeldError's does), then names `what`,
 * the secrets by NAME and row, and why; never a value. A fresh grade's last attempt throws EntrySecretsHeldFault in its
 * place (createGradeHandler).
 */
export class EntrySecretsUnopenedError extends Error {
  /** The NAMES of the secrets that did not open, in the order read. */
  readonly names: readonly string[];
  constructor(words: string, names: readonly string[]) {
    super(`${ENTRY_SECRETS_UNOPENED_HOLD_REASON}: ${words}`);
    this.name = 'EntrySecretsUnopenedError';
    this.names = [...names];
  }
}

/**
 * A fresh grade still held on its entrant's entry secrets on its job's last attempt (EntrySecretsUnopenedError; the
 * header's `entry secrets`): a PlatformFaultError, so the pipeline's grade stage never fails the entry but puts it back
 * to the status that attempt found it in, its error untouched (server/pipeline/index.ts), and the job dead-letters,
 * paged once by its handler (the header's `dead grade job`: heldGradeJobPage names the keys to mount and the resend).
 * Its message is the hold's.
 */
export class EntrySecretsHeldFault extends PlatformFaultError {
  /** The NAMES of the secrets that did not open (EntrySecretsUnopenedError.names). */
  readonly names: readonly string[];
  constructor(held: EntrySecretsUnopenedError) {
    super(held.message, { cause: held });
    this.name = 'EntrySecretsHeldFault';
    this.names = held.names;
  }
}

/** Whether a job's error (thrown, or as pg-boss keeps its message) is a hold on its entrant's entry secrets. */
function isEntrySecretsHold(err: unknown): boolean {
  if (err instanceof EntrySecretsUnopenedError || err instanceof EntrySecretsHeldFault) return true;
  return typeof err === 'string' && err.startsWith(`${ENTRY_SECRETS_UNOPENED_HOLD_REASON}: `);
}

/**
 * Each of `rows` (env-lane rows server/secrets/store.ts sealedEntrySecretsFor read, in its order) opened with the
 * grader's private keys (server/secrets/seal.ts openEntrySecret): those that open as a run takes them, and every one that
 * does not (sealed to a key this grader lacks, a record that does not open) with the seal's words, never a value. Any
 * other fault is thrown as it is.
 */
async function openEnvRows(privateKeys: EntrySecretSealSettings['privateKeys'], rows: readonly SealedEntrySecretRow[]): Promise<{ opened: EnvSecrets; unopened: UnopenedEnvSecret[] }> {
  const { EntrySecretSealError, openEntrySecret } = await import('../server/secrets/seal.ts');
  const opened = noEnvSecrets();
  const unopened: UnopenedEnvSecret[] = [];
  for (const r of rows) {
    try {
      const value = openEntrySecret(privateKeys, r.sealed, r.aad);
      opened.ids.push(r.id);
      opened.env[r.name] = value;
    } catch (err) {
      // The seal's words never quote a value; anything else is a fault of this process, thrown as it is.
      if (!(err instanceof EntrySecretSealError)) throw err;
      unopened.push({ id: r.id, name: r.name, why: err.message });
    }
  }
  return { opened, unopened };
}

/** Secrets that did not open, as a message names them: each cause's rows by NAME and row, then the cause ("A (entry_secret x), B (entry_secret y): why; C (entry_secret z): why"). */
function unopenedNamed(unopened: readonly UnopenedEnvSecret[]): string {
  const byWhy = new Map<string, UnopenedEnvSecret[]>();
  for (const u of unopened) byWhy.set(u.why, [...(byWhy.get(u.why) ?? []), u]);
  return [...byWhy].map(([why, rows]) => `${secretRowsNamed(rows)}: ${why}`).join('; ');
}

/**
 * The env-lane entry secrets a fresh grade of `who`'s entry runs with (the header's `entry secrets`): the account's active
 * ones in the competition (server/secrets/store.ts sealedEntrySecretsFor), opened with the grader's private keys; never
 * the provider lane's (no sandbox but an agent/v1 forwarder's holds a provider key). None pushed: none, and no key read.
 * Any this grader cannot open (no private key here, a seal it lacks) holds the grade: EntrySecretsUnopenedError naming
 * every one that did not open by NAME and row, and why, never a value; the job is retried, the entry never graded
 * without them and never failed for them.
 */
export async function activeEnvSecrets(db: Pick<Db, 'select'>, seal: () => Promise<EntrySecretSealSettings>, who: SecretOwner, what: string): Promise<EnvSecrets> {
  const [{ entrySecretSealRefusal }, { sealedEntrySecretsFor }] = await Promise.all([import('../server/secrets/seal.ts'), import('../server/secrets/store.ts')]);
  const rows = (await sealedEntrySecretsFor(db, who)).secrets.filter((r) => r.lane === 'env');
  if (rows.length === 0) return noEnvSecrets();
  const settings = await seal();
  const off = entrySecretSealRefusal(settings, 'open');
  if (off !== null) {
    throw new EntrySecretsUnopenedError(
      `${what}: the env-lane entry secrets its entrant pushed (${secretRowsNamed(rows)}) cannot be opened here, so it is not graded without them (its job tries again): ${off}`,
      rows.map((r) => r.name),
    );
  }
  const { opened, unopened } = await openEnvRows(settings.privateKeys, rows);
  if (unopened.length > 0) {
    const which =
      unopened.length === 1
        ? 'an env-lane entry secret its entrant pushed cannot be opened here, so it is not graded without it'
        : `${unopened.length} env-lane entry secrets its entrant pushed cannot be opened here, so it is not graded without them`;
    throw new EntrySecretsUnopenedError(
      `${what}: ${which} (its job tries again): ${unopenedNamed(unopened)}`,
      unopened.map((u) => u.name),
    );
  }
  return opened;
}

/**
 * The env-lane entry secrets of rows `ids` a run recorded (run.entry_secret_ids, run_trial.entry_secret_ids), for a run of
 * the entry again (the header's `entry secrets`): exactly those rows, retained ones included, the provider lane's left
 * out, opened as the run opened them. `opened`: the rows still held, opened (`secrets`), and `erased` the rows whose
 * ciphertext is gone since (replaced, deleted, purged, or no row of `who`'s: by NAME and row; null when none is).
 * `unopened`: this grader cannot open the rows held (`off`: no private key here, entrySecretSealRefusal's words, every
 * held row's NAME in `names`; `seal`: those it cannot open, each by NAME and row with EntrySecretSealError's words, their
 * NAMES in `names`), `erased` beside it alike. No value in any word.
 */
export async function recordedEnvSecrets(
  db: Pick<Db, 'select'>,
  seal: () => Promise<EntrySecretSealSettings>,
  who: SecretOwner,
  ids: readonly string[] | null | undefined,
): Promise<{ kind: 'opened'; secrets: EnvSecrets; erased: string | null } | { kind: 'unopened'; cause: 'off' | 'seal'; why: string; names: string[]; erased: string | null }> {
  const asked = [...new Set(ids ?? [])];
  if (asked.length === 0) return { kind: 'opened', secrets: noEnvSecrets(), erased: null };
  const [{ entrySecretSealRefusal }, { sealedEntrySecretsFor }] = await Promise.all([import('../server/secrets/seal.ts'), import('../server/secrets/store.ts')]);
  const lanes = await db.select({ id: entrySecret.id, name: entrySecret.name, lane: entrySecret.lane }).from(entrySecret).where(inArray(entrySecret.id, asked));
  // A row that is not there (or not a uuid) is no provider key: asked for, and named erased by the read.
  const envIds = asked.filter((id) => lanes.find((r) => r.id === id)?.lane !== 'provider');
  if (envIds.length === 0) return { kind: 'opened', secrets: noEnvSecrets(), erased: null };
  const read = await sealedEntrySecretsFor(db, { ...who, ids: envIds });
  const erased = read.erased.length === 0 ? null : read.erased.map((id) => `${lanes.find((r) => r.id === id)?.name ?? 'a secret'} (entry_secret ${id})`).join(', ');
  if (read.secrets.length === 0) return { kind: 'opened', secrets: noEnvSecrets(), erased };
  const settings = await seal();
  const off = entrySecretSealRefusal(settings, 'open');
  if (off !== null) return { kind: 'unopened', cause: 'off', why: off, names: read.secrets.map((r) => r.name), erased };
  const { opened, unopened } = await openEnvRows(settings.privateKeys, read.secrets);
  if (unopened.length > 0) return { kind: 'unopened', cause: 'seal', why: unopenedNamed(unopened), names: unopened.map((u) => u.name), erased };
  return { kind: 'opened', secrets: opened, erased };
}

/**
 * Of rows `ids` a final-phase run of `who`'s entry opened and is recording (run.entry_secret_ids,
 * run_trial.entry_secret_ids: the header's `entry secrets`), the env-lane ones whose ciphertext is gone since (replaced,
 * deleted or purged), by NAME and row; null when every one still holds it. A provider-lane row is never re-opened (a
 * replay runs on no key), so never asked about. Read in the caller's transaction, after it wrote the ids, under `who`'s
 * account lock: FOR SHARE on the user row, which server/secrets/store.ts's push and delete take FOR NO KEY UPDATE before
 * they read which rows a final run recorded (finalRecorded). A delete holding the lock first has committed by the time
 * this reads (its erasure is seen here); one coming after waits for the caller's commit, then reads the run and keeps
 * the row sealed for the challenge's re-run. No value in any word.
 */
export async function erasedSinceOpened(tx: Pick<Db, 'select'>, who: SecretOwner, ids: readonly string[] | null | undefined): Promise<string | null> {
  const asked = [...new Set(ids ?? [])];
  if (asked.length === 0) return null;
  await tx.select({ id: user.id }).from(user).where(eq(user.id, who.userId)).for('share');
  const lanes = await tx.select({ id: entrySecret.id, name: entrySecret.name, lane: entrySecret.lane }).from(entrySecret).where(inArray(entrySecret.id, asked));
  const envIds = asked.filter((id) => lanes.find((r) => r.id === id)?.lane !== 'provider');
  if (envIds.length === 0) return null;
  const { sealedEntrySecretsFor } = await import('../server/secrets/store.ts');
  const read = await sealedEntrySecretsFor(tx, { ...who, ids: envIds });
  return read.erased.length === 0 ? null : read.erased.map((id) => `${lanes.find((r) => r.id === id)?.name ?? 'a secret'} (entry_secret ${id})`).join(', ');
}

/**
 * Record a final-phase run that ran its entry with env-lane rows `ids` (the header's `entry secrets`): `write` writes it
 * in a transaction (record.ts recordGrade, handed it as its Db, nests its own), then every row it names must still hold
 * its ciphertext under the entrant's account lock (erasedSinceOpened), so a delete or replace either sees the run and
 * keeps the row for the challenge's re-run or came first. One erased while the run ran rolls the write back: a
 * retryable Error naming it by NAME (`what` the run), never a value, and the job runs the entry again with the secrets
 * as they stand. With no ids, `write` writes on `db` as ever.
 */
export async function recordWithSecretsHeld<T>(db: Db, who: SecretOwner, ids: readonly string[], what: string, write: (db: Db) => Promise<T>): Promise<T> {
  if (ids.length === 0) return write(db);
  return db.transaction(async (tx) => {
    const out = await write(tx as unknown as Db);
    const erased = await erasedSinceOpened(tx, who, ids);
    if (erased !== null) {
      throw new Error(
        `${what} ran with an env-lane entry secret its entrant removed or replaced while it ran, whose sealed copy is erased (${erased}): its run is not recorded, since a challenge's re-run could never open it, and its job runs it again with the secrets as they stand`,
      );
    }
    return out;
  });
}

/** The file a scan names a run's action log by (record.ts SecretHit.file); an output is `output/<path>`. */
export const ACTION_LOG_SCAN_FILE = 'action-log.json';

/** The NAMEs whose forms occur in a byte stream, read chunk by chunk with the last (longest pattern − 1) bytes carried over, so no occurrence is cut. */
async function secretNamesIn(stream: AsyncIterable<Uint8Array>, index: FormIndex): Promise<Set<string>> {
  const { findForms } = await import('./gateway/secret-mask.ts');
  let longest = 0;
  for (const p of index.patterns) longest = Math.max(longest, Buffer.byteLength(p, 'utf8'));
  const names = new Set<string>();
  let carry = Buffer.alloc(0);
  for await (const chunk of stream) {
    const buf = carry.length === 0 ? Buffer.from(chunk) : Buffer.concat([carry, chunk]);
    for (const hit of findForms(buf, index, { limit: 1 })) names.add(hit.name);
    carry = Buffer.from(buf.subarray(Math.max(0, buf.length - Math.max(0, longest - 1))));
  }
  return names;
}

/**
 * Where a run graded as one execution holds a form of the entry secrets it ran with (the header's `entry secrets`), by
 * NAME and file, never the value, and never masked (they are scored byte for byte): its canonical action log
 * (ACTION_LOG_SCAN_FILE: `log.json` when the caller holds it, else blob `log.sha256`) and, on program/v1, every output
 * file the log lists (`output/<path>`), read from the blob store as stored. `prefix` goes before each file (an eras
 * window's key). Hits in file order, then name order; none with no secret or no log.
 */
export async function secretHitsOfRun(
  blobs: Pick<BlobStore, 'get' | 'openRead'>,
  kind: HarnessT['kind'],
  log: { json?: string | null; sha256: string | null },
  env: Readonly<Record<string, string>>,
  prefix = '',
): Promise<SecretHit[]> {
  const held = log.json === undefined || log.json === null ? null : log.json;
  if (Object.keys(env).length === 0 || (held === null && log.sha256 === null)) return [];
  const { secretScanIndex } = await import('./agent.ts');
  const index = secretScanIndex(env);
  if (index.patterns.length === 0) return [];
  let json = held;
  if (json === null) {
    const bytes = await blobs.get(log.sha256!, { verify: true });
    if (bytes === null) throw new Error(`action log ${log.sha256} is missing from the blob store, so its outputs cannot be scanned for the entry's secrets`);
    json = Buffer.from(bytes).toString('utf8');
  }
  const sorted = (names: Iterable<string>) => [...names].sort(compareCodeUnits);
  const { findForms } = await import('./gateway/secret-mask.ts');
  const hits: SecretHit[] = [];
  for (const name of sorted(new Set(findForms(json, index, { limit: 1 }).map((h) => h.name)))) hits.push({ name, file: `${prefix}${ACTION_LOG_SCAN_FILE}` });
  if (kind === 'program/v1') {
    const { ProgramOutputs } = await import('./program.ts');
    const outputs = ProgramOutputs.parse(JSON.parse(json));
    for (const f of outputs.files) {
      for (const name of sorted(await secretNamesIn(await blobs.openRead(f.sha256), index))) hits.push({ name, file: `${prefix}output/${f.path}` });
    }
  }
  return hits;
}

/**
 * What a regrade run records of the entry secrets (record.ts recordRegrade's RunSecrets; the header's `entry secrets`): an
 * L2 the rows it re-executed the entry with, or, refused because one is erased (`erased`), the rows its run recorded,
 * which it would have run with; its stderr and error masked of their values. An L1 runs nothing: none.
 */
function l2Secrets(kind: JobPayload<'grade-dev'>['kind'], stored: Pick<StoredRun, 'entry_secret_ids'>, secrets: EnvSecrets, erased: string | undefined, forms: FormSet | null): Pick<RunSecrets, 'entry_secret_ids' | 'mask'> {
  if (kind !== 'regrade_l2') return {};
  return { entry_secret_ids: erased === undefined ? secrets.ids : (stored.entry_secret_ids ?? []), mask: forms };
}

/** A log line naming a run's outputs that held entry secrets, by NAME and file, never a value. */
function secretHitsLine(what: string, hits: readonly SecretHit[]): string {
  const names = [...new Set(hits.map((h) => h.name))].join(', ');
  const files = [...new Set(hits.map((h) => h.file))].join(', ');
  return `[grade] ${what}: its outputs hold a form of entry secret ${names} (${files}), never masked: its run is flagged ${SECRET_IN_OUTPUT_FLAG}`;
}

/** The final grades' live feed of each database in this process (finalGradeLanded): one gap per competition, whichever job lands the grade. */
const gradeLives = new WeakMap<object, Promise<GradeLive>>();

/**
 * Tell the live board a grade run of competition `competitionId`'s final phase landed (server/competitions/
 * live-judging.ts openGradeLive: a live change on its `phase` topic, kind `grade`, at most one per JUDGE_LIVE_MIN_GAP_MS
 * a competition, one inside the gap recorded at its end), so a page holding the live stream reads GET /live again and
 * its judging's grades move (the run's own `standings` change, record.ts GRADE_CHANGE, moves only the leaderboard).
 * Never throws: the grade stands whatever becomes of the change, and what fails is logged.
 */
async function finalGradeLanded(db: Db, competitionId: string, log: (line: string) => void): Promise<void> {
  try {
    let feed = gradeLives.get(db);
    if (feed === undefined) {
      feed = import('../server/competitions/live-judging.ts').then((m) => m.openGradeLive({ db, log }));
      gradeLives.set(db, feed);
      feed.catch(() => gradeLives.delete(db));
    }
    await (await feed).landed(competitionId);
  } catch (err) {
    log(`[grade] the final grades' live change on competition ${competitionId} could not be recorded (${err instanceof Error ? err.message : String(err)}): the live board shows them at its next read`);
  }
}

// ---------------------------------------------------------------- referral/v1: the count is the score

/** How long a referral/v1 final grade with a still-undecided sign-up waits before it is sent again (the metered pattern: REFERRAL_GRADE_RESEND_MS). */
export const REFERRAL_GRADE_RESEND_MS = 60_000;

/** The grade job a referral/v1 final grade `gradeJobId` sends itself again as while a sign-up is undecided: one per job, so a retried attempt sends it once. */
export function referralHoldJobId(gradeJobId: string): string {
  return sha256Uuid(`referral-hold\0${gradeJobId.toLowerCase()}`);
}

/** One sign-up of the entrant's in the contest window, as its action log records it (grader/score.ts ReferralActionLog.signups). */
interface ReferralSignupFact {
  referral_id: string;
  counted: boolean;
  why: string | null;
}

/** What a referral/v1 grade job reads besides GradeWorkerDeps' own: the job, its entry, phase and competition, and the hand-on. */
interface ReferralGradeStart {
  deps: GradeWorkerDeps;
  ctx: GradeJobContext | undefined;
  job: JobPayload<'grade-dev'>;
  sub: typeof submission.$inferSelect;
  ph: typeof phase.$inferSelect;
  comp: typeof competition.$inferSelect;
  bundle: CompetitionBundleT;
  handedOn: (() => void) | undefined;
}

/** Why a sign-up the contest does not count did not count, as its log's `why`: the live reward's state first, then the cached verdict's. */
function referralUncountedWhy(row: { rewardStatus: string | null; verdict: string | null; rule: string | null; why: string | null }): string {
  if (row.rewardStatus === 'pending') return REFERRAL_CONTEST_REWARD_PENDING_WHY;
  if (row.rewardStatus === 'rejected') return 'its sign-up reward was rejected';
  if (row.rewardStatus !== null) return `its sign-up reward is ${row.rewardStatus}`;
  if (row.verdict === 'unverified') return row.rule === null ? 'the referral rules do not count it' : `the referral rules do not count it (${row.rule})`;
  if (row.verdict === 'undecided') return row.why ?? 'undecided at the check';
  return 'no verdict: an undecided sign-up never counts';
}

/**
 * Every referral of `referrerUserId` bound inside the contest's window, in binding order, each as its action log
 * records it: counted by the referral contest's own rule (a live sign-up reward approved, claimed or paid, or a cached
 * 'verified' verdict with no reward row; server/referrals/contest.ts verifiedSignupSql's predicate), and, when it does
 * not count, why. Read-only: the grade never decides a referral (the referral-contest sweep does) and never caches one.
 */
async function referralSignupFactsOf(
  db: Db,
  input: { competitionId: string; referrerUserId: string; opensAt: Date; deadline: Date },
): Promise<ReferralSignupFact[]> {
  const rows = await db
    .select({
      id: referral.id,
      rewardStatus: referralReward.status,
      verdict: referralContestVerdict.verdict,
      rule: referralContestVerdict.rule,
      why: referralContestVerdict.why,
    })
    .from(referral)
    .leftJoin(referralReward, and(eq(referralReward.referralId, referral.id), eq(referralReward.kind, 'signup')))
    .leftJoin(referralContestVerdict, and(eq(referralContestVerdict.referralId, referral.id), eq(referralContestVerdict.competitionId, input.competitionId)))
    .where(and(eq(referral.referrerUserId, input.referrerUserId), gte(referral.createdAt, input.opensAt), lte(referral.createdAt, input.deadline)))
    .orderBy(asc(referral.createdAt), asc(referral.id));
  return rows.map((row) => {
    const counted = row.rewardStatus === 'approved' || row.rewardStatus === 'claimed' || row.rewardStatus === 'paid' || (row.rewardStatus === null && row.verdict === 'verified');
    return { referral_id: row.id, counted, why: counted ? null : referralUncountedWhy(row) };
  });
}

/**
 * Hand a referral/v1 final grade on while one of its sign-ups is still undecided and the phase has time left (the
 * metered pattern): the job is sent again on its own queue for REFERRAL_GRADE_RESEND_MS on (at the phase's end at the
 * latest) at the priority it came at, `handedOn` is told, and nothing is graded or recorded now. At the phase's end the
 * grade counts what is decided: an undecided sign-up never counts. With no queue to send it on, a retryable Error.
 */
async function referralHandOn(s: ReferralGradeStart, input: { now: Date; endsAt: Date; undecided: number }): Promise<null> {
  const { deps, ctx, job, ph, comp, sub } = s;
  const when = new Date(Math.min(input.now.getTime() + REFERRAL_GRADE_RESEND_MS, input.endsAt.getTime()));
  const what = `submission ${sub.id}'s final grade counts its referrals once every sign-up in ${comp.slug}'s window is decided (${input.undecided} still undecided), or the phase ends at ${input.endsAt.toISOString()} at the latest`;
  if (deps.jobs === undefined) throw new Error(`${what}, and this process has no queue to send the grade on for then: the job retries`);
  const queue = ctx?.queue === 'grade-dev' || ctx?.queue === 'grade-final' ? ctx.queue : gradeQueue(ph.key);
  const id = referralHoldJobId(ctx?.id ?? uuidv7());
  await deps.jobs.send(queue, job, { id, startAfter: when, ...(ctx?.priority === undefined ? {} : { priority: ctx.priority }) });
  s.handedOn?.();
  (deps.log ?? ((line: string) => console.log(line)))(`[grade] ${what}: sent again on ${queue} for ${when.toISOString()} (job ${id}); nothing is graded now`);
  return null;
}

/**
 * The referral/v1 grade job (the header's `referral/v1`): a fresh grade reads the entry's sign-ups inside the contest's
 * window (referralSignupFactsOf), records them as the run's action log (grader/score.ts ReferralActionLog) and scores
 * that log (buildScore counts its counted sign-ups), so the score is a pure function of the evidence the run stores.
 * Nothing runs: no sandbox, no runtime and no snapshot is read (only its presence checked), and no pod is held. A final
 * grade with a still-undecided sign-up and time left in the phase hands itself on (referralHandOn) so it never counts
 * one that could still be verified; an undecided sign-up at the phase's end never counts. Its L1 regrade re-scores the
 * stored log (regrade.ts regradeReferralL1); its L2 is refused (REFERRAL_L2_REFUSAL), as a count is the facts at the
 * grade's read.
 */
async function gradeReferral(s: ReferralGradeStart): Promise<{ run_id: string } | null> {
  if (s.job.kind === 'regrade_l2') throw new PermanentJobError(REFERRAL_L2_REFUSAL);
  if (s.job.kind === 'regrade_l1') return { run_id: await regradeReferralRun(s) };
  const { deps, sub, ph, comp, bundle } = s;
  const { db, blobs } = deps;
  // A referral entry's snapshot is its ad page and image (the intake checks read it); the grade reads no file of it,
  // and no entry without one is taken in (server/routes/admin/grading.ts takenInCandidatesWhere).
  if (sub.snapshotSha256 === null) throw new PermanentJobError(`submission ${sub.id} has no snapshot yet`);
  const now = deps.now?.() ?? new Date();
  const undecided = await undecidedContestReferralsOf(db, { competitionId: comp.id, referrerUserId: sub.userId });
  // A final grade waits out a still-undecided sign-up while the phase has time left (referralHandOn); a dev grade counts
  // at once, its board showing the count as it lands (`scores: live`), and the referral-contest sweep sends it afresh
  // when a verdict moves the count.
  if (ph.key === 'final' && undecided.length > 0 && ph.endsAt !== null && now.getTime() < ph.endsAt.getTime()) {
    return referralHandOn(s, { now, endsAt: ph.endsAt, undecided: undecided.length });
  }
  const signups = await referralSignupFactsOf(db, { competitionId: comp.id, referrerUserId: sub.userId, opensAt: comp.opensAt, deadline: comp.deadline });
  const log: ReferralActionLogT = { version: 1, referrer_user_id: sub.userId, signups, verified_signups: signups.filter((x) => x.counted).length };
  // The same facts through the count the sweep reads: a verdict decided between the two reads is a race, and the job
  // tries again for a log that holds (an inconsistent log would be refused by buildScore anyway).
  const counts = (await verifiedSignupCountsOf(db, { competitionId: comp.id, referrerUserIds: [sub.userId] })).get(sub.userId) ?? { verified: 0, signups: 0 };
  if (counts.verified !== log.verified_signups || counts.signups !== signups.length) {
    throw new Error(
      `submission ${sub.id}'s referral count moved while its action log was read (${counts.verified} verified of ${counts.signups}, the log holds ${log.verified_signups} of ${signups.length}): the job tries again for a count that holds`,
    );
  }
  const actionLogJson = canonicalJson(log);
  const result = buildScore(
    {
      harness: { kind: 'referral/v1', version: harnessVersion() },
      image_digest: null,
      dataset_sha256: REFERRAL_DATASET_SHA256,
      seed: REFERRAL_SEED,
      deterministic: true,
      execution_flags: [],
      house: standingsHouse(sub),
      baseline: sub.baseline,
    },
    { action_log_sha256: sha256Hex(actionLogJson), performance: referralPerformanceOf(log), referral_log: log, performance_flags: [], cost: REFERRAL_COST, authorship: null },
    eligibilityRulesOf(bundle),
    scorerVersion(),
  );
  // An attempt given up records nothing: its retry grades again and records once.
  s.ctx?.signal?.throwIfAborted();
  const runId = await recordGrade(
    db,
    blobs,
    {
      status: 'finished',
      error: null,
      executions: [],
      action_log_json: actionLogJson,
      action_log_sha256: sha256Hex(actionLogJson),
      result,
      result_sha256: scoreDigest(result).sha256,
      trace_json: null,
      trace_sha256: null,
      flags: [],
      wall_ms: 0,
      stderr: Buffer.alloc(0),
      image_digest: null,
      harness_version: harnessVersion(),
      scorer_version: scorerVersion(),
      dataset_sha256: REFERRAL_DATASET_SHA256,
      seed: REFERRAL_SEED,
      fail_key: null,
      exec_count: 0,
      started_at: now,
      finished_at: now,
    },
    { submissionId: sub.id, phaseId: ph.id },
  );
  // A final grade moves the live board's grades count (finalGradeLanded): the page reads /live again.
  if (ph.key === 'final') await finalGradeLanded(db, comp.id, deps.log ?? ((line: string) => console.log(line)));
  return { run_id: runId };
}

/** A referral/v1 L1 regrade job (gradeReferral): the stored grade run re-scored from its action log (regrade.ts regradeReferralL1), recorded as a regrade run. */
async function regradeReferralRun(s: ReferralGradeStart): Promise<string> {
  const { deps, job, sub, ph, bundle } = s;
  const { db, blobs } = deps;
  const stored = await loadStoredRun(db, job.reproduces_run_id!);
  if (stored === null) throw new PermanentJobError(`run ${job.reproduces_run_id} does not exist`);
  if (stored.submissionId !== sub.id || stored.phaseId !== ph.id) throw new PermanentJobError(`run ${stored.id} is not a run of submission ${sub.id} in phase ${ph.id}`);
  const [orig] = await db.select({ kind: run.kind }).from(run).where(eq(run.id, stored.id));
  if (orig?.kind !== 'grade') throw new PermanentJobError(`run ${stored.id} is a ${orig?.kind}; regrade the grade run it reproduces`);
  try {
    const outcome = await regradeReferralL1({ stored, blobs, rules: eligibilityRulesOf(bundle), entry: { house: standingsHouse(sub), baseline: sub.baseline }, startedAt: deps.now?.() ?? new Date() });
    // The re-score runs to its end (a referral/v1 L1 takes no signal), and an attempt given up meanwhile records nothing.
    s.ctx?.signal?.throwIfAborted();
    return await recordRegrade(db, blobs, outcome, { submissionId: sub.id, phaseId: ph.id });
  } catch (err) {
    if (err instanceof RegradeError) throw new PermanentJobError(err.message, { cause: err });
    throw err;
  }
}

/**
 * The grade job handler (see the header). Handed the job's context (JobQueue.work's), it pages the job
 * should it die for good; with or without one, every job first sweeps the grade jobs that died before
 * it (the header's `dead grade job`). `handedOn`, when given, is told when the job, instead of grading,
 * has sent itself again to grade later (the header's `metered`): it answers null with nothing graded,
 * and the pipeline's grade stage marks the job so nothing is sent after it (server/pipeline/index.ts,
 * server/jobs.ts PipelineHandlers.gradeHandedOn).
 */
export function createGradeHandler(deps: GradeWorkerDeps): (job: JobPayload<'grade-dev'>, ctx?: GradeJobContext, handedOn?: () => void) => Promise<{ run_id: string } | null> {
  const { db, blobs } = deps;
  const loadDataset = deps.loadDataset ?? createDatasetLoader();
  const loadBarsDataset = deps.loadBarsDataset ?? createBarsDatasetLoader();
  const loadClmmDataset = deps.loadClmmDataset ?? createClmmDatasetLoader();
  const loadAuthorship = deps.loadAuthorship ?? ((submissionId: string, pricingRev: string, algoVersion?: number) => loadStoredAuthorship(db, submissionId, pricingRev, algoVersion));
  const dead = createDeadGradeJobPager(deps);
  const failKeyPaged = failKeyPager(deps, '[grade]');
  const sealOf = entrySecretSealOf(deps);
  const grade = async (job: JobPayload<'grade-dev'>, ctx: GradeJobContext | undefined, handedOn: (() => void) | undefined): Promise<{ run_id: string } | null> => {
    const sub = await one(db.select().from(submission).where(eq(submission.id, job.submission_id)), `submission ${job.submission_id}`);
    const ph = await one(db.select().from(phase).where(eq(phase.id, job.phase_id)), `phase ${job.phase_id}`);
    if (ph.competitionId !== sub.competitionId) throw new PermanentJobError(`phase ${ph.id} is not a phase of submission ${sub.id}'s competition`);
    const comp = await one(db.select().from(competition).where(eq(competition.id, sub.competitionId)), `competition ${sub.competitionId}`);
    if (comp.bundle === null) throw new PermanentJobError(`competition ${comp.slug} has no bundle (a demo row cannot be graded)`);
    let bundle: CompetitionBundleT;
    try {
      bundle = CompetitionBundle.parse(comp.bundle);
    } catch (err) {
      throw new PermanentJobError(`competition ${comp.slug}'s stored bundle does not validate`, { cause: err });
    }
    // An admin's provisional rejudge of a kept dev run (the header's `provisional rejudge`): it runs no program and
    // records no run, only the run's verdict judged again, so it hands nothing on (no publish).
    if (job.rejudge !== undefined) {
      await rejudgeProvisional(deps, { job, sub, ph, comp, bundle, ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }) });
      return null;
    }
    // A referral/v1 entry (contracts/competition.ts ReferralHarness) is checked, never run: its score is the verified
    // sign-ups its submitter brought, read from the referral contest's facts and recorded as the run's action log
    // (gradeReferral, the header's `referral/v1`). No sandbox, runtime or snapshot materialization is read, so it
    // branches before every sandbox path below and before the snapshot read (it holds the entry to a snapshot itself:
    // the entry set and awaitingSnapshot take only snapshotted entries, and its ad page and image are that snapshot).
    if (bundle.harness.kind === 'referral/v1') return gradeReferral({ deps, ctx, job, sub, ph, comp, bundle, handedOn });
    if (sub.snapshotSha256 === null) throw new PermanentJobError(`submission ${sub.id} has no snapshot yet`);
    // A fresh final grade under a build meter prices only once masq has settled the requests it counts (the header's
    // `metered`): sooner, the job is sent again for then, and hands on nothing (`handedOn` told). A dev grade prices at once.
    if (job.kind === 'grade' && bundle.build_meter !== undefined && ph.key !== 'dev' && (await meteredSettleWait(deps, { sub, ph, job, ctx, handedOn })) !== null) return null;
    const index = await readSnapshotIndex(blobs, sub.snapshotSha256);
    const competitionKey = competitionSeedKey(comp);

    // A scrape entry grades in a heat of timed trials (the header's `scrape/v1`): on dev its practice heat beside the
    // house baseline (alone where the heat is staged), on the final phase the phase's one heat (createScrapeHeatHandler), whose run this job hands on.
    // Its L1 regrade re-judges the record; an L2 is refused: the measurement is never re-run.
    if (bundle.harness.kind === 'scrape/v1') {
      if (job.kind === 'regrade_l2') throw new PermanentJobError(SCRAPE_L2_REFUSAL);
      const scrape: ScrapeGradeStart = { deps, ctx, sub, ph, comp: { id: comp.id, slug: comp.slug, createdAt: comp.createdAt }, bundle, harness: bundle.harness, index, competitionKey, loadAuthorship };
      if (job.kind === 'regrade_l1') {
        // It waits out a heat under the `host` lease scope only (the header's `scrape/v1`).
        await scrapeHostQuiet(deps, `run ${job.reproduces_run_id}'s regrade_l1 regrade`, ctx?.signal);
        return regradeScrapeRun({ ...scrape, job });
      }
      return ph.key === 'dev' ? gradeScrapePractice(scrape) : scrapeFinalGrade(scrape);
    }
    // While a scrape heat holds this host (its lease), no other grading runs here under the `host` lease scope; under
    // `egress` this does not wait (the header's `scrape/v1`).
    await scrapeHostQuiet(deps, job.kind === 'grade' ? `submission ${sub.id}'s grade on the ${ph.key} phase` : `run ${job.reproduces_run_id}'s ${job.kind} regrade`, ctx?.signal);

    // An agent entry grades as K trials, run by jobs of their own (the header's `agent/v1`): the job starts the run.
    // Its regrade re-derives a stored run from its trials (regrade.ts regradeAgentL1, regradeAgentL2).
    if (bundle.harness.kind === 'agent/v1') {
      const agent = { deps, ctx, sub, ph, comp: { id: comp.id, slug: comp.slug, createdAt: comp.createdAt }, bundle, harness: bundle.harness, index, competitionKey };
      if (job.kind === 'grade') return startAgentRun(agent);
      return regradeAgentRun({ ...agent, job, loadAuthorship });
    }

    // A regrade re-derives a stored grade run, under the seed that run recorded.
    let stored: Awaited<ReturnType<typeof loadStoredRun>> = null;
    if (job.kind !== 'grade') {
      stored = await loadStoredRun(db, job.reproduces_run_id!);
      if (stored === null) throw new PermanentJobError(`run ${job.reproduces_run_id} does not exist`);
      if (stored.submissionId !== sub.id || stored.phaseId !== ph.id) throw new PermanentJobError(`run ${stored.id} is not a run of submission ${sub.id} in phase ${ph.id}`);
      const [orig] = await db.select({ kind: run.kind }).from(run).where(eq(run.id, stored.id));
      if (orig?.kind !== 'grade') throw new PermanentJobError(`run ${stored.id} is a ${orig?.kind}; regrade the grade run it reproduces`);
      if (stored.seed === null) throw new PermanentJobError(`run ${stored.id} recorded no seed`);
    }

    /** A replay phase's dataset row and its frozen files, through `load`, checked against the row. */
    const phaseDataset = async <T extends { dataset: { sha256: string } }>(load: (row: DatasetRow) => Promise<T>): Promise<{ ds: DatasetRow; loaded: T }> => {
      if (ph.datasetId === null) throw new PermanentJobError(`phase ${ph.key} of ${comp.slug} has no dataset attached`);
      const ds = await one(db.select().from(dataset).where(eq(dataset.id, ph.datasetId)), `dataset ${ph.datasetId}`);
      let loaded: T;
      try {
        loaded = await load(ds);
      } catch (err) {
        if (err instanceof DatasetIntegrityError) throw new PermanentJobError(`dataset ${ds.slug}: ${err.message}`, { cause: err });
        throw err;
      }
      if (loaded.dataset.sha256 !== ds.sha256) throw new PermanentJobError(`dataset ${ds.slug} loads as ${loaded.dataset.sha256}, not its recorded ${ds.sha256}`);
      return { ds, loaded };
    };

    // A dev phase on practice windows grades every window (gradeEras), and a regrade of a run that did follows its run_era rows (eraRegradeWindows).
    // The plan built here is the first window's: what the run takes its versions and runtimes from, window by window the same.
    const practice = stored === null ? practiceWindowsOf(bundle, ph.key) : null;
    const storedEras = stored === null ? [] : await loadEras(db, stored.id);
    let eras: { harness: PumpHarnessT; windows: EraWindow[] } | null = null;
    let plan: HarnessPlan;
    if (practice !== null) {
      const windows = await attachedEraWindows(db, ph.id, practice.windows, competitionKey);
      eras = { harness: practice.harness, windows };
      plan = await eraWindowPlan(practice.harness, windows[0]!, loadDataset);
    } else if (storedEras.length > 0) {
      if (bundle.harness.kind !== 'pumpfun-replay/v2') throw new PermanentJobError(`run ${stored!.id} has practice windows, and ${comp.slug}'s harness is ${bundle.harness.kind}`);
      const windows = await storedEraWindows(db, storedEras);
      eras = { harness: bundle.harness, windows };
      plan = await eraWindowPlan(bundle.harness, windows[0]!, loadDataset);
    } else if (bundle.harness.kind === 'pumpfun-replay/v2') {
      const { ds, loaded } = await phaseDataset(loadDataset);
      const receipt = ph.key === 'final' ? await lastReceiptAt(db, comp.id) : null;
      // The phase that races live on fail-key scheme server-secret/v1 is seeded as its race seeds every racer's hello (the
      // header's `seed`: gradeTakesRaceSeed); on any other scheme (a sealed-window final committed at its deadline) it keeps
      // its dataset part, the seed its commitment holds every final run to; a regrade keeps its run's. raceSeed loads only
      // then: server/race/entries.ts reaches the admin routes and better-auth, which no other grade, nor any CLI importing
      // this file, should load.
      const seed = stored?.seed ?? (gradeTakesRaceSeed(bundle, ph) ? (await import('../server/race/entries.ts')).raceSeed(comp, ph.key) : phaseSeed(competitionKey, ph.key, ds.sha256));
      // By the phase's scheme (the header's `fail key`); a regrade keeps the key its run was graded with.
      const failKey =
        stored?.fail_key ??
        (await failKeyPaged(stored === null ? `${comp.slug}: submission ${sub.id}'s grade on the ${ph.key} phase` : `${comp.slug}: run ${stored.id}'s ${job.kind} regrade`, () =>
          phaseFailKey({
            phase: ph,
            slug: comp.slug,
            seed,
            datasetSha256: ds.sha256,
            compDir: competitionDirOf(deps, comp.slug, bundle.harness),
            sealedDir: deps.sealedDir ?? sealedDirFromEnv(),
            chain: instanceChainOptions(deps.drandChain),
            serverSecret: () => deps.failKeySecret ?? defaultFailKeySecret(),
          }),
        ));
      plan = replayPlan({
        harness: bundle.harness,
        dataset: loaded.dataset,
        sample: loaded.sample,
        seed,
        failKey,
        finalWindow: receipt === null ? null : { last_graded_receipt_at: receipt },
      });
    } else if (bundle.harness.kind === 'bars-replay/v1') {
      // Every phase of a bars competition grades on a frozen bars window, dev included.
      const { ds, loaded } = await phaseDataset(loadBarsDataset);
      const receipt = ph.key === 'final' ? await lastReceiptAt(db, comp.id) : null;
      // The phase that races live is seeded as its race seeds every racer's hello (the header's `seed`); a regrade keeps its
      // run's. raceSeed loads only then: server/race/entries.ts reaches the admin routes and better-auth, which no other
      // grade, nor any CLI importing this file, should load.
      const seed = stored?.seed ?? (racesLive(bundle, ph.key) ? (await import('../server/race/entries.ts')).raceSeed(comp, ph.key) : phaseSeed(competitionKey, ph.key, ds.sha256));
      try {
        plan = barsPlan({ harness: bundle.harness, dataset: loaded.dataset, seed, finalWindow: receipt === null ? null : { last_graded_receipt_at: receipt } });
      } catch (err) {
        if (err instanceof SimDataError) throw new PermanentJobError(`dataset ${ds.slug} cannot replay ${comp.slug}'s universe: ${err.message}`, { cause: err });
        throw err;
      }
    } else if (bundle.harness.kind === 'clmm-replay/v1') {
      // Every phase of a clmm competition grades on a frozen pool window, dev included.
      const { ds, loaded } = await phaseDataset(loadClmmDataset);
      const receipt = ph.key === 'final' ? await lastReceiptAt(db, comp.id) : null;
      const seed = stored?.seed ?? phaseSeed(competitionKey, ph.key, ds.sha256);
      try {
        plan = clmmPlan({
          harness: bundle.harness,
          dataset: loaded.dataset,
          seed,
          finalWindow: receipt === null ? null : { last_graded_receipt_at: receipt },
          // The phase's floor of whole blocks: 28 on the ranked final phase, 8 on dev (contracts/clmm-protocol.ts clmmPhaseBlocksIssue).
          phase: ph.key,
          ...(deps.clmmScorer === undefined ? {} : { scorer: deps.clmmScorer }),
        });
      } catch (err) {
        if (err instanceof ClmmShortWindowError) throw new PermanentJobError(`dataset ${ds.slug}: ${comp.slug}'s window is too short for its blocks: ${err.message}`, { cause: err });
        if (err instanceof SimDataError) throw new PermanentJobError(`dataset ${ds.slug} cannot replay ${comp.slug}'s pool: ${err.message}`, { cause: err });
        throw err;
      }
    } else if (bundle.harness.kind === 'patch/v1') {
      // A patch/v1 phase grades on the bounty's sealed base tree and the phase's tree, never as a program/v1 run.
      plan = patchPlan(await patchPhaseSetup(deps, { slug: comp.slug, harness: bundle.harness, phaseKey: ph.key, competitionKey, seed: stored?.seed ?? null }));
    } else {
      plan = await programPhasePlan(deps, { slug: comp.slug, bundle, harness: bundle.harness, phaseKey: ph.key, competitionKey, seed: stored?.seed ?? null });
    }

    // Under a build meter a grade syncs the entrant's metered requests first and keeps the list of those it counts; a
    // regrade prices from exactly the stored ones that list names (the header's `metered`).
    const { cost, pricingRev } = await entryCostFor(deps, { sub, bundle, fresh: stored === null, ...(stored === null ? {} : { stored: stored.result }), ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }) });
    // A regrade is given the summary its run was graded with (the version its score names), whatever
    // the entry was ingested under since; a grade the newest.
    const version = stored === null ? undefined : storedAuthorshipVersion(stored.result);
    let authorship: AuthorshipSummaryT | null = null;
    if (version !== null) {
      authorship = await loadAuthorship(sub.id, pricingRev, version);
      if (version !== undefined && authorship?.algo_version !== version) {
        throw new PermanentJobError(`run ${stored!.id} was graded with authorship algorithm ${version}, and submission ${sub.id} has no summary of it under pricing_rev ${pricingRev}`);
      }
    }
    // Handed its job, the grade names its scratch for the job, the same on each attempt, and an attempt first removes
    // what one that died left (the header's `scratch`); with no job, its scratch is named for none, as before.
    let owned: { owner?: string; onScratchReap?: (reaped: ScratchReap) => void } = {};
    if (ctx !== undefined) {
      const what = stored === null ? `submission ${sub.id}'s grade on the ${ph.key} phase (job ${ctx.id})` : `run ${stored.id}'s ${job.kind} regrade (job ${ctx.id})`;
      const before = `attempt ${ctx.retryCount + 1}`;
      const log = deps.log ?? ((line: string) => console.log(line));
      owned = {
        owner: regradeOwner(ctx.id),
        onScratchReap: (r) => {
          const line = scratchReapLine(what, before, r);
          if (line !== null) log(line);
        },
      };
    }
    const rules = eligibilityRulesOf(bundle);
    // Under a size count, the entry's code size over its snapshot, the competition's starter left out where kept as
    // handed (the header's `size`): one count for the grade and every regrade of it.
    const starterOf = deps.starter ?? ((slug: string) => competitionStarter(COMPETITIONS_DIR, slug));
    const size = rules.size === undefined ? undefined : codeSize(rules.size, index.files, await starterOf(comp.slug));
    // A regrade under a judge naming a ladder: the ladder a dev run's v3 provisional record is held to, read off the event loop before the regrade (regradeJudgeLadder).
    const judgeLadder = stored !== null && bundle.harness.kind === 'program/v1' && bundle.harness.judge?.ladder !== undefined ? await regradeJudgeLadder(deps, comp.slug, bundle.harness, bundle.harness.judge) : undefined;
    const common = {
      plan,
      sandbox: deps.sandbox,
      limits: bundle.limits,
      workRoot: deps.workRoot,
      blobs,
      cost,
      authorship,
      // The entry's public link as the entry-link stage resolved it (submission.entry_link), which a pump.fun one turns
      // into the score's launch (grade.ts entryLinkFactsOf, contracts/score.ts ProgramPerformance.entry_link); a grade
      // and every regrade of it read it here. Null for every entry without one: the grade is what it was.
      entry: { house: standingsHouse(sub), baseline: sub.baseline, entry_link: sub.entryLink ?? null },
      rules,
      ...(size === undefined ? {} : { size }),
      // The judge heat the bundle names, whose record a regrade holds a judged run's verdict to (regrade.ts judgeVerdictOf),
      // and its prizes, which a screened final's v4 record's line M and race tiers are held to (regradeJudgeOf).
      ...regradeJudgeOf(bundle),
      ...(judgeLadder === undefined ? {} : { judgeLadder }),
      ...owned,
    };
    const ids = { submissionId: sub.id, phaseId: ph.id };
    // A patch/v1 entry is a diff, in no runtime of its own: it runs on the plan's one (harnesses.ts PATCH_RUNTIME).
    const picked = bundle.harness.kind === 'patch/v1' ? { runtime: PATCH_RUNTIME } : entryRuntime(index, plan.runtimes);
    /** A clmm score whose LVR parts from LVR leg by leg, as the platform's fault (the header's `platform fault`); any other error as it is. */
    const platformFault = (err: unknown, what: string): unknown =>
      err instanceof ClmmLvrMismatchError
        ? new PlatformFaultError(`${comp.slug}: ${what} is refused as the platform's fault, never the entry's (no run is recorded, nothing is posted): ${err.message}`, { cause: err })
        : err;

    // The attempt's signal stops the grade or regrade once pg-boss gives the attempt up (grade.ts's `Stopping`, regrade.ts's
    // `stopping`): the program running killed, nothing more run, the reason thrown (retried, never permanent), and no run
    // recorded.
    const stop = ctx?.signal === undefined ? {} : { signal: ctx.signal };
    // The entrant's env-lane entry secrets every run of the entry here gets (the header's `entry secrets`): a grade the
    // account's active ones, an L2 exactly those its run recorded, re-opened (once one is erased the L2 is refused, its
    // L1 standing); an L1 runs nothing and opens none. They ride the entry's snapshot, so every execution of it gets them.
    const secretOwner = { userId: sub.userId, competitionId: comp.id };
    let secrets: EnvSecrets = { ids: [], env: {} };
    let secretsErased: string | undefined;
    if (stored === null) {
      if (!('error' in picked)) secrets = await activeEnvSecrets(db, sealOf, secretOwner, `${comp.slug}: submission ${sub.id}'s grade on the ${ph.key} phase`);
    } else if (job.kind === 'regrade_l2') {
      const recorded = await recordedEnvSecrets(db, sealOf, secretOwner, stored.entry_secret_ids);
      if (recorded.erased !== null) {
        secretsErased = `an env-lane entry secret run ${stored.id} ran the entry with is erased since (replaced, deleted or purged): ${recorded.erased}, so it cannot re-execute as it was graded; its L1 stands`;
        (deps.log ?? ((line: string) => console.log(line)))(`[grade] ${comp.slug}: run ${stored.id}'s regrade_l2 is refused unexecuted (${ENTRY_SECRETS_ERASED}): ${secretsErased}`);
      } else if (recorded.kind === 'unopened') {
        // Held, as a grade is (the header's `entry secrets`): retried, nothing re-executed, its last attempt paged.
        const which = recorded.cause === 'off' ? ` (${recorded.names.join(', ')})` : '';
        throw new EntrySecretsUnopenedError(
          `${comp.slug}: run ${stored.id}'s regrade_l2: the env-lane entry secrets its run ran with${which} cannot be opened here, so it is not re-executed without them (its job tries again): ${recorded.why}`,
          recorded.names,
        );
      } else {
        secrets = recorded.secrets;
      }
    }
    const secretForms = entrySecretForms(secrets.env);
    const snapshot: SnapshotSource = { index, blobs, ...(secrets.ids.length === 0 ? {} : { secrets: secrets.env }) };
    if (stored === null) {
      if (practice !== null && eras !== null && !('error' in picked)) {
        return gradeEras({ deps, ctx, ids, harness: eras.harness, hours: practice.windows.hours, windows: eras.windows, plan, runtime: picked.runtime, snapshot, secrets, base: { ...common, ...stop }, load: loadDataset });
      }
      let outcome;
      try {
        outcome = 'error' in picked ? refusedGrade(plan, picked.error) : await gradeEntry({ ...common, ...stop, runtime: picked.runtime, snapshot, label: ph.key === 'dev' ? 'grade-dev' : 'grade-final' });
      } catch (err) {
        throw platformFault(err, `entry ${sub.id}'s grade on the ${ph.key} phase`);
      }
      // A code-fastest dev grade that passed carries its provisional timing (the header's `code heat`); the final's heat times the field after every final grade.
      if (!('error' in picked) && ph.key === 'dev' && rules.timing !== undefined) {
        outcome = await withProvisionalTiming(deps, {
          outcome,
          sub,
          plan,
          runtime: picked.runtime,
          snapshot,
          limits: bundle.limits,
          rules,
          entry: common.entry,
          ...(owned.owner === undefined ? {} : { owner: owned.owner }),
          ...stop,
        });
      }
      // A judged dev grade that passed carries its provisional judge verdict (the header's `provisional judge`); the final's heat judges the field after every final grade.
      let judgeHeat: string | null = null;
      if (!('error' in picked) && ph.key === 'dev' && bundle.harness.kind === 'program/v1' && bundle.harness.judge !== undefined) {
        // Its sandbox part is over (the grade's pods closed, the timing above run): the heat only calls the house judge,
        // so its place in the sandbox pool goes to the next grade in line now, not after the heat's calls (server/jobs.ts
        // JobContext.releasePlace). The heat, the record and the hand-on run as they did.
        ctx?.releasePlace?.(`submission ${sub.id}'s dev grade runs its provisional judge heat, house judge calls and no sandbox pod`);
        const judged = await withProvisionalJudge(deps, {
          outcome,
          sub,
          comp,
          ph,
          plan,
          harness: bundle.harness,
          judge: bundle.harness.judge,
          rules,
          entry: common.entry,
          ...stop,
        });
        outcome = judged.outcome;
        judgeHeat = judged.judge_heat_sha256;
      }
      // An attempt given up records nothing, however far it got: its retry grades again, and records once.
      ctx?.signal?.throwIfAborted();
      // The record its verdict came from, linked as the run's judge heat in the run's own insert (the regrade rebuilds the verdict from it).
      // Its action log and outputs scanned for the secrets it ran with, never masked (the header's `entry secrets`).
      const hits = await secretHitsOfRun(blobs, bundle.harness.kind, { json: outcome.action_log_json, sha256: outcome.action_log_sha256 }, secrets.env);
      if (hits.length > 0) (deps.log ?? ((line: string) => console.log(line)))(secretHitsLine(`${comp.slug}: submission ${sub.id}'s grade on the ${ph.key} phase`, hits));
      ctx?.signal?.throwIfAborted();
      const links = { judge_heat_sha256: judgeHeat, entry_secret_ids: secrets.ids, mask: secretForms, secret_hits: hits };
      // A final run's rows recorded only while each still holds its ciphertext, under its entrant's account lock, so a
      // challenge's re-run of it can always open them (the header's `entry secrets`).
      const runId =
        ph.key === 'final'
          ? await recordWithSecretsHeld(db, secretOwner, secrets.ids, `${comp.slug}: submission ${sub.id}'s grade on the final phase`, (into) => recordGrade(into, blobs, outcome, ids, links))
          : await recordGrade(db, blobs, outcome, ids, links);
      // A final grade moves the live board's grades count (finalGradeLanded): the page reads /live again.
      if (ph.key === 'final') await finalGradeLanded(db, comp.id, deps.log ?? ((line: string) => console.log(line)));
      // An official run of the phase that races live, once its results are published: the race held to it now (the header's `crosscheck`).
      if (racesLive(bundle, ph.key)) await crosscheckLandedGrade(deps, { slug: comp.slug, phaseId: ph.id, runId });
      return { run_id: runId };
    }
    try {
      if (eras !== null) {
        // An eras run regrades window by window (regrade.ts regradeErasL1, regradeErasL2); the regrade run takes a run_era row of its own for each.
        const windows = eraRegradeWindows(stored, storedEras, eras.windows, eras.harness, loadDataset);
        const base: Omit<typeof common, 'plan'> = common;
        let regraded;
        if (job.kind === 'regrade_l1') {
          regraded = await regradeErasL1({ ...base, ...stop, stored, windows });
        } else {
          if ('error' in picked) throw new PermanentJobError(picked.error);
          regraded = await regradeErasL2({ ...base, ...stop, stored, windows, runtime: picked.runtime, snapshot, label: 'regrade', ...(secretsErased === undefined ? {} : { secretsErased }) });
        }
        ctx?.signal?.throwIfAborted();
        return { run_id: await recordRegrade(db, blobs, regraded.outcome, ids, regraded.windows.map((w) => eraOfRegrade(w, w.outcome)), l2Secrets(job.kind, stored, secrets, secretsErased, secretForms)) };
      }
      let outcome;
      if (job.kind === 'regrade_l1') {
        outcome = await regradeL1({ ...common, ...stop, stored });
      } else {
        if ('error' in picked) throw new PermanentJobError(picked.error);
        outcome = await regradeL2({ ...common, ...stop, stored, runtime: picked.runtime, snapshot, label: 'regrade', ...(secretsErased === undefined ? {} : { secretsErased }) });
      }
      // regradeL1 / regradeL2 reject once the signal has aborted; read again here, so an attempt given up never writes the row.
      ctx?.signal?.throwIfAborted();
      return { run_id: await recordRegrade(db, blobs, outcome, ids, [], l2Secrets(job.kind, stored, secrets, secretsErased, secretForms)) };
    } catch (err) {
      if (err instanceof RegradeError) throw new PermanentJobError(err.message, { cause: err });
      throw platformFault(err, `run ${stored.id}'s ${job.kind} regrade on the ${ph.key} phase`);
    }
  };
  return async (job, ctx, handedOn) => {
    // Before it grades: the grade jobs that died since, unpaged (outside their handler, or with no context handed it).
    await dead.sweep().catch((err: unknown) => console.error('[grade] the dead grade jobs could not be read to page them; the next grade job looks again:', err));
    try {
      return await grade(job, ctx, handedOn);
    } catch (thrown) {
      const last = ctx !== undefined && isLastAttempt(ctx);
      // Held on its entrant's entry secrets (the header's `entry secrets`): retried while attempts remain, each logged,
      // never paged; on a fresh grade's last attempt the platform's fault, which the pipeline's grade stage never fails
      // the entry on (it puts back the status the attempt found).
      const err = thrown instanceof EntrySecretsUnopenedError && last && job.kind === 'grade' ? new EntrySecretsHeldFault(thrown) : thrown;
      if (ctx !== undefined && thrown instanceof EntrySecretsUnopenedError && !last) {
        (deps.log ?? ((line: string) => console.log(line)))(
          `[grade] job ${ctx.id} (${ctx.queue}) of submission ${job.submission_id} is held on attempt ${attemptWords(ctx)}, never failed: ${thrown.message}; pg-boss tries it again, and its last attempt pages`,
        );
      }
      // Dying for good (pg-boss retries it no more): paged, then the job's own error stands. A grade whose instance is
      // not drawn is not dying: the pipeline's grade stage hands it on (the header's `not drawn`).
      if (ctx !== undefined && (err instanceof PermanentJobError || last) && !(err instanceof InstanceNotDrawnError && job.kind === 'grade')) {
        await dead.dying(job, ctx, err).catch((e: unknown) => console.error(`[grade] ${ctx.id}: submission ${job.submission_id}'s ${job.kind} job died for good, and paging it failed; the next grade job's sweep pages it:`, e));
      }
      throw err;
    }
  };
}

// ---------------------------------------------------------------- code-fastest: the timing clock, the dev timing and the heat

/**
 * The sandbox a code-fastest timing reads CPU time on (GradeWorkerDeps.timingSandbox, which a test hands in, null for
 * none): by default the grader's own when it is the docker driver (a timing parent cgroup, sandbox/docker.ts) or the
 * k8s driver (the CPU launcher's readings, sandbox/k8s.ts openCpuClock); null on the process driver, which reads none.
 */
export function timingSandboxOf(deps: Pick<GradeWorkerDeps, 'sandbox' | 'timingSandbox'>): TimingSandbox | null {
  if (deps.timingSandbox !== undefined) return deps.timingSandbox;
  return deps.sandbox instanceof DockerSandbox || deps.sandbox instanceof K8sSandbox ? deps.sandbox : null;
}

/** `p`, or the signal's reason once it aborts first. */
function untilAborted(p: Promise<void>, signal: AbortSignal | undefined): Promise<void> {
  if (signal === undefined) return p;
  signal.throwIfAborted();
  return new Promise((resolve, reject) => {
    const onAbort = (): void => reject(signal.reason);
    signal.addEventListener('abort', onAbort, { once: true });
    void p.then(() => {
      signal.removeEventListener('abort', onAbort);
      resolve();
    });
  });
}

/**
 * The one CPU clock a worker process times on (the header's `code heat`): its timing sandbox's openCpuClock, opened at
 * the first timing and kept open, so a docker process leaves one empty timing cgroup behind (sandbox/docker.ts: a clock's
 * parent stays once it closes, where this process may not remove it), never one per grade; a k8s clock is a sum this
 * process holds (sandbox/k8s.ts K8sCpuClock) and leaves nothing. One timing at a time (exclusive): no two timed runs
 * count on the clock at once (docker: share its parent cgroup, whose usage is their CPU time). A clock that fails a read
 * is closed and left, and the next timing opens a fresh one. It knows which of its timings are heats (exclusive's
 * `holder`), so a dev grade's timing can tell it would wait on one (heatAhead) and not wait.
 */
export class ProcessCpuClock {
  readonly #base: TimingSandbox;
  #open: TimedSandbox | null = null;
  #tail: Promise<void> = Promise.resolve();
  /** The heats handed in that have not ended: holding the clock, or waiting for it. */
  #heats = 0;

  constructor(base: TimingSandbox) {
    this.#base = base;
  }

  /**
   * Run `fn` once every timing handed in before it has ended, handing it a sandbox whose openCpuClock is this clock (a
   * close of it leaves the clock open: grader/code-heat.ts openCodeTimer closes its timer). An abort of `signal` while it
   * waits throws the signal's reason, and nothing runs: it leaves the queue, the timings behind it waiting only for those
   * before it (a heat's wait given up at its expiry: the header's `hand-on`). `holder` says what the timing is: a `heat` (a code-heat job's,
   * which may hold the clock up to its job's expiry, server/jobs.ts CODE_HEAT_EXPIRY_SECONDS, or a hand-on's up to
   * CODE_HEAT_MAX_EXPIRY_SECONDS: the header's `hand-on`) counts in heatAhead from
   * the call until it ends, waiting included; a `timing` (a dev grade's, the default) does not.
   */
  async exclusive<T>(fn: (sandbox: TimingSandbox) => Promise<T>, signal?: AbortSignal, holder: 'heat' | 'timing' = 'timing'): Promise<T> {
    const before = this.#tail;
    let release!: () => void;
    const mine = new Promise<void>((resolve) => {
      release = resolve;
    });
    this.#tail = before.then(() => mine);
    if (holder === 'heat') this.#heats++;
    try {
      await untilAborted(before, signal);
      return await fn(sharedClockSandbox(this, this.#base));
    } finally {
      if (holder === 'heat') this.#heats--;
      release();
    }
  }

  /**
   * Whether a heat holds the clock or waits for it (exclusive's `holder`): a timing handed in now would wait for that heat
   * to end. A dev grade's timing never does (withProvisionalTiming).
   */
  get heatAhead(): boolean {
    return this.#heats > 0;
  }

  /** The open clock and its timed sandbox, opened now (in `runtime`'s image) if none is; its close() leaves it open. */
  lease(runtime: Runtime): TimedSandbox {
    const open = (this.#open ??= this.#base.openCpuClock(runtime));
    const drop = async (): Promise<void> => {
      if (this.#open !== open) return;
      this.#open = null;
      await open.clock.close().catch(() => undefined);
    };
    const guarded = async (read: () => Promise<bigint>): Promise<bigint> => {
      try {
        return await read();
      } catch (err) {
        await drop();
        throw err;
      }
    };
    return {
      clock: { source: open.clock.source, read: () => guarded(() => open.clock.read()), settled: () => guarded(() => open.clock.settled()), close: async () => undefined },
      sandbox: open.sandbox,
    };
  }

  /** Whether a clock is open now. */
  get isOpen(): boolean {
    return this.#open !== null;
  }

  /** Close the clock (a worker's stop); the next timing opens a fresh one. */
  async close(): Promise<void> {
    const open = this.#open;
    this.#open = null;
    await open?.clock.close();
  }
}

/**
 * The timing sandbox as ProcessCpuClock.exclusive hands it out: the base itself in every member (its methods bound to it,
 * so a class's private state answers, and `instanceof` holds), but its openCpuClock is the process's one clock (lease).
 */
function sharedClockSandbox(clock: ProcessCpuClock, base: TimingSandbox): TimingSandbox {
  const openCpuClock = (runtime: Runtime): TimedSandbox => clock.lease(runtime);
  return new Proxy(base, {
    get(target, prop) {
      if (prop === 'openCpuClock') return openCpuClock;
      const value: unknown = Reflect.get(target, prop, target);
      return typeof value === 'function' ? (value as (...args: unknown[]) => unknown).bind(target) : value;
    },
  });
}

const PROCESS_CPU_CLOCKS = new WeakMap<object, ProcessCpuClock>();

/** This process's one CPU clock on `sandbox` (ProcessCpuClock): the same for every grade and heat job handed that sandbox. */
export function processCpuClock(sandbox: TimingSandbox): ProcessCpuClock {
  let clock = PROCESS_CPU_CLOCKS.get(sandbox);
  if (clock === undefined) {
    clock = new ProcessCpuClock(sandbox);
    PROCESS_CPU_CLOCKS.set(sandbox, clock);
  }
  return clock;
}

/** Close this process's CPU clock on `sandbox`, if one is open (server/pipeline/index.ts, as the workers stop). */
export async function closeProcessCpuClock(sandbox: Sandbox | null): Promise<void> {
  if (sandbox !== null) await PROCESS_CPU_CLOCKS.get(sandbox)?.close();
}

/** What a dev grade's provisional timing reads (withProvisionalTiming). */
interface ProvisionalTimingInput {
  outcome: GradeOutcome;
  sub: Pick<typeof submission.$inferSelect, 'id' | 'receipt' | 'createdAt'>;
  plan: HarnessPlan;
  runtime: Runtime;
  snapshot: SnapshotSource;
  limits: CompetitionBundleT['limits'];
  rules: EligibilityRules;
  entry: EntryFacts;
  owner?: string;
  signal?: AbortSignal;
}

/**
 * A code-fastest dev grade with its provisional timing (the header's `code heat`): a grade that passed its gate timed
 * CODE_TIMING_DEV_ROUNDS times on the process's clock (code-heat.ts runProvisionalTiming, its outputs held to the
 * graded action log) and its score built again with the verdict (grade.ts scoreWithTiming); any other grade as it is.
 * With no timing sandbox in this process the grade is recorded untimed, and that is logged; so it is, at once, when a
 * heat holds the process's clock or waits for it (ProcessCpuClock.heatAhead): the timing would wait for the heat, which
 * may run past the grade job's own expiry. Behind another dev grade's timing it waits, as long as the job's signal
 * lets it. The signal stops the timing too (runProvisionalTiming): its run under way killed, nothing recorded.
 */
async function withProvisionalTiming(deps: GradeWorkerDeps, t: ProvisionalTimingInput): Promise<GradeOutcome> {
  const score = t.outcome.result;
  if (t.outcome.status !== 'finished' || score === null || score.performance.kind !== 'program/v1' || score.performance.passed !== true || t.outcome.action_log_sha256 === null) return t.outcome;
  const log = deps.log ?? ((line: string) => console.log(line));
  const timing = timingSandboxOf(deps);
  if (timing === null) {
    log(`[grade] submission ${t.sub.id}: its dev grade is recorded with no provisional timing: this process's ${deps.sandbox.kind} sandbox reads no CPU time (a timing runs on the docker driver or the k8s driver)`);
    return t.outcome;
  }
  const { runProvisionalTiming } = await import('./code-heat.ts');
  // No await between this read and exclusive below, which joins the clock's queue as it is called: no heat comes between.
  const clock = processCpuClock(timing);
  if (clock.heatAhead) {
    log(`[grade] submission ${t.sub.id}: its dev grade is recorded with no provisional timing: a timing heat holds this process's CPU clock (or waits for it), and a dev grade never waits on a heat`);
    return t.outcome;
  }
  const ms = receiptMs(t.sub);
  const entry: TimedEntry = {
    entry: t.sub.id,
    received_at: new Date(Number.isFinite(ms) ? ms : t.sub.createdAt.getTime()).toISOString(),
    action_log_sha256: t.outcome.action_log_sha256,
    snapshot: t.snapshot,
    image_digest: t.outcome.image_digest,
  };
  const verdict = await clock.exclusive(
    (sandbox) =>
      runProvisionalTiming({
        plan: t.plan,
        sandbox,
        runtime: t.runtime,
        limits: t.limits,
        workRoot: deps.workRoot,
        blobs: deps.blobs,
        entry,
        ...(t.owner === undefined ? {} : { owner: t.owner }),
        ...(t.signal === undefined ? {} : { signal: t.signal }),
      }),
    t.signal,
  );
  const timed = scoreWithTiming(score, verdict, t.entry, t.rules);
  return { ...t.outcome, result: timed.result, result_sha256: timed.result_sha256 };
}

/** What a judged dev grade's provisional judge heat reads (withProvisionalJudge). */
interface ProvisionalJudgeInput {
  outcome: GradeOutcome;
  /** The entry: its id, and its account and competition, which its artifact is recorded under (entry_artifact). */
  sub: Pick<typeof submission.$inferSelect, 'id' | 'userId' | 'competitionId'>;
  comp: { slug: string };
  /** The dev phase: where its heat's key is kept (judgeKeysDir). */
  ph: { id: string };
  plan: HarnessPlan;
  /** The bundle's harness: where its judge directory is read (judgedTreesOf). */
  harness: ProgramHarnessT;
  judge: ProgramJudgeT;
  rules: EligibilityRules;
  entry: EntryFacts;
  signal?: AbortSignal;
}

/** A dev grade as withProvisionalJudge leaves it, and the judge heat record its verdict came from (null: the grade is recorded unjudged). */
interface ProvisionalJudged {
  outcome: GradeOutcome;
  judge_heat_sha256: string | null;
}

/**
 * A judged dev grade with its provisional judge verdict (the header's `provisional judge`): a grade that passed its
 * gate plays its artifact against every house anchor in both orders (provisionalJudgeHeat), its score built again with
 * the verdict (scoreWithJudge: performance.judge, provisional), to be linked to the run (run.judge_heat_sha256); any
 * other grade as it is. A grade its heat cannot judge is recorded unjudged and says so in the log.
 */
async function withProvisionalJudge(deps: GradeWorkerDeps, j: ProvisionalJudgeInput): Promise<ProvisionalJudged> {
  const score = j.outcome.result;
  const as: ProvisionalJudged = { outcome: j.outcome, judge_heat_sha256: null };
  if (j.outcome.status !== 'finished' || score === null || score.performance.kind !== 'program/v1' || score.performance.passed !== true || j.outcome.action_log_sha256 === null) return as;
  const log = deps.log ?? ((line: string) => console.log(line));
  const heat = await provisionalJudgeHeat(deps, {
    actionLog: { sha256: j.outcome.action_log_sha256, json: j.outcome.action_log_json },
    sub: j.sub,
    comp: j.comp,
    ph: j.ph,
    phaseSeed: j.plan.seed,
    harness: j.harness,
    judge: j.judge,
    ...(j.signal === undefined ? {} : { signal: j.signal }),
  });
  if ('unjudged' in heat) {
    log(`[grade] submission ${j.sub.id}: its dev grade is recorded with no provisional judge verdict: ${heat.unjudged}`);
    return as;
  }
  const judged = scoreWithJudge(score, heat.verdict, j.entry, j.rules);
  log(`[grade] submission ${j.sub.id}: its dev grade is judged provisionally against ${provisionalHeatWords(heat)}`);
  return { outcome: { ...j.outcome, result: judged.result, result_sha256: judged.result_sha256 }, judge_heat_sha256: heat.judge_heat_sha256 };
}

/** What a provisional judge heat reads (provisionalJudgeHeat): a dev grade's (withProvisionalJudge), or a kept dev run's again (rejudgeProvisional). */
interface ProvisionalHeatInput {
  /** The action log the artifact is read from; its JSON, when given, stored first (a grade's, ahead of the run that records it). */
  actionLog: { sha256: string; json: string | null };
  /** The entry: its id, and its account and competition, which its artifact is recorded under (entry_artifact). */
  sub: Pick<typeof submission.$inferSelect, 'id' | 'userId' | 'competitionId'>;
  comp: { slug: string };
  /** The dev phase: where its heat's key is kept (judgeKeysDir). */
  ph: { id: string };
  /** The dev phase's seed, a u64 decimal: the plan's (a grade's), or the seed its run recorded (a rejudge's). */
  phaseSeed: string;
  /** The bundle's harness: where its judge directory is read (judgedTreesOf). */
  harness: ProgramHarnessT;
  judge: ProgramJudgeT;
  signal?: AbortSignal;
  /**
   * A screened bundle's dev money-place scrutiny line (server/grading/dev-scrutiny-line.ts) the heat is held to, in
   * place of the phase's stored one: a scrutiny top-up's (server/jobs.ts GradeJob `scrutiny_top_up`).
   */
  scrutinyLine?: number;
  /**
   * A scrutiny top-up's extension (rejudgeProvisional): the record the run links on the current judge, the setup it
   * becomes with its scrutiny (scrutinisedSetupOf), its calls and spares carried verbatim into the new heat, never asked
   * again, and only the calls the schedule plans past them sent. No earlier verdict is reused for it.
   */
  extend?: ProvisionalExtension;
}

/** A scrutiny top-up's extension of a kept provisional record (ProvisionalHeatInput.extend). */
interface ProvisionalExtension {
  /** The record extended, and its sha256. */
  record: JudgeHeatRecordT;
  sha256: string;
  /** The record's setup with its ladder's scrutiny at the top-up's line (scrutinisedSetupOf). */
  setup: JudgeHeatSetupT;
}

/**
 * Why a provisional heat judged nothing, for a rejudge to weigh against the verdict the run has (rejudgeProvisional):
 * `fault` the platform's (a judge call that faulted again after its one resend or that the router answered finally, a
 * judge key masq did not mint, no LLM gateway), so the job is retried; `unpriced` a judge model with no price, so it is sent again another UTC day;
 * `other` the heat's own end on the artifact (no artifact or one the judge cannot read, too many calls with no verdict,
 * a model that cannot see images...).
 */
type ProvisionalUnjudgedCause = 'fault' | 'unpriced' | 'other';

/** A provisional heat's end: why it judged nothing, or its verdict and the record it is stored as, with what the log says of it. */
type ProvisionalHeat =
  | { unjudged: string; cause: ProvisionalUnjudgedCause }
  | {
      verdict: ProgramJudgeScoreT;
      judge_heat_sha256: string;
      /** The judge anchors it played, two calls each. */
      anchors: number;
      calls: number;
      invalid_calls: number;
      micro_usd: string;
      /**
       * A heat on a ladder's: the adaptive rounds it played (every one of its ladder's design, and its scrutiny's when its
       * entry reached the line), of its ladder's and its scrutiny's, each of `games` games.
       */
      adaptive?: { rounds: number; of: number; games: number };
      /** A heat with money-place scrutiny (a screened bundle's dev heat): its line and rounds, and whether its entry reached the line. */
      scrutiny?: { line_micro: number; rounds: number; reached: boolean };
      /** A scrutiny top-up's: the record it extended, and how many of its calls were that record's, kept verbatim. */
      extended?: { judge_heat_sha256: string; kept_calls: number };
      /**
       * Present only when no heat was played: the verdict is an earlier entry's on the same artifact bytes, read from
       * its record (`judge_heat_sha256`; the header's `provisional reuse`), with no call sent, no key and no spend.
       */
      reused?: true;
    };

/**
 * A win rate's millionths as the 0..1 fraction they are, at every digit they hold: 868330 is '0.868330', 1000000
 * '1.000000' (six fraction digits, fixed, so an exact 870000 never reads as rounded). Integer arithmetic only. Every
 * printed win rate (the worker's log, grade-local's summary, verify-result's re-derivation) goes through it.
 */
export function winRateFraction(micro: number): string {
  const n = Math.round(micro);
  const abs = Math.abs(n);
  return `${n < 0 ? '-' : ''}${Math.floor(abs / 1_000_000)}.${String(abs % 1_000_000).padStart(6, '0')}`;
}

/** A judged provisional heat in the log's words: its anchors, its calls, what it spent, its record and the win rate in full; a reused verdict says so. */
function provisionalHeatWords(h: Exclude<ProvisionalHeat, { unjudged: string }>): string {
  if (h.reused === true) {
    return `the verdict of record ${h.judge_heat_sha256} on the same artifact bytes, reused with no judge call sent (${h.calls} calls, ${h.micro_usd} µUSD): win rate ${winRateFraction(h.verdict.win_rate_micro)}`;
  }
  const games = h.adaptive === undefined ? '' : ` and ${h.adaptive.rounds * h.adaptive.games} adaptive ladder games (${h.adaptive.rounds} of ${h.adaptive.of} rounds)`;
  const scrutiny =
    h.scrutiny === undefined
      ? ''
      : h.scrutiny.reached
        ? `, its ${h.scrutiny.rounds} money-place scrutiny rounds among them (its interval reached the dev line ${winRateFraction(h.scrutiny.line_micro)})`
        : `, with no money-place scrutiny (its interval is below the dev line ${winRateFraction(h.scrutiny.line_micro)})`;
  const kept = h.extended === undefined ? '' : `, ${h.extended.kept_calls} of them record ${h.extended.judge_heat_sha256}'s kept verbatim`;
  return `${h.anchors} anchors${games}${scrutiny} in ${h.calls} calls (${h.invalid_calls} with no verdict${kept}, ${h.micro_usd} µUSD, record ${h.judge_heat_sha256}): win rate ${winRateFraction(h.verdict.win_rate_micro)}`;
}

/**
 * One dev entry's provisional judge heat (the header's `provisional judge`): its artifact played against every house
 * anchor in both orders (grader/judge-heat.ts judgeProvisionalCalls: two an anchor), on a key of its own minted with no
 * dollar cap (the header's `judge keys`; no spend is read or weighed, and it never waits on another heat), its record
 * stored before its verdict is read from it. `unjudged`, with why and its cause, when the heat cannot judge it: no
 * gateway, no judge directory of the bundle's, no artifact or one the judge cannot read, a judge model with no price, a
 * key that does not open, a second faulted call, a call the router answered finally (never sent again), or more calls
 * with no verdict than judge.invalid_share_max allows. Nothing is sent again, and nothing paged. The signal stops it too: its key retired, the error thrown.
 *
 * A bundle naming a ladder (judge.ladder) plays a v3 heat on it: the ladder read and held (grader/judge-ladder-tree.ts
 * readJudgeLadder; one that does not read judges nothing), the field the entry, the judge anchors and the rungs, the
 * anchors played once each and then every adaptive round of the ladder's design (judgeHeatPlannedCalls). A screened
 * bundle's adds its money-place scrutiny at the phase's dev line (provisionalScrutinyOf; the header's `dev scrutiny`).
 *
 * An artifact the judge reads that is byte for byte one an earlier entry of the phase was judged on, on the current
 * judge and phase seed, takes that verdict with no heat played (reusedProvisionalVerdict; the header's `provisional
 * reuse`). Every heat's artifact that ends judged, reused or recorded unjudged is then written to the phase's
 * entry_artifact (recordProvisionalArtifact), a fault there logged and the heat kept. A scrutiny top-up (`extend`)
 * reuses nothing and writes no row: its record is extended, and scrutinyTopUp relinks the rows.
 */
async function provisionalJudgeHeat(deps: GradeWorkerDeps, j: ProvisionalHeatInput): Promise<ProvisionalHeat> {
  const { judge } = j;
  const unjudged = (why: string, cause: ProvisionalUnjudgedCause = 'other'): ProvisionalHeat => ({ unjudged: why, cause });
  let trees: JudgedTrees;
  try {
    trees = await judgedTreesOf(deps, j.comp.slug, j.harness, judge);
  } catch (err) {
    if (err instanceof PermanentJobError) return unjudged(err.message);
    throw err;
  }
  const dir = await readJudgeTreeAsync(trees.judgeDir, judge);
  if ('refused' in dir) return unjudged(dir.refused);
  // A bundle naming a ladder: its sealed ladder read and held (grader/judge-ladder-tree.ts), beside the competition's
  // judge directory (a sponsored one's materialized with it: judgedTreesOf), and the heat a v3 one on it. A ladder the image does not hold judges nothing, as a judge directory.
  let ladder: ProvisionalLadder | null = null;
  if (judge.ladder !== undefined) {
    const { judgeLadderBlock, readJudgeLadderAsync } = await import('./judge-ladder-tree.ts');
    const read = await readJudgeLadderAsync(judgeLadderDirOf(deps, j.comp.slug, j.harness, judge.ladder, trees), judge, trees.judgeDir);
    if ('refused' in read) return unjudged(`its judge's ladder does not read: ${read.refused}`);
    ladder = { read, design: judge.ladder, block: judgeLadderBlock };
  }
  // The action log stored ahead of the run that records it (grader/record.ts recordGrade stores it again, as the same blob): the artifact is read through it.
  if (j.actionLog.json !== null) {
    const put = await deps.blobs.put(j.actionLog.json);
    if (put.sha256 !== j.actionLog.sha256) throw new Error(`submission ${j.sub.id}'s action log stored as ${put.sha256}, not ${j.actionLog.sha256}`);
  }
  const art = await readOutputFile(deps.blobs, j.actionLog.sha256, judge.artifact);
  if (art === null) return unjudged(`its outputs hold no ${judge.artifact}, the artifact the judge compares (the scorer's gate is to fail an entry that writes none)`);
  const refused = await judgeArtifactRefusal(judge.media, art);
  if (refused !== null) return unjudged(`the judge cannot read its ${judge.artifact} (${refused})`);
  // An earlier entry's verdict on the same bytes, on the current judge, taken with no call (the header's `provisional
  // reuse`): before any setup, broker or key. Else the heat is played as it always was. A scrutiny top-up extends the
  // record it was handed: nothing reused, and its runs' and entry_artifact rows' links are the top-up's to move
  // (rejudgeProvisional relinks every one that linked the record), so no row is written here.
  if (j.extend !== undefined) {
    if (ladder === null) return unjudged(`its scrutiny top-up extends ladder record ${j.extend.sha256}, and the bundle's judge names no ladder`);
    return playProvisionalJudgeHeat(deps, j, dir, ladder, art);
  }
  const heat = (await reusedProvisionalVerdict(deps, j, art, ladder)) ?? (await playProvisionalJudgeHeat(deps, j, dir, ladder, art));
  await recordProvisionalArtifact(deps, j, art, heat);
  return heat;
}

/**
 * A screened bundle's dev money-place scrutiny (contracts/competition.ts ProgramJudgeScreened.dev_rounds; grader/judge-heat.ts
 * JudgeHeatLadder.scrutiny) for a provisional heat on `judge`'s ladder: its line and rounds, or null when the heat
 * records none (no ladder, no screened block, dev_rounds 0, or no line: none given and none stored for the phase, or
 * the stored one null while fewer than K entrants are rated). The line is `given` (a top-up's) when given, else the
 * phase's stored one (server/grading/dev-scrutiny-line.ts readDevScrutinyLine); a read of it that fails is logged and
 * read as no line, so the heat plays with no scrutiny and the sweep tops it up once a line stands.
 */
async function provisionalScrutinyOf(deps: GradeWorkerDeps, judge: ProgramJudgeT, phaseId: string, given: number | undefined, say: (line: string) => void): Promise<{ line_micro: number; rounds: number } | null> {
  const rounds = judge.screened?.dev_rounds ?? 0;
  if (judge.ladder === undefined || rounds < 1) return null;
  if (given !== undefined) return { line_micro: given, rounds };
  try {
    const { readDevScrutinyLine } = await import('../server/grading/dev-scrutiny-line.ts');
    const stored = await readDevScrutinyLine(deps.db, phaseId);
    return stored === null || stored.line_micro === null ? null : { line_micro: stored.line_micro, rounds };
  } catch (err) {
    say(`its dev scrutiny line could not be read (${err instanceof Error ? err.message : String(err)}): it is played with no scrutiny, and the sweep tops it up once a line stands`);
    return null;
  }
}

/**
 * The setup a scrutiny top-up plays (the header's `provisional rejudge`): the kept provisional ladder record's own setup
 * (its seed, field, judges and ladder as they were), its ladder's `scrutiny` set to `scrutiny`. Its calls are then a
 * prefix of the new setup's schedule (grader/judge-heat.ts: a heat before the line's decision is the same calls either
 * way), which judgeHeatSchedule holds. JudgeHeatError when the setup does not hold.
 */
export async function scrutinisedSetupOf(record: JudgeHeatRecordT, scrutiny: { line_micro: number; rounds: number }): Promise<JudgeHeatSetupT> {
  const jh = await import('./judge-heat.ts');
  if (record.ladder === undefined) throw new jh.JudgeHeatError(`the record is a ${record.format} ${record.stage} heat's with no ladder: only a ladder heat takes money-place scrutiny`);
  const keys = Object.keys(jh.JudgeHeatSetup.shape) as (keyof JudgeHeatSetupT)[];
  const base = Object.fromEntries(keys.filter((k) => record[k] !== undefined).map((k) => [k, record[k]]));
  const parsed = jh.JudgeHeatSetup.safeParse({ ...base, ladder: { ...record.ladder, scrutiny: { line_micro: scrutiny.line_micro, rounds: scrutiny.rounds } } });
  if (!parsed.success) throw new jh.JudgeHeatError(`its scrutinised setup does not hold: ${parsed.error.issues.map((i) => `${i.path.join('.') || '(setup)'}: ${i.message}`).join('; ')}`);
  const issues = jh.judgeHeatSetupIssues(parsed.data);
  if (issues.length > 0) throw new jh.JudgeHeatError(`its scrutinised setup does not hold: ${issues.join('; ')}`);
  return parsed.data;
}

/** A provisional heat's ladder (judge.ladder) as provisionalJudgeHeat read and held it: what readJudgeLadder read, the bundle's design, and the block its setup builds. */
interface ProvisionalLadder {
  read: JudgeLadderInputs;
  design: NonNullable<ProgramJudgeT['ladder']>;
  block: typeof import('./judge-ladder-tree.ts').judgeLadderBlock;
}

/**
 * The verdict a provisional heat of `art` takes with no call (the header's `provisional reuse`): of the phase's other
 * entries judged on the same bytes (judgedSameArtifact, oldest first), the first whose record is keyed on the current
 * judge (provisionalRecordJudgeKey against provisionalJudgeKey), was drawn under this heat's phase seed, and holds a
 * verdict on the artifact that a regrade of this entry's run rebuilds (grader/regrade.ts judgeRecordVerdictOf: its
 * judge, seed and ladder held, the field's one entrant member on these bytes; judge-heat.ts judgeHeatVerdicts). Null on
 * a miss: no such entry, a field that played the artifact in no game, another judge or seed. A fault in the lookup is
 * logged with its full stack and is a miss too, so the heat is judged as it always was; the signal's abort is thrown.
 */
async function reusedProvisionalVerdict(deps: GradeWorkerDeps, j: ProvisionalHeatInput, art: ProgramOutputRead, ladder: ProvisionalLadder | null): Promise<ProvisionalHeat | null> {
  const log = deps.log ?? ((line: string) => console.log(line));
  try {
    const { judgedSameArtifact } = await import('../server/entries/screen/artifact.ts');
    const { judgeHeldVerdictOf, loadHeldJudgeHeatRecord } = await import('./regrade.ts');
    const rows = await judgedSameArtifact(deps.db, j.ph.id, art.sha256);
    const entryId = j.sub.id.toLowerCase();
    const tried = new Set<string>();
    let key: string | null = null;
    for (const row of rows) {
      if (row.submissionId.toLowerCase() === entryId || tried.has(row.judgeHeatSha256)) continue;
      tried.add(row.judgeHeatSha256);
      j.signal?.throwIfAborted();
      key ??= await provisionalJudgeKey(j.judge);
      if ((await provisionalRecordJudgeKey(deps.blobs, row.judgeHeatSha256, j.judge)) !== key) continue;
      // Read back once a process, off this thread (regrade.ts loadHeldJudgeHeatRecord), as provisionalRecordJudgeKey read it.
      const held = await loadHeldJudgeHeatRecord(deps.blobs, row.judgeHeatSha256);
      if (held.record.phase_seed !== j.phaseSeed) continue;
      let verdict: ProgramJudgeScoreT;
      try {
        verdict = judgeHeldVerdictOf(held, { id: `the grade of entry ${entryId}`, submission_id: entryId, seed: j.phaseSeed, artifact_sha256: art.sha256, artifact_bytes: art.size }, j.judge, ladder?.read).verdict;
      } catch (err) {
        // A record that judged the bytes in no game (a field under two members), or one a regrade would not hold: judged afresh.
        if (err instanceof RegradeError) continue;
        throw err;
      }
      log(
        `[grade] submission ${j.sub.id}: its ${j.judge.artifact} is byte for byte entry ${row.submissionId}'s (${art.sha256}), judged on the current judge in record ${row.judgeHeatSha256}: that verdict is reused and no judge call is sent`,
      );
      return { verdict, judge_heat_sha256: row.judgeHeatSha256, anchors: 0, calls: 0, invalid_calls: 0, micro_usd: '0', reused: true };
    }
    return null;
  } catch (err) {
    if (j.signal?.aborted === true) throw err;
    countEntryArtifactFault('lookup');
    log(`[grade] submission ${j.sub.id}: the lookup of an earlier verdict on its ${j.judge.artifact} ${art.sha256} failed, so it is judged afresh: ${err instanceof Error ? (err.stack ?? err.message) : String(err)}`);
    return null;
  }
}

/**
 * The entry's artifact written to its phase's entry_artifact once its heat ends (the header's `provisional reuse`): its
 * media, sha256, size and fingerprint (artifactFingerprint: a text's normalised sha256, an image's dHash), the record
 * its verdict is in, whether it was reused, and near_of (nearArtifactOf). A heat that judged nothing writes the row with
 * no record, unless it ended on the platform's fault or on a judge model with no price: a run then keeps the verdict it
 * had (a rejudge's), or is judged again later, so the row is left as it was. Never throws: a fault is logged with its full
 * stack, and the heat stands.
 */
async function recordProvisionalArtifact(deps: GradeWorkerDeps, j: ProvisionalHeatInput, art: ProgramOutputRead, heat: ProvisionalHeat): Promise<void> {
  if ('unjudged' in heat && heat.cause !== 'other') return;
  const log = deps.log ?? ((line: string) => console.log(line));
  try {
    const { artifactFingerprint, nearArtifactOf, recordArtifact } = await import('../server/entries/screen/artifact.ts');
    const media = j.judge.media;
    const print = await artifactFingerprint(media, art.bytes, (line) => log(`[grade] submission ${j.sub.id}: ${line}`));
    const nearOf = await nearArtifactOf(deps.db, { phaseId: j.ph.id, userId: j.sub.userId, artifactSha256: art.sha256, normSha256: print.normSha256, dhash: print.dhash });
    await recordArtifact(deps.db, {
      submissionId: j.sub.id,
      phaseId: j.ph.id,
      competitionId: j.sub.competitionId,
      userId: j.sub.userId,
      media,
      artifactSha256: art.sha256,
      bytes: art.size,
      normSha256: print.normSha256,
      dhash: print.dhash,
      judgeHeatSha256: 'unjudged' in heat ? null : heat.judge_heat_sha256,
      reused: !('unjudged' in heat) && heat.reused === true,
      nearOf,
    });
  } catch (err) {
    countEntryArtifactFault('record');
    log(`[grade] submission ${j.sub.id}: its ${j.judge.artifact} ${art.sha256} could not be written to the phase's entry_artifact, and its heat stands: ${err instanceof Error ? (err.stack ?? err.message) : String(err)}`);
  }
}

/**
 * The provisional heat provisionalJudgeHeat plays on an artifact the judge reads when no earlier verdict is reused: the
 * setup, its key, its calls and its record (see provisionalJudgeHeat). With a planner (JudgeWorkerDeps.plan) that
 * answers a plan, the heat is played whole on its one judge (server/judging/pool-heat.ts; its record lists it in
 * `judges`, its `agent` the bundle's block still), and a pick made via the overflow that ends on the platform's fault
 * is played once more on the plan's fallback (`fixed`: a fallback's plan, null the bundle's own judge; never asked again).
 */
async function playProvisionalJudgeHeat(deps: GradeWorkerDeps, j: ProvisionalHeatInput, dir: JudgeDirInputs, ladder: ProvisionalLadder | null, art: ProgramOutputRead, fixed?: JudgeWorkerPlan | null): Promise<ProvisionalHeat> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  const { judge } = j;
  const unjudged = (why: string, cause: ProvisionalUnjudgedCause = 'other'): ProvisionalHeat => ({ unjudged: why, cause });
  // Its judges, asked before its setup (seeded as the record it writes is): null with no planner or on the bundle's one named judge.
  const planner = deps.judge?.plan;
  let plan: JudgeWorkerPlan | null = fixed ?? null;
  const extend = j.extend;
  if (extend !== undefined && fixed === undefined) {
    // A top-up plays on the judges its record fixed (none: the bundle's own named judge), their pins read again for the
    // calls still to send (plan.ts resume), never asked of the planner afresh.
    const judges = extend.setup.judges;
    if (judges !== undefined) {
      if (planner === undefined) return unjudged(`its record's judges (${judges.map((x) => x.model).join(', ')}) were fixed before its first call, and this process has no judge planner to play them on`, 'fault');
      try {
        plan = await planner.resume(judges);
      } catch (err) {
        if ((err as { retryable?: unknown } | null)?.retryable !== true) throw err;
        return unjudged(`its record's judges could not be planned again (${err instanceof Error ? err.message : String(err)})`, 'fault');
      }
    }
  } else if (fixed === undefined && planner !== undefined) {
    const { JUDGE_HEAT_FORMAT, JUDGE_HEAT_FORMAT_V3, judgeHeatSeed } = await import('./judge-heat.ts');
    try {
      plan = await planner.of({ slug: j.comp.slug, stage: 'provisional', judge: judge.agent, seed: judgeHeatSeed(j.phaseSeed, ladder === null ? JUDGE_HEAT_FORMAT : JUDGE_HEAT_FORMAT_V3), subject: art.sha256 });
    } catch (err) {
      // A JudgePlanFault (retryable): the platform's, never the entry's.
      if ((err as { retryable?: unknown } | null)?.retryable !== true) throw err;
      return unjudged(`its judges could not be planned (${err instanceof Error ? err.message : String(err)})`, 'fault');
    }
  }
  if (plan !== null && plan.fallback !== undefined && extend === undefined) {
    const fallback = plan.fallback;
    const picked = plan.judges.map((x) => x.model).join(', ');
    const first = await playProvisionalJudgeHeat(deps, j, dir, ladder, art, { judges: plan.judges, pins: plan.pins });
    if (!('unjudged' in first) || first.cause !== 'fault') return first;
    j.signal?.throwIfAborted();
    const on = fallback === null ? `the bundle's own judge ${namedJudgeAgent(judge.agent)?.model ?? '(none named)'}` : fallback.judges.map((x) => x.model).join(', ');
    log(`[grade] submission ${j.sub.id}: its provisional heat on the overflow judge ${picked} judged nothing, the platform's fault (${first.unjudged}): it is played once more on ${on}, the first heat's calls kept only as blobs`);
    const again = await playProvisionalJudgeHeat(deps, j, dir, ladder, art, fallback);
    if (!('unjudged' in again)) log(`[grade] submission ${j.sub.id}: its provisional heat is judged on ${on}, the overflow judge ${picked} having failed`);
    return again;
  }
  // The one model its calls ask with no plan (namedJudgeAgent): a pool or the house's waits on the judge planner, the platform's fault.
  const agent = namedJudgeAgent(judge.agent);
  if (agent === null && plan === null) return unjudged(JUDGE_NAMES_NO_MODEL, 'fault');
  const jh = await import('./judge-heat.ts');
  const { JUDGE_CALL_ATTEMPTS, JudgeArtifactRefused, JudgeCallFault, judgePreflight, judgeSystemPrompt, openJudgeHeat } = await import('./judge-call.ts');
  const entryId = j.sub.id.toLowerCase();
  // Its setup, on a ladder at every adaptive round of its design (with no ladder the v2 setup), and on a screened
  // bundle's ladder with its money-place scrutiny at the phase's dev line (provisionalScrutinyOf): built before a key is
  // claimed, so it cannot fail after. A top-up's is the one it was handed: its record's, scrutinised.
  const say = (line: string): void => log(`[grade] submission ${j.sub.id}: ${line}`);
  let setup: JudgeHeatSetupT;
  if (extend !== undefined) setup = extend.setup;
  else {
    const scrutiny = ladder === null ? null : await provisionalScrutinyOf(deps, judge, j.ph.id, j.scrutinyLine, say);
    try {
      setup = jh.judgeHeatSetup({
        stage: 'provisional',
        phaseSeed: j.phaseSeed,
        judge,
        entries: [{ entry: entryId, artifact_sha256: art.sha256, artifact_bytes: art.size }],
        anchors: dir.anchors,
        ...(ladder === null
          ? {}
          : {
              rungs: ladder.read.rungs,
              ladder: { ...ladder.block(ladder.read, { rounds: ladder.design.rounds, games: ladder.design.games, spread: ladder.design.spread }, art.sha256), ...(scrutiny === null ? {} : { scrutiny }) },
            }),
        ...(plan === null ? {} : { judges: plan.judges }),
      });
    } catch (err) {
      if (err instanceof jh.JudgeHeatError) return unjudged(`its heat does not set up: ${err.message}`);
      throw err;
    }
  }
  // The subject member: the artifact the heat judges (a top-up's record's, which must be these bytes).
  const subject = setup.field.find((m) => m.entries.length > 0);
  if (subject === undefined || subject.artifact_sha256 !== art.sha256) {
    return unjudged(`its heat's setup judges ${subject === undefined ? 'no entry' : `artifact ${subject.artifact_sha256}`}, and its ${judge.artifact} is ${art.sha256}`);
  }
  // The adaptive rounds its ladder plays: the design's, and the scrutiny's on top when its entry reaches the line.
  const rounds = setup.ladder?.rounds ?? 0;
  const scrutinyRounds = setup.ladder?.scrutiny?.rounds ?? 0;
  // The judge anchors it plays (every one but its own artifact's), two calls each; on a ladder two more each adaptive game.
  const anchorsPlayed = setup.field.filter((m) => m.anchor && m.artifact_sha256 !== art.sha256).length;
  // Its calls: every one of a heat with no scrutiny, at most this many with it (judgeHeatCallsBounded: the scrutiny's
  // rounds played only when its entry reaches the line), so the heat ends when its schedule is complete, and a share of
  // calls with no verdict over the bound's is one no call to come can mend (the record holds it to the calls made).
  const planned = jh.judgeHeatPlannedCalls(setup);
  const plannedWords = judgeHeatCallsBounded(setup) ? `at most ${planned}` : String(planned);
  // Its share judged over the most calls its schedule can still come to (judgeHeatInvalidShareStop: the bound until its scrutiny is decided).
  const shareStop = judgeHeatInvalidShareStop(jh, setup, judge.invalid_share_max);
  // Two an anchor; none when its artifact is the one anchor's bytes (the field then a single member; a ladder heat's
  // setup refuses that above, as it rates against at least one other anchor).
  if (planned === 0) return unjudged(`its ${judge.artifact} is byte for byte the house's only anchor, so there is nothing to play it against`);
  // A top-up's calls kept: its record's, carried verbatim and never sent again; they must be the start of its schedule.
  const keptCalls = extend?.record.calls ?? [];
  if (extend !== undefined) {
    const sc = jh.judgeHeatSchedule(setup, keptCalls);
    if (sc.issue !== null) return unjudged(`record ${extend.sha256}'s calls are not the start of its scrutinised heat: ${sc.issue}`);
    if (sc.complete && sc.planned.length === keptCalls.length) return unjudged(`record ${extend.sha256}'s heat owes no call at the line ${setup.ladder?.scrutiny?.line_micro ?? '(none)'}: there is nothing to top up`);
  }
  // The calls this heat's key sends: those past the kept ones.
  const toSend = planned - keptCalls.length;
  // A plan whose every judge is on OpenRouter needs no house broker, and takes no seat in the judge pool (no client-side cap on that door).
  const offHouse = plan !== null && plan.judges.every((x) => x.door === 'openrouter');
  let broker: MasqJudgeKeyBroker | null;
  try {
    broker = await judgeBrokerOf(deps);
  } catch (err) {
    if (!offHouse) return unjudged(`the LLM gateway is not configured (${err instanceof Error ? err.message : String(err)})`, 'fault');
    broker = null;
  }
  // On a plan, the planner's broker over the house's (plan.ts broker): every key of the heat minted and retired through it.
  if (plan !== null && planner !== undefined && (broker !== null || offHouse)) broker = planner.broker(broker);
  if (broker === null) return unjudged("this process has no LLM gateway (MAKEFUN_LLM_GATEWAY=masq, its URL and admin key) and no superbot-router pair (MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_KEY) to send the house judge's calls through", 'fault');
  // Every artifact a call may carry: the anchors, on a ladder its rungs, and the entry's.
  const artifacts = new Map(dir.artifacts);
  if (ladder !== null) for (const [sha256, bytes] of ladder.read.artifacts) artifacts.set(sha256, bytes);
  artifacts.set(art.sha256, art.bytes);
  const list = [...artifacts].map(([sha256, bytes]) => ({ sha256, bytes }));
  // Its calls still to send (all its planned ones, past a top-up's kept ones), and room for the one a fault sends again.
  const calls = toSend + 1;
  // Its worst case (judgePreflight, handed no cap): an anchor or rung no call can carry, or a judge model with no price,
  // holds it before a key is claimed. No spend is weighed against it. On a plan, the pool heat's own (judgePoolPreflight),
  // where a pin that cannot see an image holds it: the planner's pick, so the platform's fault.
  try {
    const pre =
      plan === null
        ? judgePreflight({ agent: agent!, system: judgeSystemPrompt(dir.prompt, setup.house_text), media: judge.media, house: setup.house_text, artifacts: list, calls, at: now().toISOString() })
        : (await import('../server/judging/pool-heat.ts')).judgePoolPreflight({ prompt: dir.prompt, media: judge.media, house: setup.house_text, artifacts: list, calls, now: () => now().getTime() }, plan);
    if (pre.hold !== null) return unjudged(pre.hold.why, pre.hold.kind === 'unpriced' ? 'unpriced' : plan !== null && pre.hold.kind === 'vision' ? 'fault' : 'other');
  } catch (err) {
    if (err instanceof JudgeArtifactRefused) return unjudged(`the judge refuses the house ${ladder === null ? 'anchor' : 'anchor or rung'} ${err.sha256}: ${err.message}`);
    throw err;
  }
  // Its key's attempt number, claimed among the phase's kept keys (the header's `judge keys`): no other key is read.
  const keysDir = judgeKeysDir(deps.blobs, j.ph.id);
  const mine = await claimJudgeKey(
    keysDir,
    {
      format: JUDGE_KEY_FORMAT,
      phase_id: j.ph.id.toLowerCase(),
      stage: 'provisional',
      at: now().toISOString(),
      key_id: null,
      label: null,
      reserved_micro_usd: '0',
      meter_micro_usd: '0',
      masq_micro_usd: null,
      open: true,
    },
    1,
  );
  let opening: Awaited<ReturnType<typeof openJudgeHeat>>;
  try {
    // A key with no dollar cap (masq mints it uncapped; the router's key is static and uncapped).
    const options = {
      broker,
      key: { slug: j.comp.slug, phase: 'dev' as const, attempt: mine.attempt },
      prompt: dir.prompt,
      media: judge.media,
      house: setup.house_text,
      artifacts: list,
      calls,
      blobs: deps.blobs,
      ...(deps.judge?.fetch === undefined ? {} : { fetch: deps.judge.fetch }),
      ...(deps.judge?.timeoutMs === undefined ? {} : { timeoutMs: deps.judge.timeoutMs }),
      now: () => now().getTime(),
      ...(j.signal === undefined ? {} : { signal: j.signal }),
    };
    // On a plan, the pool heat on its judge (server/judging/pool-heat.ts), which notes the forms memo under each judge's own model.
    const seen = plan === null ? undefined : judgeFormsSeenOf(deps);
    opening = plan === null ? await openJudgeHeat({ ...options, agent: agent! }) : await (await import('../server/judging/pool-heat.ts')).openJudgePoolHeat({ ...options, ...(seen === undefined ? {} : { formsSeen: seen }) }, plan);
  } catch (err) {
    await dropJudgeKey(keysDir, mine);
    if (j.signal?.aborted === true) throw err;
    const { MasqBrokerError } = await import('./gateway/masq.ts');
    // A JudgePlanFault (retryable: OpenRouter's key unset when its judge's key is minted) is the platform's too.
    const platform = err instanceof MasqBrokerError || err instanceof JudgeCallFault || (plan !== null && (err as { retryable?: unknown } | null)?.retryable === true);
    return unjudged(`its judge key did not open (${err instanceof Error ? err.message : String(err)})`, platform ? 'fault' : 'other');
  }
  if (opening.held !== null) {
    if (opening.retired === null) await dropJudgeKey(keysDir, mine);
    else await writeJudgeKey(keysDir, retiredJudgeKey({ ...mine, key_id: opening.retired.id }, 0n, opening.retired));
    // An unpriced model or one that cannot see images: no cap is handed to the heat, so no budget holds it.
    return unjudged(opening.held.why, opening.held.kind === 'unpriced' ? 'unpriced' : 'other');
  }
  const heat = opening.heat;
  const minted = await writeJudgeKey(keysDir, { ...mine, key_id: heat.key.id, label: heat.key.label });
  // A top-up's kept calls and their spares first, verbatim: sendJudgeHeatCalls sends only the calls planned past them.
  const done: JudgeHeatCallT[] = [...keptCalls];
  // The kept calls' other sends (a backup's, or the primary a backup decided before), in memory until the record.
  const spares: JudgeHeatSpareT[] = [...(extend?.record.spares ?? [])];
  let resent = 0;
  const stopped: { failed: string | null; cause: ProvisionalUnjudgedCause } = { failed: null, cause: 'other' };
  const fault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault;
  // A fault superbot-router answered finally (judge-call.ts JudgeCallFault.final): no layer sends that call again.
  const finalFault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault && s.err.final;
  const { judgeBackupRuleOf } = await import('./judge-backup.ts');
  const { ROUTER_KEY_ID_PREFIX } = await import('../server/superbot-router.ts');
  const formsSeen = judgeFormsSeenOf(deps);
  // Its seat in the platform's one budget of judge sends in flight (the header's `judge heat`), held while it sends; none off the house's doors.
  const seat = offHouse ? null : await judgePoolSeatOf(deps, heat.key.label, 'practice', (line) => log(`[grade] submission ${j.sub.id}: provisional ${line}`));
  try {
    // Its calls up to min(its width, its share of JUDGE_POOL_BUDGET) at once, each kept in planned order, the last of a batch backed up (sendJudgeHeatCalls).
    await sendJudgeHeatCalls({
      heat,
      setup,
      calls: done,
      concurrency: deps.judge?.concurrency ?? JUDGE_HEAT_CONCURRENCY,
      ...(seat === null ? {} : { seat }),
      ...(j.signal === undefined ? {} : { signal: j.signal }),
      // The deps' rule if any (null: none), else the house's: each call sent once on a router key, JUDGE_BACKUP on masq's.
      // A plan's pool heat takes no backup (each call sent once), and notes the forms memo itself.
      backup: plan !== null ? null : judgeBackupRuleOf(deps.judge?.backup, heat.key.id.startsWith(ROUTER_KEY_ID_PREFIX)),
      ...(deps.judge?.clock === undefined ? {} : { clock: deps.judge.clock }),
      ...(formsSeen === undefined || plan !== null ? {} : { formsSeen }),
      callsTotal: planned,
      // Its one fault re-send's requests (the key's planned + 1 calls), held back from a backup while unspent.
      reserveRequests: () => (resent === 0 ? JUDGE_CALL_ATTEMPTS : 0),
      log: (line) => log(`[grade] submission ${j.sub.id}: provisional ${line}`),
      doomed: (ahead) =>
        ahead.some((s) => !s.ok && !fault(s)) ||
        ahead.some(finalFault) ||
        resent + ahead.filter(fault).length > 1 ||
        shareStop(done, done.filter((c) => c.verdict === null).length + ahead.filter((s) => s.ok && s.answer.verdict === null).length, done.length + ahead.length) !== null,
      take: async (next, sent, callSpares) => {
        if (!sent.ok) {
          const err = sent.err;
          if (!(err instanceof JudgeCallFault)) throw err;
          if (j.signal?.aborted === true) throw j.signal.reason instanceof Error ? j.signal.reason : err;
          // The router answered it finally: never sent again in this attempt (the fault's, as a second fault is: the job retried).
          if (err.final) {
            stopped.failed = `call ${done.length + 1} of ${plannedWords} faulted (${err.message}): the router answered it finally, so it is not sent again in this attempt`;
            stopped.cause = 'fault';
            return 'stop';
          }
          if (resent === 0) {
            log(`[grade] submission ${j.sub.id}: provisional judge call ${done.length + 1} of ${plannedWords} faulted (${err.message}): it is sent again, the heat's one`);
            resent = 1;
            return 'again';
          }
          stopped.failed = `call ${done.length + 1} of ${plannedWords} faulted (${err.message}) after the heat had sent one faulted call again`;
          stopped.cause = 'fault';
          return 'stop';
        }
        try {
          done.push(jh.judgeHeatCallOf(next, sent.answer));
        } catch (err) {
          if (!(err instanceof jh.JudgeHeatError)) throw err;
          stopped.failed = err.message;
          return 'stop';
        }
        spares.push(...callSpares);
        const invalid = done.filter((c) => c.verdict === null).length;
        const most = shareStop(done, invalid, done.length);
        if (most !== null) {
          stopped.failed = `${invalid} of its heat's ${judgeHeatCallsBounded(setup) ? `at most ${most}` : String(most)} calls came back with no verdict, over judge.invalid_share_max ${judge.invalid_share_max}`;
          return 'stop';
        }
        return 'kept';
      },
    });
  } finally {
    // Its seat given back whatever came of the heat (it never throws).
    await seat?.close();
    // Retired whatever came of the heat, once every call in flight settled; what it spent kept in its key's file.
    const retired = await heat.retire().catch((err: unknown) => {
      log(`[grade] submission ${j.sub.id}: its provisional judge key ${heat.key.label} could not be retired (${err instanceof Error ? err.message : String(err)}): masq lets it lapse`);
      return null;
    });
    if (retired !== null && retired.flags.length > 0) log(`[grade] submission ${j.sub.id}: retired its provisional judge key ${heat.key.label}: ${retired.flags.join('; ')}`);
    await writeJudgeKey(keysDir, retired === null ? { ...minted, meter_micro_usd: String(heat.meterMicroUsd()) } : retiredJudgeKey(minted, heat.meterMicroUsd(), retired));
  }
  if (stopped.failed !== null) return unjudged(stopped.failed, stopped.cause);
  // The record held once, its digest and its verdicts with it (judge-heat.ts judgeHeatRecordEnd): a provisional heat's is
  // a few dozen calls, built here; a final's goes off this thread (judgeCodeHeat).
  let end: ReturnType<typeof jh.judgeHeatRecordEnd>;
  try {
    end = jh.judgeHeatRecordEnd(setup, done, spares);
  } catch (err) {
    if (!(err instanceof jh.JudgeHeatError)) throw err;
    return unjudged(err.message);
  }
  const { record } = end;
  const digest = { json: end.json, sha256: end.sha256 };
  const put = await deps.blobs.put(digest.json);
  if (put.sha256 !== digest.sha256) throw new Error(`submission ${j.sub.id}'s provisional judge heat record stored as ${put.sha256}, not ${digest.sha256}`);
  if (end.verdicts === null) throw new jh.JudgeHeatError(end.verdictsIssue!);
  // The verdict on its artifact (judgeHeatHeldVerdicts, keyed by artifact: a top-up's record may judge another entry on these bytes, whose verdict this run reused).
  const verdict = extend === undefined ? end.verdicts.get(entryId) : jh.judgeHeatHeldVerdicts(record).get(art.sha256);
  if (verdict === undefined) throw new Error(`submission ${j.sub.id}'s provisional judge heat record ${digest.sha256} holds no verdict on it`);
  // The adaptive rounds played: two calls a game, `games` games a round (the design's, and the scrutiny's when reached).
  const games = setup.ladder?.games ?? 0;
  const adaptiveCalls = record.calls.filter((c) => c.stage === 'adaptive').length;
  return {
    verdict,
    judge_heat_sha256: digest.sha256,
    anchors: anchorsPlayed,
    calls: record.calls.length,
    invalid_calls: record.invalid_calls,
    micro_usd: record.totals.micro_usd,
    ...(setup.ladder === undefined ? {} : { adaptive: { rounds: games === 0 ? 0 : adaptiveCalls / (2 * games), of: rounds + scrutinyRounds, games } }),
    ...(setup.ladder?.scrutiny === undefined ? {} : { scrutiny: { line_micro: setup.ladder.scrutiny.line_micro, rounds: scrutinyRounds, reached: adaptiveCalls > 2 * rounds * games } }),
    ...(extend === undefined ? {} : { extended: { judge_heat_sha256: extend.sha256, kept_calls: keptCalls.length } }),
  };
}

// ---------------------------------------------------------------- the dev contender rounds

/** Where a dev phase's contender round keeps its judge calls as they settle (playContenderRound): a file of the work root, one per dev phase. */
export function judgeContenderPartialPath(workRoot: string, phaseId: string): string {
  return join(workRoot, `judge-contender-partial-${phaseId.toLowerCase()}.json`);
}

/**
 * A contender round's `ladder` block (grader/judge-contender.ts JudgeContenderLadder) from the bundle's sealed ladder as
 * readJudgeLadder read it: its tree and calibration digests, every house member's fixed strength and the judge anchors
 * among them, each in sha256 order, and phi. What playContenderRound holds a round's setup to.
 */
export function judgeContenderLadderOf(read: Pick<JudgeLadderInputs, 'ladder_sha256' | 'calibration_sha256' | 'members' | 'strengths' | 'dispersion'>): JudgeContenderLadderT {
  return {
    ladder_sha256: read.ladder_sha256,
    calibration_sha256: read.calibration_sha256,
    strengths: read.strengths.map((s) => ({ artifact_sha256: s.artifact_sha256, strength: s.strength })).sort((x, y) => compareCodeUnits(x.artifact_sha256, y.artifact_sha256)),
    anchors: read.members
      .filter((m) => m.anchor)
      .map((m) => m.artifact_sha256)
      .sort(compareCodeUnits),
    dispersion: read.dispersion,
  };
}

/** What a dev contender round plays (playContenderRound). */
export interface ContenderRoundInput {
  /** The competition: where its judge directory and ladder are read (judgedTreesOf), and its judge key's label. */
  slug: string;
  harness: ProgramHarnessT;
  /** The bundle's judge block: one named model, on a ladder. */
  judge: ProgramJudgeT;
  /** The dev phase: where the round's key is kept (judgeKeysDir) and its calls (judgeContenderPartialPath). */
  devPhaseId: string;
  /** The chain before the round (grader/judge-contender.ts judgeContenderFold), null before round 0: what the round follows. */
  fold: JudgeContenderFoldT | null;
  setup: JudgeContenderSetupT;
  /** The round's calls, two a pair: judgeContenderSchedule(fold, setup).planned, held to it again. */
  planned: readonly JudgePlannedCallT[];
  /** The players' artifact bytes by sha256: every one a planned call names. */
  artifacts: ReadonlyMap<string, Uint8Array>;
  signal?: AbortSignal;
}

/**
 * Why a contender round recorded nothing (as a provisional heat's ProvisionalUnjudgedCause): `fault` the platform's (a
 * call that faulted again after the round's one re-send, one the router answered finally, a key masq did not mint or
 * retire, no gateway), so the job is tried again from the calls kept; `unpriced` a judge model with no price; `other` the
 * round's own end (no judge, ladder or artifact the round can be played on, too many calls with no verdict...).
 */
export type ContenderRoundCause = 'fault' | 'unpriced' | 'other';

/** A contender round's end: its record, stored as a blob under its sha256, and how many of its calls an earlier attempt kept; or why it recorded nothing. */
export type ContenderRoundEnd = { record: JudgeContenderRecordT; sha256: string; kept_calls: number } | { unplayed: string; cause: ContenderRoundCause };

/**
 * A text a contender round says (its log lines and its `unplayed` reasons) with every sha256 in it masked: a round is
 * sealed (no record, no sha256 of one, no member of it shown before the deadline), so what it says carries counts only.
 */
function contenderSealed(text: string): string {
  return text.replace(/[0-9a-f]{64}/g, '(sha256)');
}

/** The first settled call that is not the round's call at its place, or one past its last; null when none (sendJudgeHeatCalls' schedule issue). */
function contenderKeptIssue(planned: readonly JudgePlannedCallT[], settled: readonly Pick<JudgeHeatCallT, 'stage' | 'round' | 'a' | 'b' | 'slot_order'>[]): string | null {
  if (settled.length > planned.length) return `call ${planned.length + 1}: the round makes ${planned.length} calls`;
  for (let i = 0; i < settled.length; i++) {
    const c = settled[i]!;
    const p = planned[i]!;
    if (c.stage !== p.stage || c.round !== p.round || c.a !== p.a || c.b !== p.b || c.slot_order !== p.slot_order) return `call ${i + 1} is not the round's call at its place`;
  }
  return null;
}

/**
 * The calls an earlier attempt kept for this round (playContenderRound), when they are this round's (its resume key,
 * judgeContenderResumeKey) and each the call planned at its place, holding as a contender call does (a race call of the
 * round, no `judge` index, its margin as a v2 call carries it), its spares naming kept calls; else none, said under
 * `say`. Another round's partial passes on only its open key (the next attempt retires it first) and its key count:
 * its calls and spend were that round's, which never recorded.
 */
async function keptContenderRound(store: CodeHeatPartialStore, key: string, planned: readonly JudgePlannedCallT[], say: (line: string) => void): Promise<JudgeHeatPartialT> {
  const jh = await import('./judge-heat.ts');
  const fresh: JudgeHeatPartialT = { format: jh.JUDGE_HEAT_PARTIAL_FORMAT, key, calls: [], spent_micro_usd: '0', resent: 0, keys: 0, open_key: null };
  const text = await store.read();
  if (text === null) return fresh;
  let parsed: JudgeHeatPartialT;
  try {
    parsed = jh.JudgeHeatPartial.parse(JSON.parse(text));
  } catch (err) {
    say(`the judge calls kept do not read (${err instanceof Error ? err.message : String(err)}): the round is judged from its first call`);
    return fresh;
  }
  if (parsed.key !== key) {
    if (parsed.calls.length > 0) say(`the ${parsed.calls.length} judge calls kept are another round's: this round is judged from its first call`);
    return { ...fresh, keys: parsed.keys, open_key: parsed.open_key };
  }
  const issueOf = (): string | null => {
    const at = contenderKeptIssue(planned, parsed.calls);
    if (at !== null) return at;
    for (const [i, c] of parsed.calls.entries()) {
      if (c.judge !== undefined) return `call ${i + 1} names a judge index`;
      if (c.margin === undefined || (c.margin === null) !== (c.verdict === null)) return `call ${i + 1} carries no margin for its verdict`;
      const issues = jh.judgeHeatCallIssues(c);
      if (issues.length > 0) return `call ${i + 1}: ${issues[0]}`;
    }
    for (const [k, x] of (parsed.spares ?? []).entries()) {
      if (x.call >= parsed.calls.length) return `spare ${k + 1} names no kept call`;
      const issues = jh.judgeHeatSpareIssues(x);
      if (issues.length > 0) return `spare ${k + 1}: ${issues[0]}`;
    }
    return null;
  };
  const issue = issueOf();
  const { judges: _judges, screen: _screen, ...own } = parsed;
  if (issue !== null) {
    say(`the ${parsed.calls.length} judge calls kept are dropped (${issue}): the round is judged from its first call`);
    return judgeHeatPartialSpares({ ...own, calls: [], resent: 0 }, []);
  }
  return own;
}

/**
 * Play one sealed dev contender round (grader/judge-contender.ts; the bundle's judge.screened.contender_games) and store
 * its record: what a provisional heat is (playProvisionalJudgeHeat) for a round of contender games. Its judge directory
 * and ladder read as provisionalJudgeHeat reads them (judgedTreesOf, readJudgeTree, readJudgeLadder), the setup held to
 * them (its judge the bundle's block, its ladder judgeContenderLadderOf of the sealed one) and its calls to the round's
 * schedule over the chain (judgeContenderSchedule), every player's artifact one the judge reads; then judgePreflight
 * (handed no cap: an artifact no call carries, or a judge model with no price, holds the round before any key).
 *
 * Its key is claimed among the dev phase's kept keys (judgeKeysDir) as stage 'provisional', its pool seat and log
 * lines labelled with the round, and opened (openJudgeHeat) on the bundle's one named model: never a pool, the overflow
 * switch or a planner's pick, which a round is never played on (the job defers it instead). Its calls go out through a
 * 'contender' seat in the judge pool (judgePoolShares: only what every other seat's share leaves; one send in flight
 * at least) at width JUDGE_HEAT_CONCURRENCY, backed up by the house's rule (judgeBackupRuleOf), a faulted call sent once
 * again (a second fault, or one the router answered finally, ends the round 'fault'), and no more calls with no verdict
 * than invalid_share_max allows.
 *
 * Each call is kept as it settles in the phase's partial (judgeContenderPartialPath, the JudgeHeatPartial format) under
 * the round's resume key (judgeContenderResumeKey): a retried job sends only the calls still to come, and never asks a
 * kept one again; a round whose every call is kept sends nothing and opens no key. The key is retired whatever happens
 * (an abort and an error no round expects too, then thrown), what it spent kept in its file. The record
 * (judgeContenderRecordOf after `fold`) is stored as a blob before it is returned. Every log line and reason carries
 * counts only, every sha256 masked (contenderSealed): the record, its sha256 and its members are sealed until the
 * deadline. It writes no run, score or entry_artifact row.
 */
export async function playContenderRound(deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'workRoot' | 'competitionDir' | 'judge' | 'log' | 'now'>, j: ContenderRoundInput): Promise<ContenderRoundEnd> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  const { judge } = j;
  const unplayed = (why: string, cause: ContenderRoundCause = 'other'): ContenderRoundEnd => ({ unplayed: contenderSealed(why), cause });
  const jc = await import('./judge-contender.ts');
  const jh = await import('./judge-heat.ts');
  const parsedSetup = jc.JudgeContenderSetup.safeParse(j.setup);
  if (!parsedSetup.success) return unplayed(`the round's setup is not one: ${parsedSetup.error.issues.map((i) => `${i.path.join('.') || '(setup)'}: ${i.message}`)[0] ?? 'malformed'}`);
  const setup = parsedSetup.data;
  const say = (line: string): void => log(contenderSealed(`[contender] ${j.slug} round ${setup.round}: ${line}`));
  // The bundle's one named model on its own door, on its ladder: a round is judged on nothing else.
  const agent = namedJudgeAgent(judge.agent);
  if (agent === null) return unplayed("the bundle's judge names no one model: a contender round is judged only by the bundle's own named judge");
  if (judge.ladder === undefined) return unplayed("the bundle's judge names no ladder (harness.judge.ladder): a contender round rates on one");
  const bundleJudge = { agent: judge.agent, judge_sha256: judge.judge_sha256, media: judge.media, artifact: judge.artifact, invalid_share_max: judge.invalid_share_max };
  const setupJudge = { agent: setup.agent, judge_sha256: setup.judge_sha256, media: setup.media, artifact: setup.artifact, invalid_share_max: setup.invalid_share_max };
  if (canonicalJson(setupJudge) !== canonicalJson(bundleJudge)) return unplayed("the round's judge (its model, directory, media, artifact or invalid share) is not the bundle's judge block");
  // Its judge directory and ladder, read and held as a provisional heat reads them.
  let trees: JudgedTrees;
  try {
    trees = await judgedTreesOf(deps, j.slug, j.harness, judge);
  } catch (err) {
    if (err instanceof PermanentJobError) return unplayed(err.message);
    throw err;
  }
  const dir = await readJudgeTreeAsync(trees.judgeDir, judge);
  if ('refused' in dir) return unplayed(dir.refused);
  const { readJudgeLadderAsync } = await import('./judge-ladder-tree.ts');
  const read = await readJudgeLadderAsync(judgeLadderDirOf(deps, j.slug, j.harness, judge.ladder, trees), judge, trees.judgeDir);
  if ('refused' in read) return unplayed(`its judge's ladder does not read: ${read.refused}`);
  if (canonicalJson(setup.ladder) !== canonicalJson(judgeContenderLadderOf(read))) return unplayed("the round's ladder (its digests, strengths, anchors or phi) is not the bundle's sealed one");
  // Its calls: the round's schedule over the chain, which the calls handed in must be.
  let planned: JudgePlannedCallT[];
  try {
    planned = jc.judgeContenderSchedule(j.fold, setup).planned;
  } catch (err) {
    if (err instanceof jh.JudgeHeatError) return unplayed(`the round does not follow the chain: ${err.message}`);
    throw err;
  }
  if (planned.length === 0) return unplayed('the round is empty: no pair to judge');
  if (j.planned.length !== planned.length || contenderKeptIssue(planned, j.planned) !== null) return unplayed("the calls handed in are not the round's schedule over the chain");
  // Every player's artifact a call carries, by its bytes, one the judge reads.
  const named = [...new Set(planned.flatMap((p) => [p.a, p.b]))].sort(compareCodeUnits);
  const list: { sha256: string; bytes: Uint8Array }[] = [];
  for (const sha256 of named) {
    const bytes = j.artifacts.get(sha256);
    if (bytes === undefined) return unplayed(`a player's ${judge.artifact} was not handed in`);
    if (sha256Hex(bytes) !== sha256) return unplayed(`a player's ${judge.artifact} bytes do not hash to its name`);
    const refused = await judgeArtifactRefusal(judge.media, { sha256, bytes });
    if (refused !== null) return unplayed(`the judge cannot read a player's ${judge.artifact} (${refused})`);
    list.push({ sha256, bytes });
  }
  const { JUDGE_CALL_ATTEMPTS, JudgeArtifactRefused, JudgeCallFault, judgePreflight, judgeSystemPrompt, openJudgeHeat } = await import('./judge-call.ts');
  // The calls an earlier attempt kept for this round, never asked again.
  const { codeHeatPartialFile } = await import('./code-heat.ts');
  await mkdir(deps.workRoot, { recursive: true });
  const store = codeHeatPartialFile(judgeContenderPartialPath(deps.workRoot, j.devPhaseId));
  let p = await keptContenderRound(store, jc.judgeContenderResumeKey(setup), planned, say);
  const save = async (next: JudgeHeatPartialT): Promise<void> => {
    p = next;
    await store.write(canonicalJson(next));
  };
  const calls: JudgeHeatCallT[] = [...p.calls];
  const keptCalls = calls.length;
  const owed = planned.length - calls.length;
  // Its worst case over the calls still to come and the one a fault sends again (judgePreflight, handed no cap).
  const callsCap = owed + (p.resent === 0 ? 1 : 0);
  if (owed > 0) {
    try {
      const pre = judgePreflight({ agent, system: judgeSystemPrompt(dir.prompt, setup.house_text), media: judge.media, house: setup.house_text, artifacts: list, calls: callsCap, at: now().toISOString() });
      if (pre.hold !== null) return unplayed(pre.hold.why, pre.hold.kind === 'unpriced' ? 'unpriced' : 'other');
    } catch (err) {
      if (err instanceof JudgeArtifactRefused) return unplayed(`the judge refuses a player's ${judge.artifact}: ${err.message}`);
      throw err;
    }
  }
  const keysDir = judgeKeysDir(deps.blobs, j.devPhaseId);
  if (owed > 0 || p.open_key !== null) {
    let broker: MasqJudgeKeyBroker | null;
    try {
      broker = await judgeBrokerOf(deps);
    } catch (err) {
      return unplayed(`the LLM gateway is not configured (${err instanceof Error ? err.message : String(err)})`, 'fault');
    }
    if (broker === null) return unplayed("this process has no LLM gateway (MAKEFUN_LLM_GATEWAY=masq, its URL and admin key) and no superbot-router pair (MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_KEY) to send the house judge's calls through", 'fault');
    const { MasqBrokerError, retireTrialKey } = await import('./gateway/masq.ts');
    // A key an earlier attempt left open (it stopped mid-round): retired first, against what it metered.
    if (p.open_key !== null) {
      const open = p.open_key;
      let retired: RetiredTrialKey;
      try {
        retired = await retireTrialKey(broker, open.id, BigInt(open.meter_micro_usd));
      } catch (err) {
        return unplayed(`its key ${open.label}, which an earlier attempt left open, could not be retired (${err instanceof Error ? err.message : String(err)})`, 'fault');
      }
      say(`retired key ${open.label}, which an earlier attempt left open${retired.flags.length === 0 ? '' : ` (${retired.flags.join('; ')})`}`);
      const k = (await readJudgeKeys(keysDir, now())).find((x) => x.key_id === open.id);
      if (k !== undefined) await writeJudgeKey(keysDir, retiredJudgeKey(k, BigInt(open.meter_micro_usd), retired));
      await save({ ...p, open_key: null });
    }
    if (owed > 0) {
      const mine = await claimJudgeKey(
        keysDir,
        { format: JUDGE_KEY_FORMAT, phase_id: j.devPhaseId.toLowerCase(), stage: 'provisional', at: now().toISOString(), key_id: null, label: null, reserved_micro_usd: '0', meter_micro_usd: '0', masq_micro_usd: null, open: true },
        1,
      );
      let opening: Awaited<ReturnType<typeof openJudgeHeat>>;
      try {
        // A key with no dollar cap, on the bundle's one named model (masq mints it uncapped; the router's is static).
        opening = await openJudgeHeat({
          broker,
          key: { slug: j.slug, phase: 'dev', attempt: mine.attempt },
          agent,
          prompt: dir.prompt,
          media: judge.media,
          house: setup.house_text,
          artifacts: list,
          calls: callsCap,
          blobs: deps.blobs,
          ...(deps.judge?.fetch === undefined ? {} : { fetch: deps.judge.fetch }),
          ...(deps.judge?.timeoutMs === undefined ? {} : { timeoutMs: deps.judge.timeoutMs }),
          now: () => now().getTime(),
          ...(j.signal === undefined ? {} : { signal: j.signal }),
        });
      } catch (err) {
        await dropJudgeKey(keysDir, mine);
        if (j.signal?.aborted === true) throw err;
        if (err instanceof JudgeArtifactRefused) return unplayed(`the judge refuses a player's ${judge.artifact}: ${err.message}`);
        const platform = err instanceof MasqBrokerError || err instanceof JudgeCallFault;
        return unplayed(`its judge key did not open (${err instanceof Error ? err.message : String(err)})`, platform ? 'fault' : 'other');
      }
      if (opening.held !== null) {
        if (opening.retired === null) await dropJudgeKey(keysDir, mine);
        else await writeJudgeKey(keysDir, retiredJudgeKey({ ...mine, key_id: opening.retired.id }, 0n, opening.retired));
        return unplayed(opening.held.why, opening.held.kind === 'unpriced' ? 'unpriced' : 'other');
      }
      const heat = opening.heat;
      const minted = await writeJudgeKey(keysDir, { ...mine, key_id: heat.key.id, label: heat.key.label });
      const base = BigInt(p.spent_micro_usd);
      const spentNow = (): string => String(base + heat.meterMicroUsd());
      const openKey = (): JudgeHeatPartialT['open_key'] => ({ id: heat.key.id, label: heat.key.label, meter_micro_usd: String(heat.meterMicroUsd()) });
      await save({ ...p, keys: p.keys + 1, open_key: openKey() });
      say(`judging ${planned.length / 2} games in ${planned.length} calls, ${keptCalls} kept from an earlier attempt, on key ${heat.key.label}`);
      const fault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault;
      // A fault superbot-router answered finally (judge-call.ts JudgeCallFault.final): no layer sends that call again.
      const finalFault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault && s.err.final;
      const invalidOver = (invalid: number): boolean => jh.judgeHeatInvalidShareOver(invalid, planned.length, setup.invalid_share_max);
      // Why the round stopped, and whether its calls are kept for the retry (not when they already fail the round).
      const stopped: { failed: string | null; cause: ContenderRoundCause; keep: boolean } = { failed: null, cause: 'other', keep: true };
      const { judgeBackupRuleOf } = await import('./judge-backup.ts');
      const { ROUTER_KEY_ID_PREFIX } = await import('../server/superbot-router.ts');
      const formsSeen = judgeFormsSeenOf(deps);
      // Its seat in the judge pool, class 'contender': what every other seat's share leaves (judgePoolShares).
      const seat = await judgePoolSeatOf(deps, `${heat.key.label} contender round ${setup.round}`, 'contender', say);
      try {
        await sendJudgeHeatCalls({
          heat,
          setup,
          calls,
          concurrency: deps.judge?.concurrency ?? JUDGE_HEAT_CONCURRENCY,
          ...(seat === null ? {} : { seat }),
          ...(j.signal === undefined ? {} : { signal: j.signal }),
          // The deps' rule if any (null: none), else the house's: each call sent once on a router key, JUDGE_BACKUP on masq's.
          backup: judgeBackupRuleOf(deps.judge?.backup, heat.key.id.startsWith(ROUTER_KEY_ID_PREFIX)),
          ...(deps.judge?.clock === undefined ? {} : { clock: deps.judge.clock }),
          ...(formsSeen === undefined ? {} : { formsSeen }),
          // The round's calls, all known at once (one batch): its schedule never moves with its results.
          schedule: (_setup, settled) => ({ planned: [...planned], complete: true, finalists: null, issue: contenderKeptIssue(planned, settled) }),
          callsTotal: planned.length,
          // Its one fault re-send's requests, held back from a backup while unspent.
          reserveRequests: () => (p.resent === 0 ? JUDGE_CALL_ATTEMPTS : 0),
          log: say,
          doomed: (ahead) =>
            ahead.some((s) => !s.ok && !fault(s)) ||
            ahead.some(finalFault) ||
            p.resent + ahead.filter(fault).length > 1 ||
            invalidOver(calls.filter((c) => c.verdict === null).length + ahead.filter((s) => s.ok && s.answer.verdict === null).length),
          take: async (next, sent, callSpares) => {
            if (!sent.ok) {
              const err = sent.err;
              if (!(err instanceof JudgeCallFault)) throw err;
              if (j.signal?.aborted === true) throw j.signal.reason instanceof Error ? j.signal.reason : err;
              if (err.final) {
                stopped.failed = `call ${calls.length + 1} of ${planned.length} faulted (${err.message}): the router answered it finally, so it is not sent again in this attempt`;
                stopped.cause = 'fault';
                return 'stop';
              }
              if (p.resent === 0) {
                say(`call ${calls.length + 1} of ${planned.length} faulted (${err.message}): it is sent again, the round's one`);
                await save({ ...p, resent: 1, spent_micro_usd: spentNow(), open_key: openKey() });
                return 'again';
              }
              stopped.failed = `call ${calls.length + 1} of ${planned.length} faulted (${err.message}) after the round had sent one faulted call again`;
              stopped.cause = 'fault';
              return 'stop';
            }
            try {
              calls.push(jh.judgeHeatCallOf(next, sent.answer));
            } catch (err) {
              if (!(err instanceof jh.JudgeHeatError)) throw err;
              stopped.failed = err.message;
              return 'stop';
            }
            // The call and its spares in one save: a partial's spares name only the calls it keeps.
            await save(judgeHeatPartialSpares({ ...p, calls: [...calls], spent_micro_usd: spentNow(), open_key: openKey() }, [...(p.spares ?? []), ...callSpares]));
            const invalid = calls.filter((c) => c.verdict === null).length;
            if (invalidOver(invalid)) {
              stopped.failed = `${invalid} of the round's ${planned.length} calls came back with no verdict, over judge.invalid_share_max ${setup.invalid_share_max}`;
              stopped.keep = false;
              return 'stop';
            }
            return 'kept';
          },
        });
      } finally {
        // Its seat given back (it never throws), and its key retired whatever came of the round, once every call in flight
        // settled: what it spent kept in its key's file and on the partial, the key left on the partial only when masq did not answer.
        await seat?.close();
        const retired = await heat.retire().catch((err: unknown) => {
          say(`its judge key ${heat.key.label} could not be retired (${err instanceof Error ? err.message : String(err)}): the next attempt retires it`);
          return null;
        });
        if (retired !== null && retired.flags.length > 0) say(`retired its judge key ${heat.key.label}: ${retired.flags.join('; ')}`);
        await writeJudgeKey(keysDir, retired === null ? { ...minted, meter_micro_usd: String(heat.meterMicroUsd()) } : retiredJudgeKey(minted, heat.meterMicroUsd(), retired));
        await save({ ...p, spent_micro_usd: spentNow(), open_key: retired === null ? openKey() : null });
      }
      if (stopped.failed !== null) {
        // The calls kept for the retry (the re-send its own again), unless they already fail the round.
        await save(stopped.keep ? { ...p, resent: 0 } : judgeHeatPartialSpares({ ...p, calls: [], resent: 0 }, []));
        say(`nothing recorded: ${stopped.failed}`);
        return unplayed(stopped.failed, stopped.cause);
      }
    }
  }
  let record: JudgeContenderRecordT;
  try {
    record = jc.judgeContenderRecordOf(j.fold, setup, calls, p.spares ?? []);
  } catch (err) {
    if (!(err instanceof jh.JudgeHeatError)) throw err;
    await save(judgeHeatPartialSpares({ ...p, calls: [], resent: 0 }, []));
    return unplayed(`the round's record does not hold: ${err.message}`);
  }
  const digest = jc.judgeContenderRecordDigest(record);
  const put = await deps.blobs.put(digest.json);
  if (put.sha256 !== digest.sha256) throw new Error(contenderSealed(`${j.slug}'s contender round ${setup.round} record stored as ${put.sha256}, not ${digest.sha256}`));
  say(`recorded ${record.games.length} games in ${record.calls.length} calls (${keptCalls} kept from an earlier attempt, ${record.invalid_calls} with no verdict, ${record.totals.micro_usd} µUSD)`);
  return { record, sha256: digest.sha256, kept_calls: keptCalls };
}

// ---------------------------------------------------------------- the provisional rejudge

/**
 * What a provisional verdict was judged on (the header's `provisional rejudge`): the record's format, the house judge's
 * model call and directory (agent, judge_sha256), what it reads (media, artifact), the share of calls it may leave with
 * no verdict, and the house text its requests were built from. A heat setup or a stored record holds every one of them.
 */
export type ProvisionalJudgeOn = Pick<JudgeHeatSetupT, 'format' | 'agent' | 'judge_sha256' | 'media' | 'artifact' | 'invalid_share_max' | 'house_text'> & {
  /** A heat on a ladder's (a v3 record's): the sealed ladder and its adaptive design. */
  ladder?: Pick<JudgeHeatLadderT, 'ladder_sha256' | 'rounds' | 'games' | 'spread'>;
};

/**
 * The key of what a provisional verdict was judged on (ProvisionalJudgeOn): two verdicts share one scale exactly when
 * their keys are equal. One with no ladder hashes the fields it always has, so a bundle naming none keeps its key; one on
 * a ladder (format v3) hashes its ladder's digest and design beside them.
 */
export function provisionalJudgeKeyOf(on: ProvisionalJudgeOn): string {
  const key = {
    format: on.format,
    agent: on.agent,
    judge_sha256: on.judge_sha256,
    media: on.media,
    artifact: on.artifact,
    invalid_share_max: on.invalid_share_max,
    house_text: on.house_text,
  };
  if (on.ladder === undefined) return canonicalSha256(key);
  return canonicalSha256({ ...key, ladder: { ladder_sha256: on.ladder.ladder_sha256, rounds: on.ladder.rounds, games: on.ladder.games, spread: on.ladder.spread } });
}

/**
 * The key (provisionalJudgeKeyOf) of a provisional heat run now on `judge`, a bundle's: the current record format and
 * house text, and when it names a ladder, the ladder's format (JUDGE_HEAT_FORMAT_V3), digest and design.
 */
export async function provisionalJudgeKey(judge: ProgramJudgeT): Promise<string> {
  const { JUDGE_HEAT_FORMAT, JUDGE_HEAT_FORMAT_V3 } = await import('./judge-heat.ts');
  const { JUDGE_HOUSE_TEXT } = await import('./judge-call.ts');
  const ladder = judge.ladder;
  return provisionalJudgeKeyOf({
    format: ladder === undefined ? JUDGE_HEAT_FORMAT : JUDGE_HEAT_FORMAT_V3,
    agent: judge.agent,
    judge_sha256: judge.judge_sha256,
    media: judge.media,
    artifact: judge.artifact,
    invalid_share_max: judge.invalid_share_max,
    house_text: { ...JUDGE_HOUSE_TEXT },
    ...(ladder === undefined ? {} : { ladder: { ladder_sha256: ladder.ladder_sha256, rounds: ladder.rounds, games: ladder.games, spread: ladder.spread } }),
  });
}

/**
 * The key (provisionalJudgeKeyOf) of the provisional heat record `sha256` a dev run links, or null when it is no
 * provisional record this store holds whole (missing, corrupt, refused, or a final heat's): such a run is judged again.
 * Given the bundle's `judge`, a record on its ladder that played fewer adaptive rounds than the ladder names (one an
 * earlier release's daily cap cut short, or played before the ladder's rounds grew) is keyed at the ladder's rounds: it
 * is on the current judge, so it is not paid for again.
 */
export async function provisionalRecordJudgeKey(blobs: Pick<BlobStore, 'get'>, sha256: string, judge?: ProgramJudgeT): Promise<string | null> {
  const { loadHeldJudgeHeatRecord } = await import('./regrade.ts');
  try {
    // Its head is all the key reads: read back once a process, off this thread (regrade.ts loadHeldJudgeHeatRecord).
    const record = (await loadHeldJudgeHeatRecord(blobs, sha256)).record;
    if (record.stage !== 'provisional') return null;
    const on = record.ladder;
    const design = judge?.ladder;
    if (on !== undefined && design !== undefined && on.ladder_sha256 === design.ladder_sha256 && on.games === design.games && on.spread === design.spread && on.rounds < design.rounds) {
      return provisionalJudgeKeyOf({ ...record, ladder: { ...on, rounds: design.rounds } });
    }
    return provisionalJudgeKeyOf(record);
  } catch (err) {
    if (err instanceof RegradeError) return null;
    throw err;
  }
}

/** How a provisional rejudge ended (rejudgeProvisional): judged on the current judge, recorded unjudged, or nothing written and why. */
export type ProvisionalRejudgeEnd =
  | { kind: 'judged'; run_id: string; judge_heat_sha256: string; win_rate_micro: number; result_sha256: string }
  | { kind: 'unjudged'; run_id: string; why: string; result_sha256: string }
  | { kind: 'skipped'; run_id: string; why: string };

/**
 * A kept dev run's provisional verdict judged again on its bundle's current judge (the header's `provisional rejudge`;
 * server/jobs.ts GradeJob `rejudge`): the run its job names, a finished grade run of the job's entry on the dev phase
 * that passed its gate, plays its artifact in a provisional heat (provisionalJudgeHeat: the anchors, the judge
 * directory, the house text, its uncapped key, the record stored before its verdict is read), and its score is built
 * again with the new verdict and written with the link to the new record, in one transaction held to the result it had,
 * as a new dev grade would record it. A heat that judges nothing records the run unjudged (its old verdict and link
 * dropped), as a dev grade is recorded unjudged, unless it ended on the platform's fault or on a judge model with no
 * price (ProvisionalUnjudgedCause): the verdict is kept and nothing written, a fault thrown for the job to retry, an
 * unpriced model skipped for a later UTC day's sweep. Nothing is written for a run already judged on the current judge (its record's
 * key is the job's), for a run that is no passed grade, or for an unjudged run the heat leaves unjudged. A final
 * phase's run is refused (PermanentJobError): its verdict is its heat's.
 */
async function rejudgeProvisional(
  deps: GradeWorkerDeps,
  r: { job: JobPayload<'grade-dev'>; sub: typeof submission.$inferSelect; ph: typeof phase.$inferSelect; comp: typeof competition.$inferSelect; bundle: CompetitionBundleT; signal?: AbortSignal },
): Promise<ProvisionalRejudgeEnd> {
  const { db, blobs } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const runId = r.job.reproduces_run_id;
  const what = `run ${runId ?? '?'}'s provisional rejudge (entry ${r.sub.id}, ${r.comp.slug})`;
  if (runId === null) throw new PermanentJobError(`${what}: the job names no run`);
  if (r.ph.key !== 'dev') throw new PermanentJobError(`${what}: phase ${r.ph.id} is the ${r.ph.key} phase, and only a dev run's provisional verdict is judged again (a final run's verdict is its phase's judge heat's)`);
  const harness = r.bundle.harness;
  if (harness.kind !== 'program/v1' || harness.judge === undefined) throw new PermanentJobError(`${what}: ${r.comp.slug}'s bundle names no judge heat, so it has no provisional verdict to judge again`);
  const judge = harness.judge;
  const [row] = await db.select().from(run).where(eq(run.id, runId));
  if (row === undefined) throw new PermanentJobError(`${what}: run ${runId} does not exist`);
  if (row.submissionId !== r.sub.id || row.phaseId !== r.ph.id || row.kind !== 'grade') throw new PermanentJobError(`${what}: run ${runId} is no grade run of entry ${r.sub.id} on phase ${r.ph.id}`);
  const skipped = (why: string): ProvisionalRejudgeEnd => {
    log(`[grade] ${what}: nothing is written: ${why}`);
    return { kind: 'skipped', run_id: row.id, why };
  };
  const parsed = Score.safeParse(row.result);
  const score = parsed.success ? parsed.data : null;
  const perf = score?.performance;
  if (row.status !== 'finished' || score === null || perf?.kind !== 'program/v1' || perf.passed !== true || row.actionLogSha256 === null || row.seed === null) {
    return skipped('it is no finished grade that passed its gate with an action log and a seed, so it carries no provisional verdict');
  }
  const key = await provisionalJudgeKey(judge);
  if (r.job.rejudge !== undefined && r.job.rejudge.judge_key !== key) log(`[grade] ${what}: the bundle's judge changed since the job was sent (key ${r.job.rejudge.judge_key}): it is judged on the judge it names now (key ${key})`);
  // A scrutiny top-up (GradeJob scrutiny_top_up) of a run on the current judge extends its record, never skipped as
  // current (scrutinyTopUp); one whose run is not on the current judge ({afresh}) is judged afresh below, at its line.
  const topUp = r.job.scrutiny_top_up;
  let topUpLine: number | undefined;
  if (topUp !== undefined) {
    const ended = await scrutinyTopUp(deps, { ...r, judge, row, score, key, what, topUp, skipped });
    if (!('afresh' in ended)) return ended;
    topUpLine = ended.afresh;
  } else if (perf.judge !== undefined && row.judgeHeatSha256 !== null && (await provisionalRecordJudgeKey(blobs, row.judgeHeatSha256, judge)) === key) {
    return skipped(`it is judged on the current judge already (record ${row.judgeHeatSha256})`);
  }
  const heat = await provisionalJudgeHeat(deps, {
    actionLog: { sha256: row.actionLogSha256, json: null },
    sub: r.sub,
    comp: r.comp,
    ph: r.ph,
    phaseSeed: row.seed,
    harness,
    judge,
    ...(r.signal === undefined ? {} : { signal: r.signal }),
    ...(topUpLine === undefined ? {} : { scrutinyLine: topUpLine }),
  });
  const entry: EntryFacts = { house: standingsHouse(r.sub), baseline: r.sub.baseline };
  const rules = eligibilityRulesOf(r.bundle);
  if ('unjudged' in heat && perf.judge === undefined && row.judgeHeatSha256 === null) return skipped(`it stays unjudged: ${heat.unjudged}`);
  // A verdict is never dropped for the platform's fault or an unpriced model: a fault is retried, a model with no price waits for another day.
  if ('unjudged' in heat && heat.cause === 'fault') {
    log(`[grade] ${what}: nothing is written, its verdict kept, and the job is retried: ${heat.unjudged}`);
    throw new Error(`${what}: its heat could not judge it (${heat.unjudged}), the platform's fault: its verdict is kept and the job retried`);
  }
  if ('unjudged' in heat && heat.cause === 'unpriced') return skipped(`kept its verdict: ${heat.unjudged}; the sweep sends it again on a later UTC day`);
  const next = 'unjudged' in heat ? { ...scoreWithJudge(score, null, entry, rules), judge_heat_sha256: null } : { ...scoreWithJudge(score, heat.verdict, entry, rules), judge_heat_sha256: heat.judge_heat_sha256 };
  // An attempt given up writes nothing: its retry judges again (the record it stored stays, unlinked).
  r.signal?.throwIfAborted();
  await db.transaction(async (tx) => {
    const updated = await tx
      .update(run)
      .set({ result: next.result, resultSha256: next.result_sha256, judgeHeatSha256: next.judge_heat_sha256 })
      .where(and(eq(run.id, row.id), eq(run.resultSha256, row.resultSha256 ?? '')))
      .returning({ id: run.id });
    // A run written since it was read (a regrade, or another rejudge): the retry judges it as it now stands.
    if (updated.length === 0) throw new Error(`${what}: run ${row.id} changed while its heat ran`);
    await recordLiveChange(tx, { ...GRADE_CHANGE, scopeId: r.comp.id });
  });
  if ('unjudged' in heat) {
    log(`[grade] ${what}: it is recorded with no provisional judge verdict (its verdict${row.judgeHeatSha256 === null ? '' : ` and record ${row.judgeHeatSha256}`} dropped), as a dev grade is: ${heat.unjudged}`);
    return { kind: 'unjudged', run_id: row.id, why: heat.unjudged, result_sha256: next.result_sha256 };
  }
  log(`[grade] ${what}: judged provisionally again on the current judge (key ${key}) against ${provisionalHeatWords(heat)}${row.judgeHeatSha256 === null ? '' : `, in place of record ${row.judgeHeatSha256}`}`);
  return { kind: 'judged', run_id: row.id, judge_heat_sha256: heat.judge_heat_sha256, win_rate_micro: heat.verdict.win_rate_micro, result_sha256: next.result_sha256 };
}

/**
 * A screened bundle's dev money-place scrutiny top-up of a kept dev run (rejudgeProvisional, a job carrying
 * `scrutiny_top_up`; the header's `provisional rejudge`): the provisional ladder record the run links on the current
 * judge extended at the line (the job's `line_micro` when an older release sent one, else the phase's dev scrutiny line
 * as stored now: server/grading/dev-scrutiny-line.ts readDevScrutinyLine), never judged afresh. The record's setup
 * takes the ladder's scrutiny at the line (scrutinisedSetupOf), its calls and spares are carried into the new heat verbatim (never asked again), and only the
 * calls its schedule plans past them are sent: the scrutiny rounds, when the entry's interval high over its games
 * reaches the line. The new record stored, every grade run of the phase that linked the old one (the entry's, and each
 * that reused its verdict on the same bytes) is scored again with the new verdict and relinked, and every entry_artifact
 * row of the phase that named it names the new one, in one transaction held to each run's result as it was read.
 *
 * {afresh: the line} when the run's record is not on the current judge (or it holds no verdict on one): it is judged
 * afresh at the line, as any rejudge. Nothing is written (skipped) when its bundle plays no dev scrutiny, its entry is a
 * baseline or the house's (it holds no prize place, so the line never counts it: dev-scrutiny-line.ts devScrutinyLine),
 * the run no longer links the record the job names (topped up or judged again since it was sent), no line stands, its
 * record played its scrutiny already or owes no call at the line (its interval high is below it), or its heat judged
 * nothing more for a reason of its own (its verdict and record kept: a top-up never drops a verdict). A heat that ends
 * on the platform's fault throws for the queue to retry; every other end is final for the job, an unpriced model's among
 * them. A skip writes nothing, so the record it names stays unscrutinised and linked: the sweep sends it again (under the
 * job id of the record and the line then stored: server/grading/provisional-rejudge-sweep.ts devScrutinyTopUpJobId) once
 * the line is stored anew and reaches it, as when the line rose past it before this job ran and later came back down;
 * a record this job extended is linked by no run, so it is never sent again.
 */
async function scrutinyTopUp(
  deps: GradeWorkerDeps,
  t: {
    sub: typeof submission.$inferSelect;
    ph: typeof phase.$inferSelect;
    comp: typeof competition.$inferSelect;
    bundle: CompetitionBundleT;
    signal?: AbortSignal;
    judge: ProgramJudgeT;
    row: typeof run.$inferSelect;
    score: ScoreT;
    key: string;
    what: string;
    topUp: NonNullable<JobPayload<'grade-dev'>['scrutiny_top_up']>;
    skipped: (why: string) => ProvisionalRejudgeEnd;
  },
): Promise<ProvisionalRejudgeEnd | { afresh: number }> {
  const { db, blobs } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const { judge, row, what, skipped } = t;
  const harness = t.bundle.harness;
  const rounds = judge.screened?.dev_rounds ?? 0;
  if (harness.kind !== 'program/v1' || judge.ladder === undefined || rounds < 1) {
    return skipped(`its scrutiny top-up finds no dev money-place scrutiny in its bundle (a screened judge on a ladder with dev_rounds above 0)`);
  }
  // A baseline or a house entry holds no prize place, so the line never counts it, and it is scrutinised for none.
  if (t.sub.baseline || standingsHouse(t.sub)) return skipped(`its entry is ${t.sub.baseline ? 'a baseline' : "the house's"}, which holds no prize place, so it takes no money-place scrutiny`);
  const perf = t.score.performance;
  const old = row.judgeHeatSha256;
  if (perf.kind !== 'program/v1' || perf.judge === undefined || old === null) return skipped(`its scrutiny top-up finds no provisional verdict and no record to extend (the rejudge judges an unjudged run)`);
  const sent = t.topUp.judge_heat_sha256;
  if (sent !== undefined && sent !== old) return skipped(`it links record ${old}, not the record ${sent} its scrutiny top-up was sent for (topped up or judged again since)`);
  // The line: the job's when an older release sent one, else the phase's as stored now (the sweep stores it before it sends).
  let line = t.topUp.line_micro ?? null;
  if (line === null) {
    const { readDevScrutinyLine } = await import('../server/grading/dev-scrutiny-line.ts');
    line = (await readDevScrutinyLine(db, t.ph.id))?.line_micro ?? null;
  }
  if (line === null) return skipped('its scrutiny top-up finds no dev scrutiny line standing for its phase (none stored, or fewer entrants rated than the last paid place)');
  if ((await provisionalRecordJudgeKey(blobs, old, judge)) !== t.key) {
    log(`[grade] ${what}: its record ${old} is not on the current judge (key ${t.key}), so its scrutiny top-up judges it afresh at the line ${winRateFraction(line)}`);
    return { afresh: line };
  }
  const jh = await import('./judge-heat.ts');
  const { loadJudgeHeatRecord } = await import('./regrade.ts');
  const record = await loadJudgeHeatRecord(blobs, old);
  const ladder = record.ladder;
  if (ladder === undefined) return skipped(`its record ${old} is no ladder heat's, so it takes no scrutiny`);
  if (record.calls.some((c) => c.stage === 'adaptive' && c.round > ladder.rounds * ladder.games)) {
    return skipped(`its record ${old} played its money-place scrutiny already (at the line ${winRateFraction(ladder.scrutiny?.line_micro ?? 0)})`);
  }
  let setup: JudgeHeatSetupT;
  try {
    setup = await scrutinisedSetupOf(record, { line_micro: line, rounds });
  } catch (err) {
    if (err instanceof jh.JudgeHeatError) return skipped(`its record ${old} takes no scrutiny: ${err.message}`);
    throw err;
  }
  const sc = jh.judgeHeatSchedule(setup, record.calls);
  if (sc.issue !== null) return skipped(`its record ${old}'s calls are not the start of its scrutinised heat: ${sc.issue}`);
  if (sc.complete && sc.planned.length === record.calls.length) {
    return skipped(`its interval high over record ${old}'s games is below the dev line ${winRateFraction(line)}, so it owes no scrutiny round`);
  }
  const heat = await provisionalJudgeHeat(deps, {
    actionLog: { sha256: row.actionLogSha256!, json: null },
    sub: t.sub,
    comp: t.comp,
    ph: t.ph,
    phaseSeed: row.seed!,
    harness,
    judge,
    ...(t.signal === undefined ? {} : { signal: t.signal }),
    scrutinyLine: line,
    extend: { record, sha256: old, setup },
  });
  if ('unjudged' in heat) {
    if (heat.cause === 'fault') {
      log(`[grade] ${what}: its scrutiny top-up wrote nothing, its verdict and record ${old} kept, and the job is retried: ${heat.unjudged}`);
      throw new Error(`${what}: its scrutiny top-up could not judge it (${heat.unjudged}), the platform's fault: its verdict is kept and the job retried`);
    }
    return skipped(`its scrutiny top-up judged nothing more, so its verdict and record ${old} are kept: ${heat.unjudged}`);
  }
  const fresh = heat.judge_heat_sha256;
  // The verdict every relinked run takes: the new record's on the artifact (judgeHeatVerdicts; a reusing run's bytes are the entry's).
  const verdict = heat.verdict;
  const artifact = verdict.artifact_sha256;
  const rules = eligibilityRulesOf(t.bundle);
  // An attempt given up writes nothing: its retry tops up again (the record it stored stays, unlinked).
  t.signal?.throwIfAborted();
  let ownResult = '';
  const relinked: string[] = [];
  await db.transaction(async (tx) => {
    // The phase's grade runs linking the old record, found on run_phase_judge_heat_idx (a lookup, never the phase's
    // runs scanned), read as far as the relink uses: each run's id and score, and its entry's standing facts.
    const linked = await tx
      .select({ run: { id: run.id, result: run.result, resultSha256: run.resultSha256 }, sub: { house: submission.house, submittedAsHouse: submission.submittedAsHouse, baseline: submission.baseline } })
      .from(run)
      .innerJoin(submission, eq(run.submissionId, submission.id))
      .where(and(eq(run.phaseId, t.ph.id), eq(run.kind, 'grade'), eq(run.judgeHeatSha256, old)))
      .orderBy(asc(run.id));
    if (!linked.some((l) => l.run.id === row.id)) throw new Error(`${what}: run ${row.id} no longer links record ${old}: it changed while its top-up ran`);
    for (const l of linked) {
      const p = Score.safeParse(l.run.result);
      const lp = p.success ? p.data.performance : null;
      if (!p.success || lp?.kind !== 'program/v1' || lp.passed !== true || lp.judge === undefined || lp.judge.artifact_sha256 !== artifact) {
        log(`[grade] ${what}: run ${l.run.id} links record ${old} with no passed score judged on artifact ${artifact}, so it keeps that link`);
        continue;
      }
      const next = scoreWithJudge(p.data, verdict, { house: standingsHouse(l.sub), baseline: l.sub.baseline }, rules);
      // The job's run held to the result its rejudge read; every other to the one read here.
      const was = l.run.id === row.id ? (row.resultSha256 ?? '') : (l.run.resultSha256 ?? '');
      const updated = await tx
        .update(run)
        .set({ result: next.result, resultSha256: next.result_sha256, judgeHeatSha256: fresh })
        .where(and(eq(run.id, l.run.id), eq(run.resultSha256, was)))
        .returning({ id: run.id });
      if (updated.length === 0) throw new Error(`${what}: run ${l.run.id} changed while its top-up ran`);
      if (l.run.id === row.id) ownResult = next.result_sha256;
      relinked.push(l.run.id);
    }
    if (ownResult === '') throw new Error(`${what}: run ${row.id}'s score is not judged on artifact ${artifact}: it changed while its top-up ran`);
    // Found on entry_artifact_phase_judge_heat_idx, as the runs above are on theirs.
    await tx.update(entryArtifact).set({ judgeHeatSha256: fresh }).where(and(eq(entryArtifact.phaseId, t.ph.id), eq(entryArtifact.judgeHeatSha256, old)));
    await recordLiveChange(tx, { ...GRADE_CHANGE, scopeId: t.comp.id });
  });
  const others = relinked.filter((id) => id !== row.id);
  log(
    `[grade] ${what}: topped up at the dev line ${winRateFraction(line)} (key ${t.key}) against ${provisionalHeatWords(heat)}, in place of record ${old}${others.length === 0 ? '' : `; runs ${others.join(', ')} relinked with it`}`,
  );
  return { kind: 'judged', run_id: row.id, judge_heat_sha256: fresh, win_rate_micro: verdict.win_rate_micro, result_sha256: ownResult };
}

/** How often a code-heat job whose phase is still grading looks again (the header's `code heat`): at its next slot of this length. */
export const CODE_HEAT_RECHECK_MS = 5 * 60_000;

/**
 * The context a code-heat job is handed (JobQueue.work's): its id names its scratch's owner, its signal stops the heat
 * (the run under way killed, never kept), and its expiry is what the heat's runs must end before, the rest handed on
 * (the header's `hand-on`). Its place in the sandbox pool (a code-heat job holds one: server/jobs.ts PODS_PER_JOB) is
 * given back (releasePlace) before a judge heat's first call: it starts no pod, only calls the house judge. A job marked
 * a judge heat's (server/jobs.ts isJudgeHeatJob: its `priority`) never took one
 * (takesNoSandboxPlace), so it has no releasePlace. A timing heat keeps its place, its runs in the sandbox.
 */
export type CodeHeatJobContext = Pick<JobContext, 'id'> & Partial<Pick<JobContext, 'retryCount' | 'retryLimit' | 'signal' | 'expiresAt' | 'releasePlace' | 'priority'>>;

/**
 * The most runs a heat makes (the header's `hand-on`; grader/code-heat.ts the stages): the warm-up and main rounds over a
 * field of `field` entries and the control, then the playoff rounds over as many finalists as it can take (`places`,
 * codeHeatPlaces, and no more than the field; none under two) and the control. A main round that leaves fewer entries
 * ranked names fewer finalists, so the heat makes at most this many.
 */
export function codeHeatPlannedRuns(timing: Pick<ProgramTimingT, 'warmup_rounds' | 'rounds' | 'playoff_rounds'>, field: number, places: number): number {
  if (!Number.isSafeInteger(field) || field < 0 || !Number.isSafeInteger(places) || places < 0) throw new RangeError(`a heat of ${field} entries and ${places} finalist places: counts`);
  if (field === 0) return 0;
  const most = Math.min(field, places);
  const finalists = timing.playoff_rounds > 0 && most >= 2 ? most : 0;
  return (timing.warmup_rounds + timing.rounds) * (field + 1) + (finalists === 0 ? 0 : timing.playoff_rounds * (finalists + 1));
}

/**
 * The longest one run of a heat takes, in ms (the header's `hand-on`): under one run per case (grader/program.ts
 * executeProgram), each case's time cap (its reference manifest's, programCases) and server/proposals/checks.ts
 * PACK_CASE_OVERHEAD_MS for its containers' start and exit; under one whole run, the competition's wall budget and one
 * case's overhead. The control's run goes over the same cases, so it takes as long at most. A manifest that does not
 * read is ScorerError, as it is to the heat's first run.
 */
export function codeHeatRunMs(setup: ProgramSetup, limits: Pick<CompetitionBundleT['limits'], 'wall_budget_sec'>): number {
  if (setup.harness.cases !== 'per-file') return limits.wall_budget_sec * 1000 + PACK_CASE_OVERHEAD_MS;
  return programCases(programPaths(setup).referenceDir).reduce((ms, c) => ms + c.time_cap_ms + PACK_CASE_OVERHEAD_MS, 0);
}

/** One entry of a recorded heat, as its grade run now stands. */
export interface CodeHeatEntryOutcome {
  submission_id: string;
  run_id: string;
  /** `timed`: its timing is on its score; TIMING_OUTPUTS_DIFFER: a timed run wrote other outputs, and it is unranked. */
  verdict: 'timed' | typeof TIMING_OUTPUTS_DIFFER;
  /** Its timing's rank key (null when unranked). */
  trimmed_mean_cpu_us: number | null;
  rounds: number | null;
  /** The run's result_sha256 after the heat. */
  result_sha256: string;
}

/** What a code-heat job recorded on a timing heat (the header's `code heat`). */
export interface CodeHeatOutcome {
  kind: 'timing';
  phase_id: string;
  /** The heat record's sha256: its blob's name, and every timed run's run.code_heat_sha256. */
  heat_sha256: string;
  /** Where the CPU time was read (CpuClock.source: the record's, the clock of its first run), how many runs the heat made, and its finalists. */
  cpu_source: string;
  runs: number;
  /**
   * How many of the runs an earlier attempt of the heat measured and kept, taken as they stood (the header's `resume`):
   * 0 when this attempt timed every one.
   */
  kept_runs: number;
  /** Every clock the record's runs were read on, cpu_source first: more than one when an attempt resumed on a fresh clock. */
  cpu_sources: string[];
  finalists: string[];
  /** How long the heat ran, in ms (its runs, not the wait for the clock). */
  wall_ms: number;
  /** Every entry of the field, in receipt order. */
  entries: CodeHeatEntryOutcome[];
}

/** A due phase whose heat is a timing heat, with its timing (createProgramHeatHandler): what timeCodeHeat times. */
type TimingHeatDue = Extract<CodeHeatDue, { kind: 'due' }> & { timing: ProgramTimingT };

/** A due phase whose heat is a judge heat, with its judge (createProgramHeatHandler): what judgeCodeHeat judges. */
type JudgeHeatDue = Extract<CodeHeatDue, { kind: 'due' }> & { judge: ProgramJudgeT };

/** What a code-heat job recorded, by its heat's kind: a timing heat's (CodeHeatOutcome) or a judge heat's (JudgeHeatOutcome). */
export type ProgramHeatOutcome = CodeHeatOutcome | JudgeHeatOutcome;

/**
 * The code-heat job handler (the header's `code heat`), for a program-heat final of either kind (finalize.ts
 * programHeatPhaseOf): a code-fastest final's field timed in one heat on the process's clock, or a judged final's
 * judged in one by the house judge (judgeCodeHeat, the header's `judge heat`); either way its record stored, and each
 * field entry's grade run written its score with its verdict and the link to the record. Null when it recorded
 * nothing: the phase is no program-heat final, is not locked, has nothing owed, or is still grading (the job then hands
 * itself on to its next CODE_HEAT_RECHECK_MS slot on deps.jobs), the heat's runs would outlast the attempt (it times
 * those that fit, keeps them and hands the rest on: the header's `hand-on`), the attempt waited for the clock (or a
 * scrape heat holding the host) until its expiry less the slack (it hands on from the wait, timing nothing:
 * codeHeatWait, handOnCodeHeatWait), or a judge heat is held at its opening (it hands on an hour later: the header's
 * `judge heat`). Throws PermanentJobError on what no retry mends (no timing sandbox here, a field run graded under
 * another plan, a judge heat that failed); anything else (a clock that does not read, a sandbox that fails, a record
 * that does not hold, a gateway that does not answer) is the house's fault, and the job is retried.
 */
export function createProgramHeatHandler(deps: GradeWorkerDeps): (data: JobPayload<'code-heat'>, ctx?: CodeHeatJobContext) => Promise<ProgramHeatOutcome | null> {
  return programHeatHandler(deps, true);
}

/**
 * createProgramHeatHandler for a code-fastest final alone, its outcome a timing heat's: a TypeError, judging nothing,
 * on a phase whose heat is a judge heat.
 */
export function createCodeHeatHandler(deps: GradeWorkerDeps): (data: JobPayload<'code-heat'>, ctx?: CodeHeatJobContext) => Promise<CodeHeatOutcome | null> {
  const handle = programHeatHandler(deps, false);
  return async (data, ctx) => {
    const out = await handle(data, ctx);
    if (out?.kind === 'judge') throw new TypeError(`phase ${out.phase_id}'s heat is a judge heat: createProgramHeatHandler judges it`);
    return out;
  };
}

/** The code-heat job handler (createProgramHeatHandler); with `judges` false, one that refuses a judge heat before judging (createCodeHeatHandler). */
function programHeatHandler(deps: GradeWorkerDeps, judges: boolean): (data: JobPayload<'code-heat'>, ctx?: CodeHeatJobContext) => Promise<ProgramHeatOutcome | null> {
  const { db } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  // The heats whose hand-on this process paged as ending past their result deadline (the header's `late`), when.
  const late: LatePaged = new Map();
  // The competitions whose held judge heat this process paged (the header's `judge heat`), when: once an hour each.
  const held: HoldPaged = new Map();
  return async (input, ctx) => {
    const data = CodeHeatJob.parse(input);
    const jobKey = ctx?.id ?? uuidv7();
    const { codeHeatDue, programHeatPhaseOf } = await import('../server/competitions/lifecycle/finalize.ts');
    // The phase's heat kind off its bundle (programHeatPhaseOf; null: no program-heat final), read only where a mark
    // turns on it, at most once a job.
    let heatKind: 'timing' | 'judge' | null | undefined;
    const kindOfHeat = async (): Promise<'timing' | 'judge' | null> => (heatKind ??= (await programHeatPhaseOf(db, data.phase_id))?.heat.kind ?? null);
    // A job marked a judge heat's took no place in the sandbox pool (server/jobs.ts takesNoSandboxPlace), and a timing
    // heat runs pods: it times nothing, and the phase's job goes again unmarked (codeHeatJobId `placed:<job id>`), which
    // waits for its place. With no queue handed in there is no pool, and it goes on here.
    if (isJudgeHeatJob(ctx?.priority) && deps.jobs !== undefined && (await kindOfHeat()) === 'timing') {
      const id = codeHeatJobId(data.phase_id, `placed:${jobKey}`);
      const sent = await sendCodeHeat(deps.jobs, data.phase_id, { id });
      log(`[code-heat] ${jobKey}: the heat of phase ${data.phase_id} is a timing heat, and this job was sent as a judge heat's, holding no sandbox place: job ${id}${sent === null ? ' (sent before)' : ''} takes it up with its place`);
      return null;
    }
    const dueFrom = performance.now();
    const first = await codeHeatDue(db, data.phase_id);
    const dueMs = performance.now() - dueFrom;
    if (first.kind === 'waiting') {
      if (deps.jobs === undefined) {
        log(`[code-heat] ${jobKey}: the heat of phase ${data.phase_id} waits (${first.why}), and no queue is handed in to look again on`);
        return null;
      }
      const slot = Math.floor(now().getTime() / CODE_HEAT_RECHECK_MS) + 1;
      const at = new Date(slot * CODE_HEAT_RECHECK_MS);
      const id = codeHeatJobId(data.phase_id, `wait:${slot}`);
      // A judge heat's next look is marked so (server/jobs.ts sendJudgeHeatJob): it runs no sandbox pod, so it waits
      // for no place in the sandbox pool. The phase's bundle says which (a waiting phase names no kind).
      const judge = (await kindOfHeat()) === 'judge';
      await (judge ? sendJudgeHeatJob : sendCodeHeat)(deps.jobs, data.phase_id, { id, startAfter: at });
      log(`[code-heat] ${jobKey}: the heat of phase ${data.phase_id} waits: ${first.why}; it looks again at ${at.toISOString()} (job ${id}${judge ? ', a judge heat taking no sandbox place' : ''})`);
      return null;
    }
    if (first.kind === 'none') {
      log(`[code-heat] ${jobKey}: nothing to ${first.heat === 'judge' ? 'judge' : 'time'}: ${first.why}`);
      await dropCodeHeatPartial(deps, data.phase_id, `[code-heat] ${jobKey}`);
      return null;
    }
    if (first.heat.kind === 'judge') {
      if (!judges) throw new TypeError(`phase ${data.phase_id}'s heat is a judge heat: createProgramHeatHandler judges it`);
      // No clock and no sandbox: its calls go to the house judge over the network (the header's `judge heat`). So its
      // place in the sandbox pool goes back before its first call (JobContext.releasePlace), never held through the
      // heat's calls: the next sandbox job in line takes it.
      ctx?.releasePlace?.(`the judge heat of phase ${data.phase_id} runs house judge calls and no sandbox pod`);
      log(`[code-heat] ${jobKey}: ${judgeHeatPrepLine(`its due field read: ${first.field.length} entries`, dueMs)}`);
      return judgeCodeHeat(deps, { ...first, judge: first.heat.judge }, jobKey, ctx, held);
    }
    const firstTimed: TimingHeatDue = { ...first, timing: first.heat.timing };
    const timing = timingSandboxOf(deps);
    if (timing === null) {
      throw new PermanentJobError(`the final phase of ${first.comp.slug} is due its timing heat, and this process's ${deps.sandbox.kind} sandbox reads no CPU time: a heat runs on the docker driver or the k8s driver (MAKEFUN_SANDBOX docker or k8s)`);
    }
    // Its waits before its runs end at its expiry less the slack, and the heat hands on then (the header's `hand-on`):
    // with no expiry or no queue to hand on to, it waits as long as its attempt's signal lets it.
    const jobs = deps.jobs;
    const wait = ctx?.expiresAt === undefined || jobs === undefined ? null : codeHeatWait(ctx.expiresAt, now, ctx.signal);
    let latest = firstTimed;
    let waitingOn = "this process's CPU clock, another timing holding it";
    try {
      // Held as a heat: while it holds the clock or waits for it, a dev grade's timing does not wait (withProvisionalTiming).
      return await processCpuClock(timing).exclusive(
        async (sandbox) => {
          // Read again under the clock: another job of this process may have timed the phase while this one waited for it.
          const due = await codeHeatDue(db, data.phase_id);
          if (due.kind !== 'due') {
            wait?.end();
            log(`[code-heat] ${jobKey}: nothing to time once the clock was free: ${due.why}`);
            if (due.kind === 'none') await dropCodeHeatPartial(deps, data.phase_id, `[code-heat] ${jobKey}`);
            return null;
          }
          // A bundle that turned to a judge heat while this one waited: the retry judges it, off the clock.
          if (due.heat.kind !== 'timing') throw new Error(`phase ${data.phase_id}'s heat turned from a timing heat to a ${due.heat.kind} heat while its job waited for the clock: the job's retry takes it as it now stands`);
          const timed: TimingHeatDue = { ...due, timing: due.heat.timing };
          latest = timed;
          // No timing beside a scrape heat holding this host under the `host` lease scope (the header's `scrape/v1`; under
          // `egress` the heat's pods reserve their CPU and nothing here waits). Given up as the clock came, its wait was the clock's.
          if (scrapeLeaseScopeOf(deps) === 'host') {
            if (wait?.signal.aborted !== true) waitingOn = 'a scrape heat holding this host';
            await scrapeHostQuiet(deps, `the timing heat of ${due.comp.slug}'s final phase (job ${jobKey})`, wait?.signal ?? ctx?.signal);
          }
          // Its waits are over: from here its runs stop for its expiry between runs (timeCodeHeat).
          wait?.end();
          return timeCodeHeat(deps, timed, sandbox, jobKey, ctx, late);
        },
        wait?.signal ?? ctx?.signal,
        'heat',
      );
    } catch (err) {
      if (wait === null || jobs === undefined || !wait.gaveUp(err)) throw err;
      // Out of the clock's queue (exclusive's abort) or off the clock: handed on, never failed by its expiry.
      return handOnCodeHeatWait(deps, jobs, latest, jobKey, { on: waitingOn, until: wait.until, endsAt: wait.endsAt }, late);
    } finally {
      wait?.end();
    }
  };
}

/** The longest one timer waits (setTimeout's most, 2^31 - 1 ms): a longer wait is several. */
const TIMER_MAX_MS = 2 ** 31 - 1;

/**
 * A code-heat attempt's waits before its runs (createProgramHeatHandler: for the process's clock behind other timings, then
 * for any scrape heat holding the host), held to its expiry `endsAt` less server/jobs.ts CODE_HEAT_SLACK_SECONDS (the
 * header's `hand-on`): its signal aborts with a CodeHeatHandOn once that comes (gaveUp), or with the attempt's own
 * reason first (`signal`: pg-boss gave it up). How long is left is read on `now` as the wait starts, then on the
 * monotonic clock. `end` disarms it: the waits are over, and its deadline stops nothing after.
 */
function codeHeatWait(endsAt: Date, now: () => Date, signal: AbortSignal | undefined): { signal: AbortSignal; until: Date; endsAt: Date; gaveUp(err: unknown): boolean; end(): void } {
  const until = new Date(endsAt.getTime() - CODE_HEAT_SLACK_SECONDS * 1000);
  const stop = new AbortController();
  const reason = new CodeHeatHandOn(`the heat waited until ${until.toISOString()}, ${CODE_HEAT_SLACK_SECONDS} s before its attempt expires at ${endsAt.toISOString()}`);
  const fireAt = performance.now() + Math.max(0, until.getTime() - now().getTime());
  let ended = false;
  let timer: ReturnType<typeof setTimeout> | undefined;
  // Always on a timer, never at once: a clock that is free is taken (exclusive, in microtasks) before the timer fires.
  const arm = (): void => {
    timer = setTimeout(
      () => {
        timer = undefined;
        if (ended) return;
        if (performance.now() >= fireAt) stop.abort(reason);
        else arm();
      },
      Math.min(TIMER_MAX_MS, Math.max(0, Math.ceil(fireAt - performance.now()))),
    );
  };
  arm();
  return {
    signal: signal === undefined ? stop.signal : AbortSignal.any([signal, stop.signal]),
    until,
    endsAt,
    gaveUp: (err) => stop.signal.aborted && err === reason,
    end: () => {
      ended = true;
      if (timer !== undefined) clearTimeout(timer);
      timer = undefined;
    },
  };
}

/**
 * The heat of a due phase handed on from its wait (createProgramHeatHandler; the header's `hand-on`): its attempt waited for
 * `w.on` until its expiry less the slack and timed nothing, so it sends the phase's next job as a heat stopped between its
 * runs does (sendCodeHeatRest: `rest:<job id>:<runs kept>`, the runs kept as they stand, expiring after the rest at most),
 * not before CODE_HEAT_RECHECK_MS from now, and logs it (and pages it when the rest plans to end past the result deadline:
 * pageLateCodeHeat). Null: nothing recorded, and nothing failed.
 */
async function handOnCodeHeatWait(
  deps: GradeWorkerDeps,
  jobs: Pick<JobQueue, 'send'>,
  due: TimingHeatDue,
  jobKey: string,
  w: { on: string; until: Date; endsAt: Date },
  late: LatePaged,
): Promise<null> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  const { codeHeatPartialFile } = await import('./code-heat.ts');
  const { runMs, plannedRuns } = await codeHeatWork(deps, due);
  const kept = await keptCodeHeatRuns(codeHeatPartialFile(codeHeatPartialPath(deps.workRoot, due.ph.id)));
  const startAfter = new Date(now().getTime() + CODE_HEAT_RECHECK_MS);
  const next = await sendCodeHeatRest(jobs, due.ph.id, { jobKey, kept, plannedRuns, runMs, startAfter });
  log(
    `[code-heat] ${jobKey}: the heat of ${due.comp.slug}'s final phase hands on: it waited for ${w.on} until ${w.until.toISOString()}, ${CODE_HEAT_SLACK_SECONDS} s before this attempt expires at ${w.endsAt.toISOString()}, and timed nothing; ` +
      `${kept} of its ${plannedRuns} runs at most are kept, and job ${next.id}${next.sent === null ? ' (sent before)' : ''} times the rest (${next.rest} at most) from ${startAfter.toISOString()}, expiring ${next.expireInSeconds} s after it starts`,
  );
  await pageLateCodeHeat(deps, due, jobKey, { job: next.id, rest: next.rest, runMs, startsAt: startAfter }, late);
  return null;
}

/** What createProgramHeatHandler paged of late heats (the header's `late`): codeHeatLateKey to when it paged. */
type LatePaged = Map<string, Date>;

/** Which heat and deadline a late page is for (the header's `late`): one page each. */
function codeHeatLateKey(phaseId: string, deadline: Date): string {
  return `${phaseId.toLowerCase()} ${deadline.toISOString()}`;
}

/** A hand-on that plans to end past its competition's result deadline (codeHeatLatePage's facts). */
export interface CodeHeatLate {
  slug: string;
  phase_id: string;
  /** The rest job handed on to (codeHeatJobId `rest:…`), its runs at most, one run's time at most, and when it starts. */
  job: string;
  rest: number;
  run_ms: number;
  starts_at: Date;
  /** starts_at plus rest runs of run_ms each: when the heat ends at the latest. */
  finishes_by: Date;
  /** The competition's open escrow's resolve_deadline (the earliest, with one on each cluster), and that escrow's address. */
  deadline: Date;
  escrow: string;
}

/**
 * The page of a heat whose hand-on plans to end past its competition's result deadline (the header's `late`): the
 * competition, the job, the planned finish and the deadline, past which post_result cannot land and the whole pot
 * refunds to the sponsor. An alert only: it says that nothing was stopped.
 */
export function codeHeatLatePage(l: CodeHeatLate): string {
  return (
    `[code-heat] ALERT: the timing heat of ${l.slug}'s final phase (phase ${l.phase_id}) handed its rest on to job ${l.job}, which plans to finish by ${l.finishes_by.toISOString()} ` +
    `(${l.rest} ${l.rest === 1 ? 'run' : 'runs'} at most, each up to ${l.run_ms} ms, from ${l.starts_at.toISOString()}): after the competition's result deadline ${l.deadline.toISOString()} ` +
    `(escrow ${l.escrow}'s resolve_deadline), past which no result can be posted and the whole pot refunds to the sponsor. ` +
    `Nothing is stopped or refused: the heat goes on as planned, and this page is not sent again for it. What holds it is in the job's log (a wait for this host's CPU clock or a scrape heat, or runs taking their time caps)`
  );
}

/**
 * Page the admins once a heat hands on (sendCodeHeatRest) when the rest it sent plans to end past the competition's
 * result deadline (the header's `late`): `rest` runs at most of `runMs` each from `startsAt`, against the earliest
 * resolve_deadline of its escrows still open (none open: no deadline, nothing paged). Once per heat and deadline in
 * `late`; a later hand-on of the same heat is logged. An alert only: a deadline that cannot be read is logged, and the
 * hand-on stands either way.
 */
async function pageLateCodeHeat(
  deps: GradeWorkerDeps,
  due: Extract<CodeHeatDue, { kind: 'due' }>,
  jobKey: string,
  o: { job: string; rest: number; runMs: number; startsAt: Date },
  late: LatePaged,
): Promise<void> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const page = deps.page ?? ((line: string) => console.error(line));
  const now = deps.now ?? (() => new Date());
  let open: { escrow: string; resolveDeadline: Date }[];
  try {
    open = await deps.db
      .select({ escrow: competitionEscrow.escrow, resolveDeadline: competitionEscrow.resolveDeadline })
      .from(competitionEscrow)
      .where(and(eq(competitionEscrow.competitionId, due.comp.id), eq(competitionEscrow.status, 'open')));
  } catch (err) {
    log(`[code-heat] ${jobKey}: the result deadline of ${due.comp.slug} could not be read (${err instanceof Error ? err.message : String(err)}): the hand-on to job ${o.job} stands, unchecked against it`);
    return;
  }
  const first = open.reduce<{ escrow: string; resolveDeadline: Date } | null>((a, e) => (a === null || e.resolveDeadline < a.resolveDeadline ? e : a), null);
  if (first === null) return;
  const finishesBy = new Date(o.startsAt.getTime() + o.rest * o.runMs);
  if (finishesBy.getTime() <= first.resolveDeadline.getTime()) return;
  const key = codeHeatLateKey(due.ph.id, first.resolveDeadline);
  const paged = late.get(key);
  if (paged !== undefined) {
    log(`[code-heat] ${jobKey}: job ${o.job} plans to finish the heat of ${due.comp.slug}'s final phase by ${finishesBy.toISOString()}, past its result deadline ${first.resolveDeadline.toISOString()} (paged at ${paged.toISOString()})`);
    return;
  }
  late.set(key, now());
  page(codeHeatLatePage({ slug: due.comp.slug, phase_id: due.ph.id, job: o.job, rest: o.rest, run_ms: o.runMs, starts_at: o.startsAt, finishes_by: finishesBy, deadline: first.resolveDeadline, escrow: first.escrow }));
}

/** A due heat's phase setup, as its grades ran it (programPhaseSetup of its competition and final phase, no seed). */
function codeHeatPhaseSetup(deps: GradeWorkerDeps, due: Extract<CodeHeatDue, { kind: 'due' }>): Promise<{ setup: ProgramSetup; seed: string }> {
  const { comp, ph, bundle, harness } = due;
  return programPhaseSetup(deps, { slug: comp.slug, bundle, harness, phaseKey: ph.key, competitionKey: competitionSeedKey(comp), seed: null });
}

/**
 * A due heat's work at most (the header's `hand-on`): its finalist places (code-heat.ts codeHeatPlaces), one run's time at
 * most (codeHeatRunMs over `setup`, default the phase's: codeHeatPhaseSetup) and its runs at most (codeHeatPlannedRuns).
 */
async function codeHeatWork(deps: GradeWorkerDeps, due: TimingHeatDue, setup?: ProgramSetup): Promise<{ places: number; runMs: number; plannedRuns: number }> {
  const { codeHeatPlaces } = await import('./code-heat.ts');
  const places = codeHeatPlaces(due.bundle.prizes, due.timing);
  const runMs = codeHeatRunMs(setup ?? (await codeHeatPhaseSetup(deps, due)).setup, due.bundle.limits);
  return { places, runMs, plannedRuns: codeHeatPlannedRuns(due.timing, due.field.length, places) };
}

/**
 * Send the job that times the rest of phase `phaseId`'s heat (the header's `hand-on`): codeHeatJobId `rest:<job id>:<runs
 * kept>`, expiring after the runs still to come at most (server/jobs.ts codeHeatExpirySeconds of them at `runMs` each),
 * not before `startAfter` when one is named. Its id, the send's answer (null: sent before), the runs left and the expiry.
 */
async function sendCodeHeatRest(
  jobs: Pick<JobQueue, 'send'>,
  phaseId: string,
  o: { jobKey: string; kept: number; plannedRuns: number; runMs: number; startAfter?: Date },
): Promise<{ id: string; sent: string | null; rest: number; expireInSeconds: number }> {
  const rest = Math.max(0, o.plannedRuns - o.kept);
  const expireInSeconds = codeHeatExpirySeconds(rest * o.runMs);
  const id = codeHeatJobId(phaseId, `rest:${o.jobKey}:${o.kept}`);
  const sent = await sendCodeHeat(jobs, phaseId, { id, expireInSeconds, ...(o.startAfter === undefined ? {} : { startAfter: o.startAfter }) });
  return { id, sent, rest, expireInSeconds };
}

/** Where the code-heat job keeps a phase's heat runs as they are measured (the header's `resume`): a file of the work root, one per phase. */
export function codeHeatPartialPath(workRoot: string, phaseId: string): string {
  return join(workRoot, `code-heat-partial-${phaseId.toLowerCase()}.json`);
}

/**
 * Drop what was kept for phase `phaseId`'s heat, the runs of a timing heat and the calls of a judge heat (the header's
 * `resume`, `judge heat`): it owes nothing. A removal that fails is logged under `who`.
 */
async function dropCodeHeatPartial(deps: Pick<GradeWorkerDeps, 'workRoot' | 'log'>, phaseId: string, who: string): Promise<void> {
  const { codeHeatPartialFile } = await import('./code-heat.ts');
  for (const [store, what] of [
    [codeHeatPartialFile(codeHeatPartialPath(deps.workRoot, phaseId)), 'runs'],
    [judgeHeatPartialStore(deps.workRoot, phaseId), 'judge calls'],
  ] as const) {
    try {
      await store.remove();
    } catch (err) {
      (deps.log ?? ((line: string) => console.log(line)))(`${who}: the ${what} kept at ${store.where} could not be removed (${err instanceof Error ? err.message : String(err)})`);
    }
  }
}

/** How many runs `store` keeps of a heat (the header's `resume`): 0 when it keeps none, or none that reads as kept runs. */
async function keptCodeHeatRuns(store: CodeHeatPartialStore): Promise<number> {
  const { CodeHeatPartial } = await import('./code-heat.ts');
  try {
    const text = await store.read();
    if (text === null) return 0;
    const parsed = CodeHeatPartial.safeParse(JSON.parse(text));
    return parsed.success ? parsed.data.runs.length : 0;
  } catch {
    return 0;
  }
}

/** Why an attempt of a heat stopped between its runs (the header's `hand-on`): its next run could outlast it. */
class CodeHeatHandOn extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CodeHeatHandOn';
  }
}

/**
 * The heat of a due phase (createProgramHeatHandler), on `sandbox` (the process's clock), recorded; or, when its runs would
 * outlast the attempt, those that fit timed and kept and the rest handed on (null: the header's `hand-on`), paged when
 * the rest plans to end past the result deadline (`late`: pageLateCodeHeat).
 */
async function timeCodeHeat(
  deps: GradeWorkerDeps,
  due: TimingHeatDue,
  sandbox: TimingSandbox,
  jobKey: string,
  ctx: CodeHeatJobContext | undefined,
  late: LatePaged,
): Promise<CodeHeatOutcome | null> {
  const { db, blobs } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  const { comp, ph, bundle, harness, timing, field } = due;
  const { CodeHeatError, codeHeatPartialFile, runCodeHeat } = await import('./code-heat.ts');
  const what = `the timing heat of ${comp.slug}'s final phase (job ${jobKey})`;
  const phaseSetup = await codeHeatPhaseSetup(deps, due);
  const plan = await programPlanAsync(phaseSetup);
  // A timing heat races the entries in one language (contracts/competition.ts ProgramHarness.timing): its one runtime.
  const runtime = harness.runtimes.length === 1 ? harness.runtimes[0]! : null;
  if (runtime === null) throw new PermanentJobError(`${comp.slug}'s harness names ${harness.runtimes.length} runtimes, and a timing heat runs the entries in one`);
  const runRows = await db
    .select()
    .from(run)
    .where(
      inArray(
        run.id,
        field.map((f) => f.run_id),
      ),
    );
  const runOf = new Map(runRows.map((r) => [r.id, r]));
  const subRows = await db
    .select()
    .from(submission)
    .where(
      inArray(
        submission.id,
        field.map((f) => f.submission_id),
      ),
    );
  const subOf = new Map(subRows.map((s) => [s.id, s]));
  const entries: TimedEntry[] = [];
  /** The entry_secret rows each entry is timed with (the header's `entry secrets`), by submission: what its kept runs were measured under. */
  const timedSecretIds = new Map<string, string[]>();
  const sealOf = entrySecretSealOf(deps);
  for (const f of field) {
    const r = runOf.get(f.run_id);
    const sub = subOf.get(f.submission_id);
    if (r === undefined || sub === undefined) throw new CodeHeatError(`entry ${f.submission_id}'s grade run ${f.run_id} is gone`);
    // Timed under any other plan, its runs could never write its graded outputs: the house's to mend, never the entry's.
    if (r.seed !== plan.seed || r.datasetSha256 !== plan.datasetSha256) {
      throw new PermanentJobError(
        `${what}: entry ${f.submission_id}'s final grade (run ${r.id}) ran under seed ${r.seed ?? 'none'} on data ${r.datasetSha256 ?? 'none'}, and the phase's plan is seed ${plan.seed} on ${plan.datasetSha256 ?? 'none'}: its timed runs could never write its graded outputs. Regrade the phase as it stands, then send the heat again`,
      );
    }
    // The env-lane entry secrets its graded run ran with, re-opened (the header's `entry secrets`): its timed runs run as
    // it was graded. One erased since is left out, said by NAME: whether it mattered, its timed outputs show.
    const recorded = await recordedEnvSecrets(db, sealOf, { userId: sub.userId, competitionId: comp.id }, r.entrySecretIds);
    if (recorded.kind === 'unopened') {
      throw new Error(`${what}: the env-lane entry secrets entry ${f.submission_id}'s final grade (run ${r.id}) ran with cannot be opened here, so it is not timed without them (the job tries again): ${recorded.why}`);
    }
    if (recorded.erased !== null) {
      log(`[code-heat] ${jobKey}: entry ${f.submission_id} is timed without the env-lane entry secret its final grade (run ${r.id}) ran with that is erased since (replaced, deleted or purged): ${recorded.erased}; its timed outputs are held to its graded ones as ever`);
    }
    const env = recorded.secrets.env;
    if (recorded.secrets.ids.length > 0) timedSecretIds.set(f.submission_id, recorded.secrets.ids);
    entries.push({
      entry: f.submission_id,
      received_at: f.received_at,
      action_log_sha256: f.action_log_sha256,
      snapshot: { index: await readSnapshotIndex(blobs, f.snapshot_sha256), blobs, ...(recorded.secrets.ids.length === 0 ? {} : { secrets: env }) },
      image_digest: f.image_digest,
    });
  }
  // Named for its job, the same on each attempt: an attempt first removes what one that died left (the header's `scratch`).
  const owner = ctx === undefined ? undefined : regradeOwner(ctx.id);
  if (owner !== undefined) {
    const line = scratchReapLine(what, `attempt ${(ctx?.retryCount ?? 0) + 1}`, await reapGradeScratch(sandbox, deps.workRoot, owner));
    if (line !== null) log(line);
  }
  // The runs this host kept of the phase's heat, and what they must have been measured under (the header's `resume`).
  const partial = codeHeatPartialFile(codeHeatPartialPath(deps.workRoot, ph.id));
  const measuredUnder = {
    phase_id: ph.id.toLowerCase(),
    bundle_sha256: canonicalSha256(JSON.parse(JSON.stringify(bundle)) as unknown),
    dataset_sha256: plan.datasetSha256,
    harness_version: harnessVersion(),
    runtime,
    image_digest: sandbox.imageDigest(runtime),
    // Each entry's entry_secret rows only where it is timed with some, so a field with none keys what it always did.
    field: field
      .map((f) => {
        const secretIds = timedSecretIds.get(f.submission_id);
        return { entry: f.submission_id, snapshot_sha256: f.snapshot_sha256, image_digest: f.image_digest, ...(secretIds === undefined ? {} : { entry_secret_ids: secretIds }) };
      })
      .sort((a, b) => compareCodeUnits(a.entry, b.entry)),
  };

  // The heat's work at most, and what of it this attempt has time for (the header's `hand-on`).
  const { places, runMs, plannedRuns } = await codeHeatWork(deps, due, phaseSetup.setup);
  const slackMs = CODE_HEAT_SLACK_SECONDS * 1000;
  const endsAt = ctx?.expiresAt;
  const jobs = deps.jobs;
  // A run no attempt could hold (its caps past pg-boss's most) is started by each attempt whatever its expiry: one an attempt.
  const anyAttemptHoldsARun = runMs + slackMs <= CODE_HEAT_MAX_EXPIRY_SECONDS * 1000;
  let timedNow = 0;
  const stop = new AbortController();
  /** Stop the heat before its next run when that run at most could end past the attempt's expiry less the slack. */
  const stopIfOutrun = (): void => {
    if (endsAt === undefined || jobs === undefined || stop.signal.aborted) return;
    if (now().getTime() + runMs + slackMs <= endsAt.getTime() || (timedNow === 0 && !anyAttemptHoldsARun)) return;
    stop.abort(new CodeHeatHandOn(`${what}: its next run may take up to ${runMs} ms, and this attempt expires at ${endsAt.toISOString()}`));
  };
  if (endsAt !== undefined && jobs === undefined && now().getTime() + plannedRuns * runMs + slackMs > endsAt.getTime()) {
    log(
      `[code-heat] ${jobKey}: the heat's ${plannedRuns} runs at most, each up to ${runMs} ms, may outlast this attempt (it expires at ${endsAt.toISOString()}), and no queue is handed in to hand the rest on to: ` +
        'it times them all, and should the attempt expire the next job of the phase goes on from the runs it kept',
    );
  }
  stopIfOutrun();
  const signal = ctx?.signal === undefined ? stop.signal : AbortSignal.any([ctx.signal, stop.signal]);
  const started = Date.now();
  let heat: CodeHeatRun;
  try {
    heat = await runCodeHeat({
      plan,
      sandbox,
      runtime,
      limits: bundle.limits,
      workRoot: deps.workRoot,
      blobs,
      phaseSeed: plan.seed,
      timing,
      places,
      entries,
      progress: { store: partial, plan: measuredUnder },
      log: (line) => log(`[code-heat] ${jobKey}: ${line}`),
      // Told of each run as it is recorded, before it is kept: the heat stops before the next one when that may outrun the attempt.
      onRun: () => {
        timedNow++;
        stopIfOutrun();
      },
      ...(owner === undefined ? {} : { owner }),
      signal,
    });
  } catch (err) {
    if (!(stop.signal.aborted && err === stop.signal.reason) || jobs === undefined || endsAt === undefined) throw err;
    // Stopped between runs, every run so far kept (the header's `resume`): the rest goes on in a job sized to it.
    const kept = await keptCodeHeatRuns(partial);
    const next = await sendCodeHeatRest(jobs, ph.id, { jobKey, kept, plannedRuns, runMs });
    log(
      `[code-heat] ${jobKey}: the heat of ${comp.slug}'s final phase hands on: its next run may take up to ${runMs} ms, and this attempt expires at ${endsAt.toISOString()} (${CODE_HEAT_SLACK_SECONDS} s of it kept free); ` +
        `${kept} of its ${plannedRuns} runs at most are kept (${timedNow} timed by this attempt), and job ${next.id}${next.sent === null ? ' (sent before)' : ''} times the rest (${next.rest} at most), expiring ${next.expireInSeconds} s after it starts`,
    );
    // Sent with no startAfter: it starts as soon as the phase's queue lets it.
    await pageLateCodeHeat(deps, due, jobKey, { job: next.id, rest: next.rest, runMs, startsAt: now() }, late);
    return null;
  }
  const wallMs = Date.now() - started;
  const put = await blobs.put(heat.json);
  if (put.sha256 !== heat.sha256) throw new CodeHeatError(`the heat record's blob ${put.sha256} is not its sha256 ${heat.sha256}`);

  // Each field entry's grade run, its score built again with its verdict, and the link to the record: in one transaction.
  const rules = eligibilityRulesOf(bundle);
  const writes = field.map((f) => {
    const r = runOf.get(f.run_id)!;
    const sub = subOf.get(f.submission_id)!;
    const verdict = heat.verdicts.get(f.submission_id);
    if (verdict === undefined) throw new CodeHeatError(`the heat's record holds no verdict on ${f.submission_id}, an entry of its field`);
    const stored = Score.safeParse(r.result);
    if (!stored.success) throw new CodeHeatError(`entry ${f.submission_id}'s grade run ${r.id} holds no score that validates`);
    const timed = scoreWithTiming(stored.data, verdict, { house: standingsHouse(sub), baseline: sub.baseline }, rules);
    return { f, r, verdict, ...timed };
  });
  await db.transaction(async (tx) => {
    for (const w of writes) {
      const [written] = await tx
        .update(run)
        .set({ result: w.result, resultSha256: w.result_sha256, codeHeatSha256: heat.sha256 })
        .where(and(eq(run.id, w.r.id), w.r.resultSha256 === null ? isNull(run.resultSha256) : eq(run.resultSha256, w.r.resultSha256)))
        .returning({ id: run.id });
      if (written === undefined) {
        throw new CodeHeatError(
          `entry ${w.f.submission_id}'s grade run ${w.r.id} changed while the heat ran: nothing of it is written, and the job's retry records the heat again from the runs kept at ${partial.where} while its field and plan stand (else it times the field again)`,
        );
      }
    }
    await recordLiveChange(tx, { ...GRADE_CHANGE, scopeId: comp.id });
  });
  // Recorded and written: nothing is left to resume.
  try {
    await partial.remove();
  } catch (err) {
    log(`[code-heat] ${jobKey}: the heat is recorded, and the runs kept at ${partial.where} could not be removed (${err instanceof Error ? err.message : String(err)})`);
  }
  const keptRuns = heat.resume.kind === 'resumed' ? heat.resume.runs : 0;
  const cpuSources = heat.resume.kind === 'resumed' ? [...heat.resume.cpu_sources] : [heat.record.cpu_source];
  const outcome: CodeHeatOutcome = {
    kind: 'timing',
    phase_id: ph.id,
    heat_sha256: heat.sha256,
    cpu_source: heat.record.cpu_source,
    runs: heat.record.runs.length,
    kept_runs: keptRuns,
    cpu_sources: cpuSources,
    finalists: [...heat.record.finalists],
    wall_ms: wallMs,
    entries: writes.map((w) => ({
      submission_id: w.f.submission_id,
      run_id: w.r.id,
      verdict: w.verdict === TIMING_OUTPUTS_DIFFER ? TIMING_OUTPUTS_DIFFER : 'timed',
      trimmed_mean_cpu_us: w.verdict === TIMING_OUTPUTS_DIFFER ? null : w.verdict.trimmed_mean_cpu_us,
      rounds: w.verdict === TIMING_OUTPUTS_DIFFER ? null : w.verdict.rounds,
      result_sha256: w.result_sha256,
    })),
  };
  const unranked = outcome.entries.filter((e) => e.verdict !== 'timed').map((e) => e.submission_id);
  log(
    `[code-heat] ${jobKey}: timed ${field.length} ${field.length === 1 ? 'entry' : 'entries'} of ${comp.slug}'s final phase in ${outcome.runs} runs` +
      `${keptRuns === 0 ? '' : ` (${keptRuns} kept by an earlier attempt, ${outcome.runs - keptRuns} timed by this one)`} (${(wallMs / 1000).toFixed(1)} s) on ${cpuSources.join(' then ')}; record ${heat.sha256}` +
      `${outcome.finalists.length === 0 ? '' : `; finalists ${outcome.finalists.join(', ')}`}${unranked.length === 0 ? '' : `; unranked (${TIMING_OUTPUTS_DIFFER}): ${unranked.join(', ')}`}`,
  );
  return outcome;
}

// ---------------------------------------------------------------- a judged final's heat (the header's `judge heat`)

/** How long a judge heat held at its opening (grader/judge-call.ts JudgeHold) waits before it is weighed again: its next code-heat job's start. */
export const JUDGE_HEAT_HOLD_RECHECK_MS = 60 * 60_000;

/** When this process last paged each competition's held judge heat, by competition id (AGENT_REFUSAL_PAGE_MS apart). */
type HoldPaged = Map<string, number>;

/** One field entry of a recorded judge heat (JudgeHeatOutcome). */
export interface JudgeHeatEntryOutcome {
  submission_id: string;
  run_id: string;
  /** Its artifact's sha256: the member it played as, one with every entry whose artifact has the same bytes. */
  artifact_sha256: string;
  /** Its verdict (performance.judge): the rank key, and whether its member played the playoff. */
  win_rate_micro: number;
  finalist: boolean;
  /** Its grade run's result_sha256 once the verdict is written. */
  result_sha256: string;
}

/** What a code-heat job recorded on a judge heat (the header's `judge heat`). */
export interface JudgeHeatOutcome {
  kind: 'judge';
  phase_id: string;
  /** The heat record's sha256 (grader/judge-heat.ts JudgeHeatRecord): its blob's name, and every judged run's run.judge_heat_sha256. */
  heat_sha256: string;
  /** The calls the record holds, those an earlier attempt kept of them, and those that came back with no verdict. */
  calls: number;
  kept_calls: number;
  invalid_calls: number;
  /** What the heat spent, µUSD (a u64 decimal): every attempt its keys sent and priced, over every attempt of the job. */
  spent_micro_usd: string;
  /** The playoff's members, artifact sha256s, in Swiss-standing order. */
  finalists: string[];
  /** What retiring this attempt's key found (grader/gateway/masq.ts RetiredTrialKey.flags); empty when it opened none. */
  key_flags: string[];
  /** Every field entry judged, in the field's order. */
  entries: JudgeHeatEntryOutcome[];
  /** Every field entry the heat left out (no artifact, or one the judge cannot read), in the field's order: its run linked to the record, with no verdict. */
  left_out: { submission_id: string; run_id: string; why: string; result_sha256: string | null }[];
}

/** Where the code-heat job keeps a phase's judge calls as they settle (the header's `judge heat`): a file of the work root, one per phase. */
export function judgeHeatPartialPath(workRoot: string, phaseId: string): string {
  return join(workRoot, `judge-heat-partial-${phaseId.toLowerCase()}.json`);
}

/** Where a screened final's partial keeps its screen (judgeHeatPartialStore): a sidecar beside judgeHeatPartialPath's file. */
export function judgeHeatScreenPath(workRoot: string, phaseId: string): string {
  return join(workRoot, `judge-heat-partial-${phaseId.toLowerCase()}.screen.json`);
}

/** The screen sidecar's format (judgeHeatPartialStore): {format, key, screen}, the partial's `screen` and the resume key it was kept under. */
export const JUDGE_HEAT_SCREEN_SIDECAR_FORMAT = 'agent-fun/judge-heat-partial-screen/v1';

/**
 * A phase's kept judge calls (judgeHeatPartialPath), its partial's `screen` written apart (judgeHeatScreenPath): what
 * judgeCodeHeat reads and saves. A screened final's screen holds one input per entrant (50,000 at the field's most),
 * fixed before the heat's first call, while its calls move once a settled call: written whole with them, each settled
 * call re-serialized and rewrote every member (measured: 140 ms of CPU and 16 MB a call at 50,000 members, against
 * 1 ms and 106 KB for the calls of a heat 100 calls in). So `save` writes the screen to its sidecar only when it is
 * another (another object, or another resume key, and then only when its bytes differ from what the sidecar holds),
 * the sidecar before the partial, and the partial without it; and with no screen, removes the sidecar first.
 * `read` gives the partial as one text, `screen` and all, as it was written whole: the sidecar's screen joined in when
 * its key is the partial's (a sidecar of another key, or none, joins nothing: the screen is read from the dev records
 * again, as with none kept), and a partial that holds its screen itself (an earlier release's) as it is. The partial's
 * bytes, its resume key and the record a heat writes are what they were: only where the screen sits moves.
 */
export interface JudgeHeatPartialStore {
  readonly where: string;
  /** The partial kept, its screen joined in (the text a whole partial's file held), or null when none is. */
  read(): Promise<string | null>;
  /**
   * Keep `next` in place of what was kept, its screen in the sidecar (written only when it moved), the rest as `text`
   * writes it (default canonicalJson; sendJudgeHeat's judgeHeatPartialWriter, the same bytes, its calls remembered).
   */
  save(next: JudgeHeatPartialT, text?: (partial: JudgeHeatPartialT) => string): Promise<void>;
  /** Keep nothing: the partial and its sidecar removed. */
  remove(): Promise<void>;
}

export function judgeHeatPartialStore(workRoot: string, phaseId: string): JudgeHeatPartialStore {
  const mainPath = judgeHeatPartialPath(workRoot, phaseId);
  const sidePath = judgeHeatScreenPath(workRoot, phaseId);
  const files = async () => {
    const { codeHeatPartialFile } = await import('./code-heat.ts');
    return { main: codeHeatPartialFile(mainPath), side: codeHeatPartialFile(sidePath) };
  };
  // The sidecar as this store last read or wrote it: its text (null: none), and the screen object and key it was
  // written for (absent when read: the first save of a screen compares the bytes once). Undefined: not known yet.
  let held: { text: string | null; screen?: JudgeHeatScreenInputsT; key?: string } | undefined;
  const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
  return {
    where: mainPath,
    async read() {
      const { main, side } = await files();
      const text = await main.read();
      if (text === null) return null;
      let parsed: unknown;
      try {
        parsed = JSON.parse(text);
      } catch {
        return text; // its reader says why it does not read
      }
      if (!isObject(parsed) || 'screen' in parsed) return text;
      const sideText = await side.read();
      held = { text: sideText };
      if (sideText === null) return text;
      let kept: unknown;
      try {
        kept = JSON.parse(sideText);
      } catch {
        return text; // a sidecar that does not read joins nothing: the screen is read again
      }
      if (!isObject(kept) || kept.format !== JUDGE_HEAT_SCREEN_SIDECAR_FORMAT || kept.key !== parsed.key || kept.screen === undefined) return text;
      return JSON.stringify({ ...parsed, screen: kept.screen });
    },
    async save(next, text = canonicalJson) {
      const { main, side } = await files();
      const { screen, ...rest } = next;
      if (screen === undefined) {
        if (held === undefined || held.text !== null) {
          await side.remove();
          held = { text: null };
        }
      } else if (held?.screen !== screen || held?.key !== next.key) {
        const text = canonicalJson({ format: JUDGE_HEAT_SCREEN_SIDECAR_FORMAT, key: next.key, screen });
        if (held?.text !== text) await side.write(text);
        held = { text, screen, key: next.key };
      }
      await main.write(text(rest));
    },
    async remove() {
      const { main, side } = await files();
      await main.remove();
      await side.remove();
      held = { text: null };
    },
  };
}

/** The environment's masq broker for a judge heat's keys (JudgeWorkerDeps.broker's default), once made; undefined until then. */
let environmentJudgeBroker: MasqJudgeKeyBroker | null | undefined;

/**
 * The broker a judge heat mints its keys at (JudgeWorkerDeps.broker, else the environment's, made once); null: none. The
 * environment's is server/superbot-router.ts judgeKeyBroker over masq's (masqBrokerFromConfig) and, with
 * MAKEFUN_SUPERBOT_ROUTER_URL and _KEY set, the router's (routerJudgeBroker), from one loadConfig().
 */
async function judgeBrokerOf(deps: Pick<GradeWorkerDeps, 'judge'>): Promise<MasqJudgeKeyBroker | null> {
  if (deps.judge?.broker !== undefined) return deps.judge.broker;
  if (environmentJudgeBroker === undefined) {
    const { masqBrokerFromConfig } = await import('./gateway/masq.ts');
    const { judgeKeyBroker, routerJudgeBroker, routerRouteFromConfig } = await import('../server/superbot-router.ts');
    const config = loadConfig();
    const route = routerRouteFromConfig(config);
    environmentJudgeBroker = judgeKeyBroker(masqBrokerFromConfig(config), route === null ? null : routerJudgeBroker(route));
  }
  return environmentJudgeBroker;
}

/** How long a model seen answering a forced form is taken to answer one still (environmentFormsSeen). */
const JUDGE_FORMS_SEEN_MS = 6 * 3_600_000;

/**
 * The models this process saw answer a forced form (`answer` or `tool`, HTTP 200) on the environment's broker, each
 * with when it last did: JudgeWorkerDeps.formsSeen's default beside environmentJudgeBroker, true for 6 h after a note.
 */
const environmentFormsSeen: JudgeFormsSeen = (() => {
  const seen = new Map<string, number>();
  return {
    has: (model) => {
      const at = seen.get(model);
      return at !== undefined && Date.now() - at < JUDGE_FORMS_SEEN_MS;
    },
    note: (model) => {
      seen.set(model, Date.now());
    },
  };
})();

/** The forms memo a heat reads (JudgeWorkerDeps.formsSeen, else the process's own only on the environment's broker). */
function judgeFormsSeenOf(deps: Pick<GradeWorkerDeps, 'judge'>): JudgeFormsSeen | undefined {
  if (deps.judge?.formsSeen !== undefined) return deps.judge.formsSeen;
  return deps.judge?.broker === undefined ? environmentFormsSeen : undefined;
}

/** A kept judge key's format (JudgeKeyFile). */
const JUDGE_KEY_FORMAT = 'makefun/judge-key/v1';

/**
 * One judge key a phase's heats minted, or the attempt about to mint it (the header's `judge keys`): a file of its own
 * under the blob store (judgeKeysDir, `<attempt>.json`), so what it spent is known on whichever host runs the next heat,
 * and the attempt number its label carries (grader/gateway/masq.ts judgeKeyLabel) is no other heat's.
 */
const JudgeKeyFile = z.strictObject({
  format: z.literal(JUDGE_KEY_FORMAT),
  phase_id: z.string().min(1),
  stage: z.enum(['final', 'provisional']),
  attempt: z.int().min(1),
  /** When the attempt was claimed (a claim that never minted expires by it: JUDGE_KEY_CLAIM_EXPIRE_MS). */
  at: IsoDateTime,
  /** The key as minted; null before the mint. */
  key_id: z.string().min(1).nullable(),
  label: z.string().min(1).nullable(),
  /** 0 on every key written now; a provisional key an earlier release wrote may hold its heat's worst case, which nothing reads. */
  reserved_micro_usd: U64,
  /** The heat's meter when the key was last written, and masq's spend on it once retired (null before). */
  meter_micro_usd: U64,
  masq_micro_usd: U64.nullable(),
  /** Whether the key may still spend: not yet retired. */
  open: z.boolean(),
});
type JudgeKeyFileT = z.infer<typeof JudgeKeyFile>;

/** Where a phase's judge keys are kept (JudgeKeyFile): a directory under the blob store's root, which every host grading against the database shares. */
export function judgeKeysDir(blobs: Pick<BlobStore, 'root'>, phaseId: string): string {
  return join(blobs.root, 'judge-keys', phaseId.toLowerCase());
}

/** The names a kept judge key's file takes: `<attempt>.json`. */
const JUDGE_KEY_FILE_RE = /^([1-9][0-9]*)\.json$/;

/**
 * How old a claim that never minted (open, key_id null; by its `at`) is removed by whoever reads the phase's keys (a
 * final heat), and counts nothing: a claim lives the seconds from its claim to its mint, so one older was left by a heat
 * that stopped between them (a crash, a SIGTERM, an abort).
 */
const JUDGE_KEY_CLAIM_EXPIRE_MS = 10 * 60_000;

/**
 * A phase's kept judge keys (judgeKeysDir), in attempt order; none before its first. A file that does not read is
 * thrown: what its key spent cannot be counted. One gone between the listing and its read is none: another heat dropped
 * a claim that minted nothing (dropJudgeKey), and it spent nothing. A claim that never minted, older at `now` than
 * JUDGE_KEY_CLAIM_EXPIRE_MS, is none too, and its file removed; a minted key counts however old.
 */
async function readJudgeKeys(dir: string, now: Date): Promise<JudgeKeyFileT[]> {
  let names: string[];
  try {
    names = await readdir(dir);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw err;
  }
  const keys: JudgeKeyFileT[] = [];
  for (const name of names) {
    if (!JUDGE_KEY_FILE_RE.test(name)) continue;
    const path = join(dir, name);
    let key: JudgeKeyFileT;
    try {
      key = JudgeKeyFile.parse(JSON.parse(await readFile(path, 'utf8')));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') continue;
      throw new Error(`the judge key kept at ${path} does not read (${err instanceof Error ? err.message : String(err)}): what it spent cannot be counted`);
    }
    if (key.open && key.key_id === null && now.getTime() - Date.parse(key.at) > JUDGE_KEY_CLAIM_EXPIRE_MS) {
      await dropJudgeKey(dir, key);
      continue;
    }
    keys.push(key);
  }
  return keys.sort((a, b) => a.attempt - b.attempt);
}

/**
 * Claim a phase's next judge key attempt (the header's `judge keys`), from `from` on and past every attempt kept: its
 * file written whole beside the others, then linked into place, which fails on a name that exists, so two claims never
 * take one number.
 */
async function claimJudgeKey(dir: string, key: Omit<JudgeKeyFileT, 'attempt'>, from: number): Promise<JudgeKeyFileT> {
  await mkdir(dir, { recursive: true });
  let attempt = from;
  for (const name of await readdir(dir)) {
    const m = JUDGE_KEY_FILE_RE.exec(name);
    if (m !== null) attempt = Math.max(attempt, Number(m[1]) + 1);
  }
  const tmp = join(dir, `.claim-${uuidv7()}.tmp`);
  try {
    for (; ; attempt++) {
      const claimed: JudgeKeyFileT = { ...key, attempt };
      await writeFile(tmp, canonicalJson(claimed), { mode: 0o600 });
      try {
        await link(tmp, join(dir, `${attempt}.json`));
        return claimed;
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err;
      }
    }
  } finally {
    await unlink(tmp).catch(() => undefined);
  }
}

/** Write a kept judge key over its file, whole (a file beside it renamed into place). */
async function writeJudgeKey(dir: string, key: JudgeKeyFileT): Promise<JudgeKeyFileT> {
  const tmp = join(dir, `.${key.attempt}-${uuidv7()}.tmp`);
  await writeFile(tmp, canonicalJson(key), { mode: 0o600 });
  await rename(tmp, join(dir, `${key.attempt}.json`));
  return key;
}

/** Drop a claimed attempt that minted nothing (a heat held before its mint): its number goes to the next heat. */
async function dropJudgeKey(dir: string, key: JudgeKeyFileT): Promise<void> {
  await unlink(join(dir, `${key.attempt}.json`)).catch((err: unknown) => {
    if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
  });
}

/** A kept key retired: what masq says it spent beside the heat's meter, and nothing more reserved. */
function retiredJudgeKey(key: JudgeKeyFileT, meterMicroUsd: bigint, retired: RetiredTrialKey): JudgeKeyFileT {
  return { ...key, reserved_micro_usd: '0', meter_micro_usd: String(meterMicroUsd), masq_micro_usd: String(retired.spend.microUsd), open: false };
}

/** A judge pool seat's format (JudgePoolSeatFile, `<id>.json`): what every grader process reads, an old one too. */
const JUDGE_POOL_FORMAT = 'makefun/judge-pool/v1';
/** A judge pool seat's second file's format (JudgePoolSeatFileV2, `<id>.seat`): its class and its sends in flight besides. */
const JUDGE_POOL_FORMAT_V2 = 'makefun/judge-pool/v2';

/** A seat's id, and so its files' name stem (`<id>.json`, `<id>.seat`). */
const JUDGE_POOL_ID_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JUDGE_POOL_FILE_RE = /^([A-Za-z0-9_-]{1,128})\.json$/;
const JUDGE_POOL_FILE_V2_RE = /^([A-Za-z0-9_-]{1,128})\.seat$/;

/**
 * A live judge heat's seat in the platform's one budget of judge sends in flight (the header's `judge heat`;
 * JUDGE_POOL_BUDGET): a file of its own under the blob store (judgePoolDir, `<id>.json`), which every grader process of
 * the deployment reads. `want`: the sends the heat could use right now; `at`: when the file was last written (a seat
 * older than JUDGE_POOL_STALE_MS counts no more: its process died).
 */
const JudgePoolSeatFile = z.strictObject({
  format: z.literal(JUDGE_POOL_FORMAT),
  id: z.string().regex(JUDGE_POOL_ID_RE),
  label: z.string(),
  want: z.int().min(0),
  at: IsoDateTime,
});

/**
 * A judge heat's class in the pool (judgePoolShares): a final's heat goes first; a dev grade's provisional one shares
 * what is left; a dev contender round (playContenderRound) takes only what every other seat's share leaves.
 */
export type JudgePoolClassT = 'final' | 'practice' | 'contender';

/**
 * A seat's second file (`<id>.seat`, beside its `<id>.json`), which only a process that knows classes reads: the seat's
 * want again, its class, and `flying`, the sends its heat held in flight when written (judgePoolAllowance). Its own file,
 * never a change to `<id>.json`: a process from before it parses `<id>.json` strictly at v1 and counts nothing for a
 * file that does not parse (it sweeps it, removed only once 10 minutes old by its mtime, which a live seat's never is),
 * so a seat written only at v2 would drop out of an old process's pool and split it; `<id>.seat` matches no name an old
 * process reads or removes, and it goes on reading `<id>.json` at v1, as today. Written whenever `<id>.json` is and
 * whenever `flying` moved, at most each JUDGE_POOL_REFRESH_MS; a reader takes it over `<id>.json` while it is fresh.
 *
 * A 'contender' seat writes its `<id>.seat` alone, never an `<id>.json` (it rewrites it on the same beat): a process
 * that knows only 'final' and 'practice' fails to parse its class and so never counts it, which is safe, since a
 * contender seat only ever takes what every other seat's share leaves; a reader that knows the class takes a fresh
 * `<id>.seat` with no `<id>.json` beside it, as it takes any fresh `<id>.seat`.
 */
const JudgePoolSeatFileV2 = z.strictObject({
  format: z.literal(JUDGE_POOL_FORMAT_V2),
  id: z.string().regex(JUDGE_POOL_ID_RE),
  label: z.string(),
  class: z.enum(['final', 'practice', 'contender']),
  want: z.int().min(0),
  flying: z.int().min(0),
  at: IsoDateTime,
});

/** Where the live judge heats' seats are kept (JudgePoolSeatFile): a directory under the blob store's root, which every grader process shares. */
export function judgePoolDir(blobs: Pick<BlobStore, 'root'>): string {
  // Shared today because every grader pod mounts one claim on the cluster's one node (makefun-data, ReadWriteOnce, local-path; checked 2026-11-11): a grader on a second node would not see these seats.
  return join(blobs.root, 'judge-pool');
}

/** A seat as the share rule reads it (judgePoolShares): `class` absent or null for an old process's seat, which names none. */
export interface JudgePoolSeatWantT {
  id: string;
  want: number;
  class?: JudgePoolClassT | null;
}

/** A seat as the overshoot bound reads it (judgePoolAllowance): `flying` the sends it holds in flight, null when not known (an old process's seat). */
export interface JudgePoolSeatCountT extends JudgePoolSeatWantT {
  flying?: number | null;
}

/** A number as the pool reads it: a whole number >= 0, anything else 0. */
const poolWhole = (n: number): number => (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0);

/** `left` split max-min fair over `wants` (ids in code-unit order), each share then at least min(want, least). */
function judgePoolFair(left: number, wants: ReadonlyMap<string, number>, least: number): Map<string, number> {
  const ids = [...wants.keys()].sort(compareCodeUnits);
  const shares = new Map<string, number>(ids.map((id) => [id, 0]));
  let open = ids.filter((id) => wants.get(id)! > 0);
  for (;;) {
    // Each want at most an equal split of what is left (want x seats <= left, in whole numbers) is met at once.
    const fits = open.filter((id) => wants.get(id)! * open.length <= left);
    if (fits.length === 0) break;
    for (const id of fits) {
      shares.set(id, wants.get(id)!);
      left -= wants.get(id)!;
    }
    open = open.filter((id) => !fits.includes(id));
  }
  if (open.length > 0) {
    const each = Math.floor(left / open.length);
    let rest = left - each * open.length;
    for (const id of open) {
      shares.set(id, each + (rest > 0 ? 1 : 0));
      if (rest > 0) rest--;
    }
  }
  for (const id of ids) shares.set(id, Math.max(shares.get(id)!, Math.min(wants.get(id)!, least)));
  return shares;
}

/**
 * The share rule's working (judgePoolShares): each seat's share and the floor it was held to (min(want, its tier's
 * floor); 0 for a contender seat), in code-unit order of ids. The contender seats (an id every entry of which names
 * 'contender') are set aside: every other seat's share is the rule's over the rest alone (judgePoolTiersOf, bit for bit
 * what it is with no contender seat), and the contender seats split max(0, budget - the sum of those shares) max-min
 * fair with floor 0.
 */
function judgePoolTiers(budget: number, seats: readonly JudgePoolSeatWantT[], floor: number): { shares: Map<string, number>; floors: Map<string, number> } {
  const notContender = new Set<string>();
  for (const s of seats) if (s.class !== 'contender') notContender.add(s.id);
  const contenders = new Map<string, number>();
  for (const s of seats) if (!notContender.has(s.id)) contenders.set(s.id, Math.max(contenders.get(s.id) ?? 0, poolWhole(s.want)));
  if (contenders.size === 0) return judgePoolTiersOf(budget, seats, floor);
  // The other seats (an id also named 'contender' by an entry of it read in that entry as a practice heat's).
  const rest = judgePoolTiersOf(
    budget,
    seats.filter((s) => notContender.has(s.id)).map((s) => (s.class === 'contender' ? { ...s, class: 'practice' as const } : s)),
    floor,
  );
  // What every other seat's share leaves, split over the contender seats alone, none floored.
  let given = 0;
  for (const n of rest.shares.values()) given += n;
  const low = judgePoolFair(Math.max(0, poolWhole(budget) - given), contenders, 0);
  const ids = [...rest.shares.keys(), ...contenders.keys()].sort(compareCodeUnits);
  return {
    shares: new Map<string, number>(ids.map((id) => [id, rest.shares.get(id) ?? low.get(id)!])),
    floors: new Map<string, number>(ids.map((id) => [id, rest.floors.get(id) ?? 0])),
  };
}

/** judgePoolTiers over seats none of which is a contender's: the final and practice tiers. */
function judgePoolTiersOf(budget: number, seats: readonly JudgePoolSeatWantT[], floor: number): { shares: Map<string, number>; floors: Map<string, number> } {
  const wants = new Map<string, number>();
  // A seat in the first tier: a final's, or an old process's (no class), which takes an equal split whatever it is.
  const first = new Set<string>();
  let final = false;
  for (const s of seats) {
    wants.set(s.id, Math.max(wants.get(s.id) ?? 0, poolWhole(s.want)));
    if (s.class !== 'practice') first.add(s.id);
    if (s.class === 'final') final = true;
  }
  const least = poolWhole(floor);
  const ids = [...wants.keys()].sort(compareCodeUnits);
  if (!final) {
    const shares = judgePoolFair(poolWhole(budget), wants, least);
    return { shares, floors: new Map<string, number>(ids.map((id) => [id, Math.min(wants.get(id)!, least)])) };
  }
  const top = judgePoolFair(poolWhole(budget), new Map<string, number>(ids.filter((id) => first.has(id)).map((id) => [id, wants.get(id)!])), least);
  let given = 0;
  for (const n of top.values()) given += n;
  const low = Math.min(least, JUDGE_POOL_PRACTICE_FLOOR);
  const rest = judgePoolFair(Math.max(0, poolWhole(budget) - given), new Map<string, number>(ids.filter((id) => !first.has(id)).map((id) => [id, wants.get(id)!])), low);
  const shares = new Map<string, number>(ids.map((id) => [id, top.get(id) ?? rest.get(id)!]));
  return { shares, floors: new Map<string, number>(ids.map((id) => [id, Math.min(wants.get(id)!, first.has(id) ? least : low)])) };
}

/**
 * The share of a judge pool's `budget` (sends in flight) each seat takes (the header's `judge heat`), max-min fair over
 * the seats' wants in whole sends: a seat wanting no more than an equal split of what is left takes its want, until none
 * does, and the seats left split what remains equally, its indivisible remainder one send each in the code-unit order
 * of their ids, so every process computes the same shares from the same files. Every seat takes at least
 * min(want, floor), even past the budget (many heats at once: none starves). A want is read as a whole number >= 0
 * (anything else 0), a repeated id once at its largest want; a seat wanting 0 takes 0. Under JUDGE_POOL_BUDGET (96): a
 * seat alone wanting 64 takes 64; two wanting 64 take 48 and 48; one wanting 64 beside one wanting 8 (a round in its
 * tail) takes 64, the other 8; three wanting 64 take 32 each.
 *
 * Final first: while a seat of class 'final' is live, the finals' seats (and any seat naming no class, an old process's,
 * which takes an equal split of what it sees whatever the rest decide, so it is reserved one) split the budget as above
 * first, and the 'practice' seats split what is left, max(0, budget - those shares), each floored at
 * min(want, JUDGE_POOL_PRACTICE_FLOOR) (1), not 4: so a final alone wanting 64 beside 25 practice heats takes 64, and the
 * pool holds at most the budget plus one a practice heat. A repeated id is in the first tier when any of its entries
 * is. With no final live, the classes change nothing: the equal shares above, exactly.
 *
 * Contender last: a 'contender' seat's (a dev contender round's, playContenderRound) is left out of the rule above,
 * which shares the budget over every other seat exactly as it would with no contender seat live, and the contender
 * seats split only what those shares leave, max(0, budget - their sum), max-min fair with floor 0: a contender seat may
 * take 0 (its sender still keeps one send in flight, sendJudgeHeatCalls' max(1, share), so a round never stalls). A
 * repeated id is a contender seat only when every one of its entries is (else its contender entry reads as a practice heat's).
 */
export function judgePoolShares(budget: number, seats: readonly JudgePoolSeatWantT[], floor: number = JUDGE_POOL_FLOOR): Map<string, number> {
  return judgePoolTiers(budget, seats, floor).shares;
}

/**
 * The sends in flight seat `id` may hold now (openJudgePoolSeat's share()): its share (judgePoolShares) less the pool's
 * observed excess, what the other seats hold in flight past their own shares (each `flying` known, past its share;
 * an unknown one, an old process's, as within it), never under its floor (min(want, its tier's floor)) and never past
 * its share. A heat cancels nothing in flight when its share falls, it only stops sending: without this a heat that
 * joins (or whose want rises, a final's next Swiss round) would fill to its share at once while the others still hold
 * their old ones, past the budget by what they hold over (a final at 64 beside three full practice heats: 136 for
 * 10-13 s). With it the joiner grows as the others' sends complete, and the pool's total stays within the budget plus
 * the floors, however many join at once (each takes the whole excess off its own share). A seat absent from `seats`: 0.
 */
export function judgePoolAllowance(budget: number, seats: readonly JudgePoolSeatCountT[], id: string, floor: number = JUDGE_POOL_FLOOR): number {
  const { shares, floors } = judgePoolTiers(budget, seats, floor);
  const mine = shares.get(id);
  if (mine === undefined) return 0;
  // Each other seat's sends in flight, a repeated id at its most; past its share, the excess.
  const held = new Map<string, number>();
  for (const s of seats) {
    if (s.id === id || s.flying === undefined || s.flying === null) continue;
    held.set(s.id, Math.max(held.get(s.id) ?? 0, poolWhole(s.flying)));
  }
  let over = 0;
  for (const [other, n] of held) over += Math.max(0, n - (shares.get(other) ?? 0));
  return Math.min(mine, Math.max(floors.get(id)!, mine - over));
}

/** A live heat's seat in the judge pool (openJudgePoolSeat): what the sender reads and tells each turn, and its end. */
export interface JudgePoolSeat {
  /** Its id: its file's name stem, and its place in the shares' remainder order. */
  readonly id: string;
  /**
   * The sends in flight this heat may hold now: its allowance as last computed (judgePoolAllowance: its share less what
   * the others hold past theirs), never under min(want, its tier's floor); once the pool's I/O failed, the whole budget,
   * or 0 for a 'contender' seat (it never takes budget it cannot see is left: its sender's one send in flight alone).
   */
  share(): number;
  /** The sends the heat could use right now (a whole number, held to the budget): its share recomputed against the seats last read, and written at the next refresh. */
  want(n: number): void;
  /** The sends the heat holds in flight now (a whole number), backups counted: written to its `<id>.seat` at the next refresh, for the others' bound (judgePoolAllowance). */
  flying(n: number): void;
  /**
   * Start one refresh (never awaited, never two at once) once the last began JUDGE_POOL_REFRESH_MS ago or the beat is
   * due (JUDGE_POOL_BEAT_MS since the last write): the file written when its want moved or the beat is due, the
   * directory read, the share recomputed.
   */
  tick(): void;
  /** Remove its file (once its refresh in hand ends); again, the same promise. Never rejects. */
  close(): Promise<void>;
}

export interface JudgePoolSeatOptions {
  /** The seats' directory (judgePoolDir): made when missing. */
  dir: string;
  /** The pool's sends in flight across every seat (default JUDGE_POOL_BUDGET). */
  budget?: number;
  /** The clock the seat's `at` and its refreshes run on (default Date.now). */
  clock?: Pick<JudgeHeatClock, 'now'>;
  /** What the seat's file and its log lines name it (default `a judge heat`). */
  label?: string;
  /** The sends the heat could use as it opens (default the budget). */
  want?: number;
  /** Its heat's class (judgePoolShares: a final's goes first, a contender round's last; default 'practice'). A contender seat writes its `<id>.seat` alone. */
  class?: JudgePoolClassT;
  /** Where an I/O failure is said, once per line (default console.log). */
  log?: (line: string) => void;
}

/** How old a seat's file (by its `at`; a file that does not read, or a writer's temp file, by its mtime) is removed by whoever reads it. */
const JUDGE_POOL_REMOVE_MS = 10 * 60_000;

/**
 * Take a live heat's seat in the judge pool (the header's `judge heat`): its files written (`<id>.json` at v1 for every
 * process, `<id>.seat` at v2 with its class and sends in flight for those that read it; each a file beside it renamed
 * into place) and the directory read once before it resolves, so its first share() is right. A reader takes a seat's
 * fresh `<id>.seat` over its `<id>.json`, and an `<id>.json` alone (an old process's seat) as naming no class and no
 * count (judgePoolShares, judgePoolAllowance). The pool can never cost a heat:
 * an I/O failure of a write, a read or the removal is logged once per line, and the seat then answers the whole budget
 * (its own width alone then bounds the heat, as before the pool) until a refresh goes through whole; this never rejects.
 * A 'contender' seat is the exception: it takes only what every other seat's share leaves, which a seat that cannot
 * read or write the pool cannot know, so it then answers 0 (its sender keeps its one send in flight,
 * sendJudgeHeatCalls' max(1, share)) and takes no budget from a final's or a practice heat's seat until a refresh goes
 * through whole.
 */
export async function openJudgePoolSeat(o: JudgePoolSeatOptions): Promise<JudgePoolSeat> {
  const budget = o.budget !== undefined && Number.isSafeInteger(o.budget) && o.budget > 0 ? o.budget : JUDGE_POOL_BUDGET;
  const clock = o.clock;
  const now = (): number => (clock === undefined ? Date.now() : clock.now());
  const log = o.log ?? ((line: string) => console.log(line));
  const label = o.label ?? 'a judge heat';
  const id = uuidv7();
  const path = join(o.dir, `${id}.json`);
  const pathV2 = join(o.dir, `${id}.seat`);
  const cls: JudgePoolClassT = o.class === 'final' || o.class === 'contender' ? o.class : 'practice';
  // A contender seat keeps its `<id>.seat` alone (JudgePoolSeatFileV2): no process that cannot read its class counts it.
  const seatOnly = cls === 'contender';
  const held = (n: number): number => (Number.isFinite(n) && n > 0 ? Math.min(budget, Math.floor(n)) : 0);
  let want = held(o.want ?? budget);
  // The sends its heat holds in flight, as last told.
  let flying = 0;
  // The other seats as last read, this seat's allowance against them, whether the pool's I/O failed since.
  let others: JudgePoolSeatCountT[] = [];
  let share = budget;
  let broken = false;
  // What it answers while the pool's I/O is failed: the whole budget, or a contender seat nothing past its one send.
  const blind = seatOnly ? 0 : budget;
  // The want its `<id>.json` holds (null before its first write) and when it was written; the want and count its
  // `<id>.seat` holds (null before its first write); when the last refresh began.
  let wrote: number | null = null;
  let wroteAt = Number.NEGATIVE_INFINITY;
  let wroteV2: { want: number; flying: number } | null = null;
  let refreshedAt = Number.NEGATIVE_INFINITY;
  let running: Promise<void> | null = null;
  let closing: Promise<void> | null = null;
  const said = new Set<string>();
  const fail = (what: string, err: unknown): void => {
    broken = true;
    const code = (err as NodeJS.ErrnoException | null)?.code;
    const why = typeof code === 'string' ? code : err instanceof Error ? err.message : String(err);
    const line = seatOnly
      ? `judge pool: the seat of ${label} at ${o.dir} could not be ${what} (${why}): a contender round takes no pool budget it cannot see is left, so it holds one send in flight until the pool reads again`
      : `judge pool: the seat of ${label} at ${o.dir} could not be ${what} (${why}): its own width alone bounds the heat, as before the pool`;
    if (said.has(line)) return;
    said.add(line);
    try {
      log(line);
    } catch {
      // A log that throws costs the heat nothing either.
    }
  };
  const recompute = (): void => {
    share = judgePoolAllowance(budget, [...others, { id, want, class: cls }], id);
  };
  // One file written whole: a file beside it renamed into place.
  const put = async (file: string, body: Record<string, string | number>): Promise<void> => {
    const tmp = join(o.dir, `.${id}-${uuidv7()}.tmp`);
    try {
      await writeFile(tmp, canonicalJson(body), { mode: 0o644 });
      await rename(tmp, file);
    } catch (err) {
      await unlink(tmp).catch(() => undefined);
      throw err;
    }
  };
  // `<id>.json` when the beat is due or its want moved, `<id>.seat` then too and whenever its count moved; a contender
  // seat's `<id>.seat` alone, on the same beats.
  const write = async (beat: boolean): Promise<void> => {
    const n = want;
    const f = flying;
    const v1 = beat || n !== wrote;
    if (!v1 && wroteV2 !== null && wroteV2.want === n && wroteV2.flying === f) return;
    const at = now();
    const stamp = new Date(at).toISOString();
    await mkdir(o.dir, { recursive: true });
    if (v1) {
      if (!seatOnly) await put(path, { format: JUDGE_POOL_FORMAT, id, label, want: n, at: stamp });
      wrote = n;
      wroteAt = at;
    }
    await put(pathV2, { format: JUDGE_POOL_FORMAT_V2, id, label, class: cls, want: n, flying: f, at: stamp });
    wroteV2 = { want: n, flying: f };
  };
  // A file that does not read, or a writer's temp file, removed once 10 minutes old by its mtime: best effort.
  const sweep = async (name: string): Promise<void> => {
    try {
      const st = await stat(join(o.dir, name));
      if (Date.now() - st.mtimeMs > JUDGE_POOL_REMOVE_MS) await unlink(join(o.dir, name));
    } catch {
      // Gone already, or another reader's to remove.
    }
  };
  const read = async (): Promise<void> => {
    const t = now();
    const names = await readdir(o.dir);
    const seen = new Map<string, JudgePoolSeatCountT>();
    // A seat's `<id>.seat` first: fresh, it stands for the seat (its class and count), and its `<id>.json` goes unread.
    for (const name of names) {
      const m = JUDGE_POOL_FILE_V2_RE.exec(name);
      if (m === null || m[1] === id) continue;
      let seat: z.infer<typeof JudgePoolSeatFileV2>;
      try {
        seat = JudgePoolSeatFileV2.parse(JSON.parse(await readFile(join(o.dir, name), 'utf8')));
      } catch {
        await sweep(name);
        continue;
      }
      if (seat.id !== m[1]) continue;
      const age = t - Date.parse(seat.at);
      if (age > JUDGE_POOL_REMOVE_MS) {
        await unlink(join(o.dir, name)).catch(() => undefined);
        continue;
      }
      if (age > JUDGE_POOL_STALE_MS) continue;
      seen.set(seat.id, { id: seat.id, want: seat.want, class: seat.class, flying: seat.flying });
    }
    // Then each `<id>.json` with no fresh `<id>.seat`: an old process's seat, naming no class and no count.
    for (const name of names) {
      const m = JUDGE_POOL_FILE_RE.exec(name);
      if (m === null) {
        if (name.startsWith('.') && name.endsWith('.tmp')) await sweep(name);
        continue;
      }
      if (m[1] === id || seen.has(m[1]!)) continue;
      let seat: z.infer<typeof JudgePoolSeatFile>;
      try {
        seat = JudgePoolSeatFile.parse(JSON.parse(await readFile(join(o.dir, name), 'utf8')));
      } catch {
        await sweep(name);
        continue;
      }
      if (seat.id !== m[1]) continue;
      const age = t - Date.parse(seat.at);
      if (age > JUDGE_POOL_REMOVE_MS) {
        await unlink(join(o.dir, name)).catch(() => undefined);
        continue;
      }
      if (age > JUDGE_POOL_STALE_MS) continue;
      seen.set(seat.id, { id: seat.id, want: seat.want, class: null, flying: null });
    }
    others = [...seen.values()];
  };
  const refresh = async (beat: boolean): Promise<void> => {
    try {
      await write(beat);
    } catch (err) {
      fail('written', err);
      return;
    }
    try {
      await read();
    } catch (err) {
      fail('read', err);
      return;
    }
    broken = false;
    recompute();
  };
  const seat: JudgePoolSeat = {
    id,
    share: () => (broken ? blind : share),
    want(n) {
      want = held(n);
      if (!broken) recompute();
    },
    flying(n) {
      flying = poolWhole(n);
    },
    tick() {
      if (closing !== null || running !== null) return;
      const t = now();
      const beat = t - wroteAt >= JUDGE_POOL_BEAT_MS;
      if (!beat && t - refreshedAt < JUDGE_POOL_REFRESH_MS) return;
      refreshedAt = t;
      running = refresh(beat).finally(() => {
        running = null;
      });
    },
    close() {
      closing ??= (async () => {
        if (running !== null) await running;
        if (wrote === null) return;
        // `<id>.seat` first: a reader that finds `<id>.json` alone counts it as an old process's seat until it goes too.
        for (const file of seatOnly ? [pathV2] : [pathV2, path]) {
          try {
            await unlink(file);
          } catch (err) {
            if ((err as NodeJS.ErrnoException).code !== 'ENOENT') fail('removed', err);
          }
        }
      })();
      return closing;
    },
  };
  try {
    refreshedAt = now();
  } catch (err) {
    fail('timed', err);
  }
  await refresh(true);
  return seat;
}

/**
 * The seat a heat takes in the judge pool while it sends (JudgeWorkerDeps.pool; the header's `judge heat`), of its
 * class (a final's heat 'final', a dev grade's provisional one 'practice', a dev contender round 'contender'): on the deps' pool, else, with none named,
 * only on the environment's broker; null: none.
 */
async function judgePoolSeatOf(deps: Pick<GradeWorkerDeps, 'judge' | 'blobs'>, label: string, cls: JudgePoolClassT, log: (line: string) => void): Promise<JudgePoolSeat | null> {
  const pool = deps.judge?.pool;
  if (pool === null) return null;
  if (pool === undefined && deps.judge?.broker !== undefined) return null;
  const clock = deps.judge?.clock;
  return openJudgePoolSeat({
    dir: pool?.dir ?? judgePoolDir(deps.blobs),
    ...(pool?.budget === undefined ? {} : { budget: pool.budget }),
    ...(clock === undefined ? {} : { clock }),
    label,
    class: cls,
    log,
  });
}

/**
 * A program/v1 score that passed, built again with its entry's judge heat verdict (performance.judge): grade.ts
 * scoreWithTiming's twin, the score's own facts and inputs as they were, the entry's facts and the rules given. A
 * verdict moves no eligibility, so only performance.judge is new (the entry's launch, performance.entry_link, rides the
 * rebuilt performance as it was); grader/regrade.ts builds the same from the heat's record (judgeVerdictOf). A TypeError
 * for a score that is no program/v1 one, or did not pass. What createProgramHeatHandler
 * writes on a judged run; with null, the score built again with no verdict, what it writes on a run the heat left out
 * whose score carried one.
 */
export function scoreWithJudge(score: ScoreT, judge: ProgramJudgeScoreT | null, entry: EntryFacts, rules: EligibilityRules): { result: ScoreT; result_sha256: string } {
  const perf = score.performance;
  if (perf.kind !== 'program/v1') throw new TypeError(`a judge verdict is a program/v1 score's, and this score is ${perf.kind}`);
  if (perf.passed !== true) throw new TypeError('a judge verdict is the verdict of an entry that passed the gate, and this score did not pass');
  const result = buildScore(
    {
      harness: score.harness,
      image_digest: score.image_digest,
      dataset_sha256: score.dataset_sha256,
      seed: score.seed,
      deterministic: !score.flags.includes('nondeterministic'),
      execution_flags: score.flags.filter((f) => f !== 'nondeterministic'),
      house: entry.house,
      baseline: entry.baseline,
    },
    {
      action_log_sha256: score.action_log_sha256,
      // The entry's launch is the run's own fact, never the heat's: it rides the rebuilt performance as it was.
      performance: { kind: 'program/v1', scores: perf.scores, ...(perf.entry_link === undefined ? {} : { entry_link: perf.entry_link }), ...(judge === null ? {} : { judge }) },
      performance_flags: [],
      cost: score.cost,
      authorship: score.authorship,
      size: score.size,
    },
    rules,
    score.scorer_version,
  );
  return { result, result_sha256: scoreDigest(result).sha256 };
}

/** The judge directory a bundle seals, read (readJudgeDir): the judge's prompt, and its house anchors (each file's sha256 and size) with their bytes by sha256. */
export interface JudgeDirInputs {
  prompt: string;
  anchors: { file: string; artifact_sha256: string; artifact_bytes: number }[];
  artifacts: Map<string, Uint8Array>;
}

/**
 * Read the judge directory a bundle seals under the competition's directory (cli/grade-local.ts's local heat):
 * readJudgeTree of judge.dir there.
 */
export function readJudgeDir(compDir: string, judge: ProgramJudgeT): JudgeDirInputs | { refused: string } {
  return readJudgeTree(join(compDir, ...judge.dir.split('/')), judge);
}

/**
 * Read the judge directory a bundle seals at `judgeDir` (judgeHeatInputs, withProvisionalJudge: where judgedTreesOf
 * finds it, the competition's directory or a sponsored judged-artifact competition's materialized one; readJudgeDir),
 * held to its tree digest judge_sha256 (treeSha256): its prompt and its anchors. `refused` when no such directory is
 * there or another one is: no retry mends that.
 */
export function readJudgeTree(judgeDir: string, judge: ProgramJudgeT): JudgeDirInputs | { refused: string } {
  let judgeSha: string;
  try {
    judgeSha = treeSha256(judgeDir);
  } catch (err) {
    return judgeTreeUnread(judge, err);
  }
  const other = judgeTreeOther(judge, judgeSha);
  if (other !== null) return other;
  const prompt = readFileSync(join(judgeDir, ...judge.agent.prompt.split('/')), 'utf8');
  // The anchors: regular files flat under anchors/ (server/competitions/load.ts held them so at load, and the digest just matched).
  const anchorsDir = join(judgeDir, PROGRAM_JUDGE_ANCHORS_DIR);
  const files = readdirSync(anchorsDir).sort(compareCodeUnits);
  return judgeTreeInputs(prompt, files.map((file) => ({ file, bytes: new Uint8Array(readFileSync(join(anchorsDir, file))) })));
}

/**
 * readJudgeTree off the event loop's back, the same answer: the tree digest on fs/promises (load.ts treeSha256Async, a
 * file hashed before answered from its stat), the prompt and every anchor read with fs/promises. What a grade reads its
 * judge directory by (a provisional heat, every judged dev grade; a contender round; a final's screen); the command line
 * keeps readJudgeDir.
 */
export async function readJudgeTreeAsync(judgeDir: string, judge: ProgramJudgeT): Promise<JudgeDirInputs | { refused: string }> {
  let judgeSha: string;
  try {
    judgeSha = await treeSha256Async(judgeDir);
  } catch (err) {
    return judgeTreeUnread(judge, err);
  }
  const other = judgeTreeOther(judge, judgeSha);
  if (other !== null) return other;
  const prompt = await readFile(join(judgeDir, ...judge.agent.prompt.split('/')), 'utf8');
  const anchorsDir = join(judgeDir, PROGRAM_JUDGE_ANCHORS_DIR);
  const files = (await readdir(anchorsDir)).sort(compareCodeUnits);
  const read: { file: string; bytes: Uint8Array }[] = [];
  for (const file of files) read.push({ file, bytes: new Uint8Array(await readFile(join(anchorsDir, file))) });
  return judgeTreeInputs(prompt, read);
}

/** readJudgeTree's refusal of a judge directory whose digest cannot be taken (`err`, why). */
function judgeTreeUnread(judge: ProgramJudgeT, err: unknown): { refused: string } {
  return { refused: `the judge directory ${judge.dir} does not read (${err instanceof Error ? err.message : String(err)}): the image holds no judge for this bundle` };
}

/** readJudgeTree's refusal of a judge directory digesting to `judgeSha`, another than the bundle seals; null when it is the sealed one. */
function judgeTreeOther(judge: ProgramJudgeT, judgeSha: string): { refused: string } | null {
  if (judgeSha === judge.judge_sha256) return null;
  return { refused: `the judge directory ${judge.dir} hashes to ${judgeSha}, and the bundle seals ${judge.judge_sha256}: the image holds another judge than the bundle's` };
}

/** readJudgeTree's answer from its prompt and its anchors' bytes (in code-unit order of their names), each anchor by its sha256. */
function judgeTreeInputs(prompt: string, files: readonly { file: string; bytes: Uint8Array }[]): JudgeDirInputs {
  const artifacts = new Map<string, Uint8Array>();
  const anchors = files.map(({ file, bytes }) => {
    const sha256 = sha256Hex(bytes);
    artifacts.set(sha256, bytes);
    return { file, artifact_sha256: sha256, artifact_bytes: bytes.byteLength };
  });
  return { prompt, anchors, artifacts };
}

/**
 * Why the judge cannot read an artifact (grader/judge-call.ts judgeUserContent: JudgeArtifactRefused, a text not UTF-8,
 * an unknown image type, or a dossier contracts/dossier.ts parseDossier refuses, its DossierRefused message quoted), or
 * null when it can.
 */
async function judgeArtifactRefusal(media: ProgramJudgeT['media'], art: { sha256: string; bytes: Uint8Array }): Promise<string | null> {
  const { JudgeArtifactRefused, judgeUserContent } = await import('./judge-call.ts');
  try {
    judgeUserContent(media, art, art);
    return null;
  } catch (err) {
    if (err instanceof JudgeArtifactRefused) return err.message;
    throw err;
  }
}

/**
 * What a final's judge heat reads of each field entry's grade run (judgeHeatInputs): its id and seed, and the score the
 * heat's verdict is written over, held to its sha256 (judgeCodeHeat's write). None of the run's other columns.
 */
const JUDGE_HEAT_RUN_COLUMNS = { id: run.id, seed: run.seed, result: run.result, resultSha256: run.resultSha256 };
type JudgeHeatRun = Pick<RunRow, keyof typeof JUDGE_HEAT_RUN_COLUMNS>;

/** A judge heat's field read in: each entry's artifact from its final grade's outputs, the house anchors, and the judge's prompt. */
interface JudgeHeatInputs {
  setup: JudgeHeatSetupT;
  prompt: string;
  /** Every member's bytes, by sha256: what the judge reads. */
  artifacts: Map<string, Uint8Array>;
  /** Each field entry the heat judges, its grade run and artifact, in the field's order. */
  entries: { row: CodeHeatFieldRow; run: JudgeHeatRun; artifact_sha256: string; artifact_bytes: number }[];
  /** Each field entry left out of the heat, and why: it wrote no artifact, or one the judge cannot read. */
  left: { row: CodeHeatFieldRow; run: JudgeHeatRun; why: string }[];
  /**
   * A screened final's: where its screen inputs came from, the partial an earlier attempt kept (fixed before its first
   * call) or the dev phase's records now, and each entry's verdict when read from the dev records (what the heat logs).
   */
  screen?: { from: 'partial' | 'dev'; entries: JudgeScreenEntryVerdictT[] };
}

/**
 * Where a screened final's screen inputs come from (judgeHeatInputs; the header's `judge heat`): the screen an earlier
 * attempt kept, with the resume key it kept it under (null: none kept), and the judges the final calls on, asked with
 * the heat's seed, which a dev rating is held to.
 */
interface JudgeHeatScreenSource {
  kept: () => Promise<{ key: string; screen: JudgeHeatScreenInputsT } | null>;
  judges: (seed: string) => Promise<readonly Pick<JudgeOfHeatT, 'model' | 'door'>[]>;
}

/** The key a final heat's kept calls resume under (judge-heat.ts judgeHeatResumeKey): its setup, and the phase, the bundle and the prompt. */
function judgeHeatResumeKeyOf(resumeKey: (typeof import('./judge-heat.ts'))['judgeHeatResumeKey'], setup: JudgeHeatSetupT, due: Pick<JudgeHeatDue, 'ph' | 'bundle'>, prompt: string): string {
  return resumeKey(setup, { phase_id: due.ph.id.toLowerCase(), bundle_sha256: canonicalSha256(due.bundle), prompt_sha256: sha256Hex(prompt) });
}

/**
 * The ids one read of a final's field names at once (an IN list: latestDevRunLinks, judgeHeatInputs' grade runs, the
 * heat's entries), so a 50,000-entry final stays under a statement's 65,535 bound parameters.
 */
export const FIELD_READ_CHUNK = 5_000;

/** `ids` in FIELD_READ_CHUNK slices, each read by `read` in turn: one statement a slice, the rows of every slice. */
async function chunkedRead<T>(ids: readonly string[], read: (slice: string[]) => Promise<T[]>): Promise<T[]> {
  const out: T[] = [];
  for (let i = 0; i < ids.length; i += FIELD_READ_CHUNK) out.push(...(await read(ids.slice(i, i + FIELD_READ_CHUNK))));
  return out;
}

/** What a screened final's screen reads of an entry's latest dev grade run (judgeScreenInputsOf): whether it finished, and the record it links. */
export type DevRunLink = Pick<RunRow, 'submissionId' | 'status' | 'judgeHeatSha256'>;

/**
 * Each of `submissionIds`' latest grade run on dev phase `phaseId` (the run server/routes/admin/grading.ts
 * latestGradeRuns picks: the highest attempt, then the newest; the highest id breaks a tie it left open), read as far as
 * the screen uses: its status and the record it links, never its result or any other attempt. One DISTINCT ON a
 * FIELD_READ_CHUNK slice, in run_phase_kind_submission_idx's own order, so a 50,000-entry final reads 50,000 narrow rows
 * in ten statements, never every attempt's whole row.
 */
export async function latestDevRunLinks(db: GradeWorkerDeps['db'], phaseId: string, submissionIds: readonly string[]): Promise<Map<string, DevRunLink>> {
  const ids = [...new Set(submissionIds)];
  const rows = await chunkedRead(ids, (slice) =>
    db
      .selectDistinctOn([run.submissionId], { submissionId: run.submissionId, status: run.status, judgeHeatSha256: run.judgeHeatSha256 })
      .from(run)
      .where(and(eq(run.phaseId, phaseId), eq(run.kind, 'grade'), inArray(run.submissionId, slice)))
      .orderBy(asc(run.submissionId), desc(run.attempt), desc(run.createdAt), desc(run.id)),
  );
  return new Map(rows.map((r) => [r.submissionId, r]));
}

/** A dev phase's contender chain as read (contenderChainOf): its fold, none recorded, or why it does not hold. */
export type ContenderChainRead = { fold: JudgeContenderFoldT } | { none: true } | { broken: string };

/**
 * Dev phase `phaseId`'s sealed contender chain (grader/judge-contender.ts), read from its head
 * (server/grading/contender-select.ts contenderHeadOf) back through each record's `prev` to round 0, every record a
 * blob under its sha256 kept as its canonical JSON (judgeContenderRecordDigest) and of the round it stands at, then
 * each held against the chain before it and folded in (judgeContenderHold), round 0 first. `none` with no head;
 * `broken`, saying why (every sha256 in it masked: the chain is sealed), when a record is missing, corrupt, of another
 * round or does not hold, or the head's row does not read. A database fault is thrown: a retry may mend it.
 */
export async function contenderChainOf(deps: Pick<GradeWorkerDeps, 'db' | 'blobs'>, phaseId: string): Promise<ContenderChainRead> {
  const { contenderHeadOf } = await import('../server/grading/contender-select.ts');
  let head: Awaited<ReturnType<typeof contenderHeadOf>>;
  try {
    head = await contenderHeadOf(deps.db, phaseId);
  } catch (err) {
    if (err instanceof TypeError) return { broken: contenderSealed(err.message) };
    throw err;
  }
  if (head === null) return { none: true };
  const jc = await import('./judge-contender.ts');
  const { JudgeHeatError } = await import('./judge-heat.ts');
  const records: JudgeContenderRecordT[] = [];
  let sha: string | null = head.head_sha256;
  for (let round = head.round; round >= 0; round--) {
    if (sha === null) return { broken: `round ${round + 1}'s record follows no record, and the head is round ${head.round}` };
    let bytes: Uint8Array | null;
    try {
      bytes = await deps.blobs.get(sha, { verify: true });
    } catch (err) {
      return { broken: contenderSealed(`round ${round}'s record is corrupt: ${err instanceof Error ? err.message : String(err)}`) };
    }
    if (bytes === null) return { broken: `round ${round}'s record is missing from the blob store` };
    if (sha256Hex(bytes) !== sha) return { broken: `round ${round}'s record is corrupt: its bytes hash to another sha256` };
    let record: JudgeContenderRecordT;
    try {
      record = jc.parseJudgeContenderRecord(bytes);
    } catch (err) {
      if (err instanceof JudgeHeatError) return { broken: contenderSealed(`round ${round}'s record is refused: ${err.message}`) };
      throw err;
    }
    if (jc.judgeContenderRecordDigest(record).json !== Buffer.from(bytes).toString('utf8')) return { broken: `round ${round}'s record is not kept as its canonical JSON` };
    if (record.round !== round) return { broken: `the record at round ${round} is round ${record.round}'s` };
    records.push(record);
    sha = record.prev;
  }
  if (sha !== null) return { broken: "round 0's record follows another record" };
  let fold: JudgeContenderFoldT | null = null;
  for (const record of records.reverse()) {
    try {
      fold = jc.judgeContenderHold(fold, record);
    } catch (err) {
      if (err instanceof JudgeHeatError || err instanceof RangeError) return { broken: contenderSealed(`round ${record.round}: ${err.message}`) };
      throw err;
    }
  }
  return { fold: fold! };
}

/**
 * A screened final's screen inputs read from its dev phase (the header's `judge heat`; grader/judge-screen-inputs.ts
 * judgeScreenInputs): the bundle's ladder read and held (grader/judge-ladder-tree.ts readJudgeLadder, beside the judge
 * directory judgedTreesOf found), the competition's dev phase (as server/routes/admin/grading.ts
 * provisionalRejudgeTargetOf finds it), each entry's latest dev grade run (latestDevRunLinks: its status and link alone) and, when it finished and
 * links one, the record it links (grader/regrade.ts loadJudgeHeatRecord; one that does not load is no record, said under
 * `say`), each record loaded once. A PermanentJobError when the bundle's ladder does not read: no retry mends it.
 * With the bundle's contender_games above 0, the dev phase's sealed contender chain too (contenderChainOf, held to the
 * bundle's judge, ladder and contender design by judge-screen-inputs.ts judgeScreenContenderOf): its members' contender
 * ratings flag them (judgeScreenInputs' contender rule). A chain that does not hold, or is not this bundle's, is said
 * under `say` and left out (every member then rated on its ladder record alone), never the final's fault; the screen
 * this builds is kept in the heat's partial, so a resumed final never reads the head again.
 */
async function judgeScreenInputsOf(
  deps: Pick<GradeWorkerDeps, 'db' | 'blobs' | 'competitionDir'>,
  due: Pick<JudgeHeatDue, 'comp' | 'harness' | 'judge' | 'bundle'>,
  what: string,
  trees: JudgedTrees,
  entries: readonly { entry: string; submission_id: string; artifact_sha256: string }[],
  anchors: readonly string[],
  judges: readonly Pick<JudgeOfHeatT, 'model' | 'door'>[],
  say: (line: string) => void,
): Promise<JudgeScreenInputsResultT> {
  const { judge } = due;
  const screened = judge.screened;
  if (screened === undefined || judge.ladder === undefined) throw new PermanentJobError(`${what}: a screened final screens on the dev phase's ladder ratings, and the bundle names no ladder`);
  const { readJudgeLadderAsync } = await import('./judge-ladder-tree.ts');
  const read = await readJudgeLadderAsync(judgeLadderDirOf(deps, due.comp.slug, due.harness, judge.ladder, trees), judge, trees.judgeDir);
  if ('refused' in read) throw new PermanentJobError(`${what}: its screen reads the dev ratings on the bundle's ladder, which does not read: ${read.refused}`);
  const [dev] = await deps.db
    .select({ id: phase.id })
    .from(phase)
    .where(and(eq(phase.competitionId, due.comp.id), eq(phase.key, 'dev')));
  const runs = dev === undefined ? new Map<string, DevRunLink>() : await latestDevRunLinks(deps.db, dev.id, entries.map((e) => e.submission_id));
  const { RegradeError, loadJudgeHeatRecord } = await import('./regrade.ts');
  const records = new Map<string, JudgeHeatRecordT | null>();
  const recordOf = async (sha: string): Promise<JudgeHeatRecordT | null> => {
    if (records.has(sha)) return records.get(sha)!;
    let record: JudgeHeatRecordT | null;
    try {
      record = await loadJudgeHeatRecord(deps.blobs, sha);
    } catch (err) {
      if (!(err instanceof RegradeError)) throw err;
      say(`dev record ${sha} does not load (${err.message}): the entries linking it are unrated`);
      record = null;
    }
    records.set(sha, record);
    return record;
  };
  const list: JudgeScreenEntryT[] = [];
  for (const e of entries) {
    const r = runs.get(e.submission_id);
    const sha = r !== undefined && r.status === 'finished' ? r.judgeHeatSha256 : null;
    const record = sha === null ? null : await recordOf(sha);
    list.push({ entry: e.entry, artifact_sha256: e.artifact_sha256, dev: sha === null || record === null ? null : { record_sha256: sha, record } });
  }
  const { judgeContenderDesignOf, judgeScreenContenderOf, judgeScreenInputs } = await import('./judge-screen-inputs.ts');
  // The dev phase's sealed contender rounds (contenderChainOf), held to the bundle's judge, ladder and design: a chain
  // that does not hold is said and left out, every member then rated on its ladder record alone; never the final's fault.
  let contender: JudgeScreenContenderT | undefined;
  if (dev !== undefined && screened.contender_games > 0) {
    const chain = await contenderChainOf(deps, dev.id);
    if ('broken' in chain) say(`its dev contender chain does not hold (${chain.broken}): every member is rated on its ladder record alone`);
    else if ('fold' in chain) {
      const held = judgeScreenContenderOf(chain.fold, { judge, ladder: judgeContenderLadderOf(read), design: judgeContenderDesignOf(screened, due.bundle.prizes) });
      if ('refused' in held) say(`its dev contender chain is not this final's (${contenderSealed(held.refused)}): every member is rated on its ladder record alone`);
      else contender = held;
    }
  }
  try {
    const out = judgeScreenInputs({
      entries: list,
      anchors,
      judge: { judge_sha256: judge.judge_sha256, media: judge.media, artifact: judge.artifact, screened: { z: screened.z, contender_games: screened.contender_games } },
      ladder: { ladder_sha256: read.ladder_sha256, calibration_sha256: read.calibration_sha256, rounds: judge.ladder.rounds, games: judge.ladder.games, strengths: read.strengths },
      judges,
      ...(contender === undefined ? {} : { contender }),
    });
    if (out.contender !== undefined) {
      say(
        out.contender.members > 0
          ? `its dev contender chain (${contender!.rounds} rounds) rates ${out.contender.members} of its members`
          : `its dev contender chain (${contender!.rounds} rounds) rates none of its members: ${out.contender.off ?? ''}`,
      );
    }
    return out;
  } catch (err) {
    if (err instanceof RangeError) throw new PermanentJobError(`${what}: its screen does not set up: ${err.message}`, { cause: err });
    throw err;
  }
}

/**
 * Read a due judge heat's inputs (judgeCodeHeat): the judge directory the bundle seals (judgedTreesOf, readJudgeTree),
 * its prompt and its anchors, and each field entry's artifact, the output file judge.artifact of its final grade
 * (program.ts readOutputFile). An entry that passed and wrote no artifact, or one the judge cannot read
 * (judgeArtifactRefusal), is left out, and says why: its run is linked to the heat's record with no verdict, so it
 * ranks below every judged entry and holds up nothing. A PermanentJobError when the image holds another judge
 * directory (or a sponsored judged-artifact competition's cannot be materialized: judgedTreesOf), a field run ran under
 * another plan, an entry's outputs do not read, or no entry is left to judge: no retry mends those. `judgesOf` (a block
 * naming no one model, which sets up only on judges): the judges its setup lists, asked with the heat's seed.
 *
 * A screened final's (judge.screened: a v4 setup) screens its entrants on their dev ratings (`screenSource`): the
 * screen its partial kept, when it sets this heat up under the resume key it was kept under (fixed before the heat's
 * first call, so a resumed attempt never reads the dev records as they are now); else each entry's latest dev grade
 * run's ladder record now (judgeScreenInputsOf), held to the judges the final calls on. A bundle whose ladder does not
 * read is a PermanentJobError.
 */
async function judgeHeatInputs(deps: GradeWorkerDeps, due: JudgeHeatDue, what: string, judgesOf?: (seed: string) => Promise<readonly JudgeOfHeatT[]>, screenSource?: JudgeHeatScreenSource): Promise<JudgeHeatInputs> {
  const { db, blobs } = deps;
  const { judge, field, bundle } = due;
  const { JUDGE_HEAT_FORMAT, JUDGE_HEAT_FORMAT_V4, JudgeHeatError, judgeHeatJudgesOf, judgeHeatResumeKey, judgeHeatSeed, judgeHeatSetup } = await import('./judge-heat.ts');
  const phaseSetup = await codeHeatPhaseSetup(deps, due);
  const plan = await programPlanAsync(phaseSetup);
  // Read where the image or the grader's cache holds it, never the setup's compDir: a k8s setup's is its scorer's stage directory.
  const trees = await judgedTreesOf(deps, due.comp.slug, due.harness, judge);
  const dir = await readJudgeTreeAsync(trees.judgeDir, judge);
  if ('refused' in dir) throw new PermanentJobError(`${what}: ${dir.refused}`);
  const { prompt, anchors, artifacts } = dir;
  // Each field run read as far as the heat uses it (JudgeHeatRun), a FIELD_READ_CHUNK of ids a statement.
  const runRows = await chunkedRead(
    field.map((f) => f.run_id),
    (slice) => db.select(JUDGE_HEAT_RUN_COLUMNS).from(run).where(inArray(run.id, slice)),
  );
  const runOf = new Map(runRows.map((r) => [r.id, r]));
  const entries: JudgeHeatInputs['entries'] = [];
  const left: JudgeHeatInputs['left'] = [];
  for (const row of field) {
    const r = runOf.get(row.run_id);
    // A run gone since the field was read: the retry reads the field as it now stands.
    if (r === undefined) throw new Error(`${what}: entry ${row.submission_id}'s grade run ${row.run_id} is gone`);
    if (r.seed !== plan.seed) {
      throw new PermanentJobError(`${what}: entry ${row.submission_id}'s final grade (run ${r.id}) ran under seed ${r.seed}, and the phase's plan is seed ${plan.seed}: regrade the phase, then send the heat again`);
    }
    let art: Awaited<ReturnType<typeof readOutputFile>>;
    try {
      art = await readOutputFile(blobs, row.action_log_sha256, judge.artifact);
    } catch (err) {
      throw new PermanentJobError(`${what}: entry ${row.submission_id}'s outputs (run ${r.id}) do not read: ${err instanceof Error ? err.message : String(err)}`);
    }
    if (art === null) {
      left.push({ row, run: r, why: `it passed its final grade and its outputs hold no ${judge.artifact}, the artifact the judge compares (the scorer's gate is to fail an entry that writes none)` });
      continue;
    }
    const refused = await judgeArtifactRefusal(judge.media, art);
    if (refused !== null) {
      left.push({ row, run: r, why: `the judge cannot read its ${judge.artifact} (${refused}; the scorer's gate is to fail an entry whose artifact the judge cannot read)` });
      continue;
    }
    artifacts.set(art.sha256, art.bytes);
    entries.push({ row, run: r, artifact_sha256: art.sha256, artifact_bytes: art.size });
  }
  if (entries.length === 0 && left.length > 0) {
    throw new PermanentJobError(
      `${what}: no entry of the field has an artifact the judge can read (${left.map((l) => `${l.row.submission_id}: ${l.why}`).join('; ')}), so there is no heat to judge. Mend the gate, regrade the phase, then send the heat again`,
    );
  }
  // The heat's seed, as its setup draws it (a screened final's record is v4, and so is its seed's domain).
  const seed = judgeHeatSeed(plan.seed, judge.screened === undefined ? JUDGE_HEAT_FORMAT : JUDGE_HEAT_FORMAT_V4);
  const judges = judgesOf === undefined ? undefined : await judgesOf(seed);
  const setupOf = (screen?: JudgeHeatScreenInputsT): JudgeHeatSetupT => {
    try {
      return judgeHeatSetup({
        stage: 'final',
        phaseSeed: plan.seed,
        judge,
        prizes: bundle.prizes,
        entries: entries.map((e) => ({ entry: e.row.submission_id.toLowerCase(), artifact_sha256: e.artifact_sha256, artifact_bytes: e.artifact_bytes })),
        anchors,
        ...(judges === undefined ? {} : { judges }),
        ...(screen === undefined ? {} : { screen }),
      });
    } catch (err) {
      if (err instanceof JudgeHeatError) throw new PermanentJobError(`${what}: its field does not set up: ${err.message}`, { cause: err });
      throw err;
    }
  };
  if (judge.screened === undefined) return { setup: setupOf(), prompt, artifacts, entries, left };
  // A screened final (the header's `judge heat`): the screen an earlier attempt kept, fixed before its first call, when
  // it sets this heat up under the key it was kept under (a resumed attempt never reads the dev records again); else
  // the dev phase's ratings now, held to the judges the final calls on.
  const kept = (await screenSource?.kept()) ?? null;
  if (kept !== null) {
    let resumed: JudgeHeatSetupT | null = null;
    try {
      resumed = setupOf(kept.screen);
    } catch (err) {
      // Kept for another field: the screen is read again.
      if (!(err instanceof PermanentJobError)) throw err;
    }
    if (resumed !== null && judgeHeatResumeKeyOf(judgeHeatResumeKey, resumed, due, prompt) === kept.key) return { setup: resumed, prompt, artifacts, entries, left, screen: { from: 'partial', entries: [] } };
  }
  const finalJudges = screenSource === undefined ? judgeHeatJudgesOf({ agent: judge.agent, ...(judges === undefined ? {} : { judges: [...judges] }) }) : await screenSource.judges(seed);
  const read = await judgeScreenInputsOf(
    deps,
    due,
    what,
    trees,
    entries.map((e) => ({ entry: e.row.submission_id.toLowerCase(), submission_id: e.row.submission_id, artifact_sha256: e.artifact_sha256 })),
    anchors.map((a) => a.artifact_sha256),
    finalJudges,
    (line) => (deps.log ?? ((l: string) => console.log(l)))(`[code-heat] ${what}: ${line}`),
  );
  return { setup: setupOf(read.inputs), prompt, artifacts, entries, left, screen: { from: 'dev', entries: read.entries } };
}

/**
 * The calls an earlier attempt kept for this heat (the header's `judge heat`), when they are this heat's (its resume
 * key) and a prefix of its schedule (judge-heat.ts judgeHeatKeptIssue); else none, said under `say`. Whatever the
 * calls, what the heat spent and the keys it minted carry on: the spend goes on the heat's outcome, and an open key is
 * retired before the next is minted.
 *
 * `read` answers the partial as its store keeps it, read back off this thread (judge-heat-tasks.ts
 * judgeHeatKeptReadOffThread: null when none is kept), once an attempt: judgeCodeHeat's judgesOf takes its judges from
 * the same answer. The kept calls are held to the heat off this thread too (judgeHeatKeptCheckOffThread), and parsed
 * back here only when they resume it, each with the canonical JSON it was kept as (`texts`, for the partial writer's
 * memo). A pool that is saturated or failing rejects (an OffThreadError): the attempt ends and its job retries.
 */
async function keptJudgeHeat(
  store: Pick<JudgeHeatPartialStore, 'where'>,
  read: () => Promise<JudgeKeptRead | null>,
  key: string,
  setup: JudgeHeatSetupT,
  say: (line: string) => void,
  signal?: AbortSignal,
): Promise<{ partial: JudgeHeatPartialT; own: boolean; texts: string[] }> {
  const [{ JUDGE_HEAT_PARTIAL_FORMAT }, { judgeHeatKeptCalls, judgeHeatKeptCheckOffThread }] = await Promise.all([import('./judge-heat.ts'), import('./judge-heat-tasks.ts')]);
  const fresh: JudgeHeatPartialT = { format: JUDGE_HEAT_PARTIAL_FORMAT, key, calls: [], spent_micro_usd: '0', resent: 0, keys: 0, open_key: null };
  const kept = await read();
  if (kept === null) return { partial: fresh, own: false, texts: [] };
  if ('unread' in kept) {
    say(`the judge calls kept at ${store.where} do not read (${kept.unread}): the heat is judged from its first call`);
    return { partial: fresh, own: false, texts: [] };
  }
  const head = kept.head;
  // `own`: the partial is this heat's (its resume key). Its calls are held to the setup on the partial's own `judges`.
  const own = head.key === key;
  const { judges: _judges, ...bare } = setup;
  const theirs: JudgeHeatSetupT = head.judges === undefined ? bare : { ...bare, judges: head.judges };
  const check = own ? await judgeHeatKeptCheckOffThread({ setup: theirs, calls: kept.calls, spares: head.spares ?? [] }, signal) : null;
  const issue = check === null ? 'they are another heat\'s (its field, its bundle or its prompt has changed since)' : check.issue;
  if (issue !== null) {
    say(`the ${kept.ends.length} judge calls kept at ${store.where} are dropped: ${issue}; the heat is judged from its first call`);
    // Another heat's judges go with its calls; this heat's stay fixed, unless it does not set up on them.
    const { judges, ...rest } = head;
    const keep = check !== null && judges !== undefined && check.setsUp;
    return { partial: judgeHeatPartialSpares({ ...rest, ...(keep ? { judges } : {}), key, calls: [], resent: 0 }, []), own, texts: [] };
  }
  // The calls back in their place among the partial's keys, as JudgeHeatPartial parsed them.
  const { calls, texts } = await judgeHeatKeptCalls(kept);
  return { partial: { ...head, calls }, own, texts };
}

/**
 * The most judge sends in flight at once in one heat (the header's `judge heat`): a heat's width
 * (JudgeWorkerDeps.concurrency), inside the wider budget every live heat shares (JUDGE_POOL_BUDGET). A judge call on
 * superbot/high takes ~10-50 s, so a final heat of a few hundred calls sent one at a time would run for hours, past its
 * grade job's expiry. Only the calls already planned can go out together: Swiss rounds are sequential (a 14-member
 * field's round is 14 calls) and the playoff's calls are all known at once (an 11-finalist playoff's 110). At 64 a round
 * goes out in one wave and that playoff in two, so a final heat takes a few minutes: at 8, ai-joke-01's final heat (194
 * calls, p50 8.5 s, p95 26 s) took 6 min 17 s. Wider buys nothing: a ramp on live masq on 2026-11-11 (02:13-02:18Z;
 * superbot at high, max_tokens 12100, 30 ordered pairs of makefun-tagline-01's house texts, W requests held in flight
 * 90 s a stage, no judged heat live) had the pool answer all 708 requests at 64 in flight (p50 5.7 s, p90 19.4, p95
 * 25.3, max 59.8; 101.7 tokens/s a call p50) and all 806 at 96 (p50 7.3 s, p90 25.0, p95 34.6, max 104.5; 81.0
 * tokens/s, 79.6% of the speed at 64), none shed: 96 bought 14% more requests only by slowing every call 20%, so 128
 * was never run and 64 is a heat's most. The model pool is one, though, and two finals closing together would put 128
 * in flight before any backup: so the platform's budget is JUDGE_POOL_BUDGET (96), not 64 a heat. Every live heat (a
 * final's, a dev grade's provisional one) holds a seat in the judge pool (openJudgePoolSeat, a file under the blob
 * store every grader process reads) and takes its share of the 96 (judgePoolShares: max-min fair over what each could
 * use right now, backups counted; a dead grader's seat stops counting JUDGE_POOL_STALE_MS on), and never more than its
 * width: a heat alone still tops at 64 in flight, backups counted, the sender capping both its want and its sends at
 * min(its width in force, its share). A pool that pushes back (a rate-limited re-send, grader/judge-call.ts
 * JudgeHeat.pushbacks) narrows a heat below its share for a while (JUDGE_PUSHBACK_FLOOR and the rest).
 */
export const JUDGE_HEAT_CONCURRENCY = 64;

/**
 * The judge pool's budget (the header's `judge heat`; JudgeWorkerDeps.pool): the judge sends in flight across every live
 * heat on the platform, primaries and backups alike, in every grader process together. Its own number, wider than a
 * heat's width: measured on the live pool 2026-11-11 with no heat live, 64 in flight ran clean (p50 5.7 s, 101.7
 * tokens/s a call); 96 shed nothing and ran each call at 79.6% of that (81.0 tokens/s), about a fifth more work in
 * total; 128 was not measured. Two heats at once get 48 each, and a heat whose round is in its tail gives the rest to
 * the other (judgePoolShares); a heat alone still holds at most its width, JUDGE_HEAT_CONCURRENCY. While a final's heat
 * is live it takes its share first and the practice heats split the rest, at least JUDGE_POOL_PRACTICE_FLOOR each; a
 * heat that joins takes no more than its share less what the others hold past theirs (judgePoolAllowance).
 */
export const JUDGE_POOL_BUDGET = 96;
/** The least share of the pool a seat takes, its want permitting, however many heats are live (judgePoolShares): none starves. */
export const JUDGE_POOL_FLOOR = 4;
/**
 * The least share a practice heat's seat takes while a final's is live (judgePoolShares: final first), its want
 * permitting: 1, not JUDGE_POOL_FLOOR, so 25 practice heats beside a final at 64 put at most 96 + 25 in flight, not 164.
 */
export const JUDGE_POOL_PRACTICE_FLOOR = 1;
/** How often a seat's file is rewritten when its want moved, and the directory read, at most, ms (openJudgePoolSeat); a heat holding a seat turns at least this often. */
export const JUDGE_POOL_REFRESH_MS = 1_000;
/** How often a seat's file is rewritten at least, its want unchanged, ms (openJudgePoolSeat): its heartbeat. */
export const JUDGE_POOL_BEAT_MS = 10_000;
/** How old a seat's file may be and still count, ms (openJudgePoolSeat): past it, its grader died and its share goes back. */
export const JUDGE_POOL_STALE_MS = 30_000;

/**
 * A heat masq's pool pushes back on (a rate-limited request re-sent: grader/judge-call.ts JudgeHeat.pushbacks; on
 * superbot-router each wait the router names, waited out and sent again; the header's `judge heat`): each sender turn that sees the count risen halves the width in force, never under this (nor
 * under a narrower `concurrency`, which it never raises), sends no backup for JUDGE_PUSHBACK_HOLD_MS, and each
 * JUDGE_PUSHBACK_QUIET_MS with no new pushback gives JUDGE_PUSHBACK_STEP back, up to the `concurrency` it started from.
 * Calls in flight are never cancelled for it.
 */
export const JUDGE_PUSHBACK_FLOOR = 16;
/** How long after a pushback no backup is sent, ms (JUDGE_PUSHBACK_FLOOR). */
export const JUDGE_PUSHBACK_HOLD_MS = 30_000;
/** The quiet a heat's width waits for before it widens again after a pushback, ms (JUDGE_PUSHBACK_FLOOR). */
export const JUDGE_PUSHBACK_QUIET_MS = 15_000;
/** The calls each quiet JUDGE_PUSHBACK_QUIET_MS gives back to a width a pushback narrowed (JUDGE_PUSHBACK_FLOOR). */
export const JUDGE_PUSHBACK_STEP = 8;

/** What one call of a heat came to: its answer, or what JudgeHeat.call threw. */
export type JudgeSentT = { ok: true; answer: JudgeCallResult } | { ok: false; err: unknown };

/** What a heat makes of a call that settled, taken in planned order: kept (pushed onto its calls), sent again, or the heat stopped. */
export type JudgeTakenT = 'kept' | 'again' | 'stop';

/** The clock a heat's sends are aged and stamped by (epoch ms), and the sleep its backup wake waits on (rejecting once `signal` aborts). */
export interface JudgeHeatClock {
  now(): number;
  sleep(ms: number, signal?: AbortSignal): Promise<void>;
}

/** The models seen answering a forced form (JudgeHeatCallsRun.formsSeen): a heat on one of them sends its first call with the rest. */
export interface JudgeFormsSeen {
  has(model: string): boolean;
  note(model: string): void;
}

/**
 * A heat's progress as its calls settle (JudgeHeatCallsRun.progress): the calls taken (kept), the answers settled past
 * them in planned order (each with its planned index and call; a fault ahead is not listed), the calls with a send in
 * flight, and the batch (the calls one planning added: a Swiss round, the playoff, an adaptive round) last planned.
 */
export type JudgeHeatProgressT = {
  taken: number;
  ahead: { index: number; planned: JudgePlannedCallT; answer: JudgeCallResult }[];
  flying: number;
  batch: { start: number; size: number };
};

/**
 * What sendJudgeHeatCalls reads of a setup itself: its judge (`agent`, and a pool heat's `judges`) and its `format`
 * (whether a kept call carries a margin: none on v1). Everything else of it is its planner's (`schedule`): a judge
 * heat's setup, or a contender round's (grader/judge-contender.ts JudgeContenderSetup), which brings its own planner.
 */
export type JudgeHeatSendSetupT = Pick<JudgeHeatSetupT, 'agent' | 'judges'> & { format: string };

/**
 * A heat's calls to send concurrently and take in order (sendJudgeHeatCalls). `S` the setup its planner reads: a judge
 * heat's (the default planner and call count read it), or any other with its own `schedule` and `callsTotal`.
 */
export interface JudgeHeatCallsRun<S extends JudgeHeatSendSetupT = JudgeHeatSetupT> {
  /**
   * The heat's calls and, where it keeps them, its ledger and its pushback count (an opened heat keeps both): with
   * `requestsLeft` absent (a hand-made heat) no backup is held back for the ledger; with `pushbacks` absent the pool
   * never pushes back (JUDGE_PUSHBACK_FLOOR).
   */
  heat: Pick<JudgeHeat, 'call' | 'forms' | 'requestsLeft' | 'pushbacks'>;
  setup: S;
  /** The calls kept so far, in the heat's order: `take` pushes each call it keeps onto it. */
  calls: JudgeHeatCallT[];
  /** The most calls in flight at once (1 or more; anything else sends one at a time); a pushback narrows it for a while. */
  concurrency: number;
  /** Aborts the calls in flight: the heat's own (openJudgeHeat's), which each backed-up send's signal joins. */
  signal?: AbortSignal;
  /**
   * Each call as it settles, strictly in planned order (its place is calls.length): 'kept' once pushed onto the calls,
   * 'again' to send it again, 'stop' to stop the heat. `spares` are the call's other sends (grader/judge-heat.ts
   * JudgeHeatSpare, its `call` the planned index), every one ended by then; none for a call that faulted. What it throws
   * stops the heat and propagates.
   */
  take: (planned: JudgePlannedCallT, sent: JudgeSentT, spares: readonly JudgeHeatSpareT[]) => Promise<JudgeTakenT>;
  /**
   * Whether the calls settled but not yet taken (each behind a call still in flight) already fail the heat, whatever the
   * calls before them come to: no more planned calls are sent (a resend `take` asks for still is), and no backup.
   */
  doomed: (ahead: readonly JudgeSentT[]) => boolean;
  /** The backup rule (grader/judge-backup.ts); absent or null: each call is sent once. */
  backup?: JudgeBackupRule | null;
  /** The clock (default Date.now and node:timers/promises). */
  clock?: JudgeHeatClock;
  /**
   * The heat's planned calls, kept ones included (default judgeHeatPlannedCalls(setup): a screened final's an upper bound,
   * its race's calls decided by its results): what the ledger holds back for.
   */
  callsTotal?: number;
  /** The requests held back for the heat's one fault re-send: JUDGE_CALL_ATTEMPTS while it is unspent, else 0 (default 0). */
  reserveRequests?: () => number;
  /** After each settle and each take: the heat's progress (JudgeHeatProgressT). What it throws is swallowed. */
  progress?: (p: JudgeHeatProgressT) => void;
  /** The models seen answering a forced form: noted as a call's first request in one answers HTTP 200. */
  formsSeen?: JudgeFormsSeen;
  /** Where a backup's odd throw, a spare that does not hold or a rule that throws is said (default console.log). */
  log?: (line: string) => void;
  /**
   * The heat's seat in the platform's one budget of judge sends in flight (openJudgePoolSeat; the header's `judge
   * heat`): told each turn what the heat could use and (with `flying`) what it holds in flight, its share caps the sends
   * in flight, backups counted. Absent: the width alone bounds the heat, as before the pool.
   */
  seat?: Pick<JudgePoolSeat, 'share' | 'want' | 'tick'> & Partial<Pick<JudgePoolSeat, 'flying'>>;
  /**
   * Reporting only (a final heat's live document: judgeCodeHeat's JudgeLiveFeed.flying): the calls in flight (sent, not
   * yet settled), in planned order, each with when it last went out (`now`), told after each batch sent, each call
   * settled and each call sent again, whenever the list moved; [] once the last one settles. It changes nothing the heat
   * does, and must not throw: what it throws is dropped.
   */
  flying?: (out: { planned: JudgePlannedCallT; at: Date }[]) => void;
  /** The clock `flying` stamps a call sent with (default the wall clock, as `clock` reads it). */
  now?: () => Date;
  /**
   * The planner (default: a screened final's grader/judge-heat.ts judgeHeatSchedule on a memo of this run's, its Swiss
   * rounds, racing epochs and playoff each one batch, planned once, in this thread; any other heat's
   * grader/judge-heat-tasks.ts judgeHeatScheduleFor, judgeHeatSchedule off this thread past a small heat's size): run
   * once at the start, then once a batch, as its last call is kept (tests/unit/judge-heat-replan.test.ts counts its
   * runs), and awaited. It must answer as judgeHeatSchedule does.
   */
  schedule?(setup: S, settled: readonly JudgeSettledCallT[]): JudgeHeatScheduleT | Promise<JudgeHeatScheduleT>;
}

/** Forms that ask the forced verdict tool: a model that always thinks refuses them, and the heat learns so from a call. */
const forcedForms = (forms: JudgeForms): boolean => forms.some((f) => f === 'answer' || f === 'tool');

/** The backup wake's bounds, ms: never sooner (a send coming due now waits this long at most), never later. */
const JUDGE_BACKUP_WAKE_MIN_MS = 50;
const JUDGE_BACKUP_WAKE_MAX_MS = 1_000;

/**
 * What a cancelled send's spare says (its `invalid`), and the reason its send is aborted with: it was cancelled, nothing
 * failed, and send `decided` of its call (numbered as the record's `send`, from 0) decided it; null: another send did.
 * It names no call number: the spare's own `call` (from 0) does.
 */
export function judgeSendCancelledText(send: number, decided: number | null): string {
  if (decided === null || decided === send) return 'cancelled: another send of this call decided it first';
  return `cancelled: send ${decided} of this call (${decided < send ? 'an earlier' : 'a later'} send) decided it first`;
}

/**
 * Send a heat's calls still to come (sendJudgeHeat; the provisional heat): the calls grader/judge-heat.ts
 * judgeHeatSchedule has already planned past the kept ones (a Swiss round's, the playoff's, a provisional heat's anchors)
 * go out in planned order, up to `concurrency` at once, and each is handed to `take` strictly in planned order, a call that
 * settles early held until every call before it is taken: the calls kept are a serial run's, byte for byte. Each call kept
 * is checked against its planned place (as judgeHeatNextCall does), and the schedule is planned again (every call kept
 * checked against it) once a batch's last call is kept: before then it would plan the same calls, each planning a fit of
 * every round so far (O(n^2) a fit), which a call-by-call planning paid on every call of a large field. While the heat's forms are
 * forced, no call of this run has been taken and `formsSeen` has not seen its model answer one, one call goes alone: a
 * forced form masq refuses its model (grader/judge-call.ts `no force`) moves the heat's later calls to the unforced forms,
 * as a serial run's second call would be.
 *
 * With a `backup` rule (grader/judge-backup.ts), a call still out may get a backup, a second (or third) send of the same
 * request: after each settle and on a wake (the soonest a send could come due, 50 ms to 1 s on), every call with no
 * verdict yet is weighed by judgeBackupDue over its batch's counts and its newest send's age, and backed up when due, the
 * heat's forms are known, the run is not aborted or doomed, the heat's ledger keeps room for every call still to send and
 * the fault re-send (heat.requestsLeft() >= 2 + 2 x (callsTotal - calls sent, kept ones included) + reserveRequests()),
 * and fewer than width + ceil(width / 4) sends fly (primaries go out only below the width). Each send has its own
 * AbortController, joined to the heat's signal. judgeCallOutcome decides: the first send to answer with a verdict; the
 * call's other sends are then aborted and awaited, and only then is the call settled (for `take`, `doomed` and
 * `progress`), its spares final and its requests back. A send that faults while another flies waits for it: a call faults
 * only when every send faulted (`take` gets the first send's error, and its faulted sends are no spares), and is invalid
 * only when every send is done and none gave a verdict. A backup's throw that is no JudgeCallFault is logged and ends
 * that send faulted; the rule's own throw is logged once and read as no backup. Without a rule each call is sent once,
 * as before backups.
 *
 * The pool's pushback, at every width: each turn (a settle, a take, a wake) reads the heat's count of rate-limited
 * re-sends (grader/judge-call.ts JudgeHeat.pushbacks); risen, the width in force halves, never under
 * min(JUDGE_PUSHBACK_FLOOR, concurrency), the line is logged when it narrows, and no backup goes out for
 * JUDGE_PUSHBACK_HOLD_MS (a call due meanwhile waits for the hold's end); each JUDGE_PUSHBACK_QUIET_MS with no new one
 * gives JUDGE_PUSHBACK_STEP back up to `concurrency`, taken at the next turn (no timer of its own). A call in flight is
 * never cancelled for it, and the re-sends stay what they are (no attempt, no request of the ledger): it only ever
 * lowers what goes out. With no pushback the sends are as before.
 *
 * With a `seat` (the platform's one budget of judge sends, the header's `judge heat`): each turn tells it the heat's
 * want and ticks it (a throw of it logged once, its share then the width), the want being the sends the heat could
 * have in flight now: with U its planned calls in hand not yet settled (sent or not; one settled ahead of the kept
 * prefix is settled), min(width in force, U + min(U x (maxSends - 1), the backups the rule's budget still allows)) (U
 * with no rule, 1 while the first call goes alone, 0 at the end), so a round's tail keeps room for its backups and the
 * rest of the budget goes to the other heats. The sends in flight, primaries and backups together, then never pass
 * max(1, min(width in force, the seat's share)) as a send starts (no quarter of room past the width for backups), a
 * backup due taking a free place before a new primary (the backup pass runs first) and a call sent again waiting for a
 * place like a primary; a share that falls below what flies cancels nothing, and the turns come at least every
 * JUDGE_POOL_REFRESH_MS (a timer cancelled as the backup wake's is), so the seat's beat goes on through one long call
 * and a share that rises is filled. A seat that keeps a count (openJudgePoolSeat's `flying`) is told the sends in
 * flight each turn, before its tick and again after the turn's sends, and 0 at the end: the other seats read it to hold
 * a heat that joins (or whose want rises) under the budget until this one's sends past its share complete
 * (judgePoolAllowance). Without a seat the sends are as before the pool.
 *
 * `flying`, when given, is told the calls in flight as they move (reporting only: nothing above depends on it).
 * They are the calls with a send out and no outcome yet, in planned order, each with when its newest send went out
 * (`now`, else the clock), told whenever that list moved: after the sends a turn makes, a call settled or one sent
 * again, and [] once the last settles; what it throws is dropped.
 *
 * True when every planned call is kept; false when `take` stopped the heat. Before it returns or throws (a `take` that
 * throws, an abort, or a JudgeHeatError when the calls kept are not the heat's), every send in flight has settled, its
 * spend on the heat's meter, and no timer is left armed.
 *
 * A setup that is no judge heat's (a contender round's: JudgeHeatSendSetupT) comes with its own `schedule` and
 * `callsTotal`, the only readers of the rest of it; the run is otherwise the same, call for call.
 */
export async function sendJudgeHeatCalls(o: JudgeHeatCallsRun): Promise<boolean>;
export async function sendJudgeHeatCalls<S extends JudgeHeatSendSetupT>(o: JudgeHeatCallsRun<S> & Required<Pick<JudgeHeatCallsRun<S>, 'schedule' | 'callsTotal'>>): Promise<boolean>;
export async function sendJudgeHeatCalls(o: JudgeHeatCallsRun<JudgeHeatSendSetupT>): Promise<boolean> {
  const jh = await import('./judge-heat.ts');
  const { JudgeCallFault, JUDGE_MARGIN_MAX, JUDGE_MARGIN_MIN } = await import('./judge-call.ts');
  const { judgeBackupDue, judgeBackupThresholdMs, judgeCallOutcome } = await import('./judge-backup.ts');
  const { calls, signal } = o;
  // The width the run starts from, and the pushback's narrowed width (JUDGE_PUSHBACK_FLOOR; `follow` lowers and restores it).
  const ceiling = Number.isSafeInteger(o.concurrency) && o.concurrency > 1 ? o.concurrency : 1;
  let width = ceiling;
  // The width in force: the one place the primary fill and the backup room read it.
  const widthNow = (): number => width;
  const rule = o.backup ?? null;
  const log = o.log ?? ((line: string) => console.log(line));
  let clock: JudgeHeatClock;
  if (o.clock !== undefined) clock = o.clock;
  else {
    const timers = await import('node:timers/promises');
    clock = { now: () => Date.now(), sleep: (ms, sig) => timers.setTimeout(ms, undefined, sig === undefined ? undefined : { signal: sig }) };
  }
  const named = namedJudgeAgent(o.setup.agent);
  if (named === null && o.setup.judges === undefined) throw new jh.JudgeHeatError(JUDGE_NAMES_NO_MODEL);
  // The model the forms memo is read and noted under: none on a heat that lists its judges (a pool heat notes each judge's).
  const model = o.setup.judges === undefined ? named!.model : null;
  // With no `callsTotal` (nor `schedule`) the setup is a judge heat's (the overloads).
  const callsTotal = o.callsTotal ?? jh.judgeHeatPlannedCalls(o.setup as JudgeHeatSetupT);
  const maxSends = rule === null ? 1 : Math.max(1, Math.min(rule.maxSends, jh.JUDGE_HEAT_MAX_SENDS));
  // The heat's seat in the judge pool, and its share as this turn read it.
  const seat = o.seat ?? null;
  let share = Number.POSITIVE_INFINITY;
  // A backup takes room a primary would not: primaries fill the width in force, backups up to a quarter more. With a
  // seat, every send in flight counts against min(width, share), and never fewer than one may fly.
  const sendCap = (): number => (seat === null ? widthNow() + Math.ceil(widthNow() / 4) : Math.max(1, Math.min(widthNow(), share)));
  // The default planner: a screened final keeps its steps (each Swiss round's pairing, racing epoch and the playoff)
  // between its plans (judge-heat.ts judgeHeatScheduleMemo), so a plan a batch computes only the step the batch's last
  // call settled, in this thread; any other format refits every Swiss round so far (0.1-0.2 s of CPU at 2,500 members),
  // planned off this thread past a small heat's size (judge-heat-tasks.ts judgeHeatScheduleFor).
  const memo = jh.judgeHeatScheduleMemo();
  const offThread = o.schedule === undefined && o.setup.format !== jh.JUDGE_HEAT_FORMAT_V4 ? (await import('./judge-heat-tasks.ts')).judgeHeatScheduleFor : null;
  const schedule =
    o.schedule ??
    ((setup: JudgeHeatSendSetupT, settled: readonly JudgeSettledCallT[]): JudgeHeatScheduleT | Promise<JudgeHeatScheduleT> =>
      offThread !== null ? offThread(setup as JudgeHeatSetupT, settled) : jh.judgeHeatSchedule(setup as JudgeHeatSetupT, settled, memo));
  const plan = async (): Promise<JudgePlannedCallT[]> => {
    const s = await schedule(o.setup, calls);
    if (s.issue !== null) throw new jh.JudgeHeatError(`the calls made are not the heat's: ${s.issue}`);
    return s.planned;
  };
  // Whether kept call i is surely the one planned at its place, as judgeHeatSchedule checks it: the same stage, round,
  // pair and slot order, and a margin as the setup's format records one (its callFormatIssue). False on any doubt: the
  // heat is then planned again, which throws the schedule's own issue when there is one.
  const keptAsPlanned = (i: number): boolean => {
    const c = calls[i];
    const p = planned[i];
    if (c === undefined || p === undefined) return false;
    if (c.stage !== p.stage || c.round !== p.round || c.a !== p.a || c.b !== p.b || c.slot_order !== p.slot_order) return false;
    const m: unknown = c.margin;
    if (o.setup.format === jh.JUDGE_HEAT_FORMAT_V1) return m === undefined;
    if (c.verdict === null) return m === null;
    return typeof m === 'number' && Number.isSafeInteger(m) && m >= JUDGE_MARGIN_MIN && m <= JUDGE_MARGIN_MAX;
  };
  let planned = await plan();
  // The batches: the run of planned calls each planning added (a resumed attempt's first, the calls it has still to settle).
  const batches: { start: number; size: number }[] = [{ start: calls.length, size: Math.max(0, planned.length - calls.length) }];
  const batchOf = (i: number): { start: number; size: number } => {
    for (let k = batches.length - 1; k >= 0; k--) if (batches[k]!.start <= i) return batches[k]!;
    return batches[0]!;
  };

  // One send of a call: its own abort, when it went out, and how it ended (null while it flies).
  interface Send {
    n: number;
    ctl: AbortController;
    sentAt: number;
    /** When it went out, as `flying` tells it (`now`, else the clock). */
    wentAt: Date;
    /** Aborted by this run because another send decided its call: never a fault of the call. */
    cancelled: boolean;
    end: { ok: true; answer: JudgeCallResult; at: number } | { ok: false; err: unknown; at: number } | null;
    done: Promise<void>;
  }
  // A call with a send out: its sends in send order, and the deciding send once one answered with a verdict.
  interface OpenCall {
    sends: Send[];
    decided: number | null;
  }
  // The next planned call not yet sent; the calls sent and not yet settled, and those settled but not yet taken, by their place.
  let next = calls.length;
  const open = new Map<number, OpenCall>();
  const settled = new Map<number, { sent: JudgeSentT; spares: JudgeHeatSpareT[] }>();
  const live = new Set<Send>();
  const ended = new Set<number>();
  let taken = 0;
  // This attempt's counters (the rule's budget and threshold).
  let primariesSent = 0;
  let backupsSent = 0;
  const answeredMs: number[] = [];
  const aborted = (): boolean => signal?.aborted === true;
  const ahead = (): JudgeSentT[] => [...settled.values()].map((s) => s.sent);
  const alone = (): boolean => taken === 0 && forcedForms(o.heat.forms()) && (model === null || o.formsSeen?.has(model) !== true);
  const said = new Set<string>();
  const sayOnce = (kind: string, line: string): void => {
    if (said.has(kind)) return;
    said.add(kind);
    log(line);
  };
  const messageOf = (err: unknown): string => (err instanceof Error ? err.message : String(err));

  // The pool's pushback (JUDGE_PUSHBACK_FLOOR): the heat's count as last read, when backups may go out again, and since
  // when the narrowed width has been quiet. A count that does not read is no pushback.
  const floor = Math.min(JUDGE_PUSHBACK_FLOOR, ceiling);
  const pushbacksNow = (fallback: number): number => {
    try {
      const n = o.heat.pushbacks?.() ?? fallback;
      return Number.isFinite(n) ? n : fallback;
    } catch (err) {
      sayOnce('pushbacks', `judge heat: the heat's pushback count threw (${messageOf(err)}): read as none`);
      return fallback;
    }
  };
  let pushbacks = pushbacksNow(0);
  let backupsFrom = -Infinity;
  let quietFrom = 0;
  // Each turn: a count risen halves the width in force and holds backups; a width narrowed widens a step a quiet spell.
  const follow = (): void => {
    const seen = pushbacksNow(pushbacks);
    if (seen > pushbacks) {
      pushbacks = seen;
      const now = clock.now();
      backupsFrom = now + JUDGE_PUSHBACK_HOLD_MS;
      quietFrom = now;
      const was = width;
      width = Math.max(floor, Math.floor(width / 2));
      if (width < was) log(`judge heat: the judge's upstream pushed back (${seen} rate-limited re-sends so far): ${width} calls in flight at most, down from ${was}, and no backup for ${JUDGE_PUSHBACK_HOLD_MS / 1_000} s`);
      return;
    }
    if (width >= ceiling) return;
    const steps = Math.floor((clock.now() - quietFrom) / JUDGE_PUSHBACK_QUIET_MS);
    if (steps <= 0) return;
    width = Math.min(ceiling, width + steps * JUDGE_PUSHBACK_STEP);
    quietFrom += steps * JUDGE_PUSHBACK_QUIET_MS;
  };

  // The wall time a send went out at, as `flying` tells it: `now`, else the clock's (a `now` that throws or answers no
  // time is the clock's).
  const wallNow = (at: number): Date => {
    if (o.now !== undefined) {
      try {
        const d = o.now();
        if (d instanceof Date && Number.isFinite(d.getTime())) return d;
      } catch {
        // Reporting only: the clock's time stands in.
      }
    }
    return new Date(at);
  };
  // The sends the heat could have in flight now (the seat's want): its calls in hand not yet settled, and as many
  // backups of them as the rule's budget still allows (the sender's doc comment).
  const wantNow = (): number => {
    const unsettled = Math.max(0, planned.length - calls.length - settled.size);
    if (unsettled === 0) return 0;
    if (alone()) return 1;
    let spare = 0;
    if (rule !== null) {
      const allowed = Math.max(rule.budgetMin, Math.ceil(rule.budgetShare * primariesSent)) - backupsSent;
      spare = Number.isFinite(allowed) ? Math.max(0, allowed) : 0;
    }
    return Math.min(widthNow(), unsettled + Math.min(unsettled * (maxSends - 1), spare));
  };
  // The seat told the sends in flight (for the other seats' bound: judgePoolAllowance), written at its next refresh.
  const seatFlying = (): void => {
    if (seat === null || seat.flying === undefined) return;
    try {
      seat.flying(live.size);
    } catch (err) {
      sayOnce('seat', `judge heat: its seat in the judge pool threw (${messageOf(err)}): its width alone bounds it`);
    }
  };
  // Each turn: the seat told the heat's want and its sends in flight and ticked, and its share read; a seat that throws is the width's.
  const seatTurn = (): void => {
    if (seat === null) return;
    try {
      seat.want(wantNow());
      seat.flying?.(live.size);
      seat.tick();
      const n = seat.share();
      share = typeof n === 'number' && !Number.isNaN(n) ? n : widthNow();
    } catch (err) {
      sayOnce('seat', `judge heat: its seat in the judge pool threw (${messageOf(err)}): its width alone bounds it`);
      share = widthNow();
    }
  };
  // The calls in flight as last told to `flying`: each planned place and when its newest send went out.
  let told: { i: number; at: number }[] = [];
  const tellFlying = (): void => {
    if (o.flying === undefined) return;
    const now: { i: number; at: Date }[] = [];
    for (const [i, c] of [...open].sort(([a], [b]) => a - b)) {
      if (c.decided !== null || !c.sends.some((s) => s.end === null)) continue;
      now.push({ i, at: c.sends[c.sends.length - 1]!.wentAt });
    }
    if (now.length === told.length && now.every((x, k) => x.i === told[k]!.i && x.at.getTime() === told[k]!.at)) return;
    told = now.map((x) => ({ i: x.i, at: x.at.getTime() }));
    try {
      o.flying(now.map((x) => ({ planned: planned[x.i]!, at: new Date(x.at.getTime()) })));
    } catch {
      // Reporting only: what it throws is dropped.
    }
  };

  const sendOne = (i: number, c: OpenCall): void => {
    const p = planned[i]!;
    const [first, second] = p.slot_order === 'ab' ? [p.a, p.b] : [p.b, p.a];
    const ctl = new AbortController();
    // Without a rule nothing is ever cancelled: the heat's own signal, as before backups.
    const opts = rule === null ? (signal === undefined ? {} : { signal }) : { signal: signal === undefined ? ctl.signal : AbortSignal.any([signal, ctl.signal]) };
    const sentAt = clock.now();
    const s: Send = { n: c.sends.length, ctl, sentAt, wentAt: wallNow(sentAt), cancelled: false, end: null, done: Promise.resolve() };
    let call: Promise<JudgeCallResult>;
    try {
      // A heat on a plan's judges sends each game to the judge its schedule dealt (planned `judge`); none, today's call.
      call = o.heat.call(first, second, p.judge === undefined ? opts : { ...opts, judge: p.judge });
    } catch (err) {
      call = Promise.reject(err);
    }
    s.done = call.then(
      (answer) => {
        const at = clock.now();
        s.end = { ok: true, answer, at };
        answeredMs.push(Math.max(0, at - s.sentAt));
        const t = answer.attempts[0];
        if (t !== undefined && (t.form === 'answer' || t.form === 'tool') && t.status === 200) {
          try {
            if (model !== null) o.formsSeen?.note(model);
          } catch (err) {
            sayOnce('forms', `judge heat: the forms memo did not take a note (${messageOf(err)})`);
          }
        }
        live.delete(s);
        ended.add(i);
      },
      (err: unknown) => {
        s.end = { ok: false, err, at: clock.now() };
        if (s.n > 0 && !s.cancelled && !(err instanceof JudgeCallFault)) log(`judge heat: backup ${s.n} of call ${i + 1} threw (${messageOf(err)}): it ends faulted`);
        live.delete(s);
        ended.add(i);
      },
    );
    c.sends.push(s);
    live.add(s);
  };
  const sendPrimary = (i: number): void => {
    const c: OpenCall = { sends: [], decided: null };
    open.set(i, c);
    primariesSent++;
    sendOne(i, c);
  };

  // What a send ended on, as the rule reads it.
  const stateOf = (s: Send): JudgeSendState =>
    s.end === null ? { state: 'flying' } : s.end.ok ? { state: 'answered', verdict: s.end.answer.verdict !== null, atMs: Math.max(0, s.end.at) } : { state: 'faulted' };
  const outcomeOf = (sends: readonly Send[]): JudgeCallOutcome => {
    try {
      return judgeCallOutcome(sends.map(stateOf));
    } catch (err) {
      // The rule cannot fail a heat: the first send's own result, as before backups.
      sayOnce('outcome', `judge heat: the backup rule's outcome threw (${messageOf(err)}): a call is its first send's`);
      const s = stateOf(sends[0]!);
      if (s.state === 'flying') return { kind: 'pending' };
      if (s.state === 'faulted') return { kind: 'fault' };
      return s.verdict ? { kind: 'decided', send: 0 } : { kind: 'invalid', send: 0 };
    }
  };
  // A send that is not its call's decision, as the record keeps it (judge-heat.ts judgeHeatSpareOf); null, said, when it does not hold.
  // `decided` is the send that decided the call, null when none did. A cancelled send's `invalid` says it was cancelled and which
  // send decided (sends numbered as the record's `send`, from 0), never the fault its abort surfaced as (judge-call.ts wraps an
  // aborted fetch as "masq could not be reached": nothing failed).
  const spareOf = (i: number, s: Send, decided: number | null): JudgeHeatSpareT | null => {
    const end = s.end!;
    let how: JudgeSpareEndT;
    let from: JudgeCallResult | { message: string; attempts: readonly JudgeCallResult['attempts'][number][] };
    if (end.ok) {
      how = end.answer.verdict === null ? 'invalid' : 'late';
      from = end.answer;
    } else {
      const message = messageOf(end.err);
      const attempts = end.err instanceof JudgeCallFault ? end.err.attempts : [];
      how = s.cancelled && attempts.length < jh.JUDGE_CALL_MAX_ATTEMPTS && attempts.every((t) => t.invalid !== null) ? 'cancelled' : 'faulted';
      from = { message: how === 'cancelled' ? judgeSendCancelledText(s.n, decided) : message === '' ? 'the send ended with no answer' : message, attempts };
    }
    try {
      return jh.judgeHeatSpareOf(i, s.n, s.sentAt, Math.max(s.sentAt, end.at), how, from);
    } catch (err) {
      log(`judge heat: send ${s.n} of call ${i + 1} is kept as no spare (${messageOf(err)}): the call and its decision stand`);
      return null;
    }
  };
  const finish = (i: number, c: OpenCall, out: Exclude<JudgeCallOutcome, { kind: 'pending' }>): void => {
    open.delete(i);
    if (out.kind === 'fault') {
      const e = c.sends[0]!.end!;
      settled.set(i, { sent: { ok: false, err: e.ok ? new Error('judge heat: a faulted call answered') : e.err }, spares: [] });
      return;
    }
    const e = c.sends[out.send]!.end!;
    const sent: JudgeSentT = e.ok ? { ok: true, answer: e.answer } : { ok: false, err: e.err };
    const spares: JudgeHeatSpareT[] = [];
    for (const s of c.sends) {
      if (s.n === out.send) continue;
      const spare = spareOf(i, s, out.kind === 'decided' ? out.send : null);
      if (spare !== null) spares.push(spare);
    }
    settled.set(i, { sent, spares });
  };
  // The calls whose sends ended since last looked at: decided (its other sends aborted, the call settled once they end),
  // invalid or a fault (settled), or still pending. True when any call settled.
  const settleEnded = (): boolean => {
    let any = false;
    for (const i of [...ended].sort((a, b) => a - b)) {
      ended.delete(i);
      const c = open.get(i);
      if (c === undefined) continue;
      if (c.decided === null) {
        const out = outcomeOf(c.sends);
        if (out.kind === 'pending') continue;
        if (out.kind !== 'decided') {
          finish(i, c, out);
          any = true;
          continue;
        }
        c.decided = out.send;
        for (const s of c.sends) {
          if (s.end !== null) continue;
          s.cancelled = true;
          s.ctl.abort(new Error(`judge heat: ${judgeSendCancelledText(s.n, out.send)}`));
        }
      }
      if (c.sends.some((s) => s.end === null)) continue;
      finish(i, c, { kind: 'decided', send: c.decided });
      any = true;
    }
    return any;
  };
  const report = (): void => {
    if (o.progress === undefined) return;
    try {
      const list: JudgeHeatProgressT['ahead'] = [];
      for (const [index, s] of [...settled].sort(([a], [b]) => a - b)) if (s.sent.ok && planned[index] !== undefined) list.push({ index, planned: planned[index]!, answer: s.sent.answer });
      const flying = [...open.values()].filter((c) => c.sends.some((s) => s.end === null)).length;
      const batch = batches[batches.length - 1]!;
      o.progress({ taken: calls.length, ahead: list, flying, batch: { start: batch.start, size: batch.size } });
    } catch (err) {
      sayOnce('progress', `judge heat: its progress hook threw (${messageOf(err)}): the heat goes on`);
    }
  };
  // Back up every call due (the rule), and say how soon the next could come due: null when none can, or no rule.
  const backUp = (): number | null => {
    if (rule === null || alone() || aborted() || o.doomed(ahead())) return null;
    let thresholdMs: number;
    try {
      thresholdMs = judgeBackupThresholdMs(rule, answeredMs);
    } catch (err) {
      sayOnce('threshold', `judge heat: the backup rule's threshold threw (${messageOf(err)}): no backup now`);
      return null;
    }
    if (backupsSent >= Math.max(rule.budgetMin, Math.ceil(rule.budgetShare * primariesSent))) return null;
    const now = clock.now();
    const counts = new Map<number, { unsettled: number; unsent: number }>();
    const countsOf = (b: { start: number; size: number }): { unsettled: number; unsent: number } => {
      let got = counts.get(b.start);
      if (got === undefined) {
        got = { unsettled: 0, unsent: 0 };
        for (let i = b.start; i < b.start + b.size; i++) {
          if (i >= next) got.unsent++;
          if (i >= calls.length && !settled.has(i)) got.unsettled++;
        }
        counts.set(b.start, got);
      }
      return got;
    };
    let wake: number | null = null;
    for (const [i, c] of [...open].sort(([a], [b]) => a - b)) {
      if (c.decided !== null || c.sends.length >= maxSends || !c.sends.some((s) => s.end === null)) continue;
      const b = batchOf(i);
      const n = countsOf(b);
      const newest = c.sends[c.sends.length - 1]!.sentAt;
      const state = {
        batchSize: b.size,
        batchUnsettled: n.unsettled,
        batchUnsent: n.unsent,
        newestSendAgeMs: Math.max(0, now - newest),
        sends: c.sends.length,
        backupsSent,
        primariesSent,
        thresholdMs,
      };
      let due: boolean;
      try {
        due = judgeBackupDue(rule, state);
      } catch (err) {
        sayOnce('due', `judge heat: the backup rule threw (${messageOf(err)}): no backup now`);
        return null;
      }
      // How old a send of this call must be to come due, as its batch stands now.
      const tail = n.unsent === 0 && n.unsettled <= Math.max(rule.tailMin, Math.ceil(rule.tailShare * b.size));
      const dueAge = tail ? Math.min(thresholdMs, rule.maxAgeMs) : rule.maxAgeMs;
      if (!due) {
        const dueAt = newest + dueAge;
        if (dueAt > now) wake = Math.min(wake ?? Infinity, dueAt - now);
        continue;
      }
      if (live.size >= sendCap()) continue;
      // Held after a pushback: due, and sent once the hold ends should it still be.
      if (now < backupsFrom) {
        wake = Math.min(wake ?? Infinity, backupsFrom - now);
        continue;
      }
      // A heat that keeps no ledger (a hand-made one) is never held back for it.
      if ((o.heat.requestsLeft?.() ?? Number.POSITIVE_INFINITY) < jh.JUDGE_CALL_MAX_ATTEMPTS * (1 + Math.max(0, callsTotal - next)) + (o.reserveRequests?.() ?? 0)) continue;
      backupsSent++;
      sendOne(i, c);
      // Its next send, should it still have no verdict, comes due that much after this one.
      if (c.sends.length < maxSends) wake = Math.min(wake ?? Infinity, dueAge);
      if (backupsSent >= Math.max(rule.budgetMin, Math.ceil(rule.budgetShare * primariesSent))) return null;
    }
    return wake;
  };
  // Wait for a send to end, or, when a backup may come due first, for the wake; the wake's timer cancelled either way.
  const waitForSends = async (wake: number | null): Promise<void> => {
    const sends = [...live].map((s) => s.done);
    if (wake === null) {
      await Promise.race(sends);
      return;
    }
    const nap = new AbortController();
    const slept = clock.sleep(Math.min(JUDGE_BACKUP_WAKE_MAX_MS, Math.max(JUDGE_BACKUP_WAKE_MIN_MS, Math.ceil(wake))), nap.signal).catch(() => undefined);
    try {
      await Promise.race([...sends, slept]);
    } finally {
      nap.abort();
    }
  };

  // With a seat, a call `take` sent again that found no place in flight: it goes out first once one frees.
  let again: number | null = null;
  // The sooner of two wakes (null: none).
  const sooner = (a: number | null, b: number | null): number | null => (a === null ? b : b === null ? a : Math.min(a, b));
  try {
    for (;;) {
      if (settleEnded()) report();
      tellFlying();
      follow();
      seatTurn();
      const head = calls.length;
      const got = settled.get(head);
      if (got === undefined) {
        // The head first, then the calls after it: a call sent again goes out before any call planned after it. The
        // width counts calls in flight (each open call has a send out), so a backup takes room a primary would not;
        // the sends in flight stay under sendCap all the same. Without a rule each call is one send: the two agree.
        const room = alone() ? 1 : widthNow();
        const roomy = (): boolean => open.size < room && live.size < sendCap();
        // With a seat a backup due takes a free place before a new primary does.
        let wake = seat === null ? null : backUp();
        if (again !== null && roomy() && !aborted()) {
          sendPrimary(again);
          again = null;
        }
        if (roomy() && next < planned.length && !aborted() && !o.doomed(ahead())) {
          // A send may abort the attempt (its fetch throws at once): nothing more goes out after it.
          while (roomy() && next < planned.length && !aborted()) sendPrimary(next++);
        }
        wake = sooner(wake, backUp());
        tellFlying();
        // The sends this turn made, told to the seat: its next refresh writes them for the others.
        seatFlying();
        if (live.size > 0) {
          // A seat's beat goes on through a long call, and a share that rose is filled: a turn at least every refresh.
          await waitForSends(seat === null ? wake : sooner(wake, JUDGE_POOL_REFRESH_MS));
          continue;
        }
        if (ended.size > 0) continue;
        if (head >= planned.length) return true;
        // Nothing in flight and the next call not sent: the attempt was given up between calls.
        if (signal !== undefined && aborted()) throw signal.reason instanceof Error ? signal.reason : new Error('the judge heat was aborted');
        throw new Error(`judge heat: call ${head + 1} is neither sent nor settled, and none is in flight`);
      }
      settled.delete(head);
      taken++;
      const took = await o.take(planned[head]!, got.sent, got.spares);
      if (took === 'stop') return false;
      if (took === 'again') {
        // With a seat it waits for a place in flight, as a primary does.
        if (seat !== null && live.size >= sendCap()) again = head;
        else sendPrimary(head);
        report();
        continue;
      }
      if (calls.length !== head + 1) throw new Error(`judge heat: call ${head + 1} was taken as kept, and ${calls.length} calls are kept`);
      // The schedule plans more only once every call it planned is kept (a round's games fit, the playoff drawn): until a
      // batch's last call is kept, planning again answers the same calls, so it waits for that call (each plan refits
      // every round so far), the call kept checked against its planned place meanwhile.
      const before = planned.length;
      if (calls.length >= before || !keptAsPlanned(head)) planned = await plan();
      if (planned.length > before) batches.push({ start: before, size: planned.length - before });
      report();
    }
  } finally {
    // Every call sent settles before the heat goes on to retire its key or keep its partial: none of them is left unmetered.
    while (live.size > 0) await Promise.allSettled([...live].map((s) => s.done));
    // Nothing flies now, and the heat wants nothing more of the pool.
    tellFlying();
    if (seat !== null) {
      try {
        seat.want(0);
        seat.flying?.(0);
      } catch (err) {
        sayOnce('seat', `judge heat: its seat in the judge pool threw (${messageOf(err)}): its width alone bounds it`);
      }
    }
  }
}

/** An opened judge heat's calls to send (sendJudgeHeat). */
export interface JudgeHeatSend {
  /** The heat openJudgeHeat opened, on its own key. */
  heat: JudgeHeat;
  setup: JudgeHeatSetupT;
  judge: Pick<ProgramJudgeT, 'invalid_share_max'>;
  /** The calls kept so far, in the heat's order: each call that settles is pushed onto it. */
  calls: JudgeHeatCallT[];
  /** The heat's partial as it stands, its key saved open on it. */
  partial: JudgeHeatPartialT;
  /**
   * Keep the partial (a resumable heat's store; a local heat's own copy): as calls settle at most once every
   * `saveEvery` (JudgeHeatSaveEvery), and always at the heat's one fault re-send, a stop, an abort or unexpected
   * throw, and its end. Never two at once: each save is awaited before the heat goes on.
   */
  save: (next: JudgeHeatPartialT) => Promise<void>;
  /**
   * How often the partial is kept as calls settle; absent, after every call (a local heat's copy, which a reader
   * watches call by call). A final's heat on the grader passes JUDGE_HEAT_SAVE_EVERY_MS and JUDGE_HEAT_SAVE_EVERY_CALLS
   * (judgeCodeHeat).
   */
  saveEvery?: JudgeHeatSaveEvery;
  say: (line: string) => void;
  /** What a PermanentJobError the heat fails with opens with. */
  what: string;
  /**
   * The queue that runs the heat's job (judgeCodeHeat), `last` when this attempt is the job's last (isLastAttempt). A call
   * superbot-router answered finally (judge-call.ts JudgeCallFault.final), or a router heat's second call the router never
   * saw (after its one re-send), ends the attempt at once, its calls and their
   * spares kept and its key retired: with a queue attempt still to come it throws a plain Error, which the queue retries
   * (server/jobs.ts code-heat: retryDelay 300 s, backoff) from the calls kept; on the last attempt, or with no queue (a
   * local heat), it fails the heat as a PermanentJobError. When the attempt kept a call it did not start with, `handOn`
   * (if given) is asked first to hand the heat on to a fresh job: true, and the attempt ends with no throw and spends
   * none of the queue's attempts, on its last too; false, or a throw (logged), and it ends as above.
   */
  queue?: { last: boolean; handOn?: (cause: Error) => Promise<boolean> };
  /**
   * Once the key is retired, a failed heat's or a whole one's, before the partial is saved: what masq said (null when
   * a failed heat's retirement did not answer) and what the heat metered (judgeCodeHeat closes the key's file with it).
   */
  onRetired?: (retired: RetiredTrialKey | null, meterMicroUsd: bigint) => Promise<void>;
  /** Aborts the calls in flight; its abort is thrown, never sent again. */
  signal?: AbortSignal;
  /** The most calls in flight at once (default JUDGE_HEAT_CONCURRENCY). */
  concurrency?: number;
  /** The backup rule (sendJudgeHeatCalls; grader/judge-backup.ts JUDGE_BACKUP): absent or null, each call is sent once. */
  backup?: JudgeBackupRule | null;
  /** The clock the sends are aged and stamped by (default Date.now and a timer). */
  clock?: JudgeHeatClock;
  /** The models seen answering a forced form (sendJudgeHeatCalls: the first call goes alone only on a model not among them). */
  formsSeen?: JudgeFormsSeen;
  /** The heat's progress after each settle and take (JudgeHeatProgressT); what it throws is swallowed. */
  progress?: (p: JudgeHeatProgressT) => void;
  /** The heat's seat in the judge pool (sendJudgeHeatCalls; openJudgePoolSeat): absent, its width alone bounds it. */
  seat?: Pick<JudgePoolSeat, 'share' | 'want' | 'tick'> & Partial<Pick<JudgePoolSeat, 'flying'>>;
  /**
   * Reporting only (sendJudgeHeatCalls' flying: a final heat's live document): the calls in flight in planned order, each
   * with when it went out; [] once the last settles. What it throws is logged (once per message) and the heat goes on.
   * Told after each batch sent, each call settled and each call sent again, whenever the list moved; it changes nothing
   * the heat does.
   */
  flying?: (out: { planned: JudgePlannedCallT; at: Date }[]) => void;
  /** The clock `flying` stamps a call sent with (default the wall clock). */
  now?: () => Date;
}

/**
 * Whether a heat's judgeHeatPlannedCalls is an upper bound on its calls rather than their count: a screened final's
 * (v4: its race makes as many as its results ask for), and a ladder heat's with money-place scrutiny (its extra rounds
 * played only when its entry reaches the line). Such a heat is done at its schedule's `complete`, never at a count.
 */
export function judgeHeatCallsBounded(setup: Pick<JudgeHeatSetupT, 'format' | 'ladder'>): boolean {
  return setup.format === 'agent-fun/judge-heat/v4' || (setup.ladder !== undefined && 'scrutiny' in setup.ladder && setup.ladder.scrutiny !== undefined);
}

/**
 * The most calls a bounded heat (judgeHeatCallsBounded) can still come to once `kept` are kept, never more than `bound`
 * (judgeHeatPlannedCalls): grader/judge-heat.ts judgeHeatScheduleCeiling over its schedule (`jh`'s judgeHeatSchedule,
 * on `memo`), the arithmetic kept there beside the screened final's schedule it mirrors. It never rises as more calls
 * are kept. `shortlist` is the screened final's F2 members (min(S, field), as judgeHeatPlannedCalls counts them), null
 * on any other heat; read only when needed.
 */
export function judgeHeatCallsCeiling(
  jh: Pick<typeof import('./judge-heat.ts'), 'judgeHeatSchedule'>,
  setup: JudgeHeatSetupT,
  kept: readonly JudgeSettledCallT[],
  memo: ReturnType<(typeof import('./judge-heat.ts'))['judgeHeatScheduleMemo']>,
  bound: number,
  shortlist: () => number | null,
): number {
  return judgeHeatScheduleCeiling(setup, jh.judgeHeatSchedule(setup, kept, memo), bound, shortlist);
}

/**
 * A heat's invalid-share stop (sendJudgeHeat's, the provisional heat's): `over(kept, invalid, made)`, with `made` of
 * the heat's calls settled (those `kept`, and any settled past them) and `invalid` of those with no verdict, is the most
 * calls the heat can come to when that share is over `max` (judge.invalid_share_max) whatever the calls still to come
 * answer, and null while an outcome of them can keep it within. A heat of a fixed count (v1 to v3, a ladder heat with no
 * scrutiny) is judged over judgeHeatPlannedCalls, as it always was. A bounded heat's (judgeHeatCallsBounded) record is
 * held to the calls it makes (judge-heat.ts judgeHeatRecordOf), which its race or its scrutiny may end well short of
 * that bound: its share is judged over the most calls its schedule over the calls kept can still come to
 * (judgeHeatCallsCeiling), the most favourable rest (every call to come valid, and as many as can be planned), so the
 * heat stops as soon as its share is certain, not once every call is spent. That ceiling never rises as calls are kept,
 * so calls settled ahead that already doom the heat stop its `take` once they are kept.
 */
export function judgeHeatInvalidShareStop(
  jh: Pick<typeof import('./judge-heat.ts'), 'judgeHeatPlannedCalls' | 'judgeHeatInvalidShareOver' | 'judgeHeatSchedule' | 'judgeHeatScheduleMemo' | 'judgeHeatScreenOf'>,
  setup: JudgeHeatSetupT,
  max: string,
): (kept: readonly JudgeSettledCallT[], invalid: number, made: number) => number | null {
  const bound = jh.judgeHeatPlannedCalls(setup);
  if (!judgeHeatCallsBounded(setup)) return (_kept, invalid) => (jh.judgeHeatInvalidShareOver(invalid, bound, max) ? bound : null);
  const memo = jh.judgeHeatScheduleMemo();
  // The screened final's shortlist, its F2 members as judgeHeatPlannedCalls counts them (min(S, field)): read once, when first asked.
  let members: number | null | undefined;
  const shortlist = (): number | null => {
    if (members === undefined) {
      const screen = jh.judgeHeatScreenOf(setup);
      members = screen === null ? null : Math.min(screen.shortlist.length, setup.field.length);
    }
    return members;
  };
  // The ceiling over the calls kept, read again only once more are kept.
  let at = -1;
  let ceiling = bound;
  return (kept, invalid, made) => {
    // No call to come can lower the share under its count so far: within it, nothing more to read.
    if (!jh.judgeHeatInvalidShareOver(invalid, made, max)) return null;
    if (jh.judgeHeatInvalidShareOver(invalid, Math.max(bound, made), max)) return Math.max(bound, made);
    if (at !== kept.length) {
      ceiling = judgeHeatCallsCeiling(jh, setup, kept, memo, bound, shortlist);
      at = kept.length;
    }
    const most = Math.max(ceiling, made);
    return jh.judgeHeatInvalidShareOver(invalid, most, max) ? most : null;
  };
}

/**
 * How often sendJudgeHeat keeps a heat's partial as its calls settle: once `ms` have passed since the last save
 * (stretched to JUDGE_HEAT_SAVE_DUTY times the last save's own length, so saving never takes more than about a
 * twentieth of the heat's time), or once `calls` calls were kept since it, whichever comes first.
 */
export interface JudgeHeatSaveEvery {
  ms: number;
  calls: number;
}

/**
 * The longest a settled call waits to be kept on disk, ms (JudgeHeatSaveEvery.ms). Saved once a call, the partial of
 * a final's art heat on 2026-11-13 (6.1 MB at 3,683 calls, canonical JSON 263-318 ms of synchronous CPU, about twice a
 * second) held the grader's event loop past Node's 250 ms connect attempt timer, so every connect from that pod
 * (OpenRouter, superbot-router, Postgres) failed ETIMEDOUT with the network fine. A process killed outright (no abort
 * reaches the heat) loses at most the calls since the last save: the next attempt sends them again from the calls kept.
 */
export const JUDGE_HEAT_SAVE_EVERY_MS = 5_000;
/** The most calls kept between two saves of a heat's partial (JudgeHeatSaveEvery.calls). */
export const JUDGE_HEAT_SAVE_EVERY_CALLS = 200;
/** The least time between two throttled saves, as a multiple of the last save's own length (JudgeHeatSaveEvery). */
export const JUDGE_HEAT_SAVE_DUTY = 20;

/** The least wall time between two of a final judge heat's progress lines, ms (judgeCodeHeat; judgeHeatProgressLine). */
export const JUDGE_HEAT_PROGRESS_MS = 60_000;

/** A final judge heat's stage before its first call, and how long it took (judgeCodeHeat): `prep: <what> in <s> s`. */
export function judgeHeatPrepLine(what: string, ms: number): string {
  return `prep: ${what} in ${(ms / 1000).toFixed(1)} s`;
}

/**
 * A final judge heat's progress line (judgeCodeHeat, at most once a JUDGE_HEAT_PROGRESS_MS): the calls judged of those
 * planned (the kept prefix, `kept` of them from an earlier attempt), the pace over the `ms` since the last line (`since`
 * calls), the calls in flight, and the calls the partial on disk holds (sendJudgeHeat's throttled save).
 */
export function judgeHeatProgressLine(o: { judged: number; planned: number; kept: number; ms: number; since: number; flying: number; saved: number }): string {
  const perMin = o.ms <= 0 ? 0 : (o.since * 60_000) / o.ms;
  return `judging: ${o.judged} of ${o.planned} calls judged (${o.kept} kept from an earlier attempt), ${perMin.toFixed(1)}/min over the last ${Math.round(o.ms / 1000)} s, ${o.flying} in flight, ${o.saved} saved`;
}

/**
 * A heat's partial as canonicalJson writes it, byte for byte, its calls' and spares' texts remembered between saves:
 * the partial grows by appends (each call and spare an object kept as it was settled, never changed), so a save
 * serializes only what came since the last one and joins the rest, where canonicalJson of the whole took 263-318 ms
 * at 3,683 calls. Canonical JSON is compositional (an object is its sorted keys' members, an array its items joined
 * by commas, no whitespace: sim/canonical.ts), so the text is the same; an item it does not hold (a new object) is
 * serialized afresh.
 */
export function judgeHeatPartialWriter(): JudgeHeatPartialWriter {
  const texts = new WeakMap<object, string>();
  const textsOf = (items: readonly object[]): string[] => {
    const out: string[] = [];
    for (const item of items) {
      let text = texts.get(item);
      if (text === undefined) {
        text = canonicalJson(item);
        texts.set(item, text);
      }
      out.push(text);
    }
    return out;
  };
  const itemsOf = (items: readonly object[]): string => `[${textsOf(items).join(',')}]`;
  const write = (partial: JudgeHeatPartialT): string => {
    const record = partial as unknown as Record<string, unknown>;
    const members = Object.keys(record)
      .sort(compareCodeUnits)
      .map((k) => {
        const v = record[k];
        const text = (k === 'calls' || k === 'spares') && Array.isArray(v) && v.every((x) => x !== null && typeof x === 'object' && !Array.isArray(x)) ? itemsOf(v as object[]) : canonicalJson(v);
        return `${JSON.stringify(k)}:${text}`;
      });
    return `{${members.join(',')}}`;
  };
  // Items whose canonical JSON is known already (a kept partial read back: judge-heat-tasks.ts judgeHeatKeptCalls).
  const remember = (items: readonly object[], known: readonly string[]): void => {
    if (items.length !== known.length) throw new RangeError(`${items.length} items and ${known.length} texts to remember`);
    for (let i = 0; i < items.length; i++) texts.set(items[i]!, known[i]!);
  };
  return Object.assign(write, { texts: textsOf, remember });
}

/**
 * A partial writer (judgeHeatPartialWriter): the partial's canonical JSON, and `texts`, each item's canonical JSON as it
 * remembers it (a call's or a spare's), what a heat's end sends its record task (grader/judge-heat-tasks.ts judgeHeatEndText);
 * `remember`, the texts a resumed heat's kept calls came back with (known[i] the canonical JSON of items[i]), so its
 * first save serializes none of them again (canonicalJson of 15,000 kept calls took about 0.3 s of this thread).
 */
export type JudgeHeatPartialWriter = ((partial: JudgeHeatPartialT) => string) & {
  texts: (items: readonly object[]) => string[];
  remember: (items: readonly object[], known: readonly string[]) => void;
};

/** `partial` with `spares` its spares (grader/judge-heat.ts JudgeHeatPartial): the key absent when there are none, never empty. */
function judgeHeatPartialSpares(partial: JudgeHeatPartialT, spares: readonly JudgeHeatSpareT[]): JudgeHeatPartialT {
  const { spares: _dropped, ...rest } = partial;
  return spares.length === 0 ? rest : { ...rest, spares: [...spares] };
}

/**
 * Send an opened heat's calls still to come (judgeCodeHeat; cli/grade-local.ts's local heat), up to `concurrency` at
 * once and kept strictly in planned order as each settles (sendJudgeHeatCalls), then retire its key; the flags its
 * retirement raised are returned. A call that faults is sent once again (on superbot-router, only for a fault the router
 * never saw); a second fault (off superbot-router), a call judgeHeatCallOf refuses,
 * or more calls with no verdict than judge.invalid_share_max allows retires the key, once every call in flight has
 * settled, and fails the heat as a PermanentJobError (grader/judge-heat.ts JudgeHeatError its cause), the calls kept the
 * settled prefix before it. A fault the router answered finally (JudgeCallFault.final) is never sent again: it, or on a
 * router heat a second fault the router never saw (the heat's key ROUTER_KEY_ID_PREFIX's), ends the attempt as soon as the calls in flight settle, its calls kept and its key retired, and the queue tries the job again
 * from them (`queue`), the heat failed only on the queue's last attempt or with no queue; an attempt that kept a call it
 * did not start with is handed on instead (`queue.handOn`), returning its key's flags. An abort, or an error no
 * heat expects, keeps the partial's spend and open key's meter (the calls in flight settled) and propagates, the key left open for the retry to retire. With a `backup` rule a call still
 * out near its batch's end may be sent again (sendJudgeHeatCalls): each kept call's other sends go on the partial's
 * `spares` in the same save as the call, a failed heat that keeps its calls keeps theirs, and a backup never takes the
 * requests the heat's one fault re-send is held to while it is unspent.
 */
export async function sendJudgeHeat(o: JudgeHeatSend): Promise<string[]> {
  const { heat, setup, judge, calls, say, what, signal } = o;
  const jh = await import('./judge-heat.ts');
  const { JudgeCallFault } = await import('./judge-call.ts');
  const { ROUTER_KEY_ID_PREFIX } = await import('../server/superbot-router.ts');
  // A heat on superbot-router (its key the router's): a second fault the router never saw ends the attempt, not the heat.
  const router = heat.key.id.startsWith(ROUTER_KEY_ID_PREFIX);
  let p = o.partial;
  // The partial as it stands is always `p`; it goes to `o.save` only as the throttle lets (JudgeHeatSaveEvery), and
  // whole at every re-send, stop, abort and end. `dirty`: `p` moved since the last save that landed. A process killed
  // outright loses only the calls since that save, and the next attempt sends them again.
  const every = o.saveEvery ?? { ms: 0, calls: 1 };
  const clockNow = (): number => (o.clock === undefined ? Date.now() : o.clock.now());
  let dirty = false;
  let unsaved = 0;
  let savedAt = clockNow();
  let saveMs = 0;
  // The saves in order, never two at once (each is awaited, and a save chains on the one before all the same).
  let saving: Promise<void> = Promise.resolve();
  const flush = async (): Promise<void> => {
    const next = p;
    dirty = false;
    unsaved = 0;
    const run = saving.then(async () => {
      const from = clockNow();
      try {
        await o.save(next);
      } catch (err) {
        dirty = true;
        throw err;
      }
      savedAt = clockNow();
      saveMs = savedAt - from;
    });
    saving = run.catch(() => undefined);
    await run;
  };
  // Every save but a settled call's: at once.
  const save = async (next: JudgeHeatPartialT): Promise<void> => {
    p = next;
    dirty = true;
    await flush();
  };
  // A settled call's: kept in `p`, on disk once the throttle's time or count is up.
  const keepCall = async (next: JudgeHeatPartialT): Promise<void> => {
    p = next;
    dirty = true;
    unsaved++;
    if (unsaved >= every.calls || clockNow() - savedAt >= Math.max(every.ms, JUDGE_HEAT_SAVE_DUTY * saveMs)) await flush();
  };
  // Its calls at most: every call of a v1 or v2 heat, an upper bound on a screened final's (judgeHeatCallsBounded), whose
  // record is held to its invalid share over the calls it made (judge-heat.ts judgeHeatRecordOf): a share over the most
  // calls its schedule can still come to is one no call to come can mend (judgeHeatInvalidShareStop).
  const planned = jh.judgeHeatPlannedCalls(setup);
  const plannedWords = judgeHeatCallsBounded(setup) ? `at most ${planned}` : String(planned);
  const shareStop = judgeHeatInvalidShareStop(jh, setup, judge.invalid_share_max);
  const base = BigInt(p.spent_micro_usd);
  const spentNow = (): string => String(base + heat.meterMicroUsd());
  const openKey = (): JudgeHeatPartialT['open_key'] => ({ id: heat.key.id, label: heat.key.label, meter_micro_usd: String(heat.meterMicroUsd()) });
  // The calls kept when this attempt opened: one that kept more made progress (the queue's `handOn`).
  const opened = calls.length;
  // Fail the heat: retire its key, keep its spend (and its calls and their spares, when `keep`), and give up for good;
  // a `retry` (a fault the router answered finally, or a router heat's second it never saw) with a queue attempt still to come ends this attempt alone, retryable;
  // one after this attempt kept a call it did not start with is handed on to a fresh job instead, when the queue can (its flags returned).
  const fail = async (cause: Error, keep: boolean, retry: boolean): Promise<string[]> => {
    const retired = await heat.retire().catch((err: unknown) => {
      say(`key ${heat.key.label} could not be retired (${err instanceof Error ? err.message : String(err)}): masq lets it lapse`);
      return null;
    });
    await o.onRetired?.(retired, heat.meterMicroUsd());
    await save(judgeHeatPartialSpares({ ...p, calls: keep ? [...calls] : [], resent: 0, spent_micro_usd: spentNow(), open_key: retired === null ? openKey() : null }, keep ? (p.spares ?? []) : []));
    const handOn = o.queue?.handOn;
    if (retry && keep && calls.length > opened && handOn !== undefined) {
      const handed = await handOn(cause).catch((err: unknown) => {
        say(`the heat could not be handed on to a fresh job (${err instanceof Error ? err.message : String(err)}), so this attempt fails`);
        return false;
      });
      if (handed) return [...(retired?.flags ?? [])];
    }
    if (retry && o.queue !== undefined && !o.queue.last) {
      throw new Error(`${what}: ${cause.message}. Nothing is written: this attempt ends, its ${calls.length} calls kept, and the queue tries the job again from them`, { cause });
    }
    const spent = retry && o.queue !== undefined ? ", and the queue's attempts at the job are spent" : '';
    throw new PermanentJobError(`${what}: ${cause.message}${spent}. Nothing is written: the heat is failed, and the job dead`, { cause });
  };
  const fault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault;
  // A fault superbot-router answered finally (judge-call.ts JudgeCallFault.final): no layer sends that call again.
  const finalFault = (s: JudgeSentT): boolean => !s.ok && s.err instanceof JudgeCallFault && s.err.final;
  const stopped: { failure: { cause: Error; keep: boolean; retry: boolean } | null } = { failure: null };
  // The calls in flight, told (reporting only): what goes wrong is logged once per message, as the live feed logs its writes.
  const tellFlying = o.flying;
  let flyingFailed = '';
  const flying =
    tellFlying === undefined
      ? undefined
      : (out: { planned: JudgePlannedCallT; at: Date }[]): void => {
          try {
            tellFlying(out);
            flyingFailed = '';
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            if (message !== flyingFailed) say(`the judge heat's calls in flight could not be told to its live progress (${message}): the heat goes on`);
            flyingFailed = message;
          }
        };
  let whole: boolean;
  try {
    whole = await sendJudgeHeatCalls({
      heat,
      setup,
      calls,
      concurrency: o.concurrency ?? JUDGE_HEAT_CONCURRENCY,
      ...(signal === undefined ? {} : { signal }),
      backup: o.backup ?? null,
      ...(o.clock === undefined ? {} : { clock: o.clock }),
      ...(o.formsSeen === undefined ? {} : { formsSeen: o.formsSeen }),
      ...(o.progress === undefined ? {} : { progress: o.progress }),
      ...(o.seat === undefined ? {} : { seat: o.seat }),
      ...(flying === undefined ? {} : { flying }),
      ...(o.now === undefined ? {} : { now: o.now }),
      callsTotal: planned,
      // The fault re-send's requests, held back from a backup while the heat has not spent it.
      reserveRequests: () => (p.resent === 0 ? jh.JUDGE_CALL_MAX_ATTEMPTS : 0),
      log: say,
      // A second fault, a fault the router answered finally, an error no heat expects, or the calls with no verdict already past the share: no call to come mends it.
      doomed: (ahead) =>
        ahead.some((s) => !s.ok && !fault(s)) ||
        ahead.some(finalFault) ||
        p.resent + ahead.filter(fault).length > 1 ||
        shareStop(calls, calls.filter((c) => c.verdict === null).length + ahead.filter((s) => s.ok && s.answer.verdict === null).length, calls.length + ahead.length) !== null,
      take: async (next, sent, spares) => {
        if (!sent.ok) {
          const err = sent.err;
          if (!(err instanceof JudgeCallFault)) throw err;
          // The attempt given up (pg-boss's expiry: its signal aborts the requests in flight): no fault of the gateway's, and the retry goes on from the calls kept.
          if (signal?.aborted === true) throw signal.reason instanceof Error ? signal.reason : err;
          // The router answered it finally: never sent again in this attempt; the attempt ends, its calls kept, for the queue to retry.
          if (err.final) {
            say(`call ${calls.length + 1} of ${plannedWords} faulted (${err.message}): the router answered it finally, so it is not sent again in this attempt`);
            stopped.failure = { cause: new jh.JudgeHeatError(`call ${calls.length + 1} of ${plannedWords} faulted (${err.message}): the router answered it finally, so it is not sent again in this attempt`), keep: true, retry: true };
            return 'stop';
          }
          if (p.resent === 0) {
            say(`call ${calls.length + 1} of ${plannedWords} faulted (${err.message}): it is sent again, the heat's one`);
            await save({ ...p, resent: 1, spent_micro_usd: spentNow(), open_key: openKey() });
            return 'again';
          }
          // On superbot-router a second fault it never saw (a refused connect, the Gateway's own 503 or 403: a flap of seconds)
          // ends the attempt as a final fault does, its calls kept, for the queue to retry or the heat to hand on.
          if (router) {
            const why = `call ${calls.length + 1} of ${plannedWords} faulted (${err.message}) after the heat had sent one faulted call again: superbot-router never saw this one, so the attempt ends with its calls kept, not the heat`;
            say(why);
            stopped.failure = { cause: new jh.JudgeHeatError(why), keep: true, retry: true };
            return 'stop';
          }
          stopped.failure = { cause: new jh.JudgeHeatError(`call ${calls.length + 1} of ${plannedWords} faulted (${err.message}) after the heat had sent one faulted call again`), keep: true, retry: false };
          return 'stop';
        }
        try {
          calls.push(jh.judgeHeatCallOf(next, sent.answer));
        } catch (err) {
          if (!(err instanceof jh.JudgeHeatError)) throw err;
          stopped.failure = { cause: err, keep: true, retry: false };
          return 'stop';
        }
        // The call and its spares in one partial (a partial's spares name only the calls it keeps), saved as the throttle lets.
        await keepCall(judgeHeatPartialSpares({ ...p, calls: [...calls], spent_micro_usd: spentNow(), open_key: openKey() }, [...(p.spares ?? []), ...spares]));
        // The calls with no verdict already past the share the whole heat may hold: no call to come can mend it.
        const invalid = calls.filter((c) => c.verdict === null).length;
        const most = shareStop(calls, invalid, calls.length);
        if (most !== null) {
          const mostWords = judgeHeatCallsBounded(setup) ? `at most ${most}` : String(most);
          stopped.failure = { cause: new jh.JudgeHeatError(`${invalid} of the heat's ${mostWords} calls came back with no verdict, over judge.invalid_share_max ${judge.invalid_share_max}`), keep: false, retry: false };
          return 'stop';
        }
        return 'kept';
      },
    });
  } catch (err) {
    // What the calls in flight spent (each settled by now) goes on the partial, and on its open key's meter, which the
    // retry retires the key against; the calls kept stay the settled prefix, every one the throttle held saved now.
    const moved = p.open_key !== null && p.open_key.id === heat.key.id && p.open_key.meter_micro_usd !== String(heat.meterMicroUsd());
    if (moved || dirty) {
      await save(moved ? { ...p, spent_micro_usd: spentNow(), open_key: openKey() } : p).catch((e: unknown) => say(`the calls kept and the spend of the calls in flight could not be saved (${e instanceof Error ? e.message : String(e)})`));
    }
    throw err;
  }
  if (!whole) {
    if (stopped.failure === null) throw new Error(`${what}: the heat stopped with no failure`);
    return fail(stopped.failure.cause, stopped.failure.keep, stopped.failure.retry);
  }
  const retired = await heat.retire();
  if (retired.flags.length > 0) say(`retired key ${heat.key.label}: ${retired.flags.join('; ')}`);
  await o.onRetired?.(retired, heat.meterMicroUsd());
  await save({ ...p, calls: [...calls], spent_micro_usd: spentNow(), open_key: null });
  return [...retired.flags];
}

/**
 * Judge a due phase's field in one heat (createProgramHeatHandler; the header's `judge heat`): read the field's
 * artifacts and the house anchors, resume from the calls an earlier attempt kept, open the heat (grader/judge-call.ts
 * openJudgeHeat: a key of its own with no dollar cap, the header's `judge keys`, opened whatever its worst case), send
 * the calls still to come, every round its schedule plans, keeping each as it settles, retire the key,
 * then store the record and write each entry's run its score built again with its verdict (scoreWithJudge) and the
 * link to the record, in one transaction, the run of an entry the heat left out (judgeHeatInputs) the link alone. Null when
 * the heat is held at its opening (an unpriced model, or one blind to an image artifact): it hands itself on an hour
 * later and pages (holdJudgeHeat). A call that faults is
 * sent once again (on superbot-router, only for a fault the router never saw); a second fault off superbot-router, or
 * more calls with no verdict than judge.invalid_share_max allows, fails the heat
 * as a PermanentJobError (grader/judge-heat.ts JudgeHeatError its cause): nothing is written, the dead job is paged.
 * A fault the router answered finally, or a second one it never saw, ends the attempt with its calls kept and its key retired, and throws for the
 * queue to retry the job, which resumes from them (sendJudgeHeat's `queue`); on the job's last attempt it fails the heat.
 * An attempt that kept a call it did not start with hands the heat on instead (handOnJudgeHeat: null, nothing thrown).
 * A heat that dies (a PermanentJobError, or any throw on its job's last attempt) takes its live document with it
 * (server/competitions/live-judging.ts removeJudgeLive), as a recorded one does: the live board shows no progress of a
 * heat that no longer runs, only the grades' stage until a resend's heat writes its own.
 *
 * A screened final (judge.screened; judge heat v4) screens its field on the dev phase's ladder ratings first
 * (judgeHeatInputs), its screen kept in the partial with its judges before any key is claimed, so a resumed attempt plays
 * on the same screen whatever the dev records say by then (one held at its opening, nothing kept, drops both and reads
 * them again). Its call count is its race's (judgeHeatPlannedCalls an upper bound, its key's ledger sized to it): the
 * heat is done at its schedule's `complete`, each Swiss round, racing epoch and playoff batch planned as the last call
 * before it settles, in the same pool seat ('final') and width as any final. Every entry's run is written through
 * scoreWithJudge, a screened-out one's verdict its dev rating over no match.
 */
async function judgeCodeHeat(deps: GradeWorkerDeps, due: JudgeHeatDue, jobKey: string, ctx: CodeHeatJobContext | undefined, held: HoldPaged): Promise<JudgeHeatOutcome | null> {
  try {
    return await judgeCodeHeatAttempt(deps, due, jobKey, ctx, held);
  } catch (err) {
    if (err instanceof PermanentJobError || (ctx !== undefined && isLastAttempt(ctx))) {
      const say = (line: string) => (deps.log ?? ((l: string) => console.log(l)))(`[code-heat] ${jobKey}: ${line}`);
      const { removeJudgeLive } = await import('../server/competitions/live-judging.ts');
      await removeJudgeLive(deps.blobs.root, due.ph.id).catch((e: unknown) => say(`the failed judge heat's live progress could not be removed (${e instanceof Error ? e.message : String(e)})`));
    }
    throw err;
  }
}

/** One attempt at judgeCodeHeat's heat: everything it does but take a dead heat's live document. */
async function judgeCodeHeatAttempt(deps: GradeWorkerDeps, due: JudgeHeatDue, jobKey: string, ctx: CodeHeatJobContext | undefined, held: HoldPaged): Promise<JudgeHeatOutcome | null> {
  const { db, blobs } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());
  const { comp, ph, judge } = due;
  const what = `the judge heat of ${comp.slug}'s final phase (job ${jobKey})`;
  // The one model the heat asks with no plan (namedJudgeAgent): a pool or the house's is judged only on a plan's judges.
  const agent = namedJudgeAgent(judge.agent);
  const planner = deps.judge?.plan;
  const say = (line: string) => log(`[code-heat] ${jobKey}: ${line}`);
  const jh = await import('./judge-heat.ts');
  const { JudgeArtifactRefused, openJudgeHeat } = await import('./judge-call.ts');
  const { retireTrialKey } = await import('./gateway/masq.ts');
  const { judgeBackupRuleOf } = await import('./judge-backup.ts');
  const { ROUTER_KEY_ID_PREFIX } = await import('../server/superbot-router.ts');
  const formsSeen = judgeFormsSeenOf(deps);
  const store = judgeHeatPartialStore(deps.workRoot, ph.id);
  // The planner's answer for this heat, asked at most once an attempt (undefined: not asked).
  let asked: JudgeWorkerPlan | null | undefined;
  const ask = async (seed: string): Promise<JudgeWorkerPlan | null> => {
    if (asked === undefined) asked = await planner!.of({ slug: comp.slug, stage: 'final', judge: judge.agent, seed });
    return asked;
  };
  // The kept partial read back off this thread (judge-heat-tasks.ts judgeHeatKeptReadOffThread), once an attempt: what
  // judgesOf takes the heat's judges from and keptJudgeHeat its calls (undefined: not read yet, or its store's read
  // threw, which the next asker meets again; null: none kept). The pool's own rejection propagates: the job retries.
  let keptRead: JudgeKeptRead | null | undefined;
  const keptOf = async (text: string | null): Promise<JudgeKeptRead | null> => {
    if (keptRead === undefined) keptRead = text === null ? null : await (await import('./judge-heat-tasks.ts')).judgeHeatKeptReadOffThread(text, ctx?.signal);
    return keptRead;
  };
  const readKept = async (): Promise<JudgeKeptRead | null> => (keptRead !== undefined ? keptRead : keptOf(await store.read()));
  // A block naming no one model sets up only on judges: the kept partial's (keptJudgeHeat holds them to this heat), else
  // the planner's; with no planner it waits on one, the platform's fault.
  const judgesOf =
    agent !== null
      ? undefined
      : async (seed: string): Promise<readonly JudgeOfHeatT[]> => {
          let text: string | null | undefined;
          try {
            text = await store.read();
          } catch {
            text = undefined; // keptJudgeHeat reads it again, and says why
          }
          const kept = text === undefined ? null : await keptOf(text);
          // One that does not read, or holds no judges: keptJudgeHeat says why.
          const fixed: readonly JudgeOfHeatT[] | undefined = kept === null || 'unread' in kept ? undefined : kept.head.judges;
          if (fixed !== undefined) return fixed;
          const fresh = planner === undefined ? null : await ask(seed);
          if (fresh === null) throw new PermanentJobError(`${what}: ${JUDGE_NAMES_NO_MODEL}`);
          return fresh.judges;
        };
  // A screened final's screen (judgeHeatInputs): the one its partial kept under its key, else the dev phase's ratings
  // held to the judges the heat calls on, the planner's pick (asked once: the plan below takes the same answer), else
  // the block's one named model on its door. A heat whose screen was kept plays on the judges kept with it.
  const screenSource: JudgeHeatScreenSource | undefined =
    judge.screened === undefined
      ? undefined
      : {
          kept: async () => {
            let kept: JudgeHeatPartialT | undefined;
            try {
              const text = await store.read();
              kept = text === null ? undefined : jh.JudgeHeatPartial.safeParse(JSON.parse(text)).data;
            } catch {
              kept = undefined; // keptJudgeHeat says why
            }
            return kept?.screen === undefined ? null : { key: kept.key, screen: kept.screen };
          },
          judges: async (seed) => {
            const fresh = planner === undefined ? null : await ask(seed);
            if (fresh !== null) return fresh.judges;
            if (agent === null) throw new PermanentJobError(`${what}: ${JUDGE_NAMES_NO_MODEL}`);
            return jh.judgeHeatJudgesOf({ agent: judge.agent });
          },
        };

  // Each stage before the first call says how long it took (judgeHeatPrepLine): an attempt silent for minutes is told
  // from its log.
  let stageAt = performance.now();
  const stage = (line: string): void => {
    const at = performance.now();
    say(judgeHeatPrepLine(line, at - stageAt));
    stageAt = at;
  };
  const inputs = await judgeHeatInputs(deps, due, what, judgesOf, screenSource);
  stage(`its inputs read: ${inputs.entries.length} entries' artifacts and ${inputs.artifacts.size} distinct members' bytes, ${inputs.left.length} entries left out`);
  for (const l of inputs.left) say(`entry ${l.row.submission_id} (run ${l.run.id}) is left out of the heat, and ranks below every judged entry: ${l.why}`);
  if (inputs.screen?.from === 'partial') say('its screen is the one fixed before its first call, kept with its calls: the dev records are not read again');
  else if (inputs.screen?.from === 'dev') {
    const unrated = new Map<string, number>();
    for (const e of inputs.screen.entries) if ('unrated' in e) unrated.set(e.unrated, (unrated.get(e.unrated) ?? 0) + 1);
    const rated = inputs.screen.entries.length - [...unrated.values()].reduce((a, b) => a + b, 0);
    say(
      `its screen read from the dev phase's ladder records: ${rated} of ${inputs.screen.entries.length} entries rated` +
        (unrated.size === 0 ? '' : `, the rest unrated and entering at the line (${[...unrated].map(([why, n]) => `${why} ${n}`).join(', ')})`),
    );
  }
  // What the kept calls are this heat's only under: besides the setup (which names every member by its bytes, and a screened final's screen), the phase, the bundle and the prompt.
  const resumeKey = judgeHeatResumeKeyOf(jh.judgeHeatResumeKey, inputs.setup, due, inputs.prompt);
  const resumed = await keptJudgeHeat(store, readKept, resumeKey, inputs.setup, say, ctx?.signal);
  // Read once: the partial's text and its calls' JSON go with this answer.
  keptRead = null;
  stage(`its kept partial parsed: ${resumed.partial.calls.length} calls kept`);
  let p = resumed.partial;
  // Each save writes the calls, canonicalJson's bytes with the calls already written remembered between saves
  // (judgeHeatPartialWriter), the kept calls' as they came back read; a screened final's screen goes to its sidecar
  // once, not with every save (judgeHeatPartialStore).
  const partialText = judgeHeatPartialWriter();
  partialText.remember(resumed.partial.calls, resumed.texts);
  const save = async (next: JudgeHeatPartialT): Promise<void> => {
    p = next;
    await store.save(next, partialText);
  };
  // Its calls at most (judgeHeatPlannedCalls): every call of a v1 or v2 heat, an upper bound on a screened final's, whose
  // race makes as many as its results ask for. The heat owes calls while its schedule over those kept is not complete.
  const planned = jh.judgeHeatPlannedCalls(inputs.setup);
  const plannedWords = judgeHeatCallsBounded(inputs.setup) ? `at most ${planned}` : String(planned);
  // Its schedule over the kept calls planned as the sender plans it (sendJudgeHeatCalls' default): a screened final's on
  // this run's memo, in this thread; any other format's refits every Swiss round so far (0.25-0.65 s of CPU at 2,500
  // members), so it is planned off this thread past a small heat's size (judge-heat-tasks.ts judgeHeatScheduleFor; the
  // pool's OffThreadError rejects, and the job retries from the calls kept).
  const memo = jh.judgeHeatScheduleMemo();
  const offThreadSchedule = inputs.setup.format !== jh.JUDGE_HEAT_FORMAT_V4 ? (await import('./judge-heat-tasks.ts')).judgeHeatScheduleFor : null;
  const owes = async (on: JudgeHeatSetupT, kept: readonly JudgeHeatCallT[]): Promise<boolean> => {
    const sc = offThreadSchedule !== null ? await offThreadSchedule(on, kept, ctx?.signal) : jh.judgeHeatSchedule(on, kept, memo);
    return sc.issue !== null || !sc.complete || kept.length < sc.planned.length;
  };
  // Its judges, fixed before its first call (the partial's `judges`): a heat that has started plays on its own whatever
  // the planner says now (none: the bundle's own judge, the planner never asked); one that has not asks it once.
  let plan: JudgeWorkerPlan | null = null;
  if (p.judges !== undefined) {
    // A release with no planner (rolled back, or a test's) never replays them on the bundle's judge: the queue tries again.
    if (planner === undefined) throw new Error(`${what}: its judges (${p.judges.map((x) => x.model).join(', ')}) were fixed before its first call, and this process has no judge planner to play them on`);
    // Their pins read again for the calls still to send (plan.ts resume); a heat whose every call is kept only records.
    plan = (await owes(inputs.setup, p.calls)) ? await planner.resume(p.judges) : { judges: [...p.judges], pins: [] };
    say(`its judges, fixed before its first call: ${plan.judges.map((x) => `${x.model} on ${x.door} (weight ${x.weight})`).join(', ')}`);
  } else if (!(resumed.own && (p.calls.length > 0 || p.open_key !== null)) && planner !== undefined) {
    plan = await ask(inputs.setup.seed);
    if (plan !== null) say(`its judges, fixed now before its first call: ${plan.judges.map((x) => `${x.model} on ${x.door} (weight ${x.weight})`).join(', ')}`);
  }
  if (plan === null && agent === null) throw new PermanentJobError(`${what}: ${JUDGE_NAMES_NO_MODEL}`);
  const setup: JudgeHeatSetupT = plan === null ? inputs.setup : { ...inputs.setup, judges: [...plan.judges] };
  stage(`its judges fixed: ${plan === null ? "the bundle's own judge" : `${plan.judges.length} on its plan`}`);
  const keptCalls = p.calls.length;
  const calls = [...p.calls];
  const broker = await judgeBrokerOf(deps);
  // A plan whose every judge is on OpenRouter needs no house broker, and takes no seat in the judge pool.
  const offHouse = plan !== null && plan.judges.every((x) => x.door === 'openrouter');
  if (broker === null && !offHouse) {
    throw new PermanentJobError(`${what}: this process has no LLM gateway (MAKEFUN_LLM_GATEWAY=masq, its URL and admin key) and no superbot-router pair (MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_KEY) to send the house judge's calls through`);
  }
  // On a plan, the planner's broker over the house's (plan.ts broker): every key of the heat minted and retired through it.
  const heatBroker = plan === null ? broker! : planner!.broker(broker);
  // A key a plan's heat minted (a `pool:` or `openrouter:` id) goes back through the planner's broker, whatever it plans now.
  const retireVia = async (id: string): Promise<MasqJudgeKeyBroker> => {
    if (plan !== null || planner === undefined) return heatBroker;
    const [{ JUDGE_POOL_KEY_ID_PREFIX }, { OPENROUTER_KEY_ID_PREFIX }] = await Promise.all([import('../server/judging/plan.ts'), import('../server/openrouter-judge.ts')]);
    return id.startsWith(JUDGE_POOL_KEY_ID_PREFIX) || id.startsWith(OPENROUTER_KEY_ID_PREFIX) ? planner.broker(broker) : heatBroker;
  };
  // The phase's keys as kept (the header's `judge keys`): every attempt's, on whichever host it ran.
  const keysDir = judgeKeysDir(blobs, ph.id);
  let kept = await readJudgeKeys(keysDir, now());
  // A kept key retired: its file says so, and what masq says it spent.
  const keptKey = async (id: string, meter: bigint, retired: RetiredTrialKey): Promise<void> => {
    const k = kept.find((x) => x.key_id === id);
    if (k === undefined) return;
    const closed = await writeJudgeKey(keysDir, retiredJudgeKey(k, meter, retired));
    kept = kept.map((x) => (x === k ? closed : x));
  };
  // A key an earlier attempt left open (it stopped mid-heat): retired first, against what it metered.
  if (p.open_key !== null) {
    const retired = await retireTrialKey(await retireVia(p.open_key.id), p.open_key.id, BigInt(p.open_key.meter_micro_usd));
    say(`retired key ${p.open_key.label}, which an earlier attempt left open${retired.flags.length === 0 ? '' : ` (${retired.flags.join('; ')})`}`);
    await keptKey(p.open_key.id, BigInt(p.open_key.meter_micro_usd), retired);
    await save({ ...p, open_key: null });
  }
  // So is one an attempt on another host left open (its calls kept there, never here): the phase's heats run one at a time.
  for (const k of kept.filter((x) => x.stage === 'final' && x.open && x.key_id !== null)) {
    const retired = await retireTrialKey(await retireVia(k.key_id!), k.key_id!, BigInt(k.meter_micro_usd));
    say(`retired key ${k.label ?? k.key_id}, which an earlier attempt elsewhere left open, masq's spend on it ${retired.spend.microUsd} µUSD${retired.flags.length === 0 ? '' : ` (${retired.flags.join('; ')})`}`);
    await keptKey(k.key_id!, BigInt(k.meter_micro_usd), retired);
  }
  let keyFlags: string[] = [];
  if (await owes(setup, calls)) {
    // A plan's judges kept before any key is claimed: every attempt after plays on them (the mix fixed before its first
    // call); so is a screened final's screen, which a resumed attempt sets up on (judgeHeatInputs).
    // The setup's screen less what the bundle names (its z and line M): the inputs, whatever else they carry.
    const screen: JudgeHeatScreenInputsT | undefined = setup.screen === undefined ? undefined : (({ z: _z, line_places: _line, ...inputs }) => inputs)(setup.screen);
    const judgesNow = plan !== null && p.judges === undefined;
    const screenNow = screen !== undefined && (p.screen === undefined || canonicalJson(p.screen) !== canonicalJson(screen));
    if (judgesNow || screenNow) await save({ ...p, ...(judgesNow ? { judges: plan!.judges } : {}), ...(screenNow ? { screen } : {}) });
    const mine = await claimJudgeKey(
      keysDir,
      { format: JUDGE_KEY_FORMAT, phase_id: ph.id.toLowerCase(), stage: 'final', at: now().toISOString(), key_id: null, label: null, reserved_micro_usd: '0', meter_micro_usd: '0', masq_micro_usd: null, open: true },
      p.keys + 1,
    );
    const attempt = mine.attempt;
    let opening: Awaited<ReturnType<typeof openJudgeHeat>>;
    try {
      // No cap: the heat opens whatever its worst case, its key with no dollar cap (the header's `judge heat`).
      const options: Omit<JudgeHeatOptions, 'agent' | 'pin'> = {
        broker: heatBroker,
        key: { slug: comp.slug, phase: 'final', attempt },
        prompt: inputs.prompt,
        media: judge.media,
        house: setup.house_text,
        artifacts: [...inputs.artifacts].map(([sha256, bytes]) => ({ sha256, bytes })),
        // The calls still to come, and room for the one a fault sends again while the heat has not spent it.
        calls: planned - calls.length + (p.resent === 0 ? 1 : 0),
        blobs,
        ...(deps.judge?.fetch === undefined ? {} : { fetch: deps.judge.fetch }),
        ...(deps.judge?.timeoutMs === undefined ? {} : { timeoutMs: deps.judge.timeoutMs }),
        now: () => now().getTime(),
        ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }),
      };
      // On a plan, the pool heat on its judges (server/judging/pool-heat.ts), which notes the forms memo under each judge's own model.
      opening = plan === null ? await openJudgeHeat({ ...options, agent: agent! }) : await (await import('../server/judging/pool-heat.ts')).openJudgePoolHeat({ ...options, ...(formsSeen === undefined ? {} : { formsSeen }) }, plan);
    } catch (err) {
      await dropJudgeKey(keysDir, mine);
      if (err instanceof JudgeArtifactRefused) {
        const whose = inputs.entries.filter((e) => e.artifact_sha256 === err.sha256).map((e) => e.row.submission_id);
        throw new PermanentJobError(
          `${what}: the judge refuses the artifact ${err.sha256}${whose.length === 0 ? ' (a house anchor)' : ` of ${whose.join(', ')}`}: ${err.message}. The scorer's gate must fail an entry whose artifact the judge cannot read`,
          { cause: err },
        );
      }
      throw err;
    }
    if (opening.held !== null) {
      if (opening.retired === null) await dropJudgeKey(keysDir, mine);
      else await writeJudgeKey(keysDir, retiredJudgeKey({ ...mine, key_id: opening.retired.id }, 0n, opening.retired));
      // Held before its first call, a plan's heat has not started: its judges dropped, so the next attempt plans again,
      // and a screened final's screen with them, read again then on the judges it plans.
      if (plan !== null && calls.length === 0) await save((({ judges: _judges, ...rest }) => rest)(p));
      if (calls.length === 0 && p.screen !== undefined) await save((({ screen: _screen, ...rest }) => rest)(p));
      if (opening.retired !== null) await save({ ...p, keys: attempt });
      return holdJudgeHeat(deps, due, jobKey, { hold: opening.held, attempt }, held);
    }
    const heat = opening.heat;
    const minted = await writeJudgeKey(keysDir, { ...mine, key_id: heat.key.id, label: heat.key.label });
    await save({ ...p, keys: attempt, open_key: { id: heat.key.id, label: heat.key.label, meter_micro_usd: '0' } });
    stage(`its key ${heat.key.label} opened (attempt ${attempt})`);
    say(`judging ${setup.field.length} members (${inputs.entries.length} entries, ${setup.field.filter((m) => m.anchor).length} anchors) in ${plannedWords} calls, ${keptCalls} kept from an earlier attempt, on key ${heat.key.label}`);
    // The heat's progress for the live board (server/competitions/live-judging.ts): each settled call and the calls in
    // flight (sendJudgeHeat's flying, reporting only), a `judge` change at most every 2 s.
    // The calls settled past the kept prefix (the sender's progress) ride beside them.
    const { judgeLiveAheadOf, openJudgeLiveFeed } = await import('../server/competitions/live-judging.ts');
    const live = openJudgeLiveFeed({ blobRoot: blobs.root, phaseId: ph.id, competitionId: comp.id, db, key: resumeKey, setup, kept: keptCalls, now, log: say });
    live.update(calls);
    let ahead: ReturnType<typeof judgeLiveAheadOf>[] = [];
    // Its seat in the platform's one budget of judge sends in flight (the header's `judge heat`), held while it sends; none off the house's doors.
    const seat = offHouse ? null : await judgePoolSeatOf(deps, heat.key.label, 'final', say);
    // The queue a heat that made progress before a final fault hands itself on to (handOnJudgeHeat), and whether it did.
    const jobs = deps.jobs;
    const handed = { on: false };
    // A progress line at most once a JUDGE_HEAT_PROGRESS_MS on the wall clock (judgeHeatProgressLine): the calls judged,
    // the pace since the last line, the calls in flight and the calls the partial on disk holds.
    const told = { at: performance.now(), judged: calls.length, saved: calls.length };
    const tellProgress = (flying: number): void => {
      const at = performance.now();
      if (at - told.at < JUDGE_HEAT_PROGRESS_MS) return;
      say(judgeHeatProgressLine({ judged: calls.length, planned, kept: keptCalls, ms: at - told.at, since: calls.length - told.judged, flying, saved: told.saved }));
      told.at = at;
      told.judged = calls.length;
    };
    try {
      keyFlags = await sendJudgeHeat({
        heat,
        setup,
        judge,
        calls,
        partial: p,
        save: async (next) => {
          await save(next);
          told.saved = next.calls.length;
          live.update(next.calls, ahead);
        },
        // The partial on disk at most every 5 s or 200 calls, and at every stop, abort and the end (the header's `judge heat`).
        saveEvery: { ms: JUDGE_HEAT_SAVE_EVERY_MS, calls: JUDGE_HEAT_SAVE_EVERY_CALLS },
        progress: (q) => {
          ahead = q.ahead.map((x) => judgeLiveAheadOf(x.index, x.planned, x.answer));
          live.update(calls, ahead);
          tellProgress(q.flying);
        },
        ...(seat === null ? {} : { seat }),
        say,
        what,
        // The queue's attempts: a fault the router answered finally ends this one for the queue to retry (none without a job
        // context), or, once it kept a call it did not start with, hands the heat on to the job of the next recheck slot.
        ...(ctx === undefined ? {} : { queue: { last: isLastAttempt(ctx), ...(jobs === undefined ? {} : { handOn: (cause: Error) => handOnJudgeHeat(jobs, ph.id, jobKey, cause, now(), say, handed, { calls: calls.length, opened: keptCalls, planned: plannedWords }) }) } }),
        // The minted key's file (the header's `judge keys`) closed with what the heat metered, and what masq says it spent.
        onRetired: async (retired, meter) => {
          await writeJudgeKey(keysDir, retired === null ? { ...minted, meter_micro_usd: String(meter) } : retiredJudgeKey(minted, meter, retired));
        },
        ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }),
        ...(deps.judge?.concurrency === undefined ? {} : { concurrency: deps.judge.concurrency }),
        // The deps' rule if any (null: none), else the house's: each call sent once on a router key, JUDGE_BACKUP on masq's; on the deps' clock.
        // A plan's pool heat takes no backup (each call sent once), and notes the forms memo itself.
        backup: plan !== null ? null : judgeBackupRuleOf(deps.judge?.backup, heat.key.id.startsWith(ROUTER_KEY_ID_PREFIX)),
        ...(deps.judge?.clock === undefined ? {} : { clock: deps.judge.clock }),
        ...(formsSeen === undefined || plan !== null ? {} : { formsSeen }),
        // The calls in flight, for the live board's game being judged now (LiveJudging.now): reporting only.
        flying: (out) => live.flying(out.map(({ planned: c, at }) => ({ stage: c.stage, round: c.round, a: c.a, b: c.b, slot_order: c.slot_order, sent_at: at.toISOString() }))),
        now,
      });
    } finally {
      // Its seat given back whatever ended the send (it never throws).
      await seat?.close();
      // The last calls written before the record is, or before the heat gives up: no write of the feed's timer lands
      // after judgeCodeHeat removes a dead heat's document.
      await live.flush();
    }
    // Handed on (handOnJudgeHeat): nothing recorded, its live document left to the job it handed on to.
    if (handed.on) return null;
  }

  // The record built, held once, digested and scored off this thread (grader/judge-heat-tasks.ts; judge-heat.ts
  // judgeHeatRecordEnd): over a second of CPU at 15,000 calls. It is sent the calls' and spares' canonical JSON the
  // partial writer already holds, and answers the record's canonical JSON and what is read of it here.
  const { judgeHeatEndText, judgeHeatRecordEndOffThread } = await import('./judge-heat-tasks.ts');
  const ended = await judgeHeatRecordEndOffThread(
    { setup, heat: judgeHeatEndText(partialText.texts(calls), partialText.texts(p.spares ?? [])) },
    { key: `${resumeKey}\u0000${calls.length}`, ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }) },
  );
  if ('issue' in ended) {
    const err = new jh.JudgeHeatError(ended.issue);
    await save(judgeHeatPartialSpares({ ...p, calls: [], resent: 0 }, []));
    throw new PermanentJobError(`${what}: ${err.message}. Nothing is written: the heat is failed, and the job dead`, { cause: err });
  }
  const digest = { sha256: ended.sha256 };
  const put = await blobs.put(ended.json);
  if (put.sha256 !== digest.sha256) throw new Error(`${what}: the record stored as ${put.sha256}, not ${digest.sha256}`);
  if (ended.verdicts === null) throw new jh.JudgeHeatError(ended.verdictsIssue!);
  const verdicts = ended.verdicts;
  // Each entry's standing facts alone (the verdict's eligibility: standingsHouse and baseline), a FIELD_READ_CHUNK of ids a statement.
  const subRows = await chunkedRead(
    [...inputs.entries, ...inputs.left].map((e) => e.row.submission_id),
    (slice) => db.select({ id: submission.id, house: submission.house, submittedAsHouse: submission.submittedAsHouse, baseline: submission.baseline }).from(submission).where(inArray(submission.id, slice)),
  );
  const subOf = new Map(subRows.map((s) => [s.id, s]));
  const rules = eligibilityRulesOf(due.bundle);
  const writes = inputs.entries.map((e) => {
    const verdict = verdicts.get(e.row.submission_id.toLowerCase());
    const sub = subOf.get(e.row.submission_id);
    if (verdict === undefined) throw new Error(`${what}: the record holds no verdict on entry ${e.row.submission_id}`);
    if (sub === undefined) throw new Error(`${what}: entry ${e.row.submission_id} is gone`);
    const stored = Score.safeParse(e.run.result);
    if (!stored.success) throw new Error(`${what}: run ${e.run.id}'s result is no score: ${stored.error.issues[0]?.message ?? 'malformed'}`);
    return { e, verdict, ...scoreWithJudge(stored.data, verdict, { house: standingsHouse(sub), baseline: sub.baseline }, rules) };
  });
  // A run the heat left out keeps its score, built again only to drop a verdict an earlier heat gave it.
  const leftWrites = inputs.left.map((l) => {
    const sub = subOf.get(l.row.submission_id);
    if (sub === undefined) throw new Error(`${what}: entry ${l.row.submission_id} is gone`);
    const stored = Score.safeParse(l.run.result);
    if (!stored.success) throw new Error(`${what}: run ${l.run.id}'s result is no score: ${stored.error.issues[0]?.message ?? 'malformed'}`);
    const perf = stored.data.performance;
    const rebuilt = perf.kind === 'program/v1' && perf.judge !== undefined ? scoreWithJudge(stored.data, null, { house: standingsHouse(sub), baseline: sub.baseline }, rules) : null;
    return { e: l, ...(rebuilt === null ? { result: l.run.result, result_sha256: l.run.resultSha256 } : rebuilt) };
  });
  await db.transaction(async (tx) => {
    for (const w of [...writes, ...leftWrites]) {
      const updated = await tx
        .update(run)
        .set({ result: w.result, resultSha256: w.result_sha256, judgeHeatSha256: digest.sha256 })
        .where(and(eq(run.id, w.e.run.id), eq(run.resultSha256, w.e.run.resultSha256 ?? '')))
        .returning({ id: run.id });
      // A run written since the field was read (a regrade, or another heat): the retry judges the field as it now stands, from the calls kept.
      if (updated.length === 0) throw new Error(`${what}: run ${w.e.run.id} of entry ${w.e.row.submission_id} changed while its heat ran`);
    }
    await recordLiveChange(tx, { ...GRADE_CHANGE, scopeId: comp.id });
  });
  await store.remove().catch((err: unknown) => say(`the judge calls kept at ${store.where} could not be removed (${err instanceof Error ? err.message : String(err)})`));
  // The live board reads the record from here on (server/competitions/live-judging.ts): the heat's live document goes.
  const { removeJudgeLive } = await import('../server/competitions/live-judging.ts');
  await removeJudgeLive(blobs.root, ph.id).catch((err: unknown) => say(`the judge heat's live progress could not be removed (${err instanceof Error ? err.message : String(err)})`));
  const outcome: JudgeHeatOutcome = {
    kind: 'judge',
    phase_id: ph.id,
    heat_sha256: digest.sha256,
    calls: ended.calls,
    kept_calls: keptCalls,
    invalid_calls: ended.invalid_calls,
    spent_micro_usd: p.spent_micro_usd,
    finalists: ended.finalists,
    key_flags: keyFlags,
    entries: writes.map((w) => ({
      submission_id: w.e.row.submission_id,
      run_id: w.e.run.id,
      artifact_sha256: w.e.artifact_sha256,
      win_rate_micro: w.verdict.win_rate_micro,
      finalist: w.verdict.finalist,
      result_sha256: w.result_sha256,
    })),
    left_out: leftWrites.map((w) => ({ submission_id: w.e.row.submission_id, run_id: w.e.run.id, why: w.e.why, result_sha256: w.result_sha256 })),
  };
  say(
    `judged ${comp.slug}'s final: record ${digest.sha256}, ${outcome.calls} calls (${keptCalls} kept, ${outcome.invalid_calls} with no verdict), ${outcome.spent_micro_usd} µUSD; ` +
      writes.map((w) => `${w.e.row.submission_id} ${winRateFraction(w.verdict.win_rate_micro)}${w.verdict.finalist ? ' (finalist)' : w.verdict.screened_out === true ? ' (screened out)' : ''}`).join(', ') +
      outcome.left_out.map((x) => `, ${x.submission_id} left out`).join(''),
  );
  return outcome;
}

/**
 * A final's judge heat handed on (judgeCodeHeat; sendJudgeHeat's `queue.handOn`): its attempt ended on a fault the router
 * answered finally after keeping a call it did not start with (`kept`), its key retired and its calls kept, so rather
 * than spend one of the queue's attempts it sends the phase's code-heat job for the next CODE_HEAT_RECHECK_MS slot
 * (codeHeatJobId `wait:<slot>`, as a waiting heat does: one already sent for that slot looks then as well; the slot after
 * when that job is this one), which resumes from the calls kept, logs it, and marks `handed`. True once sent; a send that
 * throws propagates (sendJudgeHeat then fails the attempt as before). No loop: each hand-on keeps one call more of a heat
 * that plans finitely many, and an attempt that keeps none spends the queue's attempt as before.
 */
async function handOnJudgeHeat(
  jobs: Pick<JobQueue, 'send'>,
  phaseId: string,
  jobKey: string,
  cause: Error,
  at: Date,
  say: (line: string) => void,
  handed: { on: boolean },
  kept: { calls: number; opened: number; planned: number | string },
): Promise<boolean> {
  let slot = Math.floor(at.getTime() / CODE_HEAT_RECHECK_MS) + 1;
  // A clock behind the queue's names this job's own slot: no job to come, so the slot after.
  if (codeHeatJobId(phaseId, `wait:${slot}`) === jobKey) slot++;
  const startAfter = new Date(slot * CODE_HEAT_RECHECK_MS);
  const id = codeHeatJobId(phaseId, `wait:${slot}`);
  // A judge heat's: marked so (server/jobs.ts sendJudgeHeatJob), it waits for no place in the sandbox pool.
  const sent = await sendJudgeHeatJob(jobs, phaseId, { id, startAfter });
  handed.on = true;
  say(
    `handed on: ${cause.message}; ${kept.calls} of its ${kept.planned} calls kept (${kept.calls - kept.opened} by this attempt) and its key retired, ` +
      `job ${id}${sent === null ? ' (sent before)' : ''} looks again at ${startAfter.toISOString()}, and none of the queue's attempts is spent`,
  );
  return true;
}

/**
 * A judge heat held at its opening (grader/judge-call.ts JudgeHold: an unpriced model, or a model that cannot see an
 * image artifact): the phase's code-heat job sent again for the next JUDGE_HEAT_HOLD_RECHECK_MS slot (codeHeatJobId
 * `judge-hold:<slot>`), which opens the heat again from the calls kept, and the hold paged, once an hour a competition
 * (AGENT_REFUSAL_PAGE_MS; logged between). Once
 * that job is sent, the competition's open pages are told (server/competitions/live-judging.ts JUDGE_LIVE_CHANGE),
 * so they read GET /live again rather than at their next poll, and the board finds the hold from that job (heatHeldOf);
 * it is recorded last, since the board takes this job as the heat's while it runs. A change that fails to record is
 * logged, and the hold holds. Null: nothing recorded.
 */
async function holdJudgeHeat(deps: GradeWorkerDeps, due: JudgeHeatDue, jobKey: string, h: { hold: JudgeHold; attempt: number }, held: HoldPaged): Promise<null> {
  const log = deps.log ?? ((line: string) => console.log(line));
  const page = deps.page ?? ((line: string) => console.error(line));
  const at = (deps.now ?? (() => new Date()))().getTime();
  const { judgeHoldPage } = await import('./judge-call.ts');
  const slot = Math.floor(at / JUDGE_HEAT_HOLD_RECHECK_MS) + 1;
  const until = new Date(slot * JUDGE_HEAT_HOLD_RECHECK_MS);
  let sent: Date | null = null;
  if (deps.jobs !== undefined) {
    // Marked a judge heat's (server/jobs.ts sendJudgeHeatJob): it waits for no place in the sandbox pool.
    await sendJudgeHeatJob(deps.jobs, due.ph.id, { id: codeHeatJobId(due.ph.id, `judge-hold:${slot}`), startAfter: until });
    sent = until;
  }
  const text = judgeHoldPage({ slug: due.comp.slug, phase: 'final', attempt: h.attempt, hold: h.hold, until: sent });
  const last = held.get(due.comp.id);
  if (last === undefined || at - last >= AGENT_REFUSAL_PAGE_MS) {
    held.set(due.comp.id, at);
    page(text);
  } else {
    log(`[code-heat] ${jobKey}: ${text}`);
  }
  if (sent !== null) {
    const { JUDGE_LIVE_CHANGE } = await import('../server/competitions/live-judging.ts');
    await deps.db
      .transaction((tx) => recordLiveChange(tx, { ...JUDGE_LIVE_CHANGE, scopeId: due.comp.id }))
      .catch((err: unknown) => log(`[code-heat] ${jobKey}: the hold's live change could not be recorded (${err instanceof Error ? err.message : String(err)}): open pages see it at their next read`));
  }
  return null;
}

// ---------------------------------------------------------------- scrape/v1: heats

/** What a scrape/v1 grade or heat reads besides GradeWorkerDeps' own (the header's `scrape/v1`). */
export interface ScrapeWorkerDeps {
  /** The host's one lease name, every heat's and every waiting job's (default scrapeLeaseDirFromEnv()): the name of a scrape_heat_lease row. */
  leaseDir?: string;
  /**
   * What the lease keeps off the host while a heat holds it (default scrapeLeaseScopeFromEnv(): MAKEFUN_SCRAPE_LEASE_SCOPE,
   * else `host`; the header's `scrape/v1`): `host`, every other grading job; `egress`, only another heat, the heat's
   * pods reserving their CPU instead.
   */
  leaseScope?: ScrapeLeaseScope;
  /**
   * drand's signature of `round` on `chain` (default server/routes/admin/sealed-window.ts fetchDrandRound over its
   * default relays). Whatever answers, the signature is verified here against the chain's key before a heat draws on it.
   */
  drandRound?: (chain: DrandChain, round: number) => Promise<{ signature: string }>;
  /** The gateway the trials run (default grader/scrape/bundle.ts scrapeGatewayBundle, cached under <workRoot>/scrape-gateway). */
  gateway?: () => Promise<{ dir: string; script: string }>;
  /** The node22 house's launch.ts as text (default grader/scrape/launch.ts launcherSource()). */
  launcherSource?: string;
  /** The heat's pacing (default grader/scrape/heat.ts SCRAPE_PACING_DEFAULTS). */
  pacing?: ScrapePacing;
  /** Passed to every trial as they are (heat.ts ScrapeHeatOptions.trial: a test's upstream port and CA). */
  trial?: ScrapeHeatOptions['trial'];
  /** The heat's own parts (heat.ts ScrapeHeatDeps: its trials, judge, resolver and clock); tests replace them. */
  heat?: ScrapeHeatDeps;
  /** The waits' clock: a job waiting on the host's lease, the final heat waiting for its round (default the wall clock). */
  clock?: ScrapeHeatClock;
  /** How often a job waiting on the host's lease looks again (default SCRAPE_LEASE_POLL_MS). */
  leasePollMs?: number;
  /** Told every event of every heat (heat.ts ScrapeHeatEvent). */
  onEvent?: (e: ScrapeHeatEvent) => void;
  /**
   * grader/scrape/score.ts's judge, performance and disagreement error as an admin's re-judging judges with them
   * (createScrapeHeatHandler's `rejudge`; default that module, loaded at the first re-judging); a test hands in a fake.
   */
  scoring?: Pick<typeof import('./scrape/score.ts'), 'judgeScrapeTrial' | 'scrapePerformance' | 'ScorerDisagreementError'>;
}

/** The environment variable naming the host's scrape lease directory (scrapeLeaseDirFromEnv). */
export const SCRAPE_LEASE_DIR_ENV = 'MAKEFUN_SCRAPE_LEASE_DIR';
/** How often a job waiting on the host's lease looks again. */
export const SCRAPE_LEASE_POLL_MS = 15_000;
/** How long after a drand round's emission the heat asks the relays for it (a relay serves it a moment late). */
export const SCRAPE_DRAND_LAG_MS = 3_000;
/** The run flag of a run whose voids are held for an admin's review before prizes (scrapeVoidsReview): on the run row, never in the score. */
export const SCRAPE_VOIDS_REVIEW_FLAG = 'scrape_voids_review';
/** The run flag of a run its scorer left unscored (a disagreement or a fault, the house's): recorded failed and never published. */
export const SCRAPE_SCORER_FAULT_FLAG = 'scrape_scorer_fault';
/** A practice heat's id stem (scrapeHeatIdOf): its trials' owners, its lease and its record say practice. */
export const SCRAPE_PRACTICE_HEAT_PREFIX = 'practice-';
/** The final phase's heat's id stem. */
export const SCRAPE_FINAL_HEAT_PREFIX = 'final-';

/**
 * The host's scrape lease directory: MAKEFUN_SCRAPE_LEASE_DIR, else <os tmpdir>/makefun-scrape-lease, one name for every
 * process that reaches the upstream from the one egress, so every heat and every grading job of the egress meets the one
 * lease (heat.ts acquireScrapeHostLease: the name of a scrape_heat_lease row).
 */
export function scrapeLeaseDirFromEnv(env: Readonly<Record<string, string | undefined>> = process.env): string {
  const named = (env[SCRAPE_LEASE_DIR_ENV] ?? '').trim();
  return named === '' ? join(tmpdir(), 'makefun-scrape-lease') : resolve(named);
}

/** The environment variable naming the scrape lease's scope (scrapeLeaseScopeFromEnv). */
export const SCRAPE_LEASE_SCOPE_ENV = 'MAKEFUN_SCRAPE_LEASE_SCOPE';
/**
 * What a held scrape lease keeps off its host (the header's `scrape/v1`). `host`, the default: every other grading job
 * of the host waits or hands itself on while a heat runs, so the heat's trials have the CPU to themselves. `egress`:
 * only another heat does (one heat at a time on the egress address, whose rate buckets and pacer assume the heat is
 * its only caller), and the heat's pods reserve their CPU limit instead (scrape/trial.ts ScrapeTrialOptions.reserveCpu).
 */
export const SCRAPE_LEASE_SCOPES = ['host', 'egress'] as const;
export type ScrapeLeaseScope = (typeof SCRAPE_LEASE_SCOPES)[number];

/**
 * The scrape lease's scope: MAKEFUN_SCRAPE_LEASE_SCOPE, `host` when unset or empty. Any other value throws, naming the
 * variable and the two it takes: a scope misspelt is never read as either.
 */
export function scrapeLeaseScopeFromEnv(env: Readonly<Record<string, string | undefined>> = process.env): ScrapeLeaseScope {
  const named = (env[SCRAPE_LEASE_SCOPE_ENV] ?? '').trim();
  if (named === '') return 'host';
  if ((SCRAPE_LEASE_SCOPES as readonly string[]).includes(named)) return named as ScrapeLeaseScope;
  throw new Error(`${SCRAPE_LEASE_SCOPE_ENV} ${JSON.stringify(named)} is not a scrape lease scope: set host (the default: nothing else grades beside a heat) or egress (only heats exclude each other), or leave it unset`);
}

/** The scope a job reads the lease under: its deps' (ScrapeWorkerDeps.leaseScope), else scrapeLeaseScopeFromEnv(), read at each use as the lease directory is. */
export function scrapeLeaseScopeOf(deps: { scrape?: Pick<ScrapeWorkerDeps, 'leaseScope'> }): ScrapeLeaseScope {
  return deps.scrape?.leaseScope ?? scrapeLeaseScopeFromEnv();
}

/**
 * A module a scrape job reads, loaded at its first use by a specifier esbuild does not follow: the kit's one-file
 * command line bundles this module for its rules (cli/grade-local.ts), and must not carry what only the server's
 * scrape jobs run: the admin modules a heat reads (server/routes/admin/grading.ts, sealed-window.ts) and the gateway's
 * bundler (grader/scrape/bundle.ts). The scrape/v1 runtime a kit command does run (grader/scrape/heat.ts, score.ts,
 * trial.ts: cli/regrade.ts, cli/scrape-local.ts) is in the kit through those commands, its self-starting entry modules
 * (grader/scrape/gateway-main.ts, launch.ts) pinned off there (server/kit/cli-bundle.ts); loaded here the same way, so
 * this module's own load reaches none of it. No kit command runs a heat or a scrape job. `rel` is relative to this
 * module.
 */
async function scrapeRuntime<T>(rel: string): Promise<T> {
  return (await import(new URL(rel, import.meta.url).href)) as T;
}

/** The waits' wall clock: a sleep that an abort ends early, rejecting with the signal's reason (heat.ts ScrapeHeatClock). */
const wallClock: ScrapeHeatClock = {
  now: () => Date.now(),
  sleep: (ms, signal) =>
    new Promise<void>((done, fail) => {
      if (signal?.aborted) {
        fail(signal.reason);
        return;
      }
      const stop = (): void => {
        clearTimeout(timer);
        fail(signal!.reason);
      };
      const timer = setTimeout(() => {
        signal?.removeEventListener('abort', stop);
        done();
      }, Math.max(0, ms));
      signal?.addEventListener('abort', stop, { once: true });
    }),
};

/**
 * Who holds this host's scrape lease live (heat.ts scrapeHostLeaseHolder: a scrape_heat_lease row of the database the
 * egress's pods share, or this process's own take when it was handed none), in a log's words, or null when no heat holds
 * it, whatever the lease's scope: what a heat queued behind another reads (scrapeEgressQuiet). A database that cannot
 * answer throws.
 */
async function scrapeLeaseHeldBy(deps: { db?: ScrapeLeaseDb; scrape?: Pick<ScrapeWorkerDeps, 'leaseDir'> }): Promise<string | null> {
  const { scrapeHostLeaseHolder } = await scrapeRuntime<typeof import('./scrape/heat.ts')>('./scrape/heat.ts');
  const dir = deps.scrape?.leaseDir ?? scrapeLeaseDirFromEnv();
  const held = await scrapeHostLeaseHolder({ dir, db: deps.db });
  if (held === null) return null;
  const who = held.info === null ? 'a lease that does not read' : `heat ${held.info.heat} (pid ${held.info.pid} on ${held.info.hostname}, since ${held.info.acquired_at})`;
  return `${who} holds this host's scrape lease (${dir})`;
}

/**
 * Who holds this host's scrape lease live, as scrapeLeaseHeldBy says, under the `host` scope (scrapeLeaseScopeOf), or
 * null when no heat holds it: what a job that would run beside a heat reads (the header's `scrape/v1`). Under the
 * `egress` scope a heat keeps only other heats off the host, so it is null without a read: nothing that is not a heat
 * waits on one. A database that cannot answer throws.
 */
export async function scrapeHostHeldBy(deps: { db?: ScrapeLeaseDb; scrape?: Pick<ScrapeWorkerDeps, 'leaseDir' | 'leaseScope'> }): Promise<string | null> {
  if (scrapeLeaseScopeOf(deps) === 'egress') return null;
  return scrapeLeaseHeldBy(deps);
}

/** Poll `read` until it names no holder: the waits of scrapeHostQuiet and scrapeEgressQuiet. `why` closes the one log line. */
async function scrapeLeaseWait(deps: Pick<GradeWorkerDeps, 'scrape' | 'log'>, read: () => Promise<string | null>, what: string, why: string, signal?: AbortSignal): Promise<number> {
  const clock = deps.scrape?.clock ?? wallClock;
  const poll = deps.scrape?.leasePollMs ?? SCRAPE_LEASE_POLL_MS;
  const log = deps.log ?? ((line: string) => console.log(line));
  const from = clock.now();
  let told = false;
  for (;;) {
    signal?.throwIfAborted();
    const held = await read();
    if (held === null) return clock.now() - from;
    if (!told) {
      log(`[scrape] ${what} waits: ${held}, and ${why}`);
      told = true;
    }
    await clock.sleep(poll, signal);
  }
}

/**
 * Wait while a live scrape heat holds this host's lease (scrapeHostHeldBy): under the `host` scope no other grading
 * runs beside a heat (the header's `scrape/v1`); under `egress` it resolves at once, nothing read. `what` names the
 * waiting job in the log. `signal` (the job attempt's: JobContext.signal) ends the wait, rejecting with its reason, once
 * pg-boss gives the attempt up (its expiry, or the workers stopping), so a job waiting on a heat never holds a stopping
 * process. Resolves with how long it waited, ms.
 */
export async function scrapeHostQuiet(deps: Pick<GradeWorkerDeps, 'scrape' | 'log'> & { db?: ScrapeLeaseDb }, what: string, signal?: AbortSignal): Promise<number> {
  return scrapeLeaseWait(deps, () => scrapeHostHeldBy(deps), what, 'nothing else grades here while a heat runs', signal);
}

/**
 * Wait while a live scrape heat holds this egress's lease (scrapeLeaseHeldBy), under either scope: what a heat queued
 * behind another waits on before it takes the lease (runScrapeHeatFor), one heat at a time on the egress, practice or
 * final. Its log line is scrapeHostQuiet's under `host`, where a heat waits as every other job does. `signal` as
 * scrapeHostQuiet's. Resolves with how long it waited, ms.
 */
export async function scrapeEgressQuiet(deps: Pick<GradeWorkerDeps, 'scrape' | 'log'> & { db?: ScrapeLeaseDb }, what: string, signal?: AbortSignal): Promise<number> {
  const why = scrapeLeaseScopeOf(deps) === 'egress' ? 'one heat at a time runs on this egress' : 'nothing else grades here while a heat runs';
  return scrapeLeaseWait(deps, () => scrapeLeaseHeldBy(deps), what, why, signal);
}

/**
 * How often a final heat held for its entries' snapshots looks again (scrapeFieldSnapshotted): a snapshot job retries
 * 15, 30 and 60 s on (server/jobs.ts JOB_OPTIONS.snapshot), so a snapshot that lands is in the field within this.
 */
export const SCRAPE_SNAPSHOT_POLL_MS = 15_000;

/**
 * Hold a final heat until no entry of `comp` taken in by the deadline (nor a house baseline) awaits its snapshot or its
 * transcripts gate (admin/grading.ts awaitingSnapshot, handed in as `awaiting`: the predicate codeHeatDue waits on, so
 * an entry whose snapshot failed for good, failed or cancelled, holds nothing): the heat reads its field once
 * (entriesToGrade, which lists only entries with a snapshot), and an entry it ran without is never measured. Looks
 * again every SCRAPE_SNAPSHOT_POLL_MS on the waits' clock, logging the entries waited on whenever they change. `signal`
 * (the job attempt's) ends the wait, rejecting with its reason, so pg-boss retries the job: the same job id, so the
 * same heat id and round. Resolves with how long it waited, ms.
 */
async function scrapeFieldSnapshotted(
  deps: Pick<GradeWorkerDeps, 'db' | 'scrape' | 'log'>,
  comp: Pick<typeof competition.$inferSelect, 'id' | 'slug' | 'deadline' | 'bundle'>,
  awaiting: (typeof import('../server/routes/admin/grading.ts'))['awaitingSnapshot'],
  what: string,
  signal?: AbortSignal,
): Promise<number> {
  const clock = deps.scrape?.clock ?? wallClock;
  const log = deps.log ?? ((line: string) => console.log(line));
  const from = clock.now();
  let told: string | null = null;
  for (;;) {
    signal?.throwIfAborted();
    const ids = await awaiting(deps.db, comp);
    if (ids.length === 0) {
      const waited = clock.now() - from;
      if (told !== null) log(`[scrape] ${what}: no entry of ${comp.slug} taken in by the deadline awaits its snapshot any more; its field is read after ${Math.round(waited / 1000)} s`);
      return waited;
    }
    const named = ids.length <= 5 ? ids.join(', ') : `${ids.slice(0, 5).join(', ')} and ${ids.length - 5} more`;
    if (named !== told) {
      log(
        `[scrape] ${what} waits: ${ids.length === 1 ? '1 entry' : `${ids.length} entries`} of ${comp.slug} taken in by the deadline ${ids.length === 1 ? 'awaits its snapshot or its' : 'await their snapshot or their'} transcripts gate (${named}); it looks again every ${SCRAPE_SNAPSHOT_POLL_MS / 1000} s`,
      );
      told = named;
    }
    await clock.sleep(SCRAPE_SNAPSHOT_POLL_MS, signal);
  }
}

/** How often a grade-trial or hindsight-audit job that a scrape heat holds back looks again (the header's `scrape/v1`): it hands itself on to the next slot of this length. */
export const SCRAPE_HOST_RECHECK_MS = 60_000;

/** The recheck slot a job held back by a heat at `atMs` hands itself on to (SCRAPE_HOST_RECHECK_MS): it starts at slot x SCRAPE_HOST_RECHECK_MS. */
export function scrapeHostRecheckSlot(atMs: number): number {
  return Math.ceil((atMs + SCRAPE_HOST_RECHECK_MS) / SCRAPE_HOST_RECHECK_MS);
}

/** How often a grade-trial job the node had no room for looks again (the header's `node room`): it hands itself on to the next slot of this length. */
export const NODE_ROOM_RECHECK_MS = 60_000;

/** The recheck slot a trial the node had no room for at `atMs` hands itself on to (NODE_ROOM_RECHECK_MS): it starts at slot x NODE_ROOM_RECHECK_MS. */
export function nodeRoomRecheckSlot(atMs: number): number {
  return Math.ceil((atMs + NODE_ROOM_RECHECK_MS) / NODE_ROOM_RECHECK_MS);
}

/** The drand chain a heat draws on: quicknet, or under dev auth the test chain (instanceChainOptions, as instance draws read it). */
function scrapeDrandChain(deps: Pick<GradeWorkerDeps, 'drandChain'>): DrandChain {
  return instanceChainOptions(deps.drandChain).testChain ?? DRAND_QUICKNET;
}

/** The newest round `chain` has emitted at or before `atMs` (a practice heat's round). RangeError before its genesis. */
export function latestDrandRound(chain: DrandChain, atMs: number): number {
  const first = roundMin(new Date(atMs), chain);
  const round = roundTime(first, chain).getTime() <= atMs ? first : first - 1;
  if (round < 1) throw new RangeError(`drand chain ${chain.hash} emits its first round after ${new Date(atMs).toISOString()}`);
  return round;
}

/** A heat's drand round, its signature fetched (ScrapeWorkerDeps.drandRound) and verified against the chain's key. */
async function verifiedDrandRound(deps: Pick<GradeWorkerDeps, 'scrape'>, chain: DrandChain, round: number): Promise<{ chain: string; round: number; signature: string }> {
  const fetchRound = deps.scrape?.drandRound ?? (async (c: DrandChain, r: number) => (await scrapeRuntime<typeof import('../server/routes/admin/sealed-window.ts')>('../server/routes/admin/sealed-window.ts')).fetchDrandRound(c, r));
  const { signature } = await fetchRound(chain, round);
  // The BLS check off the event loop (fetch.ts verifyDrandRoundOffLoop; the pool's OffThreadError rejects, the job retries).
  if (!(await verifyDrandRoundOffLoop(chain, round, signature))) throw new Error(`the signature served for drand round ${round} of chain ${chain.hash} does not verify against the chain's key: no heat draws on it`);
  return { chain: chain.hash, round, signature };
}

/**
 * The first round `chain` emits at or after the final phase's start (instance.ts scoredBeacon, as a scored instance
 * draw takes it), and when: the final heat's round and the earliest the heat may draw on it.
 */
export function scrapeFinalRound(finalStartsAt: Date, chain: DrandChain): { round: number; at: Date } {
  const round = scoredBeacon(finalStartsAt, chain).round;
  return { round, at: roundTime(round, chain) };
}

/** A UUID (version 8) shaped from the sha256 of `text` (server/jobs.ts's job ids' shape). */
function sha256Uuid(text: string): string {
  const h = createHash('sha256').update(text).digest('hex').split('');
  h[12] = '8';
  h[16] = ((parseInt(h[16]!, 16) & 0x3) | 0x8).toString(16);
  const s = h.join('');
  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20, 32)}`;
}

/**
 * The scrape-heat job's payload: the final phase whose one heat it runs, as server/jobs.ts's queue takes it (its
 * `node_room` hand-back count, and `one_pod`: the heat runs on the `pod` layout, the header's `layout`), one schema.
 */
export const ScrapeHeatJob = ServerScrapeHeatJob;
export type ScrapeHeatJobT = z.infer<typeof ScrapeHeatJob>;

/** The scrape-heat job's id: one per final phase, so the phase's heat is sent once however often it is asked for. */
export function scrapeHeatJobId(phaseId: string): string {
  return sha256Uuid(`scrape-heat\0${phaseId.toLowerCase()}`);
}

/**
 * A heat's id (contracts/scrape.ts ScrapeHeatId): `practice-` or `final-` and 31 or 34 hex of sha256 of what it is for
 * (the grade job's id, or the phase's and the heat job's), so a retried job's heat reuses its trials' owners and reaps
 * what a dead attempt left running (trial.ts scrapeTrialOwner).
 */
export function scrapeHeatIdOf(purpose: 'practice' | 'final', key: string): string {
  const prefix = purpose === 'practice' ? SCRAPE_PRACTICE_HEAT_PREFIX : SCRAPE_FINAL_HEAT_PREFIX;
  return `${prefix}${createHash('sha256').update(key).digest('hex').slice(0, 40 - prefix.length)}`;
}

/** A submission's receipt time (ms), +infinity with none: a heat lists its entries in receipt order. */
function receiptMs(sub: Pick<typeof submission.$inferSelect, 'receipt'>): number {
  const t = (sub.receipt as { server_time?: unknown } | null)?.server_time;
  const ms = typeof t === 'string' ? Date.parse(t) : Number.NaN;
  return Number.isNaN(ms) ? Number.POSITIVE_INFINITY : ms;
}

function byReceipt(a: Pick<typeof submission.$inferSelect, 'id' | 'receipt' | 'createdAt'>, b: Pick<typeof submission.$inferSelect, 'id' | 'receipt' | 'createdAt'>): number {
  return receiptMs(a) - receiptMs(b) || a.createdAt.getTime() - b.createdAt.getTime() || compareCodeUnits(a.id, b.id);
}

/** The competition's house baseline: its latest baseline submission with a snapshot, not cancelled; null when it has none. */
async function scrapeBaselineOf(db: Db, competitionId: string): Promise<typeof submission.$inferSelect | null> {
  const rows = await db
    .select()
    .from(submission)
    .where(and(eq(submission.competitionId, competitionId), eq(submission.baseline, true), ne(submission.status, 'cancelled'), isNotNull(submission.snapshotSha256)));
  return rows.sort(byReceipt).at(-1) ?? null;
}

/**
 * The voids a heat holds for an admin's review before prizes (the header's `scrape/v1`): per timed stage, a run whose
 * voided and re-run trials there number more than twice the stage field's median plus 2 (the main stage's field every
 * entry, the playoff's its finalists). Only attempts of outcome 'void' count: a judged void (grader/scrape/heat.ts: a
 * trial voided at its judging, a short chart the upstream served, its outcome 'run' with judged_void set) is never
 * counted, since such voids hit every entrant in their window, though it re-ran and the run's voids_rerun counts it.
 * Never a penalty: the run is scored as any. Entry id -> what to say.
 */
export function scrapeVoidsReview(heat: Pick<ScrapeHeatT, 'entries' | 'playoff'>, attempts: readonly Pick<ScrapeHeatAttempt, 'stage' | 'entry' | 'outcome'>[]): Map<string, string> {
  const out = new Map<string, string>();
  for (const [stage, field] of [['main', heat.entries], ['playoff', heat.playoff]] as const) {
    if (field.length === 0) continue;
    const voids = new Map(field.map((id) => [id, 0]));
    for (const a of attempts) if (a.stage === stage && a.outcome === 'void' && voids.has(a.entry)) voids.set(a.entry, voids.get(a.entry)! + 1);
    const sorted = [...voids.values()].sort((x, y) => x - y);
    const mid = sorted.length >> 1;
    // Twice the median, a whole number: the two middle counts summed on an even field.
    const twice = sorted.length % 2 === 1 ? 2 * sorted[mid]! : sorted[mid - 1]! + sorted[mid]!;
    for (const id of field) {
      const n = voids.get(id)!;
      if (n <= twice + 2) continue;
      const said = `${n} of its ${stage} trials voided and re-ran, more than twice the field's median (${twice / 2}) plus 2`;
      out.set(id, out.has(id) ? `${out.get(id)!}; ${said}` : said);
    }
  }
  return out;
}

/** A heat's log (regrade.ts SCRAPE_HEAT_LOG_FORMAT, record.ts recordScrapeRuns): what its runs' stderr_sha256 names. */
export function scrapeHeatLog(o: { purpose: 'practice' | 'final'; heatSha256: string; result: ScrapeHeatResult }): Record<string, unknown> {
  const r = o.result;
  return {
    format: SCRAPE_HEAT_LOG_FORMAT,
    heat_sha256: o.heatSha256,
    heat: r.heat.id,
    purpose: o.purpose,
    reference: { ...r.reference },
    ca_sha256: r.ca_sha256,
    started_at: r.started_at,
    ended_at: r.ended_at,
    attempts: r.attempts.map((a) => ({ ...a })),
    runs: r.runs.map((run) => ({
      entry: run.entry,
      finalist: run.finalist,
      voids_rerun: run.voids_rerun,
      scorer_faults: run.scorer_faults.map((f) => ({ ...f })),
      trials_sha256: run.trials === null ? null : canonicalSha256(run.trials),
      // Unscored: its trials as the heat ran them, unjudged, for an L1 re-judging once the scorer is mended.
      unjudged: run.trials === null ? run.runs.map((t) => ({ ...t })) : [],
    })),
  };
}

/** What a scrape/v1 grade job reads (createGradeHandler: `agent/v1`'s AgentRunStart, with the authorship loader). */
interface ScrapeGradeStart {
  deps: GradeWorkerDeps;
  ctx: GradeJobContext | undefined;
  sub: typeof submission.$inferSelect;
  ph: typeof phase.$inferSelect;
  /** The competition: its id, its slug and its row's created_at (what sandboxLayoutOf reads, the header's `layout`). */
  comp: { id: string; slug: string; createdAt: Date };
  bundle: CompetitionBundleT;
  harness: ScrapeHarnessT;
  index: SnapshotIndex;
  competitionKey: string;
  loadAuthorship: NonNullable<GradeWorkerDeps['loadAuthorship']>;
}

/** One entrant of a heat: its submission, its snapshot's runtime, and (once materialized) its /bot. */
interface ScrapeEntrant {
  sub: typeof submission.$inferSelect;
  index: SnapshotIndex;
  runtime: Runtime;
}

/** A heat to run and record (runScrapeHeatFor). */
interface ScrapeHeatTask {
  deps: GradeWorkerDeps;
  purpose: 'practice' | 'final';
  heatId: string;
  comp: { id: string; slug: string };
  ph: typeof phase.$inferSelect;
  bundle: CompetitionBundleT;
  harness: ScrapeHarnessT;
  competitionKey: string;
  loadAuthorship: NonNullable<GradeWorkerDeps['loadAuthorship']>;
  /** Every entrant in receipt order: the house baseline among them, but in a staged heat's practice heat (the entry alone). */
  entrants: readonly ScrapeEntrant[];
  /** The house baseline: the reference read's reader, materialized apart when it is no entrant. */
  baseline: ScrapeEntrant;
  /** The entrants whose runs are recorded (a practice heat's: its entry's alone). */
  recorded: ReadonlySet<string>;
  drand: { chain: string; round: number; signature: string };
  /** The job's owner (regradeOwner of its id): its scratch is named for it, and a dead attempt's removed first. */
  owner: string | null;
  what: string;
  /** The job attempt's signal (JobContext.signal): once pg-boss gives the attempt up, the wait for the lease ends and the heat stops (heat.ts `Abort`). */
  signal?: AbortSignal;
  /** The layout its trials run on (the header's `layout`; absent `split`): on `pod` each trial one pod, its gateway a lane of this process's lanes pod, and every run it records flagged ONE_POD_FLAG. */
  layout?: SandboxLayout;
}

/** A heat's recorded runs (runScrapeHeatFor). */
interface ScrapeHeatRecorded {
  heat: ScrapeHeatT;
  heatSha256: string;
  logSha256: string;
  /** Each recorded run: unscored (its scorer faulted: never published), and held for review (why) or not. */
  runs: Array<{ submissionId: string; runId: string; unscored: boolean; held: string | null }>;
}

/** The node22 or python3.13 house's launcher text, as trial.ts runs it for `runtime`. */
async function launcherTextOf(deps: GradeWorkerDeps, runtime: Runtime): Promise<string> {
  const launch = await scrapeRuntime<typeof import('./scrape/launch.ts')>('./scrape/launch.ts');
  if (runtime === 'python3.13') return launch.PYTHON_LAUNCHER_SOURCE;
  return deps.scrape?.launcherSource ?? launch.launcherSource();
}

/**
 * Run one heat and record its runs (the header's `scrape/v1`): the entrants' snapshots materialized in the job's
 * scratch, every image the trials need present, each entrant's env-lane entry secrets opened (the header's `entry
 * secrets`: a house entry's none, its account's never read), the heat run under the host's lease (a lease held by
 * another heat is waited out: the heat is queued behind it), then the heat record and its log stored, and each recorded
 * entrant's run written (record.ts recordScrapeRuns), its score built as every run's, with the secret rows it ran with
 * and the forms its outputs held (ScrapeRunRecord's RunSecrets: one SECRET_IN_OUTPUT_ACTION row a leaking run), in one
 * transaction. The scratch is removed however it ends.
 */
async function runScrapeHeatFor(t: ScrapeHeatTask): Promise<ScrapeHeatRecorded> {
  const { deps } = t;
  const { db, blobs } = deps;
  const log = deps.log ?? ((line: string) => console.log(line));
  const compDir = competitionDirOf(deps, t.comp.slug, t.harness);
  const { runScrapeHeat, ScrapeLeaseBusyError } = await scrapeRuntime<typeof import('./scrape/heat.ts')>('./scrape/heat.ts');
  const leaseDir = deps.scrape?.leaseDir ?? scrapeLeaseDirFromEnv();
  // Under the `egress` scope other grading runs beside the heat, so its pods reserve their CPU limit (the header's `scrape/v1`).
  const reserveCpu = scrapeLeaseScopeOf(deps) === 'egress';
  const plan0 = scrapePlan({ harness: t.harness, seed: '0', datasetSha256: null });
  // The reference read's reader: an entrant's snapshot, or (the baseline in no entrant's place: a staged heat's practice
  // heat) its own, materialized beside them under its own name.
  const referenceApart = !t.entrants.some((e) => e.sub.id === t.baseline.sub.id);
  // Every image a trial runs: each entrant's runtime and the reference read's, the gateway's and the launcher's node22, the scorer's.
  for (const runtime of new Set([...t.entrants.map((e) => e.runtime), t.baseline.runtime])) await preflight(plan0, deps.sandbox, runtime, null);
  await deps.sandbox.preflight('node22');
  // The scorer as the sandbox mounts it, before anything of the heat is made: on the k8s sandbox its stage on the data claim (the header's `k8s data`).
  const scoringSetup = await scrapeScorerSetupFor(deps.sandbox, t.comp.slug, { compDir, harness: t.harness });
  // On `pod` (the header's `layout`): the one-pod view for the trials and their scratch, and this process's lanes pod
  // open before anything of the heat is made (no room for it is the node's: thrown on, the job handed back); the scorer
  // stays a pod of its own on the grader's sandbox. A process that cannot host it refuses the heat as the platform's fault.
  const layout: SandboxLayout = t.layout ?? 'split';
  let sandbox: Sandbox = deps.sandbox;
  let lanes: OnePodLanes | null = null;
  if (layout === 'pod') {
    const host = onePodHostOf(deps.onePod, `${t.comp.slug}: ${t.what}`);
    lanes = await openOnePodLanes(host);
    sandbox = host.view();
  }
  // Each entrant's env-lane entry secrets, opened before anything of the heat is made (the header's `entry secrets`): its
  // every trial runs with its own. One this grader cannot open is an Error naming the rows (its job tries again): no
  // entrant runs without its own. A house entry (housePaysEntryLane: the house baseline among them) runs with none, as
  // an agent/v1 pass does: its account's secrets are never read or opened.
  const sealOf = entrySecretSealOf(deps);
  const secretsOf = new Map<string, EnvSecrets>();
  for (const e of t.entrants) {
    const secrets = housePaysEntryLane(e.sub) ? noEnvSecrets() : await activeEnvSecrets(db, sealOf, { userId: e.sub.userId, competitionId: t.comp.id }, `${t.comp.slug}: submission ${e.sub.id}'s trials in ${t.what}`);
    secretsOf.set(e.sub.id, secrets);
  }

  if (t.owner !== null) {
    const line = scratchReapLine(t.what, 'its heat', await reapGradeScratch(sandbox, deps.workRoot, t.owner));
    if (line !== null) log(line);
  }
  const work = t.owner === null ? await mkdtemp(join(deps.workRoot, EXEC_SCRATCH_PREFIX)) : await ownedScratch(deps.workRoot, EXEC_SCRATCH_PREFIX, t.owner);
  // Held as an owned one is (grade.ts holdScratch, its header's Releasing): its removal below, once the heat's runs are
  // recorded (or it threw), releases it from the sandbox's daemon in one go, every trial's and scorer's scratch with it.
  if (t.owner === null) holdScratch(work);
  try {
    const dirOf = new Map<string, string>();
    for (const e of t.entrants) {
      const dir = join(work, `bot-${e.sub.id}`);
      await materializeSnapshot(e.index, blobs, dir);
      dirOf.set(e.sub.id, dir);
    }
    const referenceDir = referenceApart ? join(work, `reference-${t.baseline.sub.id}`) : dirOf.get(t.baseline.sub.id)!;
    if (referenceApart) await materializeSnapshot(t.baseline.index, blobs, referenceDir);
    const heatDir = join(work, 'heat');
    await mkdir(heatDir, { mode: 0o700 });
    const gateway = await (deps.scrape?.gateway ?? (async () => (await scrapeRuntime<typeof import('./scrape/bundle.ts')>('./scrape/bundle.ts')).scrapeGatewayBundle({ cacheDir: join(deps.workRoot, 'scrape-gateway') })))();
    const nodeLauncher = await launcherTextOf(deps, 'node22');
    const harness = t.purpose === 'practice' ? { network: t.harness.network, heat: { ...t.harness.heat, playoff: { places: 0, rounds: 0 } } } : { network: t.harness.network, heat: t.harness.heat };
    // Every trial's options as the bundle's tests set them, and on `pod` the lane host and the door besides (trial.ts
    // ScrapeTrialOptions.hosted and .door, which the heat hands every trial with the rest).
    const trial = lanes === null ? deps.scrape?.trial : { ...deps.scrape?.trial, hosted: lanes.hosted, door: lanes.door };
    const options: ScrapeHeatOptions = {
      id: t.heatId,
      entries: t.entrants.map((e) => {
        const secrets = secretsOf.get(e.sub.id)!;
        return { id: e.sub.id, dir: dirOf.get(e.sub.id)!, runtime: e.runtime, ...(secrets.ids.length === 0 ? {} : { secrets: secrets.env }) };
      }),
      harness,
      drand: t.drand,
      reference: { dir: referenceDir, runtime: t.baseline.runtime },
      sandbox,
      limits: t.bundle.limits,
      gateway: { dir: gateway.dir, script: gateway.script },
      launcherSource: nodeLauncher,
      workDir: heatDir,
      blobs,
      scoring: { setup: scoringSetup, ...(layout === 'pod' ? { sandbox: deps.sandbox } : {}) },
      lease: { dir: leaseDir, db },
      ...(reserveCpu ? { reserveCpu: true } : {}),
      ...(deps.scrape?.pacing === undefined ? {} : { pacing: deps.scrape.pacing }),
      ...(trial === undefined ? {} : { trial }),
      ...(deps.scrape?.onEvent === undefined ? {} : { onEvent: deps.scrape.onEvent }),
      ...(deps.scrape?.heat === undefined ? {} : { deps: deps.scrape.heat }),
      ...(t.signal === undefined ? {} : { signal: t.signal }),
    };
    // Queued behind any heat running on this egress, under either scope: its lease waited out, and taken again if another heat took it first.
    let result: ScrapeHeatResult;
    for (;;) {
      await scrapeEgressQuiet(deps, t.what, t.signal);
      try {
        result = await runScrapeHeat(options);
        break;
      } catch (err) {
        if (err instanceof ScrapeLeaseBusyError) continue;
        throw err;
      }
    }

    // The heat record (every run's dataset_sha256, served by the archive) and its log (every run's stderr_sha256).
    const heatJson = canonicalJson(result.heat);
    const heatSha256 = (await blobs.put(heatJson)).sha256;
    const logJson = canonicalJson(scrapeHeatLog({ purpose: t.purpose, heatSha256, result }));
    const logSha256 = (await blobs.put(logJson)).sha256;
    const gatewaySha256 = sha256Hex(await readFile(join(gateway.dir, gateway.script)));
    const review = scrapeVoidsReview(result.heat, result.attempts);
    const startedAt = new Date(result.started_at);
    const finishedAt = new Date(result.ended_at);
    /**
     * Each recorded run, with its entry secrets (the header's `entry secrets`, ScrapeRunRecord's RunSecrets): the rows its
     * trials ran with, the forms its error is masked of, and where its outputs held one, which recordScrapeRuns flags
     * secret_in_output with the run's one SECRET_IN_OUTPUT_ACTION row.
     */
    const records: ScrapeRunRecord[] = [];
    for (const e of t.entrants) {
      if (!t.recorded.has(e.sub.id)) continue;
      const r = result.runs.find((x) => x.entry === e.sub.id);
      if (r === undefined) throw new Error(`heat ${t.heatId} returned no run of entry ${e.sub.id}`);
      const secrets = secretsOf.get(e.sub.id)!;
      const forms = entrySecretForms(secrets.env);
      // Redacted here as well as in the record: the admins' page below quotes a left-unscored run's error.
      const redacted = (text: string): string => redactSecrets(text, forms);
      // Its trials' /output as the heat scanned it, every attempt's (heat.ts ScrapeHeatRun.secret_hits), never masked.
      const hits: SecretHit[] = r.secret_hits.map((h) => ({ name: h.name, file: h.file }));
      const seed = phaseSeed(t.competitionKey, t.ph.key, heatSha256);
      const plan = scrapePlan({ harness: t.harness, seed, datasetSha256: heatSha256 });
      const launcherSha256 = sha256Hex(await launcherTextOf(deps, e.runtime));
      const listedNs = (r.trials?.trials ?? r.runs).reduce((s, x) => s + x.wall_ns, 0);
      const base = {
        submissionId: e.sub.id,
        phaseId: t.ph.id,
        exec_count: result.attempts.filter((a) => a.entry === e.sub.id).length,
        wall_ms: Math.round(listedNs / 1e6),
        image_digest: deps.sandbox.imageDigest(e.runtime),
        harness_version: scrapeHarnessVersion(launcherSha256, gatewaySha256),
        scorer_version: scorerVersionOf(plan, deps.sandbox),
        dataset_sha256: heatSha256,
        heat_log_sha256: logSha256,
        seed,
        started_at: startedAt,
        finished_at: finishedAt,
      };
      if (r.trials === null || r.performance === null) {
        const f = r.scorer_faults[0];
        const fault = f === undefined ? 'a fault' : `${f.name} on its ${f.stage} round ${f.round}: ${f.message}`;
        if (hits.length > 0) log(secretHitsLine(`${t.comp.slug}: submission ${e.sub.id}'s run in ${t.what}`, hits));
        records.push({
          ...base,
          status: 'failed',
          error: redacted(`left unscored: the competition's scorer could not judge it (${fault}). That is the house's fault, never the entry's: nothing is published, and its trials are kept unjudged in heat ${t.heatId}'s log (${logSha256})`),
          action_log_json: null,
          action_log_sha256: null,
          result: null,
          result_sha256: null,
          flags: layoutFlags([SCRAPE_SCORER_FAULT_FLAG], layout),
          entry_secret_ids: secrets.ids,
          mask: forms,
          secret_hits: hits,
        });
        continue;
      }
      const actionLog = canonicalJson(r.trials);
      const actionLogSha256 = sha256Hex(actionLog);
      // Its action log (the trials manifest, which names its outputs' paths) scanned as a one-execution run's is (secretHitsOfRun).
      hits.push(...(await secretHitsOfRun(blobs, 'scrape/v1', { json: actionLog, sha256: actionLogSha256 }, secrets.env)));
      if (hits.length > 0) log(secretHitsLine(`${t.comp.slug}: submission ${e.sub.id}'s run in ${t.what}`, hits));
      const { cost, pricingRev } = await entryCostFor(deps, { sub: e.sub, bundle: t.bundle, fresh: true, ...(t.signal === undefined ? {} : { signal: t.signal }) });
      const authorship = await t.loadAuthorship(e.sub.id, pricingRev);
      const score = buildScore(
        {
          harness: { kind: 'scrape/v1', version: base.harness_version },
          image_digest: base.image_digest,
          dataset_sha256: heatSha256,
          seed,
          // Scored: its scorer agreed with itself on every listed trial (a disagreement leaves a run unscored, above).
          deterministic: true,
          execution_flags: [],
          house: standingsHouse(e.sub),
          baseline: e.sub.baseline,
        },
        { action_log_sha256: actionLogSha256, performance: r.performance, performance_flags: [], cost, authorship },
        eligibilityRulesOf(t.bundle),
        base.scorer_version,
      );
      const held = review.get(e.sub.id);
      records.push({
        ...base,
        status: 'finished',
        error: held === undefined ? null : `held for an admin's review before prizes, never a penalty: ${held}; heat ${t.heatId}'s log (${logSha256}) lists every attempt`,
        action_log_json: actionLog,
        action_log_sha256: actionLogSha256,
        result: score,
        result_sha256: scoreDigest(score).sha256,
        // secret_in_output (recordScrapeRuns's, from its hits) beside the hold, on the run row alone, never in its score
        // (regrade.ts RUN_ONLY_FLAGS).
        // ONE_POD_FLAG on `pod` alike (the header's `layout`).
        flags: layoutFlags(held === undefined ? [] : [SCRAPE_VOIDS_REVIEW_FLAG], layout),
        entry_secret_ids: secrets.ids,
        mask: forms,
        secret_hits: hits,
      });
    }
    // One transaction (recordScrapeRuns's): the runs, the rows each ran with (run.entry_secret_ids) and each leaking
    // run's one SECRET_IN_OUTPUT_ACTION row (the header's `entry secrets`).
    const ids = await recordScrapeRuns(db, blobs, records);
    // The final's grades landed at once: the live board's count moves (finalGradeLanded).
    if (t.ph.key === 'final') await finalGradeLanded(db, t.comp.id, log);
    const runs = records.map((r, i) => ({ submissionId: r.submissionId, runId: ids[i]!, unscored: r.status === 'failed', held: r.flags.includes(SCRAPE_VOIDS_REVIEW_FLAG) ? r.error : null }));
    // The heat's one line in the grader's log: what an operator reads a heat recorded by.
    log(
      `[scrape] ${t.what}: heat ${t.heatId} recorded on the ${deps.sandbox.kind} sandbox, ${result.attempts.length} attempts from ${result.started_at} to ${result.ended_at} (record ${heatSha256}): ` +
        runs.map((r) => `entry ${r.submissionId}'s run ${r.runId} ${r.unscored ? 'left unscored' : r.held === null ? 'scored' : 'scored, held for review'}`).join('; '),
    );
    // A run its scorer left unscored is the house's to mend: paged, never published.
    const page = deps.page ?? ((line: string) => console.error(line));
    for (const [i, r] of records.entries()) {
      if (r.status !== 'failed') continue;
      page(
        `[scrape] ALERT: ${t.comp.slug}'s ${t.ph.key} phase: entry ${r.submissionId}'s run ${ids[i]} in heat ${t.heatId} ${r.error!.slice('left '.length)}. ` +
          `Mend the scorer (competitions/${t.comp.slug}), then judge the run again from the heat's records: POST /api/admin/runs/${ids[i]}/rejudge {"reason": "<what was mended>"} (server/routes/admin/scrape-holds.ts)`,
      );
    }
    return { heat: result.heat, heatSha256, logSha256, runs };
  } finally {
    for (const e of t.entrants) await removeMaterialized(join(work, `bot-${e.sub.id}`)).catch(() => undefined);
    if (referenceApart) await removeMaterialized(join(work, `reference-${t.baseline.sub.id}`)).catch(() => undefined);
    await removeScratch(sandbox, work);
  }
}

/** A scrape/v1 run's harness_version: the harness source's (version.ts harnessVersion), and the digests of the launcher and the gateway its trials ran. */
export function scrapeHarnessVersion(launcherSha256: string, gatewaySha256: string): string {
  return `${harnessVersion()} launcher@${launcherSha256} gateway@${gatewaySha256}`;
}

/** An entrant from its submission: its snapshot index and the runtime it selects, or why it can run in no heat. */
async function scrapeEntrantOf(deps: GradeWorkerDeps, sub: typeof submission.$inferSelect, harness: ScrapeHarnessT): Promise<ScrapeEntrant | { sub: typeof submission.$inferSelect; error: string }> {
  if (sub.snapshotSha256 === null) return { sub, error: `submission ${sub.id} has no snapshot yet` };
  const index = await readSnapshotIndex(deps.blobs, sub.snapshotSha256);
  const picked = entryRuntime(index, harness.runtimes);
  return 'error' in picked ? { sub, error: picked.error } : { sub, index, runtime: picked.runtime };
}

/**
 * A practice heat's field (the header's `scrape/v1` dev): the entry beside the house baseline, in receipt order; where
 * the bundle stages its heat (contracts/competition.ts stagedHeatOf kind scrape), the entry alone, since the baseline's
 * run beside it was never recorded and the practice heat is the entry's qualifying trial for the cut. The baseline's own
 * grade is the entry alone either way. The baseline stays the reference read's reader (runScrapeHeatFor
 * materializes it apart when it is no entrant).
 */
export function scrapePracticeField<E extends { sub: Pick<typeof submission.$inferSelect, 'id' | 'receipt' | 'createdAt'> }>(bundle: Pick<CompetitionBundleT, 'harness'>, entry: E, baseline: E): E[] {
  if (baseline.sub.id === entry.sub.id || stagedHeatOf(bundle)?.kind === 'scrape') return [entry];
  return [entry, baseline].sort((a, b) => byReceipt(a.sub, b.sub));
}

/**
 * A dev phase's scrape/v1 grade (the header's `scrape/v1`): a practice heat of the entry beside the house baseline (where
 * the heat is staged, the entry alone: scrapePracticeField) over the bundle's warm-up and main rounds, no playoff, its
 * round the newest drand round, queued behind any heat this host runs, the baseline's snapshot the reference read's
 * reader either way. The entry's run is recorded and published; the baseline's run in it is not (its own grade job
 * grades it). An entry that selects no runtime fails at once, nothing run; a competition with no house baseline
 * submitted cannot run one (PermanentJobError).
 */
async function gradeScrapePractice(s: ScrapeGradeStart): Promise<{ run_id: string } | null> {
  const { deps, sub, ph, comp, harness } = s;
  const entrant = await scrapeEntrantOf(deps, sub, harness);
  if ('error' in entrant) {
    const plan = scrapePlan({ harness, seed: phaseSeed(s.competitionKey, ph.key, null), datasetSha256: null });
    return { run_id: await recordGrade(deps.db, deps.blobs, refusedGrade(plan, entrant.error), { submissionId: sub.id, phaseId: ph.id }) };
  }
  let baseline: ScrapeEntrant = entrant;
  if (!sub.baseline) {
    const row = await scrapeBaselineOf(deps.db, comp.id);
    if (row === null) throw new PermanentJobError(`${comp.slug} has no house baseline submitted: a practice heat runs an entry beside it, and its read is the heat's reference. Submit the baseline, then resend this grade`);
    const b = await scrapeEntrantOf(deps, row, harness);
    if ('error' in b) throw new PermanentJobError(`${comp.slug}'s house baseline ${row.id} cannot run in a heat: ${b.error}`);
    baseline = b;
  }
  const chain = scrapeDrandChain(deps);
  const clock = deps.scrape?.clock ?? wallClock;
  const drand = await verifiedDrandRound(deps, chain, latestDrandRound(chain, clock.now() - SCRAPE_DRAND_LAG_MS));
  const jobKey = s.ctx?.id ?? uuidv7();
  const what = `submission ${sub.id}'s practice heat on the ${ph.key} phase (job ${jobKey})`;
  // By the table (the header's `layout`; dormant: `split`, nothing read).
  const layout = layoutOfFresh(deps.onePod, comp, harness.kind, deps.log ?? ((line: string) => console.log(line)), `${comp.slug}: ${what}`);
  const recorded = await runScrapeHeatFor({
    deps,
    purpose: 'practice',
    heatId: scrapeHeatIdOf('practice', jobKey),
    comp,
    ph,
    bundle: s.bundle,
    harness,
    competitionKey: s.competitionKey,
    loadAuthorship: s.loadAuthorship,
    entrants: scrapePracticeField(s.bundle, entrant, baseline),
    baseline,
    recorded: new Set([sub.id]),
    drand,
    owner: s.ctx === undefined ? null : regradeOwner(s.ctx.id),
    what,
    ...(s.ctx?.signal === undefined ? {} : { signal: s.ctx.signal }),
    layout,
  });
  const mine = recorded.runs.find((r) => r.submissionId === sub.id)!;
  return mine.unscored ? null : { run_id: mine.runId };
}

/**
 * A final phase's scrape/v1 grade job (kind grade): the phase's one heat grades every final entry
 * (createScrapeHeatHandler), never this job. Once that heat has recorded the entry's run, the job hands it on to
 * publish (null when its scorer left it unscored); before, it hands on nothing. An entry the recorded heat ran without
 * (on a staged heat, an entry cut on its practice heat among them) can no longer be graded on the phase
 * (PermanentJobError).
 */
async function scrapeFinalGrade(s: ScrapeGradeStart): Promise<{ run_id: string } | null> {
  const { deps, sub, ph } = s;
  const runs = await deps.db
    .select({ id: run.id, submissionId: run.submissionId, status: run.status, flags: run.flags, attempt: run.attempt })
    .from(run)
    .where(and(eq(run.phaseId, ph.id), eq(run.kind, 'grade'), isNotNull(run.datasetSha256)));
  const mine = runs.filter((r) => r.submissionId === sub.id).sort((a, b) => b.attempt - a.attempt)[0];
  if (mine !== undefined) return mine.flags.includes(SCRAPE_SCORER_FAULT_FLAG) ? null : { run_id: mine.id };
  const staged = stagedHeatOf(s.bundle)?.kind === 'scrape';
  if (runs.length > 0) {
    const field = staged
      ? 'a staged scrape/v1 final measures its contenders and the house baseline in that heat (an entry cut on its practice heat runs in none)'
      : 'a scrape/v1 final measures every entry in that heat';
    throw new PermanentJobError(`the final phase of ${s.comp.slug} ran its one heat without submission ${sub.id}: ${field}, and none is measured after it`);
  }
  (deps.log ?? ((line: string) => console.log(line)))(
    `[scrape] submission ${sub.id}'s final grade waits for the phase's one heat (scrape-heat job ${scrapeHeatJobId(ph.id)}), which grades every final entry${staged ? ' the cut sends on' : ''}: this job hands on nothing`,
  );
  return null;
}

/** A scrape/v1 L1 regrade job (the header's `scrape/v1`): the stored grade run judged again from its record (regrade.ts regradeScrapeL1), recorded as a regrade run. */
async function regradeScrapeRun(s: ScrapeGradeStart & { job: JobPayload<'grade-dev'> }): Promise<{ run_id: string }> {
  const { deps, sub, ph, comp, harness, job } = s;
  const { db, blobs } = deps;
  const stored = await loadStoredRun(db, job.reproduces_run_id!);
  if (stored === null) throw new PermanentJobError(`run ${job.reproduces_run_id} does not exist`);
  if (stored.submissionId !== sub.id || stored.phaseId !== ph.id) throw new PermanentJobError(`run ${stored.id} is not a run of submission ${sub.id} in phase ${ph.id}`);
  const [orig] = await db.select({ kind: run.kind }).from(run).where(eq(run.id, stored.id));
  if (orig?.kind !== 'grade') throw new PermanentJobError(`run ${stored.id} is a ${orig?.kind}; regrade the grade run it reproduces`);
  if (stored.seed === null) throw new PermanentJobError(`run ${stored.id} recorded no seed`);
  // The scorer as the sandbox mounts it: on the k8s sandbox its stage on the data claim (the header's `k8s data`).
  const setup = await scrapeScorerSetupFor(deps.sandbox, comp.slug, { compDir: competitionDirOf(deps, comp.slug, harness), harness });
  const plan = scrapePlan({ harness, seed: stored.seed, datasetSha256: stored.dataset_sha256 });
  const { cost, pricingRev } = await entryCostFor(deps, { sub, bundle: s.bundle, fresh: false, stored: stored.result });
  const version = storedAuthorshipVersion(stored.result);
  let authorship: AuthorshipSummaryT | null = null;
  if (version !== null) {
    authorship = await s.loadAuthorship(sub.id, pricingRev, version);
    if (version !== undefined && authorship?.algo_version !== version) {
      throw new PermanentJobError(`run ${stored.id} was graded with authorship algorithm ${version}, and submission ${sub.id} has no summary of it under pricing_rev ${pricingRev}`);
    }
  }
  const jobId = s.ctx?.id ?? uuidv7();
  const log = deps.log ?? ((line: string) => console.log(line));
  const regrading = `run ${stored.id}'s ${job.kind} regrade (job ${jobId})`;
  try {
    const outcome = await regradeScrapeL1({
      stored,
      plan,
      sandbox: deps.sandbox,
      blobs,
      limits: s.bundle.limits,
      workRoot: deps.workRoot,
      cost,
      authorship,
      entry: { house: standingsHouse(sub), baseline: sub.baseline },
      rules: eligibilityRulesOf(s.bundle),
      entryId: sub.id,
      setup,
      trim: harness.heat.trim,
      scoring: await scrapeRuntime<typeof import('./scrape/score.ts')>('./scrape/score.ts'),
      owner: regradeOwner(jobId),
      onScratchReap: (r) => {
        const line = scratchReapLine(regrading, `attempt ${(s.ctx?.retryCount ?? 0) + 1}`, r);
        if (line !== null) log(line);
      },
    });
    // The re-judging runs to its end (a scrape/v1 L1 takes no signal), and an attempt given up meanwhile records nothing.
    s.ctx?.signal?.throwIfAborted();
    return { run_id: await recordRegrade(db, blobs, outcome, { submissionId: sub.id, phaseId: ph.id }) };
  } catch (err) {
    if (err instanceof RegradeError) throw new PermanentJobError(err.message, { cause: err });
    throw err;
  }
}

/**
 * The final heat's runs, as the scrape-heat job hands them on: every run to publish, and the runs left unscored or held for
 * review. A re-judging's job (`rejudge`) answers its re-judging's end in the same shape: no heat ran, nothing unscored or
 * held to page (its re-judging wrote its outcome to the run and its audit rows), and to publish only a run it judged and
 * could not publish itself.
 */
export interface ScrapeHeatOutcome {
  phase_id: string;
  /**
   * The heat (ScrapeHeat.id) and its record's canonical sha256: every run's dataset_sha256. A re-judging's: its run's
   * heat, each empty where the job ended before reading it.
   */
  heat: string;
  heat_sha256: string;
  /** False when the job found the phase's heat already recorded (a retry, or a second send): nothing ran. A re-judging's: whether it judged the run's trials. */
  ran: boolean;
  /** Each run to publish (AggregatedRun's shape, so the pipeline sends each its publish job), in receipt order. */
  publish: AggregatedRun[];
  /** Runs left unscored by the scorer (never published, the admins paged). */
  unscored: Array<{ run_id: string; submission_id: string }>;
  /** Runs published and held for an admin's review before prizes (SCRAPE_VOIDS_REVIEW_FLAG), with why. */
  held: Array<{ run_id: string; submission_id: string; reason: string }>;
  /** A re-judging's job: how its re-judging ended (server/routes/admin/scrape-holds.ts judgeRejudgeJob); absent on a heat's. */
  rejudge?: RejudgeJobEnd;
}

/** The context a scrape-heat job is handed (JobQueue.work's): its signal, once pg-boss gives the attempt up, ends its waits and stops its heat. */
export type ScrapeHeatJobContext = Pick<JobContext, 'id'> & Partial<Pick<JobContext, 'retryCount' | 'retryLimit' | 'signal'>>;

/**
 * The scrape-heat job handler (the header's `scrape/v1`): the final phase's one heat, for every final entry
 * (admin/grading.ts entriesToGrade, as a lock queues them) and the house baseline, its field read once no entry taken in
 * by the deadline awaits its snapshot (scrapeFieldSnapshotted, as codeHeatDue waits). It draws on the first drand round
 * at or after the phase's scheduled start (scrapeFinalRound, waited for when the job runs early), fetched and
 * verified, runs once this host's lease is free, and records one grade run per entry (an entry that selects no
 * runtime: a failed run, nothing run). A phase whose heat is recorded already is not run again: the job answers its
 * runs. Throws PermanentJobError on what no retry mends: no such phase, not a final phase, not scrape/v1, no house
 * baseline among the entries, and a staged heat (contracts/competition.ts stagedHeatOf kind scrape) whose cut the
 * phase does not store as decided (server/grading/heat-cut-field.ts storedHeatCutOf): the final-cut job decides it and
 * sends this heat, so nothing waits for it inside the attempt. Once it is decided, the field is entriesToGrade as ever,
 * which the dev gate has cut to the contenders and the house's entries (server/entries/dev-profit.ts devProfitGate),
 * and the job logs how many were taken in and how many run.
 *
 * The queue's other payload, an admin's re-judging of a run its scorer left unscored (server/jobs.ts ScrapeRejudgeJob),
 * is judged here on this host's own parts, as a heat's trials are: its sandbox (on the cluster the k8s sandbox, which
 * only the worker and grader pods carry), the bundle's sealed scorer as that sandbox mounts it (scrapeScorerSetupFor: on
 * the k8s sandbox its stage on the data claim), the host's scrape lease (ScrapeWorkerDeps.leaseDir, else
 * scrapeLeaseDirFromEnv), the work root and the job's owner (regradeOwner of its id, so a retry reaps what a dead attempt
 * left) by server/routes/admin/scrape-holds.ts judgeRejudgeJob, which writes every outcome to the run and its audit rows
 * and never throws, and hands itself on through `deps.jobs` while a heat holds the lease.
 */
export function createScrapeHeatHandler(deps: GradeWorkerDeps): (data: ScrapeHeatJobT | ScrapeRejudgeJobT, ctx?: ScrapeHeatJobContext) => Promise<ScrapeHeatOutcome> {
  const { db } = deps;
  const loadAuthorship = deps.loadAuthorship ?? ((submissionId: string, pricingRev: string, algoVersion?: number) => loadStoredAuthorship(db, submissionId, pricingRev, algoVersion));
  return async (input, ctx) => {
    if (isScrapeRejudgeJob(input)) return scrapeRejudgeFor(deps, ScrapeRejudgeJob.parse(input), loadAuthorship, ctx);
    const data = ScrapeHeatJob.parse(input);
    const ph = await one(db.select().from(phase).where(eq(phase.id, data.phase_id)), `phase ${data.phase_id}`);
    const comp = await one(db.select().from(competition).where(eq(competition.id, ph.competitionId)), `competition ${ph.competitionId}`);
    if (comp.bundle === null) throw new PermanentJobError(`competition ${comp.slug} has no bundle (a demo row cannot be graded)`);
    let bundle: CompetitionBundleT;
    try {
      bundle = CompetitionBundle.parse(comp.bundle);
    } catch (err) {
      throw new PermanentJobError(`competition ${comp.slug}'s stored bundle does not validate`, { cause: err });
    }
    const harness = bundle.harness;
    if (harness.kind !== 'scrape/v1') throw new PermanentJobError(`${comp.slug} is a ${harness.kind} competition: only a scrape/v1 final phase runs a heat`);
    if (ph.key !== 'final') throw new PermanentJobError(`phase ${ph.key} of ${comp.slug} is not its final phase: a dev phase's entries each run a practice heat of their own`);
    const competitionKey = competitionSeedKey(comp);

    // The phase's heat already recorded: answered, never run again.
    const done = await db
      .select({ id: run.id, submissionId: run.submissionId, status: run.status, flags: run.flags, error: run.error, attempt: run.attempt, datasetSha256: run.datasetSha256 })
      .from(run)
      .where(and(eq(run.phaseId, ph.id), eq(run.kind, 'grade'), isNotNull(run.datasetSha256)));
    if (done.length > 0) {
      const heatSha256 = done.sort((a, b) => b.attempt - a.attempt)[0]!.datasetSha256!;
      const rows = done.filter((r) => r.datasetSha256 === heatSha256);
      const heat = ScrapeHeat.parse(JSON.parse(Buffer.from((await deps.blobs.get(heatSha256, { verify: true })) ?? Buffer.from('null')).toString('utf8')));
      return outcomeOf(ph, heat.id, heatSha256, false, rows.map((r) => ({ submissionId: r.submissionId, runId: r.id, unscored: r.flags.includes(SCRAPE_SCORER_FAULT_FLAG), held: r.flags.includes(SCRAPE_VOIDS_REVIEW_FLAG) ? r.error : null })));
    }

    const { entriesToGrade, entriesBeforeDevGate, awaitingSnapshot } = await scrapeRuntime<typeof import('../server/routes/admin/grading.ts')>('../server/routes/admin/grading.ts');
    const jobKey = ctx?.id ?? uuidv7();
    const what = `the final heat of ${comp.slug} (job ${jobKey})`;
    // A staged heat runs once its cut is decided, never waiting for it inside the attempt: the phase's final-cut job
    // decides it and sends this heat itself (the header's `scrape/v1` final).
    const log = deps.log ?? ((line: string) => console.log(line));
    const staged = stagedHeatOf(bundle);
    const cut = staged === null ? null : (await scrapeRuntime<typeof import('../server/grading/heat-cut-field.ts')>('../server/grading/heat-cut-field.ts')).storedHeatCutOf(ph);
    if (staged !== null && cut === null) {
      const cutJob =
        ph.lockedAt === null
          ? "the final-cut job the phase's lock sends (the final is not locked yet)"
          : `the phase's final-cut job (${finalCutJobId(ph.id, `lock:${ph.lockedAt.toISOString()}`)}, sent at its lock)`;
      throw new PermanentJobError(
        `the final heat of ${comp.slug} is staged (its ${staged.contenders} contenders cut on their practice heats) and its cut is undecided: ` +
          `${cutJob} decides it once every entry's practice heat is in, then sends this heat (scrape-heat job ${scrapeHeatJobId(ph.id)}); this job runs nothing`,
      );
    }
    // Its field is read once: held first while an entry taken in by the deadline awaits its snapshot (the header's `scrape/v1`).
    await scrapeFieldSnapshotted(deps, comp, awaitingSnapshot, what, ctx?.signal);
    // Staged, the dev gate has cut it to the contenders and the house's entries (server/entries/dev-profit.ts devProfitGate).
    const subs = await entriesToGrade(db, comp, bundle.submission_rule.rule);
    if (staged !== null && cut !== null) {
      const takenIn = await entriesBeforeDevGate(db, comp, bundle.submission_rule.rule);
      const line = cut.line_us === null ? 'no line: fewer entrants were measured than its contenders, and every measured one went on' : `its line ${cut.line_us} µs`;
      log(
        `[scrape] ${what}: the heat is staged (${staged.contenders} contenders), its cut decided at ${cut.decided_at.toISOString()} with ${line}: ` +
          `of ${takenIn.length} ${takenIn.length === 1 ? 'entry' : 'entries'} taken in, ${subs.length} run the heat (its contenders and the house's entries), ${takenIn.length - subs.length} kept off it by the cut`,
      );
    }
    const baselineRow = subs.filter((x) => x.baseline).sort(byReceipt).at(-1) ?? (await scrapeBaselineOf(db, comp.id));
    if (baselineRow === null) throw new PermanentJobError(`${comp.slug} has no house baseline submitted: the final heat runs every final entry beside it, and its read is the heat's reference`);
    if (!subs.some((x) => x.id === baselineRow.id)) subs.push(baselineRow);
    const entrants: ScrapeEntrant[] = [];
    const refused: Array<{ sub: typeof submission.$inferSelect; error: string }> = [];
    for (const sub of subs.sort(byReceipt)) {
      const e = await scrapeEntrantOf(deps, sub, harness);
      if ('error' in e) refused.push(e);
      else entrants.push(e);
    }
    const baseline = entrants.find((e) => e.sub.id === baselineRow.id);
    if (baseline === undefined) throw new PermanentJobError(`${comp.slug}'s house baseline ${baselineRow.id} cannot run in a heat: ${refused.find((r) => r.sub.id === baselineRow.id)?.error ?? 'its snapshot does not read'}`);

    // The first drand round at or after the scheduled start, once it is out.
    const chain = scrapeDrandChain(deps);
    const clock = deps.scrape?.clock ?? wallClock;
    const start = scrapeFinalRound(ph.startsAt, chain);
    const early = start.at.getTime() + SCRAPE_DRAND_LAG_MS - clock.now();
    if (early > 0) await clock.sleep(early, ctx?.signal);
    const drand = await verifiedDrandRound(deps, chain, start.round);

    // Its layout (the header's `layout`): a job that says `one_pod` runs on `pod` wherever it can be hosted (refused
    // as the platform's fault where it cannot); else by the table (dormant: `split`, nothing read).
    const layout: SandboxLayout = data.one_pod === true ? 'pod' : layoutOfFresh(deps.onePod, comp, harness.kind, deps.log ?? ((line: string) => console.log(line)), `${comp.slug}: ${what}`);
    const recorded = await runScrapeHeatFor({
      deps,
      purpose: 'final',
      heatId: scrapeHeatIdOf('final', `${ph.id}\0${jobKey}`),
      comp: { id: comp.id, slug: comp.slug },
      ph,
      bundle,
      harness,
      competitionKey,
      loadAuthorship,
      entrants,
      baseline,
      recorded: new Set(entrants.map((e) => e.sub.id)),
      drand,
      owner: ctx === undefined ? null : regradeOwner(ctx.id),
      what,
      ...(ctx?.signal === undefined ? {} : { signal: ctx.signal }),
      layout,
    });
    // An entry that can run in no heat fails on its own, as an entry with no runtime does on any kind.
    const plan = scrapePlan({ harness, seed: phaseSeed(competitionKey, ph.key, null), datasetSha256: null });
    const failed: ScrapeHeatRecorded['runs'] = [];
    for (const r of refused) failed.push({ submissionId: r.sub.id, runId: await recordGrade(db, deps.blobs, refusedGrade(plan, r.error), { submissionId: r.sub.id, phaseId: ph.id }), unscored: false, held: null });
    return outcomeOf(ph, recorded.heat.id, recorded.heatSha256, true, [...recorded.runs, ...failed]);
  };
}

function outcomeOf(
  ph: Pick<typeof phase.$inferSelect, 'id' | 'key'>,
  heat: string,
  heatSha256: string,
  ran: boolean,
  runs: ReadonlyArray<{ submissionId: string; runId: string; unscored: boolean; held: string | null }>,
): ScrapeHeatOutcome {
  const phaseKey = ph.key as AggregatedRun['phase'];
  return {
    phase_id: ph.id,
    heat,
    heat_sha256: heatSha256,
    ran,
    publish: runs.filter((r) => !r.unscored).map((r) => ({ run_id: r.runId, submission_id: r.submissionId, phase_id: ph.id, phase: phaseKey })),
    unscored: runs.filter((r) => r.unscored).map((r) => ({ run_id: r.runId, submission_id: r.submissionId })),
    held: runs.filter((r) => !r.unscored && r.held !== null).map((r) => ({ run_id: r.runId, submission_id: r.submissionId, reason: r.held! })),
  };
}

/**
 * A re-judging's scrape-heat job (createScrapeHeatHandler's `rejudge`): server/routes/admin/scrape-holds.ts
 * judgeRejudgeJob on this host's parts, its end answered in a heat job's shape (ScrapeHeatOutcome.rejudge).
 */
async function scrapeRejudgeFor(
  deps: GradeWorkerDeps,
  data: ScrapeRejudgeJobT,
  loadAuthorship: NonNullable<GradeWorkerDeps['loadAuthorship']>,
  ctx: ScrapeHeatJobContext | undefined,
): Promise<ScrapeHeatOutcome> {
  const jobId = ctx?.id ?? uuidv7();
  let end: RejudgeJobEnd;
  try {
    const { judgeRejudgeJob } = await scrapeRuntime<typeof import('../server/routes/admin/scrape-holds.ts')>('../server/routes/admin/scrape-holds.ts');
    end = await judgeRejudgeJob(
      {
        db: deps.db,
        blobs: deps.blobs,
        sandbox: deps.sandbox,
        workRoot: deps.workRoot,
        leaseDir: deps.scrape?.leaseDir ?? scrapeLeaseDirFromEnv(),
        // The scorer as the sandbox mounts it: on the k8s sandbox its stage on the data claim (the header's `k8s data`), as a heat judges.
        scorerSetup: (slug, harness) => scrapeScorerSetupFor(deps.sandbox, slug, { compDir: competitionDirOf(deps, slug, harness), harness }),
        scoring: deps.scrape?.scoring ?? (await scrapeRuntime<typeof import('./scrape/score.ts')>('./scrape/score.ts')),
        loadAuthorship: (submissionId, pricingRev) => loadAuthorship(submissionId, pricingRev),
        owner: regradeOwner(jobId),
        ...(deps.jobs === undefined ? {} : { jobs: deps.jobs }),
        ...(deps.now === undefined ? {} : { now: deps.now }),
        ...(deps.log === undefined ? {} : { log: deps.log }),
      },
      data,
      { id: jobId },
    );
  } catch (err) {
    // A module that does not load: lost, never thrown (judgeRejudgeJob never throws; the stage would page a dead heat).
    console.error(`[scrape] re-judging ${data.rejudge.attempt} of run ${data.rejudge.run_id} (scrape-heat job ${jobId}) could not start:`, err);
    end = { attempt: data.rejudge.attempt, run_id: data.rejudge.run_id, stage: 'lost', heat: null, heat_sha256: null, judged: false, result: null, error: null, refusal: null, next_job_id: null, next_at: null, publish: null };
  }
  return {
    phase_id: data.phase_id,
    heat: end.heat ?? '',
    heat_sha256: end.heat_sha256 ?? '',
    ran: end.judged,
    publish: end.publish === null ? [] : [end.publish],
    unscored: [],
    held: [],
    rejudge: end,
  };
}

// ---------------------------------------------------------------- agent/v1: a run of K trials

/** A series of live passes: the first, and up to AGENT_VOID_RERUNS re-runs of a void; the trial is held once it is spent. A pass cut off (AGENT_INTERRUPTED_RERUNS) is none of them. */
export const AGENT_VOID_RERUNS = 2;
export const AGENT_SERIES_PASSES = 1 + AGENT_VOID_RERUNS;

/** How long a void's re-run waits before its job starts (a broker or provider blip passes meanwhile); an upstream_errors void's: agentVoidRerunDelayMs. */
export const AGENT_VOID_RERUN_DELAY_MS = 60_000;

/** The void reason of a live pass that met upstream errors (grader/agent.ts: any on the house lane, the entry lane's past its void share). */
export const UPSTREAM_ERRORS_VOID_REASON = 'upstream_errors' satisfies TrialVoidReason;

/**
 * How long the first re-run of a series after an upstream_errors void waits (agentVoidRerunDelayMs): each later one
 * waits twice the one before.
 */
export const AGENT_UPSTREAM_VOID_RERUN_DELAY_MS = 5 * 60_000;

/**
 * How long re-run `rerun` of a series (1 for the series' second pass, the first re-run) waits before its job starts,
 * after a void of `reason`. An upstream_errors void's waits AGENT_UPSTREAM_VOID_RERUN_DELAY_MS, doubled for each re-run
 * after the first (5, then 10 minutes for the series' AGENT_VOID_RERUNS; a third would wait 20), so the passes of one
 * series cannot all land in one burst of failing upstream calls (2026-11-11: three bursts of one to three minutes held
 * 38 werewolf-agent-01 trials whose three passes ran a minute apart); every other void's waits
 * AGENT_VOID_RERUN_DELAY_MS. A pass cut off (INTERRUPTED_VOID_REASON) is re-run at once by its caller and comes not here.
 */
export function agentVoidRerunDelayMs(reason: string, rerun: number): number {
  if (reason !== UPSTREAM_ERRORS_VOID_REASON) return AGENT_VOID_RERUN_DELAY_MS;
  return AGENT_UPSTREAM_VOID_RERUN_DELAY_MS * 2 ** Math.max(0, Math.trunc(rerun) - 1);
}

/**
 * How long a trial held for upstream errors (UPSTREAM_ERRORS_VOID_REASON, its series spent) waits, from its last pass's
 * end, before the fan-in re-queues it by itself, once (the header's `held`; createAgentAggregateHandler selfRequeue).
 */
export const TRIAL_SELF_REQUEUE_AFTER_MS = 30 * 60_000;

/**
 * Who an automatic re-queue's trial.requeue audit rows name as their actor (data.actor, with data.automatic true; their
 * actor_user_id null, the system's): the fan-in, whose wait slots sweep its run's held trials.
 */
export const TRIAL_SELF_REQUEUE_ACTOR = 'grade-aggregate';

/** The audit action of a held trial's re-queue: server/routes/admin/grading.ts TRIAL_REQUEUE_ACTION, an admin's or the fan-in's. */
const TRIAL_REQUEUE_ACTION = 'trial.requeue' satisfies AuditAction;

/** The fan-in's wait slot: while a trial is not done it looks again at the end of the next slot (each trial's end looks at once). */
export const AGENT_AGGREGATE_WAIT_MS = 15 * 60_000;

/** A trial job that spent its retries on a refused mint is sent again this much later, so the trial runs once the key is pinned. */
export const AGENT_REFUSAL_RETRY_MS = 15 * 60_000;

/** A refusal of the admin key (or of the engine) is paged at most this often by one process: every trial job meets the same one. */
export const AGENT_REFUSAL_PAGE_MS = 60 * 60_000;

/** What a refusal's trials wait on, and what lets them run (the trial handler's log and page wording of a refusal). */
interface RefusalTerms {
  waitsOn: string;
  once: string;
}
const KEY_REFUSAL: RefusalTerms = { waitsOn: "the admin key's pin", once: 'the key is pinned' };

/**
 * superbot-router as a router-served target's house lane dials it (the header's `house lane`): its origin
 * (MAKEFUN_SUPERBOT_ROUTER_URL), the house-lane key (MAKEFUN_SUPERBOT_ROUTER_HOUSE_KEY) and the tier every call asks
 * (MAKEFUN_SUPERBOT_ROUTER_HOUSE_SPEED).
 */
export interface HouseRouter {
  origin: string;
  key: string;
  speed: Config['superbotRouterHouseSpeed'];
}

/** The house router `config` names: null unless both MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_HOUSE_KEY are set. */
export function houseRouterOf(config: Pick<Config, 'superbotRouterUrl' | 'superbotRouterHouseKey' | 'superbotRouterHouseSpeed'>): HouseRouter | null {
  if (config.superbotRouterUrl === null || config.superbotRouterHouseKey === null) return null;
  return { origin: config.superbotRouterUrl, key: config.superbotRouterHouseKey, speed: config.superbotRouterHouseSpeed };
}

/**
 * Whether a target's house lane runs on superbot-router (the header's `house lane`): every model it names is a router
 * house id or masq's spelling of one (grader/dialect.ts ROUTER_MODELS: a bundle stored before the house lane left masq
 * still names `superbot-router/superbot`).
 */
export function targetOnRouter(models: readonly string[]): boolean {
  return models.length > 0 && models.every((m) => routerModel(m) !== null);
}

/**
 * A router-served target's pass that cannot start (the header's `house lane`): no house router configured, or a target
 * naming a router id beside another model. Never masq in its place: met as a refused admin key is, `terms` its page's.
 */
export class HouseRouterRefusal extends Error {
  readonly terms: RefusalTerms;
  constructor(message: string, terms: RefusalTerms) {
    super(message);
    this.name = 'HouseRouterRefusal';
    this.terms = terms;
  }
}
/** What the isolation lines call the engine, by its driver: grader/sandbox/network.ts ISOLATION_ENGINES, its type pinning the spelling (network.ts is loaded on first use: the header's `isolation`). */
const ISOLATION_ENGINES: typeof SandboxIsolationEngines = { docker: 'Docker engine', k8s: 'Kubernetes cluster' };
/** The driver a sandbox's isolation lines name: k8s's cluster, else docker's engine (IsolationRefusal's default). */
const isolationDriverOf = (sandbox: Pick<Sandbox, 'kind'>): IsolationDriver => (sandbox.kind === 'k8s' ? 'k8s' : 'docker');
/** A refused engine's terms, by the driver whose probe refused it. */
const engineRefusal = (driver: IsolationDriver): RefusalTerms => ({
  waitsOn: `a ${ISOLATION_ENGINES[driver]} that keeps trials apart`,
  once: `the ${driver === 'k8s' ? 'cluster' : 'engine'} keeps trials apart`,
});

/** The void reason of a live pass cut off before it ended (its job attempt stopped or expired): no cassette came back. */
export const INTERRUPTED_VOID_REASON = 'interrupted';

/**
 * The void reason of a dev trial's recorded live pass whose practice instance was re-drawn under it before it was scored
 * (the header's `re-drawn practice`): the scorer would read another instance's reference, so the pass is voided spending
 * no pass of its series, as a cut-off one is, and its next pass runs on the instance drawn now.
 */
export const INSTANCE_REDRAWN_VOID_REASON = 'instance_redrawn';

/**
 * How long a dev trial whose practice instance is not drawn as instance.yaml commits it waits before it looks again (the
 * header's `re-drawn practice`): the slot a waiting dev grade looks again on (server/pipeline/index.ts INSTANCE_RECHECK_MS).
 */
export const PRACTICE_REDRAW_RECHECK_MS = 5 * 60_000;

/**
 * How many passes of a trial in a row may be cut off before it is held (the header's `cut off`): a live pass voided
 * INTERRUPTED_VOID_REASON, or a replay found cut off. Each is re-run without spending a pass of the series (a grader
 * restart is the platform's, never the entry's), and the AGENT_INTERRUPTED_RERUNS-th in a row holds the trial under
 * INTERRUPTED_VOID_REASON, so a pass that kills its grader every time cannot loop.
 */
export const AGENT_INTERRUPTED_RERUNS = 6;

/** The words a cut-off pass's error ends with once two or more in a row were cut off (one alone says none): `n` of them. */
const cutOffRunWords = (n: number): string => `; cut off ${n} times in a row (held at ${AGENT_INTERRUPTED_RERUNS})`;
const CUT_OFF_RUN_RE = /; cut off (\d+) times in a row \(held at \d+\)$/;

/**
 * How many live passes in a row, the last of them `pass`, `row` records as cut off: 0 unless its latest void is pass
 * `pass` voided INTERRUPTED_VOID_REASON with the words interrupted() wrote (a void reason and error are kept through the
 * next pass's run until its own void, so a claimed row still tells of the pass before it); else the count its words
 * end with, 1 when they name none. A held or re-queued trial's error is its hold's, so its run starts again at 0.
 */
function liveCutOffRun(row: Pick<TrialRow, 'voidReason' | 'error'>, pass: number): number {
  if (row.voidReason !== INTERRUPTED_VOID_REASON || row.error === null || !row.error.startsWith(`live pass ${pass}, started `)) return 0;
  const m = CUT_OFF_RUN_RE.exec(row.error);
  return m === null ? 1 : Number(m[1]);
}

/** The words a replay found cut off writes on its row (replayCutOff), `n` the replays of its live pass cut off in a row. */
const replayCutOffWords = (row: Pick<TrialRow, 'attempt' | 'replayStartedAt'>, n: number): string =>
  `the replay of live pass ${row.attempt}, started ${row.replayStartedAt?.toISOString() ?? 'at an unknown time'}, was cut off before it ended (its job attempt stopped or expired)${cutOffRunWords(n)}`;

/** How many replays of `row`'s live pass in a row were found cut off before this one (replayCutOffWords on its error), 0 when none. */
function replayCutOffRun(row: Pick<TrialRow, 'attempt' | 'error'>): number {
  if (row.error === null || !row.error.startsWith(`the replay of live pass ${row.attempt}, started `)) return 0;
  const m = CUT_OFF_RUN_RE.exec(row.error);
  return m === null ? 0 : Number(m[1]);
}

/** The hold reason of a trial whose job died for good outside its handler (an attempt expired, its process gone). */
export const DEAD_JOB_HOLD_REASON = 'job_dead';

/** The hold reason of a trial whose job met a fault no retry mended (none more specific said). */
export const HARNESS_FAULT_HOLD_REASON = 'harness_fault';

/** The run flag of a held trial: server/entries/stage.ts TRIAL_HELD_FLAG, its type pinning the spelling (the stage machine is not loaded here: the header's `agent/v1`). */
const TRIAL_HELD_FLAG: typeof StageTrialHeldFlag = 'trial_held';

/**
 * How often a pass waiting on an entrant's provider key checks it again (the header's `entry secrets`): a key its
 * provider refused on the final, or a provider that gave no verdict. Its job's next slot.
 */
export const AGENT_PROVIDER_KEY_RECHECK_MS = 15 * 60_000;

/**
 * The longest a final pass waits for its entrant to push a new key in place of one its provider refused, from the first
 * refusal (the header's `entry secrets`), and never past the final phase's end: then the trial scores 0
 * (PROVIDER_KEY_REFUSED).
 */
export const AGENT_PROVIDER_KEY_HOLD_MS = 24 * 3_600_000;

/**
 * The audit_event action that starts a final pass's wait on a refused provider key (the header's `entry secrets`), once
 * for the trial and pass: the system's (actor null), subject the run_trial row; data {run_id, trial_index, pass, until
 * (when the trial scores 0 if the key is still refused, ISO), entry_secret_ids, providers}, ids and names only. Its `at`
 * is the window's start (server/payouts/audit.ts AuditAction's `entry_secret.held`).
 */
export const ENTRY_SECRET_HELD_ACTION = 'entry_secret.held';

/**
 * The audit_event action of outputs that held a form of one of their entrant's secrets (the header's `entry secrets`;
 * record.ts SECRET_IN_OUTPUT_ACTION), the run flagged SECRET_IN_OUTPUT_FLAG beside it: the system's (actor null). Of an
 * agent/v1 pass, subject the run_trial row; data {run_id, trial_index, pass, mode (live, replay), hits: [{name, file}]},
 * one a pass and mode. Of a run graded as one execution, subject the run row; data {run_id, hits}, one a run. Each hit a
 * secret's NAME and the output's file (agent.ts SecretOutputHit, record.ts SecretHit), never a value.
 */
export { SECRET_IN_OUTPUT_ACTION };

/**
 * The hold reason of a trial whose entrant's entry secrets this grader cannot open (the header's `entry secrets`): no
 * seal private key configured here (server/secrets/seal.ts entrySecretSealRefusal), or a sealed secret it holds no
 * private key for or cannot open. The platform's fault, never the entrant's, and never sent to masq instead.
 */
export const ENTRY_SECRETS_UNOPENED_HOLD_REASON = 'entry_secrets_unopened';

/**
 * The void reason of a live pass whose replay cannot run as it did: an env-lane entry secret it ran with was erased
 * meanwhile (replaced, removed or purged: the header's `entry secrets`). The next pass runs on what the entrant holds then.
 * The same reason an L2 is refused with once a secret its run recorded is erased (regrade.ts ENTRY_SECRETS_ERASED).
 */
export const ENTRY_SECRETS_ERASED_VOID_REASON = ENTRY_SECRETS_ERASED;

/**
 * The run flag of a trial key whose spend masq had not settled when the read stopped (grader/gateway/masq.ts
 * RetiredTrialKey.settled false: the figure still moving at MASQ_SPEND_SETTLE_CAP_MS, kept as its last read gave it and
 * never compared with the forwarder's meter, so never gateway_spend_mismatch). For admins only, as the mismatch is
 * (server/routes/archive/entry.ts ADMIN_RUN_FLAGS; server/api-types/inference.ts GatewaySpendRunFlag, its type pinning
 * the spelling); it changes no score.
 */
export const GATEWAY_SPEND_UNSETTLED_FLAG: Extract<GatewaySpendRunFlag, 'gateway_spend_unsettled'> = 'gateway_spend_unsettled';

/**
 * The run flags a live pass's masq key sets once it is retired (TrialPass.masq): its cross-check's (masq.ts
 * RetiredTrialKey.flags, gateway_spend_mismatch on a settled figure the meter disagrees with), and
 * GATEWAY_SPEND_UNSETTLED_FLAG when its spend read never settled. None with no key, or a key whose retirement failed.
 */
export function masqRunFlags(masq: Pick<NonNullable<TrialPass['masq']>, 'retired' | 'flags'> | null): string[] {
  if (masq === null) return [];
  return masq.retired !== null && !masq.retired.settled ? [...masq.flags, GATEWAY_SPEND_UNSETTLED_FLAG] : [...masq.flags];
}

/**
 * The run flag of a pass on a house clock (TrialPass.house_clock: grader/house-clock.ts houseClockFlag), one a pass of
 * a trial: what the house took, its bound and the credit the entry's deadline stood at. On the run row alone, never in
 * its score (an agent/v1 score's execution flags are none), its trials manifest or any record a result_sha256 covers.
 * None for a pass on no house clock, or whose entry never ran.
 */
export function houseClockRunFlags(p: Pick<TrialPass, 'mode' | 'house_clock'>, trialIndex: number, pass: number): string[] {
  return p.house_clock === undefined ? [] : [houseClockFlag(trialIndex, pass, p.mode, p.house_clock)];
}

/** The format an agent/v1 run's dataset_sha256 digests (agentDatasetSha256). */
export const AGENT_INSTANCES_FORMAT = 'agent-fun/agent-instances/v1';

/** The trial statuses that count: done, nothing more to run (contracts/agent.ts AGENT_TRIAL_STATUSES). */
const DONE_TRIAL_STATUSES: ReadonlySet<string> = new Set(AGENT_TRIAL_STATUSES);

/**
 * An agent/v1 run's dataset_sha256 (and its phase seed's dataset part): canonicalSha256 of {format:
 * AGENT_INSTANCES_FORMAT, trials: [{index, instance_sha256}]} over the instances its trials run on, in
 * index order, so another draw (a redraw) or another phase's instances name another.
 */
export function agentDatasetSha256(trials: readonly { index: number; instance_sha256: string }[]): string {
  return canonicalSha256({ format: AGENT_INSTANCES_FORMAT, trials: trials.map((t) => ({ index: t.index, instance_sha256: t.instance_sha256 })) });
}

/**
 * The wait of a dev grade or trial whose competition directory's instance.yaml (`path`) was drawn by generator
 * `drawnBy` while the stored bundle seals `stored` (agentPhaseTrials; the header's `re-drawn practice`): a release
 * between its deploy, which ships the new instance.yaml in its image, and its seed, which stores the new bundle. An
 * InstanceNotDrawnError naming instance.yaml, so the grade waits as it waits for a practice tree, and no practice-draw
 * job is sent for it by the grade stage (server/pipeline/index.ts: its path is no practice tree's).
 */
function releaseWindowError(slug: string, path: string, drawnBy: string, stored: string): InstanceNotDrawnError {
  return new InstanceNotDrawnError(
    `${slug}'s ${INSTANCE_FILE} (${path}) was drawn by generator ${drawnBy}, and the stored bundle's harness.generator_sha256 is ${stored}: the stored bundle and the ${INSTANCE_FILE} this release ships are not of one bundle yet. The practice grade waits, and no entry is failed: deploy/k8s/makefun-k8s.sh -o <overlay> seed of the running release stores its bundle and mends it (or the next release ships the ${INSTANCE_FILE} of the bundle stored)`,
    path,
  );
}

/** One trial a phase of an agent/v1 bundle runs (agentPhaseTrials): the draw's trial t, its instance and the directory holding it. */
export interface AgentPhaseTrial {
  index: number;
  instance_sha256: string;
  /** The instance's directory, holding input/ (input/prompt.txt, input/env/) and reference/. */
  dir: string;
}

/** The trials a phase of an agent/v1 bundle runs. */
export interface AgentPhaseTrials {
  /** practice on the dev phase, scored on the final. */
  purpose: 'practice' | 'scored';
  /** The scored draw in force (the newest record's k); null for practice. */
  k: number | null;
  trials: AgentPhaseTrial[];
}

/**
 * The trials an agent/v1 bundle's phase runs (the header's `agent/v1`): its trials sidecar (the
 * competition directory's instance.yaml, parseTrialsSidecar) checked against the bundle
 * (checkInstanceBundle, its trial counts the harness's); the dev phase one trial, on practice trial 0
 * (load.ts practiceTrialDir); any other phase (the final) every trial of the newest scored draw, the
 * whole draw chain verified (verifyInstanceDraws under kind agent/v1), in its scored-<k>/trial-<t>/
 * (scoredTrialDir). Each trial's trees digest to its record's and its directory to its
 * instance_sha256. Throws PermanentJobError: no retry draws an instance or mends one. What is not there at all (no
 * instance.yaml, no draw record yet, a tree), or a practice trial there that is not its sidecar record, is an
 * InstanceNotDrawnError: the draw mends it. So is, on the dev phase alone, an instance.yaml drawn by another generator
 * than the stored bundle's harness.generator_sha256 (checkInstanceBundle's instance_generator naming the one it
 * expected; the header's `re-drawn practice`, its release window): the stored bundle and the instance.yaml this release
 * ships are not of one bundle yet, which the seed of the running release mends (or the next release, shipping the
 * instance.yaml of the bundle stored), so the dev grade or trial waits, naming instance.yaml's path (releaseWindowError).
 * On the final phase it stays a PermanentJobError, as does every other way instance.yaml fails to check, on dev too.
 */
export async function agentPhaseTrials(input: { slug: string; bundle: CompetitionBundleT; compDir: string; sealedDir: string; phaseKey: string; chain: InstanceChainOptions }): Promise<AgentPhaseTrials> {
  const { slug, bundle } = input;
  const h = bundle.harness;
  if (h.kind !== 'agent/v1') throw new PermanentJobError(`${slug} is not an agent/v1 competition`);
  const sidecarPath = join(input.compDir, INSTANCE_FILE);
  const practiceFix = `draw them with node scripts/competitions/instance.ts practice --competition ${slug} (it re-draws a committed ${INSTANCE_FILE}'s practice trials into a removed practice/)`;
  const bytes = readSmallFile(sidecarPath, MAX_INSTANCE_BYTES, `${slug}'s ${INSTANCE_FILE}`);
  if (bytes === null) throw sidecarNotThere(sidecarPath, `${slug} is an agent/v1 competition, and its competition directory has no ${INSTANCE_FILE} (${sidecarPath}) to say which instances its trials run on: ${practiceFix}`);
  const final = bundle.phases.find((p) => p.key === 'final');
  // Its drand rounds checked off the event loop (load.ts instanceRoundCheckOffLoop, the verdicts handed in as the
  // chain's verifyRound): the sidecar read and the draw chain verified below do no BLS arithmetic on the loop. The
  // pool's OffThreadError rejects, and the job retries.
  const testChain = input.chain.testChain === undefined ? {} : { testChain: input.chain.testChain };
  const practiceRound = await instanceRoundCheckOffLoop({ sidecar: bytes, ...testChain });
  let sidecar: TrialsSidecarT;
  try {
    sidecar = parseTrialsSidecar(bytes, { ...input.chain, verifyRound: practiceRound });
    if (final === undefined) throw new PermanentJobError(`${slug} is an agent/v1 competition and has no final phase to draw its scored trials for`);
    checkInstanceBundle(sidecar, { generatorSha256: h.generator_sha256, opensAt: bundle.competition.opens_at, finalStartsAt: final.starts_at, finalEndsAt: final.ends_at, trials: h.trials }, input.chain);
  } catch (err) {
    if (isInstanceError(err)) {
      // A release window (the header's `re-drawn practice`): the dev phase's sidecar drawn by another generator than the stored bundle's waits for the seed.
      const expected = err.detail.expected_generator_sha256;
      if (input.phaseKey === 'dev' && isInstanceError(err, 'instance_generator') && typeof expected === 'string') throw releaseWindowError(slug, sidecarPath, String(err.detail.generator_sha256), expected);
      throw new PermanentJobError(`${slug}'s ${INSTANCE_FILE} does not check (${err.code}): ${err.message}`, { cause: err });
    }
    throw err;
  }
  const { instanceSha256Async: agentInstanceSha256 } = await import('./agent.ts');
  // `stale` (a practice trial's only): a tree there that is not its record waits for the release's re-draw (checkInstanceTrees).
  // Its trees and its instance digest walked and hashed on fs/promises (checkInstanceTreesAsync, agent.ts instanceSha256Async).
  const checked = async (t: number, dir: string, rec: { input_sha256: string; reference_sha256: string; instance_sha256: string }, what: string, fix: string, stale?: string): Promise<AgentPhaseTrial> => {
    await checkInstanceTreesAsync({ dir, expected: { input: rec.input_sha256, reference: rec.reference_sha256 }, what, fix, ...(stale === undefined ? {} : { stale }) });
    const digest = await agentInstanceSha256(dir);
    if (digest !== rec.instance_sha256) {
      const message = `${what} ${dir} has instance digest ${digest}, not its record's instance_sha256 ${rec.instance_sha256}`;
      if (stale !== undefined) throw new InstanceNotDrawnError(`${message}: ${stale}`, dir);
      throw new PermanentJobError(`${message}: ${fix}`);
    }
    return { index: t, instance_sha256: rec.instance_sha256, dir };
  };

  if (input.phaseKey === 'dev') {
    const practice = sidecar.practice.trials[0]!;
    return { purpose: 'practice', k: null, trials: [await checked(0, practiceTrialDir(input.sealedDir, slug, 0), practice, `${slug}'s practice trial 0`, practiceFix, practiceStaleFix(slug, 'trials'))] };
  }

  const root = instanceRootOf(input.sealedDir, slug);
  const records = readDrawRecords(root, slug);
  if (records.length === 0) {
    throw new InstanceNotDrawnError(
      `the ${input.phaseKey} phase of ${slug} runs its trials on its drawn scored instances, and there is no draw record (${instanceDrawFile(0)}) in ${root}: the final phase is graded once the scored round (${sidecar.scored.beacon.round}, ${sidecar.scored.beacon.at}) is drawn (POST /api/admin/competitions/${slug}/instance/draw)`,
      join(root, instanceDrawFile(0)),
    );
  }
  const rounds = await instanceRoundCheckOffLoop({ sidecar: bytes, records, ...testChain });
  let draw;
  try {
    draw = verifyInstanceDraws({ sidecar: bytes, records, competition: slug, kind: 'agent/v1', ...input.chain, verifyRound: rounds }).at(-1)!;
  } catch (err) {
    if (isInstanceError(err)) throw new PermanentJobError(`${slug}'s draw records do not verify (${err.code}): ${err.message}`, { cause: err });
    throw err;
  }
  const k = draw.k;
  const fix = `it is not the instance ${instanceDrawFile(k)} records; the final phase's trials run only on the draw as recorded`;
  // One trial at a time, in the record's order: the first that does not check is the answer, as before.
  const trials: AgentPhaseTrial[] = [];
  for (const tr of draw.record.trials) trials.push(await checked(tr.t, scoredTrialDir(input.sealedDir, slug, k, tr.t), tr, `${slug}'s scored trial ${tr.t} of draw ${k}`, fix));
  return { purpose: 'scored', k, trials };
}

/**
 * The staged final a run of phase `phaseKey` of `bundle` grades on (the header's `staged final`): the bundle's staged
 * block (contracts/competition.ts stagedFinalOf) on its final phase; null on every other phase, and on a bundle that
 * stages nothing, whose runs grade as before.
 */
export function stagedFinalRun(bundle: { harness: HarnessT }, phaseKey: string): StagedFinalT | null {
  return phaseKey === 'final' ? stagedFinalOf(bundle) : null;
}

/**
 * A grade-trial job's priority from its trial's queue tag (server/jobs.ts gradeTrialPriority), a tag past
 * MAX_GRADE_TRIAL_QUEUE_TAG (which the priority column cannot hold) taken at the cap's priority and said so (`capped`),
 * so a staged final's contender is never stranded by a throw (the header's `staged final`).
 */
export function cappedTrialPriority(queueTag: number): { priority: number; capped: boolean } {
  if (queueTag > MAX_GRADE_TRIAL_QUEUE_TAG) return { priority: gradeTrialPriority(MAX_GRADE_TRIAL_QUEUE_TAG), capped: true };
  return { priority: gradeTrialPriority(queueTag), capped: false };
}

/**
 * The entry's facts the LLM agent floor reads (grader/agent-score.ts AgentEntryFacts): the house's and the baseline's
 * exemptions, and the harness's waivers (a target, model_calls: optional) read off it as a regrade reads them
 * (agentHarnessFloorFacts). The fan-in scores a run with them, and a staged final's first trial is measured with them.
 */
function agentEntryFactsOf(sub: Pick<typeof submission.$inferSelect, 'house' | 'submittedAsHouse' | 'baseline'>, harness: HarnessT) {
  return { house: standingsHouse(sub), baseline: sub.baseline, ...(harness.kind === 'agent/v1' ? agentHarnessFloorFacts(harness) : {}) };
}

/**
 * A trial's row as aggregateTrials reads it (AgentTrialResult): its stored records, scored `status`, and the LLM agent
 * floor's count of model calls off its stored cassette alone, as a regrade counts it. The fan-in lists every trial of a
 * run so, and a staged final's first trial is measured so.
 */
function agentTrialResultOf(t: TrialRow, cassette: CassetteT, modelCalls: number, status: AgentTrialStatusT): AgentTrialResult {
  return {
    index: t.trialIndex,
    instance_sha256: t.instanceSha256,
    cassette_sha256: t.cassetteSha256!,
    state_sha256: t.stateSha256!,
    status,
    scores: t.score as ProgramScores | null,
    // The rows its scorer wrote beside those scores, or why they were dropped (the header's `checks`): the breakdown's, never the score's.
    checks: t.checks as ScorerChecksT | null,
    checks_issue: t.checksIssue,
    pricing_rev: cassette.pricing_rev,
    requests: t.requests ?? cassette.totals.requests,
    // The LLM agent floor's count, off the stored cassette alone, as a regrade counts it.
    model_calls: modelCalls,
    spend_micro_usd: (t.spendMicroUsd ?? 0n).toString(),
    voids: Math.max(0, t.attempt - 1),
  };
}

/**
 * A staged final's qualifying trials (the header's `staged final`, its stages): the scored instances a run has run when
 * the finalists are chosen, so its trials 0 to this - 1 park at their live pass until its fate is known and trials from
 * here on are a finalist's own. 1 on a final with one cut (trial 0 alone); the last earlier cut's `instances` on one that
 * names cuts (server/grading/final-cut.ts finalCutsOf: the last cut's `at`).
 */
export function stagedQualifyingTrials(staged: StagedFinalT): number {
  return staged.cuts?.at(-1)?.instances ?? 1;
}

/** A trial parked at its live pass (the header's `staged final`): live_done and scored, waiting on its run's fate. */
function parkedTrial(t: Pick<TrialRow, 'status' | 'score'>): boolean {
  return t.status === 'live_done' && t.score !== null;
}

/** One decided cut of a staged final as the grader reads it (stagedCutsOf): when, and its stored line (null: fewer than its contenders were scored). */
interface StoredCut {
  decidedAt: Date;
  line: number | null;
}

/**
 * Every cut of a staged final's phase as it stands now, by index (server/grading/final-cut.ts finalCutsOf), `count` of
 * them: cut 0 off the phase's own columns (phase.cut_decided_at, cut_line_points), each later one off its phase_cut row
 * (server/db/schema.ts phaseCut); null where undecided. Read afresh each time it is asked: a run's context read the
 * phase as its job began, a live pass ago maybe.
 */
async function stagedCutsOf(db: Db, phaseId: string, count: number): Promise<(StoredCut | null)[]> {
  const [p] = await db.select({ decidedAt: phase.cutDecidedAt, line: phase.cutLinePoints }).from(phase).where(eq(phase.id, phaseId));
  if (p === undefined) throw new Error(`phase ${phaseId} does not exist`);
  const out: (StoredCut | null)[] = Array.from({ length: count }, () => null);
  if (p.decidedAt !== null) out[0] = { decidedAt: p.decidedAt, line: p.line };
  if (count > 1) {
    for (const r of await db.select({ cut: phaseCut.cut, decidedAt: phaseCut.decidedAt, line: phaseCut.linePoints }).from(phaseCut).where(eq(phaseCut.phaseId, phaseId))) {
      if (r.cut >= 1 && r.cut < count) out[r.cut] = { decidedAt: r.decidedAt, line: r.line };
    }
  }
  return out;
}

/** The trial statuses whose row holds its live pass's scores: parked or replaying, or ended. */
const SCORED_PASS_STATUSES: ReadonlySet<string> = new Set(['live_done', 'replaying', 'finished', 'nondeterministic']);

/**
 * A staged final's run's trials 0 to `under` - 1 as its cuts measure them (server/grading/final-cut.ts runFateOf): a
 * timeout at 0 points; a trial whose row holds its live pass's scores (parked at live_done, replaying, or ended) at the
 * points cutPointsOf reads of it alone, with the entry's facts and the floor's count off its stored cassette, as the
 * fan-in will score it, and as the one-cut final's first trial is measured (cutVerdict). A trial still to run, running,
 * void, held or unscored is not measured.
 */
async function measuredTrialsOf(
  blobs: BlobStore,
  sub: Pick<typeof submission.$inferSelect, 'house' | 'submittedAsHouse' | 'baseline'>,
  bundle: CompetitionBundleT,
  trials: readonly TrialRow[],
  under: number,
): Promise<CutMeasuredTrial[]> {
  const cut = await import('../server/grading/final-cut.ts');
  const { cassetteModelCalls, readCassette } = await import('./gateway/cassette.ts');
  const facts = agentEntryFactsOf(sub, bundle.harness);
  const out: CutMeasuredTrial[] = [];
  for (const t of trials) {
    if (t.trialIndex >= under) continue;
    if (t.status === 'timeout') {
      out.push({ index: t.trialIndex, status: 'timeout', points: 0 });
      continue;
    }
    if (!SCORED_PASS_STATUSES.has(t.status) || t.score === null || t.cassetteSha256 === null) continue;
    const cassette = await readCassette(blobs, t.cassetteSha256);
    // A live pass recorded and scored is measured as a finished trial on the live pass's scores (cutPointsOf's terms).
    out.push({ index: t.trialIndex, status: 'scored', points: cut.cutPointsOf(agentTrialResultOf(t, cassette, cassetteModelCalls(cassette), 'finished'), bundle.leaderboard, facts) });
  }
  return out;
}

/** A staged final's run's fate as it stands now (stagedFateOf): its cuts, each one's stored decision, and where its walk through them ends. */
interface StagedFate {
  cuts: FinalCut[];
  decided: (StoredCut | null)[];
  fate: RunFate;
}

/**
 * A staged final's run's fate (the header's `staged final`, its stages): the bundle's cuts (finalCutsOf), every one as
 * stored now (stagedCutsOf), and runFateOf over the run's measured qualifying trials (measuredTrialsOf) with the
 * house's flag (cutExempt), each cut judged on the run's total over its trials once all are measured, against its
 * stored line.
 */
async function stagedFateOf(
  db: Db,
  blobs: BlobStore,
  who: { sub: typeof submission.$inferSelect; phaseId: string; bundle: CompetitionBundleT },
  staged: StagedFinalT,
  trials: readonly TrialRow[],
): Promise<StagedFate> {
  const cut = await import('../server/grading/final-cut.ts');
  const cuts = cut.finalCutsOf(staged);
  const decided = await stagedCutsOf(db, who.phaseId, cuts.length);
  const { sorting } = cut.cutColumnOf(who.bundle.leaderboard);
  const measured = await measuredTrialsOf(blobs, who.sub, who.bundle, trials, stagedQualifyingTrials(staged));
  const fate = cut.runFateOf(
    cuts,
    decided.map((d) => (d === null ? null : { line: d.line, sorting })),
    measured,
    cut.cutExempt(who.sub),
  );
  return { cuts, decided, fate };
}

/** A fate that waits: on a cut not decided yet or its stage's trials not all measured (pending), or on the next stage's trials (through). */
function fateWaits(fate: RunFate): fate is Extract<RunFate, { fate: 'pending' | 'through' }> {
  return fate.fate === 'pending' || fate.fate === 'through';
}

/** The cut a waiting fate waits on: a pending run's own, a run through cut c the next one. */
function cutWaitedOn(fate: Extract<RunFate, { fate: 'pending' | 'through' }>): number {
  return fate.fate === 'pending' ? fate.cut : fate.cut + 1;
}

/**
 * The job key a decided cut wakes a parked trial under (gradeTrialJobId's `key`): `cut:<decided ms>` for cut 0, as the
 * final-cut job has always sent it, `cut:<c>:<decided ms>` for a later cut c, so the cut job and a trial's own handler
 * send one job for each parked trial.
 */
export function stagedWakeKey(cut: number, decidedAt: Date): string {
  return cut === 0 ? `cut:${decidedAt.getTime()}` : `cut:${cut}:${decidedAt.getTime()}`;
}

/** An instance directory as run_trial.instance_ref holds it: relative to the sealed directory, with / between its parts. */
function sealedRef(sealedDir: string, dir: string): string {
  const rel = relative(sealedDir, dir);
  if (rel === '' || isAbsolute(rel) || rel.split(sep).includes('..')) throw new PermanentJobError(`the instance directory ${dir} is not under the sealed directory ${sealedDir}`);
  return rel.split(sep).join('/');
}

interface AgentRunStart {
  deps: GradeWorkerDeps;
  ctx: GradeJobContext | undefined;
  sub: typeof submission.$inferSelect;
  ph: typeof phase.$inferSelect;
  /** The competition: its id, its slug and its row's created_at (what sandboxLayoutOf reads, the header's `layout`). */
  comp: { id: string; slug: string; createdAt: Date };
  bundle: CompetitionBundleT;
  harness: AgentHarnessT;
  index: SnapshotIndex;
  competitionKey: string;
}

/**
 * A retried agent/v1 grade's run as it stands (the header's `layout`): its flags and its trials' rows (loadTrials': every
 * run_trial row of the run, in trial index order), in ONE query, the one its retry made of the trials alone before.
 */
async function trialsWithFlags(db: Pick<Db, 'select'>, runId: string): Promise<{ flags: string[]; trials: TrialRow[] }> {
  const rows = await db.select({ flags: run.flags, trial: runTrial }).from(run).leftJoin(runTrial, eq(runTrial.runId, run.id)).where(eq(run.id, runId)).orderBy(asc(runTrial.trialIndex));
  return { flags: rows[0]?.flags ?? [], trials: rows.flatMap((r) => (r.trial === null ? [] : [r.trial])) };
}

/**
 * An agent/v1 grade job (the header's `agent/v1`): the phase's trials found, the entry's runtime
 * picked (none: a failed run recorded at once, nothing run), every image the trials need present,
 * then the run's row (running) and its trial rows, each trial's job for live pass 1 and the fan-in's
 * first job. Answers null: nothing is published until the fan-in finishes the run.
 */
async function startAgentRun(s: AgentRunStart): Promise<{ run_id: string } | null> {
  const { deps, sub, ph, comp, bundle, harness } = s;
  const compDir = competitionDirOf(deps, comp.slug, harness);
  const sealedDir = deps.sealedDir ?? sealedDirFromEnv();
  const phaseTrials = await agentPhaseTrials({ slug: comp.slug, bundle, compDir, sealedDir, phaseKey: ph.key, chain: instanceChainOptions(deps.drandChain) });
  const datasetSha256 = agentDatasetSha256(phaseTrials.trials);
  const plan = agentPlan({ harness, seed: phaseSeed(s.competitionKey, ph.key, datasetSha256), datasetSha256 });
  const ids = { submissionId: sub.id, phaseId: ph.id };
  const picked = entryRuntime(s.index, plan.runtimes);
  if ('error' in picked) return { run_id: await recordGrade(deps.db, deps.blobs, refusedGrade(plan, picked.error), ids) };
  const jobs = deps.jobs;
  if (jobs === undefined) throw new Error(`${comp.slug} is an agent/v1 competition, and this grader has no job queue to send its trials on (GradeWorkerDeps.jobs)`);
  // The entry's image, the env's and the scorer's: a trial that could not start any of them would only void.
  await preflight(plan, deps.sandbox, picked.runtime, null);

  const startedAt = deps.now?.() ?? new Date();
  const runId = s.ctx === undefined ? uuidv7() : agentRunId(s.ctx.id);
  const started = await startRun(deps.db, {
    id: runId,
    ...ids,
    imageDigest: deps.sandbox.imageDigest(picked.runtime),
    datasetSha256,
    harnessVersion: harnessVersion(),
    scorerVersion: scorerVersionOf(plan, deps.sandbox),
    seed: plan.seed,
    startedAt,
  });
  // The run's layout (the header's `layout`): a run made now takes the table's (dormant: `split`, nothing read or
  // written), flagged ONE_POD_FLAG at once on `pod`; a run a dead attempt of this job made keeps its own, in every
  // process (a dormant one too): its flags come with its trials, in the one read a retry makes of them (trialsWithFlags
  // below). Every trial job of it says so (`one_pod`), so the queue counts it one pod in the pod trials' own slots (and
  // the trial handler follows the run's flag whatever its job says). A staged final's run is flagged so as any other.
  let onePod = false;
  if (started.inserted) {
    onePod = layoutOfFresh(deps.onePod, comp, bundle.harness.kind, deps.log ?? ((line: string) => console.log(line)), `${comp.slug}: submission ${sub.id}'s grade on the ${ph.key} phase`) === 'pod';
    if (onePod) await addRunFlags(deps.db, runId, [ONE_POD_FLAG]);
  }
  // A staged final's run starts with the draw's trial 0 alone (the header's `staged final`); its dataset above is the
  // whole draw's all the same.
  const made = stagedFinalRun(bundle, ph.key) === null ? phaseTrials.trials : phaseTrials.trials.filter((t) => t.index === 0);
  // Each trial tagged with its place in the grade-trial queue as it is made (record.ts `queue tags`).
  await insertTrials(
    deps.db,
    runId,
    made.map((t) => ({ index: t.index, instanceSha256: t.instance_sha256, instanceRef: sealedRef(sealedDir, t.dir) })),
    bundle.limits.wall_budget_sec,
  );
  // The trials as the run holds them: a retried grade job's run keeps those it was made with, their tags and their jobs' ids
  // (and its own layout, by the flags read with them).
  const expireInSeconds = agentTrialExpirySeconds(bundle.limits.wall_budget_sec, comp.slug);
  let trials: TrialRow[];
  if (started.inserted) {
    trials = await loadTrials(deps.db, runId);
  } else {
    const held = await trialsWithFlags(deps.db, runId);
    trials = held.trials;
    onePod = held.flags.includes(ONE_POD_FLAG);
  }
  for (const t of trials) {
    const tag = t.queueTag ?? (await retagTrial(deps.db, t, bundle.limits.wall_budget_sec)).tag;
    await jobs.send(
      'grade-trial',
      { run_id: runId, trial_index: t.trialIndex, pass: 1, first_pass: 1, ...(onePod ? { one_pod: true as const } : {}) },
      { id: gradeTrialJobId(runId, t.trialIndex, 1), priority: gradeTrialPriority(tag), expireInSeconds },
    );
  }
  await jobs.send('grade-aggregate', { run_id: runId }, { id: gradeAggregateJobId(runId, 'start'), startAfter: new Date(startedAt.getTime() + AGENT_AGGREGATE_WAIT_MS) });
  return null;
}

/** The trial statuses an agent/v1 run replayed (regrade.ts REPLAYED): a timeout never was, so an L2 replays it not. */
const REPLAYED_TRIAL_STATUSES: ReadonlySet<string> = new Set(['finished', 'nondeterministic']);

/**
 * The env-lane entry secrets each trial of an agent/v1 run replays with on an L2 (the header's `entry secrets`): of every
 * trial the run replayed on its entrant's credential, exactly the rows its live pass recorded (run_trial.entry_secret_ids,
 * the env lane's alone: a replay runs on no provider key), retained rows included, re-opened, by trial index. `erased`
 * names the trials and rows erased since (the L2 is then refused unexecuted, regrade.ts ENTRY_SECRETS_ERASED); `forms`
 * every form of every value, what the regrade's record is masked of. One this grader cannot open holds the regrade
 * (EntrySecretsUnopenedError: the job tries again), naming rows, never a value.
 */
async function agentTrialSecrets(
  deps: GradeWorkerDeps,
  who: SecretOwner,
  rows: readonly TrialRow[],
  what: string,
): Promise<{ trialSecrets: Map<number, Record<string, string>>; erased?: string; forms: FormSet | null }> {
  const seal = entrySecretSealOf(deps);
  const trialSecrets = new Map<number, Record<string, string>>();
  const erased: string[] = [];
  const values: string[] = [];
  for (const row of rows) {
    if (row.entryCredential !== 'entrant' || !REPLAYED_TRIAL_STATUSES.has(row.status)) continue;
    const recorded = await recordedEnvSecrets(deps.db, seal, who, row.entrySecretIds);
    if (recorded.erased !== null) {
      erased.push(`trial ${row.trialIndex}: ${recorded.erased}`);
      continue;
    }
    if (recorded.kind === 'unopened') {
      const which = recorded.cause === 'off' ? ` (${recorded.names.join(', ')})` : '';
      throw new EntrySecretsUnopenedError(
        `${what}: the env-lane entry secrets trial ${row.trialIndex}'s live pass ran with${which} cannot be opened here, so it is not replayed without them (its job tries again): ${recorded.why}`,
        recorded.names,
      );
    }
    if (recorded.secrets.ids.length === 0) continue;
    trialSecrets.set(row.trialIndex, recorded.secrets.env);
    values.push(...Object.values(recorded.secrets.env));
  }
  const { secretFormSet } = await import('./gateway/upstream.ts');
  const why = erased.length === 0 ? undefined : `an env-lane entry secret its trials' live passes ran with is erased since (replaced, deleted or purged): ${erased.join('; ')}, so they cannot replay as they did; its L1 stands`;
  return { trialSecrets, ...(why === undefined ? {} : { erased: why }), forms: values.length === 0 ? null : secretFormSet(values) };
}

/**
 * An agent/v1 regrade job (the header's `regrade`): the stored grade run (a grade of this entry on this phase, its
 * seed recorded), the phase's trials as the grade found them (agentPhaseTrials: the same instances, verified, or
 * a dataset_sha256 that differs), each trial's void re-runs from its row, the cost and the authorship its score was
 * built with; then regrade.ts regradeAgentL1 (a rescore of the stored state exports) or regradeAgentL2 (a replay of
 * the stored cassettes with no upstream, then L1), recorded as a regrade run. A run that cannot be re-derived is a
 * PermanentJobError.
 */
async function regradeAgentRun(s: AgentRunStart & { job: JobPayload<'grade-dev'>; loadAuthorship: NonNullable<GradeWorkerDeps['loadAuthorship']> }): Promise<{ run_id: string }> {
  const { deps, sub, ph, comp, bundle, harness, job } = s;
  const { db, blobs } = deps;
  const stored = await loadStoredRun(db, job.reproduces_run_id!);
  if (stored === null) throw new PermanentJobError(`run ${job.reproduces_run_id} does not exist`);
  if (stored.submissionId !== sub.id || stored.phaseId !== ph.id) throw new PermanentJobError(`run ${stored.id} is not a run of submission ${sub.id} in phase ${ph.id}`);
  const [orig] = await db.select({ kind: run.kind }).from(run).where(eq(run.id, stored.id));
  if (orig?.kind !== 'grade') throw new PermanentJobError(`run ${stored.id} is a ${orig?.kind}; regrade the grade run it reproduces`);
  if (stored.seed === null) throw new PermanentJobError(`run ${stored.id} recorded no seed`);

  const compDir = competitionDirOf(deps, comp.slug, harness);
  const phaseTrials = await agentPhaseTrials({ slug: comp.slug, bundle, compDir, sealedDir: deps.sealedDir ?? sealedDirFromEnv(), phaseKey: ph.key, chain: instanceChainOptions(deps.drandChain) });
  const plan = agentPlan({ harness, seed: stored.seed, datasetSha256: agentDatasetSha256(phaseTrials.trials) });
  const dirOf = new Map(phaseTrials.trials.map((t) => [t.index, t.dir]));
  const trialRows = await loadTrials(db, stored.id);
  const trials = trialRows.flatMap((t) => {
    const dir = dirOf.get(t.trialIndex);
    return dir === undefined ? [] : [{ index: t.trialIndex, instanceDir: dir, voids: Math.max(0, t.attempt - 1) }];
  });
  const { cost, pricingRev } = await entryCostFor(deps, { sub, bundle, fresh: false, stored: stored.result });
  const version = storedAuthorshipVersion(stored.result);
  let authorship: AuthorshipSummaryT | null = null;
  if (version !== null) {
    authorship = await s.loadAuthorship(sub.id, pricingRev, version);
    if (version !== undefined && authorship?.algo_version !== version) {
      throw new PermanentJobError(`run ${stored.id} was graded with authorship algorithm ${version}, and submission ${sub.id} has no summary of it under pricing_rev ${pricingRev}`);
    }
  }
  // The job's owner, the same on each of its attempts: a retry removes what an attempt that died left (the header's `regrade`).
  const jobId = s.ctx?.id ?? uuidv7();
  const log = deps.log ?? ((line: string) => console.log(line));
  const regrading = `run ${stored.id}'s ${job.kind} regrade (job ${jobId})`;
  const req: AgentRegradeL1Request = {
    stored,
    plan,
    sandbox: deps.sandbox,
    blobs,
    limits: bundle.limits,
    workRoot: deps.workRoot,
    cost,
    authorship,
    entry: { house: standingsHouse(sub), baseline: sub.baseline },
    rules: eligibilityRulesOf(bundle),
    // The env and the scorer as the sandbox mounts them: on the k8s sandbox their stages on the data claim (the header's `k8s data`).
    setup: await agentSetupFor(deps.sandbox, comp.slug, { compDir, harness, leaderboard: bundle.leaderboard, competition: comp.slug }),
    leaderboard: bundle.leaderboard,
    trials,
    owner: regradeOwner(jobId),
    onScratchReap: (r) => {
      const line = scratchReapLine(regrading, `attempt ${(s.ctx?.retryCount ?? 0) + 1}`, r);
      if (line !== null) log(line);
    },
    // Trials' rows that make no checks trace: logged with why, as the fan-in logged them; the regrade carries none.
    onTraceIssue: (issue) => log(traceIssueLine(regrading, issue)),
  };
  const ids = { submissionId: sub.id, phaseId: ph.id };
  /** Every form of the secrets an L2's replays run with: what its record is masked of (record.ts RunSecrets.mask). */
  let mask: FormSet | null = null;
  try {
    let outcome;
    if (job.kind === 'regrade_l1') {
      outcome = await regradeAgentL1(req);
    } else {
      const picked = entryRuntime(s.index, plan.runtimes);
      if ('error' in picked) throw new PermanentJobError(picked.error);
      // On the run's own layout, whatever the table says now (the header's `layout`): a run flagged ONE_POD_FLAG replays
      // each trial on one pod, its lanes in this process's lanes pod (opened first: no room for it is the node's, thrown
      // on); a process that cannot host it refuses the regrade as the platform's fault, never replaying it on `split`.
      // Each replay's entry lane key is the one its trial's record carries (AgentTrialRecord.entry_key, regrade.ts reads
      // it): the L2 is handed no key and no secret.
      let onePod: (Omit<OnePodPass, 'entryKey'> & Pick<AgentRegradeL2Request, 'sandbox'>) | Record<string, never> = {};
      if (storedRunLayout(stored) === 'pod') {
        const host = onePodHostOf(deps.onePod, `${comp.slug}: ${regrading}`);
        const lanes = await openOnePodLanes(host);
        const requests = podRequestsOf(comp.slug);
        onePod = { sandbox: host.view(), hosted: lanes.hosted, door: lanes.door, ...(requests === null ? {} : { podRequests: { ...requests } }) };
      }
      // Its replays make trial networks: none on an engine that does not keep trials apart (the header's `isolation`).
      const isolation = deps.isolation !== undefined ? deps.isolation : await sandboxIsolation(deps.sandbox);
      if (isolation !== null) await isolation.require();
      const gateway = await (deps.forwarder ?? (async () => (await import('./gateway/bundle.ts')).gatewayBundle({ cacheDir: join(deps.workRoot, 'gateway') })))();
      const onReap = (index: number, r: ReapResult): void => {
        const line = reapLine(`trial ${index} of run ${stored.id}`, `its replay in ${regrading}`, r);
        if (line !== null) log(line);
      };
      // The attempt's signal stops its replays once pg-boss gives the attempt up (regrade.ts's `stopping`): the reason thrown, retried.
      const stop = s.ctx?.signal === undefined ? {} : { signal: s.ctx.signal };
      // Each replayed trial's env-lane entry secrets, exactly those its live pass recorded, re-opened (the header's `entry
      // secrets`): its replay runs as live did. One erased since refuses the L2 before any trial replays; its L1 stands.
      const opened = await agentTrialSecrets(deps, { userId: sub.userId, competitionId: comp.id }, trialRows, regrading);
      if (opened.erased !== undefined) log(`[grade] ${comp.slug}: ${regrading} is refused unexecuted (${ENTRY_SECRETS_ERASED}): ${opened.erased}`);
      mask = opened.forms;
      outcome = await (deps.regradeAgentL2 ?? regradeAgentL2)({
        ...req,
        ...onePod,
        ...stop,
        runtime: picked.runtime,
        snapshot: { index: s.index, blobs },
        gateway,
        onReap,
        trialSecrets: opened.trialSecrets,
        ...(opened.erased === undefined ? {} : { secretsErased: opened.erased }),
        // The words of a once-run trial's first replay: a practice trial, or a staged final's entry cut at its first.
        phaseKey: ph.key,
      });
    }
    // An attempt given up records nothing, however far it got (an L1, or an L2's re-score, runs to its end): its retry records once.
    s.ctx?.signal?.throwIfAborted();
    return { run_id: await recordRegrade(db, blobs, outcome, ids, [], { mask }) };
  } catch (err) {
    if (err instanceof RegradeError) throw new PermanentJobError(err.message, { cause: err });
    throw err;
  }
}

// ---------------------------------------------------------------- agent/v1: the gateway

/** masq, as agent/v1 trials reach it (openAgentGateway). */
export interface AgentGateway {
  /** The broker each live pass mints its own key at (grader/gateway/masq.ts). */
  broker: MasqBroker;
  /** masq's origin as a trial's forwarder reaches it (config.llmGatewaySandboxUrl: MAKEFUN_LLM_GATEWAY_SANDBOX_URL, else MAKEFUN_LLM_GATEWAY_URL). */
  origin: string;
  /** ms before the first retry of a failed key retirement (default grader/agent.ts MASQ_RETIRE_BACKOFF_MS). */
  retireBackoffMs?: number;
}

/** What openAgentGateway reads of the server's config. */
export type AgentGatewayConfig = Pick<Config, 'llmGateway' | 'llmGatewayUrl' | 'llmGatewayAdminKey' | 'llmGatewaySandboxUrl'>;

/**
 * The gateway agent/v1 trials run against, as the server's config names it; null when
 * MAKEFUN_LLM_GATEWAY is off (server/config.ts agentTrialsRefusal), and then no trial runs in this
 * process. The broker is opened with masq.ts openMasqBroker, which reads the admin key's pin first: an
 * admin key masq reports unpinned, or pinned wider than a /24 (MasqAdminKeyRefusal), is paged at once,
 * and so is one masq itself refuses from this host's address (its 403 source-pin refusal, the same
 * class, problem `source`: the page names the address masq saw and the `masq keys admin-sources` line
 * that adds it); a masq that cannot be asked (MasqBrokerError) is logged. Either way the broker is
 * kept: its every mint reads the pin again until a read is good (a refusal is never held), so the
 * trials run once the operator pins the key, with no restart.
 */
export async function openAgentGateway(config: AgentGatewayConfig, opts: { page?: (line: string) => void; log?: (line: string) => void } = {}): Promise<AgentGateway | null> {
  if (agentTrialsRefusal(config) !== null) return null;
  const page = opts.page ?? ((line: string) => console.error(line));
  const log = opts.log ?? ((line: string) => console.log(line));
  const { MasqAdminKeyRefusal, MasqBrokerError, masqBrokerFromConfig, openMasqBroker } = await import('./gateway/masq.ts');
  let broker: MasqBroker | null;
  try {
    broker = await openMasqBroker(config);
  } catch (err) {
    if (err instanceof MasqAdminKeyRefusal) {
      page(
        err.problem === 'source'
          ? `[grade] ALERT: agent/v1 grading cannot mint a trial key: ${err.message}. Every agent/v1 trial's mint reads the pin again and fails the same way until it admits this host: its live passes void (up to ${AGENT_SERIES_PASSES} a series) and the trial is held, so nothing of the entry is scored. Fix the pin on the masq box, and the next mint picks it up with no restart`
          : `[grade] ALERT: agent/v1 grading is stopped: ${err.message}. No trial runs until then; nothing is marked, and every trial job tries again as it retries`,
      );
    } else if (err instanceof MasqBrokerError) {
      log(`[grade] masq could not be asked for its admin key's pin as the grader started (${err.message}); every trial's mint asks again`);
    } else {
      throw err;
    }
    broker = masqBrokerFromConfig(config);
  }
  const origin = config.llmGatewaySandboxUrl ?? config.llmGatewayUrl;
  if (broker === null || origin === null) return null;
  return { broker, origin };
}

/**
 * At a grader's start, the leftovers of a grader that crashed (Sandbox.networks sweepStale: on the
 * docker driver grader/sandbox/network.ts sweepStale, grader containers and trial networks older than
 * six hours), logged; nothing on the process driver. Never throws.
 */
export async function sweepStaleSandbox(sandbox: Sandbox, log: (line: string) => void = (line) => console.log(line)): Promise<void> {
  const networks = sandbox.networks;
  if (networks === undefined) return;
  try {
    const swept = await networks.sweepStale();
    if (swept.containers.length > 0 || swept.networks.length > 0 || swept.errors.length > 0) {
      log(`[grade] stale sandbox leftovers swept: ${swept.containers.length} containers, ${swept.networks.length} trial networks${swept.errors.length === 0 ? '' : `; not swept: ${swept.errors.join('; ')}`}`);
    }
  } catch (err) {
    log(`[grade] the stale sandbox leftovers could not be swept: ${err instanceof Error ? err.message : String(err)}`);
  }
}

/** A pipeline trial's owner (grader/agent.ts RunTrialOptions.owner, the makefun.trial label of its passes' networks): `<run id>.<trial index>`. */
export function trialOwner(runId: string, trialIndex: number): string {
  if (!Number.isSafeInteger(trialIndex) || trialIndex < 0) throw new TypeError(`trial index ${trialIndex} is not a non-negative integer`);
  return `${runId.toLowerCase()}.${trialIndex}`;
}

/**
 * Where a pipeline trial's pass works under the work root (`dead grader` in the header): its scratch,
 * the snapshot and the pass's own directory, and its scorer's, `trial-<owner>-XXXXXX` (regrade.ts
 * ownedScratch), which the trial's next pass removes should its grader die (regrade.ts reapScratch).
 */
export const TRIAL_SCRATCH_PREFIX = 'trial-';

/**
 * A grader job's owner, by the job's id: `regrade-<job id>`, the same on every attempt of the job and
 * no other job's, so its retry removes what an attempt that died left, and never a grade's trial
 * (`<run id>.<trial index>`) or another job's. An agent/v1 regrade's (regrade.ts
 * AgentRegradeL1Request.owner): its scratch, and each replay's containers and network, which run
 * under `regrade-<job id>.<trial index>`. Any other grade or regrade job's (grade.ts
 * GradeRequest.owner, regrade.ts RegradeL1Request.owner: the header's `scratch`): its executions' and
 * scorer's scratch. A hindsight audit job's: its audit's scratch (HINDSIGHT_SCRATCH_PREFIX). A job id
 * that is no part of a label value (pg-boss's are uuids) goes in as the first 32 hex digits of its
 * sha256.
 */
export function regradeOwner(jobId: string): string {
  const id = jobId.toLowerCase();
  return `regrade-${/^[a-z0-9][a-z0-9-]{0,63}$/.test(id) ? id : createHash('sha256').update(jobId, 'utf8').digest('hex').slice(0, 32)}`;
}

/**
 * The log line naming the scratch a reap of `what` removed before `before` (and what it could not); null when it found
 * nothing. `tag` opens it (default `grade`; a hindsight audit's `hindsight`).
 */
export function scratchReapLine(what: string, before: string, r: ScratchReap, tag = 'grade'): string | null {
  if (r.dirs.length === 0 && r.errors.length === 0) return null;
  return (
    `[${tag}] ${what}: before ${before}, removed the scratch a dead grader left of it (owner ${r.owner}): ` +
    `${r.dirs.length === 0 ? 'none' : r.dirs.join(', ')}${r.errors.length === 0 ? '' : `; not removed: ${r.errors.join('; ')}`}`
  );
}

/** The log line naming what a reap of `what` removed before `before` (and what it could not); null when it found nothing. */
export function reapLine(what: string, before: string, r: ReapResult): string | null {
  if (r.containers.length === 0 && r.networks.length === 0 && r.errors.length === 0) return null;
  const named = (xs: readonly string[]): string => (xs.length === 0 ? 'none' : xs.join(', '));
  return (
    `[grade] ${what}: before ${before}, removed what a dead grader left of it (makefun.trial=${r.owner}): ` +
    `containers ${named(r.containers)}; networks ${named(r.networks)}${r.errors.length === 0 ? '' : `; not removed: ${r.errors.join('; ')}`}`
  );
}

/**
 * What a dead grader left of trial `owner`, removed (Sandbox.networks reap: on the docker driver
 * grader/sandbox/network.ts reapTrial, the networks labelled with the owner and the containers on
 * each); null on the process driver, which makes no network. Never throws for what it could not
 * remove: the result says.
 */
export async function sandboxReap(sandbox: Sandbox, owner: string): Promise<ReapResult | null> {
  const networks = sandbox.networks;
  if (networks === undefined) return null;
  return networks.reap(owner);
}

/**
 * The isolation check of a sandbox's engine (the header's `isolation`): an IsolationCheck of its
 * Sandbox.networks isolation (grader/sandbox/network.ts isolationCheck, loaded here on first use),
 * on the docker driver this process's one EngineIsolation of its CLI, runtime and node22 image; null
 * on the process driver, which makes no network.
 */
export async function sandboxIsolation(sandbox: Sandbox): Promise<IsolationCheck | null> {
  const networks = sandbox.networks;
  if (networks === undefined) return null;
  const { isolationCheck } = await import('./sandbox/network.ts');
  return isolationCheck(networks);
}

// ---------------------------------------------------------------- agent/v1: house spend by lane

/**
 * A model lane a trial's spend is metered on apart (the header's `house lane`): the entry's calls, on harness.inference,
 * or with a target the env's calls to it, on harness.target. No contest-level limit weighs either (the header's `spend`).
 */
export type SpendLane = 'entry' | 'house';

/**
 * A lane's house spend summed over run_trial rows: its counted meter and every voided pass's (server/db/schema.ts runTrial's
 * SPEND). On the entry lane only the house's: a row whose entry lane ran on the entrant's own keys (entry_credential
 * entrant) spent the entrant's money, never the house's (the header's `entry lane`), so it is never counted as house
 * spend (server/routes/admin/inference.ts sums the competition's spend the same way).
 */
export function laneSpentSql(lane: SpendLane) {
  return lane === 'house'
    ? sql<string>`coalesce(sum(coalesce(${runTrial.houseSpendMicroUsd}, 0) + ${runTrial.voidedHouseSpendMicroUsd}), 0)::text`
    : sql<string>`coalesce(sum(case when ${runTrial.entryCredential} = 'house' then coalesce(${runTrial.spendMicroUsd}, 0) + ${runTrial.voidedSpendMicroUsd} else 0 end), 0)::text`;
}

/**
 * housePaysEntryLane over the submission table, for a query joined to it: a house entry, one a house account
 * submitted, or a baseline (standingsHouse || baseline is exactly house || submitted_as_house || baseline).
 */
export function housePaidSql() {
  return or(eq(submission.house, true), eq(submission.submittedAsHouse, true), eq(submission.baseline, true));
}

// ---------------------------------------------------------------- agent/v1: one trial

export interface AgentTrialDeps {
  db: Db;
  blobs: BlobStore;
  sandbox: Sandbox;
  /**
   * Existing directory for each pass's scratch (the snapshot, the pass's own directory, the scorer's:
   * `trial-<owner>-XXXXXX`, TRIAL_SCRATCH_PREFIX) and the forwarder's cache. A pass removes what a dead
   * grader's pass of its trial left here (the header's `dead grader`), so a grader that restarts on
   * the same work root leaves nothing of the trials it resumes.
   */
  workRoot: string;
  /** Where a void's re-run, a refused mint's later try and the fan-in's wake-ups are sent. */
  jobs: Pick<JobQueue, 'send'>;
  gateway: AgentGateway;
  /** The gateway forwarder (default grader/gateway/bundle.ts gatewayBundle, cached under <workRoot>/gateway). */
  forwarder?: () => Promise<Pick<GatewayBundle, 'dir' | 'script'>>;
  /** A competition's directory (default competitions/<slug>): its env and scorer. */
  competitionDir?(slug: string): string;
  /** MAKEFUN_SEALED_DIR: what each trial's instance_ref is relative to (default as GradeWorkerDeps.sealedDir). */
  sealedDir?: string;
  /**
   * The drand chain a staged final's draw is verified on as a contender's later trials are made (agentPhaseTrials; the
   * header's `staged final`): a dev-auth test chain besides quicknet (default as GradeWorkerDeps.drandChain).
   */
  drandChain?: DrandChain;
  /** Where a held trial, a refused admin key and a refused engine are paged (default console.error). */
  page?: (line: string) => void;
  log?: (line: string) => void;
  now?: () => Date;
  /** The engine check every live pass and replay passes first (the header's `isolation`; default sandboxIsolation(sandbox), null: none). */
  isolation?: IsolationCheck | null;
  /** The host's scrape lease, which a trial runs nothing beside under its `host` scope (the header's `scrape heat`; default scrapeLeaseDirFromEnv() and scrapeLeaseScopeFromEnv(), as GradeWorkerDeps.scrape's). */
  scrape?: Pick<ScrapeWorkerDeps, 'leaseDir' | 'leaseScope'>;
  /** How an entrant's pass opens its entrant's entry secrets and checks its provider keys (the header's `entry secrets`). */
  entrySecrets?: AgentEntrySecretDeps;
  /**
   * The free pod slots on the sandbox's node(s), every namespace's pods counted, or null when unknown (the header's `node
   * room`; default a K8sSandbox's nodePodRoom, none on any other driver).
   */
  podRoom?: () => Promise<number | null>;
  /**
   * superbot-router as a router-served target's house lane dials it, or null when none is configured, and then no such
   * pass starts (the header's `house lane`). Default: houseRouterOf(loadConfig()), read when such a pass first sets out.
   */
  houseRouter?: HouseRouter | null;
  /** What runs a live pass (default grader/agent.ts runTrial): a test's stand-in reads the upstream the pass was handed. */
  runTrial?: (opts: RunTrialOptions) => Promise<TrialPass>;
  /** What runs a replay (default grader/agent.ts runTrial): a test's stand-in reads what the replay was handed. */
  replayTrial?: (opts: RunTrialOptions) => Promise<TrialPass>;
  /**
   * The sandbox layout's inputs (the header's `layout`): a trial follows its run's flag, so only `host` is read here (a
   * flagged run's trial on `pod`; absent or null, such a trial refused as the platform's fault and held).
   */
  onePod?: OnePodDeps;
  /**
   * The server secret a `pod` pass's entry lane key is derived under (onePodEntryKey), as AgentAggregateDeps
   * .failKeySecret, under which the run's record carries the same keys: the two must be the same secret. Default as
   * GradeWorkerDeps.failKeySecret.
   */
  failKeySecret?: string;
}

/** The seal settings entry secrets open with (server/secrets/seal.ts entrySecretSealSettings). */
export type EntrySecretSealSettings = ReturnType<typeof entrySecretSealSettings>;

/** AgentTrialDeps.entrySecrets. */
export interface AgentEntrySecretDeps {
  /**
   * The grader's seal settings, whose private keys open an entrant's secrets (server/secrets/store.ts
   * openEntrySecretRows) and whose public key, or none, says whether an entrant can push one here at all
   * (EntrantKeys.entrySecrets: the no-key 401's words). Default: the environment's (entrySecretSealSettings of
   * loadConfig()), read when an entrant's pass first sets out.
   */
  seal?: EntrySecretSealSettings;
  /**
   * Each provider's origin and the certificates to trust instead of Node's, for both the pre-flight key check and the
   * forwarder's entrant lane (agent.ts EntrantKeys origins and ca): a test's fake provider. Default: each provider's own
   * origin (gateway/providers.ts PROVIDER_ORIGINS), verified against Node's certificates.
   */
  providers?: { origins?: Partial<Record<SecretProvider, string>>; ca?: string };
  /** The pre-flight's budget per key (default gateway/providers.ts KEY_CHECK_TIMEOUT_MS). */
  checkTimeoutMs?: number;
}

/** A grade-trial job's context as its handler reads it (JobQueue.work's): its id, the attempt's signal, its attempt and retry limit (isLastAttempt), and the priority it was sent at (queueTurn). */
export type AgentTrialContext = Pick<JobContext, 'id' | 'signal'> & Partial<Pick<JobContext, 'retryCount' | 'retryLimit' | 'priority'>>;

/** What one grade-trial job did (tests read it). */
export type AgentTrialOutcome =
  | { kind: 'done'; status: AgentTrialStatusT }
  | { kind: 'void'; reason: string; next: { pass: number; job_id: string | null; start_after: Date } }
  | { kind: 'held'; reason: string }
  | { kind: 'stopped'; why: string }
  /**
   * A pass on the entrant's own keys that did not start, waiting on one (the header's `entry secrets`): `refused` a key
   * its provider refused on the final, the run flagged ENTRY_SECRET_HELD_FLAG, `deadline` when the trial scores 0 if it
   * is still refused; `unreachable` a provider that gave no verdict, never the entrant's fault (`deadline` null). Its job
   * sent again for the next AGENT_PROVIDER_KEY_RECHECK_MS slot (`until`), or nothing sent once the competition is
   * resolved (`until` and `job_id` null). `reason`: the providers' words, redacted of every secret.
   */
  | { kind: 'key_wait'; why: 'refused' | 'unreachable'; until: Date | null; job_id: string | null; deadline: Date | null; reason: string }
  /**
   * A scrape heat held the host (scrapeHostHeldBy, `held_by` its words), or the node had no room for the trial's pods
   * (`held_by` saying so): nothing run, or what ran undone and counted as no pass, the job sent again for the next
   * recheck slot (the header's `scrape heat` and `node room`).
   */
  | { kind: 'waiting'; until: Date; job_id: string | null; held_by: string }
  /**
   * A pass that woke with no place in the queue (record.ts `queue tags`), sent ahead of the place it took (`tag`): its job
   * sent again at that place's priority, nothing run.
   */
  | { kind: 'queued'; tag: number; job_id: string | null }
  /**
   * A staged final's first trial scored while its phase's cut is undecided (the header's `staged final`): left at
   * live_done, its queue tag deferred, and the phase's final-cut job poked (`job_id` the poke's, null when this minute's
   * was sent already); the cut job wakes it once it decides. On a final that names earlier cuts, any qualifying trial
   * scored while its run's fate waits (the header's stages), `job_id` null too when the cut it waits on is decided and
   * nothing was poked.
   */
  | { kind: 'parked'; phase_id: string; job_id: string | null };

/** A trial another attempt claimed while this one was minting its key: this one runs nothing. */
class TrialTaken extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'TrialTaken';
  }
}

/**
 * A final pass whose entrant removed or replaced an env-lane entry secret it opened before it claimed the trial, its
 * sealed copy erased (erasedSinceOpened; the header's `entry secrets`): nothing claimed, and the pass sets out again
 * with the secrets as they stand, so no final trial records a row its challenge re-run cannot open.
 */
class PassSecretsErased extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PassSecretsErased';
  }
}

/** A fault after the live pass is recorded (its replay voided): retried, then held under `reason`, never a live re-run. */
class TrialHarnessFault extends Error {
  readonly reason: string;
  constructor(reason: string, message: string) {
    super(message);
    this.name = 'TrialHarnessFault';
    this.reason = reason;
  }
}

/**
 * A broker whose mint, once it has a key, claims the trial for the pass (claim) before the pass goes on, the entry's
 * key claiming and a target's house key (spec.role house, minted after it) recorded beside it (house; on an entrant's
 * pass, which mints no entry key, the house key's callback claims instead: the header's `entry lane`); the key is
 * disabled when either fails.
 */
function claimingBroker(broker: MasqBroker, claim: (minted: MintedTrialKey) => Promise<void>, house: (minted: MintedTrialKey) => Promise<void>): MasqBroker {
  return {
    origin: broker.origin,
    verifyAdminKey: (opts) => broker.verifyAdminKey(opts),
    async mint(spec, opts) {
      const minted = await broker.mint(spec, opts);
      try {
        await (spec.role === 'house' ? house(minted) : claim(minted));
      } catch (err) {
        await broker.disable(minted.id).catch(() => undefined);
        throw err;
      }
      return minted;
    },
    disable: (id, opts) => broker.disable(id, opts),
    spend: (id, opts) => broker.spend(id, opts),
  };
}

/** A blob's bytes as JSON, or an Error naming it (the store must hold what a trial row names). */
async function blobJson(blobs: BlobStore, sha256: string, what: string): Promise<unknown> {
  const bytes = await blobs.get(sha256, { verify: true });
  if (bytes === null) throw new Error(`the blob store holds no ${what} ${sha256}`);
  return JSON.parse(Buffer.from(bytes).toString('utf8')) as unknown;
}

/** A trial row's live pass is recorded and whole (what its replay and scoring read). */
function liveRecorded(row: TrialRow): boolean {
  return row.cassetteSha256 !== null && row.envLogSha256 !== null && row.stateSha256 !== null && row.outputsSha256 !== null && row.liveFinishedAt !== null;
}

/**
 * A claim of `row` for live pass `pass` undone (the header's `node room`): every field the claim set (passStart's, the
 * status, the lanes' keys and credential, a target's house key recorded after it) back as `row` had it, so the trial
 * stands as the pass found it and its next pass is the same `pass`.
 */
function unclaimed(row: TrialRow, pass: number, at: Date): TrialUpdate {
  const started = Object.keys(passStart(row, pass, at)) as (keyof TrialUpdate & keyof TrialRow)[];
  return {
    ...(Object.fromEntries(started.map((k) => [k, row[k]])) as TrialUpdate),
    status: row.status,
    masqKeyId: row.masqKeyId,
    houseMasqKeyId: row.houseMasqKeyId,
    entryCredential: row.entryCredential,
    entrySecretIds: row.entrySecretIds,
  };
}

/**
 * A live pass's start from `row` (a trial pending, or void): pass `pass` begins, and the void it
 * re-runs is cleared, its spend counted as voided spend (server/db/schema.ts runTrial).
 */
function passStart(row: TrialRow, pass: number, at: Date): TrialUpdate {
  return {
    attempt: pass,
    liveStartedAt: at,
    liveFinishedAt: null,
    replayStartedAt: null,
    replayFinishedAt: null,
    cassetteSha256: null,
    envLogSha256: null,
    stateSha256: null,
    outputsSha256: null,
    promptSha256: null,
    baselinePrompt: null,
    score: null,
    scoreSha256: null,
    checks: null,
    checksIssue: null,
    requests: null,
    spendMicroUsd: null,
    upstreamErrors: null,
    wallMs: null,
    voidedSpendMicroUsd: row.voidedSpendMicroUsd + (row.spendMicroUsd ?? 0n),
    houseCassetteSha256: null,
    houseSpendMicroUsd: null,
    voidedHouseSpendMicroUsd: row.voidedHouseSpendMicroUsd + (row.houseSpendMicroUsd ?? 0n),
  };
}

/**
 * What a live pass recorded, as a trial row holds it: the brief it copied among it (the header's `brief`), none when it
 * copied none, and with a target the house lane's cassette with its spend (houseSpend, that cassette's totals: houseSpendOf).
 */
function passRecord(p: TrialPass, at: Date, houseSpend: bigint | null): TrialUpdate {
  return {
    liveFinishedAt: at,
    wallMs: p.entry?.wall_ms ?? null,
    cassetteSha256: p.cassette_sha256,
    envLogSha256: p.env_log_sha256,
    stateSha256: p.state_sha256,
    outputsSha256: p.outputs_sha256,
    promptSha256: p.prompt_sha256,
    baselinePrompt: p.prompt_sha256 === null ? null : p.baseline_prompt,
    requests: p.totals?.requests ?? null,
    spendMicroUsd: p.totals === null ? null : BigInt(p.totals.micro_usd),
    upstreamErrors: p.totals?.upstream_errors ?? null,
    ...(p.masq === null ? {} : { masqKeyId: p.masq.key_id }),
    houseCassetteSha256: p.house_cassette_sha256,
    houseSpendMicroUsd: p.house_cassette_sha256 === null ? null : houseSpend,
    ...(p.house_masq === null ? {} : { houseMasqKeyId: p.house_masq.key_id }),
  };
}

/**
 * A pass's ending as the trial row records it (the header's `cut off`): live_done or timeout from a live pass,
 * finished or nondeterministic from a replay, with that ending's own reason and nothing older. A row keeps the void
 * reason and error of the void it re-runs while its next pass runs (liveCutOffRun reads them), a re-queued one its
 * hold's, and a replay claimed again the words of the replay cut off before it (replayCutOffRun): once a pass ends
 * otherwise they told of an attempt that no longer stands, so the void reason goes and the error holds only a
 * nondeterministic replay's fault (none for any other ending).
 */
export function trialEnding(status: 'live_done' | 'timeout' | 'finished'): TrialUpdate;
export function trialEnding(status: 'nondeterministic', error: string): TrialUpdate;
export function trialEnding(status: 'live_done' | 'timeout' | 'finished' | 'nondeterministic', error?: string): TrialUpdate {
  return { status, voidReason: null, error: status === 'nondeterministic' ? error! : null };
}

/** What a pass's calls to the target cost the house: its house cassette's totals (null with no house cassette). */
async function houseSpendOf(blobs: BlobStore, p: TrialPass): Promise<bigint | null> {
  if (p.house_cassette_sha256 === null) return null;
  const { readCassette } = await import('./gateway/cassette.ts');
  return BigInt((await readCassette(blobs, p.house_cassette_sha256)).totals.micro_usd);
}

/** A held trial's row: its void's record moved out (spend counted as voided), so it holds a live pass only when that pass is whole and its replay is what is left. */
function voidHeld(row: TrialRow): TrialUpdate {
  return {
    cassetteSha256: null,
    envLogSha256: null,
    stateSha256: null,
    outputsSha256: null,
    promptSha256: null,
    baselinePrompt: null,
    score: null,
    scoreSha256: null,
    checks: null,
    checksIssue: null,
    requests: null,
    spendMicroUsd: null,
    upstreamErrors: null,
    voidedSpendMicroUsd: row.voidedSpendMicroUsd + (row.spendMicroUsd ?? 0n),
    houseCassetteSha256: null,
    houseSpendMicroUsd: null,
    voidedHouseSpendMicroUsd: row.voidedHouseSpendMicroUsd + (row.houseSpendMicroUsd ?? 0n),
  };
}

/** What a trial job knows of the run it belongs to. */
/**
 * Whether the house pays an entry's own model calls (the header's `entry lane`): a house entry (submission.house), an
 * entry a house account submitted (submitted_as_house) or a baseline (the house's reference, whoever entered
 * it). Its live pass then runs on a masq key of its own. Any other entry is an entrant's, whose model calls house money
 * never pays: its live pass runs its entry lane on the entrant's own keys, model-free while none is pushed. The house
 * here is standingsHouse's (server/payouts/standings.ts), baselines added: a baseline no house account entered is
 * placed as no house entry, and the house still runs it. The house's entries run with no entry secret of any lane.
 */
export function housePaysEntryLane(sub: HouseFacts): boolean {
  return standingsHouse(sub) || sub.baseline;
}

/**
 * The entrant's own keys an entry's live passes start from (the header's `entry lane`), or null for an entry the house
 * pays (housePaysEntryLane): none, which is what a pass runs on while its entrant has no provider key pushed (model-free,
 * each call answered 401 by the forwarder). The keys a pass runs on are read from the entrant's secrets as the pass sets
 * out (the header's `entry secrets`: the handler's entrantLane), never from the entry.
 */
export function entrantKeysOf(sub: HouseFacts): EntrantKeys | null {
  return housePaysEntryLane(sub) ? null : { keys: {}, mask: [] };
}

/**
 * An entrant's entry whose passes ran on no provider key (entrantKeysOf): each model call of theirs was answered 401 by
 * the gateway. Given the run's trials, only when none of their latest passes ran with a provider-lane entry secret: none
 * of their entry_secret_ids among `providerSecretIds` (the provider-lane rows of those ids; an env-lane secret pays for
 * no model call). A run of it refused for calling no model then says which key is missing.
 */
export function keylessEntry(sub: HouseFacts, trials: readonly Pick<TrialRow, 'entrySecretIds'>[] = [], providerSecretIds: ReadonlySet<string> = new Set()): boolean {
  const own = entrantKeysOf(sub);
  return own !== null && Object.values(own.keys).every((k) => k === undefined) && trials.every((t) => (t.entrySecretIds ?? []).every((id) => !providerSecretIds.has(id)));
}

/** Of `ids` (entry_secret rows), those on the provider lane: what keylessEntry weighs a run's trials by. */
async function providerSecretIdsOf(db: Pick<Db, 'select'>, ids: readonly string[]): Promise<Set<string>> {
  const wanted = [...new Set(ids)];
  if (wanted.length === 0) return new Set();
  const rows = await db
    .select({ id: entrySecret.id })
    .from(entrySecret)
    .where(and(inArray(entrySecret.id, wanted), eq(entrySecret.lane, 'provider')));
  return new Set(rows.map((r) => r.id));
}

/** A provider key a pass opened (the header's `entry secrets`): its row's id, NAME, provider and hint, and the key, which is never stored, logged or thrown. */
interface OpenedProviderKey {
  id: string;
  name: string;
  provider: SecretProvider;
  hint: string;
  key: string;
}

/** A key's provider's verdict on it (gateway/providers.ts KeyCheck), its words redacted of every secret of the pass. */
interface ProviderKeyVerdict {
  id: string;
  name: string;
  provider: SecretProvider;
  hint: string;
  check: KeyCheck;
}

/**
 * The entry secrets a pass runs with (the header's `entry secrets`), opened: `ids` every row it runs with, both lanes
 * (run_trial.entry_secret_ids), `env` the env lane's NAME to value (the entry's SandboxSpec.secrets), `forms` every form
 * of every value the pass holds (both lanes, and the ids the key check learned) for what it says and stores, and
 * `byName` each value by NAME, for the scan of its outputs. No value is stored, logged or thrown.
 */
interface PassSecrets {
  ids: string[];
  env: Record<string, string>;
  forms: FormSet;
  byName: Record<string, string>;
}

/**
 * Whose keys a live pass's entry lane runs on (the header's `entry lane`): the house's on masq, with no entry secret, or
 * the entrant's own (`own` what the forwarder is given, `secrets` the entry secrets the pass runs with).
 */
type EntryLane = { credential: 'house' } | { credential: 'entrant'; own: EntrantKeys; secrets: PassSecrets };

/**
 * What the trial row records of a pass's entry lane as it claims it (server/db/schema.ts runTrial's CREDENTIAL): the
 * credential, and the entry_secret rows an entrant's pass runs with (a list, empty with none pushed, as the table's
 * run_trial_entry_secrets_entrant check holds entry_credential to it; null on the house's).
 */
function laneCredential(lane: EntryLane): Pick<TrialUpdate, 'entryCredential' | 'entrySecretIds'> {
  return lane.credential === 'house' ? { entryCredential: 'house', entrySecretIds: null } : { entryCredential: 'entrant', entrySecretIds: lane.secrets.ids };
}

/**
 * What an entrant's pass found as it set out (the handler's entrantLane; the header's `entry secrets`): `run` on these
 * keys and secrets (none pushed: none, model-free), or why not now: `unopened` this grader cannot open them (`error`
 * naming no value), `refused` a provider refused a key, `unreachable` a provider gave no verdict on one (`verdicts`
 * those keys', their words redacted of every secret; `ids` every row the pass would run with; `forms` every secret's
 * forms, to redact what is said of them).
 */
type EntrantLaneVerdict =
  | { kind: 'run'; lane: Extract<EntryLane, { credential: 'entrant' }> }
  | { kind: 'unopened'; ids: string[]; error: string }
  | { kind: 'refused'; ids: string[]; verdicts: ProviderKeyVerdict[]; forms: FormSet }
  | { kind: 'unreachable'; ids: string[]; verdicts: ProviderKeyVerdict[]; forms: FormSet };

/** A verdict on a key in a message: the provider's words (already redacted), and which secret it was (its NAME and hint, never the key). */
function keyVerdictWords(v: ProviderKeyVerdict): string {
  const name = SECRET_PROVIDER_NAME[v.provider];
  const said = v.check.state === 'valid' ? `${name} accepted the key` : v.check.reason;
  return `${said} (its entry secret ${v.name}, ${v.hint})`;
}

/** What pushes a working key in place of each refused one, in a message: its NAME in a .env, and the command. */
function keyFixWords(slug: string, verdicts: readonly ProviderKeyVerdict[]): string {
  const names = [...new Set(verdicts.map((v) => v.name))];
  return `${names.map((n) => `${n}=<a working key>`).join(' and ')} in a .env, pushed with \`makefun secrets push ${slug} --env-file .env\``;
}

/** What a refused key's trial exports (keyRefusedRecord): an empty store state, canonical JSON with its newline, as an env's export ends. */
const KEY_REFUSED_STATE = '{}\n';

/**
 * The record of a trial that scores 0 for a key its provider refused (the header's `entry secrets`), nothing run: a cassette
 * with no entry (with a target, the house lane's the same), an empty env log and an export of an empty state.json, each
 * stored as a pass stores them, so the fan-in, the trials manifest and a regrade read the trial as any timeout's: its
 * points 0 on every column, its export never scored, never replayed. Nothing was spent: its meter is 0. Its cassettes are
 * stamped with `pricingRev`, its run's (trialPricingRev), so the run's trials still name one revision.
 */
export async function keyRefusedRecord(blobs: Pick<BlobStore, 'put'>, row: Pick<TrialRow, 'trialIndex' | 'instanceSha256'>, target: boolean, pricingRev: string): Promise<TrialUpdate> {
  const { CassetteWriter } = await import('./gateway/cassette.ts');
  const trial = { index: row.trialIndex, instance_sha256: row.instanceSha256 };
  const cassette = await new CassetteWriter({ trial, pricing_rev: pricingRev, blobs }).finish();
  const house = target ? await new CassetteWriter({ trial, pricing_rev: pricingRev, blobs }).finish() : null;
  const state = await blobs.put(KEY_REFUSED_STATE);
  const envLog = await blobs.put(new Uint8Array(0));
  const outputs: TrialOutputsT = { format: TRIAL_OUTPUTS_FORMAT, files: [{ path: 'state.json', size: state.size, sha256: state.sha256 }] };
  const manifest = await blobs.put(canonicalJson(outputs));
  return {
    cassetteSha256: cassette.sha256,
    envLogSha256: envLog.sha256,
    stateSha256: state.sha256,
    outputsSha256: manifest.sha256,
    requests: 0,
    spendMicroUsd: 0n,
    upstreamErrors: 0,
    wallMs: null,
    houseCassetteSha256: house?.sha256 ?? null,
    houseSpendMicroUsd: house === null ? null : 0n,
  };
}

/**
 * The pricing revision a live pass of `row`'s trial meters both lanes on (the header's `pricing`; spend-revision.ts
 * runPricingRev): the one the cassette of its run's lowest-index trial with a cassette names, else `sub`'s receipt's
 * (submission.pricing_rev; the bundled table for an entry that names none). A revision this grader holds no table of is
 * a PlatformFaultError (server/jobs.ts): the platform's fault, never the entry's, the trial held as on any.
 */
export async function trialPricingRev(
  db: Pick<Db, 'select'>,
  blobs: Pick<BlobStore, 'get'>,
  sub: Pick<typeof submission.$inferSelect, 'id' | 'pricingRev'>,
  row: Pick<TrialRow, 'runId' | 'trialIndex'>,
): Promise<string> {
  const [{ readCassette }, { PricingRevisionNotHeldError }, { pricingRev: bundled }] = await Promise.all([import('./gateway/cassette.ts'), import('./gateway/policy.ts'), import('../pricing/price.ts')]);
  const recorded = await db
    .select({ index: runTrial.trialIndex, cassette: runTrial.cassetteSha256 })
    .from(runTrial)
    .where(and(eq(runTrial.runId, row.runId), isNotNull(runTrial.cassetteSha256)));
  try {
    return await runPricingRev(
      recorded.map((t) => ({ index: t.index, pricingRev: async () => (await readCassette(blobs, t.cassette!)).pricing_rev })),
      sub.pricingRev ?? bundled,
    );
  } catch (err) {
    if (!(err instanceof PricingRevisionNotHeldError)) throw err;
    throw new PlatformFaultError(
      `trial ${row.trialIndex} of run ${row.runId} (entry ${sub.id}) is metered on its run's pricing revision ${err.pricing_rev}, which this grader holds no table of (pricing/revs.ts): nothing is run; deploy a release that keeps pricing/revs/${err.pricing_rev}.json, then re-queue the trial`,
      { cause: err },
    );
  }
}

/**
 * `text` with every form of the pass's secrets redacted (gateway/upstream.ts redactForms, with the keys' echoed runs:
 * gateway/providers.ts redactKeys, loaded by then); as it is when there are none.
 */
type Redact = (text: string) => string;

/** The identity Redact: a pass that holds no secret. */
const NO_REDACT: Redact = (text) => text;

/** `err` with its message and stack redacted (`redact`), so what is thrown on carries no secret: the same object when nothing changed. */
function redactedError(err: unknown, redact: Redact): unknown {
  if (!(err instanceof Error)) return typeof err === 'string' ? redact(err) : err;
  const message = redact(err.message);
  const stack = err.stack === undefined ? undefined : redact(err.stack);
  if (message === err.message && stack === err.stack) return err;
  try {
    err.message = message;
    if (stack !== undefined) err.stack = stack;
    return err;
  } catch {
    // A frozen error: a plain one in its place, its words redacted.
    return new Error(message);
  }
}

/** A Redact over `forms` (every form of the pass's secrets) and `keys` (the provider keys, whose echoed runs go too); NO_REDACT with neither. */
async function redactorOf(forms: FormSet | null, keys: readonly string[] = []): Promise<Redact> {
  if (forms === null && keys.length === 0) return NO_REDACT;
  const [{ redactForms }, { redactKeys }] = await Promise.all([import('./gateway/upstream.ts'), import('./gateway/providers.ts')]);
  const held = keys.filter((k) => k !== '');
  return (text) => {
    const k = held.length === 0 ? text : redactKeys(text, held);
    return forms === null ? k : redactForms(k, forms);
  };
}

interface TrialRunContext {
  run: RunRow;
  sub: typeof submission.$inferSelect;
  ph: typeof phase.$inferSelect;
  slug: string;
  /** The competition's status as the job read it: a resolved one sends no pass waiting on its entrant's provider key again (the header's `entry secrets`). */
  competitionStatus: (typeof competition.$inferSelect)['status'];
  bundle: CompetitionBundleT;
  harness: AgentHarnessT;
  setup: AgentSetup;
  index: SnapshotIndex;
  runtime: Runtime;
  /** The run's layout, by its flag (ONE_POD_FLAG), never the table (the header's `layout`). */
  layout: SandboxLayout;
  /** The sandbox its passes, scorer and scratch go to: on `pod` the one-pod view (a pass's one pod; its removeTree the base's, no pod), else the grader's. */
  sandbox: Sandbox;
  /** On `pod` this process's host of it (its lanes client made on the first pass that needs it), else null. */
  onePod: OnePodHost | null;
}

/**
 * The grade-trial job handler (the header's `agent/v1`): it moves one trial on from where its row
 * stands, as far as this job's pass reaches, and answers what it did. Run by JobQueue.work, it is
 * handed the attempt's signal, which runTrial stops every program of the pass on.
 */
export function createAgentTrialHandler(deps: AgentTrialDeps): (data: JobPayload<'grade-trial'>, ctx: AgentTrialContext) => Promise<AgentTrialOutcome> {
  const { db, blobs, sandbox } = deps;
  const now = deps.now ?? (() => new Date());
  const page = deps.page ?? ((line: string) => console.error(line));
  const log = deps.log ?? ((line: string) => console.log(line));
  const sealedDir = deps.sealedDir ?? sealedDirFromEnv();
  let forwarder: Promise<Pick<GatewayBundle, 'dir' | 'script'>> | null = null;
  const forwarderOf = (): Promise<Pick<GatewayBundle, 'dir' | 'script'>> => {
    if (forwarder === null) {
      const building = (deps.forwarder ?? (async () => (await import('./gateway/bundle.ts')).gatewayBundle({ cacheDir: join(deps.workRoot, 'gateway') })))();
      forwarder = building;
      building.catch(() => {
        if (forwarder === building) forwarder = null;
      });
    }
    return forwarder;
  };
  /** When each refusal message was last paged (AGENT_REFUSAL_PAGE_MS). */
  const refusalsPaged = new Map<string, number>();
  /** What the isolation lines call this sandbox's engine (its driver's). */
  const engineName = ISOLATION_ENGINES[isolationDriverOf(sandbox)];
  /** When each set of providers no entrant's key could be checked with was last paged (AGENT_REFUSAL_PAGE_MS). */
  const unreachablePaged = new Map<string, number>();
  /** The seal settings an entrant's secrets open with (AgentEntrySecretDeps.seal, else the environment's), read when an entrant's pass first sets out. */
  let sealSettings: EntrySecretSealSettings | null = null;
  const sealOf = async (): Promise<EntrySecretSealSettings> => {
    if (sealSettings === null) {
      const own = deps.entrySecrets?.seal;
      sealSettings = own ?? (await import('../server/secrets/seal.ts')).entrySecretSealSettings(loadConfig());
    }
    return sealSettings;
  };
  /** The house router (AgentTrialDeps.houseRouter, else the environment's), read when a router-served target's pass first sets out. */
  let houseRouterRead: HouseRouter | null | undefined = deps.houseRouter;
  /**
   * What a pass's house lane runs on superbot-router with (the header's `house lane`): null for a pass with no target or
   * one naming no router house id (masq, as ever). A target naming one beside any other model, or one on a grader with
   * no house router configured, is a HouseRouterRefusal before anything is minted or claimed: never masq for it.
   */
  const routerLaneOf = (c: TrialRunContext): HouseRouter | null => {
    const models = c.harness.target?.models;
    if (models === undefined || !models.some((m) => routerModel(m) !== null)) return null;
    if (!targetOnRouter(models)) {
      const others = models.filter((m) => routerModel(m) === null);
      throw new HouseRouterRefusal(
        `${c.slug}'s house players run on superbot, dialled on superbot-router alone, which serves its own models only, yet its target names ${others.join(', ')} beside them: harness.target.models names router models alone, or none`,
        { waitsOn: 'a target that names router models alone', once: "the competition's bundle names router models alone in harness.target.models" },
      );
    }
    if (houseRouterRead === undefined) houseRouterRead = houseRouterOf(loadConfig());
    if (houseRouterRead === null) {
      throw new HouseRouterRefusal(`${c.slug}'s house players run on superbot, dialled on superbot-router alone: set MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_HOUSE_KEY`, {
        waitsOn: "superbot-router's house lane key",
        once: 'MAKEFUN_SUPERBOT_ROUTER_URL and MAKEFUN_SUPERBOT_ROUTER_HOUSE_KEY are set and the grader restarted',
      });
    }
    return houseRouterRead;
  };

  /** The engine check (the header's `isolation`): the deps', else this process's probe of a docker sandbox's engine; null on the process driver. */
  let isolationOf: Promise<IsolationCheck | null> | null = null;
  const isolation = (): Promise<IsolationCheck | null> => (isolationOf ??= deps.isolation !== undefined ? Promise.resolve(deps.isolation) : sandboxIsolation(sandbox));
  /** Before a pass mints, claims or makes a network: an IsolationRefusal on an engine that does not keep trials apart. */
  const requireIsolation = async (): Promise<void> => {
    const check = await isolation();
    if (check !== null) await check.require();
  };

  // As the grader starts: the engine probed in the background (the first pass waits on that same probe), a refusal paged at once.
  void (async () => {
    const check = await isolation();
    if (check === null) return;
    let v: IsolationVerdict;
    try {
      v = await check.verdict();
    } catch (err) {
      log(`[grade] this ${engineName}'s trial isolation could not be probed as the grader started (${err instanceof Error ? err.message : String(err)}); every live pass and replay probes it again first`);
      return;
    }
    if (v.enforced) {
      log(`[grade] trial isolation holds on this ${engineName} (${v.engine}): ${v.detail}`);
      return;
    }
    const refusal = new (await import('./sandbox/network.ts')).IsolationRefusal(v);
    refusalsPaged.set(refusal.message, now().getTime());
    page(`[grade] ALERT: agent/v1 grading is stopped: ${refusal.message}. No trial runs in this process until then: nothing is marked, and each trial job tries again as it retries.`);
  })().catch((err: unknown) => console.error('[grade] the isolation probe at the grader\'s start could not report:', err));

  const trialRow = async (data: JobPayload<'grade-trial'>): Promise<TrialRow | null> => {
    const [row] = await db
      .select()
      .from(runTrial)
      .where(and(eq(runTrial.runId, data.run_id), eq(runTrial.trialIndex, data.trial_index)));
    return row ?? null;
  };

  /** The run's facts, or why there is nothing to run (the run is over, or its entry is out). */
  const runContext = async (data: JobPayload<'grade-trial'>): Promise<TrialRunContext | { stopped: string }> => {
    const [r] = await db.select().from(run).where(eq(run.id, data.run_id));
    if (r === undefined) return { stopped: `run ${data.run_id} does not exist` };
    if (r.status !== 'running') return { stopped: `run ${r.id} is ${r.status}: its trials run no more` };
    const sub = await one(db.select().from(submission).where(eq(submission.id, r.submissionId)), `submission ${r.submissionId}`);
    if (sub.status === 'cancelled') return { stopped: `submission ${sub.id} was cancelled: its trials run no more` };
    // A refusal that stands (server/pipeline/publish.ts isRefused): a duplicate snapshot, a committed secret, or an admin's security-audit refusal.
    const refusal = await import('../server/pipeline/publish.ts');
    if (refusal.isRefused(sub)) {
      const why = refusal.isRefusedDuplicate(sub) ? 'refused as a duplicate snapshot' : 'refused for a secret committed in its code';
      return { stopped: `submission ${sub.id} was ${why}: its trials run no more` };
    }
    const ph = await one(db.select().from(phase).where(eq(phase.id, r.phaseId)), `phase ${r.phaseId}`);
    const comp = await one(db.select().from(competition).where(eq(competition.id, ph.competitionId)), `competition ${ph.competitionId}`);
    const parsed = comp.bundle === null ? null : CompetitionBundle.safeParse(comp.bundle);
    if (parsed === null || !parsed.success) throw new PermanentJobError(`competition ${comp.slug} has no bundle that validates`);
    const bundle = parsed.data;
    if (bundle.harness.kind !== 'agent/v1') throw new PermanentJobError(`${comp.slug} is a ${bundle.harness.kind} competition: it runs no agent/v1 trial`);
    if (sub.snapshotSha256 === null) throw new PermanentJobError(`submission ${sub.id} has no snapshot`);
    const index = await readSnapshotIndex(blobs, sub.snapshotSha256);
    const picked = entryRuntime(index, bundle.harness.runtimes);
    if ('error' in picked) throw new PermanentJobError(`submission ${sub.id}: ${picked.error}`);
    const compDir = competitionDirOf(deps, comp.slug, bundle.harness);
    // The run's layout by its flag, read with the run (the header's `layout`): a flagged run's trial runs on `pod` in any
    // process that can host it, and one that cannot refuses it as the platform's fault (held as any fault no retry mends).
    const layout: SandboxLayout = r.flags.includes(ONE_POD_FLAG) ? 'pod' : 'split';
    const host = layout === 'pod' ? onePodHostOf(deps.onePod, `${comp.slug}: trial ${data.trial_index} of run ${r.id}`) : null;
    return {
      run: r,
      sub,
      ph,
      slug: comp.slug,
      competitionStatus: comp.status,
      bundle,
      harness: bundle.harness,
      // Its slug keys its house clock (grader/house-clock.ts): a competition with a row there has its passes' walls moved by it.
      setup: { compDir, harness: bundle.harness, leaderboard: bundle.leaderboard, competition: comp.slug },
      index,
      runtime: picked.runtime,
      layout,
      sandbox: host === null ? sandbox : host.view(),
      onePod: host,
    };
  };

  const instanceDirOf = (row: TrialRow): string => join(sealedDir, ...row.instanceRef.split('/'));
  const trialRef = (row: TrialRow) => ({ index: row.trialIndex, instance_sha256: row.instanceSha256 });
  /**
   * A trial's job sent again: its expiry, and its priority from its place in the queue (record.ts `queue tags`), which a
   * platform `fault` keeps (faultTrialQueueTag: one charge behind the head at most) and a `deferral` its contest's own
   * policy made clears (deferTrialQueueTag: the job that wakes takes a fresh one, queueTurn).
   */
  const sendOptions = async (c: TrialRunContext, trial: Pick<TrialRow, 'runId' | 'trialIndex'>, why: 'fault' | 'deferral') => {
    const wall = c.bundle.limits.wall_budget_sec;
    const tag = why === 'fault' ? await faultTrialQueueTag(db, trial, wall) : await deferTrialQueueTag(db, trial);
    return { priority: gradeTrialPriority(tag ?? 0), expireInSeconds: agentTrialExpirySeconds(wall, c.slug) };
  };
  const what = (row: Pick<TrialRow, 'runId' | 'trialIndex'>) => `trial ${row.trialIndex} of run ${row.runId}`;
  /** The trial's owner: the makefun.trial label of its passes' networks and the name of its scratch, by which the next pass removes what a dead grader left. */
  const ownerOf = (row: Pick<TrialRow, 'runId' | 'trialIndex'>) => trialOwner(row.runId, row.trialIndex);
  /** A reap's names logged (reapLine), when it found anything. */
  const logReap =
    (row: Pick<TrialRow, 'runId' | 'trialIndex'>, before: string) =>
    (r: ReapResult): void => {
      const line = reapLine(what(row), before, r);
      if (line !== null) log(line);
    };
  /**
   * The scratch a dead grader left of the trial (every `trial-<owner>-XXXXXX` under the work root but
   * `keep`, this pass's own) removed and logged by name (scratchReapLine). Run once the trial is the
   * pass's (its row claimed, or a cut-off pass declared over), so what carries its owner then is a dead pass's.
   * What it removed is released from the sandbox's daemon as the reap ends (regrade.ts reapScratch), or, given
   * `released`, handed there for the pass to release with its own scratch once it is over (grade.ts releaseScratch).
   * `on` is the run's sandbox (TrialRunContext.sandbox: on `pod` the one-pod view, whose removeTree is the base's: every member's tree came back as the grader's own, so the grader deletes it itself, no pod).
   */
  const reapDeadScratch = async (on: Sandbox, row: Pick<TrialRow, 'runId' | 'trialIndex'>, before: string, keep: string | null = null, released?: string[]): Promise<void> => {
    const line = scratchReapLine(what(row), before, await reapScratch(on, deps.workRoot, TRIAL_SCRATCH_PREFIX, ownerOf(row), keep, released));
    if (line !== null) log(line);
  };

  /**
   * A pass in a fresh scratch directory of its own, named for the trial's owner (`trial-<owner>-XXXXXX`):
   * the snapshot materialized at <dir>/bot, the pass's work directory beside it; all removed after, and released from
   * the sandbox's daemon then (grade.ts removeScratch), or, given `released`, handed there for the pass's one release.
   */
  const inScratch = async <T>(c: TrialRunContext, row: Pick<TrialRow, 'runId' | 'trialIndex'>, fn: (dirs: { dir: string; botDir: string; workDir: string }) => Promise<T>, released?: string[]): Promise<T> => {
    const dir = await ownedScratch(deps.workRoot, TRIAL_SCRATCH_PREFIX, ownerOf(row));
    const botDir = join(dir, 'bot');
    const workDir = join(dir, 'work');
    try {
      await materializeSnapshot(c.index, blobs, botDir);
      await mkdir(workDir, { mode: 0o700 });
      return await fn({ dir, botDir, workDir });
    } finally {
      await removeMaterialized(botDir).catch(() => undefined);
      await removeScratch(c.sandbox, dir, released);
    }
  };

  /** The fan-in, told a trial is done (each trial's end once: the wait slot looks again either way), and the grader's log. */
  const poke = async (row: TrialRow): Promise<void> => {
    log(`[grade] ${what(row)}: ${row.status} after live pass ${row.attempt} on the ${sandbox.kind} sandbox; its run's fan-in is told`);
    try {
      await deps.jobs.send('grade-aggregate', { run_id: row.runId }, { id: gradeAggregateJobId(row.runId, `trial:${row.trialIndex}:${row.attempt}:${row.status}`) });
    } catch (err) {
      log(`[grade] ${what(row)} is ${row.status}, and its run's fan-in could not be told (${err instanceof Error ? err.message : String(err)}); its next wait slot looks`);
    }
  };

  /** Hold the trial (the run flagged trial_held in the same transaction) and page the admins; 'again' when the row moved meanwhile. */
  const hold = async (row: TrialRow, reason: string, error: string, c: TrialRunContext | null, extra: TrialUpdate = {}): Promise<AgentTrialOutcome | 'again'> => {
    const held = await db.transaction(async (tx) => {
      const moved = await moveTrial(tx, row, { ...extra, status: 'held', voidReason: reason, error });
      if (moved === null) return null;
      await addRunFlags(tx, row.runId, [TRIAL_HELD_FLAG]);
      return moved;
    });
    if (held === null) return 'again';
    // Whether the fan-in re-queues it by itself (an audit read that fails pages it as one for an admin alone).
    page(trialHeldPage(held, heldTrialOf(c), await selfRequeueOf(db, held).catch(() => null)));
    return { kind: 'held', reason };
  };

  /**
   * A void of pass `row.attempt` recorded: the series spent, the trial is held; else the next pass is sent its job. A
   * pass cut off (INTERRUPTED_VOID_REASON: its grader died, or its attempt stopped or expired; the header's `cut off`)
   * spends no pass of the series: the next pass's series starts one later (first_pass + 1), so the passes it counts are
   * the same; the AGENT_INTERRUPTED_RERUNS-th cut off in a row holds the trial instead. A dev pass whose practice instance
   * was re-drawn under it (INSTANCE_REDRAWN_VOID_REASON; the header's `re-drawn practice`) spends none either. An
   * upstream_errors void's next pass waits longer for each re-run of its series (agentVoidRerunDelayMs), whatever
   * `delayMs` its caller gave.
   */
  const voided = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, delayMs: number): Promise<AgentTrialOutcome | 'again'> => {
    const reason = row.voidReason ?? 'void';
    const pass = row.attempt + 1;
    let firstPass = data.first_pass;
    let spends = '';
    let waitMs = delayMs;
    if (reason === INTERRUPTED_VOID_REASON) {
      const inARow = Math.max(1, liveCutOffRun(row, row.attempt));
      if (inARow >= AGENT_INTERRUPTED_RERUNS) {
        return hold(row, reason, `${inARow} live passes in a row voided, the last (pass ${row.attempt}) of ${reason}: ${row.error ?? 'no detail'}`, c, voidHeld(row));
      }
      firstPass = Math.min(data.first_pass + 1, pass);
      spends = `, ${inARow} of ${AGENT_INTERRUPTED_RERUNS} cut off in a row, which spends no pass of its series`;
    } else if (reason === INSTANCE_REDRAWN_VOID_REASON) {
      // Its practice instance re-drawn under it (the header's `re-drawn practice`): the release's doing, never the entry's.
      firstPass = Math.min(data.first_pass + 1, pass);
      spends = ', its practice instance re-drawn under it, which spends no pass of its series';
    } else {
      const spent = row.attempt - data.first_pass + 1;
      if (spent >= AGENT_SERIES_PASSES) {
        return hold(row, reason, `${spent} live passes in a row voided, the last (pass ${row.attempt}) of ${reason}: ${row.error ?? 'no detail'}`, c, voidHeld(row));
      }
      // The next pass is re-run `spent` of the series.
      if (reason === UPSTREAM_ERRORS_VOID_REASON) waitMs = agentVoidRerunDelayMs(reason, spent);
    }
    const startAfter = new Date(now().getTime() + waitMs);
    const jobId = await deps.jobs.send('grade-trial', { ...data, pass, first_pass: firstPass }, { id: gradeTrialJobId(row.runId, row.trialIndex, pass), startAfter, ...(await sendOptions(c, row, 'fault')) });
    log(`[grade] ${what(row)}: live pass ${row.attempt} voided (${reason}${spends}); pass ${pass} of ${firstPass + AGENT_SERIES_PASSES - 1} runs from ${startAfter.toISOString()}`);
    return { kind: 'void', reason, next: { pass, job_id: jobId, start_after: startAfter } };
  };

  /**
   * A scrape heat holds the host (the header's `scrape heat`): nothing run, the job sent again for the next recheck slot
   * (one job of a pass and series a slot), so the trial spends none of its expiry on the heat.
   */
  const waitOutHeat = async (c: TrialRunContext, data: JobPayload<'grade-trial'>, heldBy: string): Promise<AgentTrialOutcome> => {
    const slot = scrapeHostRecheckSlot(now().getTime());
    const until = new Date(slot * SCRAPE_HOST_RECHECK_MS);
    // A trial yet to start its live pass waits on the host's policy and takes a fresh place as it wakes; one further on keeps its own.
    const row = await trialRow(data);
    const why = row !== null && (row.status === 'pending' || row.status === 'void') ? 'deferral' : 'fault';
    const jobId = await deps.jobs.send('grade-trial', data, {
      id: gradeTrialJobId(data.run_id, data.trial_index, data.pass, `scrape-wait:${data.first_pass}:${slot}`),
      startAfter: until,
      ...(await sendOptions(c, { runId: data.run_id, trialIndex: data.trial_index }, why)),
    });
    log(`[grade] ${what({ runId: data.run_id, trialIndex: data.trial_index })}: pass ${data.pass} waits for ${until.toISOString()}: ${heldBy}, and nothing else grades here while a heat runs`);
    return { kind: 'waiting', until, job_id: jobId, held_by: heldBy };
  };

  /** The nodes' free pod slots (the header's `node room`): the deps', else a K8sSandbox's own read, each node counted past NODE_POD_HEADROOM; none on any other driver. */
  const podRoom: (() => Promise<number | null>) | null = deps.podRoom ?? (sandbox instanceof K8sSandbox ? () => sandbox.nodePodRoom(NODE_POD_HEADROOM) : null);
  /** Why the node has no room for `pods` more sandbox pods now (nodeHasRoom: NODE_POD_HEADROOM kept free), or null when it has, or none can be told. */
  const roomShort = async (pods: number): Promise<string | null> => {
    if (podRoom === null) return null;
    const room = await podRoom().catch(() => null);
    return nodeHasRoom(room, pods) ? null : `the node has ${room} pod slots free, ${NODE_POD_HEADROOM} of them kept free, and this needs ${pods}`;
  };

  /**
   * The node had no room for the trial's pods (the header's `node room`): nothing more run, the job sent again for the
   * next recheck slot (one job of a pass, series and slot), so the trial waits for room spending no pass and none of its
   * expiry.
   */
  const waitForRoom = async (c: TrialRunContext, data: JobPayload<'grade-trial'>, why: string): Promise<AgentTrialOutcome> => {
    const slot = nodeRoomRecheckSlot(now().getTime());
    const until = new Date(slot * NODE_ROOM_RECHECK_MS);
    const jobId = await deps.jobs.send('grade-trial', data, {
      id: gradeTrialJobId(data.run_id, data.trial_index, data.pass, `node-room:${data.first_pass}:${slot}`),
      startAfter: until,
      ...(await sendOptions(c, { runId: data.run_id, trialIndex: data.trial_index }, 'fault')),
    });
    const heldBy = `the node has no room for its pods: ${why}`;
    log(`[grade] ${what({ runId: data.run_id, trialIndex: data.trial_index })}: pass ${data.pass} waits for ${until.toISOString()}: ${heldBy}; no pass is spent on it`);
    return { kind: 'waiting', until, job_id: jobId, held_by: heldBy };
  };

  /**
   * What a `pod` pass takes besides the one-pod view (the header's `layout`): this process's lanes pod opened (made on
   * its first such pass), its hosted lanes and door, the contest's own pod requests (podRequestsOf) and the entry's lane
   * key for `row`'s trial (onePodEntryKey); null on `split`.
   * No room for the lanes pod (a NodeRoomError) is `short`: the job waits for the next slot as no pass, nothing minted or
   * claimed. Any other failure to open it is thrown on, as a fault (the job retries).
   */
  const passLanes = async (c: TrialRunContext, row: TrialRow): Promise<{ pod: OnePodPass | null } | { short: string }> => {
    if (c.onePod === null) return { pod: null };
    let lanes: OnePodLanes;
    try {
      lanes = await openOnePodLanes(c.onePod);
    } catch (err) {
      if (err instanceof NodeRoomError) return { short: `its grader's lanes pod found no room (${err.message})` };
      throw err;
    }
    const requests = podRequestsOf(c.slug);
    // The entry's lane key for the trial, keyed by the row's run: the same on the trial's live pass and its replay, and
    // the one the run's record carries once it is recorded (finish), where an L2 reads it.
    const entryKey = await onePodEntryKey(deps.failKeySecret, row);
    return { pod: { hosted: lanes.hosted, door: lanes.door, entryKey, ...(requests === null ? {} : { podRequests: { ...requests } }) } };
  };

  /**
   * What masq metered on a lane's key a pass handed back (its retirement's figure, else read now, the key disabled
   * first: retireTrialKey); 0 for no key, or one whose spend cannot be read (said in the log).
   */
  const keySpend = async (key: TrialPass['masq'], whose: string, row: Pick<TrialRow, 'runId' | 'trialIndex'>, signal: AbortSignal): Promise<bigint> => {
    if (key === null) return 0n;
    if (key.retired !== null) return key.retired.spend.microUsd;
    try {
      const { retireTrialKey } = await import('./gateway/masq.ts');
      const retired = await retireTrialKey(deps.gateway.broker, key.key_id, 0n, { signal });
      if (!retired.settled) await addRunFlags(db, row.runId, [GATEWAY_SPEND_UNSETTLED_FLAG]);
      return retired.spend.microUsd;
    } catch (err) {
      if (signal.aborted) throw err;
      log(`[grade] ${what(row)}: ${whose} ${key.key_id}, of a pass the node had no room for, could not be read (${err instanceof Error ? err.message : String(err)}); it lapses on its own`);
      return 0n;
    }
  };

  /**
   * As a pass claims its trial (or a refused key's trial scores 0), in `tx`: the run's `flag` (ENTRY_SECRET_HELD_FLAG)
   * taken off once no other trial of it is left to start (pending, or void before its re-run), so the
   * flag stays while any of them may still be waiting on what it says. Nothing written on a run that does not carry it.
   */
  const dropFlagOnceStarted = async (tx: Pick<Db, 'select' | 'update'>, row: Pick<TrialRow, 'runId' | 'trialIndex'>, flag: string): Promise<void> => {
    const [r] = await tx.select({ flags: run.flags }).from(run).where(eq(run.id, row.runId));
    if (r === undefined || !r.flags.includes(flag)) return;
    const [left] = await tx
      .select({ n: count() })
      .from(runTrial)
      .where(and(eq(runTrial.runId, row.runId), ne(runTrial.trialIndex, row.trialIndex), inArray(runTrial.status, ['pending', 'void'])));
    if (Number(left?.n ?? 0) === 0) await dropRunFlag(tx, row.runId, flag);
  };

  /**
   * What an entrant's pass runs with, read as it sets out (the header's `entry secrets`): its account's active entry
   * secrets in the competition, both lanes, each opened with the grader's private keys; of the provider lane only a
   * provider its allowlist serves (contracts/entry-secrets.ts providersOfModels: a key for any other could pay for no
   * call of the pass, so it is neither opened, checked nor recorded), each such key then checked with its provider. None
   * pushed: none (model-free, no variable). Either way the forwarder is told whether an entrant can push a secret on this
   * deployment at all (EntrantKeys.entrySecrets: `off` with no seal public key, where a push answers 503), so a no-key 401
   * never names `makefun secrets push` where that cannot work. Every word it answers is redacted of every form of every
   * secret; no value is logged, stored or thrown.
   */
  const entrantLane = async (c: TrialRunContext, signal: AbortSignal): Promise<EntrantLaneVerdict> => {
    const providers = deps.entrySecrets?.providers;
    const [{ entrySecretSealRefusal, EntrySecretSealError }, { openEntrySecretRows, sealedEntrySecretsFor }, { secretFormSet }] = await Promise.all([
      import('../server/secrets/seal.ts'),
      import('../server/secrets/store.ts'),
      import('./gateway/upstream.ts'),
    ]);
    const seal = await sealOf();
    const entrySecrets: EntrySecretsOpenT = entrySecretSealRefusal(seal, 'seal') === null ? 'on' : 'off';
    const reach = { ...(providers?.origins === undefined ? {} : { origins: providers.origins }), ...(providers?.ca === undefined ? {} : { ca: providers.ca }) };
    const serves = providersOfModels(c.harness.inference.models);
    const { secrets: held } = await sealedEntrySecretsFor(db, { userId: c.sub.userId, competitionId: c.ph.competitionId });
    const rows = held.filter((r) => r.lane === 'env' || (r.provider !== null && serves.includes(r.provider)));
    const none: PassSecrets = { ids: [], env: {}, forms: secretFormSet([]), byName: {} };
    if (rows.length === 0) return { kind: 'run', lane: { credential: 'entrant', own: { keys: {}, mask: [], ...reach, entrySecrets }, secrets: none } };
    const ids = rows.map((r) => r.id);
    const named = rows.map((r) => `${r.name} (entry_secret ${r.id})`).join(', ');
    const off = entrySecretSealRefusal(seal, 'open');
    if (off !== null) return { kind: 'unopened', ids, error: `the entry secrets its entrant pushed (${named}) cannot be opened, so its live pass does not run (never on the house's key instead): ${off}` };
    let opened: OpenedEntrySecret[];
    try {
      opened = openEntrySecretRows(seal.privateKeys, rows);
    } catch (err) {
      if (!(err instanceof EntrySecretSealError)) throw err;
      return { kind: 'unopened', ids, error: `an entry secret its entrant pushed cannot be opened here, so its live pass does not run (never on the house's key instead): ${err.message}` };
    }
    const keys: OpenedProviderKey[] = [];
    const env: Record<string, string> = {};
    const byName: Record<string, string> = {};
    for (const s of opened) {
      byName[s.name] = s.value;
      if (s.lane === 'env') env[s.name] = s.value;
      else keys.push({ id: s.id, name: s.name, provider: s.provider!, hint: rows.find((r) => r.id === s.id)!.hint, key: s.value });
    }
    const values = opened.map((s) => s.value);
    const forms = secretFormSet(values);
    const redact = await redactorOf(forms, keys.map((k) => k.key));
    const { checkProviderKey } = await import('./gateway/providers.ts');
    const timeout = deps.entrySecrets?.checkTimeoutMs === undefined ? {} : { timeoutMs: deps.entrySecrets.checkTimeoutMs };
    const verdicts: ProviderKeyVerdict[] = await Promise.all(
      keys.map(async (k): Promise<ProviderKeyVerdict> => {
        const check = await checkProviderKey(k.provider, k.key, { signal, ...reach, ...timeout });
        return { id: k.id, name: k.name, provider: k.provider, hint: k.hint, check: check.state === 'valid' ? check : { ...check, reason: redact(check.reason) } };
      }),
    );
    // The attempt is over: nothing is decided on a check it cut short.
    if (signal.aborted) throw signal.reason ?? new Error("the trial job was stopped while its entrant's keys were checked");
    const refused = verdicts.filter((v) => v.check.state === 'refused');
    if (refused.length > 0) return { kind: 'refused', ids, verdicts: refused, forms };
    const unreachable = verdicts.filter((v) => v.check.state === 'unreachable');
    if (unreachable.length > 0) return { kind: 'unreachable', ids, verdicts: unreachable, forms };
    const byProvider: Partial<Record<SecretProvider, string>> = {};
    for (const k of keys) byProvider[k.provider] = k.key;
    // The org and project ids each provider named for its key: masked with the keys out of every answer the forwarder relays.
    const mask = [...new Set(verdicts.flatMap((v) => (v.check.state === 'valid' ? v.check.identifiers : [])))].sort(compareCodeUnits);
    const secrets: PassSecrets = { ids, env, forms: mask.length === 0 ? forms : secretFormSet([...values, ...mask]), byName };
    return { kind: 'run', lane: { credential: 'entrant', own: { keys: byProvider, mask, ...reach, entrySecrets }, secrets } };
  };

  /**
   * The env-lane entry secrets a replay of `row`'s live pass runs with (the header's `entry secrets`): exactly the rows
   * that pass recorded (run_trial.entry_secret_ids; none on a house-paid pass), opened as it opened them. `erased` the
   * env-lane ones whose ciphertext is gone meanwhile, by NAME and row (the replay cannot run as live did); `unopened`
   * why this grader cannot open them. A provider-lane row is never opened: the replay runs on no key.
   */
  const replaySecrets = async (c: TrialRunContext, row: TrialRow): Promise<{ secrets: PassSecrets } | { erased: string } | { unopened: string }> => {
    const ids = row.entryCredential === 'entrant' ? (row.entrySecretIds ?? []) : [];
    const { secretFormSet } = await import('./gateway/upstream.ts');
    const recorded = await recordedEnvSecrets(db, sealOf, { userId: c.sub.userId, competitionId: c.ph.competitionId }, ids);
    if (recorded.erased !== null) return { erased: `an env-lane entry secret its live pass ran with is erased now (replaced, removed or purged): ${recorded.erased}, so its replay cannot run as it did` };
    if (recorded.kind === 'unopened') {
      return { unopened: recorded.cause === 'off' ? `the entry secrets its live pass ran with cannot be opened for its replay: ${recorded.why}` : `an entry secret its live pass ran with cannot be opened for its replay: ${recorded.why}` };
    }
    const { env } = recorded.secrets;
    return { secrets: { ids: [...ids], env, forms: secretFormSet(Object.values(env)), byName: { ...env } } };
  };

  /**
   * Best effort, for words about a pass that ran with `ids` (a cut-off pass's): every form of those secrets this grader can
   * still open, or null when it can open none (erased, or no private key here). Never throws on a secret it cannot open.
   */
  const recordedForms = async (c: TrialRunContext, ids: readonly string[]): Promise<FormSet | null> => {
    if (ids.length === 0) return null;
    try {
      const [{ openEntrySecretRows, sealedEntrySecretsFor }, { secretFormSet }] = await Promise.all([import('../server/secrets/store.ts'), import('./gateway/upstream.ts')]);
      const seal = await sealOf();
      if (seal.privateKeys === null) return null;
      const read = await sealedEntrySecretsFor(db, { userId: c.sub.userId, competitionId: c.ph.competitionId, ids });
      const values: string[] = [];
      for (const r of read.secrets) {
        try {
          values.push(...openEntrySecretRows(seal.privateKeys, [r]).map((s) => s.value));
        } catch {
          // A secret this grader cannot open is masked of nothing: its words never held it (it never reached this process).
        }
      }
      return values.length === 0 ? null : secretFormSet(values);
    } catch {
      return null;
    }
  };

  /**
   * After a pass that stands (its record kept: live_done, timeout; finished, nondeterministic), its outputs scanned for
   * its secrets (agent.ts secretsInPassOutputs: the env's export and call log, never masked): a hit flags the run
   * SECRET_IN_OUTPUT_FLAG and writes a SECRET_IN_OUTPUT_ACTION row naming each secret's NAME and the file (the header's
   * `entry secrets`), and is logged by NAME. Nothing with no secret.
   */
  const scanOutputs = async (row: Pick<TrialRow, 'id' | 'runId' | 'trialIndex'>, pass: number, p: Pick<TrialPass, 'mode' | 'outputs' | 'env_log_sha256'>, secrets: PassSecrets): Promise<SecretOutputHit[]> => {
    if (Object.keys(secrets.byName).length === 0) return [];
    const { secretScanIndex, secretsInPassOutputs } = await import('./agent.ts');
    const index: FormIndex = secretScanIndex(secrets.byName);
    const hits = await secretsInPassOutputs(blobs, p, index);
    if (hits.length === 0) return hits;
    await db.transaction(async (tx) => {
      await addRunFlags(tx, row.runId, [SECRET_IN_OUTPUT_FLAG]);
      await tx.insert(auditEvent).values({
        at: now(),
        actorUserId: null,
        action: SECRET_IN_OUTPUT_ACTION,
        subjectType: 'run_trial',
        subjectId: row.id,
        data: { run_id: row.runId, trial_index: row.trialIndex, pass, mode: p.mode, hits: hits.map((h) => ({ name: h.name, file: h.file })) },
      });
    });
    const named = [...new Set(hits.map((h) => h.name))].join(', ');
    log(`[grade] ${what(row)}: the ${p.mode} pass ${pass}'s outputs hold a form of entry secret ${named} (${[...new Set(hits.map((h) => h.file))].join(', ')}), never masked: its run is flagged ${SECRET_IN_OUTPUT_FLAG}`);
    return hits;
  };

  /** The next provider-key recheck slot after `at` (AGENT_PROVIDER_KEY_RECHECK_MS) and its start. */
  const keyRecheckSlot = (at: Date): { slot: number; start: Date } => {
    const slot = Math.ceil((at.getTime() + AGENT_PROVIDER_KEY_RECHECK_MS) / AGENT_PROVIDER_KEY_RECHECK_MS);
    return { slot, start: new Date(slot * AGENT_PROVIDER_KEY_RECHECK_MS) };
  };

  /**
   * When pass data.pass of the trial first met a refused key on the final: its ENTRY_SECRET_HELD_ACTION audit row's time,
   * or `at`, that row written now with when the wait ends (`deadline` of that start).
   */
  const keyHeldSince = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, v: { ids: string[]; verdicts: readonly ProviderKeyVerdict[] }, at: Date): Promise<Date> => {
    const [first] = await db
      .select({ at: auditEvent.at })
      .from(auditEvent)
      .where(and(eq(auditEvent.action, ENTRY_SECRET_HELD_ACTION), eq(auditEvent.subjectType, 'run_trial'), eq(auditEvent.subjectId, row.id), sql`${auditEvent.data}->>'pass' = ${String(data.pass)}`))
      .orderBy(asc(auditEvent.at), asc(auditEvent.id))
      .limit(1);
    if (first !== undefined) return first.at;
    await db.insert(auditEvent).values({
      at,
      actorUserId: null,
      action: ENTRY_SECRET_HELD_ACTION,
      subjectType: 'run_trial',
      subjectId: row.id,
      data: { run_id: row.runId, trial_index: row.trialIndex, pass: data.pass, until: keyHoldDeadline(c, at).toISOString(), entry_secret_ids: v.ids, providers: [...new Set(v.verdicts.map((x) => x.provider))] },
    });
    return at;
  };

  /** When a final pass that first met a refused key at `since` stops waiting: AGENT_PROVIDER_KEY_HOLD_MS on, never past the final phase's end. */
  const keyHoldDeadline = (c: TrialRunContext, since: Date): Date => new Date(Math.min(since.getTime() + AGENT_PROVIDER_KEY_HOLD_MS, c.ph.endsAt?.getTime() ?? Number.POSITIVE_INFINITY));

  /**
   * A pass whose entrant's key its provider refused (the header's `entry secrets`): on the final it waits for the entrant
   * to push a new one, the run flagged ENTRY_SECRET_HELD_FLAG and its job sent again for the next
   * AGENT_PROVIDER_KEY_RECHECK_MS slot, until AGENT_PROVIDER_KEY_HOLD_MS after the first refusal (capped at the final
   * phase's end); past that, once the competition is resolved, or on the dev phase at once, the trial scores 0
   * (keyRefusedZero, its record stamped with `pricingRev`, the run's: trialPricingRev). Its words are redacted of every form
   * of every secret the pass holds (`v.forms`).
   */
  const keyRefused = async (
    c: TrialRunContext,
    row: TrialRow,
    data: JobPayload<'grade-trial'>,
    v: { ids: string[]; verdicts: ProviderKeyVerdict[]; forms: FormSet },
    pricingRev: string,
  ): Promise<AgentTrialOutcome | 'again'> => {
    const at = now();
    const redact = await redactorOf(v.forms);
    const words = redact(v.verdicts.map(keyVerdictWords).join('; '));
    const fix = `push a working key: ${keyFixWords(c.slug, v.verdicts)}`;
    if (c.ph.key !== 'final') {
      return keyRefusedZero(c, row, data, v.ids, `the live pass did not run: ${words}, so trial ${row.trialIndex} scores 0 (${PROVIDER_KEY_REFUSED}); ${fix}, then submit again`, redact, pricingRev);
    }
    if (c.competitionStatus === 'resolved') {
      return keyRefusedZero(c, row, data, v.ids, `the final live pass did not run: ${words}, and the competition is resolved, so trial ${row.trialIndex} scores 0 (${PROVIDER_KEY_REFUSED})`, redact, pricingRev);
    }
    const since = await keyHeldSince(c, row, data, v, at);
    const deadline = keyHoldDeadline(c, since);
    if (at.getTime() >= deadline.getTime()) {
      return keyRefusedZero(
        c,
        row,
        data,
        v.ids,
        `the final live pass did not run: ${words}; it was first refused at ${since.toISOString()} and still was at ${deadline.toISOString()}, the end of the wait for a new key (${AGENT_PROVIDER_KEY_HOLD_MS / 3_600_000} hours, never past the final phase's end), so trial ${row.trialIndex} scores 0 (${PROVIDER_KEY_REFUSED})`,
        redact,
        pricingRev,
      );
    }
    const { slot, start } = keyRecheckSlot(at);
    const until = new Date(Math.min(start.getTime(), deadline.getTime()));
    const jobId = await deps.jobs.send('grade-trial', data, { id: gradeTrialJobId(row.runId, row.trialIndex, data.pass, `provider-key:${data.first_pass}:${slot}`), startAfter: until, ...(await sendOptions(c, row, 'deferral')) });
    await addRunFlags(db, row.runId, [ENTRY_SECRET_HELD_FLAG]);
    log(
      redact(
        `[grade] ${what(row)}: final pass ${data.pass} waits for its entrant to push a new key in place of a refused one (${words}): checked again at ${until.toISOString()}, and the trial scores 0 (${PROVIDER_KEY_REFUSED}) if it is still refused at ${deadline.toISOString()}; the entrant's fix: ${fix}`,
      ),
    );
    return { kind: 'key_wait', why: 'refused', until, job_id: jobId, deadline, reason: words };
  };

  /**
   * A refused key's trial scored 0 (the header's `entry secrets`), nothing run: its record keyRefusedRecord's, its points
   * 0 on every column (agent.ts timeoutScores) as a timeout's, void_reason PROVIDER_KEY_REFUSED and `note`, the readable
   * why, as its error (redacted, `redact`). The rows the pass would have run with recorded (entry_secret_ids); the run's
   * ENTRY_SECRET_HELD_FLAG taken off once no other trial of it is left to start; the fan-in told.
   */
  const keyRefusedZero = async (
    c: TrialRunContext,
    row: TrialRow,
    data: JobPayload<'grade-trial'>,
    ids: string[],
    note: string,
    redact: Redact,
    pricingRev: string,
  ): Promise<AgentTrialOutcome | 'again'> => {
    const at = now();
    const record = await keyRefusedRecord(blobs, row, c.harness.target !== undefined, pricingRev);
    const scores = (await import('./agent.ts')).timeoutScores(c.bundle.leaderboard);
    const error = redact(note);
    const moved = await db.transaction(async (tx) => {
      const m = await moveTrial(tx, row, {
        ...passStart(row, data.pass, at),
        ...record,
        status: 'timeout',
        liveFinishedAt: at,
        score: scores,
        scoreSha256: canonicalSha256(scores),
        masqKeyId: null,
        houseMasqKeyId: null,
        entryCredential: 'entrant',
        entrySecretIds: ids,
        voidReason: PROVIDER_KEY_REFUSED,
        error,
      });
      if (m !== null) await dropFlagOnceStarted(tx, row, ENTRY_SECRET_HELD_FLAG);
      return m;
    });
    if (moved === null) return 'again';
    log(`[grade] ${what(row)}: ${error}`);
    await poke(moved);
    return { kind: 'done', status: 'timeout' };
  };

  /**
   * A pass whose entrant's key its provider gave no verdict on (the header's `entry secrets`): never the entrant's fault,
   * so never scored for it. Its job sent again for the next AGENT_PROVIDER_KEY_RECHECK_MS slot, unless the competition is
   * resolved; the admins paged at most once an hour for the same providers, else logged; every word redacted of the
   * pass's secrets.
   */
  const keyUnreachable = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, v: { verdicts: ProviderKeyVerdict[]; forms: FormSet }): Promise<AgentTrialOutcome> => {
    const at = now();
    const redact = await redactorOf(v.forms);
    const words = redact(v.verdicts.map(keyVerdictWords).join('; '));
    const { slot, start } = keyRecheckSlot(at);
    const until = c.competitionStatus === 'resolved' ? null : start;
    const jobId = until === null ? null : await deps.jobs.send('grade-trial', data, { id: gradeTrialJobId(row.runId, row.trialIndex, data.pass, `provider-key:${data.first_pass}:${slot}`), startAfter: until, ...(await sendOptions(c, row, 'deferral')) });
    const line = `[grade] ${what(row)}: ${c.ph.key} pass ${data.pass} waits: its entrant's provider key could not be checked (${words}), which is never the entrant's fault${until === null ? ', and its competition is resolved, so nothing is sent again' : `; checked again at ${until.toISOString()}`}`;
    const providers = [...new Set(v.verdicts.map((x) => x.provider))];
    const pageKey = providers.join(',');
    const last = unreachablePaged.get(pageKey);
    if (last !== undefined && at.getTime() - last < AGENT_REFUSAL_PAGE_MS) {
      log(line);
    } else {
      unreachablePaged.set(pageKey, at.getTime());
      page(
        `[grade] ALERT: ${c.slug}: ${providers.map((p) => SECRET_PROVIDER_NAME[p]).join(' and ')} gave no verdict on an entrant's provider key from this grader (${words}). ` +
          `Live passes on entrants' own keys wait and check again every ${AGENT_PROVIDER_KEY_RECHECK_MS / 60_000} minutes: nothing is run, marked or scored meanwhile, and it is never the entrant's fault (${what(row)} is one). ` +
          `Fix: mend the grader's egress to the provider, or wait out its outage`,
      );
    }
    return { kind: 'key_wait', why: 'unreachable', until, job_id: jobId, deadline: null, reason: words };
  };

  /**
   * Live pass data.pass from a pending or void row: a house-paid entry's on a key of its own, the row claimed as the key
   * comes back; an entrant's on its own keys and with its env-lane secrets (read, opened and checked first: the header's
   * `entry secrets`), the row claimed as its house key comes back, or as it sets out with no target (the header's `entry
   * lane`).
   */
  const livePass = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome | 'again'> => {
    const pass = data.pass;
    // A router-served target's house lane on superbot-router, or no pass at all (HouseRouterRefusal): never masq for it.
    const router = routerLaneOf(c);
    // Nothing minted, claimed or networked on an engine that does not keep trials apart.
    await requireIsolation();
    // The pricing revision both lanes meter it on, its run's (the header's `pricing`): one this grader holds no table of is the platform's fault, before anything is minted or claimed.
    const pricingRev = await trialPricingRev(db, blobs, c.sub, row);
    // Nothing minted or claimed while the node has no room for the pass's pods (on `pod` its one): it waits for the next slot, as no pass.
    const short = await roomShort((await import('./agent.ts')).trialPods(c.harness, c.layout));
    if (short !== null) return waitForRoom(c, data, short);
    // On `pod` its lanes pod open first (the header's `layout`): no room for it is the node's, waited out as no pass.
    const lanes = await passLanes(c, row);
    if ('short' in lanes) return waitForRoom(c, data, lanes.short);
    // No spend is weighed (the header's `spend`): the pass's own budget alone bounds it. Whether the house pays the entry lane.
    const housePaid = housePaysEntryLane(c.sub);
    // An entrant's pass runs with the secrets its entrant pushed, each opened (its provider keys checked with their
    // providers) before anything is minted or claimed; a key that cannot run it now holds, waits or zeroes the trial,
    // never sending it to masq. A house-paid entry's pass runs with none.
    let lane: EntryLane = { credential: 'house' };
    if (!housePaid) {
      const found = await entrantLane(c, ctx.signal);
      if (found.kind === 'unopened') return hold(row, ENTRY_SECRETS_UNOPENED_HOLD_REASON, found.error, c, passStart(row, pass, now()));
      if (found.kind === 'refused') return keyRefused(c, row, data, found, pricingRev);
      if (found.kind === 'unreachable') return keyUnreachable(c, row, data, found);
      lane = found.lane;
    }
    const started = now();
    /**
     * What the pass removes of the trial's scratch, a dead pass's (removed as the key is claimed, mid-pass) and its own,
     * released from the sandbox's daemon in one go once the pass is over and its outcome recorded, or it threw (grade.ts
     * releaseScratch, its header's Releasing): never while the agent runs, and never before the pass's end is read
     * (liveFinishedAt), which a release would move.
     */
    const removed: string[] = [];
    try {
      return await livePassIn(c, row, data, ctx, pass, lane, started, removed, router, lanes.pod, pricingRev);
    } finally {
      await releaseScratch(c.sandbox, removed);
    }
  };

  /**
   * livePass's pass and its record, every scratch dir it removes handed to `removed` (for livePass's one release);
   * `lane` whose keys its entry lane runs on (the house's, when the house pays it: housePaysEntryLane; else the
   * entrant's: the header's `entry lane`); `router` the superbot-router its target's house lane runs on (routerLaneOf),
   * null for one on masq or no target; `onePod` what a `pod` pass takes besides the one-pod view (passLanes), null on `split`;
   * `pricingRev` the pricing revision both its lanes meter it on (trialPricingRev).
   */
  const livePassIn = async (
    c: TrialRunContext,
    row: TrialRow,
    data: JobPayload<'grade-trial'>,
    ctx: AgentTrialContext,
    pass: number,
    lane: EntryLane,
    started: Date,
    removed: string[],
    router: HouseRouter | null,
    onePod: OnePodPass | null,
    pricingRev: string,
  ): Promise<AgentTrialOutcome | 'again'> => {
    const housePaid = lane.credential === 'house';
    // Every word of the pass stored, logged or thrown, redacted of every form of the entrant's secrets (none on the house's).
    const secrets = lane.credential === 'entrant' ? lane.secrets : null;
    const ownKeys = lane.credential === 'entrant' ? Object.values(lane.own.keys).filter((k): k is string => typeof k === 'string') : [];
    const redact: Redact = secrets === null || secrets.forms.forms.length === 0 ? NO_REDACT : await redactorOf(secrets.forms, ownKeys);
    let claimed: TrialRow | null = null;
    /** This pass's own scratch (inScratch's), which the removal of a dead pass's spares. */
    let ownScratch: string | null = null;
    /**
     * The trial claimed for this pass on the keys it holds then (`masqKeyId` its entry lane's, null on an entrant's pass;
     * `houseMasqKeyId` a target's house key when that is what claims), whose they are recorded beside them (laneCredential:
     * an entrant's pass the entry_secret rows it runs with, minting none for its entry lane); then what a dead pass left
     * of the trial removed. `doing`: what the pass was doing, for the words of a claim another attempt took first.
     */
    const claim = async (keys: { masqKeyId: string | null; houseMasqKeyId: string | null }, doing: string): Promise<void> => {
      claimed = await db.transaction(async (tx) => {
        const moved = await moveTrial(tx, row, { ...passStart(row, pass, started), status: 'live_running', ...keys, ...laneCredential(lane) });
        // A final pass's rows recorded only while each it opened still holds its ciphertext, under its entrant's account
        // lock, so a challenge's re-run of the trial can always open them (the header's `entry secrets`).
        if (moved !== null && c.ph.key === 'final' && lane.credential === 'entrant') {
          const erased = await erasedSinceOpened(tx, { userId: c.sub.userId, competitionId: c.ph.competitionId }, lane.secrets.ids);
          if (erased !== null) {
            throw new PassSecretsErased(
              `${what(row)}: live pass ${pass} opened an env-lane entry secret its entrant removed or replaced before the pass claimed the trial, whose sealed copy is erased (${erased}): nothing is claimed, and the pass sets out again with the secrets as they stand`,
            );
          }
        }
        // Its keys passed their check: a wait on a refused one is over once no other trial of the run is left to start.
        if (moved !== null && !housePaid) await dropFlagOnceStarted(tx, row, ENTRY_SECRET_HELD_FLAG);
        return moved;
      });
      if (claimed === null) throw new TrialTaken(`${what(row)} moved on from ${row.status} while pass ${pass} ${doing}`);
      // The trial is this pass's now: what a dead grader's pass of it left under the work root goes first (its containers go as the pass makes its network).
      await reapDeadScratch(c.sandbox, row, `live pass ${pass}`, ownScratch, removed);
    };
    const broker = claimingBroker(
      deps.gateway.broker,
      (minted) => claim({ masqKeyId: minted.id, houseMasqKeyId: null }, 'minted its key'),
      async (minted) => {
        // An entrant's pass mints no entry-lane key: its target's house key, the one key it mints, claims the trial.
        if (!housePaid) return claim({ masqKeyId: null, houseMasqKeyId: minted.id }, 'minted its house key');
        // A target's house key, minted after the entry's claimed the trial: recorded beside it, so a pass cut off retires both (interrupted).
        const mine = claimed as TrialRow | null;
        if (mine === null) throw new Error(`live pass ${pass} of ${what(row)} minted its house key before its own claimed the trial`);
        const moved = await moveTrial(db, mine, { houseMasqKeyId: minted.id });
        if (moved === null) throw new TrialTaken(`${what(row)} moved on from live_running while pass ${pass} minted its house key`);
        claimed = moved;
      },
    );
    const key: TrialKeySpec = {
      slug: c.slug,
      runId: row.runId,
      trialIndex: row.trialIndex,
      attempt: pass,
      budgetUsdPerTrial: c.harness.inference.budget_usd_per_trial,
      models: c.harness.inference.models,
      wallBudgetSec: c.bundle.limits.wall_budget_sec,
    };
    const masq: MasqTrialUpstream = { broker, key, origin: deps.gateway.origin, ...(deps.gateway.retireBackoffMs === undefined ? {} : { retireBackoffMs: deps.gateway.retireBackoffMs }) };
    // House-paid: the entry lane on a masq key of the pass's own (and a target's house lane on another), and no entry
    // secret. An entrant's: its entry lane on the keys its entrant pushed (none: every model call of it answered 401 by the
    // forwarder itself), the org and project ids their providers named masked with them, and its env-lane secrets in the
    // entry's own sandbox; a target's house lane still on a masq key, derived from `key` (role house). A router-served
    // target's house lane on superbot-router instead, on either: the house-lane key, the pass's house label its user.
    const routerHouse =
      router === null
        ? null
        : { config: { adapter: 'router' as const, origin: router.origin, speed: router.speed, user: (await import('./gateway/masq.ts')).trialKeyLabel({ ...key, role: 'house' }) }, key: router.key };
    const upstream: PassUpstream =
      lane.credential === 'house'
        ? { masq, ...(routerHouse === null ? {} : { house: routerHouse }) }
        : { provider: lane.own, ...(c.harness.target === undefined ? {} : { house: routerHouse ?? { masq } }) };
    const envSecrets = secrets === null || Object.keys(secrets.env).length === 0 ? {} : { secrets: secrets.env };
    const gateway = await forwarderOf();
    const { runTrial: agentRunTrial, NODE_CAPACITY_VOID_REASON } = await import('./agent.ts');
    const runAgentTrial = deps.runTrial ?? agentRunTrial;
    let p: TrialPass;
    try {
      p = await inScratch(c, row, async ({ dir, botDir, workDir }) => {
        ownScratch = dir;
        // An entrant's pass with no target, or its house lane on the router, mints nothing, so no key coming back claims the trial: it is claimed here, before anything runs.
        if (!housePaid && (c.harness.target === undefined || routerHouse !== null)) await claim({ masqKeyId: null, houseMasqKeyId: null }, 'set out');
        return runAgentTrial({
          mode: 'live',
          sandbox: c.sandbox,
          snapshot: { dir: botDir, runtime: c.runtime, imageDigest: c.run.imageDigest },
          instanceDir: instanceDirOf(row),
          trial: trialRef(row),
          // A house baseline's pass reads the instance's baseline brief when it has one (the header's `brief`).
          baseline: c.sub.baseline,
          setup: c.setup,
          limits: c.bundle.limits,
          pricingRev,
          upstream,
          ...envSecrets,
          gateway,
          workDir,
          blobs,
          signal: ctx.signal,
          score: false,
          owner: ownerOf(row),
          onReap: logReap(row, `live pass ${pass}`),
          ...(onePod ?? {}),
        });
      }, removed);
    } catch (err) {
      // Another job claimed the pass first (the key that would have claimed it, if any, disabled here): that job runs it.
      if (err instanceof TrialTaken) return { kind: 'stopped', why: err.message };
      // A final pass whose entrant erased a secret it opened before it claimed (any key it minted disabled here): it sets out again, the row read afresh.
      if (err instanceof PassSecretsErased) {
        log(`[grade] ${err.message}`);
        return 'again';
      }
      // Anything else goes on as it was, its words redacted of the entrant's secrets (a held trial's error stores them).
      throw redactedError(err, redact);
    }
    // The pass's end, read as it returns: its scratch is released once the row records it (livePass).
    const at = now();
    const mine = claimed as TrialRow | null;
    const error = p.error === null ? null : redact(p.error);
    // The node had no room for one of its pods, so the entry never ran (agent.ts NODE_CAPACITY_VOID_REASON; the header's
    // `node room`): no pass of the trial's. Its claim, if it made one, undone, what masq metered on its keys counted as
    // voided spend, and its job sent again for the next recheck slot.
    const noRoom = p.status === 'void' && p.reason === NODE_CAPACITY_VOID_REASON;
    if (mine === null) {
      if (noRoom) return waitForRoom(c, data, error ?? 'one of its pods found none');
      // No key came back (an entrant's pass with no target, or a router house lane, claims before it runs, so never here): the pass voided before
      // anything ran (the instance, the sandbox, the broker).
      if (p.status !== 'void') throw new Error(`live pass ${pass} of ${what(row)} ended ${p.status} with no key minted`);
      const moved = await moveTrial(db, row, { ...passStart(row, pass, started), status: 'void', liveFinishedAt: at, voidReason: p.reason, error, ...laneCredential(lane) });
      return moved === null ? 'again' : voided(c, moved, data, AGENT_VOID_RERUN_DELAY_MS);
    }
    if (noRoom) {
      const roomFlags = [...new Set([...masqRunFlags(p.masq), ...masqRunFlags(p.house_masq)])];
      if (roomFlags.length > 0) await addRunFlags(db, row.runId, roomFlags);
      const spent = await keySpend(p.masq, 'its key', row, ctx.signal);
      const houseSpent = await keySpend(p.house_masq, 'its house key', row, ctx.signal);
      const undone = await moveTrial(db, mine, {
        ...unclaimed(row, pass, started),
        voidedSpendMicroUsd: row.voidedSpendMicroUsd + spent,
        voidedHouseSpendMicroUsd: row.voidedHouseSpendMicroUsd + houseSpent,
      });
      if (undone === null) return 'again';
      return waitForRoom(c, data, error ?? 'one of its pods found none');
    }
    // The entrant's secrets a pass ran with are marked used, its keys validated (their pre-flight had each provider answer 200).
    if (secrets !== null && secrets.ids.length > 0) {
      try {
        await (await import('../server/secrets/store.ts')).markUsed(db, secrets.ids, at, { validated: true });
      } catch (e) {
        log(`[grade] ${what(row)}: the entry secrets live pass ${pass} ran with (${secrets.ids.join(', ')}) could not be marked used (${redact(e instanceof Error ? e.message : String(e))}); nothing else hangs on it`);
      }
    }
    // Each lane's key retired as runPass ended: either's flags are the run's; on a house clock, the pass's own besides.
    const flags = [...new Set([...masqRunFlags(p.masq), ...masqRunFlags(p.house_masq), ...houseClockRunFlags(p, row.trialIndex, pass)])];
    if (flags.length > 0) await addRunFlags(db, row.runId, flags);
    const houseSpend = await houseSpendOf(blobs, p);
    if (p.status === 'live_done') {
      // Its outputs scanned for its secrets, never masked (the header's `entry secrets`); then scored and replayed next (a
      // row another attempt moved meanwhile is read again either way).
      if (secrets !== null) await scanOutputs(mine, pass, p, secrets);
      await moveTrial(db, mine, { ...passRecord(p, at, houseSpend), ...trialEnding('live_done') });
      return 'again';
    }
    if (p.status === 'timeout') {
      if (secrets !== null) await scanOutputs(mine, pass, p, secrets);
      const scores = (await import('./agent.ts')).timeoutScores(c.bundle.leaderboard);
      const moved = await moveTrial(db, mine, { ...passRecord(p, at, houseSpend), ...trialEnding('timeout'), score: scores, scoreSha256: canonicalSha256(scores) });
      if (moved === null) return 'again';
      await poke(moved);
      await stagedTimeout(c, moved);
      return { kind: 'done', status: 'timeout' };
    }
    if (p.status === 'void') {
      const moved = await moveTrial(db, mine, { ...passRecord(p, at, houseSpend), status: 'void', voidReason: p.reason, error });
      return moved === null ? 'again' : voided(c, moved, data, AGENT_VOID_RERUN_DELAY_MS);
    }
    throw new Error(`live pass ${pass} of ${what(row)} ended ${p.status}, which no live pass ends`);
  };

  /**
   * This job's live pass found running: its earlier attempt was cut off (the pass is over, whatever it
   * spent). What its grader left running, if it died, removed first (so its forwarder spends nothing
   * more before the key's spend is read), and the scratch it left; then a void, its key retired. That scratch is released
   * from the sandbox's daemon once the void is recorded, or it threw (grade.ts releaseScratch, its header's Releasing).
   */
  const interrupted = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome | 'again'> => {
    const before = `live pass ${row.attempt} is voided as cut off`;
    const reaped = await sandboxReap(c.sandbox, ownerOf(row));
    if (reaped !== null) logReap(row, before)(reaped);
    const removed: string[] = [];
    try {
      await reapDeadScratch(c.sandbox, row, before, null, removed);
      /** A lane's key retired: what masq metered on it, and why it could not be read. */
      const retire = async (keyId: string | null, whose: string): Promise<{ spent: bigint; note: string }> => {
        if (keyId === null) return { spent: 0n, note: '' };
        let settled = true;
        let spent = 0n;
        let note = '';
        try {
          const { retireTrialKey } = await import('./gateway/masq.ts');
          // No meter came back to check the figure against: only whether it settled is kept.
          const retired = await retireTrialKey(deps.gateway.broker, keyId, 0n, { signal: ctx.signal });
          spent = retired.spend.microUsd;
          settled = retired.settled;
        } catch (err) {
          if (ctx.signal.aborted) throw err;
          note = `; ${whose} ${keyId} could not be retired (${err instanceof Error ? err.message : String(err)}) and lapses on its own`;
        }
        if (!settled) await addRunFlags(db, row.runId, [GATEWAY_SPEND_UNSETTLED_FLAG]);
        return { spent, note };
      };
      const own = await retire(row.masqKeyId, 'its key');
      // A target's house key (the header's `house lane`): its meter is the house lane's voided spend.
      const house = await retire(row.houseMasqKeyId, 'its house key');
      const spent = own.spent;
      // An entrant's pass held no key for its entry lane (the header's `entry lane`): nothing of the house's was metered
      // there, and what it spent on the entrant's own keys is the entrant's, unmetered here (no cassette came back).
      const entrantSecrets = row.entryCredential === 'entrant' ? (row.entrySecretIds ?? []) : [];
      const ownWords =
        row.masqKeyId !== null
          ? `masq metered ${spent} µUSD on its key, counted as voided spend`
          : entrantSecrets.length > 0
            ? `its entry lane ran with its entrant's own entry secrets (entry_secret ${entrantSecrets.join(', ')}), so what it spent on a provider key there is the entrant's and unmetered here: no key of the house's to retire`
            : "its entry lane held no key of the house's (an entrant's pass, on its own keys), so nothing was metered there";
      const houseWords =
        row.houseMasqKeyId === null
          ? ''
          : row.masqKeyId === null
            ? `; masq metered ${house.spent} µUSD on its house key, counted as the house lane's voided spend`
            : `, and ${house.spent} µUSD on its house key, counted as the house lane's`;
      const started = row.liveStartedAt?.toISOString() ?? 'at an unknown time';
      // Its words redacted of every secret the cut-off pass ran with that this grader can still open (the header's `entry secrets`).
      const redact = await redactorOf(await recordedForms(c, entrantSecrets));
      // The passes cut off in a row, this one with them (the header's `cut off`): the row still tells of the pass before it.
      const inARow = liveCutOffRun(row, row.attempt - 1) + 1;
      const moved = await moveTrial(db, row, {
        status: 'void',
        liveFinishedAt: now(),
        voidReason: INTERRUPTED_VOID_REASON,
        error:
          redact(`live pass ${row.attempt}, started ${started}, was cut off before it ended (its job attempt stopped or expired) and recorded no cassette; ${ownWords}${houseWords}${own.note}${house.note}`) +
          (inARow > 1 ? cutOffRunWords(inARow) : ''),
        voidedSpendMicroUsd: row.voidedSpendMicroUsd + spent,
        voidedHouseSpendMicroUsd: row.voidedHouseSpendMicroUsd + house.spent,
      });
      return moved === null ? 'again' : voided(c, moved, data, 0);
    } finally {
      await releaseScratch(c.sandbox, removed);
    }
  };

  /**
   * The recorded live pass's export scored by the bundle's scorer, in the integer points the run counts (a ScorerError
   * otherwise: the competition's fault), with the per-check rows it wrote beside them (agent.ts scoreTrialWithChecks;
   * the header's `checks`): kept on the row with the score, or why a malformed checks.json was dropped, never a fault.
   * The scorer works in a scratch named for the trial's owner, which the replay's removal of a dead pass's scratch takes
   * should the grader die meanwhile; removed once it scored, it is released from the sandbox's daemon once the score is
   * recorded, or it threw (grade.ts releaseScratch, its header's Releasing). The scorer reads the export as the entry left
   * it (never masked: the header's `entry secrets`), so what it throws is redacted of the secrets the pass ran with
   * before it goes on (a held trial's error stores it).
   */
  const scorePass = async (c: TrialRunContext, row: TrialRow): Promise<void> => {
    try {
      await scorePassIn(c, row);
    } catch (err) {
      const ids = row.entryCredential === 'entrant' ? (row.entrySecretIds ?? []) : [];
      throw ids.length === 0 ? err : redactedError(err, await redactorOf(await recordedForms(c, ids)));
    }
  };

  /** scorePass's scoring, its errors as they came. */
  const scorePassIn = async (c: TrialRunContext, row: TrialRow): Promise<void> => {
    const outputs = TrialOutputs.parse(await blobJson(blobs, row.outputsSha256!, 'state export manifest'));
    const { scoreTrialWithChecks } = await import('./agent.ts');
    const dir = await ownedScratch(deps.workRoot, TRIAL_SCRATCH_PREFIX, ownerOf(row));
    const removed: string[] = [];
    try {
      let scored: TrialScored;
      try {
        scored = await scoreTrialWithChecks({ sandbox: c.sandbox, setup: c.setup, instanceDir: instanceDirOf(row), outputs, blobs, limits: c.bundle.limits, workDir: dir });
      } finally {
        await removeScratch(c.sandbox, dir, removed);
      }
      const { scores } = scored;
      // aggregateTrials's own check of one trial's points: integers, and a working column of 0 or 1.
      aggregateTrials(
        [{ index: row.trialIndex, instance_sha256: row.instanceSha256, cassette_sha256: row.cassetteSha256!, state_sha256: row.stateSha256!, status: 'finished', scores, pricing_rev: 'check', requests: 0, spend_micro_usd: '0', voids: 0 }],
        c.bundle.leaderboard,
      );
      // The rows as canonical JSON (their keys in code-unit order), beside the score they were read with.
      await moveTrial(db, row, { score: scores, scoreSha256: canonicalSha256(scores), checks: scored.checks === null ? null : JSON.parse(canonicalJson(scored.checks)), checksIssue: scored.checks_issue });
    } finally {
      await releaseScratch(c.sandbox, removed);
    }
  };

  /**
   * The replay of the recorded live pass (from live_done, or again from an interrupted replay): finished or nondeterministic.
   * It copies the brief its live pass recorded (the header's `brief`), and a replay that copied another is a harness fault.
   * It runs with exactly the env-lane entry secrets its live pass ran with (the header's `entry secrets`): one erased
   * meanwhile voids the live pass (ENTRY_SECRETS_ERASED_VOID_REASON, a fresh one sent), and one this grader cannot open
   * holds the trial (ENTRY_SECRETS_UNOPENED_HOLD_REASON), never a replay on other values. Its outputs are scanned as the
   * live pass's were, and its words redacted of every form of those secrets.
   */
  const replay = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext, cutOff: string | null = null): Promise<AgentTrialOutcome | 'again'> => {
    // Nothing claimed or networked on an engine that does not keep trials apart.
    await requireIsolation();
    // Nothing claimed while the node has no room for the replay's pods (on `pod` its one): it waits for the next slot.
    const short = await roomShort((await import('./agent.ts')).trialPods(c.harness, c.layout));
    if (short !== null) return waitForRoom(c, data, short);
    // On `pod` its lanes pod open first (the header's `layout`): no room for it is the node's, waited out.
    const lanes = await passLanes(c, row);
    if ('short' in lanes) return waitForRoom(c, data, lanes.short);
    const opened = await replaySecrets(c, row);
    if ('erased' in opened) {
      const at = now();
      const error = `${opened.erased}: live pass ${row.attempt} is voided, and the next runs with what its entrant holds now`;
      const moved = await moveTrial(db, row, { status: 'void', voidReason: ENTRY_SECRETS_ERASED_VOID_REASON, error, replayStartedAt: null, replayFinishedAt: null, liveFinishedAt: row.liveFinishedAt ?? at });
      return moved === null ? 'again' : voided(c, moved, data, 0);
    }
    if ('unopened' in opened) return hold(row, ENTRY_SECRETS_UNOPENED_HOLD_REASON, opened.unopened, c);
    const secrets = opened.secrets;
    const redact = await redactorOf(secrets.forms.forms.length === 0 ? null : secrets.forms);
    // A replay found cut off is counted as this one claims (replayCutOff's words), so a wait before it counts nothing.
    const claimed = await moveTrial(db, row, { status: 'replaying', replayStartedAt: now(), replayFinishedAt: null, ...(cutOff === null ? {} : { error: cutOff }) });
    if (claimed === null) return 'again';
    // What the replay removes of the trial's scratch, a dead pass's and its own, released in one go once its outcome is
    // recorded, or it threw (grade.ts releaseScratch, its header's Releasing): never before its end is read (replayFinishedAt).
    const removed: string[] = [];
    try {
      // The trial is this replay's now: what a dead grader's pass of it (or its scorer) left under the work root goes first.
      await reapDeadScratch(c.sandbox, claimed, `the replay of live pass ${claimed.attempt}`, null, removed);
      const gateway = await forwarderOf();
      const { runTrial: agentRunTrial, NODE_CAPACITY_VOID_REASON } = await import('./agent.ts');
      const runAgentTrial = deps.replayTrial ?? agentRunTrial;
      const p = await inScratch(
        c,
        claimed,
        ({ botDir, workDir }) =>
          runAgentTrial({
            mode: 'replay',
            sandbox: c.sandbox,
            snapshot: { dir: botDir, runtime: c.runtime, imageDigest: c.run.imageDigest },
            instanceDir: instanceDirOf(claimed),
            trial: trialRef(claimed),
            // The live pass's choice, never the flag as it stands now; a row recorded before the choice was replays on the flag.
            baseline: claimed.baselinePrompt ?? c.sub.baseline,
            setup: c.setup,
            limits: c.bundle.limits,
            // A target's replay serves the house lane its own cassette too, both wholly consumed (agent.ts ReplaySource).
            cassette: {
              cassette_sha256: claimed.cassetteSha256!,
              state_sha256: claimed.stateSha256!,
              ...(claimed.houseCassetteSha256 === null ? {} : { house_cassette_sha256: claimed.houseCassetteSha256 }),
            },
            // The env-lane secrets its live pass ran with: the entry's variables, and its forwarder's request mask.
            ...(Object.keys(secrets.env).length === 0 ? {} : { secrets: secrets.env }),
            gateway,
            workDir,
            blobs,
            signal: ctx.signal,
            owner: ownerOf(claimed),
            onReap: logReap(claimed, `the replay of live pass ${claimed.attempt}`),
            ...(lanes.pod ?? {}),
          }),
        removed,
      ).catch((err: unknown) => {
        throw redactedError(err, redact);
      });
      // The node had no room for one of its pods (the header's `node room`): the replay's claim undone, the job sent again.
      if (p.status === 'void' && p.reason === NODE_CAPACITY_VOID_REASON) {
        const back = await moveTrial(db, claimed, { status: row.status, replayStartedAt: row.replayStartedAt, replayFinishedAt: row.replayFinishedAt, error: row.error });
        if (back === null) return 'again';
        return await waitForRoom(c, data, redact(p.error ?? 'one of its pods found none'));
      }
      // On a house clock, what the replay ran on: a run flag, as its live pass's is.
      const clockFlags = houseClockRunFlags(p, claimed.trialIndex, claimed.attempt);
      if (clockFlags.length > 0) await addRunFlags(db, claimed.runId, clockFlags);
      if (p.status === 'void') throw new TrialHarnessFault(`replay_${p.reason ?? 'void'}`, redact(`the replay of live pass ${claimed.attempt} voided (${p.reason}): ${p.error ?? 'no detail'}`));
      if (p.status !== 'finished' && p.status !== 'nondeterministic') throw new Error(`the replay of ${what(claimed)} ended ${p.status}, which no replay ends`);
      // Its outputs scanned for its secrets, never masked (the header's `entry secrets`).
      await scanOutputs(claimed, claimed.attempt, p, secrets);
      if (claimed.promptSha256 !== null && p.prompt_sha256 !== claimed.promptSha256) {
        throw new TrialHarnessFault(
          'replay_brief',
          `the replay of live pass ${claimed.attempt} copied the brief ${p.prompt_sha256 ?? 'none'} (${p.baseline_prompt ? "the instance's baseline brief" : 'input/prompt.txt'}), not the ${claimed.promptSha256} its live pass read: it replays nothing that pass did`,
        );
      }
      const done = await moveTrial(db, claimed, { ...(p.status === 'nondeterministic' ? trialEnding(p.status, redact(`${p.reason}: ${p.error}`)) : trialEnding(p.status)), replayFinishedAt: now() });
      if (done === null) return 'again';
      await poke(done);
      return { kind: 'done', status: p.status };
    } catch (err) {
      // A replay that met a fault ended (the header's `cut off`): its end recorded, so the next attempt retries it as a
      // fault, never as a replay cut off. An attempt stopped or expired writes nothing more: that one was cut off.
      if (!ctx.signal.aborted) await moveTrial(db, claimed, { replayFinishedAt: now() }).catch(() => undefined);
      throw err;
    } finally {
      await releaseScratch(c.sandbox, removed);
    }
  };

  /**
   * A replay found cut off (the header's `cut off`: the row replaying with no end, the attempt that ran it stopped or
   * expired, or its grader died): replayed again, which spends nothing, the replays of its live pass cut off in a row
   * counted on the row as the next claims it (replayCutOffWords); the AGENT_INTERRUPTED_RERUNS-th in a row holds the
   * trial (INTERRUPTED_VOID_REASON), its recorded live pass kept, so a re-queue replays it again.
   */
  const replayCutOff = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome | 'again'> => {
    const inARow = replayCutOffRun(row) + 1;
    const words = replayCutOffWords(row, inARow);
    if (inARow >= AGENT_INTERRUPTED_RERUNS) {
      return hold(row, INTERRUPTED_VOID_REASON, `${inARow} replays of live pass ${row.attempt} in a row voided, the last of ${INTERRUPTED_VOID_REASON}: ${words}`, c);
    }
    log(`[grade] ${what(row)}: the replay of live pass ${row.attempt} was cut off before it ended (${inARow} of ${AGENT_INTERRUPTED_RERUNS} in a row): it is replayed again, spending nothing`);
    return replay(c, row, data, ctx, words);
  };

  /**
   * A dev-phase trial's scored live pass, its trial's end (the header's `practice once`): finished with no replay, its
   * run flagged REPLAY_SKIPPED_FLAG in the same transaction, then the fan-in told. What a dead grader's pass of the
   * trial (or its scorer) left under the work root goes once the trial is finished, as a replay's claim would have
   * taken it, released from the sandbox's daemon in one go (grade.ts releaseScratch, its header's Releasing). A staged
   * final's first trial cut at the line ends the same way (the header's `staged final`), `why` saying which it is.
   */
  const practiceOnce = async (c: TrialRunContext, row: TrialRow, why = 'a practice trial run once'): Promise<AgentTrialOutcome | 'again'> => {
    const done = await db.transaction(async (tx) => {
      const moved = await moveTrial(tx, row, { ...trialEnding('finished'), replayStartedAt: null, replayFinishedAt: null });
      if (moved !== null) await addRunFlags(tx, row.runId, [REPLAY_SKIPPED_FLAG]);
      return moved;
    });
    if (done === null) return 'again';
    const removed: string[] = [];
    try {
      await reapDeadScratch(c.sandbox, done, `the end of live pass ${done.attempt}, ${why}`, null, removed);
    } finally {
      await releaseScratch(c.sandbox, removed);
    }
    await poke(done);
    return { kind: 'done', status: 'finished' };
  };

  // ---------------------------------------------------------------- a staged final's first trial (the header's `staged final`)

  /**
   * The phase's cut as it stands now: read afresh, since the run's context read the phase as the job began, a live
   * pass ago maybe. `line` is null with `decidedAt` set when fewer entries were scored than the contenders.
   */
  const cutNow = async (phaseId: string): Promise<{ decidedAt: Date | null; line: number | null }> => {
    const [p] = await db.select({ decidedAt: phase.cutDecidedAt, line: phase.cutLinePoints }).from(phase).where(eq(phase.id, phaseId));
    if (p === undefined) throw new Error(`phase ${phaseId} does not exist`);
    return { decidedAt: p.decidedAt, line: p.line };
  };

  /**
   * The phase's final-cut job poked under this minute's id (server/jobs.ts sendFinalCut, finalCutWaitJobId: every first
   * trial ending in one minute is one job): its id, or null when this minute's was sent already. A send that fails is
   * logged, never thrown: the trial stays where it is, and the cut job, sent at the phase's lock, looks again at its own
   * next slot while the cut is undecided, so a queue fault never holds a scored trial.
   */
  const pokeCut = async (c: TrialRunContext, row: TrialRow): Promise<string | null> => {
    try {
      return await sendFinalCut(deps.jobs, c.ph.id, { id: finalCutWaitJobId(c.ph.id, now()) });
    } catch (err) {
      log(`[grade] ${what(row)}: ${c.slug}'s final-cut job could not be poked (${err instanceof Error ? err.message : String(err)}); the cut job looks again at its own next slot`);
      return null;
    }
  };

  /**
   * A staged final's first trial measured against the stored `line` (server/grading/final-cut.ts cutVerdictOf, the rule
   * the cut job judged the field by): a timeout at 0 points, a scored trial at the points cutPointsOf reads of it alone
   * (aggregateTrials with the entry's facts and the floor's count off its stored cassette, as the fan-in will score it),
   * the house's own entry and a baseline (cutExempt) a contender whatever it scored.
   */
  const cutVerdict = async (c: TrialRunContext, row: TrialRow, line: number | null): Promise<'contender' | 'cut'> => {
    const cut = await import('../server/grading/final-cut.ts');
    const house = cut.cutExempt(c.sub);
    const { sorting } = cut.cutColumnOf(c.bundle.leaderboard);
    if (row.status === 'timeout') return cut.cutVerdictOf({ status: 'timeout', points: 0, house }, line, sorting);
    const { cassetteModelCalls, readCassette } = await import('./gateway/cassette.ts');
    const cassette = await readCassette(blobs, row.cassetteSha256!);
    // A live pass recorded and scored is measured as a finished trial on the live pass's scores (cutPointsOf's terms).
    const result = agentTrialResultOf(row, cassette, cassetteModelCalls(cassette), 'finished');
    return cut.cutVerdictOf({ status: 'scored', points: cut.cutPointsOf(result, c.bundle.leaderboard, agentEntryFactsOf(c.sub, c.harness)), house }, line, sorting);
  };

  /**
   * A contender's later trials (the header's `staged final`): trials 1 to K-1 of the draw its run was started on (the
   * phase's trials, its draw verified, and their dataset the run's, else a PermanentJobError: a redraw since runs no
   * contender's trials on other instances) made where they are not (record.ts insertTrials, which keeps a row the cut
   * job made on its contenders' line, its tag with it; a late contender's join its final's line), then each one still
   * to start its job for live pass 1 under its stable id (gradeTrialJobId pass 1, as the cut job sends it), at its tag's
   * priority, a tag past MAX_GRADE_TRIAL_QUEUE_TAG at the cap's (cappedTrialPriority), logged once.
   */
  const contend = (c: TrialRunContext, row: TrialRow): Promise<void> => stageTrials(c, row, 1, Number.MAX_SAFE_INTEGER, `a contender at ${c.slug}'s cut`);

  /**
   * A staged final's run's trials `from` to `to` - 1 (the header's `staged final`: a contender's later trials, or the next
   * stage of a run through an earlier cut, or a finalist's last), as contend makes trials 1 to K-1: of the draw its run
   * was started on, made where they are not (insertTrials, which keeps a row the cut job made on its stage's line, its
   * tag with it), then each one of the run still to start its job for live pass 1 under its stable id, at its tag's
   * priority (cappedTrialPriority), logged once, `lead` saying why.
   */
  const stageTrials = async (c: TrialRunContext, row: TrialRow, from: number, to: number, lead: string): Promise<void> => {
    const wall = c.bundle.limits.wall_budget_sec;
    // The competition directory as the run's context first read it: its trials sidecar (a sandbox's staged setup holds the env and scorer alone).
    const phaseTrials = await agentPhaseTrials({ slug: c.slug, bundle: c.bundle, compDir: competitionDirOf(deps, c.slug, c.harness), sealedDir, phaseKey: c.ph.key, chain: instanceChainOptions(deps.drandChain) });
    const dataset = agentDatasetSha256(phaseTrials.trials);
    if (dataset !== c.run.datasetSha256) {
      throw new PermanentJobError(`run ${row.runId} was started on the draw whose dataset is ${c.run.datasetSha256}, and ${c.slug}'s final draw is now ${dataset}: a contender's later trials run only on the draw its run was started on`);
    }
    const later = phaseTrials.trials.filter((t) => t.index >= from && t.index < to);
    await insertTrials(
      db,
      row.runId,
      later.map((t) => ({ index: t.index, instanceSha256: t.instance_sha256, instanceRef: sealedRef(sealedDir, t.dir) })),
      wall,
    );
    const expireInSeconds = agentTrialExpirySeconds(wall, c.slug);
    const capped: number[] = [];
    const sentIds: string[] = [];
    for (const t of await loadTrials(db, row.runId)) {
      if (t.trialIndex === 0 || t.status !== 'pending' || t.attempt !== 0) continue;
      const tag = t.queueTag ?? (await retagTrial(db, t, wall)).tag;
      const { priority, capped: over } = cappedTrialPriority(tag);
      if (over) capped.push(t.trialIndex);
      // As its run is (the header's `layout`): a flagged run's later trials say `one_pod`, as its qualifying trial's job did.
      const id = await deps.jobs.send('grade-trial', trialPayloadOf({ run_id: row.runId, trial_index: t.trialIndex, pass: 1, first_pass: 1 }, c.layout), { id: gradeTrialJobId(row.runId, t.trialIndex, 1), priority, expireInSeconds });
      if (id !== null) sentIds.push(`${t.trialIndex}: ${id}`);
    }
    if (capped.length > 0) log(`[grade] run ${row.runId} (${c.slug}): the queue tags of its trials ${capped.join(', ')} are past ${MAX_GRADE_TRIAL_QUEUE_TAG}, which no priority holds: their jobs are sent at the cap's priority`);
    log(`[grade] ${what(row)}: ${lead}, its later trials ${later.map((t) => t.index).join(', ')} made${sentIds.length === 0 ? ' (their jobs sent already)' : `, their jobs sent (${sentIds.join('; ')})`}`);
  };

  /**
   * A staged final's first trial, its live pass recorded and scored (the header's `staged final`): the cut read afresh;
   * undecided, the trial is parked (its queue tag deferred first, the cut read once more, then the phase's final-cut job
   * poked); decided, its verdict against the stored line: cut, it ends there as a practice trial does; a contender, its
   * later trials made and sent, then it replays as any final trial.
   */
  const stagedFirst = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome | 'again'> => {
    let cut = await cutNow(c.ph.id);
    if (cut.decidedAt === null) {
      // Out of every contest's n_c while it waits on the cut (record.ts deferTrialQueueTag: its charge kept); the job that
      // wakes it takes a tag again (faultTrialQueueTag tags a trial with none).
      const deferred = row.queueTag !== null;
      if (deferred) await deferTrialQueueTag(db, row);
      cut = await cutNow(c.ph.id);
      if (cut.decidedAt === null) {
        const jobId = await pokeCut(c, row);
        log(`[grade] ${what(row)}: its first trial is scored and parked at live_done until ${c.slug}'s cut is decided (final-cut job ${jobId ?? 'of this minute sent already'})`);
        return { kind: 'parked', phase_id: c.ph.id, job_id: jobId };
      }
      // Decided between the two reads: its place in the queue back before it goes on.
      if (deferred) await faultTrialQueueTag(db, row, c.bundle.limits.wall_budget_sec);
    }
    if ((await cutVerdict(c, row, cut.line)) === 'cut') return practiceOnce(c, row, `a final entry that stopped at its qualifying trial (cut at ${c.slug}'s line, ${cut.line})`);
    await contend(c, row);
    return replay(c, row, data, ctx);
  };

  // ---------------------------------------------------------------- a staged final's stages (the header's `staged final`, its stages)

  /** The run's fate as it stands now (stagedFateOf): every cut read afresh, the run's trials measured afresh. */
  const fateNow = async (c: TrialRunContext, staged: StagedFinalT, runId: string): Promise<StagedFate> => stagedFateOf(db, blobs, { sub: c.sub, phaseId: c.ph.id, bundle: c.bundle }, staged, await loadTrials(db, runId));

  /** The series a parked trial's pass began (its last job's first_pass, as the cut job reads it), else its parked pass; at most that pass. */
  const firstPassOf = async (t: TrialRow): Promise<number> => {
    const [table] = rowsOf<{ present: boolean }>(await db.execute(sql`select to_regclass(${JOB_TABLE}) is not null as present`));
    if (table?.present !== true) return t.attempt;
    const [job] = rowsOf<{ first_pass: string | null }>(
      await db.execute(
        sql`select j.data->>'first_pass' as first_pass from ${sql.raw(JOB_TABLE)} j
          where j.name = ${'grade-trial'} and j.data->>'run_id' = ${t.runId} and j.data->>'trial_index' = ${String(t.trialIndex)}
          order by j.created_on desc, j.id desc limit 1`,
      ),
    );
    const n = Number(job?.first_pass);
    return Number.isSafeInteger(n) && n >= 1 && n <= t.attempt ? n : t.attempt;
  };

  /**
   * The run's other parked qualifying trials woken once its fate is decided at `cut` (the header's `staged final`, its
   * stages): each one's job for the pass it parked on, under the key of the cut that decided it (stagedWakeKey, the id
   * the final-cut job sends it under, so either sender sends one job), at its tag's priority (record.ts
   * faultTrialQueueTag: parking left it none, so it takes one afresh; one an earlier wake gave it is kept). Its handler
   * ends it there (a run cut) or replays it (a finalist). A send or a write that fails is logged, never thrown: the cut
   * job's wake sends the same job.
   */
  const wakeParked = async (c: TrialRunContext, row: TrialRow, under: number, cut: number, decidedAt: Date): Promise<void> => {
    const wall = c.bundle.limits.wall_budget_sec;
    const expireInSeconds = agentTrialExpirySeconds(wall, c.slug);
    const key = stagedWakeKey(cut, decidedAt);
    const woke: string[] = [];
    for (const t of await loadTrials(db, row.runId)) {
      if (t.trialIndex === row.trialIndex || t.trialIndex >= under || !parkedTrial(t)) continue;
      try {
        const { priority, capped } = cappedTrialPriority(t.queueTag ?? (await faultTrialQueueTag(db, t, wall)) ?? 0);
        if (capped) log(`[grade] trial ${t.trialIndex} of run ${t.runId} (${c.slug}): its queue tag is past ${MAX_GRADE_TRIAL_QUEUE_TAG}, which no priority holds: its job is sent at the cap's priority`);
        const id = await deps.jobs.send(
          'grade-trial',
          { run_id: t.runId, trial_index: t.trialIndex, pass: t.attempt, first_pass: await firstPassOf(t) },
          { id: gradeTrialJobId(t.runId, t.trialIndex, t.attempt, key), priority, expireInSeconds },
        );
        woke.push(`${t.trialIndex}: ${id ?? 'sent already'}`);
      } catch (err) {
        log(`[grade] trial ${t.trialIndex} of run ${t.runId} (${c.slug}): its job could not be sent at cut ${cut}'s wake (${err instanceof Error ? err.message : String(err)}); the final-cut job's wake sends it`);
      }
    }
    if (woke.length > 0) log(`[grade] ${what(row)}: its run's parked trials woken at cut ${cut} of ${c.slug}'s final (${woke.join('; ')})`);
  };

  /**
   * A qualifying trial of a staged final that names earlier cuts (the header's `staged final`, its stages), its live
   * pass recorded and scored: the run's fate read afresh (fateNow). Waiting (a cut undecided, or the run through a cut
   * with its next stage not all measured), the trial parks: its queue tag deferred first and the fate read once more;
   * still waiting, a run through a cut gets that cut's next stage made and sent where it is not (stageTrials), the
   * phase's final-cut job is poked while the cut it waits on is undecided, and nothing else is written. Cut at a cut, it
   * ends as a practice trial does and the run's other parked trials are woken to end the same way (wakeParked); a
   * finalist's remaining trials are made and sent, its other parked trials woken, and it replays as any final trial.
   */
  const stagedStage = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext, staged: StagedFinalT): Promise<AgentTrialOutcome | 'again'> => {
    let s = await fateNow(c, staged, row.runId);
    if (fateWaits(s.fate)) {
      // Out of every contest's n_c while it waits (record.ts deferTrialQueueTag: its charge kept); the job that wakes it
      // takes a tag again (faultTrialQueueTag tags a trial with none).
      const deferred = row.queueTag !== null;
      if (deferred) await deferTrialQueueTag(db, row);
      s = await fateNow(c, staged, row.runId);
      if (fateWaits(s.fate)) {
        const fate = s.fate;
        if (fate.fate === 'through') {
          const through = s.cuts[fate.cut]!;
          await stageTrials(c, row, through.at, through.to, `through cut ${fate.cut} of ${c.slug}'s final`);
        }
        const waitedOn = cutWaitedOn(fate);
        const undecided = s.decided[waitedOn] === null;
        const jobId = undecided ? await pokeCut(c, row) : null;
        const until = fate.fate === 'pending' ? `cut ${waitedOn} judges its first ${s.cuts[waitedOn]!.at} trials` : `its trials to ${s.cuts[fate.cut]!.to} are measured for cut ${waitedOn}`;
        log(`[grade] ${what(row)}: scored and parked at live_done until ${until} (${undecided ? `cut ${waitedOn} undecided: final-cut job ${jobId ?? 'of this minute sent already'}` : `cut ${waitedOn} decided, nothing poked`})`);
        return { kind: 'parked', phase_id: c.ph.id, job_id: jobId };
      }
      // Decided between the two reads: its place in the queue back before it goes on.
      if (deferred) await faultTrialQueueTag(db, row, c.bundle.limits.wall_budget_sec);
    }
    const last = s.cuts.at(-1)!;
    if (s.fate.fate === 'cut') {
      const at = s.cuts[s.fate.cut]!;
      const decided = s.decided[at.index]!;
      const done = await practiceOnce(c, row, `a final entry that stopped at cut ${at.index} (its total over ${at.at} instances against ${c.slug}'s line, ${decided.line})`);
      await wakeParked(c, row, last.at, at.index, decided.decidedAt);
      return done;
    }
    await stageTrials(c, row, last.at, last.to, `a finalist at ${c.slug}'s last cut`);
    await wakeParked(c, row, last.at, last.index, s.decided[last.index]!.decidedAt);
    return replay(c, row, data, ctx);
  };

  /**
   * A qualifying trial of a staged final that names earlier cuts that ran out of its wall (the header's `staged final`,
   * its stages), done already, the fan-in told: the run's fate read afresh. Waiting, the phase's final-cut job poked
   * while the cut it waits on is undecided, and a run through a cut gets that cut's next stage (a house entry's: an
   * entrant with a trial at its wall never goes on); cut, its other parked trials woken to end; a finalist (the house's)
   * its remaining trials and its parked trials woken to replay. Never replayed itself: a timeout never is.
   */
  const stagedStageTimeout = async (c: TrialRunContext, row: TrialRow, staged: StagedFinalT): Promise<void> => {
    const s = await fateNow(c, staged, row.runId);
    const last = s.cuts.at(-1)!;
    if (fateWaits(s.fate)) {
      const fate = s.fate;
      if (fate.fate === 'through') {
        const through = s.cuts[fate.cut]!;
        await stageTrials(c, row, through.at, through.to, `through cut ${fate.cut} of ${c.slug}'s final`);
      }
      const waitedOn = cutWaitedOn(fate);
      if (s.decided[waitedOn] === null) {
        const jobId = await pokeCut(c, row);
        log(`[grade] ${what(row)}: it ran out of its wall before cut ${waitedOn} of ${c.slug}'s final is decided (final-cut job ${jobId ?? 'of this minute sent already'})`);
      }
      return;
    }
    if (s.fate.fate === 'cut') {
      await wakeParked(c, row, last.at, s.fate.cut, s.decided[s.fate.cut]!.decidedAt);
      return;
    }
    await stageTrials(c, row, last.at, last.to, `a finalist at ${c.slug}'s last cut`);
    await wakeParked(c, row, last.at, last.index, s.decided[last.index]!.decidedAt);
  };

  /**
   * A staged final's first trial that ran out of its wall (the header's `staged final`), done already, the fan-in told:
   * undecided, the phase's final-cut job poked (the cut job's wake gives a house entry's run its later trials); decided
   * (a late run, a re-queued one, or a job of the trial run again), a contender's later trials made and sent here: the
   * house's entry and a baseline go on whatever they scored, and an entrant's run is cut at it, which the fan-in
   * finishes. Nothing on any other trial. On a final that names earlier cuts, every qualifying trial at its wall is
   * stagedStageTimeout's.
   */
  const stagedTimeout = async (c: TrialRunContext, row: TrialRow): Promise<void> => {
    if (row.status !== 'timeout') return;
    const staged = stagedFinalRun(c.bundle, c.ph.key);
    if (staged === null) return;
    if (staged.cuts !== undefined) {
      if (row.trialIndex < stagedQualifyingTrials(staged)) await stagedStageTimeout(c, row, staged);
      return;
    }
    if (row.trialIndex !== 0) return;
    const cut = await cutNow(c.ph.id);
    if (cut.decidedAt === null) {
      const jobId = await pokeCut(c, row);
      log(`[grade] ${what(row)}: its first trial ran out of its wall before ${c.slug}'s cut is decided (final-cut job ${jobId ?? 'of this minute sent already'})`);
      return;
    }
    if ((await cutVerdict(c, row, cut.line)) === 'contender') await contend(c, row);
  };

  /**
   * A live pass about to set out from a trial with no place in the queue (record.ts `queue tags`: it woke from a deferral
   * its contest's policy made, or was made before the column): tagged afresh at max(V, F), and when this job was sent
   * ahead of that (its priority above the tag's), sent again at it under an id of this job's (one hop, a poll or so) and
   * nothing run, so a wave of deferred trials waking at once never jumps the line. Null: the pass goes on.
   */
  const queueTurn = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome | null> => {
    if (row.queueTag !== null) return null;
    const { tag } = await retagTrial(db, row, c.bundle.limits.wall_budget_sec);
    const priority = gradeTrialPriority(tag);
    if (ctx.priority === undefined || ctx.priority <= priority) return null;
    const jobId = await deps.jobs.send('grade-trial', data, { id: gradeTrialJobId(row.runId, row.trialIndex, data.pass, `queue:${ctx.id}`), priority, expireInSeconds: agentTrialExpirySeconds(c.bundle.limits.wall_budget_sec, c.slug) });
    log(`[grade] ${what(row)}: pass ${data.pass} takes its place in the queue afresh (tag ${tag}), behind the trials ahead of it: sent again as job ${jobId ?? '(sent already)'}`);
    return { kind: 'queued', tag, job_id: jobId };
  };

  // ---------------------------------------------------------------- a practice instance re-drawn (the header's `re-drawn practice`)

  /**
   * The practice instance a dev trial's competition directory commits it to, read as a hint and verified by nothing: its
   * instance.yaml's practice trial 0 instance_sha256; null when the directory holds no instance.yaml (no practice draw is
   * committed there to re-draw, and the trial takes today's path), undefined when it cannot be read so (the verified read,
   * agentPhaseTrials, says why). It decides only whether that verified read is made: nothing is re-pointed on it.
   */
  const committedPractice = async (c: TrialRunContext): Promise<string | null | undefined> => {
    const path = join(competitionDirOf(deps, c.slug, c.harness), INSTANCE_FILE);
    let bytes: Buffer | null;
    try {
      bytes = readSmallFile(path, MAX_INSTANCE_BYTES, `${c.slug}'s ${INSTANCE_FILE}`);
    } catch {
      return undefined;
    }
    if (bytes === null) return null;
    try {
      const { parse } = await import('yaml');
      const doc = parse(bytes.toString('utf8')) as { practice?: { trials?: { t?: unknown; instance_sha256?: unknown }[] } } | null;
      const first = doc?.practice?.trials?.find((t) => t.t === 0)?.instance_sha256;
      return typeof first === 'string' ? first : undefined;
    } catch {
      return undefined;
    }
  };

  /** Whether `dir` digests to `sha256` as runTrial checks its instance (grader/agent.ts instanceSha256, walked and hashed off the event loop: instanceSha256Async); a tree that cannot be read does not. */
  const digestsTo = async (dir: string, sha256: string): Promise<boolean> => {
    const { instanceSha256Async: digest } = await import('./agent.ts');
    try {
      return (await digest(dir)) === sha256;
    } catch {
      return false;
    }
  };

  /**
   * Before a dev trial's live pass sets out from a pending or void row (the header's `re-drawn practice`): when its
   * instance.yaml or the tree it runs on says its instance may not be the one drawn now, the phase's practice trial
   * read as startAgentRun reads it (agentPhaseTrials: instance.yaml checked in full, the tree verified). Not drawn yet
   * (InstanceNotDrawnError): the job waits for it (practiceNotDrawn). Drawn, and another instance than the row's: the
   * trial re-pointed (repoint) and read afresh ('again'). Null: the pass goes on as it is (the row's instance is the
   * one drawn, no instance.yaml commits one, or the trial is a final's, whose scored draw is never re-drawn in place).
   */
  const practiceCheck = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>): Promise<AgentTrialOutcome | 'again' | null> => {
    if (c.ph.key !== 'dev') return null;
    const committed = await committedPractice(c);
    if (committed === null) return null;
    if (committed === row.instanceSha256 && (await digestsTo(instanceDirOf(row), row.instanceSha256))) return null;
    let drawn: AgentPhaseTrials;
    try {
      drawn = await agentPhaseTrials({ slug: c.slug, bundle: c.bundle, compDir: competitionDirOf(deps, c.slug, c.harness), sealedDir, phaseKey: c.ph.key, chain: instanceChainOptions(deps.drandChain) });
    } catch (err) {
      if (err instanceof InstanceNotDrawnError) return practiceNotDrawn(c, row, data, err);
      throw err;
    }
    const current = drawn.trials.find((t) => t.index === row.trialIndex);
    if (current === undefined) throw new PermanentJobError(`${what(row)} is a dev trial, and ${c.slug}'s practice draw runs trial${drawn.trials.length === 1 ? '' : 's'} ${drawn.trials.map((t) => t.index).join(', ')} alone`);
    if (current.instance_sha256 === row.instanceSha256) return null;
    return repoint(c, row, data, drawn, current);
  };

  /**
   * A dev trial whose practice instance is not drawn as instance.yaml commits it (the header's `re-drawn practice`: the
   * release's practice draw has not re-drawn it yet, practice/ is not there, or instance.yaml was drawn by another
   * generator than the stored bundle's, the release not seeded yet: releaseWindowError): no pass runs, nothing of the trial is
   * marked and no pass of its series is spent. The job is sent again for the next PRACTICE_REDRAW_RECHECK_MS slot (one
   * job of a pass, series and slot), keeping its place in the queue as a platform fault does, and the competition's
   * practice-draw job is sent as a waiting dev grade sends it (server/jobs.ts sendPracticeDraw: one a slug, hour and
   * instance.yaml, the one this image ships, so only a grader of this release draws it); a
   * send of that which fails is logged, and the next look sends it. Nothing is paged.
   */
  const practiceNotDrawn = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, err: InstanceNotDrawnError): Promise<AgentTrialOutcome> => {
    const at = now();
    const slot = Math.floor(at.getTime() / PRACTICE_REDRAW_RECHECK_MS) + 1;
    const until = new Date(slot * PRACTICE_REDRAW_RECHECK_MS);
    const jobId = await deps.jobs.send('grade-trial', data, {
      id: gradeTrialJobId(row.runId, row.trialIndex, data.pass, `practice-draw:${data.first_pass}:${slot}`),
      startAfter: until,
      ...(await sendOptions(c, row, 'fault')),
    });
    let draw: string;
    try {
      const id = await sendPracticeDraw(deps.jobs, c.slug, at);
      draw = id === null ? "its practice-draw job of this hour is sent already" : `its practice-draw job ${id} is sent`;
    } catch (e) {
      draw = `its practice-draw job could not be sent (${e instanceof Error ? e.message : String(e)}), and the next look sends it`;
    }
    const heldBy = `${c.slug}'s practice instance is not drawn as its ${INSTANCE_FILE} commits it: ${err.message}`;
    log(`[grade] ${what(row)}: pass ${data.pass} waits for ${until.toISOString()}: ${heldBy}; ${draw}, and no pass is spent on it`);
    return { kind: 'waiting', until, job_id: jobId, held_by: heldBy };
  };

  /**
   * A dev trial whose practice instance was re-drawn (the header's `re-drawn practice`) re-pointed at the practice trial
   * drawn now, in one transaction: its instance_sha256 and instance_ref the current trial's, written only while the row
   * is still where it was read (moveTrial's discipline, on the two columns TrialUpdate keeps out of every other move),
   * and its run's dataset_sha256 and seed what startAgentRun stamps for the current draw (agentDatasetSha256, the phase
   * seed over it), written only while the run is running and no trial of it holds a live pass on record. One line logged
   * naming both digests; then 'again', the row read afresh, so the pass runs on the current instance under the bundle as
   * it stands. A run that is over runs nothing more; one that holds a recorded pass is never put on two draws (a
   * PermanentJobError).
   */
  const repoint = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>, drawn: AgentPhaseTrials, current: AgentPhaseTrial): Promise<AgentTrialOutcome | 'again'> => {
    const [comp] = await db.select({ seedKey: competition.seedKey, bundleSha256: competition.bundleSha256, slug: competition.slug }).from(competition).where(eq(competition.id, c.ph.competitionId));
    if (comp === undefined) throw new Error(`competition ${c.ph.competitionId} does not exist`);
    const datasetSha256 = agentDatasetSha256(drawn.trials);
    const seed = phaseSeed(competitionSeedKey(comp), c.ph.key, datasetSha256);
    const instanceRef = sealedRef(sealedDir, current.dir);
    let done: 'repointed' | 'recorded' | 'over';
    try {
      done = await db.transaction(async (tx) => {
        const [recorded] = await tx
          .select({ n: count() })
          .from(runTrial)
          .where(and(eq(runTrial.runId, row.runId), inArray(runTrial.status, ['live_done', 'replaying', 'finished', 'timeout', 'nondeterministic'])));
        if (Number(recorded?.n ?? 0) > 0) return 'recorded' as const;
        const [stamped] = await tx
          .update(run)
          .set({ datasetSha256, seed })
          .where(and(eq(run.id, row.runId), eq(run.status, 'running')))
          .returning({ id: run.id });
        if (stamped === undefined) return 'over' as const;
        const [moved] = await tx
          .update(runTrial)
          .set({ instanceSha256: current.instance_sha256, instanceRef })
          .where(
            and(
              eq(runTrial.id, row.id),
              eq(runTrial.status, row.status),
              eq(runTrial.attempt, row.attempt),
              eq(runTrial.instanceSha256, row.instanceSha256),
              row.replayStartedAt === null ? isNull(runTrial.replayStartedAt) : eq(runTrial.replayStartedAt, row.replayStartedAt),
            ),
          )
          .returning({ id: runTrial.id });
        // Moved meanwhile: the run's stamp goes back with the transaction, and the row is read afresh.
        if (moved === undefined) throw new TrialTaken(`${what(row)} moved on from ${row.status} while it was re-pointed`);
        return 'repointed' as const;
      });
    } catch (err) {
      if (err instanceof TrialTaken) return 'again';
      throw err;
    }
    if (done === 'over') return { kind: 'stopped', why: `run ${row.runId} is no longer running: its trials run no more` };
    if (done === 'recorded') {
      throw new PermanentJobError(
        `${what(row)} runs on instance ${row.instanceSha256}, and ${c.slug}'s practice instance is drawn as ${current.instance_sha256} now; its run holds a live pass on record, so it is not put on a second draw`,
      );
    }
    log(
      `[grade] ${what(row)}: ${c.slug}'s practice instance was re-drawn from ${row.instanceSha256} to ${current.instance_sha256}: the trial is re-pointed at ${instanceRef}, its run's dataset_sha256 ${c.run.datasetSha256 ?? 'none'} is ${datasetSha256} and its seed ${c.run.seed ?? 'none'} is ${seed}, and pass ${data.pass} runs on the instance drawn now under the bundle as it stands (wall ${c.bundle.limits.wall_budget_sec} s)`,
    );
    return 'again';
  };

  /**
   * A dev trial's recorded live pass, unscored, whose instance directory no longer digests to its instance_sha256 (the
   * header's `re-drawn practice`: its practice instance re-drawn under it, so the scorer would read another instance's
   * reference): voided INSTANCE_REDRAWN_VOID_REASON, its record kept as any void's (its spend counted as voided spend as
   * its next pass starts), and its next pass sent at once, spending no pass of its series (voided); that pass is
   * re-pointed as it sets out (practiceCheck). Null: its tree is the instance it played, or no instance.yaml commits a
   * practice draw there, and it is scored as ever.
   */
  const redrawnUnderPass = async (c: TrialRunContext, row: TrialRow, data: JobPayload<'grade-trial'>): Promise<AgentTrialOutcome | 'again' | null> => {
    if (c.ph.key !== 'dev' || row.status !== 'live_done' || row.score !== null) return null;
    if ((await committedPractice(c)) === null) return null;
    if (await digestsTo(instanceDirOf(row), row.instanceSha256)) return null;
    const error = `live pass ${row.attempt} ran on instance ${row.instanceSha256}, and ${instanceDirOf(row)} no longer digests to it (${c.slug}'s practice instance was re-drawn under it before it was scored): it cannot be scored on the instance it played`;
    const moved = await moveTrial(db, row, { status: 'void', voidReason: INSTANCE_REDRAWN_VOID_REASON, error });
    return moved === null ? 'again' : voided(c, moved, data, 0);
  };

  /** The staged final a trial qualifies in (stagedFinalRun), when it is one of its run's qualifying trials (stagedQualifyingTrials); else null. */
  const qualifying = (c: TrialRunContext, row: TrialRow): StagedFinalT | null => {
    const staged = stagedFinalRun(c.bundle, c.ph.key);
    return staged !== null && row.trialIndex < stagedQualifyingTrials(staged) ? staged : null;
  };

  /** Move the trial on as far as this job's pass reaches (see createAgentTrialHandler). */
  const advance = async (c: TrialRunContext, data: JobPayload<'grade-trial'>, ctx: AgentTrialContext): Promise<AgentTrialOutcome> => {
    // Each step moves the row once; a row another attempt moved meanwhile is read again.
    for (let step = 0; step < 12; step++) {
      const row = await trialRow(data);
      if (row === null) return { kind: 'stopped', why: `run ${data.run_id} has no trial ${data.trial_index}` };
      const notMine = (state: string): AgentTrialOutcome => ({ kind: 'stopped', why: `${what(row)} is ${state}: not this job's (pass ${data.pass})` });
      let next: AgentTrialOutcome | 'again';
      switch (row.status) {
        case 'finished':
        case 'timeout':
        case 'nondeterministic':
          await poke(row);
          // A staged final's first trial at its wall, its job run again: the cut poked or judged (the header's `staged final`).
          await stagedTimeout(c, row);
          return { kind: 'done', status: row.status };
        case 'held':
          return { kind: 'stopped', why: `${what(row)} is held (${row.voidReason}): it waits for an admin's re-queue` };
        case 'pending':
        case 'void':
          // This job's own void, its next pass maybe never sent (the send failed): sent now, or the trial held.
          if (row.status === 'void' && row.attempt === data.pass) {
            next = await voided(c, row, data, row.voidReason === INTERRUPTED_VOID_REASON || row.voidReason === INSTANCE_REDRAWN_VOID_REASON ? 0 : AGENT_VOID_RERUN_DELAY_MS);
            break;
          }
          if (row.attempt !== data.pass - 1) return notMine(`${row.status} after pass ${row.attempt}`);
          {
            const turn = await queueTurn(c, row, data, ctx);
            if (turn !== null) return turn;
          }
          {
            // A dev trial's practice instance not drawn yet, or re-drawn since its row was made (the header's `re-drawn practice`).
            const checked = await practiceCheck(c, row, data);
            if (checked !== null) {
              next = checked;
              break;
            }
          }
          next = await livePass(c, row, data, ctx);
          break;
        case 'live_running':
          if (row.attempt !== data.pass) return notMine(`running pass ${row.attempt}`);
          next = await interrupted(c, row, data, ctx);
          break;
        case 'live_done':
        case 'replaying':
          if (row.attempt !== data.pass) return notMine(`${row.status} on pass ${row.attempt}`);
          if (!liveRecorded(row)) throw new PermanentJobError(`${what(row)} is ${row.status} with its live pass not whole on record`);
          // A target's pass is whole only with its house lane's cassette (what the replay serves the env again).
          if (c.harness.target !== undefined && row.houseCassetteSha256 === null) throw new PermanentJobError(`${what(row)} is ${row.status} with no house lane cassette on record, under a harness with a target`);
          if (row.score === null) {
            // A dev pass whose practice instance was re-drawn under it is never scored on another's reference (the header's `re-drawn practice`).
            const redrawn = await redrawnUnderPass(c, row, data);
            if (redrawn !== null) {
              next = redrawn;
              break;
            }
            // The scorer is one pod: while the node has no room for it, the job waits for the next slot.
            const short = await roomShort(1);
            if (short !== null) return waitForRoom(c, data, short);
            await scorePass(c, row);
            next = 'again';
          } else if (row.status === 'replaying' && row.replayFinishedAt === null) {
            // A replay with no end found here: the attempt that ran it was cut off (a faulted one records its end).
            next = await replayCutOff(c, row, data, ctx);
          } else if (row.status === 'live_done' && c.ph.key === 'dev') {
            // A dev trial runs once (the header's `practice once`); one a release before claimed for its replay replays on.
            next = await practiceOnce(c, row);
          } else if (row.status === 'live_done' && qualifying(c, row) !== null) {
            // A staged final's qualifying trial waits on, or is judged by, its phase's cuts (the header's `staged final`):
            // trial 0 against the one cut, or every trial under the last cut against the cuts a final names.
            const staged = qualifying(c, row)!;
            next = staged.cuts === undefined ? await stagedFirst(c, row, data, ctx) : await stagedStage(c, row, data, ctx, staged);
          } else {
            next = await replay(c, row, data, ctx);
          }
          break;
      }
      if (next !== 'again') return next;
    }
    throw new Error(`${what({ runId: data.run_id, trialIndex: data.trial_index })} kept moving under this job; the next attempt takes it from where it stands`);
  };

  /**
   * A refused admin key (masq.ts MasqAdminKeyRefusal), engine (network.ts IsolationRefusal) or router-served target
   * (HouseRouterRefusal): paged (once an hour per refusal), the trial left as it is; a last attempt hands the job on, later.
   */
  const refused = async (data: JobPayload<'grade-trial'>, ctx: AgentTrialContext, err: MasqAdminKeyRefusal | IsolationRefusal | HouseRouterRefusal, c: TrialRunContext, terms: RefusalTerms): Promise<void> => {
    const at = now();
    let again = '';
    if (isLastAttempt(ctx)) {
      const startAfter = new Date(at.getTime() + AGENT_REFUSAL_RETRY_MS);
      const slot = Math.ceil(startAfter.getTime() / AGENT_REFUSAL_RETRY_MS);
      try {
        await deps.jobs.send('grade-trial', data, { id: gradeTrialJobId(data.run_id, data.trial_index, data.pass, `refused:${slot}`), startAfter, ...(await sendOptions(c, { runId: data.run_id, trialIndex: data.trial_index }, 'fault')) });
        again = ` This trial's job has spent its retries and is sent again for ${startAfter.toISOString()}.`;
      } catch (e) {
        again = ` This trial's job has spent its retries, and sending it again failed (${e instanceof Error ? e.message : String(e)}): re-queue it once ${terms.once}.`;
      }
    }
    const last = refusalsPaged.get(err.message);
    if (last !== undefined && at.getTime() - last < AGENT_REFUSAL_PAGE_MS) {
      log(`[grade] ${ctx.id}: trial ${data.trial_index} of run ${data.run_id} (${c.slug}) waits on ${terms.waitsOn}: ${err.message}.${again}`);
      return;
    }
    refusalsPaged.set(err.message, at.getTime());
    // A router-served target's refusal is its competition's alone (its message names the slug, so it is paged once an hour per competition).
    if (err instanceof HouseRouterRefusal) {
      page(
        `[grade] ALERT: ${err.message}. ` +
          `Trial ${data.trial_index} of run ${data.run_id} (entry ${c.sub.id}) and every other live pass of ${c.slug} wait: nothing of theirs is marked, no key is minted and masq is never asked, and each trial job tries again as it retries, so the trials run once ${terms.once}.${again}`,
      );
      return;
    }
    page(
      `[grade] ALERT: agent/v1 grading is stopped: ${err.message}. ` +
        `Trial ${data.trial_index} of run ${data.run_id} (${c.slug}, entry ${c.sub.id}) and every other agent/v1 trial wait: nothing of theirs is marked, and each trial job tries again as it retries, so the trials run once ${terms.once}.${again}`,
    );
  };

  /** A fault no retry mended (or a PermanentJobError): the trial held, under the fault's reason, unless it moved on or is not this job's. */
  const heldOnFault = async (data: JobPayload<'grade-trial'>, err: unknown, c: TrialRunContext | null): Promise<AgentTrialOutcome | null> => {
    const reason = err instanceof TrialHarnessFault ? err.reason : err instanceof ScorerError ? 'scorer' : HARNESS_FAULT_HOLD_REASON;
    const message = err instanceof Error ? err.message : String(err);
    for (let step = 0; step < 3; step++) {
      const row = await trialRow(data);
      if (row === null || DONE_TRIAL_STATUSES.has(row.status) || row.status === 'held') return null;
      const mine = row.status === 'pending' || row.status === 'void' ? row.attempt === data.pass - 1 || row.attempt === data.pass : row.attempt === data.pass;
      if (!mine) return null;
      // A void's record is not a live pass to replay: moved out as the trial is held (voidHeld). A trial that never set
      // out (pending at attempt 0: a fault before its first pass, such as a flagged run's trial where nothing can host
      // it) is held at this job's pass, which it never started (run_trial_attempt_spent: only a pending trial is at 0).
      const extra: TrialUpdate = row.status === 'void' ? voidHeld(row) : row.status === 'pending' && row.attempt === 0 ? { attempt: Math.max(1, data.pass) } : {};
      const out = await hold(row, reason, `${reason === HARNESS_FAULT_HOLD_REASON ? 'a fault no retry mended' : reason} on pass ${row.attempt} (${row.status}): ${message}`, c, extra);
      if (out !== 'again') return out;
    }
    return null;
  };

  return async (data, ctx) => {
    let c: TrialRunContext | null = null;
    try {
      const loaded = await runContext(data);
      if ('stopped' in loaded) return { kind: 'stopped', why: loaded.stopped };
      c = loaded;
      // The job as its run is (the header's `layout`): every re-send of it says the run's `one_pod`, whatever this one said.
      data = trialPayloadOf(data, c.layout);
      // While a scrape heat holds this host, no pass runs beside it under the `host` lease scope; under `egress`
      // scrapeHostHeldBy is null (the header's `scrape heat`).
      const heldBy = await scrapeHostHeldBy(deps);
      if (heldBy !== null) return await waitOutHeat(c, data, heldBy);
      // The env and the scorer as the sandbox mounts them: on the k8s sandbox their stages on the data claim (the header's
      // `k8s data`); an image that does not hold them as sealed is a PlatformFaultError, the trial held as on any fault.
      c = { ...c, setup: await agentSetupFor(sandbox, c.slug, c.setup) };
      return await advance(c, data, ctx);
    } catch (err) {
      // The attempt is over (expired, stopped): nothing more is written; the next attempt takes the trial from where it stands.
      if (ctx.signal.aborted) throw err;
      if (err instanceof (await import('./gateway/masq.ts')).MasqAdminKeyRefusal) {
        if (c !== null) await refused(data, ctx, err, c, KEY_REFUSAL).catch((e: unknown) => console.error(`[grade] ${ctx.id}: a refused admin key could not be paged:`, e));
        throw err;
      }
      if (err instanceof (await import('./sandbox/network.ts')).IsolationRefusal) {
        if (c !== null) await refused(data, ctx, err, c, engineRefusal(err.driver)).catch((e: unknown) => console.error(`[grade] ${ctx.id}: a refused engine could not be paged:`, e));
        throw err;
      }
      if (err instanceof HouseRouterRefusal) {
        if (c !== null) await refused(data, ctx, err, c, err.terms).catch((e: unknown) => console.error(`[grade] ${ctx.id}: a refused router house lane could not be paged:`, e));
        throw err;
      }
      if (err instanceof PermanentJobError || isLastAttempt(ctx)) {
        const out = await heldOnFault(data, err, c);
        if (out !== null) return out;
      }
      throw err;
    }
  };
}

/** Who a held trial's page names: its competition, entry and phase (null when they could not be read). */
interface HeldTrialOf {
  slug: string;
  submissionId: string;
  phaseKey: string;
}

const heldTrialOf = (c: TrialRunContext | null): HeldTrialOf | null => (c === null ? null : { slug: c.slug, submissionId: c.sub.id, phaseKey: c.ph.key });

/**
 * The page of a held trial (stage.ts TRIAL_HELD_EXPECTED_MS: an admin re-queues it within the day the entrant is
 * promised); `selfAt`, when the fan-in re-queues it by itself (selfRequeueOf), says so and from when.
 */
function trialHeldPage(row: TrialRow, c: HeldTrialOf | null, selfAt: Date | null = null): string {
  const where = c === null ? `agent/v1 run ${row.runId}` : `entry ${c.submissionId}'s agent/v1 run ${row.runId} on the ${c.phaseKey} phase`;
  const resumes = liveRecorded(row) ? 'its recorded live pass is scored and replayed again' : `a fresh series of up to ${AGENT_SERIES_PASSES} live passes runs`;
  const self =
    selfAt === null
      ? ''
      : `Upstream errors come in bursts, so its run's fan-in re-queues it by itself once, at its first look from ${selfAt.toISOString()} (${TRIAL_SELF_REQUEUE_AFTER_MS / 60_000} minutes on), unless an admin does first; held again after that, it waits for an admin. `;
  return (
    `[grade] ALERT: ${c === null ? '' : `${c.slug}: `}trial ${row.trialIndex} of ${where} is held (${row.voidReason}) after live pass ${row.attempt}: ${row.error ?? 'no detail'}. ` +
    `The run waits on it unpublished, and the entry shows as held (run flag ${TRIAL_HELD_FLAG}); the fault is the platform's, never the entry's, and a re-queue is expected within a day. ` +
    self +
    `Fix: mend what failed, then re-queue the trial at POST /api/admin/runs/${row.runId}/trials/${row.trialIndex}/requeue ({"reason": "<what was mended>"}): ${resumes}`
  );
}

/**
 * Whether `runId`'s trial `trialIndex` was re-queued by itself already (the fan-in's selfRequeue): an automatic
 * trial.requeue row of it (data.automatic) whose re-queue did not end `not_sent`. A `sending` row with no ending counts
 * (its process may have died after the trial moved on), so a trial is never re-queued by itself twice.
 */
export async function selfRequeueSpent(db: Pick<Db, 'select'>, runId: string, trialIndex: number): Promise<boolean> {
  const rows = await db
    .select({ data: auditEvent.data })
    .from(auditEvent)
    .where(
      and(
        eq(auditEvent.action, TRIAL_REQUEUE_ACTION),
        eq(auditEvent.subjectType, 'run'),
        eq(auditEvent.subjectId, runId),
        sql`${auditEvent.data}->>'automatic' = 'true'`,
        sql`${auditEvent.data}->>'trial_index' = ${String(trialIndex)}`,
      ),
    );
  const stages = new Map<string, Set<string>>();
  for (const { data } of rows) {
    const d = (data ?? {}) as { attempt?: unknown; stage?: unknown };
    if (typeof d.attempt !== 'string' || typeof d.stage !== 'string') continue;
    stages.set(d.attempt, (stages.get(d.attempt) ?? new Set()).add(d.stage));
  }
  return [...stages.values()].some((s) => !s.has('not_sent'));
}

/**
 * When the fan-in may re-queue held trial `row` by itself (TRIAL_SELF_REQUEUE_AFTER_MS from its last pass's end, which
 * its series' hold follows at once): null for a trial held for any reason but UPSTREAM_ERRORS_VOID_REASON, with no pass
 * end on record, or re-queued by itself already (selfRequeueSpent), which waits for an admin.
 */
async function selfRequeueOf(db: Pick<Db, 'select'>, row: Pick<TrialRow, 'runId' | 'trialIndex' | 'status' | 'voidReason' | 'liveFinishedAt'>): Promise<Date | null> {
  if (row.status !== 'held' || row.voidReason !== UPSTREAM_ERRORS_VOID_REASON || row.liveFinishedAt === null) return null;
  if (await selfRequeueSpent(db, row.runId, row.trialIndex)) return null;
  return new Date(row.liveFinishedAt.getTime() + TRIAL_SELF_REQUEUE_AFTER_MS);
}

/**
 * Re-queue a held trial (the admins' fix for one, POST /api/admin/runs/:runId/trials/:index/requeue:
 * server/routes/admin/grading.ts registerTrialRequeue; see trialHeldPage): back to live_done when its
 * live pass is whole on record (only its replay, or its scoring, is left), else to pending, a fresh
 * series of live passes from the next one; the run's trial_held flag taken off once no trial of it is
 * held; and its job sent under `key` (the re-queue's own id: an audit row's, so each re-queue is one
 * job). Throws RangeError when the trial is not held (or does not exist); a job the queue throws on or
 * does not take puts the trial back on hold (its flag on again) and throws, so the re-queue can be
 * asked for again.
 */
export async function requeueHeldTrial(deps: { db: Db; jobs: Pick<JobQueue, 'send'> }, input: { runId: string; trialIndex: number; key: string }): Promise<{ status: 'pending' | 'live_done'; pass: number; job_id: string }> {
  const { db } = deps;
  const [row] = await db
    .select()
    .from(runTrial)
    .where(and(eq(runTrial.runId, input.runId), eq(runTrial.trialIndex, input.trialIndex)));
  if (row === undefined || row.status !== 'held') throw new RangeError(`trial ${input.trialIndex} of run ${input.runId} is ${row?.status ?? 'not there'}, not held: only a held trial is re-queued`);
  const [r] = await db.select({ phaseId: run.phaseId, flags: run.flags }).from(run).where(eq(run.id, row.runId));
  const [ph] = r === undefined ? [] : await db.select({ competitionId: phase.competitionId }).from(phase).where(eq(phase.id, r.phaseId));
  const [comp] = ph === undefined ? [] : await db.select({ slug: competition.slug, bundle: competition.bundle }).from(competition).where(eq(competition.id, ph.competitionId));
  const bundle = comp?.bundle == null ? null : CompetitionBundle.safeParse(comp.bundle);
  if (bundle === null || !bundle.success) throw new RangeError(`run ${row.runId}'s competition has no bundle that validates`);
  const status = liveRecorded(row) ? ('live_done' as const) : ('pending' as const);
  const moved = await db.transaction(async (tx) => {
    const m = await moveTrial(tx, row, { status, replayStartedAt: null, replayFinishedAt: null });
    if (m === null) return null;
    const [still] = await tx
      .select({ n: count() })
      .from(runTrial)
      .where(and(eq(runTrial.runId, row.runId), eq(runTrial.status, 'held')));
    if (Number(still?.n ?? 0) === 0) await dropRunFlag(tx, row.runId, TRIAL_HELD_FLAG);
    return m;
  });
  if (moved === null) throw new RangeError(`trial ${input.trialIndex} of run ${input.runId} moved on while it was re-queued`);
  const pass = status === 'live_done' ? row.attempt : row.attempt + 1;
  const id = gradeTrialJobId(row.runId, row.trialIndex, pass, `requeue:${input.key}`);
  /** The job not queued: the trial held again as it stood (no job will take it on), its run flagged again. */
  const putBack = async (why: string, cause?: unknown): Promise<never> => {
    const back = await db.transaction(async (tx) => {
      const b = await moveTrial(tx, moved, { status: 'held', replayStartedAt: row.replayStartedAt, replayFinishedAt: row.replayFinishedAt });
      if (b !== null) await addRunFlags(tx, row.runId, [TRIAL_HELD_FLAG]);
      return b;
    });
    const where = back === null ? 'and it moved on meanwhile, so it was not put back on hold' : 'so it is held again';
    throw new Error(`trial ${input.trialIndex} of run ${input.runId} was not re-queued: ${why}, ${where}`, cause === undefined ? undefined : { cause });
  };
  let jobId: string | null;
  try {
    jobId = await deps.jobs.send(
      'grade-trial',
      // As its run is (the header's `layout`): a flagged run's job says `one_pod`.
      trialPayloadOf({ run_id: row.runId, trial_index: row.trialIndex, pass, first_pass: pass }, r?.flags.includes(ONE_POD_FLAG) === true ? 'pod' : 'split'),
      // A held trial is the platform's fault, never the entry's: it keeps its place in the queue (record.ts `queue tags`).
      { id, priority: gradeTrialPriority((await faultTrialQueueTag(db, row, bundle.data.limits.wall_budget_sec)) ?? 0), expireInSeconds: agentTrialExpirySeconds(bundle.data.limits.wall_budget_sec, comp?.slug) },
    );
  } catch (err) {
    return putBack(`the grade-trial queue could not take job ${id} (${err instanceof Error ? err.message : String(err)})`, err);
  }
  if (jobId === null) return putBack(`the grade-trial queue did not take job ${id}`);
  return { status, pass, job_id: jobId };
}

// ---------------------------------------------------------------- agent/v1: the fan-in

export interface AgentAggregateDeps {
  db: Db;
  blobs: BlobStore;
  /** Where the fan-in hands itself on while a trial is not done. */
  jobs: Pick<JobQueue, 'send'>;
  /** The entry's authorship summary (default as GradeWorkerDeps.loadAuthorship). */
  loadAuthorship?: GradeWorkerDeps['loadAuthorship'];
  /** Where a run that cannot be aggregated, and a trial whose job died, are paged (default console.error). */
  page?: (line: string) => void;
  log?: (line: string) => void;
  now?: () => Date;
  /**
   * The server secret a run flagged ONE_POD_FLAG has its trials' entry lane keys written into its record under
   * (onePodEntryKey; AgentTrialRecord.entry_key), as AgentTrialDeps.failKeySecret, under which its passes were handed
   * them: the two must be the same secret. Read only for such a run. Default as GradeWorkerDeps.failKeySecret.
   */
  failKeySecret?: string;
}

/** A grade-aggregate job's context as its handler reads it: its id, and its attempt and retry limit (isLastAttempt). */
export type AgentAggregateContext = Pick<JobContext, 'id'> & Partial<Pick<JobContext, 'retryCount' | 'retryLimit'>>;

/** The run statuses a finished agent/v1 run is published under (publish.ts PUBLISHED_STATUS's). */
const PUBLISHED_RUN_STATUSES: ReadonlySet<string> = new Set(['finished', 'failed', 'nondeterministic', 'timeout', 'cancelled']);

/**
 * The grade-aggregate job handler (the header's `agent/v1`): the run to publish once every trial is
 * done and the run is finished (or was, by an earlier fan-in); null while it waits, handed on.
 */
export function createAgentAggregateHandler(deps: AgentAggregateDeps): (data: JobPayload<'grade-aggregate'>, ctx: AgentAggregateContext) => Promise<AggregatedRun | null> {
  const { db, blobs } = deps;
  const now = deps.now ?? (() => new Date());
  const page = deps.page ?? ((line: string) => console.error(line));
  const log = deps.log ?? ((line: string) => console.log(line));
  const loadAuthorship = deps.loadAuthorship ?? ((submissionId: string, pricingRev: string, algoVersion?: number) => loadStoredAuthorship(db, submissionId, pricingRev, algoVersion));

  /**
   * The run's trials that wait on a job pg-boss holds dead (failed for good outside its handler): held and paged, so the
   * run waits on an admin, not on nothing. One whose pass that job's last attempt was running when it died (the trial
   * live_running, or replaying with no end: its grader died, the header's `cut off`) is no fault of anyone's: its pass's
   * job is sent again instead (`wallBudgetSec` its expiry's, null when the bundle cannot be read: held as before), once
   * per cut-off pass (its start in the job id), and only while no other job of the trial is waiting or running; that job
   * voids the live pass as interrupted or replays it again, counted toward AGENT_INTERRUPTED_RERUNS as any cut-off is.
   */
  const holdDead = async (r: RunRow, open: readonly TrialRow[], slug: string, phaseKey: string, sub: string, wallBudgetSec: number | null): Promise<void> => {
    const [table] = rowsOf<{ present: boolean }>(await db.execute(sql`select to_regclass(${JOB_TABLE}) is not null as present`));
    if (table?.present !== true) return;
    for (const t of open) {
      if (t.status === 'held') continue;
      const [job] = rowsOf<{ id: string; state: string; output: unknown; data: unknown }>(
        await db.execute(
          sql`select j.id::text as id, j.state, j.output, j.data from ${sql.raw(JOB_TABLE)} j
            where j.name = ${'grade-trial'} and j.data->>'run_id' = ${r.id} and j.data->>'trial_index' = ${String(t.trialIndex)}
            order by j.created_on desc, j.id desc limit 1`,
        ),
      );
      if (job === undefined || (job.state !== 'failed' && job.state !== 'cancelled')) continue;
      const cutAt = t.status === 'live_running' ? t.liveStartedAt : t.status === 'replaying' && t.replayFinishedAt === null ? t.replayStartedAt : null;
      if (job.state === 'failed' && cutAt !== null && wallBudgetSec !== null) {
        const [busy] = rowsOf<{ n: number | string }>(
          await db.execute(
            sql`select count(*) as n from ${sql.raw(JOB_TABLE)} j
              where j.name = ${'grade-trial'} and j.data->>'run_id' = ${r.id} and j.data->>'trial_index' = ${String(t.trialIndex)} and j.state in ('created', 'retry', 'active')`,
          ),
        );
        if (Number(busy?.n ?? 0) === 0) {
          const named = (job.data as { first_pass?: unknown } | null)?.first_pass;
          const firstPass = typeof named === 'number' && Number.isSafeInteger(named) && named >= 1 && named <= t.attempt ? named : t.attempt;
          const id = gradeTrialJobId(t.runId, t.trialIndex, t.attempt, `cut-off:${cutAt.getTime()}`);
          const sent = await deps.jobs.send(
            'grade-trial',
            // As its run is (the header's `layout`): a flagged run's job says `one_pod`.
            trialPayloadOf({ run_id: t.runId, trial_index: t.trialIndex, pass: t.attempt, first_pass: firstPass }, r.flags.includes(ONE_POD_FLAG) ? 'pod' : 'split'),
            // A grader that died is the platform's fault: the trial keeps its place in the queue (record.ts `queue tags`).
            { id, priority: gradeTrialPriority((await faultTrialQueueTag(db, t, wallBudgetSec)) ?? 0), expireInSeconds: agentTrialExpirySeconds(wallBudgetSec, slug) },
          );
          if (sent !== null) {
            const doing = t.status === 'live_running' ? `live pass ${t.attempt}` : `the replay of live pass ${t.attempt}`;
            log(`[grade] trial ${t.trialIndex} of run ${r.id}: its job ${job.id} died for good outside its handler with ${doing} cut off (its grader died): sent again as job ${sent}, which takes it on as any cut-off pass; not held`);
            continue;
          }
          // Sent once already for this very pass, and that job died too before it moved the trial on: held, as below.
        }
      }
      const error = `its job ${job.id} is held ${job.state} by pg-boss (its last attempt expired or was stopped, outside its handler)${jobErrorOf(job.output) === null ? '' : `: ${jobErrorOf(job.output)}`}`;
      const held = await db.transaction(async (tx) => {
        // A trial that never set out (pending at attempt 0) is held at its first pass, which it never started (run_trial_attempt_spent).
        const never: TrialUpdate = t.status === 'pending' && t.attempt === 0 ? { attempt: 1 } : {};
        const moved = await moveTrial(tx, t, { ...(t.status === 'void' ? voidHeld(t) : never), status: 'held', voidReason: DEAD_JOB_HOLD_REASON, error });
        if (moved === null) return null;
        await addRunFlags(tx, t.runId, [TRIAL_HELD_FLAG]);
        return moved;
      });
      if (held !== null) page(trialHeldPage(held, { slug, submissionId: sub, phaseKey }));
    }
  };

  /**
   * The run's trials held for upstream errors (UPSTREAM_ERRORS_VOID_REASON: a series spent in a burst of failing
   * upstream calls, never the entry's fault) re-queued by themselves once TRIAL_SELF_REQUEUE_AFTER_MS has passed since
   * their last pass ended (selfRequeueOf), each once: through requeueHeldTrial, as an admin's re-queue (its queue tag
   * kept: record.ts faultQueueTag), under trial.requeue audit rows of its own as the admin route writes them (subject
   * the run; a `sending` row committed before anything moves, whose id is the re-queue's, then `sent` or `not_sent`),
   * naming the fan-in as their actor (data.actor TRIAL_SELF_REQUEUE_ACTOR, data.automatic true, actor null). One held
   * again after that waits for an admin, paged as any held trial is; one held for any other reason is never re-queued
   * here. A re-queue that ends not_sent (the trial moved on meanwhile, or the queue did not take its job and put it back
   * on hold) is no re-queue: the next wait slot may try again.
   */
  const selfRequeue = async (r: RunRow, open: readonly TrialRow[], who: { slug: string; competitionId: string; phaseId: string; phaseKey: string; submissionId: string }): Promise<void> => {
    for (const t of open) {
      const due = await selfRequeueOf(db, t);
      if (due === null || now().getTime() < due.getTime()) continue;
      const attempt = uuidv7();
      const reason = `${TRIAL_SELF_REQUEUE_AFTER_MS / 60_000} minutes held for upstream errors, which come in bursts: re-queued by itself once (grader/worker.ts TRIAL_SELF_REQUEUE_AFTER_MS)`;
      const record = (stage: 'sending' | 'sent' | 'not_sent', extra: Record<string, unknown> = {}) =>
        recordAudit(db, {
          ...(stage === 'sending' ? { id: attempt } : {}),
          actorUserId: null,
          action: TRIAL_REQUEUE_ACTION,
          subjectType: 'run',
          subjectId: r.id,
          at: now(),
          data: {
            competition: who.slug,
            competition_id: who.competitionId,
            submission_id: who.submissionId,
            phase: who.phaseKey,
            phase_id: who.phaseId,
            run_id: r.id,
            trial_index: t.trialIndex,
            held: { attempt: t.attempt, void_reason: t.voidReason, error: t.error },
            reason,
            attempt,
            stage,
            sent: stage === 'sent',
            automatic: true,
            actor: TRIAL_SELF_REQUEUE_ACTOR,
            ...extra,
          },
        });
      // Recorded before anything moves: one that cannot be written re-queues nothing (the caller logs it; the next slot tries again).
      await record('sending');
      let out: Awaited<ReturnType<typeof requeueHeldTrial>>;
      try {
        out = await requeueHeldTrial({ db, jobs: deps.jobs }, { runId: r.id, trialIndex: t.trialIndex, key: attempt });
      } catch (err) {
        const error = err instanceof Error ? err.message : String(err);
        await record('not_sent', { error }).catch((e: unknown) => console.error(`[grade] the ${TRIAL_REQUEUE_ACTION} row (not_sent) of re-queue ${attempt} of trial ${t.trialIndex} of run ${r.id} could not be written:`, e));
        log(`[grade] trial ${t.trialIndex} of run ${r.id}, held (${t.voidReason}), was not re-queued by itself: ${error}`);
        continue;
      }
      await record('sent', { status: out.status, pass: out.pass, job_id: out.job_id }).catch((e: unknown) =>
        console.error(`[grade] the ${TRIAL_REQUEUE_ACTION} row (sent) of re-queue ${attempt} of trial ${t.trialIndex} of run ${r.id} could not be written; its sending row stands:`, e),
      );
      log(`[grade] trial ${t.trialIndex} of run ${r.id}, held (${t.voidReason}) since live pass ${t.attempt} ended at ${t.liveFinishedAt!.toISOString()}, is re-queued by itself (${TRIAL_REQUEUE_ACTION} ${attempt}): ${out.status}, pass ${out.pass} as job ${out.job_id}; held again, it waits for an admin`);
    }
  };

  /** The fan-in sent again for the end of the next wait slot (every wait landing in one slot is one job): when it looks again. */
  const nextSlot = async (r: RunRow): Promise<Date> => {
    const slot = Math.ceil((now().getTime() + AGENT_AGGREGATE_WAIT_MS) / AGENT_AGGREGATE_WAIT_MS);
    const startAfter = new Date(slot * AGENT_AGGREGATE_WAIT_MS);
    await deps.jobs.send('grade-aggregate', { run_id: r.id }, { id: gradeAggregateJobId(r.id, `wait:${slot}`), startAfter });
    return startAfter;
  };

  /** Look again at the end of the next wait slot: every wait landing in one slot is one job. */
  const wait = async (r: RunRow, open: readonly TrialRow[]): Promise<null> => {
    const startAfter = await nextSlot(r);
    const by = new Map<string, number>();
    for (const t of open) by.set(t.status, (by.get(t.status) ?? 0) + 1);
    log(`[grade] run ${r.id} waits on ${open.length} trials (${[...by].map(([s, n]) => `${n} ${s}`).join(', ')}); it looks again at ${startAfter.toISOString()}`);
    return null;
  };

  /**
   * What a staged final's run waits on with none of its trials open (the header's `staged final`), or null when it is
   * whole: its cut not decided (a first trial that ran out of its wall before it); or a contender (stageOfRun: the
   * house's entry and a baseline whatever they scored) short of its K trials, whose later trials the cut job, or its
   * first trial's own job, is still to make. A cut run is whole with its one trial.
   */
  const stagedWaitsOn = async (sub: typeof submission.$inferSelect, ph: typeof phase.$inferSelect, trials: readonly TrialRow[], staged: StagedFinalT): Promise<string | null> => {
    const { cutExempt, stageOfRun } = await import('../server/grading/final-cut.ts');
    const stage = stageOfRun(ph.cutDecidedAt, trials, cutExempt(sub) ? 'contender' : null);
    if (stage === 'qualifier') return `its final's cut, not decided yet (its first trial ${trials.find((t) => t.trialIndex === 0)?.status ?? 'not made'})`;
    if (stage === 'contender' && trials.length < staged.final_instances) return `a contender's later trials: ${trials.length} of its ${staged.final_instances} made so far`;
    return null;
  };

  /**
   * What a run of a staged final that names earlier cuts waits on with none of its trials open (the header's `staged
   * final`, its stages), or null when it is whole: its fate (stagedFateOf, its points off its cassettes) as the surfaces
   * read it (final-cut.ts stagedRunOf). Whole: cut at some cut, every trial of it ended; or a finalist with all K of its
   * trials done. Otherwise it waits as on an open trial: on a cut not decided yet (a qualifying trial that ran out of its
   * wall before it), on the next stage's trials a run through a cut is still to be given, or on a finalist's last ones.
   */
  const stagesWaitOn = async (sub: typeof submission.$inferSelect, ph: typeof phase.$inferSelect, bundle: CompetitionBundleT, trials: readonly TrialRow[], staged: StagedFinalT): Promise<string | null> => {
    const { stagedRunOf } = await import('../server/grading/final-cut.ts');
    const s = await stagedFateOf(db, blobs, { sub, phaseId: ph.id, bundle }, staged, trials);
    const decided = s.decided.findIndex((d) => d === null);
    const run = stagedRunOf(s.cuts, decided === -1 ? s.cuts.length : decided, trials, s.fate);
    if (run.stage === 'qualifier' && s.fate.fate === 'through') return `the trials of its next stage, through cut ${s.fate.cut} of its final: ${trials.length} of its ${run.owed} made so far`;
    if (run.stage === 'qualifier') return `cut ${run.cutsPassed} of its final, not decided yet (its trials ${trials.map((t) => `${t.trialIndex} ${t.status}`).join(', ')})`;
    if (run.stage === 'contender' && trials.length < staged.final_instances) return `a finalist's later trials: ${trials.length} of its ${staged.final_instances} made so far`;
    return null;
  };

  /**
   * The open trials of a run of a staged final that names earlier cuts the fan-in may hold for a dead job (holdDead):
   * every one but a parked qualifying trial (parkedTrial, under stagedQualifyingTrials) of a run whose fate still waits
   * (stagedFateOf: a cut undecided, or the next stage not all measured), whose last job ended as it parked and which a
   * cut's wake or its run's next trial takes on. A run whose fate is decided has its parked trials woken (the cut job's
   * wake, or its trials' own handler): a dead job there is held as any. A fate that cannot be read holds no parked trial.
   */
  const stagesParked = async (r: RunRow, sub: typeof submission.$inferSelect, ph: typeof phase.$inferSelect, bundle: CompetitionBundleT, staged: StagedFinalT, trials: readonly TrialRow[], open: readonly TrialRow[]): Promise<readonly TrialRow[]> => {
    const under = stagedQualifyingTrials(staged);
    const parked = (t: TrialRow) => t.trialIndex < under && parkedTrial(t);
    if (!open.some(parked)) return open;
    try {
      const { fate } = await stagedFateOf(db, blobs, { sub, phaseId: ph.id, bundle }, staged, trials);
      if (!fateWaits(fate)) return open;
    } catch (err) {
      log(`[grade] run ${r.id}: its staged fate could not be read (${err instanceof Error ? err.message : String(err)}); none of its parked trials is held for a dead job`);
    }
    return open.filter((t) => !parked(t));
  };

  /** A staged final's run that waits on its cut or its later trials, none of its trials open: looked at again next slot. */
  const waitStaged = async (r: RunRow, why: string): Promise<null> => {
    const startAfter = await nextSlot(r);
    log(`[grade] run ${r.id} waits on ${why}; it looks again at ${startAfter.toISOString()}`);
    return null;
  };

  /** A staged final's first trial parked at live_done, scored, waiting on its phase's cut (the header's `staged final`). */
  const parkedFirst = (t: TrialRow): boolean => t.trialIndex === 0 && t.status === 'live_done' && t.score !== null;

  // Its executions: every live pass, and a replay where one ran (a dev trial runs once: the header's `practice once`).
  const counted = (trials: readonly TrialRow[]) => ({
    exec_count: trials.reduce((s, t) => s + t.attempt + (t.replayFinishedAt === null ? 0 : 1), 0),
    wall_ms: trials.reduce((s, t) => s + (DONE_TRIAL_STATUSES.has(t.status) ? (t.wallMs ?? 0) : 0), 0),
  });

  /** Every trial done: the trials manifest, the performance, the score, and the run's verdict. */
  const finish = async (r: RunRow, sub: typeof submission.$inferSelect, bundle: CompetitionBundleT, trials: readonly TrialRow[]): Promise<void> => {
    if (r.seed === null || r.harnessVersion === null || r.scorerVersion === null) throw new PermanentJobError(`run ${r.id} was started without its seed, harness or scorer version`);
    const records: AgentTrialRecordT[] = [];
    const read: SpendTrial[] = [];
    const { cassetteModelCalls, readCassette } = await import('./gateway/cassette.ts');
    const target = bundle.harness.kind === 'agent/v1' && bundle.harness.target !== undefined;
    // A run flagged ONE_POD_FLAG: each trial's record carries the entry lane key its passes were handed (onePodEntryKey of
    // the row's run, as passLanes computed it), so every later replay reads it there. An unflagged run's records have none.
    const onePod = r.flags.includes(ONE_POD_FLAG);
    for (const t of trials) {
      if (!liveRecorded(t)) throw new PermanentJobError(`trial ${t.trialIndex} of run ${r.id} is ${t.status} with its live pass not whole on record`);
      if (target && t.houseCassetteSha256 === null) throw new PermanentJobError(`trial ${t.trialIndex} of run ${r.id} is ${t.status} with no house lane cassette on record, under a harness with a target`);
      const cassette = await readCassette(blobs, t.cassetteSha256!);
      const outputs = TrialOutputs.parse(await blobJson(blobs, t.outputsSha256!, 'state export manifest'));
      const status = t.status as AgentTrialStatusT;
      // The brief its live pass read, named when the row recorded it (a row from before that names none), and a target's
      // house lane cassette (what an L2 regrade replays beside its own).
      records.push({
        index: t.trialIndex,
        instance_sha256: t.instanceSha256,
        status,
        cassette_sha256: t.cassetteSha256!,
        state_sha256: t.stateSha256!,
        env_log_sha256: t.envLogSha256!,
        outputs,
        ...(t.promptSha256 === null ? {} : { prompt_sha256: t.promptSha256 }),
        ...(t.houseCassetteSha256 === null ? {} : { house_cassette_sha256: t.houseCassetteSha256 }),
        ...(onePod ? { entry_key: await onePodEntryKey(deps.failKeySecret, t) } : {}),
      });
      const house = t.houseCassetteSha256;
      read.push({ result: agentTrialResultOf(t, cassette, cassetteModelCalls(cassette), status), cassettes: async () => (house === null ? [cassette] : [cassette, await readCassette(blobs, house)]) });
    }
    // Trials priced on two tables that bill every call they record alike, stated on the first trial's (spend-revision.ts).
    const results = await spendOnFirstTrialRevision(r.id, read, log);
    const manifest = trialsManifest(records);
    // The harness's waivers of the floor (a target, model_calls: optional), read off it as a regrade reads them (agent-score.ts agentHarnessFloorFacts).
    const entry = agentEntryFactsOf(sub, bundle.harness);
    // An entrant's trial with no model call scores 0, its store unscored (agent-score.ts agentTrialSilent). aggregateTrials
    // reads only the stored records above, so what it refuses (trials still on two pricing tables, a scorer's points out
    // of range) it refuses on every attempt: the run fails at this attempt, the platform's fault paged, never retried.
    let performance: ReturnType<typeof aggregateTrials>;
    try {
      performance = aggregateTrials(results, bundle.leaderboard, entry);
    } catch (err) {
      throw new PermanentJobError(err instanceof Error ? err.message : String(err), { cause: err });
    }
    // An entrant's run none of whose trials made a model call is refused whole (agent-score.ts agentModelCallRefusal), the
    // reason naming the missing key when its passes ran on no provider key (the header's `entry lane`).
    const providerIds = await providerSecretIdsOf(db, trials.flatMap((t) => t.entrySecretIds ?? []));
    const refusal = agentModelCallRefusal(results, entry, { keyless: keylessEntry(sub, trials, providerIds) });
    if (refusal !== null) {
      await finishRun(db, blobs, r.id, { status: 'failed', action_log_json: null, action_log_sha256: null, result: null, result_sha256: null, ...counted(trials), error: refusal, finished_at: now() });
      log(`[grade] entry ${sub.id}'s agent/v1 run ${r.id} is refused: ${refusal}`);
      return;
    }
    // The run's checks trace beside the performance (agent-score.ts agentChecksBreakdown; the header's `checks`): rows that
    // make none are logged with why, the run then storing none, and the score is the same as without them.
    const checks = agentChecksBreakdown(results, entry);
    const trace = checks.trace === null ? null : encodeTrace(checks.trace);
    if (checks.reason !== null) log(`[grade] entry ${sub.id}'s agent/v1 run ${r.id} stores ${checks.reason}`);
    const deterministic = agentDeterministic(performance);
    const { cost, pricingRev } = await entryCostFor({ db, blobs }, { sub, bundle, fresh: true });
    const authorship = await loadAuthorship(sub.id, pricingRev);
    const result = buildScore(
      {
        harness: { kind: 'agent/v1', version: r.harnessVersion },
        image_digest: r.imageDigest,
        dataset_sha256: r.datasetSha256,
        seed: r.seed,
        deterministic,
        execution_flags: [],
        house: standingsHouse(sub),
        baseline: sub.baseline,
      },
      { action_log_sha256: manifest.sha256, performance, performance_flags: [], cost, authorship },
      eligibilityRulesOf(bundle),
      r.scorerVersion,
    );
    const odd = trials.filter((t) => t.status === 'nondeterministic');
    // The trials the floor scored 0, named for whoever reads the run (agent-score.ts agentSilentNote).
    const silent = agentSilentNote(results, entry);
    const notes = [deterministic ? null : `${odd.length} of the run's ${trials.length} trials replayed otherwise than their live pass: ${odd.map((t) => `trial ${t.trialIndex} (${t.error ?? 'no detail'})`).join('; ')}`, silent].filter((n) => n !== null);
    await finishRun(db, blobs, r.id, {
      status: deterministic ? 'finished' : 'nondeterministic',
      action_log_json: manifest.json,
      action_log_sha256: manifest.sha256,
      result,
      result_sha256: scoreDigest(result).sha256,
      // Beside the result, never in it: buildScore never sees the trace, so result_sha256 is what it is without one.
      trace_json: trace?.json ?? null,
      trace_sha256: trace?.sha256 ?? null,
      ...counted(trials),
      error: notes.length === 0 ? null : notes.join('; '),
      finished_at: now(),
    });
    if (silent !== null) log(`[grade] entry ${sub.id}'s agent/v1 run ${r.id} is scored with silent trials: ${silent}`);
  };

  return async (data, ctx) => {
    const [r] = await db.select().from(run).where(eq(run.id, data.run_id));
    if (r === undefined) {
      log(`[grade] ${ctx.id}: run ${data.run_id} does not exist: nothing to aggregate`);
      return null;
    }
    const ph = await one(db.select().from(phase).where(eq(phase.id, r.phaseId)), `phase ${r.phaseId}`);
    const out: AggregatedRun = { run_id: r.id, submission_id: r.submissionId, phase_id: r.phaseId, phase: ph.key };
    const finalGrade = r.kind === 'grade' && ph.key === 'final';
    // Finished by an earlier fan-in: published again (publish is idempotent), in case that one's send was lost.
    if (r.status !== 'running') return r.kind === 'grade' && PUBLISHED_RUN_STATUSES.has(r.status) ? out : null;
    const sub = await one(db.select().from(submission).where(eq(submission.id, r.submissionId)), `submission ${r.submissionId}`);
    const [comp] = await db.select().from(competition).where(eq(competition.id, ph.competitionId));
    const slug = comp?.slug ?? `competition ${ph.competitionId}`;
    const trials = await loadTrials(db, r.id);
    if (sub.status === 'cancelled') {
      await finishRun(db, blobs, r.id, { status: 'cancelled', action_log_json: null, action_log_sha256: null, result: null, result_sha256: null, ...counted(trials), error: 'the entry was cancelled while its trials ran', finished_at: now() });
      if (finalGrade) await finalGradeLanded(db, ph.competitionId, log);
      return out;
    }
    const open = trials.filter((t) => !DONE_TRIAL_STATUSES.has(t.status));
    const bundle = comp?.bundle == null ? null : CompetitionBundle.safeParse(comp.bundle);
    // A staged final's run (the header's `staged final`); null for every other run, which waits and finishes as before.
    const valid = bundle?.success === true ? bundle.data : null;
    const staged = valid === null ? null : stagedFinalRun(valid, ph.key);
    if (trials.length > 0 && open.length > 0) {
      // A first trial parked on an undecided cut is no dead job's: its last job ended as it parked, and the cut wakes it.
      // On a final that names earlier cuts, every parked qualifying trial of a run whose fate is undecided (stagesParked).
      const live = staged === null ? open : staged.cuts === undefined ? (ph.cutDecidedAt === null ? open.filter((t) => !parkedFirst(t)) : open) : await stagesParked(r, sub, ph, valid!, staged, trials, open);
      await holdDead(r, live, slug, ph.key, sub.id, bundle?.success === true ? bundle.data.limits.wall_budget_sec : null).catch((err: unknown) => console.error(`[grade] ${ctx.id}: run ${r.id}'s dead trial jobs could not be read; its next wait looks again:`, err));
      await selfRequeue(r, open, { slug, competitionId: ph.competitionId, phaseId: ph.id, phaseKey: ph.key, submissionId: sub.id }).catch((err: unknown) =>
        console.error(`[grade] ${ctx.id}: run ${r.id}'s trials held for upstream errors could not be re-queued by themselves; its next wait looks again:`, err),
      );
      return wait(r, open);
    }
    if (staged !== null && trials.length > 0) {
      const why = staged.cuts === undefined ? await stagedWaitsOn(sub, ph, trials, staged) : await stagesWaitOn(sub, ph, valid!, trials, staged);
      if (why !== null) return waitStaged(r, why);
    }
    try {
      if (trials.length === 0) throw new PermanentJobError(`run ${r.id} has no trials`);
      const parsed = comp?.bundle == null ? null : CompetitionBundle.safeParse(comp.bundle);
      if (parsed === null || !parsed.success) throw new PermanentJobError(`${slug} has no bundle that validates`);
      if (parsed.data.harness.kind !== 'agent/v1') throw new PermanentJobError(`${slug} is a ${parsed.data.harness.kind} competition, not agent/v1`);
      await finish(r, sub, parsed.data, trials);
      // A final grade moves the live board's grades count (finalGradeLanded): the page reads /live again.
      if (finalGrade) await finalGradeLanded(db, ph.competitionId, log);
      return out;
    } catch (err) {
      if (!(err instanceof PermanentJobError) && !isLastAttempt(ctx)) throw err;
      const error = err instanceof Error ? err.message : String(err);
      const failed = await finishRun(db, blobs, r.id, { status: 'failed', action_log_json: null, action_log_sha256: null, result: null, result_sha256: null, ...counted(trials), error: `the fan-in: ${error}`, finished_at: now() });
      if (failed) {
        page(
          `[grade] ALERT: ${slug}: entry ${r.submissionId}'s agent/v1 run ${r.id} on the ${ph.key} phase could not be aggregated once its ${trials.length} trials were done: ${error}. ` +
            `The run is failed, and its publish job marks the entry failed with it; every trial's records (cassettes, state exports, scores) stay on its run_trial rows. Fix: mend what failed, then grade the entry again`,
        );
        if (finalGrade) await finalGradeLanded(db, ph.competitionId, log);
      }
      return out;
    }
  };
}

// ---------------------------------------------------------------- the hindsight audit

/** The HKDF label of an audit's master seed (hindsightSeedMaster). */
export const HINDSIGHT_SEED_LABEL = 'agent-fun/hindsight-audit/v1 master';

/**
 * The prefix of a hindsight audit's scratch under the work root: `hindsight-<owner>-XXXXXX`, its owner its job's
 * (regradeOwner of the job's id; regrade.ts ownedScratch), which the job's next attempt removes should its grader die
 * (regrade.ts reapScratch), and the workers' start (server/pipeline/index.ts sweepDeadWork) only once all three hold
 * (removeIfDead): no active job on the start's database holds its owner, no one has touched it for six hours (its
 * newest change, its own or a direct entry's, older than grader/sandbox/network.ts STALE_AFTER_MS), and no live process
 * holds it open or as its cwd (processesHolding); one younger, held or not to be asked about is kept and logged.
 */
export const HINDSIGHT_SCRATCH_PREFIX = 'hindsight-';

/**
 * The master secret an audit's surrogate seeds derive from (grader/hindsight-audit.ts auditSeeds):
 * hex of HKDF-SHA256(ikm = the fail-key secret, salt = empty, info = label 0x00 kind 0x00 entry 0x00
 * run 0x00 appeal attempt), 32 bytes. Fixed for one entry, run and kind (a retried job rebuilds the
 * same surrogates), another for the appeal; without the secret nothing predicts it.
 */
export function hindsightSeedMaster(secret: string, kind: HindsightAuditKind, submissionId: string, runId: string, attempt: string | null): string {
  if (secret.length === 0) throw new RangeError('the fail-key secret is empty');
  return Buffer.from(hkdfSync('sha256', secret, Buffer.alloc(0), `${HINDSIGHT_SEED_LABEL}\0${kind}\0${submissionId}\0${runId}\0${attempt ?? ''}`, 32)).toString('hex');
}

export interface HindsightAuditDeps {
  db: Db;
  blobs: BlobStore;
  sandbox: Sandbox;
  /** Existing directory for each audit's scratch directory (the snapshot and the surrogates). */
  workRoot: string;
  /** Where the sweep sends each entry's job. */
  jobs: Pick<JobQueue, 'send'>;
  /**
   * The server secret (config.betterAuthSecret): a server-secret/v1 run's fail key when it kept none, and the audit
   * seeds on either scheme (hindsightSeedMaster; default as GradeWorkerDeps.failKeySecret).
   */
  failKeySecret?: string;
  /** A phase-secret+beacon/v1 run's fail key when it kept none (phaseFailKey): the competition's directory, holding its sealed-window.yaml (default competitions/<slug>, as GradeWorkerDeps.competitionDir). */
  competitionDir?(slug: string): string;
  /** That key's draw record is <sealedDir>/<slug>/draw.json (default as GradeWorkerDeps.sealedDir). */
  sealedDir?: string;
  /** The drand chain that draw's beacon may name besides quicknet (default as GradeWorkerDeps.drandChain). */
  drandChain?: DrandChain;
  /** A relative dataset path resolves against this (default the project root, as the grader's dataset loader). */
  datasetRoot?: string;
  /** The check's parameters (default CHEAT_CHECK; a test hands in a copy). */
  check?: CheatCheck;
  /** The audit (default grader/hindsight-audit.ts auditEntry). */
  audit?: (o: AuditOptions) => Promise<HindsightAuditRecordT>;
  /** Surrogate runs at once within one audit (default 1). */
  concurrency?: number;
  now?: () => Date;
  log?: (line: string) => void;
  /** Where an entry job that died for good is paged, one line each (the header's `dead`), and a fail key that cannot be derived (the header's `fail key`; default console.error, as the chain sync pages). */
  page?: (line: string) => void;
  /** The host's scrape lease, which an entry's audit runs nothing beside under its `host` scope (the header's `one entry`; default scrapeLeaseDirFromEnv() and scrapeLeaseScopeFromEnv(), as GradeWorkerDeps.scrape's). */
  scrape?: Pick<ScrapeWorkerDeps, 'leaseDir' | 'leaseScope'>;
  /**
   * This server's cluster (config.solanaCluster), on which the sweep and a dead job's page read the audit targets'
   * standings escrowed or not (server/routes/admin/hindsight.ts hindsightTargets, prizesEscrowed: with no escrow an
   * unsigned entry is paid, so audited); absent, an escrow of the competition on any cluster.
   */
  cluster?: SolanaCluster;
  /**
   * How an entry's audit re-opens the env-lane entry secrets its run recorded (the header's `one entry`): the grader's
   * seal settings, whose private keys open them (default the environment's, as GradeWorkerDeps.entrySecrets; read only
   * for a run that recorded some).
   */
  entrySecrets?: Pick<AgentEntrySecretDeps, 'seal'>;
  /**
   * The sandbox layout's inputs (the header's `layout`): an audit re-runs its run's entry on the run's own layout, so only
   * `host` is read here (a run flagged ONE_POD_FLAG audited on the one-pod view; absent or null, refused as the
   * platform's fault).
   */
  onePod?: OnePodDeps;
}

/** An entry job that died for good, paged (subject the submission; once per job: the header's `dead`). */
export const HINDSIGHT_AUDIT_DEAD_ACTION = 'hindsight.audit_dead' satisfies AuditAction;

/** What one hindsight-audit job did (the handler logs it; tests read it). */
export type HindsightAuditOutcome =
  | { kind: 'skipped'; why: string }
  | { kind: 'grading'; awaiting: string[] }
  | {
      kind: 'swept';
      targets: number;
      sent: { submission_id: string; kind: HindsightAuditKind; job_id: string; queued: boolean }[];
      /** The dead audit jobs this sweep paged (the header's `dead`): none it or a job's handler paged before. */
      paged: { submission_id: string; job_id: string }[];
    }
  | { kind: 'recorded'; submission_id: string; audit: HindsightAuditKind; record_sha256: string; flagged: boolean; check: 'pass' | 'fail' | 'skip' | null; already: boolean }
  /** A scrape heat held the host (scrapeHostHeldBy, `held_by` its words): nothing run, the job sent again for the next recheck slot (the header's `one entry`). */
  | { kind: 'waiting'; submission_id: string; audit: HindsightAuditKind; until: Date; job_id: string | null; held_by: string };

/**
 * A hindsight-audit job's context as the runner reads it: its id, its attempt and retry limit (a job dies for good on
 * its last: isLastAttempt; without them no attempt is the last), and the attempt's signal, which stops an entry's audit
 * once pg-boss gives the attempt up (the header's `one entry`; without one the audit is never stopped).
 */
export type HindsightJobContext = Pick<JobContext, 'id'> & Partial<Pick<JobContext, 'retryCount' | 'retryLimit' | 'signal'>>;

/** An entry job that died for good, as its page names it (the header's `dead`). */
interface DeadEntryJob {
  comp: { id: string; slug: string };
  final: { id: string; endsAt: Date | null };
  submissionId: string;
  runId: string;
  kind: HindsightAuditKind;
  /** The audit target's rank on the final phase's board; null for an appeal. */
  rank: number | null;
  /** The appeal's attempt; null for an audit. */
  attempt: string | null;
  jobId: string;
  /** How it died, in the page's words ("was refused for good ...", "failed its last attempt (3 of 3)", "is held failed by pg-boss since ..."). */
  how: string;
  error: string | null;
  /** Who found it dead: the job's own handler, or a sweep. */
  found: 'handler' | 'sweep';
}

/** The page of a dead entry job at `at` (the header's `dead`): what died, why finalize waits on it, and the verdict that lets finalize through. */
function deadJobPage(d: DeadEntryJob, at: Date): string {
  const route = `POST /api/admin/submissions/${d.submissionId}/hindsight ({"verdict": "clear" or "disqualify", "reason": "..."})`;
  const ends = d.final.endsAt;
  const ended = ends !== null && ends.getTime() <= at.getTime();
  const died = `job ${d.jobId} ${d.how}${d.error === null ? '' : `: ${d.error}`}`;
  // A verdict past a dead job (this one) stays open past ends_at, until finalize (admin/hindsight.ts): said when ends_at has passed.
  const still = (what: string) => (ended ? `. The final phase ended at ${ends.toISOString()}, and that route still takes this verdict (${what}) until the final phase is finalized` : '');
  if (d.kind === 'audit') {
    return (
      `[hindsight] ALERT: ${d.comp.slug}: the hindsight audit of entry ${d.submissionId} (run ${d.runId}, ranked ${d.rank} on the final phase) died for good, ${died}. ` +
      `No audit record will come, so the entry carries no hindsight_clean, and finalize of ${d.comp.slug}'s final phase is refused until it does. ` +
      `Fix: give a verdict at ${route} before the final phase is finalized; it is given with no audit record, and finalize waits for the entry no more${still('with no audit record')}`
    );
  }
  return (
    `[hindsight] ALERT: ${d.comp.slug}: the re-run of entry ${d.submissionId}'s appeal (attempt ${d.attempt}, run ${d.runId}) died for good, ${died}. ` +
    `The appeal waits for a re-run that will not record, so finalize of ${d.comp.slug}'s final phase is refused while it waits. ` +
    `Fix: decide the appeal without it, with a verdict at ${route} before the final phase is finalized; a refused finalize sends the re-run again, should its numbers be wanted first${still('the appeal decided without its re-run')}`
  );
}

/** The hindsight-audit job handler (see the header). */
export function createHindsightAuditHandler(deps: HindsightAuditDeps): JobHandler<'hindsight-audit'> {
  const runner = createHindsightAuditRunner(deps);
  return async (data, ctx) => {
    await runner(data, ctx);
  };
}

/** The handler's body, answering what it did (and paging an entry job that dies for good: the header's `dead`). */
export function createHindsightAuditRunner(deps: HindsightAuditDeps): (data: JobPayload<'hindsight-audit'>, ctx: HindsightJobContext) => Promise<HindsightAuditOutcome> {
  const { db, blobs } = deps;
  const check = deps.check ?? CHEAT_CHECK;
  const audit = deps.audit ?? auditEntry;
  const now = deps.now ?? (() => new Date());
  const log = deps.log ?? ((line: string) => console.log(line));
  const page = deps.page ?? ((line: string) => console.error(line));
  const failKeyPaged = failKeyPager({ page, log, now }, '[hindsight]');
  const sealOf = entrySecretSealOf(deps);
  const root = deps.datasetRoot ?? PROJECT_ROOT;
  /** The scan's index per (source, background) window pair, the two latest kept. */
  const indexes = new Map<string, Promise<HindsightIndex>>();
  const indexOf = (source: DatasetRow, background: DatasetRow | null): Promise<HindsightIndex> => {
    const key = `${source.sha256}\0${background?.sha256 ?? ''}`;
    const hit = indexes.get(key);
    if (hit !== undefined) return hit;
    const building = (async () => {
      const src = loadHindsightSource(resolve(root, source.path), background === null ? [] : [resolve(root, background.path)]);
      return buildHindsightIndex(src, check);
    })();
    indexes.set(key, building);
    building.catch(() => {
      if (indexes.get(key) === building) indexes.delete(key);
    });
    while (indexes.size > 2) indexes.delete(indexes.keys().next().value!);
    return building;
  };
  // The rules' module is loaded on the first job: it reaches the leaderboard's code, which nothing else here needs.
  const rules = () => import('../server/routes/admin/hindsight.ts');

  const sweep = async (phaseId: string, ctx: Pick<JobContext, 'id'>): Promise<HindsightAuditOutcome> => {
    const hs = await rules();
    const [ph] = await db.select().from(phase).where(eq(phase.id, phaseId));
    if (ph === undefined) return { kind: 'skipped', why: `phase ${phaseId} does not exist` };
    const [comp] = await db.select().from(competition).where(eq(competition.id, ph.competitionId));
    const bundle = comp?.bundle == null ? null : CompetitionBundle.safeParse(comp.bundle);
    if (comp === undefined || bundle === null || !bundle.success || bundle.data.harness.kind !== 'pumpfun-replay/v2') return { kind: 'skipped', why: `phase ${phaseId} is not a replay competition's` };
    if ((await hs.drawnFinal(db, comp, ph)) === null) return { kind: 'skipped', why: `the ${ph.key} phase of ${comp.slug} does not score a drawn sealed window` };
    const t = await hs.hindsightTargets(db, comp, bundle.data, ph, check, deps.cluster);
    if (t.awaiting.length > 0) {
      log(`[hindsight] ${ctx.id}: ${comp.slug}'s final phase is still grading (${t.awaiting.length} entries): no audit yet`);
      return { kind: 'grading', awaiting: t.awaiting };
    }
    const at = now();
    const sent: Extract<HindsightAuditOutcome, { kind: 'swept' }>['sent'] = [];
    for (const target of t.unchecked) {
      const id = hindsightAuditJobId(target.submission_id, target.run_id, 'audit', at);
      const queued = await deps.jobs.send('hindsight-audit', { submission_id: target.submission_id, run_id: target.run_id, kind: 'audit' }, { id });
      sent.push({ submission_id: target.submission_id, kind: 'audit', job_id: id, queued: queued !== null });
    }
    for (const target of t.targets) {
      const h = await hs.hindsightHistoryOf(db, target.submission_id);
      for (const a of h.appeals) {
        if (h.records.some((r) => r.kind === 'appeal' && r.attempt === a.attempt)) continue;
        const id = hindsightAuditJobId(target.submission_id, a.run_id, 'appeal', at, a.attempt);
        const queued = await deps.jobs.send('hindsight-audit', { submission_id: target.submission_id, run_id: a.run_id, kind: 'appeal' }, { id });
        sent.push({ submission_id: target.submission_id, kind: 'appeal', job_id: id, queued: queued !== null });
      }
    }
    // After the sends: a target the day's send could not queue again (its id held by the dead job)
    // still has the dead job as its latest, which is what lets a verdict past it (deadAuditOf).
    const paged: { submission_id: string; job_id: string }[] = [];
    try {
      for (const target of t.unchecked) {
        const job = await hs.latestAuditJobOf(db, target.submission_id, target.run_id);
        if (job === null || job.state !== 'failed') continue;
        const dead: DeadEntryJob = {
          comp,
          final: ph,
          submissionId: target.submission_id,
          runId: target.run_id,
          kind: 'audit',
          rank: target.rank,
          attempt: null,
          jobId: job.id,
          how: `is held failed by pg-boss since ${(job.completed_on ?? job.created_on).toISOString()} (its retries spent, or refused for good)`,
          error: job.error,
          found: 'sweep',
        };
        if (await pageDead(dead)) paged.push({ submission_id: target.submission_id, job_id: job.id });
      }
      // And every appeal still waiting whose latest re-run job died outside its handler (an appeal job names no
      // attempt: the run's latest appeal job is the latest filing's, or a refused finalize's resend of it).
      for (const a of t.appeals) {
        const job = await hs.latestAuditJobOf(db, a.submission_id, a.run_id, 'appeal');
        if (job === null || job.state !== 'failed') continue;
        const dead: DeadEntryJob = {
          comp,
          final: ph,
          submissionId: a.submission_id,
          runId: a.run_id,
          kind: 'appeal',
          rank: null,
          attempt: a.attempt,
          jobId: job.id,
          how: `is held failed by pg-boss since ${(job.completed_on ?? job.created_on).toISOString()} (its retries spent, or refused for good)`,
          error: job.error,
          found: 'sweep',
        };
        if (await pageDead(dead)) paged.push({ submission_id: a.submission_id, job_id: job.id });
      }
    } catch (err) {
      log(`[hindsight] ${ctx.id}: ${comp.slug}'s dead audit jobs could not be read to page them: ${err instanceof Error ? err.message : String(err)}`);
      console.error(`[hindsight] ${ctx.id}: ${comp.slug}'s dead audit jobs could not be read to page them; the next sweep looks again:`, err);
    }
    log(`[hindsight] ${ctx.id}: ${comp.slug}'s final phase: ${t.targets.length} audit targets, ${t.unchecked.length} unchecked, ${t.appeals.length} appeals waiting; ${sent.length} jobs sent${paged.length === 0 ? '' : `; ${paged.length} dead audit or appeal jobs paged`}`);
    return { kind: 'swept', targets: t.targets.length, sent, paged };
  };

  const auditOne = async (data: { submission_id: string; run_id: string; kind: HindsightAuditKind }, ctx: HindsightJobContext): Promise<HindsightAuditOutcome> => {
    // The job's owner, the same on each of its attempts: before anything else, what an attempt of it that died left
    // goes (the header's `one entry`).
    const owner = regradeOwner(ctx.id);
    const reaped = scratchReapLine(
      `the hindsight ${data.kind} of submission ${data.submission_id} (run ${data.run_id}, job ${ctx.id})`,
      `attempt ${(ctx.retryCount ?? 0) + 1}`,
      await reapScratch(deps.sandbox, deps.workRoot, HINDSIGHT_SCRATCH_PREFIX, owner),
      'hindsight',
    );
    if (reaped !== null) log(reaped);
    const hs = await rules();
    const sub = await one(db.select().from(submission).where(eq(submission.id, data.submission_id)), `submission ${data.submission_id}`);
    const r = await one(db.select().from(run).where(eq(run.id, data.run_id)), `run ${data.run_id}`);
    if (r.submissionId !== sub.id || r.kind !== 'grade') throw new PermanentJobError(`run ${r.id} is not a grade run of submission ${sub.id}`);
    const ph = await one(db.select().from(phase).where(eq(phase.id, r.phaseId)), `phase ${r.phaseId}`);
    const comp = await one(db.select().from(competition).where(eq(competition.id, ph.competitionId)), `competition ${ph.competitionId}`);
    const parsed = comp.bundle === null ? null : CompetitionBundle.safeParse(comp.bundle);
    if (parsed === null || !parsed.success) throw new PermanentJobError(`competition ${comp.slug} has no bundle that validates`);
    const bundle = parsed.data;
    if (bundle.harness.kind !== 'pumpfun-replay/v2') throw new PermanentJobError(`${comp.slug} is not a replay competition: the hindsight check re-runs a replay entry`);
    const drawn = await hs.drawnFinal(db, comp, ph);
    if (drawn === null) throw new PermanentJobError(`run ${r.id} is on the ${ph.key} phase of ${comp.slug}, which does not score a drawn sealed window`);
    const score = r.status === 'finished' ? Score.safeParse(r.result) : null;
    const net = score?.success ? hs.netPnlOf(score.data) : null;
    if (net === null) throw new PermanentJobError(`run ${r.id} is ${r.status} with no replay score: only a finished run is audited`);
    if (r.seed === null) throw new PermanentJobError(`run ${r.id} recorded no seed`);

    const history = await hs.hindsightHistoryOf(db, sub.id);
    let attempt: string | null = null;
    if (data.kind === 'audit') {
      if (history.records.some((x) => x.kind === 'audit' && x.run_id === r.id) && hs.hindsightCheckOf(sub.checks) !== null) {
        return { kind: 'skipped', why: `run ${r.id} of submission ${sub.id} is audited already` };
      }
    } else {
      const open = history.appeals.find((a) => a.run_id === r.id && !history.records.some((x) => x.kind === 'appeal' && x.attempt === a.attempt));
      if (open === undefined) return { kind: 'skipped', why: `submission ${sub.id} has no appeal awaiting its re-run` };
      attempt = open.attempt;
    }

    // While a scrape heat holds this host under the `host` lease scope, the audit runs nothing beside it: handed on to the
    // next recheck slot (the header's `one entry`; under `egress` scrapeHostHeldBy is null).
    const heldBy = await scrapeHostHeldBy(deps);
    if (heldBy !== null) {
      const slot = scrapeHostRecheckSlot(now().getTime());
      const until = new Date(slot * SCRAPE_HOST_RECHECK_MS);
      const jobId = await deps.jobs.send('hindsight-audit', data, { id: hindsightAuditWaitJobId(sub.id, r.id, data.kind, slot), startAfter: until });
      log(`[hindsight] ${ctx.id}: the ${data.kind} of submission ${sub.id} (run ${r.id}) waits for ${until.toISOString()}: ${heldBy}, and nothing else grades here while a heat runs`);
      return { kind: 'waiting', submission_id: sub.id, audit: data.kind, until, job_id: jobId, held_by: heldBy };
    }

    const masked = await one(db.select().from(dataset).where(eq(dataset.id, ph.datasetId!)), `dataset ${ph.datasetId}`);
    if (r.datasetSha256 !== null && r.datasetSha256 !== masked.sha256) throw new PermanentJobError(`run ${r.id} was graded on dataset ${r.datasetSha256}, not the final phase's ${masked.sha256}`);
    const source = await one(db.select().from(dataset).where(eq(dataset.id, drawn.source_dataset_id)), `dataset ${drawn.source_dataset_id} (the drawn window's source)`);
    const [dev] = await db.select().from(phase).where(and(eq(phase.competitionId, comp.id), eq(phase.key, 'dev')));
    const background = dev?.datasetId == null ? null : ((await db.select().from(dataset).where(eq(dataset.id, dev.datasetId)))[0] ?? null);
    if (sub.snapshotSha256 === null) throw new PermanentJobError(`submission ${sub.id} has no snapshot`);
    const index = await readSnapshotIndex(blobs, sub.snapshotSha256);
    const picked = entryRuntime(index, bundle.harness.runtimes);
    if ('error' in picked) throw new PermanentJobError(`submission ${sub.id}: ${picked.error}`);
    // The env-lane entry secrets the run ran the entry with, re-opened as an L2 re-opens them (the header's `entry
    // secrets`): every surrogate run gets them, or none runs. One erased since cannot run it as it was graded.
    const recorded = await recordedEnvSecrets(db, sealOf, { userId: sub.userId, competitionId: comp.id }, r.entrySecretIds);
    if (recorded.erased !== null) {
      throw new PermanentJobError(
        `the hindsight ${data.kind} of submission ${sub.id}: run ${r.id} ran the entry with an env-lane entry secret that is erased since (replaced, deleted or purged): ${recorded.erased}, so no surrogate can run it as it was graded`,
      );
    }
    if (recorded.kind === 'unopened') {
      throw new Error(`the hindsight ${data.kind} of submission ${sub.id}: the env-lane entry secrets run ${r.id} ran the entry with cannot be opened here, so no surrogate runs it without them (the job tries again): ${recorded.why}`);
    }
    const entrySecrets = recorded.secrets.ids.length === 0 ? {} : { secrets: recorded.secrets.env };
    const secretForms = entrySecretForms(recorded.secrets.env);
    // The run's own layout, by its flag (the header's `layout`): every surrogate runs as the graded run ran, on the
    // one-pod view for a flagged run; a process that cannot host it refuses the audit as the platform's fault.
    const sandbox = r.flags.includes(ONE_POD_FLAG) ? onePodHostOf(deps.onePod, `${comp.slug}: the hindsight ${data.kind} of submission ${sub.id} (run ${r.id})`).view() : deps.sandbox;
    const secret = deps.failKeySecret ?? (await defaultFailKeySecret());
    // The run's own key; else derived again as grading derives it, by the phase's scheme (the header's `fail key`).
    const seed = r.seed;
    const failKey =
      r.failKey ??
      (await failKeyPaged(`${comp.slug}: the hindsight ${data.kind} of submission ${sub.id} (run ${r.id})`, () =>
        phaseFailKey({
          phase: ph,
          slug: comp.slug,
          seed,
          datasetSha256: masked.sha256,
          compDir: competitionDirOf(deps, comp.slug, bundle.harness),
          sealedDir: deps.sealedDir ?? sealedDirFromEnv(),
          chain: instanceChainOptions(deps.drandChain),
          serverSecret: () => secret,
        }),
      ));
    // The entrant's own wallets, which the scan never counts as hits: its entry wallets (an agent wallet signs its entries too) and its payout wallet.
    const wallets = await entryWallets(db, sub.userId);
    if (sub.payoutWallet !== null && !wallets.includes(sub.payoutWallet)) wallets.push(sub.payoutWallet);
    const scanIndex = await indexOf(source, background);

    // The attempt's signal stops the audit once pg-boss gives the attempt up (the header's `one entry`): given up
    // already, nothing is materialized or run.
    const signal = ctx.signal;
    signal?.throwIfAborted();
    const dir = await ownedScratch(deps.workRoot, HINDSIGHT_SCRATCH_PREFIX, owner);
    const botDir = join(dir, 'bot');
    // The audit's scratch, removed once it ran, released from the sandbox's daemon once its record is kept, or it threw
    // (grade.ts releaseScratch, its header's Releasing): a release never stands between the audit and its record, where
    // an attempt given up meanwhile would record nothing.
    const removed: string[] = [];
    try {
      let record: HindsightAuditRecordT;
      try {
        await materializeSnapshot(index, blobs, botDir);
        record = await audit({
          // Bound to the signal (grade.ts stoppableSandbox): its abort kills the replay running, and no later one starts.
          sandbox: stoppableSandbox(sandbox, signal),
          runtime: picked.runtime,
          botDir,
          harness: bundle.harness,
          limits: bundle.limits,
          real: { dataset: resolve(root, masked.path), dataset_sha256: masked.sha256, seed: r.seed, failKey, net_pnl_lamports: net },
          source: scanIndex,
          ignoreAddresses: wallets,
          m: data.kind === 'audit' ? check.m : check.appeal_m,
          seeds: hindsightSeedMaster(secret, data.kind, sub.id, r.id, attempt),
          check,
          workDir: join(dir, 'work'),
          concurrency: deps.concurrency ?? 1,
          label: `hindsight-${sub.id.slice(0, 8)}`,
          imageDigest: r.imageDigest,
          ...entrySecrets,
        });
      } catch (err) {
        // Given up: whatever the stopped audit threw is the stop's doing, so the signal's reason (retried, never permanent).
        if (signal?.aborted === true) throw signal.reason;
        // Whatever else it threw says none of the secrets it ran with (the header's `entry secrets`): a dead job's page quotes it.
        redactThrown(err, secretForms);
        if (err instanceof AuditError) throw new PermanentJobError(`the hindsight ${data.kind} of submission ${sub.id}: ${err.message} (${err.code})`, { cause: err });
        throw err;
      } finally {
        await removeMaterialized(botDir).catch(() => undefined);
        await removeScratch(sandbox, dir, removed);
      }
      // An attempt given up records nothing, however far its audit got (a killed replay reads as a failed copy): its
      // retry audits again, and records once.
      signal?.throwIfAborted();
      const verified = checkAuditRecord(record, check);
      if (!verified.ok) throw new PermanentJobError(`the hindsight ${data.kind} of submission ${sub.id} made a record that does not check: ${verified.problems.join('; ')}`);
      const kept = await hs.recordHindsightAudit(db, blobs, { comp, phaseId: ph.id, submissionId: sub.id, runId: r.id, kind: data.kind, attempt, record, at: now(), check });
      log(
        `[hindsight] ${ctx.id}: ${comp.slug} submission ${sub.id} ${data.kind} on ${record.m} + ${record.m} copies: ${record.verdict.flagged ? `flagged (${record.verdict.reasons.length} reasons)` : 'not flagged'}; record ${kept.record_sha256}${kept.check === null ? '' : `, hindsight_clean ${kept.check.status}`}`,
      );
      return { kind: 'recorded', submission_id: sub.id, audit: data.kind, record_sha256: kept.record_sha256, flagged: record.verdict.flagged, check: kept.check?.status ?? null, already: kept.already };
    } finally {
      await releaseScratch(sandbox, removed);
    }
  };

  /**
   * Page `d` unless it was paged before (the header's `dead`): its HINDSIGHT_AUDIT_DEAD_ACTION row,
   * written under the submission row's lock unless one names the job already, then the line. True
   * when this call paged it. A row that cannot be written is logged with its stack, and the page
   * stands (a later sweep may page the job again).
   */
  const pageDead = async (d: DeadEntryJob): Promise<boolean> => {
    const at = now();
    const line = deadJobPage(d, at);
    let fresh = true;
    try {
      fresh = await db.transaction(async (tx) => {
        await tx.select({ id: submission.id }).from(submission).where(eq(submission.id, d.submissionId)).for('update');
        const [seen] = await tx
          .select({ id: auditEvent.id })
          .from(auditEvent)
          .where(and(eq(auditEvent.action, HINDSIGHT_AUDIT_DEAD_ACTION), eq(auditEvent.subjectType, 'submission'), eq(auditEvent.subjectId, d.submissionId), sql`${auditEvent.data}->>'job_id' = ${d.jobId}`))
          .limit(1);
        if (seen !== undefined) return false;
        await recordAudit(tx, {
          actorUserId: null,
          action: HINDSIGHT_AUDIT_DEAD_ACTION,
          subjectType: 'submission',
          subjectId: d.submissionId,
          at,
          data: {
            competition: d.comp.slug,
            competition_id: d.comp.id,
            phase_id: d.final.id,
            run_id: d.runId,
            kind: d.kind,
            attempt: d.attempt,
            rank: d.rank,
            job_id: d.jobId,
            how: d.how,
            error: d.error,
            found: d.found,
            ends_at: d.final.endsAt?.toISOString() ?? null,
            page: line,
          },
        });
        return true;
      });
    } catch (err) {
      console.error(`[hindsight] the ${HINDSIGHT_AUDIT_DEAD_ACTION} row of job ${d.jobId} (submission ${d.submissionId}) could not be written; the page below stands, and a later sweep may page it again:`, err);
    }
    if (!fresh) return false;
    page(line);
    return true;
  };

  /**
   * An entry job dying for good with `err` (the header's `dead`): paged when its entry holds
   * finalize up on it, an unchecked audit target on that run with no newer audit job held (an
   * audit) or an appeal waiting for that re-run (an appeal); otherwise logged, with why not.
   */
  const dying = async (data: { submission_id: string; run_id: string; kind: HindsightAuditKind }, ctx: HindsightJobContext, err: unknown): Promise<void> => {
    // isLastAttempt knows both; a PermanentJobError may come with neither.
    const n = ctx.retryCount === undefined ? null : `${ctx.retryCount + 1}${ctx.retryLimit === undefined ? '' : ` of ${ctx.retryLimit + 1}`}`;
    const how = err instanceof PermanentJobError ? `was refused for good${n === null ? '' : ` on attempt ${n}`} (no retry can help)` : `failed its last attempt${n === null ? '' : ` (${n})`}`;
    const error = err instanceof Error ? err.message : String(err);
    const notPaged = (why: string): void => log(`[hindsight] ${ctx.id}: the ${data.kind} job of submission ${data.submission_id} (run ${data.run_id}) ${how}: ${error}; not paged: ${why}`);
    const hs = await rules();
    const [sub] = await db.select({ id: submission.id }).from(submission).where(eq(submission.id, data.submission_id));
    const [r] = sub === undefined ? [] : await db.select({ submissionId: run.submissionId, phaseId: run.phaseId }).from(run).where(eq(run.id, data.run_id));
    if (sub === undefined || r === undefined || r.submissionId !== sub.id) return notPaged(`no run ${data.run_id} of a submission ${data.submission_id} exists to decide`);
    const [ph] = await db.select().from(phase).where(eq(phase.id, r.phaseId));
    const [comp] = ph === undefined ? [] : await db.select().from(competition).where(eq(competition.id, ph.competitionId));
    const bundle = comp?.bundle == null ? null : CompetitionBundle.safeParse(comp.bundle);
    if (ph === undefined || comp === undefined || bundle === null || !bundle.success || bundle.data.harness.kind !== 'pumpfun-replay/v2' || (await hs.drawnFinal(db, comp, ph)) === null) {
      return notPaged(`run ${data.run_id} is on no drawn sealed window's final phase, which is all finalize waits on`);
    }
    const t = await hs.hindsightTargets(db, comp, bundle.data, ph, check, deps.cluster);
    if (t.awaiting.length > 0) return notPaged(`${comp.slug}'s final phase is grading again; the sweep sent once it settles pages the entry if its latest audit job is still dead`);
    const dead = { comp, final: ph, submissionId: sub.id, runId: data.run_id, kind: data.kind, jobId: ctx.id, how, error, found: 'handler' as const };
    if (data.kind === 'audit') {
      const target = t.unchecked.find((x) => x.submission_id === sub.id && x.run_id === data.run_id);
      if (target === undefined) return notPaged(`the entry is no audit target lacking hindsight_clean on run ${data.run_id}, so finalize does not wait on it`);
      const latest = await hs.latestAuditJobOf(db, sub.id, data.run_id);
      if (latest !== null && latest.id !== ctx.id) return notPaged(`a newer audit job of the run, ${latest.id}, is the one a verdict waits for (paged in turn should it die)`);
      await pageDead({ ...dead, rank: target.rank, attempt: null });
      return;
    }
    const waiting = t.appeals.find((a) => a.submission_id === sub.id && a.run_id === data.run_id);
    if (waiting === undefined) return notPaged('no appeal of the entry waits for this re-run');
    const latest = await hs.latestAuditJobOf(db, sub.id, data.run_id, 'appeal');
    if (latest !== null && latest.id !== ctx.id) return notPaged(`a newer re-run job of the appeal, ${latest.id}, is the one a verdict past the end waits for (paged in turn should it die)`);
    await pageDead({ ...dead, rank: null, attempt: waiting.attempt });
  };

  return async (data, ctx) => {
    if ('phase_id' in data) return sweep(data.phase_id, ctx);
    try {
      return await auditOne(data, ctx);
    } catch (err) {
      // Dying for good (pg-boss retries it no more): paged, then the job's own error stands.
      if (err instanceof PermanentJobError || isLastAttempt(ctx)) {
        await dying(data, ctx, err).catch((e: unknown) => {
          log(`[hindsight] ${ctx.id}: submission ${data.submission_id}'s ${data.kind} job died for good, and paging it failed: ${e instanceof Error ? e.message : String(e)}`);
          console.error(`[hindsight] ${ctx.id}: submission ${data.submission_id}'s ${data.kind} job died for good, and paging it failed; the next sweep pages a dead audit job:`, e);
        });
      }
      throw err;
    }
  };
}

type DatasetRow = typeof dataset.$inferSelect;

// ---------------------------------------------------------------- a dead grade job

/**
 * A grade job that died for good (the header's `dead grade job`; the system's, subject the
 * submission): one row per job and attempt it died on, written before its page goes out, or with
 * why it is not paged (its entry is out). The competition, the phase, the queue, the job's kind and
 * the run a regrade reproduces, the job, its attempt, how it died and its last error, who found it,
 * whether it was paged (why_not when not) and the page text.
 */
export const GRADE_JOB_DEAD_ACTION = 'grade.job_dead' satisfies AuditAction;

/** pg-boss's job table: server/jobs.ts JobQueue runs pg-boss in the server's own database under its default schema, as server/routes/admin/hindsight.ts reads it. */
const JOB_TABLE = 'pgboss.job';

/** A pg-boss job id's shape: a uuid (the job table's id column). */
const UUID_SHAPE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** The grade queues (server/jobs.ts gradeQueue). */
const GRADE_QUEUES = ['grade-dev', 'grade-final'] as const satisfies readonly QueueName[];

/** The dead grade jobs one sweep decides at most, the oldest death first; the rest wait for the next sweep. */
export const DEAD_GRADE_SWEEP_LIMIT = 100;

/**
 * A grade job's context as its handler reads it (JobQueue.work's): its id and queue, its attempt, its retry limit (a
 * job dies for good on its last: isLastAttempt; without one no attempt is the last), and the attempt's signal, which
 * ends a wait on a scrape heat and stops a practice heat once pg-boss gives the attempt up (the header's `scrape/v1`),
 * and its place in the sandbox pool to give back early (releasePlace: a judged dev grade's, before its provisional judge heat).
 */
export type GradeJobContext = Pick<JobContext, 'id' | 'queue' | 'retryCount'> & Partial<Pick<JobContext, 'retryLimit' | 'signal' | 'priority' | 'releasePlace'>>;

/** A grade job that died for good, as its row and page name it. */
export interface DeadGradeJob {
  job: JobPayload<'grade-dev'>;
  jobId: string;
  queue: string;
  /** The attempt it died on, from 1 (pg-boss's retry_count + 1). */
  attempt: number;
  /** Its attempts in all (pg-boss's retry_limit + 1), or null when not known. */
  attempts: number | null;
  /** How it died, in its row's words ("was refused for good on attempt 1 of 3 ...", "failed its last attempt (3 of 3)", "is held failed by pg-boss since ..."), as a held page names it. */
  how: string;
  /** How it died, as one plain sentence of its page ("It failed its last attempt, 3 of 3."). */
  plain: string;
  /** Its last error, or null when pg-boss holds none. */
  error: string | null;
  /** Who found it dead: the job's own handler, or a sweep. */
  found: 'handler' | 'sweep';
}

/**
 * What one sweep decided: the deaths it paged, those it recorded without a page (an entry that is out), and those it sent
 * again by itself (a grader's cut: the header's `dead grade job`). Deaths a row records already are none of them.
 */
export interface DeadGradeSweep {
  paged: { submission_id: string; job_id: string; attempt: number }[];
  quiet: { submission_id: string; job_id: string; attempt: number; why: string }[];
  resent: { submission_id: string; job_id: string; attempt: number; why: string }[];
  /** The scrape heats it decided (the header's `dead grade job`): cut dead and sent again, or paged with why not. */
  heats: { phase_id: string; job_id: string; attempt: number; outcome: 'paged' | 'resent'; why: string | null }[];
}

/** node-postgres returns a QueryResult, PGlite a Results object: both carry `rows`. */
function rowsOf<T>(result: unknown): T[] {
  return ((result as { rows?: T[] }).rows ?? []) as T[];
}

/** The error a failed pg-boss job holds in its output: a PermanentJobError's `error`, a thrown error's `message`, a stop's `value` (server/jobs.ts SHUTDOWN_CUT_ERROR), an expiry's `value.message`; else null. */
function jobErrorOf(output: unknown): string | null {
  const o = output as { error?: unknown; message?: unknown; value?: unknown } | null;
  if (typeof o?.error === 'string') return o.error;
  if (typeof o?.message === 'string') return o.message;
  if (typeof o?.value === 'string') return o.value;
  const value = o?.value as { message?: unknown } | null | undefined;
  return typeof value?.message === 'string' ? value.message : null;
}

/** A page's free text as a sentence: its own closing stop kept, else one added. */
function sentenceOf(text: string): string {
  return /[.!?]$/.test(text) ? text : `${text}.`;
}

/**
 * The page of dead grade job `d` on `slug`'s `phaseKey` phase, in plain words: what failed for good and
 * what it leaves undone, how it died and its last error, the admin route that queues it again (a
 * grade's server/routes/admin/grading.ts registerGradeResend, a regrade's the regrade route), and
 * the ids last.
 */
function deadGradeJobPage(d: DeadGradeJob, slug: string, phaseKey: string, unsent: string | null = null): string {
  if (isEntrySecretsHold(d.error)) return heldGradeJobPage(d, slug, phaseKey);
  const died = `${d.plain}${d.error === null ? '' : ` Reason: ${sentenceOf(d.error)}`}${unsent === null ? '' : ` ${unsent}`}`;
  const ids = `entry ${d.job.submission_id}, phase ${d.job.phase_id}, job ${d.jobId} in ${d.queue}.`;
  if (d.job.rejudge !== undefined) {
    return (
      `[grade] ALERT: ${slug}'s provisional rejudge of a ${phaseKey} run failed for good, so the run keeps its provisional verdict and nothing retries the job. ${died} ` +
      `While ${slug} takes entries, the provisional rejudge sweep sends the run again on the next UTC day under a new job, or rejudge its provisional heats yourself on a later UTC day with POST /api/admin/competitions/${slug}/rejudge-provisional {}. ` +
      `Run ${d.job.reproduces_run_id}, ${ids}`
    );
  }
  if (d.job.kind === 'grade') {
    return (
      `[grade] ALERT: ${slug}'s ${phaseKey} grading of an entry failed for good, so that entry has no ${phaseKey} score and nothing retries it. ${died} ` +
      `Once the cause is fixed, grade it afresh with POST /api/admin/submissions/${d.job.submission_id}/grade/resend {"job_id": "${d.jobId}", "reason": "<what was fixed>"}. ` +
      `Entry ${d.job.submission_id}, phase ${d.job.phase_id}, job ${d.jobId} in ${d.queue}.`
    );
  }
  const reproduces = d.job.reproduces_run_id;
  const level = d.job.kind === 'regrade_l1' ? 'L1' : 'L2';
  return (
    `[grade] ALERT: ${slug}'s ${level} regrade of a ${phaseKey} run failed for good, so that run is not reproduced and nothing retries it. ${died} ` +
    `Once the cause is fixed, queue it again with POST /api/admin/runs/${reproduces}/regrade {"level": "${level}"}. ` +
    `Run ${reproduces}, ${ids}`
  );
}

/** Where the seal private keys a grader opens entry secrets with are mounted (server/secrets/seal.ts entrySecretSealRefusal's words), as a held page's fix names them. */
const SEAL_PRIVATE_KEYS_MOUNT = 'MAKEFUN_ENTRY_SECRET_SEAL_PRIVATE_KEYS_FILE; on the cluster, Secret makefun-entry-secret-seal, holding every key a secret is still sealed to';

/**
 * The page of grade job `d`, dead while held on its entrant's entry secrets (its error opening
 * ENTRY_SECRETS_UNOPENED_HOLD_REASON: the header's `entry secrets`), on `slug`'s `phaseKey` phase: the hold and its
 * secrets as the error names them (by NAME and row, and why: never a value), that nothing failed the entry, and the fix
 * (the seal private keys that open them, then the resend or the regrade). Sent once, on its last attempt.
 */
function heldGradeJobPage(d: DeadGradeJob, slug: string, phaseKey: string): string {
  const held = `is held on its entrant's entry secrets: job ${d.jobId} (${d.queue}) ${d.how}${d.error === null ? '' : `: ${d.error}`}`;
  const fault = "the fault is the platform's key configuration, never the entrant's";
  const keys = `give the grading workers the seal private keys that open the entry secrets named above (${SEAL_PRIVATE_KEYS_MOUNT}) and restart them, since a process reads its keys as it starts`;
  if (d.job.kind === 'grade') {
    return (
      `[grade] ALERT: ${slug}: the grading of entry ${d.job.submission_id} on the ${phaseKey} phase (phase ${d.job.phase_id}) ${held}. ` +
      `It recorded no run and never failed the entry, which waits ungraded on the ${phaseKey} phase, never graded without its secrets; ${fault}, and pg-boss will not run it again on its own. ` +
      `Fix: ${keys}, then send it again at POST /api/admin/submissions/${d.job.submission_id}/grade/resend ({"job_id": "${d.jobId}", "reason": "<what was mended>"}), which grades the entry afresh under a new job id`
    );
  }
  const reproduces = d.job.reproduces_run_id;
  const level = d.job.kind === 'regrade_l1' ? 'L1' : 'L2';
  return (
    `[grade] ALERT: ${slug}: the ${level} regrade of run ${reproduces} (entry ${d.job.submission_id}, the ${phaseKey} phase, phase ${d.job.phase_id}) ${held}. ` +
    `It recorded no regrade run: run ${reproduces} is not re-executed without its secrets, and its standing is untouched; ${fault}, and pg-boss will not run it again on its own. ` +
    `Fix: ${keys}, then queue the regrade again at POST /api/admin/runs/${reproduces}/regrade ({"level": "${level}"})`
  );
}

/** A grade job's attempt as a page or a log line names it: "2", or "2 of 3" when its retry limit is known. */
function attemptWords(ctx: GradeJobContext): string {
  return `${ctx.retryCount + 1}${ctx.retryLimit === undefined ? '' : ` of ${ctx.retryLimit + 1}`}`;
}

/**
 * The admins' page of grade jobs that die for good (the header's `dead grade job`): `dying` as a
 * job's own handler sees it die, `sweep` over every grade job pg-boss holds failed that no
 * GRADE_JOB_DEAD_ACTION row records (none when the database has no pg-boss table). Given `jobs`, a
 * grade cut by its grader's stop or kill is sent again instead of paged (server/routes/admin/grading.ts
 * `automatic resend`), a grade-final one refused while final grading is (`failKeySecret`, finalGradingRefusal),
 * and the sweep sends a scrape heat so cut again too (recordHeat).
 */
export function createDeadGradeJobPager(deps: Pick<GradeWorkerDeps, 'db' | 'page' | 'log' | 'now' | 'jobs' | 'failKeySecret'>): {
  dying(job: JobPayload<'grade-dev'>, ctx: GradeJobContext, err: unknown): Promise<void>;
  sweep(): Promise<DeadGradeSweep>;
} {
  const { db } = deps;
  const page = deps.page ?? ((line: string) => console.error(line));
  const log = deps.log ?? ((line: string) => console.log(line));
  const now = deps.now ?? (() => new Date());

  /**
   * Decide `d` once (its job and attempt): its row, written under the submission row's lock unless
   * one records that death already, then the page, unless its entry is out. A row that cannot be
   * written is logged with its stack, and the page stands (a later sweep may page it again).
   */
  const record = async (d: DeadGradeJob): Promise<{ outcome: 'paged' | 'quiet' | 'resent' | 'seen'; why: string | null }> => {
    const at = now();
    const subId = d.job.submission_id;
    const [sub] = await db.select({ status: submission.status, error: submission.error, checks: submission.checks, competitionId: submission.competitionId }).from(submission).where(eq(submission.id, subId));
    const [ph] = await db.select({ key: phase.key, competitionId: phase.competitionId }).from(phase).where(eq(phase.id, d.job.phase_id));
    const compId = ph?.competitionId ?? sub?.competitionId ?? null;
    const [comp] = compId === null ? [] : await db.select({ id: competition.id, slug: competition.slug }).from(competition).where(eq(competition.id, compId));
    const phaseKey = ph?.key ?? (d.queue === 'grade-dev' ? 'dev' : 'final');
    // An entry that is out was never to be graded: its death is recorded, not paged. (The pipeline's rules are loaded only here.)
    let why: string | null = null;
    if (sub?.status === 'cancelled') why = 'the entry was cancelled';
    else if (sub !== undefined) {
      // A refusal that stands (server/pipeline/publish.ts isRefused): a duplicate snapshot, a committed secret, or an admin's security-audit refusal.
      const refusal = await import('../server/pipeline/publish.ts');
      if (refusal.isRefusedDuplicate(sub)) why = 'the entry was refused as a duplicate snapshot';
      else if (refusal.isRefused(sub)) why = 'the entry was refused for a secret committed in its code';
    }
    // A grade its grader's stop or kill cut is sent again before its row is written, so a row records it decided (what
    // payouts/onchain.ts awaitingGrade waits on); a send that fails throws, leaving it to the next sweep.
    let resent: { why: string; as: string | null } | null = null;
    let unsent: string | null = null;
    if (why === null && deps.jobs !== undefined && d.job.kind === 'grade' && d.job.rejudge === undefined && UUID_SHAPE.test(d.jobId)) {
      const admin = await import('../server/routes/admin/grading.ts');
      const finalRefusal = admin.finalGradingRefusal({ nodeEnv: process.env.NODE_ENV as 'development' | 'test' | 'production', betterAuthSecret: deps.failKeySecret ?? null });
      const out = await admin.resendCutGradeJob(db, deps.jobs, { submissionId: subId, deadJobId: d.jobId, finalRefusal, now });
      if (out.kind === 'sent') resent = { why: `its grader's stop or kill cut it, so it was sent again by itself as job ${out.res.job_id} (automatic resend ${out.automatic} of ${admin.AUTO_GRADE_RESEND_CAP})`, as: out.res.job_id };
      else if (out.why === 'already') resent = { why: `its grader's stop or kill cut it, and it was sent again already: ${out.message}`, as: null };
      else if (out.why !== 'not_cut') unsent = `Its grader's stop or kill cut it, and it was not sent again by itself: ${sentenceOf(out.message)}`;
    }
    const quiet = why ?? resent?.why ?? null;
    const line = quiet === null ? deadGradeJobPage(d, comp?.slug ?? `competition ${compId ?? 'unknown'}`, phaseKey, unsent) : null;
    let fresh = true;
    try {
      fresh = await db.transaction(async (tx) => {
        await tx.select({ id: submission.id }).from(submission).where(eq(submission.id, subId)).for('update');
        const [seen] = await tx
          .select({ id: auditEvent.id })
          .from(auditEvent)
          .where(
            and(
              eq(auditEvent.action, GRADE_JOB_DEAD_ACTION),
              eq(auditEvent.subjectType, 'submission'),
              eq(auditEvent.subjectId, subId),
              sql`${auditEvent.data}->>'job_id' = ${d.jobId}`,
              sql`${auditEvent.data}->>'attempt' = ${String(d.attempt)}`,
            ),
          )
          .limit(1);
        if (seen !== undefined) return false;
        await recordAudit(tx, {
          actorUserId: null,
          action: GRADE_JOB_DEAD_ACTION,
          subjectType: 'submission',
          subjectId: subId,
          at,
          data: {
            competition: comp?.slug ?? null,
            competition_id: compId,
            phase_id: d.job.phase_id,
            phase: ph?.key ?? null,
            queue: d.queue,
            kind: d.job.kind,
            reproduces_run_id: d.job.reproduces_run_id,
            job_id: d.jobId,
            attempt: d.attempt,
            attempts: d.attempts,
            how: d.how,
            error: d.error,
            found: d.found,
            paged: line !== null,
            why_not: quiet,
            page: line,
            ...(resent === null || resent.as === null ? {} : { resent_as: resent.as }),
          },
        });
        return true;
      });
    } catch (err) {
      console.error(`[grade] the ${GRADE_JOB_DEAD_ACTION} row of job ${d.jobId} (submission ${subId}, attempt ${d.attempt}) could not be written; ${line === null ? 'it is not paged' : 'the page below stands'}, and a later sweep may decide it again:`, err);
    }
    if (!fresh) return { outcome: 'seen', why: quiet };
    if (line === null) {
      log(`[grade] job ${d.jobId} (${d.queue}) of submission ${subId} died for good on attempt ${d.attempt}${d.error === null ? '' : `: ${d.error}`}; not paged: ${quiet}`);
      return { outcome: why === null ? 'resent' : 'quiet', why: quiet };
    }
    page(line);
    return { outcome: 'paged', why: null };
  };

  /**
   * Whether the attempt ended because its job was cancelled while it ran (a superseded entry's grade: pg-boss aborts its
   * signal once its row is cancelled, server/pipeline/ingest.ts cancel), read as server/jobs.ts JobQueue reads it for the
   * job's outcome: its signal aborted and its pg-boss row `cancelled`. A row that cannot be read is logged and counts as
   * no cancel, so the death is paged.
   */
  const cancelledWhileRunning = async (ctx: GradeJobContext): Promise<boolean> => {
    if (ctx.signal?.aborted !== true || !UUID_SHAPE.test(ctx.id)) return false;
    try {
      const [table] = rowsOf<{ present: boolean }>(await db.execute(sql`select to_regclass(${JOB_TABLE}) is not null as present`));
      if (table?.present !== true) return false;
      const [row] = rowsOf<{ state: string }>(await db.execute(sql`select state from ${sql.raw(JOB_TABLE)} where name = ${ctx.queue} and id = ${ctx.id}::uuid`));
      return row?.state === 'cancelled';
    } catch (e) {
      console.error(`[grade] job ${ctx.id} (${ctx.queue}) was aborted on its last attempt, and whether it was cancelled could not be read; it is paged as dead:`, e);
      return false;
    }
  };

  const dying = async (job: JobPayload<'grade-dev'>, ctx: GradeJobContext, err: unknown): Promise<void> => {
    if (await cancelledWhileRunning(ctx)) {
      log(`[grade] job ${ctx.id} (${ctx.queue}) of submission ${job.submission_id} was cancelled while it ran, on attempt ${attemptWords(ctx)}: no death, so neither recorded nor paged`);
      return;
    }
    const n = attemptWords(ctx);
    const how = isEntrySecretsHold(err)
      ? `spent its last attempt (${n}) held, never failed`
      : err instanceof PermanentJobError
        ? `was refused for good on attempt ${n} (no retry can help)`
        : `failed its last attempt (${n})`;
    const plain = err instanceof PermanentJobError ? `It was refused on attempt ${n}, and no retry can help.` : `It failed its last attempt, ${n}.`;
    const error = err instanceof Error ? err.message : String(err);
    await record({ job, jobId: ctx.id, queue: ctx.queue, attempt: ctx.retryCount + 1, attempts: ctx.retryLimit === undefined ? null : ctx.retryLimit + 1, how, plain, error, found: 'handler' });
  };

  /**
   * Decide scrape-heat job `h`, its last attempt cut by its grader's stop or kill, once per job and attempt: sent again by
   * itself, else paged in the heat's dead-job words with why not; its row (subject the phase) is written under the phase
   * row's lock unless one records that death already. A send that fails throws, leaving it to the next sweep.
   */
  const recordHeat = async (
    jobs: Pick<JobQueue, 'send'>,
    h: { phaseId: string; jobId: string; attempt: number; attempts: number; how: string; error: string | null },
  ): Promise<{ outcome: 'paged' | 'resent' | 'seen'; why: string | null }> => {
    const at = now();
    const admin = await import('../server/routes/admin/grading.ts');
    const out = await admin.resendCutHeatJob(db, jobs, { phaseId: h.phaseId, deadJobId: h.jobId, now });
    let resent: { why: string; as: string | null } | null = null;
    let line: string | null = null;
    if (out.kind === 'sent') resent = { why: `its grader's stop or kill cut it, so it was sent again by itself as job ${out.res.job_id} (automatic resend ${out.automatic} of ${admin.AUTO_GRADE_RESEND_CAP})`, as: out.res.job_id };
    else if (out.why === 'already') resent = { why: `its grader's stop or kill cut it, and it was sent again already: ${out.message}`, as: null };
    else {
      const { scrapeHeatDeadPage } = await import('../server/pipeline/index.ts');
      const unsent = `Its grader's stop or kill cut it, and it was not sent again by itself: ${out.message.replace(/[.!?]$/, '')}`;
      line = scrapeHeatDeadPage(h.phaseId, { id: h.jobId, retryCount: h.attempt - 1, retryLimit: h.attempts - 1 }, new Error(`${h.error ?? 'no error recorded'}. ${unsent}`));
    }
    const [where] = await db.select({ key: phase.key, competitionId: competition.id, slug: competition.slug }).from(phase).innerJoin(competition, eq(competition.id, phase.competitionId)).where(eq(phase.id, h.phaseId));
    let fresh = true;
    try {
      fresh = await db.transaction(async (tx) => {
        await tx.select({ id: phase.id }).from(phase).where(eq(phase.id, h.phaseId)).for('update');
        const [seen] = await tx
          .select({ id: auditEvent.id })
          .from(auditEvent)
          .where(
            and(
              eq(auditEvent.action, GRADE_JOB_DEAD_ACTION),
              eq(auditEvent.subjectType, 'phase'),
              eq(auditEvent.subjectId, h.phaseId),
              sql`${auditEvent.data}->>'job_id' = ${h.jobId}`,
              sql`${auditEvent.data}->>'attempt' = ${String(h.attempt)}`,
            ),
          )
          .limit(1);
        if (seen !== undefined) return false;
        await recordAudit(tx, {
          actorUserId: null,
          action: GRADE_JOB_DEAD_ACTION,
          subjectType: 'phase',
          subjectId: h.phaseId,
          at,
          data: {
            competition: where?.slug ?? null,
            competition_id: where?.competitionId ?? null,
            phase_id: h.phaseId,
            phase: where?.key ?? null,
            queue: 'scrape-heat',
            kind: 'heat',
            job_id: h.jobId,
            attempt: h.attempt,
            attempts: h.attempts,
            how: h.how,
            error: h.error,
            found: 'sweep',
            paged: line !== null,
            why_not: resent?.why ?? null,
            page: line,
            ...(resent === null || resent.as === null ? {} : { resent_as: resent.as }),
          },
        });
        return true;
      });
    } catch (err) {
      console.error(`[scrape] the ${GRADE_JOB_DEAD_ACTION} row of heat job ${h.jobId} (phase ${h.phaseId}, attempt ${h.attempt}) could not be written; ${line === null ? 'it is not paged' : 'the page below stands'}, and a later sweep may decide it again:`, err);
    }
    if (!fresh) return { outcome: 'seen', why: resent?.why ?? null };
    if (line === null) {
      log(`[scrape] heat job ${h.jobId} of phase ${h.phaseId} died for good on attempt ${h.attempt}${h.error === null ? '' : `: ${h.error}`}; not paged: ${resent!.why}`);
      return { outcome: 'resent', why: resent!.why };
    }
    page(line);
    return { outcome: 'paged', why: null };
  };

  /** Every scrape heat pg-boss holds failed by its grader's stop or kill whose death no row decides yet, given a queue to send it on. */
  const sweepHeats = async (out: DeadGradeSweep): Promise<void> => {
    const jobs = deps.jobs;
    if (jobs === undefined) return;
    const rows = rowsOf<{ id: string; retry_count: number; retry_limit: number; data: unknown; created_on: Date | string; completed_on: Date | string | null; output: unknown }>(
      await db.execute(
        sql`select j.id::text as id, j.retry_count, j.retry_limit, j.data, j.created_on, j.completed_on, j.output from ${sql.raw(JOB_TABLE)} j
          where j.name = ${'scrape-heat'} and j.state = 'failed' and j.data->'rejudge' is null
            and (j.output->>'value' = ${SHUTDOWN_CUT_ERROR} or j.output->'value'->>'message' = ${HEARTBEAT_LAPSE_ERROR})
            and not exists (select 1 from ${auditEvent} e where e.action = ${GRADE_JOB_DEAD_ACTION} and e.subject_type = 'phase' and e.subject_id = j.data->>'phase_id'
              and e.data->>'job_id' = j.id::text and e.data->>'attempt' = (j.retry_count + 1)::text)
          order by j.completed_on asc nulls first, j.created_on asc, j.id asc
          limit ${DEAD_GRADE_SWEEP_LIMIT}`,
      ),
    );
    for (const r of rows) {
      // Without a hand-back's retries_spent (splitRetriesSpent), which the strict schema refuses, as JobQueue.work reads it.
      const parsed = ServerScrapeHeatJob.safeParse(splitRetriesSpent(r.data).data);
      if (!parsed.success) continue;
      const attempt = Number(r.retry_count) + 1;
      const attempts = Number(r.retry_limit) + 1;
      const since = new Date(r.completed_on ?? r.created_on).toISOString();
      try {
        const { outcome, why } = await recordHeat(jobs, {
          phaseId: parsed.data.phase_id,
          jobId: r.id,
          attempt,
          attempts,
          how: `is held failed by pg-boss since ${since}, after attempt ${attempt} of ${attempts}, cut by its grader's stop or kill`,
          error: jobErrorOf(r.output),
        });
        if (outcome !== 'seen') out.heats.push({ phase_id: parsed.data.phase_id, job_id: r.id, attempt, outcome, why });
      } catch (err) {
        console.error(`[scrape] dead heat job ${r.id} could not be decided; the next sweep looks again:`, err);
      }
    }
  };

  const sweep = async (): Promise<DeadGradeSweep> => {
    const out: DeadGradeSweep = { paged: [], quiet: [], resent: [], heats: [] };
    const [table] = rowsOf<{ present: boolean }>(await db.execute(sql`select to_regclass(${JOB_TABLE}) is not null as present`));
    if (table?.present !== true) return out;
    const queues = sql.join(
      GRADE_QUEUES.map((q) => sql`${q}`),
      sql`, `,
    );
    // Every grade job pg-boss holds failed (its retries spent, or refused for good) whose death no row records yet.
    const rows = rowsOf<{ id: string; name: string; retry_count: number; retry_limit: number; data: unknown; created_on: Date | string; completed_on: Date | string | null; output: unknown }>(
      await db.execute(
        sql`select j.id::text as id, j.name, j.retry_count, j.retry_limit, j.data, j.created_on, j.completed_on, j.output from ${sql.raw(JOB_TABLE)} j
          where j.name in (${queues}) and j.state = 'failed'
            and not exists (select 1 from ${auditEvent} e where e.action = ${GRADE_JOB_DEAD_ACTION} and e.subject_type = 'submission' and e.subject_id = j.data->>'submission_id'
              and e.data->>'job_id' = j.id::text and e.data->>'attempt' = (j.retry_count + 1)::text)
          order by j.completed_on asc nulls first, j.created_on asc, j.id asc
          limit ${DEAD_GRADE_SWEEP_LIMIT}`,
      ),
    );
    for (const r of rows) {
      // Without a hand-back's retries_spent (splitRetriesSpent), which the strict schema refuses, as JobQueue.work reads it.
      const parsed = GradeJob.safeParse(splitRetriesSpent(r.data).data);
      // A payload that is no grade job's (only a raw send makes one) names no entry to page.
      if (!parsed.success) continue;
      const attempt = Number(r.retry_count) + 1;
      const attempts = Number(r.retry_limit) + 1;
      const since = new Date(r.completed_on ?? r.created_on).toISOString();
      const d: DeadGradeJob = {
        job: parsed.data,
        jobId: r.id,
        queue: r.name,
        attempt,
        attempts,
        how: `is held failed by pg-boss since ${since}, after attempt ${attempt} of ${attempts} (its retries spent, refused for good, expired, or failed by hand)`,
        plain: `The job queue has held it failed since ${since}, after attempt ${attempt} of ${attempts}.`,
        error: jobErrorOf(r.output),
        found: 'sweep',
      };
      try {
        const { outcome, why } = await record(d);
        if (outcome === 'paged') out.paged.push({ submission_id: d.job.submission_id, job_id: d.jobId, attempt });
        else if (outcome === 'quiet') out.quiet.push({ submission_id: d.job.submission_id, job_id: d.jobId, attempt, why: why! });
        else if (outcome === 'resent') out.resent.push({ submission_id: d.job.submission_id, job_id: d.jobId, attempt, why: why! });
      } catch (err) {
        console.error(`[grade] dead grade job ${r.id} (${r.name}) could not be decided; the next sweep looks again:`, err);
      }
    }
    await sweepHeats(out);
    return out;
  };

  return { dying, sweep };
}
